CREATE TEMP TABLE _gi_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _gi_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'gastrointestinal & hepatic system'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Gastrointestinal & Hepatic System"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'gastrointestinal & hepatic system'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _gi_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Gastrointestinal & Hepatic System subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Gastrointestinal & Hepatic System points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _gi_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'GI-Hepatic seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _gi_seed_map) <> 39 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 39 note mappings, found %.',
      (SELECT count(*) FROM _gi_seed_map);
  END IF;

  INSERT INTO _gi_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _gi_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('digestive', 1, 'A nurse is preparing to perform an abdominal assessment on a client admitted with abdominal discomfort. Which sequence should the nurse follow?', '[{"id": "a", "text": "Inspection, palpation, percussion, auscultation"}, {"id": "b", "text": "Inspection, auscultation, percussion, palpation"}, {"id": "c", "text": "Auscultation, inspection, palpation, percussion"}, {"id": "d", "text": "Palpation, percussion, auscultation, inspection"}]'::jsonb, '["b"]', 'The abdominal exam sequence is inspection, auscultation, percussion, then palpation. Palpating before auscultating is incorrect because palpation can cause pain and alter bowel sounds.'),
  ('digestive', 2, 'A nurse observes a nursing student assessing the abdomen of a client with nausea. Which action by the student requires correction?', '[{"id": "a", "text": "Inspecting the abdomen before using any other technique"}, {"id": "b", "text": "Auscultating bowel sounds before percussing the abdomen"}, {"id": "c", "text": "Palpating the abdomen before auscultating bowel sounds"}, {"id": "d", "text": "Percussing the abdomen before palpating it"}]'::jsonb, '["c"]', 'Palpation is performed last in the abdominal exam because it can cause pain and alter bowel sounds. Auscultating before percussion is the correct order and needs no correction.'),
  ('digestive', 3, 'During an abdominal assessment, a client asks why the nurse listens to the abdomen before pressing on it. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Pressing first could cause pain and alter your bowel sounds.\""}, {"id": "b", "text": "\"Listening first helps me find the size of your liver.\""}, {"id": "c", "text": "\"Pressing first is avoided only when your stools are dark.\""}, {"id": "d", "text": "\"Listening first lets me check your clotting factor levels.\""}]'::jsonb, '["a"]', 'Palpation is done last because it can cause pain and alter bowel sounds, so auscultation must come before it. Dark stools and clotting factors do not determine the order of the abdominal exam.'),
  ('digestive', 4, 'A client has had persistent vomiting for 3 days. The nurse should monitor the client for which acid-base imbalance?', '[{"id": "a", "text": "Metabolic acidosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Respiratory alkalosis"}]'::jsonb, '["b"]', 'Loss of stomach acid through vomiting can cause metabolic alkalosis. Metabolic acidosis reverses the direction, because losing HCl raises the pH.'),
  ('digestive', 5, 'A client has had a nasogastric (NG) tube connected to continuous suction for several days. Which arterial blood gas change does the nurse anticipate?', '[{"id": "a", "text": "Decreased pH from retained hydrochloric acid"}, {"id": "b", "text": "Decreased pH from excess stomach acid production"}, {"id": "c", "text": "Unchanged pH because stomach acid is replaced"}, {"id": "d", "text": "Increased pH from loss of hydrochloric acid"}]'::jsonb, '["d"]', 'NG tube suction removes stomach acid, which can cause metabolic alkalosis with an increased pH and decreased HCl. A decreased pH reflects the opposite direction of the expected change.'),
  ('digestive', 6, 'A client reports passing black, tarry stools for the past 2 days. The nurse recognizes this finding most likely indicates bleeding from which area?', '[{"id": "a", "text": "Upper GI tract"}, {"id": "b", "text": "Large intestine"}, {"id": "c", "text": "Rectum"}, {"id": "d", "text": "Anal sphincter"}]'::jsonb, '["a"]', 'Tarry stool indicates upper GI bleeding. The lower structures such as the rectum and large intestine are not the source associated with tarry stool.'),
  ('digestive', 7, 'A provider suspects gastrointestinal bleeding in a client who reports fatigue and dark stools. Which test does the nurse anticipate will be used to detect blood in the stool?', '[{"id": "a", "text": "Pancreatic panel"}, {"id": "b", "text": "Lipid panel"}, {"id": "c", "text": "Fecal analysis"}, {"id": "d", "text": "Liver panel"}]'::jsonb, '["c"]', 'Fecal analysis is used to detect blood in the stool. The pancreatic panel measures amylase and lipase for pancreatitis, not blood in stool.'),
  ('digestive', 8, 'A client with advanced liver disease has easy bruising and prolonged bleeding after a venipuncture. The nurse relates this finding to the liver''s role in which function?', '[{"id": "a", "text": "Storing bile that is released into the duodenum"}, {"id": "b", "text": "Producing bicarbonate to neutralize stomach acid"}, {"id": "c", "text": "Absorbing water and electrolytes to form stool"}, {"id": "d", "text": "Making clotting factors needed for coagulation"}]'::jsonb, '["d"]', 'The liver makes clotting factors, so liver dysfunction is assessed with PT/INR. Storing bile is a function of the gallbladder, and bicarbonate is produced by the pancreas.'),
  ('digestive', 9, 'A nurse is reviewing laboratory orders for a client with liver disease who is scheduled for a procedure. Which panel will show whether the client''s liver is producing adequate clotting factors?', '[{"id": "a", "text": "Metabolic panel"}, {"id": "b", "text": "Coagulation panel"}, {"id": "c", "text": "Lipid panel"}, {"id": "d", "text": "Pancreatic panel"}]'::jsonb, '["b"]', 'The coagulation panel assesses PT/INR, which reflects the clotting factors made by the liver. The metabolic panel measures electrolytes, glucose, BUN, and creatinine, not clotting.'),
  ('digestive', 10, 'A client is admitted with suspected pancreatitis. Which laboratory values should the nurse expect the provider to evaluate?', '[{"id": "a", "text": "AST and ALT"}, {"id": "b", "text": "PT and INR"}, {"id": "c", "text": "Amylase and lipase"}, {"id": "d", "text": "BUN and creatinine"}]'::jsonb, '["c"]', 'The pancreatic panel includes amylase and lipase to evaluate pancreatitis. AST and ALT belong to the liver panel.'),
  ('digestive', 11, 'A client is admitted for evaluation of liver function. Which laboratory values does the nurse expect to see in the client''s liver panel?', '[{"id": "a", "text": "Amylase and lipase"}, {"id": "b", "text": "Electrolytes and glucose"}, {"id": "c", "text": "PT and INR"}, {"id": "d", "text": "AST, ALT, and bilirubin"}]'::jsonb, '["d"]', 'The liver panel consists of AST, ALT, and bilirubin to assess liver function. PT and INR are part of the coagulation panel, not the liver panel.'),
  ('digestive', 12, 'After several episodes of vomiting, a client needs electrolyte levels checked. Which panel does the nurse anticipate the provider will order?', '[{"id": "a", "text": "Metabolic panel"}, {"id": "b", "text": "Lipid panel"}, {"id": "c", "text": "Liver panel"}, {"id": "d", "text": "Pancreatic panel"}]'::jsonb, '["a"]', 'The metabolic panel measures electrolytes, glucose, BUN, and creatinine. The liver panel measures AST, ALT, and bilirubin and does not report electrolytes.'),
  ('digestive', 13, 'A client asks why a cholesterol/lipid panel was included in a digestive workup. The nurse explains that this panel assesses which of the following?', '[{"id": "a", "text": "Pancreatic enzyme levels"}, {"id": "b", "text": "Fat metabolism"}, {"id": "c", "text": "Clotting factor production"}, {"id": "d", "text": "Blood in the stool"}]'::jsonb, '["b"]', 'The cholesterol/lipid panel is used to assess fat metabolism. Pancreatic enzyme levels are measured by the pancreatic panel instead.'),
  ('digestive', 14, 'A client reviewing lipid panel results asks the nurse which type of cholesterol is considered "good." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"LDL is the ''good'' type, and HDL has no effect.\""}, {"id": "b", "text": "\"Both LDL and HDL are considered ''bad'' types.\""}, {"id": "c", "text": "\"HDL is the ''good'' type, and LDL is the ''bad'' type.\""}, {"id": "d", "text": "\"HDL is the ''bad'' type, and LDL is the ''good'' type.\""}]'::jsonb, '["c"]', 'LDL is considered the "bad" cholesterol and HDL the "good" cholesterol. Reversing the two labels is a common misconception.'),
  ('digestive', 15, 'A client is scheduled for an endoscopy. Which statement by the client indicates understanding of the purpose of the procedure?', '[{"id": "a", "text": "\"It measures my amylase and lipase levels.\""}, {"id": "b", "text": "\"It checks my stool for any hidden blood.\""}, {"id": "c", "text": "\"It measures how well my blood can clot.\""}, {"id": "d", "text": "\"It lets the provider look inside my GI tract.\""}]'::jsonb, '["d"]', 'Endoscopy is used to visualize the GI tract directly. Checking stool for blood is the purpose of fecal analysis, not endoscopy.'),
  ('digestive', 16, 'A client is 1 day post abdominal surgery. The nurse auscultates all areas of the abdomen and hears no bowel sounds; the client has no other new findings. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is an expected finding this soon after surgery."}, {"id": "b", "text": "It is an emergency that requires immediate surgery."}, {"id": "c", "text": "It shows the client is ready for a regular diet."}, {"id": "d", "text": "It means palpation should be done before auscultation."}]'::jsonb, '["a"]', 'Bowel sounds may be absent for up to 2 days after surgery, which is normal. Treating this as an emergency at 1 day post-op misreads an expected finding.'),
  ('digestive', 17, 'An unlicensed assistive personnel (UAP) reports that a client who had bowel surgery yesterday has no audible bowel sounds. The client is otherwise stable. Which action should the nurse take?', '[{"id": "a", "text": "Keep the client on strict bed rest"}, {"id": "b", "text": "Palpate deeply before listening again"}, {"id": "c", "text": "Assist the client to ambulate in the hall"}, {"id": "d", "text": "Prepare the client for emergency surgery"}]'::jsonb, '["c"]', 'Absent bowel sounds for up to 2 days post-surgery are normal, and walking helps stimulate intestinal activity. Strict bed rest would not promote the return of intestinal activity.'),
  ('digestive', 18, 'A nurse teaches a postoperative client about the return of bowel function. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Walking in the hall will help my intestines start working.\""}, {"id": "b", "text": "\"I should stay in bed until my bowel sounds come back.\""}, {"id": "c", "text": "\"It can be normal to have no bowel sounds for up to 2 days.\""}, {"id": "d", "text": "\"The nurse listens to my abdomen before pressing on it.\""}]'::jsonb, '["b"]', 'Ambulation helps stimulate intestinal activity, so staying in bed is incorrect. Absent bowel sounds for up to 2 days after surgery can be normal, so that statement is accurate.'),
  ('digestive', 19, 'A client scheduled for a gallbladder evaluation asks what the gallbladder does. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It stores bile from the liver and releases it to digest fats.\""}, {"id": "b", "text": "\"It produces the bile that your body uses to break down fats.\""}, {"id": "c", "text": "\"It produces digestive enzymes and bicarbonate for digestion.\""}, {"id": "d", "text": "\"It absorbs water and electrolytes and forms your stool.\""}]'::jsonb, '["a"]', 'The gallbladder stores bile from the liver and releases it into the duodenum to digest fats. Bile is produced by the liver, not the gallbladder.'),
  ('digestive', 20, 'A client states, "I thought bile was made in the gallbladder." Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, the gallbladder makes bile and sends it to the liver.\""}, {"id": "b", "text": "\"Bile is made by the pancreas along with bicarbonate.\""}, {"id": "c", "text": "\"Bile is made by the liver and stored in the gallbladder.\""}, {"id": "d", "text": "\"Bile is made in the duodenum after you eat a meal.\""}]'::jsonb, '["c"]', 'The liver produces bile for fat digestion, and the gallbladder stores it. The pancreas produces digestive enzymes and bicarbonate, not bile.'),
  ('digestive', 21, 'A nurse is explaining fat digestion to a client. Into which structure does the gallbladder release bile?', '[{"id": "a", "text": "Stomach"}, {"id": "b", "text": "Duodenum"}, {"id": "c", "text": "Ileum"}, {"id": "d", "text": "Esophagus"}]'::jsonb, '["b"]', 'The gallbladder releases bile into the duodenum to digest fats. The stomach is not where bile is released.'),
  ('digestive', 22, 'A nursing student asks about the purpose of the bicarbonate produced by the pancreas. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It neutralizes stomach acid in the duodenum."}, {"id": "b", "text": "It activates enzymes within the stomach."}, {"id": "c", "text": "It stores bile for later fat digestion."}, {"id": "d", "text": "It forms and stores stool in the colon."}]'::jsonb, '["a"]', 'Pancreatic bicarbonate neutralizes stomach acid in the duodenum. Activating enzymes is a function of stomach acid (HCl), not bicarbonate.'),
  ('digestive', 23, 'A client with a pancreatic disorder asks where the pancreas is located. The nurse explains that the pancreas lies in which position?', '[{"id": "a", "text": "Inside the wall of the duodenum"}, {"id": "b", "text": "Behind the stomach"}, {"id": "c", "text": "Beneath the gallbladder"}, {"id": "d", "text": "Above the esophagus"}]'::jsonb, '["b"]', 'The pancreas is located behind the stomach. It is a separate accessory organ, not part of the duodenal wall.'),
  ('digestive', 24, 'A client with a pancreatic disorder asks what the pancreas normally produces for digestion. Which response by the nurse is accurate?', '[{"id": "a", "text": "Bile and clotting factors"}, {"id": "b", "text": "Hydrochloric acid and mucus"}, {"id": "c", "text": "Salivary amylase and mucus"}, {"id": "d", "text": "Digestive enzymes and bicarbonate"}]'::jsonb, '["d"]', 'The pancreas produces digestive enzymes and bicarbonate. Bile and clotting factors are made by the liver.'),
  ('digestive', 25, 'A client reports a burning sensation from stomach acid backing up into the esophagus. The nurse explains that which structure normally prevents this?', '[{"id": "a", "text": "Upper esophageal sphincter"}, {"id": "b", "text": "Pyloric sphincter"}, {"id": "c", "text": "Lower esophageal sphincter"}, {"id": "d", "text": "Ileocecal junction"}]'::jsonb, '["c"]', 'The lower esophageal sphincter prevents stomach acid reflux into the esophagus. The upper esophageal sphincter controls entry of food into the esophagus.'),
  ('digestive', 26, 'A nurse is explaining stomach emptying to a client. Which structure controls the passage of stomach contents into the small intestine?', '[{"id": "a", "text": "Pyloric sphincter"}, {"id": "b", "text": "Lower esophageal sphincter"}, {"id": "c", "text": "Upper esophageal sphincter"}, {"id": "d", "text": "Internal anal sphincter"}]'::jsonb, '["a"]', 'The pyloric sphincter controls passage from the stomach to the small intestine. The lower esophageal sphincter prevents acid reflux into the esophagus.'),
  ('digestive', 27, 'A nurse is teaching a client about swallowing. Which sequence correctly lists the structures food passes through after leaving the mouth?', '[{"id": "a", "text": "Esophagus, pharynx, stomach"}, {"id": "b", "text": "Pharynx, stomach, esophagus"}, {"id": "c", "text": "Stomach, pharynx, esophagus"}, {"id": "d", "text": "Pharynx, esophagus, stomach"}]'::jsonb, '["d"]', 'The pharynx connects the mouth to the esophagus, and the esophagus conducts the bolus to the stomach. Placing the esophagus before the pharynx reverses the pathway.'),
  ('digestive', 28, 'A nursing student is describing the path of a swallowed bolus. Which order of sphincters does the bolus pass through on its way to the small intestine?', '[{"id": "a", "text": "Lower esophageal, upper esophageal, pyloric"}, {"id": "b", "text": "Pyloric, upper esophageal, lower esophageal"}, {"id": "c", "text": "Upper esophageal, lower esophageal, pyloric"}, {"id": "d", "text": "Upper esophageal, pyloric, lower esophageal"}]'::jsonb, '["c"]', 'The bolus travels through the esophagus via the UES and then the LES into the stomach, and the pyloric sphincter controls passage from the stomach to the small intestine. Starting with the LES reverses the order of the esophageal sphincters.'),
  ('digestive', 29, 'A client chewing a cracker asks where digestion of food begins. The nurse explains that digestion of which nutrient begins in the mouth?', '[{"id": "a", "text": "Proteins"}, {"id": "b", "text": "Carbohydrates"}, {"id": "c", "text": "Fats"}, {"id": "d", "text": "Minerals"}]'::jsonb, '["b"]', 'Chewing plus salivary amylase in the mouth begins carbohydrate digestion. Fat digestion depends on bile, which is released into the duodenum.'),
  ('digestive', 30, 'A nurse is teaching a client about absorption in the stomach. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"My stomach can absorb alcohol and some medications.\""}, {"id": "b", "text": "\"My stomach absorbs most of the water that I drink.\""}, {"id": "c", "text": "\"My stomach is the main site of nutrient absorption.\""}, {"id": "d", "text": "\"My stomach sends fats directly into my lymph system.\""}]'::jsonb, '["a"]', 'The stomach absorbs alcohol and some medications, with minimal water absorption. The small intestine, not the stomach, is the main site of nutrient absorption.'),
  ('digestive', 31, 'A nursing student asks about the normal acidity of stomach contents. Which pH range does the nurse identify as normal for the stomach?', '[{"id": "a", "text": "5.5–6.5"}, {"id": "b", "text": "7.35–7.45"}, {"id": "c", "text": "1.5–3.5"}, {"id": "d", "text": "8.0–9.0"}]'::jsonb, '["c"]', 'Stomach acid (HCl) has a pH of 1.5–3.5. A neutral to slightly alkaline pH describes the duodenum, not the stomach.'),
  ('digestive', 32, 'A client asks how stomach acid helps the body. The nurse explains that hydrochloric acid in the stomach performs which function?', '[{"id": "a", "text": "Neutralizes bile in the duodenum"}, {"id": "b", "text": "Kills bacteria in ingested food"}, {"id": "c", "text": "Absorbs most dietary water"}, {"id": "d", "text": "Produces bicarbonate for digestion"}]'::jsonb, '["b"]', 'Stomach acid breaks down food, kills bacteria, and activates enzymes. Bicarbonate is produced by the pancreas, not by stomach acid.'),
  ('digestive', 33, 'A client asks the nurse why strong stomach acid does not damage the stomach itself. Which response is accurate?', '[{"id": "a", "text": "\"Bile from the gallbladder neutralizes acid inside the stomach.\""}, {"id": "b", "text": "\"Bicarbonate from the pancreas neutralizes acid inside the stomach.\""}, {"id": "c", "text": "\"The stomach absorbs the acid along with most of your water.\""}, {"id": "d", "text": "\"A mucus layer protects the stomach lining from the acid.\""}]'::jsonb, '["d"]', 'A mucus layer protects the stomach lining from acid. Pancreatic bicarbonate neutralizes stomach acid in the duodenum, not inside the stomach.'),
  ('digestive', 34, 'A client has a disorder that damages the small intestine. The nurse anticipates a risk for poor nutrition because the small intestine is which of the following?', '[{"id": "a", "text": "The main site where bile is produced"}, {"id": "b", "text": "The main site of nutrient absorption"}, {"id": "c", "text": "The main site where stool is formed"}, {"id": "d", "text": "The main site where alcohol is absorbed"}]'::jsonb, '["b"]', 'The small intestine is the main site of nutrient absorption. Stool is formed in the large intestine, and bile is produced by the liver.'),
  ('digestive', 35, 'A nurse is teaching about the sections of the small intestine. Which section does the nurse identify as the site where most digestion occurs?', '[{"id": "a", "text": "Duodenum"}, {"id": "b", "text": "Jejunum"}, {"id": "c", "text": "Ileum"}, {"id": "d", "text": "Colon"}]'::jsonb, '["a"]', 'The duodenum is the most important section, where most digestion occurs. The jejunum is the middle section that continues nutrient absorption.'),
  ('digestive', 36, 'A client has low iron, calcium, and magnesium levels, and a malabsorption problem is suspected. The nurse recognizes that absorption of these minerals depends heavily on which section of the GI tract?', '[{"id": "a", "text": "Stomach"}, {"id": "b", "text": "Large intestine"}, {"id": "c", "text": "Duodenum"}, {"id": "d", "text": "Rectum"}]'::jsonb, '["c"]', 'The duodenum is important for iron, calcium, and magnesium absorption. The large intestine absorbs water, vitamins, and electrolytes and forms stool.'),
  ('digestive', 37, 'A nursing student compares the environment of the stomach with that of the duodenum. Which statement about the duodenum is accurate?', '[{"id": "a", "text": "Its pH is strongly acidic, between 1.5 and 3.5."}, {"id": "b", "text": "Its pH is neutral to slightly alkaline."}, {"id": "c", "text": "Its pH matches that of the stomach."}, {"id": "d", "text": "Its pH is lowered by pancreatic bicarbonate."}]'::jsonb, '["b"]', 'The duodenum has a neutral to slightly alkaline pH, where pancreatic bicarbonate neutralizes stomach acid. A pH of 1.5–3.5 describes stomach acid.'),
  ('digestive', 38, 'A nurse is teaching about vitamins absorbed across the small intestine. Which group of vitamins does the nurse identify as fat-soluble?', '[{"id": "a", "text": "B, C, D, and K"}, {"id": "b", "text": "A, B, C, and E"}, {"id": "c", "text": "B, C, E, and K"}, {"id": "d", "text": "A, D, E, and K"}]'::jsonb, '["d"]', 'The fat-soluble vitamins A, D, E, and K are absorbed across the small intestine. Each other option includes vitamins outside this fat-soluble group.'),
  ('digestive', 39, 'A client is told that a lesion was found in the middle section of the small intestine. The nurse recognizes this section as which structure?', '[{"id": "a", "text": "Duodenum"}, {"id": "b", "text": "Ileum"}, {"id": "c", "text": "Jejunum"}, {"id": "d", "text": "Pylorus"}]'::jsonb, '["c"]', 'The jejunum is the middle section of the small intestine and continues nutrient absorption. The ileum is the last section.'),
  ('digestive', 40, 'A client is scheduled for surgery near the ileocecal junction. The nurse knows this junction connects the large intestine to which section of the small intestine?', '[{"id": "a", "text": "Ileum"}, {"id": "b", "text": "Jejunum"}, {"id": "c", "text": "Duodenum"}, {"id": "d", "text": "Pylorus"}]'::jsonb, '["a"]', 'The ileum is the last section of the small intestine and connects to the large intestine at the ileocecal junction. The jejunum is the middle section.'),
  ('digestive', 41, 'A nurse is explaining the anatomy of the small intestine to a client before surgery. Which sequence describes the sections in the order that food passes through them?', '[{"id": "a", "text": "Jejunum, duodenum, ileum"}, {"id": "b", "text": "Ileum, jejunum, duodenum"}, {"id": "c", "text": "Duodenum, ileum, jejunum"}, {"id": "d", "text": "Duodenum, jejunum, ileum"}]'::jsonb, '["d"]', 'Food passes from the duodenum to the jejunum and then the ileum. The ileum is the last section, so it cannot come first.'),
  ('digestive', 42, 'A client with frequent watery stools asks which part of the bowel normally absorbs water and forms stool. Which response by the nurse is accurate?', '[{"id": "a", "text": "The stomach"}, {"id": "b", "text": "The duodenum"}, {"id": "c", "text": "The large intestine"}, {"id": "d", "text": "The esophagus"}]'::jsonb, '["c"]', 'The large intestine absorbs water, vitamins, and electrolytes and forms stool. The stomach has only minimal water absorption.'),
  ('digestive', 43, 'A client asks the nurse about the role of the rectum. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It absorbs most nutrients from food."}, {"id": "b", "text": "It stores waste and then expels it."}, {"id": "c", "text": "It produces bile for fat digestion."}, {"id": "d", "text": "It neutralizes acid from the stomach."}]'::jsonb, '["b"]', 'The rectum and anus store and then expel waste using internal and external sphincters. Nutrient absorption occurs mainly in the small intestine.'),
  ('digestive', 44, 'A nurse is teaching about absorption of digested nutrients. Into which system are absorbed fats taken up?', '[{"id": "a", "text": "Bloodstream directly"}, {"id": "b", "text": "Lymphatic system"}, {"id": "c", "text": "Bile ducts"}, {"id": "d", "text": "Large intestine"}]'::jsonb, '["b"]', 'During absorption, nutrients move into the bloodstream, but fats move into the lymphatic system. Stating that fats go directly into the bloodstream is the common error.'),
  ('digestive', 45, 'A client''s intestinal activity has slowed after surgery. The nurse recalls that peristalsis carries out which function of the digestive system?', '[{"id": "a", "text": "Mixing and propulsion"}, {"id": "b", "text": "Secretion of enzymes"}, {"id": "c", "text": "Ingestion of food"}, {"id": "d", "text": "Absorption of nutrients"}]'::jsonb, '["a"]', 'Mixing and propulsion occur through peristalsis, which moves food through the tract. Secretion refers to releasing enzymes and mucus.'),
  ('digestive', 46, 'A nurse is teaching a client with poor dentition about digestion. Which activity does the nurse identify as mechanical digestion?', '[{"id": "a", "text": "Enzymes breaking down food"}, {"id": "b", "text": "Bile digesting dietary fats"}, {"id": "c", "text": "Acid activating stomach enzymes"}, {"id": "d", "text": "Teeth chewing the food"}]'::jsonb, '["d"]', 'Mechanical digestion is chewing, while chemical digestion is carried out by enzymes. Enzyme breakdown is therefore chemical, not mechanical, digestion.'),
  ('digestive', 47, 'A nurse is describing the secretion function of the digestive system. Which secreted substance protects the lining of the tract?', '[{"id": "a", "text": "Bile"}, {"id": "b", "text": "Amylase"}, {"id": "c", "text": "Mucus"}, {"id": "d", "text": "Hydrochloric acid"}]'::jsonb, '["c"]', 'During secretion, enzymes are released to break down macronutrients and mucus is released to protect the lining. Hydrochloric acid is the substance the lining must be protected from.'),
  ('digestive', 48, 'A client receiving nutrition teaching asks what dietary fats are broken down into. Which response by the nurse is accurate?', '[{"id": "a", "text": "Amino acids"}, {"id": "b", "text": "Glucose"}, {"id": "c", "text": "Bile and bilirubin"}, {"id": "d", "text": "Fatty acids and glycerol"}]'::jsonb, '["d"]', 'The final digestion product of fats is lipids in the form of fatty acids and glycerol. Amino acids are the final product of proteins.'),
  ('digestive', 49, 'A nurse is reviewing digestive anatomy with a client. Which organ is an accessory organ rather than part of the alimentary canal?', '[{"id": "a", "text": "Esophagus"}, {"id": "b", "text": "Pancreas"}, {"id": "c", "text": "Stomach"}, {"id": "d", "text": "Large intestine"}]'::jsonb, '["b"]', 'The accessory organs are the liver, pancreas, and gallbladder, while the alimentary canal is the hollow tube from mouth to anus. The esophagus, stomach, and large intestine belong to the alimentary canal.'),
  ('digestive', 50, 'A client with liver failure has a reduced ability to clear medications and toxins. The nurse relates this to loss of which liver function?', '[{"id": "a", "text": "Storing bile and releasing it to the duodenum"}, {"id": "b", "text": "Producing bicarbonate to neutralize acid"}, {"id": "c", "text": "Processing nutrients and detoxifying substances"}, {"id": "d", "text": "Absorbing water and electrolytes from stool"}]'::jsonb, '["c"]', 'The liver processes nutrients and detoxifies substances. Storing and releasing bile is the role of the gallbladder.'),
  ('quadrants', 1, 'A client reports right upper abdominal pain that started about an hour after eating a fatty meal. The nurse notes a positive Murphy''s sign. Which condition does the nurse suspect?', '[{"id": "a", "text": "Cholecystitis"}, {"id": "b", "text": "Appendicitis"}, {"id": "c", "text": "Diverticulitis"}, {"id": "d", "text": "Splenic rupture"}]'::jsonb, '["a"]', 'RUQ pain with a positive Murphy''s sign and pain after a fatty meal is the classic presentation of cholecystitis. Appendicitis presents in the RLQ with McBurney''s point tenderness.'),
  ('quadrants', 2, 'A client is admitted with suspected cholecystitis. In which abdominal quadrant does the nurse expect the client to report pain?', '[{"id": "a", "text": "Left upper quadrant"}, {"id": "b", "text": "Right upper quadrant"}, {"id": "c", "text": "Right lower quadrant"}, {"id": "d", "text": "Left lower quadrant"}]'::jsonb, '["b"]', 'Cholecystitis involves the gallbladder and presents as RUQ pain, especially after a fatty meal. The RLQ is the classic location for appendicitis.'),
  ('quadrants', 3, 'A nurse is assessing the right upper quadrant (RUQ) of a client''s abdomen. Which group of structures lies in this quadrant?', '[{"id": "a", "text": "Stomach, spleen, and body of the pancreas"}, {"id": "b", "text": "Cecum, appendix, and ascending colon"}, {"id": "c", "text": "Gallbladder, duodenum, and head of the pancreas"}, {"id": "d", "text": "Sigmoid colon, left ureter, and left ovary"}]'::jsonb, '["c"]', 'The RUQ contains the right lobe of the liver, gallbladder, duodenum, and head of the pancreas. The stomach, spleen, and body of the pancreas are in the LUQ.'),
  ('quadrants', 4, 'A client was struck in the left upper abdomen during a fall. Which group of organs lies beneath this area?', '[{"id": "a", "text": "Gallbladder, duodenum, and right kidney"}, {"id": "b", "text": "Cecum, appendix, and right ureter"}, {"id": "c", "text": "Sigmoid colon and descending colon"}, {"id": "d", "text": "Stomach, spleen, and tail of the pancreas"}]'::jsonb, '["d"]', 'The LUQ contains the stomach, spleen, left lobe of the liver, and the body and tail of the pancreas. The gallbladder and duodenum are RUQ structures.'),
  ('quadrants', 5, 'A client reports tenderness in the right lower quadrant (RLQ). Which structures does the nurse recognize are located in this quadrant?', '[{"id": "a", "text": "Stomach, spleen, and left kidney"}, {"id": "b", "text": "Cecum, appendix, and ascending colon"}, {"id": "c", "text": "Gallbladder, duodenum, and liver"}, {"id": "d", "text": "Sigmoid colon and descending colon"}]'::jsonb, '["b"]', 'The RLQ contains the cecum, appendix, and ascending colon. The sigmoid and descending colon lie in the LLQ.'),
  ('quadrants', 6, 'A client reports pain in the left lower quadrant (LLQ). Which structures does the nurse recognize lie in this quadrant?', '[{"id": "a", "text": "Cecum and appendix"}, {"id": "b", "text": "Gallbladder and duodenum"}, {"id": "c", "text": "Descending and sigmoid colon"}, {"id": "d", "text": "Stomach and spleen"}]'::jsonb, '["c"]', 'The LLQ contains the descending colon and sigmoid colon. The cecum and appendix are located in the RLQ.'),
  ('quadrants', 7, 'A client with pancreatitis asks why the provider examined both upper quadrants of the abdomen. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The head of the pancreas is in the RUQ; the body and tail are in the LUQ.\""}, {"id": "b", "text": "\"The entire pancreas lies in the RUQ next to the gallbladder.\""}, {"id": "c", "text": "\"The head of the pancreas is in the LUQ; the tail is in the RUQ.\""}, {"id": "d", "text": "\"The entire pancreas lies in the LUQ next to the spleen.\""}]'::jsonb, '["a"]', 'The head of the pancreas lies in the RUQ, and the body and tail lie in the LUQ. Placing the head in the LUQ reverses the anatomy.'),
  ('quadrants', 8, 'A nursing student caring for a client with hepatitis asks where the liver is located. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The entire liver lies in the right upper quadrant.\""}, {"id": "b", "text": "\"The entire liver lies in the left upper quadrant.\""}, {"id": "c", "text": "\"The right lobe is in the LUQ, and the left lobe is in the RUQ.\""}, {"id": "d", "text": "\"The right lobe is in the RUQ, and the left lobe is in the LUQ.\""}]'::jsonb, '["d"]', 'The right lobe of the liver is in the RUQ, and the left lobe of the liver is in the LUQ. Stating the entire liver lies in the RUQ overlooks the left lobe.'),
  ('quadrants', 9, 'A female client reports sudden, severe lower abdominal pain. The nurse knows that ovarian cysts or torsion can cause pain in which quadrant(s)?', '[{"id": "a", "text": "Right lower quadrant only"}, {"id": "b", "text": "Left lower quadrant only"}, {"id": "c", "text": "Either lower quadrant"}, {"id": "d", "text": "Either upper quadrant"}]'::jsonb, '["c"]', 'Ovarian cyst/torsion is linked to any lower quadrant, because the right ovary is in the RLQ and the left ovary is in the LLQ. Limiting it to the right side misses the left ovary.'),
  ('quadrants', 10, 'A nurse is assessing the right upper quadrant of a client''s abdomen. Along with the liver and gallbladder, which structures lie in this quadrant?', '[{"id": "a", "text": "Right kidney and adrenal gland"}, {"id": "b", "text": "Left kidney and adrenal gland"}, {"id": "c", "text": "Spleen and stomach"}, {"id": "d", "text": "Sigmoid colon and left ureter"}]'::jsonb, '["a"]', 'The RUQ contains the right kidney and adrenal gland. The left kidney and adrenal gland are in the LUQ.'),
  ('quadrants', 11, 'A nurse is assessing the left upper quadrant of a client''s abdomen. Along with the stomach and spleen, which structures lie in this quadrant?', '[{"id": "a", "text": "Right kidney and adrenal gland"}, {"id": "b", "text": "Left kidney and adrenal gland"}, {"id": "c", "text": "Gallbladder and duodenum"}, {"id": "d", "text": "Cecum and appendix"}]'::jsonb, '["b"]', 'The LUQ contains the left kidney and adrenal gland along with the stomach and spleen. The right kidney and adrenal gland lie in the RUQ.'),
  ('quadrants', 12, 'A client reports right lower quadrant pain, and appendicitis has been ruled out. Which other condition associated with this quadrant should the nurse consider?', '[{"id": "a", "text": "Splenic rupture"}, {"id": "b", "text": "Hepatitis"}, {"id": "c", "text": "Gastric ulcer"}, {"id": "d", "text": "Ureteral stone"}]'::jsonb, '["d"]', 'Conditions associated with the RLQ include appendicitis, ovarian cysts/torsion, kidney/ureteral stones, and IBD. Gastric ulcers are associated with the LUQ.'),
  ('quadrants', 13, 'A female client presents with right lower quadrant pain. Besides the appendix, which structures in this quadrant does the nurse consider as a possible source?', '[{"id": "a", "text": "Right ovary and fallopian tube"}, {"id": "b", "text": "Left ovary and fallopian tube"}, {"id": "c", "text": "Spleen and stomach"}, {"id": "d", "text": "Gallbladder and duodenum"}]'::jsonb, '["a"]', 'The right ovary and fallopian tube lie in the RLQ of a female client. The left ovary and fallopian tube are in the LLQ.'),
  ('quadrants', 14, 'A female client reports left lower quadrant pain. Which reproductive structures lie in this quadrant?', '[{"id": "a", "text": "Right ovary and right fallopian tube"}, {"id": "b", "text": "Spleen and splenic flexure"}, {"id": "c", "text": "Left ovary and left fallopian tube"}, {"id": "d", "text": "Head of pancreas and duodenum"}]'::jsonb, '["c"]', 'The left ovary and fallopian tube are located in the LLQ. The right ovary and fallopian tube are in the RLQ.'),
  ('quadrants', 15, 'A client with a history of gastritis reports upper abdominal pain. The nurse recognizes that the stomach lies in which quadrant?', '[{"id": "a", "text": "Right upper quadrant"}, {"id": "b", "text": "Left upper quadrant"}, {"id": "c", "text": "Right lower quadrant"}, {"id": "d", "text": "Left lower quadrant"}]'::jsonb, '["b"]', 'The stomach is in the LUQ, so gastric ulcers and gastritis are associated with that quadrant. The RUQ is associated with gallbladder, liver, and pancreas problems.'),
  ('quadrants', 16, 'A client with an enlarged spleen is being assessed. In which quadrant does the nurse expect findings related to splenomegaly?', '[{"id": "a", "text": "Right upper quadrant"}, {"id": "b", "text": "Right lower quadrant"}, {"id": "c", "text": "Left lower quadrant"}, {"id": "d", "text": "Left upper quadrant"}]'::jsonb, '["d"]', 'The spleen lies in the LUQ, and splenomegaly/rupture is associated with that quadrant. The RUQ contains the liver and gallbladder, not the spleen.'),
  ('quadrants', 17, 'A client reports severe epigastric and right upper quadrant pain that radiates to the back. Laboratory results show elevated lipase and amylase. Which condition does the nurse suspect?', '[{"id": "a", "text": "Pancreatitis"}, {"id": "b", "text": "Cholecystitis"}, {"id": "c", "text": "Hepatitis"}, {"id": "d", "text": "Appendicitis"}]'::jsonb, '["a"]', 'RUQ/epigastric pain that radiates to the back with elevated lipase and amylase indicates pancreatitis. Cholecystitis is identified by a positive Murphy''s sign and pain after a fatty meal.'),
  ('quadrants', 18, 'A client is admitted with suspected pancreatitis. Which laboratory findings would support this diagnosis?', '[{"id": "a", "text": "Elevated liver function tests"}, {"id": "b", "text": "Normal lipase with low amylase"}, {"id": "c", "text": "Elevated lipase and amylase"}, {"id": "d", "text": "Decreased lipase and amylase"}]'::jsonb, '["c"]', 'Elevated lipase and amylase are the key clue for pancreatitis. Elevated LFTs with jaundice point to hepatitis instead.'),
  ('quadrants', 19, 'Two clients have right upper quadrant pain. Which additional finding suggests pancreatitis rather than cholecystitis?', '[{"id": "a", "text": "Pain that began after a fatty meal"}, {"id": "b", "text": "Pain that radiates to the back"}, {"id": "c", "text": "A positive Murphy''s sign"}, {"id": "d", "text": "Tenderness at McBurney''s point"}]'::jsonb, '["b"]', 'Pancreatitis pain radiates to the back with elevated lipase/amylase. A positive Murphy''s sign and pain after a fatty meal point to cholecystitis.'),
  ('quadrants', 20, 'A client reports right upper quadrant pain. The nurse notes yellowing of the skin, and liver function tests are elevated. Which condition does the nurse suspect?', '[{"id": "a", "text": "Cholecystitis"}, {"id": "b", "text": "Diverticulitis"}, {"id": "c", "text": "Splenic rupture"}, {"id": "d", "text": "Hepatitis"}]'::jsonb, '["d"]', 'RUQ pain with jaundice and elevated LFTs is the key clue for hepatitis. Cholecystitis is distinguished by a positive Murphy''s sign and pain after a fatty meal.'),
  ('quadrants', 21, 'A nurse is trying to distinguish hepatitis from cholecystitis in a client with right upper quadrant pain. Which finding points to hepatitis?', '[{"id": "a", "text": "A positive Murphy''s sign"}, {"id": "b", "text": "Pain after a fatty meal"}, {"id": "c", "text": "Jaundice with elevated LFTs"}, {"id": "d", "text": "Pain radiating to the back"}]'::jsonb, '["c"]', 'Jaundice and elevated LFTs are the key clue for hepatitis. Pain radiating to the back is the clue for pancreatitis, and Murphy''s sign points to cholecystitis.'),
  ('quadrants', 22, 'A client involved in a motor vehicle crash reports left upper quadrant abdominal pain and pain in the left shoulder. Which condition should the nurse suspect?', '[{"id": "a", "text": "Splenic rupture"}, {"id": "b", "text": "Cholecystitis"}, {"id": "c", "text": "Appendicitis"}, {"id": "d", "text": "Diverticulitis"}]'::jsonb, '["a"]', 'Left shoulder pain (Kehr''s sign) after trauma indicates splenic rupture. Cholecystitis presents with RUQ pain after a fatty meal, not after trauma.'),
  ('quadrants', 23, 'A nurse is assessing a client for Kehr''s sign after blunt abdominal trauma. Which client statement indicates a positive Kehr''s sign?', '[{"id": "a", "text": "\"My right shoulder aches when I breathe in.\""}, {"id": "b", "text": "\"The pain gets worse after I eat fatty food.\""}, {"id": "c", "text": "\"My lower right belly hurts when you let go.\""}, {"id": "d", "text": "\"I have a lot of pain in my left shoulder.\""}]'::jsonb, '["d"]', 'Kehr''s sign is left shoulder pain in a client with a trauma history. Pain on release of pressure in the right lower abdomen describes rebound tenderness, a clue for appendicitis.'),
  ('quadrants', 24, 'A client with a suspected ruptured spleen asks why the left shoulder hurts when the injury is in the abdomen. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It is likely a separate shoulder injury from the crash.\""}, {"id": "b", "text": "\"It is referred pain from blood in the left upper abdomen.\""}, {"id": "c", "text": "\"It is referred pain from an inflamed gallbladder.\""}, {"id": "d", "text": "\"It is referred pain from pressure on the appendix.\""}]'::jsonb, '["b"]', 'Kehr''s sign after trauma reflects splenic rupture, with referred pain from blood in the LUQ. Assuming a separate shoulder injury would miss this warning sign.'),
  ('quadrants', 25, 'A nurse receives reports on four clients. Which client''s finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "A client with gastritis who reports mild, ongoing LUQ discomfort"}, {"id": "b", "text": "A client with IBD who reports familiar lower abdominal cramping"}, {"id": "c", "text": "A client after a bicycle crash who reports new left shoulder pain"}, {"id": "d", "text": "A client with a kidney stone whose pain is now well controlled"}]'::jsonb, '["c"]', 'Left shoulder pain (Kehr''s sign) after trauma suggests splenic rupture from LUQ blood. The other clients describe ongoing or controlled symptoms that match their known conditions.'),
  ('quadrants', 26, 'A client has right lower quadrant pain. On assessment, the nurse notes tenderness at McBurney''s point and rebound tenderness. Which condition does the nurse suspect?', '[{"id": "a", "text": "Appendicitis"}, {"id": "b", "text": "Diverticulitis"}, {"id": "c", "text": "Cholecystitis"}, {"id": "d", "text": "Splenic rupture"}]'::jsonb, '["a"]', 'RLQ pain with McBurney''s point tenderness and rebound tenderness is the classic clue for appendicitis. Diverticulitis presents with left-sided pain and fever in an elderly client.'),
  ('quadrants', 27, 'A 24-year-old client arrives at the emergency department reporting right lower quadrant pain. Which condition should the nurse consider first?', '[{"id": "a", "text": "Diverticulitis"}, {"id": "b", "text": "Hepatitis"}, {"id": "c", "text": "Splenic rupture"}, {"id": "d", "text": "Appendicitis"}]'::jsonb, '["d"]', 'RLQ pain should prompt the nurse to think of appendicitis first. Diverticulitis is suggested by LLQ pain in an elderly client with fever.'),
  ('quadrants', 28, 'A nurse is assessing a client for suspected appendicitis. In which quadrant is McBurney''s point located?', '[{"id": "a", "text": "Right upper quadrant"}, {"id": "b", "text": "Right lower quadrant"}, {"id": "c", "text": "Left upper quadrant"}, {"id": "d", "text": "Left lower quadrant"}]'::jsonb, '["b"]', 'Appendicitis is associated with RLQ pain and McBurney''s point tenderness. The LLQ is the classic location for diverticulitis.'),
  ('quadrants', 29, 'Which assessment finding in a client with right lower quadrant pain supports a suspicion of appendicitis?', '[{"id": "a", "text": "A positive Murphy''s sign"}, {"id": "b", "text": "Pain in the left shoulder"}, {"id": "c", "text": "Rebound tenderness"}, {"id": "d", "text": "Jaundice"}]'::jsonb, '["c"]', 'McBurney''s point tenderness and rebound tenderness are the key clues for appendicitis. A positive Murphy''s sign points to cholecystitis.'),
  ('quadrants', 30, 'A 78-year-old client reports pain in the left lower quadrant and has a fever. Which condition should the nurse suspect?', '[{"id": "a", "text": "Appendicitis"}, {"id": "b", "text": "Cholecystitis"}, {"id": "c", "text": "Hepatitis"}, {"id": "d", "text": "Diverticulitis"}]'::jsonb, '["d"]', 'LLQ pain in an elderly client with fever suggests diverticulitis. Appendicitis is associated with RLQ pain and McBurney''s point tenderness.'),
  ('quadrants', 31, 'A client is admitted with diverticulitis. In which quadrant does the nurse expect the client''s pain to be located?', '[{"id": "a", "text": "Left lower quadrant"}, {"id": "b", "text": "Right lower quadrant"}, {"id": "c", "text": "Right upper quadrant"}, {"id": "d", "text": "Left upper quadrant"}]'::jsonb, '["a"]', 'Diverticulitis presents with left-sided LLQ pain and fever, classically in an elderly client. The RLQ is the classic location for appendicitis.'),
  ('quadrants', 32, 'A 75-year-old female client reports left lower quadrant pain that developed over several days, along with a fever. Which condition is most consistent with these findings?', '[{"id": "a", "text": "Ovarian torsion"}, {"id": "b", "text": "Diverticulitis"}, {"id": "c", "text": "Appendicitis"}, {"id": "d", "text": "Cholecystitis"}]'::jsonb, '["b"]', 'LLQ pain in an elderly client with fever points to diverticulitis. Ovarian cyst/torsion is characterized by sudden severe pain with nausea and vomiting.'),
  ('quadrants', 33, 'A 22-year-old female client reports sudden, severe lower abdominal pain with nausea and vomiting. Which condition should the nurse suspect?', '[{"id": "a", "text": "Diverticulitis"}, {"id": "b", "text": "Hepatitis"}, {"id": "c", "text": "Ovarian cyst or torsion"}, {"id": "d", "text": "Splenic rupture"}]'::jsonb, '["c"]', 'Sudden severe lower abdominal pain with nausea and vomiting in a female client suggests ovarian cyst/torsion. Diverticulitis is typically seen in an elderly client with left-sided pain and fever.'),
  ('quadrants', 34, 'A nursing student asks which quadrants contain portions of the transverse colon. Which response by the nurse is accurate?', '[{"id": "a", "text": "Right and left lower quadrants"}, {"id": "b", "text": "Right upper and right lower quadrants"}, {"id": "c", "text": "Left upper and left lower quadrants"}, {"id": "d", "text": "Right and left upper quadrants"}]'::jsonb, '["d"]', 'Parts of the transverse colon are listed in both the RUQ and the LUQ. The lower quadrants contain the cecum, ascending colon, descending colon, and sigmoid colon instead.'),
  ('quadrants', 35, 'A client with inflammatory bowel disease (IBD) asks where the pain from this condition is commonly felt. The nurse identifies which quadrants?', '[{"id": "a", "text": "Right and left lower quadrants"}, {"id": "b", "text": "Right and left upper quadrants"}, {"id": "c", "text": "Right upper quadrant only"}, {"id": "d", "text": "Left upper quadrant only"}]'::jsonb, '["a"]', 'IBD is listed among the conditions for both the RLQ and the LLQ. The upper quadrants are associated with conditions such as cholecystitis, hepatitis, and gastritis.'),
  ('quadrants', 36, 'A nurse is about to assess the abdomen of a client admitted with right lower quadrant pain. Which sequence should the nurse use?', '[{"id": "a", "text": "Inspection, palpation, percussion, auscultation"}, {"id": "b", "text": "Inspection, auscultation, percussion, palpation"}, {"id": "c", "text": "Auscultation, inspection, percussion, palpation"}, {"id": "d", "text": "Inspection, percussion, palpation, auscultation"}]'::jsonb, '["b"]', 'The abdominal exam order is inspection, auscultation, percussion, and palpation. Palpating before auscultating could alter bowel sounds and other findings.'),
  ('quadrants', 37, 'During an abdominal assessment, a client asks why the nurse listens with a stethoscope before tapping on the abdomen. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Tapping first helps me hear your sounds more clearly.\""}, {"id": "b", "text": "\"Listening first lets me find the edge of your liver.\""}, {"id": "c", "text": "\"Tapping or touching first could alter your bowel sounds.\""}, {"id": "d", "text": "\"Listening first is the order used for every body system.\""}]'::jsonb, '["c"]', 'Auscultation is done before tapping or touching to avoid altering bowel sounds. This order is unique to the abdomen, so it is not the order used for every body system.'),
  ('quadrants', 38, 'A charge nurse observes a newly hired nurse assessing a client''s abdomen. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Inspecting the abdominal contour before touching"}, {"id": "b", "text": "Auscultating bowel sounds before percussing"}, {"id": "c", "text": "Percussing the abdomen before palpating it"}, {"id": "d", "text": "Palpating the abdomen before auscultating"}]'::jsonb, '["d"]', 'Palpation is done last because it can cause pain or tenderness that alters other findings, including bowel sounds. Auscultating before percussing is the correct abdominal order.'),
  ('quadrants', 39, 'A nurse is teaching nursing students about the abdominal assessment. Which statement by a student indicates a need for further teaching?', '[{"id": "a", "text": "\"The abdomen follows the same exam order as other body systems.\""}, {"id": "b", "text": "\"I should listen to bowel sounds before I percuss the abdomen.\""}, {"id": "c", "text": "\"Palpation is the last step of the abdominal examination.\""}, {"id": "d", "text": "\"Inspection is the first step of the abdominal examination.\""}]'::jsonb, '["a"]', 'Unlike other body systems, the abdomen is auscultated before percussion and palpation. Listening to bowel sounds before percussing is correct and does not need further teaching.'),
  ('quadrants', 40, 'A client with right lower quadrant tenderness asks why the nurse waits until the end of the exam to press on the abdomen. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Pressing first would make my inspection more accurate.\""}, {"id": "b", "text": "\"Pressing can cause pain that may change other findings.\""}, {"id": "c", "text": "\"Pressing is only needed if no bowel sounds are heard.\""}, {"id": "d", "text": "\"Pressing first would make tapping unnecessary.\""}]'::jsonb, '["b"]', 'Palpation is done last because it can cause pain or tenderness that alters other findings. Inspection always comes first and is not improved by palpating early.'),
  ('quadrants', 41, 'A client reports right upper quadrant pain. Which condition associated with this quadrant should the nurse consider?', '[{"id": "a", "text": "Diverticulitis"}, {"id": "b", "text": "Appendicitis"}, {"id": "c", "text": "Hepatitis"}, {"id": "d", "text": "Splenomegaly"}]'::jsonb, '["c"]', 'Conditions associated with the RUQ include gallstones/cholecystitis, hepatitis, pancreatitis, and right kidney stones. Splenomegaly is associated with the LUQ.'),
  ('quadrants', 42, 'A client reports left upper quadrant pain without any history of trauma. Which condition associated with this quadrant should the nurse consider?', '[{"id": "a", "text": "Appendicitis"}, {"id": "b", "text": "Hepatitis"}, {"id": "c", "text": "Diverticulitis"}, {"id": "d", "text": "Pancreatitis"}]'::jsonb, '["d"]', 'Conditions associated with the LUQ include gastric ulcers/gastritis, splenomegaly/rupture, pancreatitis, and left kidney stones. Hepatitis is associated with the RUQ.'),
  ('quadrants', 43, 'A diagnostic report notes a mass near the splenic flexure of a client''s colon. The nurse identifies this location as which quadrant?', '[{"id": "a", "text": "Left upper quadrant"}, {"id": "b", "text": "Right upper quadrant"}, {"id": "c", "text": "Left lower quadrant"}, {"id": "d", "text": "Right lower quadrant"}]'::jsonb, '["a"]', 'The splenic flexure of the colon lies in the LUQ. The hepatic flexure, not the splenic flexure, lies in the RUQ.'),
  ('quadrants', 44, 'A client is scheduled for evaluation of the ascending colon. The nurse knows that portions of the ascending colon lie in which quadrants?', '[{"id": "a", "text": "Right upper and left upper quadrants"}, {"id": "b", "text": "Right lower and right upper quadrants"}, {"id": "c", "text": "Left lower and left upper quadrants"}, {"id": "d", "text": "Right lower and left lower quadrants"}]'::jsonb, '["b"]', 'The ascending colon is listed in the RLQ, and parts of the ascending colon are also listed in the RUQ. The descending colon, not the ascending colon, lies on the left side.'),
  ('quadrants', 45, 'A client has a lesion in the descending colon. The nurse knows that portions of the descending colon lie in which quadrants?', '[{"id": "a", "text": "Right upper and right lower quadrants"}, {"id": "b", "text": "Right upper and left upper quadrants"}, {"id": "c", "text": "Left upper and left lower quadrants"}, {"id": "d", "text": "Right lower and left lower quadrants"}]'::jsonb, '["c"]', 'Parts of the descending colon are listed in the LUQ, and the descending colon is listed in the LLQ. The ascending colon is the segment found on the right side.'),
  ('quadrants', 46, 'A nurse assessing a client with right upper quadrant pain notes a positive Murphy''s sign. This finding suggests a problem with which organ?', '[{"id": "a", "text": "Spleen"}, {"id": "b", "text": "Appendix"}, {"id": "c", "text": "Pancreas"}, {"id": "d", "text": "Gallbladder"}]'::jsonb, '["d"]', 'A positive Murphy''s sign with RUQ pain points to cholecystitis, which involves the gallbladder. Pancreatitis is identified by pain radiating to the back and elevated lipase/amylase.'),
  ('quadrants', 47, 'A client has a stone lodged in the left ureter. In which quadrant does the nurse expect the client to report pain?', '[{"id": "a", "text": "Left lower quadrant"}, {"id": "b", "text": "Right upper quadrant"}, {"id": "c", "text": "Right lower quadrant"}, {"id": "d", "text": "Left upper quadrant"}]'::jsonb, '["a"]', 'The left ureter lies in the LLQ, and kidney/ureteral stones are listed among LLQ conditions. The right ureter is in the RLQ, so a left ureteral stone would not cause RLQ pain.'),
  ('quadrants', 48, 'A nurse is reviewing abdominal assessment clues with a group of students. Which pairing of a finding with a condition is correct?', '[{"id": "a", "text": "Kehr''s sign with appendicitis"}, {"id": "b", "text": "Murphy''s sign with cholecystitis"}, {"id": "c", "text": "Rebound tenderness with hepatitis"}, {"id": "d", "text": "Left shoulder pain with diverticulitis"}]'::jsonb, '["b"]', 'A positive Murphy''s sign with pain after a fatty meal is the key clue for cholecystitis. Kehr''s sign (left shoulder pain) is linked to splenic rupture, not appendicitis.'),
  ('quadrants', 49, 'A report notes inflammation near the hepatic flexure of a client''s colon. The nurse identifies this location as which quadrant?', '[{"id": "a", "text": "Left upper quadrant"}, {"id": "b", "text": "Left lower quadrant"}, {"id": "c", "text": "Right upper quadrant"}, {"id": "d", "text": "Right lower quadrant"}]'::jsonb, '["c"]', 'The hepatic flexure of the colon lies in the RUQ. The splenic flexure is the one located in the LUQ.'),
  ('quadrants', 50, 'A nurse is comparing several clients with abdominal pain. Which presentation is most consistent with diverticulitis rather than appendicitis?', '[{"id": "a", "text": "Young client with RLQ tenderness at McBurney''s point"}, {"id": "b", "text": "Older client with RUQ pain after a fatty meal"}, {"id": "c", "text": "Client with left shoulder pain after trauma"}, {"id": "d", "text": "Elderly client with left-sided lower pain and fever"}]'::jsonb, '["d"]', 'Diverticulitis presents in an elderly client with left-sided pain and fever. RLQ tenderness at McBurney''s point indicates appendicitis.'),
  ('exam_sounds', 1, 'A nurse auscultates the lungs of a client admitted with congestive heart failure (CHF). Which adventitious lung sound does the nurse expect to hear?', '[{"id": "a", "text": "Crackles"}, {"id": "b", "text": "Stridor"}, {"id": "c", "text": "Wheezes"}, {"id": "d", "text": "Pleural friction rub"}]'::jsonb, '["a"]', 'Crackles are popping sounds associated with pneumonia, CHF, and pulmonary edema. Wheezes are associated with asthma and COPD rather than CHF.'),
  ('exam_sounds', 2, 'While auscultating the lungs of a client with pneumonia, the nurse hears popping sounds. How should the nurse document this finding?', '[{"id": "a", "text": "Wheezes"}, {"id": "b", "text": "Rhonchi"}, {"id": "c", "text": "Crackles"}, {"id": "d", "text": "Stridor"}]'::jsonb, '["c"]', 'Popping sounds are crackles (rales), which occur with pneumonia, CHF, and pulmonary edema. Rhonchi are low-pitched snoring sounds from secretions in the large airways.'),
  ('exam_sounds', 3, 'A client is admitted with an acute asthma exacerbation. Which lung sound does the nurse expect to hear on auscultation?', '[{"id": "a", "text": "Rhonchi"}, {"id": "b", "text": "Wheezes"}, {"id": "c", "text": "Stridor"}, {"id": "d", "text": "Crackles"}]'::jsonb, '["b"]', 'Wheezes are high-pitched whistling sounds associated with asthma and COPD. Crackles are associated with pneumonia, CHF, and pulmonary edema.'),
  ('exam_sounds', 4, 'A nurse hears high-pitched whistling sounds while auscultating the lungs of a client with chronic obstructive pulmonary disease (COPD). Which term describes this finding?', '[{"id": "a", "text": "Crackles"}, {"id": "b", "text": "Rhonchi"}, {"id": "c", "text": "Pleural friction rub"}, {"id": "d", "text": "Wheezes"}]'::jsonb, '["d"]', 'Wheezes are high-pitched whistling sounds heard with asthma and COPD. Rhonchi are low-pitched snoring sounds rather than high-pitched whistling.'),
  ('exam_sounds', 5, 'A nurse hears low-pitched snoring sounds while auscultating a client''s chest. The sounds clear after the client coughs. Which sound has the nurse most likely heard?', '[{"id": "a", "text": "Wheezes"}, {"id": "b", "text": "Stridor"}, {"id": "c", "text": "Rhonchi"}, {"id": "d", "text": "Crackles"}]'::jsonb, '["c"]', 'Rhonchi are low-pitched snoring sounds caused by secretions in the large airways and clear with cough. Wheezes are high-pitched whistling sounds.'),
  ('exam_sounds', 6, 'A nurse documents rhonchi in a client who has been on bed rest. The nurse recognizes that this sound is caused by which of the following?', '[{"id": "a", "text": "Secretions in the large airways"}, {"id": "b", "text": "Inflammation of the pleura"}, {"id": "c", "text": "Obstruction of the upper airway"}, {"id": "d", "text": "A stiff left ventricle"}]'::jsonb, '["a"]', 'Rhonchi result from secretions in the large airways. Upper airway obstruction produces stridor, which is an emergency.'),
  ('exam_sounds', 7, 'A nurse is assessing lung sounds in several areas. Which finding requires the nurse''s immediate action?', '[{"id": "a", "text": "Soft, low-pitched sounds over peripheral lung fields"}, {"id": "b", "text": "Louder bronchial sounds heard over the trachea"}, {"id": "c", "text": "Low-pitched snoring sounds that clear after coughing"}, {"id": "d", "text": "Harsh, high-pitched sounds from the upper airway"}]'::jsonb, '["d"]', 'Stridor is a harsh, high-pitched upper airway sound and is an emergency. Rhonchi that clear with cough reflect secretions in the large airways and are not the emergency here.'),
  ('exam_sounds', 8, 'A child is brought to the emergency department, and the nurse hears a harsh, high-pitched sound from the upper airway. The nurse recognizes this finding most likely indicates which problem?', '[{"id": "a", "text": "Secretions in the large airways"}, {"id": "b", "text": "Airway obstruction"}, {"id": "c", "text": "Fluid in the lungs"}, {"id": "d", "text": "Pleural inflammation"}]'::jsonb, '["b"]', 'Stridor indicates airway obstruction and is an emergency. Secretions in the large airways cause rhonchi, not stridor.'),
  ('exam_sounds', 9, 'While auscultating a client''s lungs, the nurse hears a grating sound. Which condition does the nurse suspect?', '[{"id": "a", "text": "Pleuritis"}, {"id": "b", "text": "Pericarditis"}, {"id": "c", "text": "Asthma"}, {"id": "d", "text": "Pneumonia"}]'::jsonb, '["a"]', 'A grating sound over the lungs is a pleural friction rub, which indicates pleuritis. Pericarditis causes a scratching pericardial friction rub heard over the heart.'),
  ('exam_sounds', 10, 'A nurse auscultates soft, low-pitched breath sounds over the peripheral lung fields of a client with no respiratory complaints. How should the nurse interpret this finding?', '[{"id": "a", "text": "Crackles that indicate fluid in the lungs"}, {"id": "b", "text": "Rhonchi that indicate airway secretions"}, {"id": "c", "text": "Normal vesicular breath sounds"}, {"id": "d", "text": "Wheezes that indicate airway narrowing"}]'::jsonb, '["c"]', 'Vesicular sounds are soft and low-pitched over the peripheral lung fields and are normal. Wheezes are high-pitched whistling sounds, not soft low-pitched sounds.'),
  ('exam_sounds', 11, 'A nurse hears louder breath sounds while auscultating over the trachea of a client with no respiratory complaints. How should the nurse interpret this finding?', '[{"id": "a", "text": "Stridor that indicates an airway emergency"}, {"id": "b", "text": "Abnormal sounds that must be reported"}, {"id": "c", "text": "Wheezes that indicate airway narrowing"}, {"id": "d", "text": "Normal bronchial breath sounds"}]'::jsonb, '["d"]', 'Bronchial sounds are louder and heard over the trachea, and they are a normal finding. Stridor is a harsh, high-pitched upper airway emergency sound, not a normal louder tracheal sound.'),
  ('exam_sounds', 12, 'A nurse auscultates intermediate breath sounds over the major bronchi of a healthy client. Which term does the nurse use to document this finding?', '[{"id": "a", "text": "Vesicular"}, {"id": "b", "text": "Bronchovesicular"}, {"id": "c", "text": "Bronchial"}, {"id": "d", "text": "Rhonchi"}]'::jsonb, '["b"]', 'Bronchovesicular sounds are intermediate and heard over the major bronchi. Vesicular sounds are soft and low-pitched over the peripheral lung fields.'),
  ('exam_sounds', 13, 'A nurse observes a nursing student auscultating a client''s lung sounds. Which action by the student requires correction?', '[{"id": "a", "text": "Listening over the trachea for bronchial sounds"}, {"id": "b", "text": "Listening over peripheral fields for vesicular sounds"}, {"id": "c", "text": "Listening only over the front of the chest"}, {"id": "d", "text": "Listening again after the client coughs"}]'::jsonb, '["c"]', 'Lung sounds are auscultated with the stethoscope over both the chest and the back. Listening again after a cough is appropriate because rhonchi clear with cough.'),
  ('exam_sounds', 14, 'A nursing student asks what produces the first heart sound (S1, "lub"). Which response by the nurse is accurate?', '[{"id": "a", "text": "Closure of the AV valves at the start of systole"}, {"id": "b", "text": "Closure of the semilunar valves at the start of diastole"}, {"id": "c", "text": "A ventricular gallop occurring in early diastole"}, {"id": "d", "text": "An atrial gallop occurring in late diastole"}]'::jsonb, '["a"]', 'S1 ("lub") occurs when the AV valves close at the start of systole. Semilunar valve closure at the start of diastole produces S2.'),
  ('exam_sounds', 15, 'A client listening to the nurse''s stethoscope asks what makes the "dub" sound. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The AV valves closing as systole starts.\""}, {"id": "b", "text": "\"A gallop that happens early in diastole.\""}, {"id": "c", "text": "\"Turbulent blood flow across a narrowed valve.\""}, {"id": "d", "text": "\"The semilunar valves closing as diastole starts.\""}]'::jsonb, '["d"]', 'S2 ("dub") is produced when the semilunar valves close at the start of diastole. AV valve closure at the start of systole produces S1.'),
  ('exam_sounds', 16, 'A nurse auscultates the heart of an adult client with heart failure and hears an extra sound in early diastole. How should the nurse document this finding?', '[{"id": "a", "text": "S4"}, {"id": "b", "text": "S3"}, {"id": "c", "text": "Murmur"}, {"id": "d", "text": "Click"}]'::jsonb, '["b"]', 'S3 is an early diastolic ventricular gallop that may indicate heart failure in adults. S4 occurs in late diastole and reflects a stiff ventricle.'),
  ('exam_sounds', 17, 'A nurse hears an S3 heart sound in a 58-year-old client. The nurse recognizes this finding may indicate which condition?', '[{"id": "a", "text": "Pericarditis"}, {"id": "b", "text": "Prosthetic valve"}, {"id": "c", "text": "Heart failure"}, {"id": "d", "text": "Pleuritis"}]'::jsonb, '["c"]', 'In adults, S3 is associated with heart failure. Pericarditis produces a scratching pericardial friction rub rather than an S3.'),
  ('exam_sounds', 18, 'A client with long-standing hypertension has an extra heart sound in late diastole. Which heart sound does the nurse document?', '[{"id": "a", "text": "S4"}, {"id": "b", "text": "S3"}, {"id": "c", "text": "S1"}, {"id": "d", "text": "S2"}]'::jsonb, '["a"]', 'S4 is a late diastolic atrial gallop that reflects a stiff ventricle, as seen with HTN and MI. S3 occurs in early diastole.'),
  ('exam_sounds', 19, 'A nurse hears an S4 heart sound in a client recovering from a myocardial infarction (MI). The nurse understands that this sound reflects which problem?', '[{"id": "a", "text": "Closure of the AV valves"}, {"id": "b", "text": "A stiff ventricle"}, {"id": "c", "text": "An inflamed pericardium"}, {"id": "d", "text": "A prosthetic heart valve"}]'::jsonb, '["b"]', 'S4 reflects a stiff ventricle, as seen with HTN and MI. An inflamed pericardium produces a pericardial friction rub.'),
  ('exam_sounds', 20, 'A client with known heart valve stenosis is being assessed. The nurse hears a whooshing sound on cardiac auscultation. Which term describes this finding?', '[{"id": "a", "text": "Pericardial friction rub"}, {"id": "b", "text": "S3 gallop"}, {"id": "c", "text": "S4 gallop"}, {"id": "d", "text": "Murmur"}]'::jsonb, '["d"]', 'A murmur is a whooshing sound caused by turbulent flow from valve stenosis or regurgitation. A pericardial friction rub is a scratching sound associated with pericarditis.'),
  ('exam_sounds', 21, 'A nurse auscultates the heart of a client who has a prosthetic heart valve and hears a click. How should the nurse interpret this finding?', '[{"id": "a", "text": "It indicates pericarditis."}, {"id": "b", "text": "It indicates heart failure."}, {"id": "c", "text": "It is associated with the prosthetic valve."}, {"id": "d", "text": "It indicates a stiff ventricle."}]'::jsonb, '["c"]', 'A click or snap is associated with prosthetic valves or stenosis. Heart failure in adults is suggested by an S3, not a click.'),
  ('exam_sounds', 22, 'A client is admitted with pericarditis. Which finding does the nurse expect on cardiac auscultation?', '[{"id": "a", "text": "A scratching pericardial friction rub"}, {"id": "b", "text": "A grating pleural friction rub"}, {"id": "c", "text": "A whooshing murmur"}, {"id": "d", "text": "An early diastolic gallop"}]'::jsonb, '["a"]', 'A pericardial friction rub is a scratching sound that indicates pericarditis. A grating pleural friction rub indicates pleuritis instead.'),
  ('exam_sounds', 23, 'A nurse is teaching students to distinguish friction rubs. Which pairing of sound and condition is correct?', '[{"id": "a", "text": "Grating sound with pericarditis"}, {"id": "b", "text": "Scratching sound with pleuritis"}, {"id": "c", "text": "Whooshing sound with pleuritis"}, {"id": "d", "text": "Grating sound with pleuritis"}]'::jsonb, '["d"]', 'A pleural friction rub is a grating sound that indicates pleuritis. A scratching pericardial friction rub, not a grating one, indicates pericarditis.'),
  ('exam_sounds', 24, 'A nurse is performing a cardiac assessment on a newly admitted client. Which location is one of the five cardiac auscultation points?', '[{"id": "a", "text": "Carotid point"}, {"id": "b", "text": "Erb''s point"}, {"id": "c", "text": "Femoral point"}, {"id": "d", "text": "Tracheal point"}]'::jsonb, '["b"]', 'The five cardiac auscultation points are aortic, pulmonic, Erb''s point, tricuspid, and mitral. The carotid and femoral arteries are auscultated with the bell for bruits, not as cardiac points.'),
  ('exam_sounds', 25, 'A nurse observes a nursing student auscultating a client''s bowel sounds. Which action by the student requires correction?', '[{"id": "a", "text": "Using the diaphragm of the stethoscope"}, {"id": "b", "text": "Listening only in the right lower quadrant"}, {"id": "c", "text": "Listening in each of the four quadrants"}, {"id": "d", "text": "Listening 5 minutes before charting absent sounds"}]'::jsonb, '["b"]', 'Bowel sounds are auscultated with the diaphragm of the stethoscope in all 4 quadrants, so listening in only one quadrant is incorrect. Using the diaphragm is the correct technique.'),
  ('exam_sounds', 26, 'A nurse auscultates a client''s abdomen and hears irregular, high-pitched gurgles every 5–15 seconds. How should the nurse interpret this finding?', '[{"id": "a", "text": "Hyperactive sounds suggesting obstruction"}, {"id": "b", "text": "Hypoactive sounds suggesting an ileus"}, {"id": "c", "text": "Normal bowel sounds"}, {"id": "d", "text": "A bruit suggesting an aneurysm"}]'::jsonb, '["c"]', 'Irregular, high-pitched gurgles every 5–15 seconds are normal bowel sounds. Hyperactive sounds are rapid and loud and suggest early obstruction or diarrhea.'),
  ('exam_sounds', 27, 'A client has had diarrhea for 2 days. Which bowel sound finding does the nurse expect when auscultating the client''s abdomen?', '[{"id": "a", "text": "Rapid, loud hyperactive sounds"}, {"id": "b", "text": "Slow, infrequent hypoactive sounds"}, {"id": "c", "text": "No sounds heard over 5 minutes"}, {"id": "d", "text": "A turbulent swishing bruit"}]'::jsonb, '["a"]', 'Hyperactive bowel sounds are rapid and loud and occur with diarrhea or early obstruction. Slow, infrequent hypoactive sounds are seen post-op or with ileus.'),
  ('exam_sounds', 28, 'A client reports abdominal cramping but no diarrhea. The nurse auscultates rapid, loud bowel sounds. Which condition might this finding indicate?', '[{"id": "a", "text": "Paralytic ileus"}, {"id": "b", "text": "Postoperative recovery"}, {"id": "c", "text": "Abdominal aortic aneurysm"}, {"id": "d", "text": "Early bowel obstruction"}]'::jsonb, '["d"]', 'Rapid, loud hyperactive bowel sounds suggest early obstruction or diarrhea. A paralytic ileus is associated with absent bowel sounds instead.'),
  ('exam_sounds', 29, 'A client is 1 day post-op after abdominal surgery. The nurse auscultates slow, infrequent bowel sounds. How should the nurse interpret this finding?', '[{"id": "a", "text": "An emergency requiring immediate surgery"}, {"id": "b", "text": "A sign of early bowel obstruction"}, {"id": "c", "text": "Hypoactive sounds seen after surgery"}, {"id": "d", "text": "Normal sounds for a healthy client"}]'::jsonb, '["c"]', 'Hypoactive bowel sounds are slow and infrequent and are associated with the post-op period and ileus. Early obstruction is suggested by rapid, loud hyperactive sounds instead.'),
  ('exam_sounds', 30, 'A client is being treated for an ileus. Which bowel sound finding does the nurse expect during auscultation?', '[{"id": "a", "text": "Rapid, loud hyperactive sounds"}, {"id": "b", "text": "Slow, infrequent hypoactive sounds"}, {"id": "c", "text": "Irregular gurgles every 5–15 seconds"}, {"id": "d", "text": "A turbulent swishing sound"}]'::jsonb, '["b"]', 'Hypoactive bowel sounds are slow and infrequent and are associated with ileus and the post-op period. Irregular gurgles every 5–15 seconds are normal bowel sounds.'),
  ('exam_sounds', 31, 'A nurse auscultates all four quadrants of a client''s abdomen for a full 5 minutes and hears no bowel sounds. Which action should the nurse take?', '[{"id": "a", "text": "Report the finding to the provider immediately"}, {"id": "b", "text": "Document the finding as a normal variation"}, {"id": "c", "text": "Reassess bowel sounds at the next routine check"}, {"id": "d", "text": "Document the bowel sounds as hypoactive"}]'::jsonb, '["a"]', 'Absent bowel sounds, with no sounds in 5 minutes, are an emergency that may indicate paralytic ileus or obstruction. Hypoactive sounds are slow and infrequent rather than absent.'),
  ('exam_sounds', 32, 'A client has a distended abdomen, and the nurse is unable to hear any bowel sounds. The nurse recognizes these findings may indicate which problem?', '[{"id": "a", "text": "Diarrhea"}, {"id": "b", "text": "Early recovery after surgery"}, {"id": "c", "text": "Pleuritis"}, {"id": "d", "text": "Paralytic ileus or obstruction"}]'::jsonb, '["d"]', 'Absent bowel sounds with distention indicate paralytic ileus or obstruction. Diarrhea is associated with hyperactive bowel sounds.'),
  ('exam_sounds', 33, 'A nursing student hears no bowel sounds after listening for 1 minute and documents "bowel sounds absent." Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"That is correct, because no sounds were heard.\""}, {"id": "b", "text": "\"You should listen with the bell instead.\""}, {"id": "c", "text": "\"Listen for 5 minutes before calling them absent.\""}, {"id": "d", "text": "\"Listen in only one quadrant for accuracy.\""}]'::jsonb, '["c"]', 'Bowel sounds are considered absent only when no sounds are heard in 5 minutes. Bowel sounds are auscultated with the diaphragm, not the bell.'),
  ('exam_sounds', 34, 'A nurse is preparing to assess a client''s abdominal aorta for a bruit. Which technique should the nurse use?', '[{"id": "a", "text": "Diaphragm of the stethoscope in all 4 quadrants"}, {"id": "b", "text": "Bell of the stethoscope over the abdominal aorta"}, {"id": "c", "text": "Percussion directly over the abdominal aorta"}, {"id": "d", "text": "Diaphragm of the stethoscope over the trachea"}]'::jsonb, '["b"]', 'Bruits are assessed with the bell of the stethoscope over the carotid, abdominal aorta, and femoral arteries. The diaphragm in all 4 quadrants is the technique for bowel sounds.'),
  ('exam_sounds', 35, 'A nurse auscultates a bruit over a client''s carotid artery. The nurse recognizes that the client is at increased risk for which condition?', '[{"id": "a", "text": "Stroke"}, {"id": "b", "text": "Abdominal aortic aneurysm"}, {"id": "c", "text": "Pericarditis"}, {"id": "d", "text": "Heart failure"}]'::jsonb, '["a"]', 'A carotid bruit indicates stroke risk. An abdominal bruit, not a carotid bruit, suggests a possible abdominal aortic aneurysm.'),
  ('exam_sounds', 36, 'A nurse hears a turbulent swishing sound over the abdominal aorta of an older client. Which condition does the nurse suspect?', '[{"id": "a", "text": "Paralytic ileus"}, {"id": "b", "text": "Early bowel obstruction"}, {"id": "c", "text": "Diarrhea"}, {"id": "d", "text": "Abdominal aortic aneurysm"}]'::jsonb, '["d"]', 'An abdominal bruit suggests a possible abdominal aortic aneurysm (AAA). Early bowel obstruction is suggested by rapid, loud hyperactive bowel sounds, not a swishing bruit.'),
  ('exam_sounds', 37, 'A client asks what the swishing sound the nurse heard over the femoral artery means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It suggests narrowing or a bulge in the artery.\""}, {"id": "b", "text": "\"It is the normal sound of blood in an artery.\""}, {"id": "c", "text": "\"It suggests fluid has collected in your lungs.\""}, {"id": "d", "text": "\"It suggests a heart valve is leaking blood.\""}]'::jsonb, '["a"]', 'A bruit is a turbulent swishing sound caused by narrowing (stenosis) or an aneurysm. It is not a normal finding, and valve regurgitation produces a murmur rather than a bruit.'),
  ('exam_sounds', 38, 'A nurse percusses the chest of a client with emphysema. Which percussion sound does the nurse expect?', '[{"id": "a", "text": "Dull"}, {"id": "b", "text": "Flat"}, {"id": "c", "text": "Hyperresonant"}, {"id": "d", "text": "Resonant"}]'::jsonb, '["c"]', 'Hyperresonance occurs over an air-trapped lung, as in emphysema or pneumothorax. Dullness indicates fluid or solid tissue, such as pneumonia.'),
  ('exam_sounds', 39, 'A client with a suspected pneumothorax is being assessed. Which percussion sound does the nurse expect over the affected side of the chest?', '[{"id": "a", "text": "Dull"}, {"id": "b", "text": "Hyperresonant"}, {"id": "c", "text": "Flat"}, {"id": "d", "text": "Resonant"}]'::jsonb, '["b"]', 'A hyperresonant sound occurs over an air-trapped lung, as in pneumothorax or emphysema. Resonant is the normal lung percussion sound.'),
  ('exam_sounds', 40, 'A client is admitted with lobar pneumonia. Which percussion sound does the nurse expect over the affected area of the lung?', '[{"id": "a", "text": "Resonant"}, {"id": "b", "text": "Hyperresonant"}, {"id": "c", "text": "Tympany"}, {"id": "d", "text": "Dull"}]'::jsonb, '["d"]', 'A dull percussion sound indicates fluid or solid tissue, as in pneumonia, a mass, or over the liver. Hyperresonance indicates an air-trapped lung instead.'),
  ('exam_sounds', 41, 'A nurse percusses directly over a client''s liver during a physical examination. Which percussion sound does the nurse expect?', '[{"id": "a", "text": "Dull"}, {"id": "b", "text": "Tympany"}, {"id": "c", "text": "Hyperresonant"}, {"id": "d", "text": "Resonant"}]'::jsonb, '["a"]', 'A dull sound is produced over fluid or solid structures, including the liver. Tympany is heard over air-filled spaces such as the stomach and bowel.'),
  ('exam_sounds', 42, 'A nurse percusses over the air-filled bowel of a client during an abdominal assessment. Which percussion sound does the nurse expect?', '[{"id": "a", "text": "Dull"}, {"id": "b", "text": "Flat"}, {"id": "c", "text": "Tympany"}, {"id": "d", "text": "Hyperresonant"}]'::jsonb, '["c"]', 'Tympany is heard over air-filled spaces such as the stomach and bowel. Hyperresonance describes an air-trapped lung, not the bowel.'),
  ('exam_sounds', 43, 'A nurse percusses over the large thigh muscle of a client. Which percussion sound does the nurse expect?', '[{"id": "a", "text": "Tympany"}, {"id": "b", "text": "Flat"}, {"id": "c", "text": "Resonant"}, {"id": "d", "text": "Hyperresonant"}]'::jsonb, '["b"]', 'A flat percussion sound is heard over bone or muscle. Tympany is heard over air-filled spaces such as the stomach and bowel.'),
  ('exam_sounds', 44, 'A nurse percusses the chest of a healthy client with no respiratory complaints. Which percussion sound does the nurse expect over the lungs?', '[{"id": "a", "text": "Dull"}, {"id": "b", "text": "Hyperresonant"}, {"id": "c", "text": "Tympany"}, {"id": "d", "text": "Resonant"}]'::jsonb, '["d"]', 'Resonant is the normal, hollow percussion sound over the lungs. Hyperresonance indicates an air-trapped lung, as in emphysema or pneumothorax.'),
  ('exam_sounds', 45, 'A client is admitted with pulmonary edema. Which lung sound does the nurse expect to hear on auscultation?', '[{"id": "a", "text": "Stridor"}, {"id": "b", "text": "Wheezes"}, {"id": "c", "text": "Pleural friction rub"}, {"id": "d", "text": "Crackles"}]'::jsonb, '["d"]', 'Crackles are popping sounds associated with pneumonia, CHF, and pulmonary edema. A pleural friction rub is a grating sound that indicates pleuritis.'),
  ('exam_sounds', 46, 'A nurse is teaching nursing students about stethoscope use. Which statement by a student indicates correct understanding?', '[{"id": "a", "text": "\"I use the bell for bowel sounds and the diaphragm for bruits.\""}, {"id": "b", "text": "\"I use the diaphragm for both bowel sounds and bruits.\""}, {"id": "c", "text": "\"I use the diaphragm for bowel sounds and the bell for bruits.\""}, {"id": "d", "text": "\"I use the bell for both bowel sounds and bruits.\""}]'::jsonb, '["c"]', 'Bowel sounds are auscultated with the diaphragm, while bruits are assessed with the bell over the carotid, abdominal aorta, and femoral arteries. Reversing the two stethoscope parts is a common error.'),
  ('exam_sounds', 47, 'A client is admitted with heart valve regurgitation. Which heart sound finding does the nurse expect?', '[{"id": "a", "text": "S3 gallop"}, {"id": "b", "text": "Murmur"}, {"id": "c", "text": "Pericardial friction rub"}, {"id": "d", "text": "S4 gallop"}]'::jsonb, '["b"]', 'Murmurs indicate valvular disease, such as valve stenosis or regurgitation. An S4 gallop reflects a stiff ventricle from HTN or MI.'),
  ('exam_sounds', 48, 'A nurse hears low-pitched snoring sounds over a client''s large airways. Which action by the nurse will help confirm that these sounds are rhonchi?', '[{"id": "a", "text": "Ask the client to cough, then listen again"}, {"id": "b", "text": "Switch to the bell and listen over the trachea"}, {"id": "c", "text": "Percuss the chest to check for flat sounds"}, {"id": "d", "text": "Listen over the abdominal aorta for a bruit"}]'::jsonb, '["a"]', 'Rhonchi are low-pitched snoring sounds from secretions in the large airways that clear with cough. Listening for a bruit over the aorta assesses vascular narrowing, not airway secretions.'),
  ('exam_sounds', 49, 'A nurse is comparing the lung sounds of several clients. Which finding is associated with COPD rather than CHF?', '[{"id": "a", "text": "Popping crackles"}, {"id": "b", "text": "Grating friction rub"}, {"id": "c", "text": "Harsh upper airway stridor"}, {"id": "d", "text": "High-pitched wheezes"}]'::jsonb, '["d"]', 'High-pitched wheezes are associated with asthma and COPD. Popping crackles are associated with CHF, pneumonia, and pulmonary edema.'),
  ('exam_sounds', 50, 'A nurse is reviewing heart sounds with a nursing student. Which statement by the student is correct?', '[{"id": "a", "text": "\"S1 marks the start of diastole.\""}, {"id": "b", "text": "\"S2 is caused by the AV valves closing.\""}, {"id": "c", "text": "\"S1 is the ''lub'' that starts systole.\""}, {"id": "d", "text": "\"S2 is the ''lub'' that starts systole.\""}]'::jsonb, '["c"]', 'S1 ("lub") occurs when the AV valves close at the start of systole. S2 ("dub") is caused by semilunar valve closure at the start of diastole.'),
  ('ng_tpn', 1, 'A nurse is preparing to begin enteral feedings through a nasogastric (NG) tube that was just inserted. Which method should the nurse use to confirm initial placement?', '[{"id": "a", "text": "Instill an air bolus and auscultate over the stomach"}, {"id": "b", "text": "Obtain an X-ray to confirm the tube position"}, {"id": "c", "text": "Test the aspirate pH and proceed if acidic"}, {"id": "d", "text": "Inspect the aspirate and proceed if it is green"}]'::jsonb, '["b"]', 'X-ray is the gold standard for confirming initial NG tube placement. An air bolus with auscultation alone is no longer best practice, and aspirate pH or color checks do not replace the X-ray for initial placement.'),
  ('ng_tpn', 2, 'Before a scheduled feeding, the nurse aspirates contents from a client''s NG tube and tests the pH. Which result supports gastric placement?', '[{"id": "a", "text": "pH 7.4"}, {"id": "b", "text": "pH 6.5"}, {"id": "c", "text": "pH 8.0"}, {"id": "d", "text": "pH 4.0"}]'::jsonb, '["d"]', 'Gastric contents are acidic, with a pH below 5. Values of 6.5 and higher are not consistent with gastric placement.'),
  ('ng_tpn', 3, 'The nurse checks the aspirate from a client''s NG tube before giving a feeding. Which finding best supports that the tube is in the stomach?', '[{"id": "a", "text": "Green fluid with a pH of 4"}, {"id": "b", "text": "Green fluid with a pH of 7"}, {"id": "c", "text": "Brown fluid with a pH of 8"}, {"id": "d", "text": "Off-white fluid with a pH of 6.5"}]'::jsonb, '["a"]', 'Green, off-white, or brown aspirate is expected, and gastric contents should have a pH below 5. The other options have an expected color but a pH that is not acidic enough for gastric contents.'),
  ('ng_tpn', 4, 'A charge nurse observes a nurse checking NG tube placement before a medication pass. Which action by the nurse requires correction?', '[{"id": "a", "text": "Aspirating gastric contents and testing the pH"}, {"id": "b", "text": "Relying on an air bolus and auscultation alone"}, {"id": "c", "text": "Observing the color of the aspirated contents"}, {"id": "d", "text": "Checking placement before giving the medications"}]'::jsonb, '["b"]', 'An air bolus with auscultation alone is outdated and no longer best practice. Testing aspirate pH, checking aspirate color, and verifying placement before every use are all appropriate.'),
  ('ng_tpn', 5, 'A client''s NG tube placement was confirmed by X-ray yesterday. Before giving the morning medications through the tube, what should the nurse do first?', '[{"id": "a", "text": "Give the medications because placement was already confirmed"}, {"id": "b", "text": "Give the medications and then verify placement afterward"}, {"id": "c", "text": "Flush the tube with 30 mL of water before checking placement"}, {"id": "d", "text": "Verify tube placement before using the tube for medications"}]'::jsonb, '["d"]', 'NG tube placement must be verified before every use, not only at insertion. Giving medications or flushing before verification uses the tube before placement is confirmed.'),
  ('ng_tpn', 6, 'A client is receiving continuous enteral feedings through an NG tube. How should the nurse position the client?', '[{"id": "a", "text": "Supine with the head of the bed flat"}, {"id": "b", "text": "Head of the bed elevated 10–15°"}, {"id": "c", "text": "Head of the bed elevated 30–45°"}, {"id": "d", "text": "Trendelenburg with the feet elevated"}]'::jsonb, '["c"]', 'The head of the bed is elevated 30–45° during and after feedings to prevent aspiration. A flat, minimally raised, or head-down position does not meet this standard.'),
  ('ng_tpn', 7, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a client who just finished an intermittent NG tube feeding. Which UAP action requires correction?', '[{"id": "a", "text": "Lowering the head of the bed flat right after the feeding"}, {"id": "b", "text": "Keeping the head of the bed raised at 30–45° after the feeding"}, {"id": "c", "text": "Raising the head of the bed before the next feeding begins"}, {"id": "d", "text": "Recording the feeding volume on the intake and output record"}]'::jsonb, '["a"]', 'The head of the bed must stay elevated 30–45° both during and after feedings to prevent aspiration, so lowering it flat immediately afterward is unsafe. Keeping the bed elevated and recording intake are appropriate.'),
  ('ng_tpn', 8, 'The family of a client receiving NG tube feedings asks why the head of the bed must stay elevated. The nurse explains that this position mainly helps to:', '[{"id": "a", "text": "speed absorption of the feeding"}, {"id": "b", "text": "keep the tube from eroding the nose"}, {"id": "c", "text": "lower the gastric residual volume"}, {"id": "d", "text": "keep stomach contents out of the lungs"}]'::jsonb, '["d"]', 'Elevating the head of the bed during and after feedings prevents aspiration, which is stomach contents entering the lungs. It is not intended to speed absorption or prevent nasal erosion.'),
  ('ng_tpn', 9, 'Before an intermittent NG tube feeding, the nurse checks the residual volume and obtains 550 mL. What is the nurse''s priority action?', '[{"id": "a", "text": "Give the feeding at a slower rate"}, {"id": "b", "text": "Hold the scheduled feeding"}, {"id": "c", "text": "Give half of the scheduled feeding"}, {"id": "d", "text": "Flush the tube and give the feeding"}]'::jsonb, '["b"]', 'Residual volume is checked before each feeding, and the feeding is held if the residual is greater than 500 mL. Giving any portion of the feeding with a residual of 550 mL is inappropriate.'),
  ('ng_tpn', 10, 'A newly hired nurse describes the plan for checking gastric residual volume in a client receiving intermittent NG feedings. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will check the residual volume before each feeding.\""}, {"id": "b", "text": "\"I will hold the feeding if the residual is over 500 mL.\""}, {"id": "c", "text": "\"I will check the residual volume only once each shift.\""}, {"id": "d", "text": "\"I will verify tube placement before I use the tube.\""}]'::jsonb, '["c"]', 'Residual volume should be checked before each feeding, not once per shift. Holding a feeding for a residual over 500 mL and verifying placement before every use are correct.'),
  ('ng_tpn', 11, 'A nurse is about to administer a medication through a client''s NG tube. How much water should the nurse use to flush the tube before and after the medication?', '[{"id": "a", "text": "5 mL"}, {"id": "b", "text": "10 mL"}, {"id": "c", "text": "30 mL"}, {"id": "d", "text": "100 mL"}]'::jsonb, '["c"]', 'The NG tube is flushed with 30 mL of water before and after medications and feedings. The smaller and larger volumes do not match this standard.'),
  ('ng_tpn', 12, 'Placement of a client''s NG tube was confirmed by X-ray on admission. Which sequence is correct for giving a medication through the tube at the next medication pass?', '[{"id": "a", "text": "Give medication, verify placement, flush with 30 mL water, clamp tube"}, {"id": "b", "text": "Flush with 30 mL water, give medication, clamp tube, verify placement"}, {"id": "c", "text": "Verify placement, give medication, clamp tube, flush with 30 mL water"}, {"id": "d", "text": "Verify placement, flush with 30 mL water, give medication, flush, clamp"}]'::jsonb, '["d"]', 'Placement is verified before every use, the tube is flushed with 30 mL of water before and after the medication, and the tube is then clamped to allow absorption. The other sequences use the tube before verifying placement or omit a flush.'),
  ('ng_tpn', 13, 'The nurse has just administered a medication through a client''s NG tube and flushed the tube with water. Which action should the nurse take next?', '[{"id": "a", "text": "Clamp the tube to allow the medication to be absorbed"}, {"id": "b", "text": "Aspirate the tube to check for the medication"}, {"id": "c", "text": "Lower the head of the bed to aid absorption"}, {"id": "d", "text": "Inject an air bolus to clear the remaining drug"}]'::jsonb, '["a"]', 'After medications, the NG tube is clamped to allow absorption. Lowering the head of the bed increases aspiration risk, and air bolus techniques are outdated.'),
  ('ng_tpn', 14, 'The nurse receives prescriptions to insert NG tubes for four clients. Which client''s prescription should the nurse question?', '[{"id": "a", "text": "A client with a bowel obstruction who needs decompression"}, {"id": "b", "text": "A client who needs gastric lavage after an overdose"}, {"id": "c", "text": "A client with a basilar skull fracture after a fall"}, {"id": "d", "text": "A client who needs enteral feeding into the stomach"}]'::jsonb, '["c"]', 'A basilar skull fracture is a contraindication to NG tube insertion because the tube could enter the brain. Bowel obstruction, gastric lavage after overdose, and enteral feeding are indications.'),
  ('ng_tpn', 15, 'The nurse should clarify a prescription for NG tube insertion for a client with which condition?', '[{"id": "a", "text": "Esophageal varices"}, {"id": "b", "text": "Bowel obstruction"}, {"id": "c", "text": "Medication overdose"}, {"id": "d", "text": "Short bowel syndrome"}]'::jsonb, '["a"]', 'Esophageal varices are a contraindication to NG tube insertion because the fragile veins can rupture. Bowel obstruction and overdose are indications for an NG tube.'),
  ('ng_tpn', 16, 'A nursing student asks why NG tube insertion is contraindicated in a client with a basilar skull fracture. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Fragile veins in the esophagus could rupture.\""}, {"id": "b", "text": "\"The tube could pass into the brain.\""}, {"id": "c", "text": "\"The tube would raise the gastric pH.\""}, {"id": "d", "text": "\"The tube would erode the nasal tissue.\""}]'::jsonb, '["b"]', 'With a basilar skull fracture, the NG tube could enter the brain. Rupture of fragile veins is the reason for avoiding NG tubes in esophageal varices, not skull fracture.'),
  ('ng_tpn', 17, 'A client with esophageal varices is admitted with nausea, and a new nurse asks why an NG tube is being avoided. Which explanation is correct?', '[{"id": "a", "text": "The tube could enter the brain"}, {"id": "b", "text": "The tube could cause refeeding syndrome"}, {"id": "c", "text": "The fragile veins could rupture"}, {"id": "d", "text": "The tube could not be verified by X-ray"}]'::jsonb, '["c"]', 'Esophageal varices are fragile veins that can rupture, which makes them a contraindication to NG tube insertion. Entry into the brain is the concern with a basilar skull fracture.'),
  ('ng_tpn', 18, 'While caring for a client who has had an NG tube for several days, the nurse notes skin breakdown on the nostril where the tube rests. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Aspiration"}, {"id": "b", "text": "Nasal erosion"}, {"id": "c", "text": "Tube displacement"}, {"id": "d", "text": "Metabolic imbalance"}]'::jsonb, '["b"]', 'Nasal erosion is a listed complication of NG tubes and involves damage to the nose where the tube sits. Aspiration involves stomach contents entering the lungs, and displacement involves the tube moving out of position.'),
  ('ng_tpn', 19, 'A client is brought to the emergency department after an intentional overdose, and the provider prescribes insertion of an NG tube. The nurse understands that the purpose of the tube is most likely:', '[{"id": "a", "text": "gastric lavage"}, {"id": "b", "text": "enteral feeding"}, {"id": "c", "text": "bowel decompression"}, {"id": "d", "text": "TPN administration"}]'::jsonb, '["a"]', 'Gastric lavage, such as after an overdose, is an indication for an NG tube. Decompression is used for bowel obstruction, and TPN is given intravenously, not through an NG tube.'),
  ('ng_tpn', 20, 'A client with a bowel obstruction has an NG tube inserted. The client asks what the tube is for. The nurse explains that its primary purpose is:', '[{"id": "a", "text": "gastric lavage"}, {"id": "b", "text": "decompression of the stomach"}, {"id": "c", "text": "intravenous nutrient delivery"}, {"id": "d", "text": "verification of gastric pH"}]'::jsonb, '["b"]', 'Bowel obstruction is an indication for an NG tube for gastric decompression. Gastric lavage is used for overdose, and intravenous nutrients are delivered by TPN.'),
  ('ng_tpn', 21, 'The nurse is teaching a client who is about to have an NG tube inserted. Which statement by the client indicates correct understanding of the tube''s path?', '[{"id": "a", "text": "\"It goes through my nose and esophagus into my stomach.\""}, {"id": "b", "text": "\"It goes through my nose and windpipe into my stomach.\""}, {"id": "c", "text": "\"It goes through my mouth directly into my small bowel.\""}, {"id": "d", "text": "\"It goes through my nose and stops in my esophagus.\""}]'::jsonb, '["a"]', 'An NG tube is a flexible tube inserted through the nose, then the esophagus, into the stomach. It does not pass through the windpipe or end in the esophagus.'),
  ('ng_tpn', 22, 'A client receiving NG tube feedings asks how this differs from total parenteral nutrition (TPN). Which response by the nurse is accurate?', '[{"id": "a", "text": "\"TPN goes into the stomach; tube feedings bypass the GI tract.\""}, {"id": "b", "text": "\"Both tube feedings and TPN bypass the GI tract entirely.\""}, {"id": "c", "text": "\"Tube feedings go into the stomach; TPN is IV and bypasses the GI tract.\""}, {"id": "d", "text": "\"Both tube feedings and TPN deliver nutrients into the stomach.\""}]'::jsonb, '["c"]', 'NG enteral feeding delivers nutrients directly into the stomach, whereas TPN is IV administration of nutrients that bypasses the GI tract entirely. The other responses reverse or merge these routes.'),
  ('ng_tpn', 23, 'The nurse is reviewing the plans of care for four clients. Which client is the most appropriate candidate for TPN?', '[{"id": "a", "text": "A client who needs gastric lavage after an overdose"}, {"id": "b", "text": "A client who needs medications given through an NG tube"}, {"id": "c", "text": "A client who needs gastric decompression for vomiting"}, {"id": "d", "text": "A client with short bowel syndrome and a non-functioning GI tract"}]'::jsonb, '["d"]', 'A non-functioning GI tract, such as with short bowel syndrome, is an indication for TPN. Gastric lavage, medication delivery, and decompression are uses of an NG tube.'),
  ('ng_tpn', 24, 'A client with Crohn''s disease is started on TPN. The client''s family asks why. The nurse explains that TPN is indicated for this client because of:', '[{"id": "a", "text": "a need for gastric lavage"}, {"id": "b", "text": "an absorptive disorder"}, {"id": "c", "text": "a basilar skull fracture"}, {"id": "d", "text": "a need for decompression"}]'::jsonb, '["b"]', 'Absorptive disorders such as Crohn''s disease are an indication for TPN. Gastric lavage and decompression are NG tube indications, and a basilar skull fracture is an NG tube contraindication.'),
  ('ng_tpn', 25, 'A client has been prescribed TPN. Which vascular access device is appropriate for the infusion?', '[{"id": "a", "text": "A peripheral IV in the hand"}, {"id": "b", "text": "A peripheral IV in the forearm"}, {"id": "c", "text": "A peripherally inserted central catheter"}, {"id": "d", "text": "A newly placed nasogastric tube"}]'::jsonb, '["c"]', 'TPN is delivered through a central venous catheter such as a PICC or subclavian line. Peripheral IVs are not used, and TPN bypasses the GI tract rather than using an NG tube.'),
  ('ng_tpn', 26, 'A new nurse asks why TPN cannot be infused through a peripheral IV catheter. Which response by the charge nurse is correct?', '[{"id": "a", "text": "\"Its high glucose content damages peripheral veins.\""}, {"id": "b", "text": "\"A micron filter cannot be used on peripheral lines.\""}, {"id": "c", "text": "\"Peripheral lines cannot be changed every 24 hours.\""}, {"id": "d", "text": "\"Its lipid content cannot pass through a peripheral line.\""}]'::jsonb, '["a"]', 'TPN is given through a central line only because its high glucose content damages peripheral veins. The other explanations are not the stated reason for central administration.'),
  ('ng_tpn', 27, 'A client receiving TPN through a single-lumen PICC is prescribed an IV antibiotic. Which action by the nurse requires correction?', '[{"id": "a", "text": "Using a micron filter on the TPN tubing"}, {"id": "b", "text": "Checking blood glucose every 4–6 hours"}, {"id": "c", "text": "Using sterile technique for dressing changes"}, {"id": "d", "text": "Piggybacking the antibiotic into the TPN line"}]'::jsonb, '["d"]', 'TPN requires a dedicated line, so no other medications may be piggybacked into it. A micron filter, glucose checks every 4–6 hours, and sterile dressing changes are all appropriate.'),
  ('ng_tpn', 28, 'The nurse is gathering equipment to hang a new TPN infusion. Which item should the nurse include on the IV line?', '[{"id": "a", "text": "A micron filter"}, {"id": "b", "text": "A piggyback port for antibiotics"}, {"id": "c", "text": "A peripheral IV extension"}, {"id": "d", "text": "A gastric pH test strip"}]'::jsonb, '["a"]', 'A micron filter is used on the TPN IV line. TPN requires a dedicated central line, so piggybacking and peripheral access are not appropriate.'),
  ('ng_tpn', 29, 'A client''s TPN infusion stopped suddenly when the tubing became disconnected and was not noticed for some time. The nurse should assess the client for which complication?', '[{"id": "a", "text": "Hyperglycemia"}, {"id": "b", "text": "Fluid overload"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Refeeding syndrome"}]'::jsonb, '["c"]', 'Hypoglycemia is a complication when TPN is suddenly stopped. Hyperglycemia is a risk during the infusion, especially in diabetic clients, not after an abrupt stop.'),
  ('ng_tpn', 30, 'The provider plans to discontinue a client''s TPN now that the client is eating. Which plan by the nurse is appropriate?', '[{"id": "a", "text": "Taper the infusion gradually before stopping"}, {"id": "b", "text": "Stop the infusion abruptly when the bag empties"}, {"id": "c", "text": "Increase the rate to finish the current bag"}, {"id": "d", "text": "Stop the infusion and recheck glucose in 24 hours"}]'::jsonb, '["a"]', 'TPN is started and stopped gradually to prevent hypoglycemia and hyperglycemia. Abrupt discontinuation can cause hypoglycemia.'),
  ('ng_tpn', 31, 'A nurse is initiating TPN for a client for the first time. The nurse anticipates that the infusion will be:', '[{"id": "a", "text": "given as a rapid bolus to restore nutrition"}, {"id": "b", "text": "started at the full rate right away"}, {"id": "c", "text": "infused by gravity through a peripheral IV"}, {"id": "d", "text": "started gradually to prevent glucose problems"}]'::jsonb, '["d"]', 'TPN is started and stopped gradually to prevent hypoglycemia and hyperglycemia. Starting at a full or bolus rate does not follow this guideline, and TPN requires a central line.'),
  ('ng_tpn', 32, 'How often should the nurse monitor the blood glucose of a client receiving TPN?', '[{"id": "a", "text": "Every 1 hour"}, {"id": "b", "text": "Every 4–6 hours"}, {"id": "c", "text": "Every 12 hours"}, {"id": "d", "text": "Once a day"}]'::jsonb, '["b"]', 'Blood glucose is monitored every 4–6 hours during TPN because of the risk of hypoglycemia and hyperglycemia. Checking once a day or every 12 hours is too infrequent.'),
  ('ng_tpn', 33, 'The nurse is caring for four clients receiving TPN. Which client is at greatest risk for hyperglycemia?', '[{"id": "a", "text": "A client with Crohn''s disease"}, {"id": "b", "text": "A client with short bowel syndrome"}, {"id": "c", "text": "A client who has been NPO for a week"}, {"id": "d", "text": "A client with diabetes mellitus"}]'::jsonb, '["d"]', 'Hyperglycemia is a TPN complication seen especially in diabetic patients. Crohn''s disease, short bowel syndrome, and prolonged NPO status are indications for TPN rather than risk factors for hyperglycemia.'),
  ('ng_tpn', 34, 'A client receiving TPN develops new crackles in both lung bases and bilateral ankle edema. The nurse recognizes these findings as signs of which complication?', '[{"id": "a", "text": "Hypoglycemia"}, {"id": "b", "text": "Refeeding syndrome"}, {"id": "c", "text": "Fluid overload"}, {"id": "d", "text": "Catheter infection"}]'::jsonb, '["c"]', 'Edema and crackles are signs of fluid overload, a complication of TPN. Refeeding syndrome is a rapid electrolyte shift, and hypoglycemia occurs when TPN is suddenly stopped.'),
  ('ng_tpn', 35, 'The nurse is planning care for a client receiving TPN. Which intervention should be included?', '[{"id": "a", "text": "Weigh the client daily"}, {"id": "b", "text": "Weigh the client weekly"}, {"id": "c", "text": "Check blood glucose daily"}, {"id": "d", "text": "Change the tubing every 72 hours"}]'::jsonb, '["a"]', 'Daily weights and intake and output monitoring are nursing responsibilities for TPN. Weekly weights and daily glucose checks are too infrequent, and tubing is changed every 24 hours.'),
  ('ng_tpn', 36, 'The nurse is hanging a new bag of TPN for a client. Which action by the nurse requires correction?', '[{"id": "a", "text": "Attaching a micron filter to the IV line"}, {"id": "b", "text": "Keeping the TPN on a dedicated line"}, {"id": "c", "text": "Using tubing that has been in place for 48 hours"}, {"id": "d", "text": "Checking the client''s blood glucose every 4–6 hours"}]'::jsonb, '["c"]', 'Both the TPN bag and the tubing are changed every 24 hours, so reusing 48-hour-old tubing is incorrect. A micron filter, a dedicated line, and glucose checks every 4–6 hours are appropriate.'),
  ('ng_tpn', 37, 'During rounds, the nurse reviews the infusion of a client receiving TPN through a PICC. Which finding requires immediate action?', '[{"id": "a", "text": "A micron filter is in place on the IV line"}, {"id": "b", "text": "The TPN bag was hung 30 hours ago"}, {"id": "c", "text": "The TPN is infusing on a dedicated line"}, {"id": "d", "text": "The last glucose check was 4 hours ago"}]'::jsonb, '["b"]', 'The TPN bag and tubing must be changed every 24 hours, so a bag hung 30 hours ago needs to be replaced. A micron filter, a dedicated line, and glucose checks every 4–6 hours are expected.'),
  ('ng_tpn', 38, 'The nurse is changing the central line dressing for a client receiving TPN. Which technique should the nurse use?', '[{"id": "a", "text": "Clean technique"}, {"id": "b", "text": "Sterile technique"}, {"id": "c", "text": "Clean technique with gloves"}, {"id": "d", "text": "No-touch clean technique"}]'::jsonb, '["b"]', 'Sterile technique is required for central line dressing changes in clients receiving TPN. Clean technique does not meet this standard.'),
  ('ng_tpn', 39, 'A client receiving long-term TPN develops sepsis. The nurse recognizes that the infection most likely originated from which source?', '[{"id": "a", "text": "The micron filter"}, {"id": "b", "text": "The lipid component"}, {"id": "c", "text": "The central line"}, {"id": "d", "text": "The NG tube"}]'::jsonb, '["c"]', 'Infection and sepsis in TPN arise from the central line. The micron filter is a safety measure on the IV line, not a stated source of infection.'),
  ('ng_tpn', 40, 'Which nursing action is most directly aimed at preventing a central line–associated bloodstream infection (CLABSI) in a client receiving TPN?', '[{"id": "a", "text": "Checking blood glucose every 4–6 hours"}, {"id": "b", "text": "Weighing the client at the same time daily"}, {"id": "c", "text": "Using sterile technique for dressing changes"}, {"id": "d", "text": "Starting and stopping the infusion gradually"}]'::jsonb, '["c"]', 'Sterile technique for central line dressing changes addresses infection risk, and the nurse watches for CLABSI. Glucose checks and gradual starts and stops target glucose problems, and daily weights address fluid status.'),
  ('ng_tpn', 41, 'A severely malnourished client is started on TPN. The nurse closely monitors phosphate, potassium, and magnesium levels because the client is at risk for:', '[{"id": "a", "text": "refeeding syndrome"}, {"id": "b", "text": "fluid overload"}, {"id": "c", "text": "catheter infection"}, {"id": "d", "text": "aspiration"}]'::jsonb, '["a"]', 'Refeeding syndrome is a rapid electrolyte shift in malnourished patients receiving TPN, so these electrolytes are monitored. Fluid overload presents with edema and crackles rather than an electrolyte shift.'),
  ('ng_tpn', 42, 'Which electrolytes are especially important for the nurse to monitor in a client receiving TPN?', '[{"id": "a", "text": "Sodium, calcium, and chloride"}, {"id": "b", "text": "Phosphate, potassium, and magnesium"}, {"id": "c", "text": "Calcium, chloride, and bicarbonate"}, {"id": "d", "text": "Sodium, chloride, and bicarbonate"}]'::jsonb, '["b"]', 'Electrolytes, especially phosphate, potassium, and magnesium, are key labs to monitor during TPN. The other combinations omit these electrolytes.'),
  ('ng_tpn', 43, 'A client on long-term TPN asks why liver function tests are being drawn. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They check how well your kidneys are working.\""}, {"id": "b", "text": "\"They measure your overall nutritional status.\""}, {"id": "c", "text": "\"The high nutrient load can stress your liver.\""}, {"id": "d", "text": "\"They show whether your blood sugar is too low.\""}]'::jsonb, '["c"]', 'Liver function tests are monitored because the high nutrient load of TPN stresses the liver. Kidney function is assessed with BUN and creatinine, and nutritional status with albumin and prealbumin.'),
  ('ng_tpn', 44, 'The nurse is reviewing laboratory results for a client receiving TPN. Which values should the nurse review to assess kidney function?', '[{"id": "a", "text": "Albumin and prealbumin"}, {"id": "b", "text": "Liver function tests"}, {"id": "c", "text": "Blood glucose levels"}, {"id": "d", "text": "BUN and creatinine"}]'::jsonb, '["d"]', 'BUN and creatinine are monitored during TPN to assess kidney function. Albumin and prealbumin reflect nutritional status, and liver function tests reflect liver stress.'),
  ('ng_tpn', 45, 'A client has received TPN for 2 weeks for severe malnutrition. Which laboratory values best help the nurse evaluate whether the client''s nutritional status is improving?', '[{"id": "a", "text": "BUN and creatinine"}, {"id": "b", "text": "Albumin and prealbumin"}, {"id": "c", "text": "Liver function tests"}, {"id": "d", "text": "Phosphate and potassium"}]'::jsonb, '["b"]', 'Albumin and prealbumin reflect nutritional status. BUN and creatinine reflect kidney function, and liver function tests reflect stress from the high nutrient load.'),
  ('ng_tpn', 46, 'The nurse teaches a client about the TPN solution the client will receive at home. Which statement by the client indicates understanding of its contents?', '[{"id": "a", "text": "\"It has glucose, protein, fat, electrolytes, and vitamins.\""}, {"id": "b", "text": "\"It has only glucose and water to give me calories.\""}, {"id": "c", "text": "\"It has only electrolytes and fluid to keep me hydrated.\""}, {"id": "d", "text": "\"It has protein and vitamins but no glucose or fat at all.\""}]'::jsonb, '["a"]', 'TPN contains dextrose (glucose), amino acids (proteins), lipids (fats), electrolytes, and vitamins and trace elements. The other statements leave out major components.'),
  ('ng_tpn', 47, 'A nursing student reviewing a TPN label asks which component supplies protein. The nurse should identify which component?', '[{"id": "a", "text": "Dextrose"}, {"id": "b", "text": "Lipids"}, {"id": "c", "text": "Amino acids"}, {"id": "d", "text": "Trace elements"}]'::jsonb, '["c"]', 'Amino acids are the protein component of TPN. Dextrose provides glucose, and lipids provide fats.'),
  ('ng_tpn', 48, 'The nurse is caring for a client whose TPN is infusing through a correctly placed central venous catheter. The nurse understands that the solution is delivered into the:', '[{"id": "a", "text": "stomach"}, {"id": "b", "text": "superior vena cava"}, {"id": "c", "text": "small intestine"}, {"id": "d", "text": "peripheral veins"}]'::jsonb, '["b"]', 'TPN is delivered through a central venous catheter into the superior vena cava. It bypasses the GI tract, and peripheral veins are avoided because high glucose damages them.'),
  ('ng_tpn', 49, 'A client has been NPO for an extended period after several complications and is now severely malnourished. Which nutritional therapy should the nurse anticipate?', '[{"id": "a", "text": "TPN through a peripheral IV catheter"}, {"id": "b", "text": "TPN through a central venous catheter"}, {"id": "c", "text": "Gastric lavage through an NG tube"}, {"id": "d", "text": "Gastric decompression through an NG tube"}]'::jsonb, '["b"]', 'Severe malnutrition and prolonged NPO status are indications for TPN, which must be given through a central line. Lavage and decompression are NG tube uses that do not provide nutrition.'),
  ('ng_tpn', 50, 'A client receiving NG tube feedings has a tube that was correctly placed on X-ray 2 days ago. The nurse aspirates contents with a pH of 7 before a feeding. What should the nurse do?', '[{"id": "a", "text": "Give the feeding because X-ray confirmed placement"}, {"id": "b", "text": "Instill air and auscultate to confirm placement"}, {"id": "c", "text": "Flush the tube with 30 mL of water and feed"}, {"id": "d", "text": "Hold the feeding because placement is not confirmed"}]'::jsonb, '["d"]', 'Placement must be verified before every use, and gastric contents should have a pH below 5. A pH of 7 does not confirm gastric placement, and an air bolus with auscultation alone is no longer best practice.'),
  ('central_picc', 1, 'A client has a newly inserted PICC and is prescribed IV antibiotics. What is the nurse''s priority before starting the infusion?', '[{"id": "a", "text": "Flush the line with saline per protocol"}, {"id": "b", "text": "Apply a transparent dressing to the site"}, {"id": "c", "text": "Verify tip placement with a chest X-ray"}, {"id": "d", "text": "Scrub the hub with an alcohol pad"}]'::jsonb, '["c"]', 'Before any infusion through a new PICC or central line, tip placement must be confirmed by chest X-ray. Flushing and scrubbing the hub are routine care but do not replace placement verification.'),
  ('central_picc', 2, 'A subclavian central venous catheter has just been inserted in a client in the ICU, and TPN is prescribed. Which action should the nurse take before hanging the TPN?', '[{"id": "a", "text": "Confirm tip placement on a chest X-ray"}, {"id": "b", "text": "Clamp all lumens for 30 minutes"}, {"id": "c", "text": "Change the dressing using sterile technique"}, {"id": "d", "text": "Place the client in left lateral Trendelenburg"}]'::jsonb, '["a"]', 'Tip placement of a new central line must be confirmed by chest X-ray before first use. Left lateral Trendelenburg is a response to air embolism, not a step before first use.'),
  ('central_picc', 3, 'A charge nurse is observing a nurse care for a client whose central line was inserted 20 minutes ago. Which action by the nurse requires correction?', '[{"id": "a", "text": "Scrubbing the hub before accessing the line"}, {"id": "b", "text": "Monitoring the client for respiratory distress"}, {"id": "c", "text": "Assessing the site for redness and drainage"}, {"id": "d", "text": "Starting fluids while the chest X-ray is pending"}]'::jsonb, '["d"]', 'A central line must never be used until placement is verified by chest X-ray. Scrubbing the hub, monitoring for respiratory distress after insertion, and assessing for infection are appropriate.'),
  ('central_picc', 4, 'The nurse reviews the chest X-ray report for a client with a newly placed PICC. Where should the catheter tip be located?', '[{"id": "a", "text": "In the basilic vein of the upper arm"}, {"id": "b", "text": "In the superior vena cava near the right atrium"}, {"id": "c", "text": "In the subclavian vein below the clavicle"}, {"id": "d", "text": "In the cephalic vein near the elbow"}]'::jsonb, '["b"]', 'A PICC is inserted into a peripheral upper-arm vein and threaded so the tip lies in the superior vena cava near the right atrium. The basilic and cephalic veins are insertion sites, not tip locations.'),
  ('central_picc', 5, 'A nursing student is discussing central venous access with the nurse. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Both device tips rest in the central circulation.\""}, {"id": "b", "text": "\"A PICC is a peripheral line because it enters the arm.\""}, {"id": "c", "text": "\"The devices differ mainly in insertion site and duration.\""}, {"id": "d", "text": "\"A PICC is threaded from the upper arm to the SVC.\""}]'::jsonb, '["b"]', 'Both PICCs and non-PICC central lines are central access devices with tips in the central circulation; the difference is insertion site and duration. A PICC is inserted peripherally but is not a peripheral line.'),
  ('central_picc', 6, 'A client asks where the PICC will be inserted. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Into a large vein under your collarbone.\""}, {"id": "b", "text": "\"Into a large vein in your neck.\""}, {"id": "c", "text": "\"Into a vein in your upper arm.\""}, {"id": "d", "text": "\"Into a large vein in your groin.\""}]'::jsonb, '["c"]', 'A PICC is inserted peripherally into the basilic, brachial, or cephalic vein in the upper arm. The subclavian, jugular, and femoral veins are insertion sites for non-PICC central lines.'),
  ('central_picc', 7, 'Which group of veins includes the insertion sites used for a non-PICC central venous catheter?', '[{"id": "a", "text": "Basilic, brachial, and cephalic"}, {"id": "b", "text": "Subclavian, internal jugular, and femoral"}, {"id": "c", "text": "Cephalic, subclavian, and basilic"}, {"id": "d", "text": "Brachial, femoral, and cephalic"}]'::jsonb, '["b"]', 'A non-PICC central line is inserted directly into a large central vein: subclavian, internal jugular, or femoral. The basilic, brachial, and cephalic veins are PICC insertion sites.'),
  ('central_picc', 8, 'A client who needs a PICC asks whether the procedure must be done in the operating room. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, a surgeon must place it in the operating room.\""}, {"id": "b", "text": "\"No, but it must be placed by a cardiologist.\""}, {"id": "c", "text": "\"Yes, it can only be placed in the ICU.\""}, {"id": "d", "text": "\"No, a trained RN can place it at the bedside.\""}]'::jsonb, '["d"]', 'A PICC is placed at the bedside by a trained RN or in interventional radiology. Placement in the OR, interventional radiology, or ICU is described for non-PICC central lines.'),
  ('central_picc', 9, 'The nurse is explaining where different central access devices are inserted. Which statement is accurate for a non-PICC central line?', '[{"id": "a", "text": "It is inserted in the OR, IR, or ICU"}, {"id": "b", "text": "It is inserted only at the bedside by an RN"}, {"id": "c", "text": "It is inserted only in an outpatient clinic"}, {"id": "d", "text": "It is inserted through a vein in the upper arm"}]'::jsonb, '["a"]', 'Non-PICC central lines are inserted in the OR, interventional radiology, or ICU. Bedside RN placement and upper-arm insertion describe a PICC.'),
  ('central_picc', 10, 'A client is being discharged home to complete 6 weeks of IV antibiotics. The nurse anticipates which vascular access device?', '[{"id": "a", "text": "A PICC line"}, {"id": "b", "text": "A femoral central line"}, {"id": "c", "text": "A peripheral IV in the hand"}, {"id": "d", "text": "A non-tunneled jugular line"}]'::jsonb, '["a"]', 'PICC lines are used for long-term antibiotics and last weeks to months. Non-tunneled central lines are used more for critically ill clients and short-term access.'),
  ('central_picc', 11, 'A client with a chronic condition will need central venous access for several years. Which type of device does the nurse anticipate?', '[{"id": "a", "text": "A PICC line"}, {"id": "b", "text": "A tunneled central line"}, {"id": "c", "text": "A non-tunneled subclavian line"}, {"id": "d", "text": "A non-tunneled femoral line"}]'::jsonb, '["b"]', 'Tunneled central lines can remain for months to years. PICCs last weeks to months, and non-tunneled central lines are used for days to weeks.'),
  ('central_picc', 12, 'The nurse reviews a client''s record, which documents a Hickman catheter. The nurse recognizes this device as which type of central line?', '[{"id": "a", "text": "A PICC line"}, {"id": "b", "text": "An implanted port"}, {"id": "c", "text": "A non-tunneled catheter"}, {"id": "d", "text": "A tunneled catheter"}]'::jsonb, '["d"]', 'Hickman and Broviac catheters are tunneled central lines. A PICC is its own category, and an implanted port is a separate special type.'),
  ('central_picc', 13, 'A client with a tunneled central line no longer needs it. Which statement by a new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"The provider is responsible for this removal.\""}, {"id": "b", "text": "\"This catheter will need surgical removal.\""}, {"id": "c", "text": "\"I can pull this line out at the bedside today.\""}, {"id": "d", "text": "\"Tunneled lines are removed differently than PICCs.\""}]'::jsonb, '["c"]', 'Central lines are removed by a provider, and tunneled lines require surgical removal. Bedside removal by a trained RN applies to PICCs when protocol allows.'),
  ('central_picc', 14, 'A client''s PICC is no longer needed, and the facility protocol allows nurse removal. Who may remove the PICC?', '[{"id": "a", "text": "A trained RN at the bedside"}, {"id": "b", "text": "A surgeon in the operating room"}, {"id": "c", "text": "The unlicensed assistive personnel"}, {"id": "d", "text": "Only the interventional radiologist"}]'::jsonb, '["a"]', 'A PICC may be removed at the bedside by a trained RN if protocol allows. Surgical removal is required for tunneled central lines, not PICCs.'),
  ('central_picc', 15, 'A client is worried about a collapsed lung after hearing about central line risks. The client is scheduled for a PICC. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A PICC has a higher risk than a neck line.\""}, {"id": "b", "text": "\"A PICC has a lower risk than a chest or neck line.\""}, {"id": "c", "text": "\"A PICC has the same risk as a subclavian line.\""}, {"id": "d", "text": "\"A PICC has no risk factors for lung problems.\""}]'::jsonb, '["b"]', 'Pneumothorax risk is higher with subclavian or jugular insertion and lower with a PICC. Lower risk is not the same as no risk.'),
  ('central_picc', 16, 'The nurse is caring for four clients who had vascular access devices inserted today. Which client requires the closest monitoring for pneumothorax?', '[{"id": "a", "text": "A client with a PICC in the basilic vein"}, {"id": "b", "text": "A client with a PICC in the cephalic vein"}, {"id": "c", "text": "A client with a PICC in the brachial vein"}, {"id": "d", "text": "A client with a new subclavian central line"}]'::jsonb, '["d"]', 'Pneumothorax is more common with subclavian or jugular central lines. PICCs, inserted in upper-arm veins, carry a lower pneumothorax risk.'),
  ('central_picc', 17, 'One hour after an internal jugular central line is inserted, a client reports sudden shortness of breath, and the SpO₂ drops. Which complication should the nurse suspect?', '[{"id": "a", "text": "Catheter occlusion"}, {"id": "b", "text": "Thrombosis of the limb"}, {"id": "c", "text": "Pneumothorax"}, {"id": "d", "text": "Bloodstream infection"}]'::jsonb, '["c"]', 'Sudden shortness of breath with decreased SpO₂ after central line insertion suggests pneumothorax or air embolism. Thrombosis presents with limb swelling, pain, and redness, and occlusion is managed by flushing.'),
  ('central_picc', 18, 'A client has just returned from having a central line inserted into the subclavian vein. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Respiratory status"}, {"id": "b", "text": "Arm circumference"}, {"id": "c", "text": "Dressing date"}, {"id": "d", "text": "Hub cap color"}]'::jsonb, '["a"]', 'After a central line is placed in the chest, the nurse monitors for respiratory distress because of the risk of pneumothorax. Limb swelling relates to thrombosis, which is not the immediate post-insertion priority.'),
  ('central_picc', 19, 'A client with a central line suddenly becomes short of breath, and the nurse suspects an air embolism. How should the nurse position the client?', '[{"id": "a", "text": "Right lateral with the head of the bed raised"}, {"id": "b", "text": "High Fowler''s with the arms on pillows"}, {"id": "c", "text": "Supine with the head of the bed flat"}, {"id": "d", "text": "Left lateral Trendelenburg"}]'::jsonb, '["d"]', 'For air embolism, the nurse clamps the line, places the client in left lateral Trendelenburg, and gives 100% oxygen. A right lateral or upright position does not follow this response.'),
  ('central_picc', 20, 'The nurse suspects an air embolism in a client with a central venous catheter. Which set of interventions is appropriate?', '[{"id": "a", "text": "Clamp the line, left lateral Trendelenburg, 100% O₂"}, {"id": "b", "text": "Flush the line, high Fowler''s position, 2 L oxygen"}, {"id": "c", "text": "Remove the line, right lateral position, room air"}, {"id": "d", "text": "Unclamp the line, supine position, 100% O₂"}]'::jsonb, '["a"]', 'Air embolism is managed by clamping the line, placing the client in left lateral Trendelenburg, and giving 100% oxygen. Flushing or unclamping the line and sitting the client upright are not the listed response.'),
  ('central_picc', 21, 'A client with a central line develops sudden dyspnea, and an air embolism is suspected. Which action by the nurse requires correction?', '[{"id": "a", "text": "Clamping the central line"}, {"id": "b", "text": "Raising the client to high Fowler''s"}, {"id": "c", "text": "Administering 100% oxygen"}, {"id": "d", "text": "Turning the client onto the left side"}]'::jsonb, '["b"]', 'The response to air embolism is to clamp the line, place the client in left lateral Trendelenburg, and give 100% oxygen. Raising the client to high Fowler''s is not part of this response.'),
  ('central_picc', 22, 'A client with a PICC in the right arm reports that the arm feels painful. The nurse notes swelling and redness of the right arm. Which complication should the nurse suspect?', '[{"id": "a", "text": "Pneumothorax"}, {"id": "b", "text": "Air embolism"}, {"id": "c", "text": "Catheter occlusion"}, {"id": "d", "text": "Thrombosis"}]'::jsonb, '["d"]', 'Swelling, pain, and redness in the limb are signs of thrombosis. Pneumothorax and air embolism present with sudden shortness of breath and decreased SpO₂.'),
  ('central_picc', 23, 'The nurse is assessing a client with a central line. Which group of findings most suggests infection?', '[{"id": "a", "text": "Site redness, drainage, and fever"}, {"id": "b", "text": "Sudden dyspnea and low SpO₂"}, {"id": "c", "text": "Inability to flush the catheter"}, {"id": "d", "text": "Arm pain and swelling without drainage"}]'::jsonb, '["a"]', 'Redness, drainage, swelling, and fever are signs of infection at a central line. Sudden dyspnea suggests pneumothorax or air embolism, and limb pain with swelling suggests thrombosis.'),
  ('central_picc', 24, 'A client with a PICC has redness at the insertion site. Which additional finding best indicates infection rather than thrombosis?', '[{"id": "a", "text": "Swelling of the arm"}, {"id": "b", "text": "Pain in the arm"}, {"id": "c", "text": "Drainage at the site"}, {"id": "d", "text": "Redness of the limb"}]'::jsonb, '["c"]', 'Drainage and fever are signs of infection, whereas swelling, pain, and redness in the limb are listed for thrombosis. Swelling, pain, and redness alone do not distinguish infection from thrombosis.'),
  ('central_picc', 25, 'The nurse suspects that a client''s central line lumen is occluded. Which action is appropriate?', '[{"id": "a", "text": "Remove the catheter at the bedside"}, {"id": "b", "text": "Leave the lumen unclamped between uses"}, {"id": "c", "text": "Place the client in left lateral Trendelenburg"}, {"id": "d", "text": "Flush with saline or heparin per protocol"}]'::jsonb, '["d"]', 'Catheter occlusion is managed by flushing with saline or heparin per protocol. Left lateral Trendelenburg is the position for air embolism.'),
  ('central_picc', 26, 'A nurse is preparing to give an intermittent medication through a client''s central line. Which action by the nurse requires correction?', '[{"id": "a", "text": "Accessing the hub without scrubbing it first"}, {"id": "b", "text": "Flushing the lumen according to protocol"}, {"id": "c", "text": "Checking the site for redness and drainage"}, {"id": "d", "text": "Clamping the lumen after the medication"}]'::jsonb, '["a"]', 'The hub must be scrubbed with an antiseptic cap or alcohol before access to prevent CLABSI. Flushing per protocol, assessing for infection, and clamping when not in use are appropriate.'),
  ('central_picc', 27, 'Before accessing the needleless connector on a client''s PICC, what should the nurse do?', '[{"id": "a", "text": "Flush the hub with heparin"}, {"id": "b", "text": "Clamp the line for one minute"}, {"id": "c", "text": "Scrub the hub with alcohol"}, {"id": "d", "text": "Remove the transparent dressing"}]'::jsonb, '["c"]', 'The hub is scrubbed with an antiseptic cap or alcohol before access. Removing the dressing is not part of accessing the line.'),
  ('central_picc', 28, 'The nurse is teaching a group of new graduates about central line care. Which pair of actions is the focus of CLABSI prevention?', '[{"id": "a", "text": "Daily chest X-rays and frequent flushing"}, {"id": "b", "text": "Sterile dressing changes and scrubbing the hub"}, {"id": "c", "text": "Clamping lumens and avoiding arm BP readings"}, {"id": "d", "text": "Left-side positioning and 100% oxygen"}]'::jsonb, '["b"]', 'CLABSI prevention consists of sterile dressing changes and scrubbing the hub. Left-side positioning and 100% oxygen are the response to air embolism.'),
  ('central_picc', 29, 'A client''s PICC has a clean, dry, intact transparent dressing. How often should the nurse plan to change this dressing?', '[{"id": "a", "text": "Every 24 hours"}, {"id": "b", "text": "Every 48 hours"}, {"id": "c", "text": "Every 72 hours"}, {"id": "d", "text": "Every 7 days"}]'::jsonb, '["d"]', 'Transparent dressings are changed every 7 days, or sooner if soiled. More frequent routine changes are not indicated for an intact dressing.'),
  ('central_picc', 30, 'A client''s central line transparent dressing was changed 3 days ago. The nurse now notes that the dressing is soiled. What should the nurse do?', '[{"id": "a", "text": "Leave it until the 7-day change"}, {"id": "b", "text": "Change it now using sterile technique"}, {"id": "c", "text": "Reinforce it with another dressing"}, {"id": "d", "text": "Change it now using clean technique"}]'::jsonb, '["b"]', 'Transparent dressings are changed every 7 days or sooner if soiled, and dressing changes require sterile technique. Clean technique or waiting until day 7 is incorrect.'),
  ('central_picc', 31, 'A client has a triple-lumen central line, with one lumen used for a continuous infusion and two lumens not in use. Which action is appropriate?', '[{"id": "a", "text": "Clamp all three lumens"}, {"id": "b", "text": "Leave all lumens unclamped"}, {"id": "c", "text": "Clamp only the infusing lumen"}, {"id": "d", "text": "Clamp the two unused lumens"}]'::jsonb, '["d"]', 'Lumens are clamped when not in use, unless a continuous infusion is running. The infusing lumen stays open, and unused lumens are clamped.'),
  ('central_picc', 32, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a client with a PICC in the left arm. Which UAP action requires correction?', '[{"id": "a", "text": "Taking a blood pressure on the left arm"}, {"id": "b", "text": "Taking a blood pressure on the right arm"}, {"id": "c", "text": "Reporting that the client has a fever"}, {"id": "d", "text": "Reporting drainage on the PICC dressing"}]'::jsonb, '["a"]', 'Blood pressure measurement must be avoided in the PICC arm. Reporting fever or drainage is appropriate because these are signs of infection.'),
  ('central_picc', 33, 'A phlebotomist plans to draw blood from a client who has a PICC in the right arm. Which instruction should the nurse give?', '[{"id": "a", "text": "Use the right arm below the PICC"}, {"id": "b", "text": "Use the right arm above the PICC"}, {"id": "c", "text": "Avoid venipuncture in the right arm"}, {"id": "d", "text": "Use whichever arm is easier to access"}]'::jsonb, '["c"]', 'Venipuncture is avoided in the arm with the PICC. The other options would place a puncture in the PICC arm.'),
  ('central_picc', 34, 'A client with a PICC in the left arm needs a peripheral IV for a short infusion. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Insert the IV in the left forearm"}, {"id": "b", "text": "Insert the IV in the left hand"}, {"id": "c", "text": "Insert the IV in the left antecubital area"}, {"id": "d", "text": "Insert the IV in the right arm"}]'::jsonb, '["d"]', 'No BP, no venipuncture, and no IV are placed in the PICC arm, so the IV belongs in the opposite arm. All other options use the PICC arm.'),
  ('central_picc', 35, 'A critically ill client requires central venous pressure (CVP) monitoring. Which device does the nurse anticipate for this purpose?', '[{"id": "a", "text": "A non-PICC central line"}, {"id": "b", "text": "A peripheral IV in the forearm"}, {"id": "c", "text": "A PICC for home antibiotics"}, {"id": "d", "text": "A PICC for outpatient chemotherapy"}]'::jsonb, '["a"]', 'Central lines are used for hemodynamic monitoring, including CVP, and for critically ill clients. PICCs are mainly used for long-term antibiotics, outpatient chemo, and TPN.'),
  ('central_picc', 36, 'A client in the ICU is in hemorrhagic shock and needs rapid administration of fluids and blood. Which access device does the nurse anticipate?', '[{"id": "a", "text": "A PICC for outpatient use"}, {"id": "b", "text": "A non-PICC central line"}, {"id": "c", "text": "A peripheral IV in the hand"}, {"id": "d", "text": "A PICC for poor peripheral access"}]'::jsonb, '["b"]', 'Non-PICC central lines are used for critically ill clients and rapid fluid or blood administration. PICCs are mainly used for long-term antibiotics, outpatient chemo, and TPN.'),
  ('central_picc', 37, 'A client is prescribed a vesicant medication that requires central access. Which statement about central lines supports this prescription?', '[{"id": "a", "text": "Central lines are used to give vesicant drugs"}, {"id": "b", "text": "Central lines are used only for blood draws"}, {"id": "c", "text": "Central lines are used only for short antibiotic courses"}, {"id": "d", "text": "Central lines are used mainly in outpatient clinics"}]'::jsonb, '["a"]', 'Central lines are used for long-term or high-volume infusion, vesicant drugs, TPN, and hemodynamic monitoring. The other statements are not supported uses.'),
  ('central_picc', 38, 'A client has had multiple failed peripheral IV attempts and will need IV therapy for several weeks. Which device is most appropriate?', '[{"id": "a", "text": "A femoral central line"}, {"id": "b", "text": "Another peripheral IV"}, {"id": "c", "text": "A PICC line"}, {"id": "d", "text": "A non-tunneled jugular line"}]'::jsonb, '["c"]', 'PICC lines are used for poor peripheral access and long-term therapy lasting weeks to months. Femoral and non-tunneled jugular lines are typically placed for critically ill clients.'),
  ('central_picc', 39, 'A client with cancer will receive chemotherapy as an outpatient over the next several months. Which device does the nurse anticipate?', '[{"id": "a", "text": "A PICC line"}, {"id": "b", "text": "A peripheral IV"}, {"id": "c", "text": "A non-tunneled femoral line"}, {"id": "d", "text": "A non-tunneled jugular line"}]'::jsonb, '["a"]', 'PICC lines are used for outpatient chemotherapy and TPN and last weeks to months. Non-tunneled central lines are generally used for days to weeks.'),
  ('central_picc', 40, 'The nurse teaches a client about a newly placed PICC. Which statement by the client indicates understanding of how long it may remain in place?', '[{"id": "a", "text": "\"It can stay in for only a few hours.\""}, {"id": "b", "text": "\"It can stay in for weeks to months.\""}, {"id": "c", "text": "\"It can stay in for many years.\""}, {"id": "d", "text": "\"It must come out within 2 days.\""}]'::jsonb, '["b"]', 'PICC lines remain in place for weeks to months. Months to years describes tunneled central lines.'),
  ('central_picc', 41, 'Which characteristic is shared by a PICC and a non-PICC central venous catheter?', '[{"id": "a", "text": "Insertion into an upper-arm vein"}, {"id": "b", "text": "Removal by surgery when no longer needed"}, {"id": "c", "text": "Tip location in the SVC near the right atrium"}, {"id": "d", "text": "Higher risk of pneumothorax after insertion"}]'::jsonb, '["c"]', 'Both devices have the tip in the superior vena cava near the right atrium. Upper-arm insertion is specific to PICCs, and a higher pneumothorax risk applies to subclavian or jugular central lines.'),
  ('central_picc', 42, 'The nurse is using the C.L.E.A.N. approach for central access care. Which action corresponds to the letter "E"?', '[{"id": "a", "text": "Exchange the tubing every 24 hours"}, {"id": "b", "text": "Elevate the arm with the PICC"}, {"id": "c", "text": "Evaluate the site for infection"}, {"id": "d", "text": "Educate the client about flushing"}]'::jsonb, '["c"]', 'In C.L.E.A.N., "E" stands for evaluating the site for infection. The other letters stand for confirming placement, flushing the lumen per protocol, aseptic technique, and never using the line until placement is verified.'),
  ('central_picc', 43, 'The nurse is performing routine maintenance on a client''s PICC. Which solution should the nurse use to flush the line?', '[{"id": "a", "text": "Sterile water as needed"}, {"id": "b", "text": "Alcohol solution per protocol"}, {"id": "c", "text": "Dextrose 5% in water"}, {"id": "d", "text": "Saline or saline + heparin per protocol"}]'::jsonb, '["d"]', 'Central lines are flushed per protocol with saline or saline plus heparin. Alcohol is used to scrub the hub, not to flush the line.'),
  ('central_picc', 44, 'A client''s record documents a Broviac catheter that is no longer needed. How does the nurse anticipate the catheter will be removed?', '[{"id": "a", "text": "At the bedside by a trained RN"}, {"id": "b", "text": "At the bedside by the client''s UAP"}, {"id": "c", "text": "Surgically by the provider"}, {"id": "d", "text": "At home by the client"}]'::jsonb, '["c"]', 'A Broviac catheter is a tunneled central line, and central lines are removed by the provider, with surgical removal for tunneled lines. Bedside removal by a trained RN applies to PICCs when protocol allows.'),
  ('central_picc', 45, 'The nurse is changing the dressing on a client''s subclavian central line. Which technique should the nurse use?', '[{"id": "a", "text": "Clean technique with nonsterile gloves"}, {"id": "b", "text": "Strict sterile technique"}, {"id": "c", "text": "Clean technique with hand hygiene"}, {"id": "d", "text": "No-touch clean technique"}]'::jsonb, '["b"]', 'Strict sterile technique is required for central line dressing changes and access to prevent CLABSI. Clean technique does not meet this standard.'),
  ('central_picc', 46, 'A client has a central line in place. In addition to site redness and drainage, which finding should the nurse report as a possible sign of infection?', '[{"id": "a", "text": "Fever"}, {"id": "b", "text": "Clamped lumens that are not in use"}, {"id": "c", "text": "A recent saline flush per protocol"}, {"id": "d", "text": "A dressing dated 4 days ago"}]'::jsonb, '["a"]', 'Signs of infection include redness, drainage, swelling, and fever. Clamping unused lumens and flushing per protocol are routine care, and a transparent dressing dated 4 days ago is within the 7-day change interval.'),
  ('central_picc', 47, 'A client asks why a PICC is being placed instead of a line in the neck or chest. The nurse explains that the main differences between the devices are:', '[{"id": "a", "text": "tip location and catheter material"}, {"id": "b", "text": "insertion site and duration"}, {"id": "c", "text": "infusion type and tip location"}, {"id": "d", "text": "flushing solution and tip location"}]'::jsonb, '["b"]', 'Both devices are central access devices with tips in the central circulation; they differ in insertion site and duration. Tip location is the same for both.'),
  ('central_picc', 48, 'The nurse is reviewing types of central venous access devices. Which device belongs to its own category separate from tunneled, non-tunneled, and implanted central lines?', '[{"id": "a", "text": "Hickman catheter"}, {"id": "b", "text": "Broviac catheter"}, {"id": "c", "text": "Implanted port"}, {"id": "d", "text": "PICC line"}]'::jsonb, '["d"]', 'A PICC is its own category, whereas Hickman and Broviac catheters are tunneled lines and the implanted port is another special type of central line.'),
  ('central_picc', 49, 'A client has a central line that is used only for an antibiotic dose every 8 hours. Which action by the nurse requires correction?', '[{"id": "a", "text": "Scrubbing the hub before each dose"}, {"id": "b", "text": "Leaving the line unclamped between doses"}, {"id": "c", "text": "Flushing the line per protocol"}, {"id": "d", "text": "Checking the site for redness and drainage"}]'::jsonb, '["b"]', 'The line should be clamped when not in use unless a continuous infusion is running. Scrubbing the hub, flushing per protocol, and assessing for infection are appropriate.'),
  ('central_picc', 50, 'A client in the ICU asks how long a newly placed non-tunneled jugular central line usually stays in. The nurse explains that a non-tunneled central line is typically used for:', '[{"id": "a", "text": "days to weeks"}, {"id": "b", "text": "several years"}, {"id": "c", "text": "months to years"}, {"id": "d", "text": "only a few hours"}]'::jsonb, '["a"]', 'Central lines are used short to long term, with non-tunneled lines in place for days to weeks and tunneled lines for months to years.'),
  ('colonoscopy', 1, 'A 45-year-old client at average risk for colorectal cancer asks when routine colonoscopy screening should begin. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Screening begins at age 50.\""}, {"id": "b", "text": "\"Screening begins at age 45.\""}, {"id": "c", "text": "\"Screening begins at age 60.\""}, {"id": "d", "text": "\"Screening begins at age 40.\""}]'::jsonb, '["b"]', 'Routine colorectal cancer screening by colonoscopy starts at age 45 for clients at average risk. The other ages do not match this guideline.'),
  ('colonoscopy', 2, 'An average-risk client had a normal screening colonoscopy at age 45. At what age should the nurse expect the next routine screening colonoscopy?', '[{"id": "a", "text": "46"}, {"id": "b", "text": "50"}, {"id": "c", "text": "55"}, {"id": "d", "text": "65"}]'::jsonb, '["c"]', 'For average-risk clients, screening colonoscopy is repeated every 10 years, so the next one would be at age 55. Annual or 5-year intervals are not the stated schedule.'),
  ('colonoscopy', 3, 'The nurse teaches an average-risk client about colorectal cancer screening. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I should have my first colonoscopy at age 45.\""}, {"id": "b", "text": "\"A colonoscopy screens for colorectal cancer.\""}, {"id": "c", "text": "\"A polyp can be removed during the procedure.\""}, {"id": "d", "text": "\"I will need a colonoscopy every year after 45.\""}]'::jsonb, '["d"]', 'Average-risk screening starts at age 45 and is repeated every 10 years, not yearly. Screening for colorectal cancer and polyp removal are correct uses of colonoscopy.'),
  ('colonoscopy', 4, 'A client scheduled for a colonoscopy asks what the procedure involves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"A flexible scope is passed through the rectum to view the colon.\""}, {"id": "b", "text": "\"A flexible scope is passed through the mouth to view the colon.\""}, {"id": "c", "text": "\"A flexible scope is passed through the rectum to view the stomach.\""}, {"id": "d", "text": "\"A rigid scope is passed through the mouth to view the esophagus.\""}]'::jsonb, '["a"]', 'A colonoscope is a long, flexible fiber-optic scope inserted through the rectum to examine the inner lining of the colon. It is not passed through the mouth and does not examine the stomach.'),
  ('colonoscopy', 5, 'A client with a polyp seen on imaging asks whether another procedure will be needed to remove it after the colonoscopy. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A colonoscopy can only view the colon, not remove polyps.\""}, {"id": "b", "text": "\"Polyps can be removed during the colonoscopy itself.\""}, {"id": "c", "text": "\"Polyps must be removed later during open surgery.\""}, {"id": "d", "text": "\"A colonoscopy can only take pictures of the rectum.\""}]'::jsonb, '["b"]', 'Colonoscopy is both diagnostic and therapeutic, allowing direct visualization, biopsy, and polyp removal. It is not limited to viewing the colon or rectum.'),
  ('colonoscopy', 6, 'The nurse is reviewing the records of four clients. Which client has an indication for a colonoscopy now rather than at routine screening?', '[{"id": "a", "text": "A 35-year-old with unexplained GI bleeding"}, {"id": "b", "text": "A 35-year-old at average risk with no symptoms"}, {"id": "c", "text": "A 40-year-old at average risk with no symptoms"}, {"id": "d", "text": "A 52-year-old with a normal colonoscopy at 47"}]'::jsonb, '["a"]', 'Unexplained GI bleeding is an indication for colonoscopy at any age. Average-risk screening starts at age 45 and repeats every 10 years, so the other clients are not yet due.'),
  ('colonoscopy', 7, 'A 38-year-old client reports several months of persistent changes in bowel habits. The provider schedules a colonoscopy. The client asks why, since screening normally starts later. The nurse explains that the colonoscopy is indicated because of:', '[{"id": "a", "text": "the client''s age"}, {"id": "b", "text": "a routine 10-year interval"}, {"id": "c", "text": "the persistent bowel changes"}, {"id": "d", "text": "a need for gastric decompression"}]'::jsonb, '["c"]', 'Persistent changes in bowel habits are an indication for colonoscopy regardless of screening age. Routine screening starts at age 45 for average-risk clients, so age is not the reason here.'),
  ('colonoscopy', 8, 'A client with ulcerative colitis is scheduled for a colonoscopy. The nurse recognizes this indication as related to which category?', '[{"id": "a", "text": "Routine average-risk screening"}, {"id": "b", "text": "Inflammatory bowel disease"}, {"id": "c", "text": "Bowel obstruction relief"}, {"id": "d", "text": "Phosphate nephropathy"}]'::jsonb, '["b"]', 'Inflammatory bowel disease, including ulcerative colitis and Crohn''s disease, is an indication for colonoscopy. Bowel obstruction is a contraindication to PEG bowel prep, not a colonoscopy indication.'),
  ('colonoscopy', 9, 'A client asks what to eat the day before a colonoscopy. Which instruction by the nurse is correct?', '[{"id": "a", "text": "\"Eat a low-fiber diet until bedtime.\""}, {"id": "b", "text": "\"Eat regular meals until midnight.\""}, {"id": "c", "text": "\"Drink only clear liquids for 24 hours.\""}, {"id": "d", "text": "\"Eat a light dinner, then begin fasting.\""}]'::jsonb, '["c"]', 'Bowel preparation includes a clear liquid diet for 24 hours before the procedure, followed by NPO after midnight. Regular or light meals the day before do not follow the prep.'),
  ('colonoscopy', 10, 'A client is scheduled for a colonoscopy at 9:00 a.m. Which instruction about oral intake is correct for the night before?', '[{"id": "a", "text": "Stop clear liquids 2 hours before the procedure"}, {"id": "b", "text": "Remain NPO after midnight"}, {"id": "c", "text": "Eat a small solid snack at bedtime"}, {"id": "d", "text": "Drink clear liquids until the morning"}]'::jsonb, '["b"]', 'The client follows a clear liquid diet for 24 hours and then remains NPO after midnight. Continuing liquids until morning or eating a snack does not follow the prep instructions.'),
  ('colonoscopy', 11, 'The nurse reviews bowel preparation instructions with a client. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will drink only clear liquids the day before.\""}, {"id": "b", "text": "\"I will not eat or drink after midnight.\""}, {"id": "c", "text": "\"I will stay close to a toilet once I start the prep.\""}, {"id": "d", "text": "\"I will eat a light breakfast the morning of the test.\""}]'::jsonb, '["d"]', 'Clients are NPO after midnight before colonoscopy, so eating breakfast the morning of the procedure is incorrect. Clear liquids for 24 hours and staying near a toilet after starting prep are correct.'),
  ('colonoscopy', 12, 'A client plans to start the colonoscopy bowel prep and then go to a long meeting. Which instruction should the nurse emphasize?', '[{"id": "a", "text": "\"Stay near a toilet after starting the prep.\""}, {"id": "b", "text": "\"Take the prep after the meeting at midnight.\""}, {"id": "c", "text": "\"Stop the prep once the first stool is passed.\""}, {"id": "d", "text": "\"Take half the prep to avoid needing a toilet.\""}]'::jsonb, '["a"]', 'Clients are taught to stay near a toilet after starting the prep and to complete it for clear visualization. Stopping early or taking only half the prep interferes with adequate bowel cleansing.'),
  ('colonoscopy', 13, 'A client taking colonoscopy bowel prep calls to say the stools are still brown and the client wants to stop because of bloating. What should the nurse tell the client?', '[{"id": "a", "text": "\"You can stop now; brown stool shows the prep worked.\""}, {"id": "b", "text": "\"Stop the prep and eat a small meal for the bloating.\""}, {"id": "c", "text": "\"Stop the prep and take it again after the procedure.\""}, {"id": "d", "text": "\"Continue the prep until your stool is clear or yellow liquid.\""}]'::jsonb, '["d"]', 'Completing the bowel prep is essential for clear visualization, and prep continues until stool is clear or yellow liquid. Brown stool indicates the prep is not yet adequate.'),
  ('colonoscopy', 14, 'The nurse is evaluating a client''s response to colonoscopy bowel preparation. Which finding indicates the prep is adequate?', '[{"id": "a", "text": "Formed brown stool"}, {"id": "b", "text": "Clear yellow liquid stool"}, {"id": "c", "text": "Soft brown stool with particles"}, {"id": "d", "text": "No stool since starting prep"}]'::jsonb, '["b"]', 'Stool that is clear or yellow liquid confirms adequate prep. Brown stool or stool with particles shows the colon is not yet clean.'),
  ('colonoscopy', 15, 'A client asks why it matters so much to finish the entire bowel prep before a colonoscopy. Which response by the nurse is best?', '[{"id": "a", "text": "\"The prep allows clear visualization of the colon.\""}, {"id": "b", "text": "\"The prep prevents cramping after the procedure.\""}, {"id": "c", "text": "\"The prep replaces the need for sedation.\""}, {"id": "d", "text": "\"The prep protects the kidneys during the test.\""}]'::jsonb, '["a"]', 'Completing the bowel prep is important for clear visualization and is essential for test accuracy. Cramping and gas can still occur after the procedure.'),
  ('colonoscopy', 16, 'Before a colonoscopy, a client asks the nurse detailed questions about the risks of the procedure while the consent form is being signed. What is the nurse''s role?', '[{"id": "a", "text": "Explain the risks and benefits of the procedure"}, {"id": "b", "text": "Witness the client signing the informed consent"}, {"id": "c", "text": "Describe each step of the procedure in detail"}, {"id": "d", "text": "Answer the questions and then sign for the client"}]'::jsonb, '["b"]', 'The nurse ensures informed consent is signed and witnesses the signature but does not explain the procedure. Explaining the procedure or its risks is outside the nurse''s consent role.'),
  ('colonoscopy', 17, 'A charge nurse observes a nurse preparing a client for colonoscopy. Which action by the nurse requires correction?', '[{"id": "a", "text": "Witnessing the client''s consent signature"}, {"id": "b", "text": "Reviewing renal labs before a magnesium prep"}, {"id": "c", "text": "Explaining the procedure to obtain consent"}, {"id": "d", "text": "Teaching the client to stay near a toilet"}]'::jsonb, '["c"]', 'The nurse witnesses informed consent but does not explain the procedure. Reviewing renal function before magnesium-based preps and teaching the client to stay near a toilet are appropriate.'),
  ('colonoscopy', 18, 'A client is prescribed magnesium citrate as bowel preparation for a colonoscopy. Which laboratory values should the nurse review before the client begins the prep?', '[{"id": "a", "text": "Hemoglobin and hematocrit"}, {"id": "b", "text": "Liver function tests"}, {"id": "c", "text": "Blood glucose levels"}, {"id": "d", "text": "BUN and creatinine"}]'::jsonb, '["d"]', 'Renal function (BUN and creatinine) is reviewed if phosphate- or magnesium-based preps are used. Magnesium citrate carries a risk of hypermagnesemia in renal disease.'),
  ('colonoscopy', 19, 'A 78-year-old client with heart failure is scheduled for a colonoscopy. Which bowel preparation prescription should the nurse question?', '[{"id": "a", "text": "Polyethylene glycol solution"}, {"id": "b", "text": "Bisacodyl the night before"}, {"id": "c", "text": "Sodium phosphate solution"}, {"id": "d", "text": "Simethicone added to PEG"}]'::jsonb, '["c"]', 'Sodium phosphate is avoided in elderly clients and those with renal disease or heart failure. PEG, bisacodyl, and simethicone are not restricted for these reasons.'),
  ('colonoscopy', 20, 'A nursing student asks why sodium phosphate (Fleet Phospho-Soda) is rarely used for colonoscopy prep today. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It carries a risk of phosphate nephropathy.\""}, {"id": "b", "text": "\"It causes too many bubbles in the colon.\""}, {"id": "c", "text": "\"It works too slowly to empty the bowel.\""}, {"id": "d", "text": "\"It is a stimulant that causes cramping.\""}]'::jsonb, '["a"]', 'Sodium phosphate is rarely used now because of the risk of phosphate nephropathy. It is an osmotic agent that empties the bowel rapidly, not a slow or stimulant laxative.'),
  ('colonoscopy', 21, 'A client with chronic renal disease is prescribed magnesium citrate for colonoscopy prep. The nurse should monitor for which complication?', '[{"id": "a", "text": "Hypoglycemia"}, {"id": "b", "text": "Hypermagnesemia"}, {"id": "c", "text": "Bowel perforation"}, {"id": "d", "text": "Fluid overload"}]'::jsonb, '["b"]', 'Magnesium citrate carries a risk of hypermagnesemia in clients with renal disease. Perforation is a complication of the colonoscopy itself, not of the prep.'),
  ('colonoscopy', 22, 'A client asks how polyethylene glycol (GoLYTELY) cleans out the bowel. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It draws water into the colon.\""}, {"id": "b", "text": "\"It increases bowel muscle movement.\""}, {"id": "c", "text": "\"It reduces bubbles in the colon.\""}, {"id": "d", "text": "\"It coats and protects the colon.\""}]'::jsonb, '["a"]', 'PEG is an osmotic laxative that draws water into the colon. Increasing bowel motility describes bisacodyl, and reducing bubbles describes simethicone.'),
  ('colonoscopy', 23, 'The nurse reviews the history of a client prescribed polyethylene glycol (PEG) bowel prep. Which finding should prompt the nurse to contact the provider before the client starts the prep?', '[{"id": "a", "text": "A history of nausea with large fluid volumes"}, {"id": "b", "text": "A current bowel obstruction"}, {"id": "c", "text": "A plan to take bisacodyl the night before"}, {"id": "d", "text": "A plan to add simethicone to the PEG"}]'::jsonb, '["b"]', 'PEG is contraindicated in bowel obstruction. Nausea is a possible side effect, and bisacodyl and simethicone are often combined with or added to PEG.'),
  ('colonoscopy', 24, 'The nurse is teaching a client how to take polyethylene glycol (PEG) bowel prep. Which instruction is correct?', '[{"id": "a", "text": "\"Drink 2–4 L of solution over several hours.\""}, {"id": "b", "text": "\"Drink 250 mL of solution all at once.\""}, {"id": "c", "text": "\"Drink 2–4 L of solution within 10 minutes.\""}, {"id": "d", "text": "\"Drink 500 mL of solution over 1 week.\""}]'::jsonb, '["a"]', 'PEG is taken as 2–4 L over several hours. The other volumes and time frames do not match this regimen.'),
  ('colonoscopy', 25, 'A client drinking polyethylene glycol (PEG) prep reports nausea and a bloated feeling. Which nursing consideration applies to this prep?', '[{"id": "a", "text": "Stop the prep and restrict fluids"}, {"id": "b", "text": "Recognize nausea as a sign of perforation"}, {"id": "c", "text": "Switch to sodium phosphate for comfort"}, {"id": "d", "text": "Expect these effects and ensure hydration"}]'::jsonb, '["d"]', 'PEG can cause nausea and bloating, and hydration should be ensured. Restricting fluids is incorrect, and sodium phosphate is rarely used because of nephropathy risk.'),
  ('colonoscopy', 26, 'A client is prescribed bisacodyl (Dulcolax) as part of colonoscopy prep. Which information should the nurse include in teaching?', '[{"id": "a", "text": "\"Take it the night before; it may cause cramping.\""}, {"id": "b", "text": "\"Take it after the test; it may reduce bloating.\""}, {"id": "c", "text": "\"Take it the morning after; it may cause bubbles.\""}, {"id": "d", "text": "\"Take it with dinner; it may cause hypermagnesemia.\""}]'::jsonb, '["a"]', 'Bisacodyl is a stimulant given the night before the procedure and can cause cramping. Hypermagnesemia is a risk of magnesium citrate, not bisacodyl.'),
  ('colonoscopy', 27, 'A nursing student asks how bisacodyl (Dulcolax) works as part of a colonoscopy prep. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It draws water into the colon.\""}, {"id": "b", "text": "\"It reduces bubbles in the colon.\""}, {"id": "c", "text": "\"It flushes the bowel with saline.\""}, {"id": "d", "text": "\"It increases bowel motility.\""}]'::jsonb, '["d"]', 'Bisacodyl is a stimulant laxative that increases bowel motility and is often combined with PEG. Drawing water into the colon describes PEG, and reducing bubbles describes simethicone.'),
  ('colonoscopy', 28, 'A client asks why simethicone has been added to the polyethylene glycol prep solution. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It speeds up bowel emptying.\""}, {"id": "b", "text": "\"It reduces bubbles to improve visibility.\""}, {"id": "c", "text": "\"It prevents kidney problems from the prep.\""}, {"id": "d", "text": "\"It stimulates the bowel muscles to move.\""}]'::jsonb, '["b"]', 'Simethicone is an antifoaming agent that reduces bubbles, improves visibility, and reduces gas and bloating. Stimulating bowel movement describes bisacodyl.'),
  ('colonoscopy', 29, 'The nurse is comparing bowel prep agents for a colonoscopy. Which agent is classified as an antifoaming agent?', '[{"id": "a", "text": "Bisacodyl"}, {"id": "b", "text": "Magnesium citrate"}, {"id": "c", "text": "Polyethylene glycol"}, {"id": "d", "text": "Simethicone"}]'::jsonb, '["d"]', 'Simethicone is an antifoaming agent that reduces bubbles. Bisacodyl is a stimulant, magnesium citrate is a saline laxative, and PEG is an osmotic laxative.'),
  ('colonoscopy', 30, 'The nurse is preparing a client for colonoscopy with sedation. Which medication does the nurse anticipate the provider will use for sedation?', '[{"id": "a", "text": "Bisacodyl"}, {"id": "b", "text": "Simethicone"}, {"id": "c", "text": "Midazolam"}, {"id": "d", "text": "Magnesium citrate"}]'::jsonb, '["c"]', 'Sedation for colonoscopy uses midazolam or propofol. Bisacodyl, simethicone, and magnesium citrate are bowel prep agents.'),
  ('colonoscopy', 31, 'The nurse is positioning a client for a colonoscopy. Which position is correct?', '[{"id": "a", "text": "Right side-lying"}, {"id": "b", "text": "Supine with knees flexed"}, {"id": "c", "text": "Prone with arms at sides"}, {"id": "d", "text": "Left side-lying (Sims'')"}]'::jsonb, '["d"]', 'The client is placed in the left side-lying (Sims'') position during colonoscopy. Right side-lying, supine, and prone positions are not used.'),
  ('colonoscopy', 32, 'A client has received sedation and is undergoing a colonoscopy. Which monitoring should the nurse perform during the procedure?', '[{"id": "a", "text": "Blood glucose every 4 hours"}, {"id": "b", "text": "Continuous HR, BP, RR, and SpO₂"}, {"id": "c", "text": "Neurologic checks every 2 hours"}, {"id": "d", "text": "Intake and output every 8 hours"}]'::jsonb, '["b"]', 'Continuous monitoring of HR, BP, RR, and SpO₂ is required during colonoscopy. Intermittent glucose, neurologic, or intake and output checks are not the stated monitoring.'),
  ('colonoscopy', 33, 'A client who received sedation for a colonoscopy is ready for discharge and states, "My car is in the parking lot, so I''ll drive myself home." What is the nurse''s priority action?', '[{"id": "a", "text": "Allow the client to drive if vital signs are stable"}, {"id": "b", "text": "Have the client wait 1 hour and then drive home"}, {"id": "c", "text": "Arrange a ride home and teach no driving for 24 hours"}, {"id": "d", "text": "Allow the client to drive if the trip is a short one"}]'::jsonb, '["c"]', 'If sedation is used, the client must have a ride home and must not drive for 24 hours. Stable vital signs, a short wait, or a short trip do not change this requirement.'),
  ('colonoscopy', 34, 'The nurse provides discharge teaching to a client who received sedation for a colonoscopy this morning. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My daughter is driving me home today.\""}, {"id": "b", "text": "\"I can drive myself to work this afternoon.\""}, {"id": "c", "text": "\"I can expect some gas and mild cramping.\""}, {"id": "d", "text": "\"I will call if I develop fever or chills.\""}]'::jsonb, '["b"]', 'After sedation, the client must not drive for 24 hours. Having a ride home, expecting gas and cramping, and reporting fever or chills are correct.'),
  ('colonoscopy', 35, 'A client is alert and has no complications after a colonoscopy. Which diet instruction should the nurse give?', '[{"id": "a", "text": "\"Stay on clear liquids for 24 hours.\""}, {"id": "b", "text": "\"Remain NPO until tomorrow morning.\""}, {"id": "c", "text": "\"Resume your diet as tolerated.\""}, {"id": "d", "text": "\"Take only full liquids for 3 days.\""}]'::jsonb, '["c"]', 'After colonoscopy, the client resumes the diet as tolerated. Clear liquids and NPO status are part of the pre-procedure bowel prep.'),
  ('colonoscopy', 36, 'A client reports feeling bloated after a colonoscopy. Which action should the nurse encourage?', '[{"id": "a", "text": "Passing gas to relieve the bloating"}, {"id": "b", "text": "Remaining NPO for 24 hours"}, {"id": "c", "text": "Lying flat on the back without moving"}, {"id": "d", "text": "Taking another dose of bowel prep"}]'::jsonb, '["a"]', 'After colonoscopy, the nurse encourages passing gas to relieve bloating. Remaining NPO is not required because the diet is resumed as tolerated.'),
  ('colonoscopy', 37, 'Thirty minutes after an uncomplicated colonoscopy, a client reports mild cramping and gas. Vital signs are stable, and the abdomen is soft. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "Notify the provider of possible perforation"}, {"id": "b", "text": "Prepare the client for emergency surgery"}, {"id": "c", "text": "Explain this is expected and encourage passing gas"}, {"id": "d", "text": "Keep the client NPO and start an IV bolus"}]'::jsonb, '["c"]', 'Clients are taught to expect possible cramping and gas after the procedure, and passing gas is encouraged to relieve bloating. Perforation presents with sudden severe pain and rigidity, which are absent here.'),
  ('colonoscopy', 38, 'Two hours after a colonoscopy, a client reports sudden severe abdominal pain. The nurse finds a rigid abdomen, fever, and tachycardia. Which complication should the nurse suspect?', '[{"id": "a", "text": "Expected post-procedure gas"}, {"id": "b", "text": "Bowel perforation"}, {"id": "c", "text": "Bleeding after biopsy"}, {"id": "d", "text": "Reaction to the bowel prep"}]'::jsonb, '["b"]', 'Sudden severe abdominal pain, rigidity, fever, and tachycardia are signs of perforation. Expected gas causes mild discomfort, not rigidity or tachycardia.'),
  ('colonoscopy', 39, 'The nurse is caring for four clients after colonoscopy. Which client should the nurse assess first?', '[{"id": "a", "text": "A client who reports bloating and is passing gas"}, {"id": "b", "text": "A client with a small streak of blood after a biopsy"}, {"id": "c", "text": "A client asking when the diet can be resumed"}, {"id": "d", "text": "A client with sudden severe pain and a rigid abdomen"}]'::jsonb, '["d"]', 'Sudden severe pain with abdominal rigidity indicates possible perforation, the priority complication after colonoscopy. A small amount of bleeding after biopsy and bloating with gas are expected.'),
  ('colonoscopy', 40, 'A client who had a biopsy during a colonoscopy notices a small amount of blood with the first bowel movement afterward. Vital signs are stable. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is expected after a biopsy"}, {"id": "b", "text": "It indicates bowel perforation"}, {"id": "c", "text": "It requires emergency surgery"}, {"id": "d", "text": "It indicates a bowel infection"}]'::jsonb, '["a"]', 'Small amounts of rectal bleeding are normal if a biopsy was taken. Excessive rectal bleeding is the complication of concern, and perforation presents with sudden severe pain and rigidity.'),
  ('colonoscopy', 41, 'The nurse is reviewing discharge instructions after a colonoscopy. Which finding should the client be taught to report?', '[{"id": "a", "text": "Passing gas several times"}, {"id": "b", "text": "Mild bloating after eating"}, {"id": "c", "text": "Bright red blood in the stool"}, {"id": "d", "text": "Mild cramping after the test"}]'::jsonb, '["c"]', 'Bright red blood in the stool is a red flag to report. Gas, mild bloating, and mild cramping are expected after colonoscopy.'),
  ('colonoscopy', 42, 'A client calls the clinic the day after a colonoscopy and reports fever and chills. The nurse recognizes these findings as signs of which complication?', '[{"id": "a", "text": "Infection"}, {"id": "b", "text": "Expected gas"}, {"id": "c", "text": "Sedation effects"}, {"id": "d", "text": "Normal biopsy bleeding"}]'::jsonb, '["a"]', 'Fever and chills are signs of infection after colonoscopy and are red flags to report. Gas and small amounts of bleeding after biopsy are expected findings.'),
  ('colonoscopy', 43, 'After a colonoscopy, a client stands to get dressed and reports feeling dizzy. The blood pressure is lower than the pre-procedure reading. What should the nurse do?', '[{"id": "a", "text": "Encourage the client to pass gas"}, {"id": "b", "text": "Resume the client''s diet as tolerated"}, {"id": "c", "text": "Treat this as a red flag and report it"}, {"id": "d", "text": "Discharge the client with a driver"}]'::jsonb, '["c"]', 'Dizziness or signs of hypotension are red flags to report after colonoscopy. Passing gas relieves bloating and does not address these findings.'),
  ('colonoscopy', 44, 'The nurse teaches a client about warning signs after a colonoscopy. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I will call if I pass a lot of gas.\""}, {"id": "b", "text": "\"I will call if I have severe abdominal pain.\""}, {"id": "c", "text": "\"I will call if I feel mildly bloated.\""}, {"id": "d", "text": "\"I will call if I am hungry tonight.\""}]'::jsonb, '["b"]', 'Severe abdominal pain or cramping is a red flag to report. Passing gas, mild bloating, and hunger are expected as the diet is resumed and gas is passed.'),
  ('colonoscopy', 45, 'A nursing student asks how magnesium citrate prepares the bowel for a colonoscopy. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a stimulant that increases motility.\""}, {"id": "b", "text": "\"It is an antifoaming agent for bubbles.\""}, {"id": "c", "text": "\"It is a saline laxative that flushes the bowel.\""}, {"id": "d", "text": "\"It is a sedative given before the test.\""}]'::jsonb, '["c"]', 'Magnesium citrate is a potent saline laxative that flushes the bowel. Stimulating motility describes bisacodyl, and reducing bubbles describes simethicone.'),
  ('colonoscopy', 46, 'A client with impaired kidney function is scheduled for a colonoscopy. Which bowel prep agents require the nurse to review renal function before the client begins?', '[{"id": "a", "text": "Bisacodyl and simethicone"}, {"id": "b", "text": "Simethicone and polyethylene glycol"}, {"id": "c", "text": "Polyethylene glycol and bisacodyl"}, {"id": "d", "text": "Sodium phosphate and magnesium citrate"}]'::jsonb, '["d"]', 'Renal function (BUN and creatinine) is reviewed when phosphate- or magnesium-based preps are used. Sodium phosphate carries a risk of phosphate nephropathy, and magnesium citrate carries a risk of hypermagnesemia in renal disease.'),
  ('colonoscopy', 47, 'A client is prescribed both bisacodyl and polyethylene glycol (PEG) before a colonoscopy and asks whether taking both is an error. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, the two should never be taken together.\""}, {"id": "b", "text": "\"Yes, bisacodyl replaces the PEG entirely.\""}, {"id": "c", "text": "\"No, bisacodyl is often combined with PEG.\""}, {"id": "d", "text": "\"No, but take the bisacodyl after the test.\""}]'::jsonb, '["c"]', 'Bisacodyl is given the night before and is often combined with PEG. It does not replace PEG and is not taken after the procedure.'),
  ('colonoscopy', 48, 'A client asks whether the colonoscopy can be used to obtain tissue from a suspicious area. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, a biopsy can be taken during the procedure.\""}, {"id": "b", "text": "\"No, the scope can only take pictures.\""}, {"id": "c", "text": "\"No, tissue is taken through the mouth instead.\""}, {"id": "d", "text": "\"No, a biopsy requires a separate surgery.\""}]'::jsonb, '["a"]', 'Biopsy of suspicious lesions is an indication for colonoscopy, which allows direct visualization, biopsy, and polyp removal. It is not limited to taking pictures.'),
  ('colonoscopy', 49, 'A client asks why simethicone is sometimes included in a bowel prep regimen. Besides improving the view of the colon, the nurse explains that it also helps to:', '[{"id": "a", "text": "increase bowel motility"}, {"id": "b", "text": "flush the bowel with saline"}, {"id": "c", "text": "speed rapid bowel emptying"}, {"id": "d", "text": "reduce gas and bloating"}]'::jsonb, '["d"]', 'Simethicone reduces bubbles, improves visibility, and reduces gas and bloating. Increasing motility describes bisacodyl, and flushing the bowel describes magnesium citrate.'),
  ('colonoscopy', 50, 'The nurse is reviewing post-colonoscopy findings for a client who had no biopsy taken. Which finding is expected and does not need to be reported?', '[{"id": "a", "text": "Mild gas and cramping"}, {"id": "b", "text": "Fever and chills"}, {"id": "c", "text": "Dizziness on standing"}, {"id": "d", "text": "Bright red blood in stool"}]'::jsonb, '["a"]', 'Clients are told to expect possible cramping and gas after the procedure. Fever and chills, dizziness, and bright red blood in the stool are red flags to report.'),
  ('colostomy', 1, 'A client is 1 day post-op after creation of a sigmoid colostomy. Which stoma appearance should the nurse document as an expected finding?', '[{"id": "a", "text": "Dusky purple and moist"}, {"id": "b", "text": "Pink-red and moist"}, {"id": "c", "text": "Pale and moist"}, {"id": "d", "text": "Black at the edges"}]'::jsonb, '["b"]', 'A normal stoma is pink/red and moist, showing it is well perfused. Pale, dusky, purple, or black color signals ischemia or necrosis and is abnormal.'),
  ('colostomy', 2, 'While changing a colostomy pouch, the nurse notes that the client''s stoma has turned black. Which action should the nurse take first?', '[{"id": "a", "text": "Document the finding and reassess at the next pouch change"}, {"id": "b", "text": "Clean the stoma with warm water and apply a new pouch"}, {"id": "c", "text": "Cut a new wafer one-eighth inch larger than the stoma"}, {"id": "d", "text": "Notify the health care provider immediately"}]'::jsonb, '["d"]', 'A black, necrotic stoma reflects poor perfusion and is an emergency requiring immediate notification of the HCP. Routine pouch care or delayed reassessment postpones needed treatment.'),
  ('colostomy', 3, 'The nurse is assessing four clients with colostomies. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "A small amount of bleeding when the stoma is touched"}, {"id": "b", "text": "A mild odor when the pouch is emptied"}, {"id": "c", "text": "Continuous bleeding from the stoma"}, {"id": "d", "text": "Some gas collecting in the pouch"}]'::jsonb, '["c"]', 'Continuous or heavy bleeding from a stoma is abnormal. A small amount of bleeding when the stoma is touched, mild odor, and some gas are normal findings.'),
  ('colostomy', 4, 'A client is 3 days post-op after a transverse colostomy and has had no stool output from the stoma yet. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is within the expected time frame for stoma function"}, {"id": "b", "text": "It indicates a bowel obstruction requiring emergency care"}, {"id": "c", "text": "It indicates ischemia of the stoma tissue"}, {"id": "d", "text": "It requires the provider to be notified immediately"}]'::jsonb, '["a"]', 'Post-op stoma function begins within 2-4 days, so no output on day 3 is still expected. The provider is notified if there is no function after 5 days.'),
  ('colostomy', 5, 'A client is 6 days post-op after colostomy creation, and the stoma has not yet produced any output. Which action is most appropriate?', '[{"id": "a", "text": "Continue to monitor, since function may take up to 7 days"}, {"id": "b", "text": "Notify the health care provider of the finding"}, {"id": "c", "text": "Increase gas-producing foods to stimulate output"}, {"id": "d", "text": "Change the pouching system to improve the seal"}]'::jsonb, '["b"]', 'A stoma should function within 2-4 days post-op; no function after 5 days requires notifying the provider. Continuing to wait delays evaluation.'),
  ('colostomy', 6, 'A client has a newly created ascending colostomy. Which stool consistency should the nurse expect?', '[{"id": "a", "text": "Normal and formed"}, {"id": "b", "text": "More formed"}, {"id": "c", "text": "Liquid"}, {"id": "d", "text": "Semi-formed"}]'::jsonb, '["c"]', 'An ascending colostomy produces liquid stool because digestive enzymes are still active. Semi-formed stool is expected with a transverse colostomy, and formed stool with lower colostomies.'),
  ('colostomy', 7, 'A client with rectal cancer had a sigmoid colostomy created. The client asks what the stool will be like. Which response by the nurse is accurate?', '[{"id": "a", "text": "Your stool will usually be normal and formed."}, {"id": "b", "text": "Your stool will be liquid because enzymes remain active."}, {"id": "c", "text": "Your stool will be semi-formed most of the time."}, {"id": "d", "text": "Your stool will stay liquid until the stoma is closed."}]'::jsonb, '["a"]', 'A sigmoid colostomy is low on the GI tract, so stool is normal and formed. Liquid stool with active enzymes describes an ascending colostomy.'),
  ('colostomy', 8, 'The nurse is caring for four clients with colostomies. Which client''s peristomal skin is at greatest risk for damage from active digestive enzymes?', '[{"id": "a", "text": "The client with a sigmoid colostomy"}, {"id": "b", "text": "The client with a descending colostomy"}, {"id": "c", "text": "The client with a transverse colostomy"}, {"id": "d", "text": "The client with an ascending colostomy"}]'::jsonb, '["d"]', 'Ascending colostomy output is liquid with digestive enzymes still active, making skin care critical because enzymes damage skin. Lower colostomies produce more formed stool.'),
  ('colostomy', 9, 'The nurse is teaching a client how the location of a colostomy affects stool. Which client statement indicates understanding?', '[{"id": "a", "text": "The higher my stoma is on the colon, the more formed my stool will be."}, {"id": "b", "text": "The lower my stoma is on the colon, the more formed my stool will be."}, {"id": "c", "text": "My stool consistency will be the same wherever the stoma is placed."}, {"id": "d", "text": "The lower my stoma is on the colon, the more liquid my stool will be."}]'::jsonb, '["b"]', 'The lower the stoma on the GI tract, the more formed the stool. The reversed statements describe the relationship backward.'),
  ('colostomy', 10, 'A client with a new transverse colostomy asks whether it will be permanent. Which response by the nurse is best?', '[{"id": "a", "text": "Transverse colostomies are always permanent."}, {"id": "b", "text": "All colostomies are reversed within a few weeks."}, {"id": "c", "text": "This type is often temporary, depending on the reason for it."}, {"id": "d", "text": "Only colostomies in the right abdomen can be temporary."}]'::jsonb, '["c"]', 'A transverse colostomy is often temporary, and colostomies can be temporary or permanent depending on the indication. Stating that it is always permanent or always reversed is inaccurate.'),
  ('colostomy', 11, 'A client is scheduled for colostomy creation after treatment for rectal cancer. Which type of colostomy is often permanent in this situation?', '[{"id": "a", "text": "Sigmoid"}, {"id": "b", "text": "Transverse"}, {"id": "c", "text": "Ascending"}, {"id": "d", "text": "Descending"}]'::jsonb, '["a"]', 'A sigmoid colostomy in the lower left abdomen is often permanent, for example after rectal cancer. A transverse colostomy is often temporary.'),
  ('colostomy', 12, 'The nurse notes a stoma in the upper abdomen, slightly right of midline, producing semi-formed stool. Which type of colostomy does this client most likely have?', '[{"id": "a", "text": "Sigmoid"}, {"id": "b", "text": "Ascending"}, {"id": "c", "text": "Descending"}, {"id": "d", "text": "Transverse"}]'::jsonb, '["d"]', 'A transverse colostomy is located in the upper abdomen (middle/right) and produces semi-formed stool. An ascending colostomy is in the right abdomen and produces liquid stool.'),
  ('colostomy', 13, 'A client with a descending colostomy asks how the stool will compare with that of a client who has a transverse colostomy. Which response is accurate?', '[{"id": "a", "text": "Your stool will be more liquid because enzymes are still active."}, {"id": "b", "text": "Your stool will be more formed because the stoma is lower."}, {"id": "c", "text": "Your stool will be identical because both are in the colon."}, {"id": "d", "text": "Your stool will be less formed because the stoma is higher."}]'::jsonb, '["b"]', 'A descending colostomy produces more formed stool than a transverse colostomy, which is semi-formed; a lower colostomy means more formed stool. Liquid stool with active enzymes describes an ascending colostomy.'),
  ('colostomy', 14, 'The nurse is reviewing the history of a client scheduled for a colostomy. Which condition is most consistent with the indications for this surgery?', '[{"id": "a", "text": "Gastroesophageal reflux disease"}, {"id": "b", "text": "Gallstones in the gallbladder"}, {"id": "c", "text": "Diverticulitis of the colon"}, {"id": "d", "text": "An ulcer in the stomach lining"}]'::jsonb, '["c"]', 'A colostomy is used when part of the colon or rectum is diseased or removed, and diverticulitis is a listed indication. The other conditions do not involve the colon or rectum.'),
  ('colostomy', 15, 'The nurse is teaching a client how to manage a colostomy pouch. When should the client empty the pouch?', '[{"id": "a", "text": "When it is one-third full"}, {"id": "b", "text": "When it is one-half full"}, {"id": "c", "text": "When it is two-thirds full"}, {"id": "d", "text": "When it is completely full"}]'::jsonb, '["a"]', 'The bag should be emptied when it is one-third full to prevent leakage. Waiting until it is fuller increases the risk of leaking.'),
  ('colostomy', 16, 'The nurse observes a UAP caring for a client with a colostomy. Which action by the UAP requires correction?', '[{"id": "a", "text": "Emptying the pouch when it is one-third full"}, {"id": "b", "text": "Rinsing the skin thoroughly after washing with mild soap"}, {"id": "c", "text": "Patting the peristomal skin completely dry"}, {"id": "d", "text": "Waiting until the pouch is three-quarters full to empty it"}]'::jsonb, '["d"]', 'The pouch should be emptied at one-third full to prevent leakage, so waiting until it is three-quarters full needs correction. Rinsing thoroughly and drying the skin completely are correct steps.'),
  ('colostomy', 17, 'A client asks why the colostomy pouch should be emptied before it becomes too full. Which response by the nurse is accurate?', '[{"id": "a", "text": "To prevent the stoma from turning dusky"}, {"id": "b", "text": "To prevent the pouch from leaking"}, {"id": "c", "text": "To prevent stool from becoming more formed"}, {"id": "d", "text": "To prevent the stoma from retracting"}]'::jsonb, '["b"]', 'Emptying the bag at one-third full prevents leakage. A dusky stoma reflects poor perfusion and is unrelated to how full the pouch is.'),
  ('colostomy', 18, 'The nurse is teaching a client with a colostomy about appliance care. How often should the client change the pouching system?', '[{"id": "a", "text": "Every 12 hours"}, {"id": "b", "text": "Once daily after bathing"}, {"id": "c", "text": "Every 3 to 7 days or as needed"}, {"id": "d", "text": "Every 2 weeks if no leaks occur"}]'::jsonb, '["c"]', 'The pouching system is changed every 3-7 days or as needed. Daily or twice-daily changes are more frequent than recommended, and every 2 weeks is too long.'),
  ('colostomy', 19, 'The nurse is preparing a new skin barrier (wafer) for a client''s colostomy. How should the nurse size the wafer opening?', '[{"id": "a", "text": "One-eighth inch larger than the stoma"}, {"id": "b", "text": "Exactly the same size as the stoma"}, {"id": "c", "text": "One-half inch larger than the stoma"}, {"id": "d", "text": "One-eighth inch smaller than the stoma"}]'::jsonb, '["a"]', 'The wafer is cut one-eighth inch larger than the stoma to protect the skin. Sizes that are too large or too small do not provide this protection.'),
  ('colostomy', 20, 'Which statement by a client learning colostomy care indicates a need for further teaching?', '[{"id": "a", "text": "I''ll cut the wafer opening one-eighth inch larger than my stoma."}, {"id": "b", "text": "I''ll empty my pouch when it is about one-third full."}, {"id": "c", "text": "I''ll pat my skin completely dry before applying the new pouch."}, {"id": "d", "text": "I''ll wash around my stoma with a moisturizing soap to keep it soft."}]'::jsonb, '["d"]', 'Oily or moisturizing soaps interfere with pouch adhesion and should be avoided. The other statements reflect correct wafer sizing, emptying, and drying.'),
  ('colostomy', 21, 'When cleaning the skin around a client''s stoma during a pouch change, which product should the nurse use?', '[{"id": "a", "text": "Alcohol pads followed by water"}, {"id": "b", "text": "Warm water and mild, fragrance-free soap"}, {"id": "c", "text": "An oily, moisturizing soap and water"}, {"id": "d", "text": "A scented soap and hot water"}]'::jsonb, '["b"]', 'The skin is cleaned with warm water and mild, fragrance-free soap. Oily soaps interfere with adhesion, and alcohol is too harsh and drying.'),
  ('colostomy', 22, 'A client asks what to use to remove adhesive residue from the skin around the stoma. Which recommendation is appropriate?', '[{"id": "a", "text": "Alcohol swabs applied to the stoma and skin"}, {"id": "b", "text": "An oily lotion massaged into the skin"}, {"id": "c", "text": "Non-alcohol adhesive remover wipes"}, {"id": "d", "text": "A moisturizing soap left on the skin"}]'::jsonb, '["c"]', 'Non-alcohol adhesive remover wipes are used to remove residue. Alcohol is too harsh and drying, and oily or moisturizing products interfere with pouch adhesion.'),
  ('colostomy', 23, 'The charge nurse observes a new nurse performing colostomy care. Which action requires correction?', '[{"id": "a", "text": "Wiping the stoma itself with an alcohol pad"}, {"id": "b", "text": "Inspecting the stoma and skin after removing the old pouch"}, {"id": "c", "text": "Rinsing the skin thoroughly after cleaning"}, {"id": "d", "text": "Gently peeling off the old pouch and barrier"}]'::jsonb, '["a"]', 'Alcohol should not be used on the stoma itself because it is too harsh and drying. Gently peeling off the pouch, inspecting, and rinsing thoroughly are correct steps.'),
  ('colostomy', 24, 'After gently peeling off a client''s old colostomy pouch, which action should the nurse take next?', '[{"id": "a", "text": "Apply the new pouch"}, {"id": "b", "text": "Pat the skin dry"}, {"id": "c", "text": "Rinse the skin thoroughly"}, {"id": "d", "text": "Inspect the stoma and skin"}]'::jsonb, '["d"]', 'After the old pouch is removed, the stoma and skin are inspected for redness, swelling, and breakdown. Cleaning, rinsing, drying, and applying the new pouch follow.'),
  ('colostomy', 25, 'Which sequence for changing a colostomy pouch is correct?', '[{"id": "a", "text": "Peel off pouch, clean skin, pat dry, inspect stoma, apply pouch"}, {"id": "b", "text": "Peel off pouch, inspect stoma, clean skin, rinse, pat dry, apply pouch"}, {"id": "c", "text": "Peel off pouch, clean skin, apply pouch, rinse, inspect stoma"}, {"id": "d", "text": "Inspect stoma, peel off pouch, apply pouch, clean skin, pat dry"}]'::jsonb, '["b"]', 'The steps are peel off the old pouch, inspect the stoma and skin, clean, rinse thoroughly, pat completely dry, and then apply the new pouch. The other sequences inspect too late or apply the pouch before the skin is prepared.'),
  ('colostomy', 26, 'A client''s new colostomy pouch keeps loosening soon after it is applied. Which part of the client''s technique most likely needs correction?', '[{"id": "a", "text": "Using mild, fragrance-free soap"}, {"id": "b", "text": "Rinsing the skin thoroughly after washing"}, {"id": "c", "text": "Applying the pouch while the skin is still damp"}, {"id": "d", "text": "Using non-alcohol adhesive remover wipes"}]'::jsonb, '["c"]', 'The skin must be completely dry before the new pouch is applied. Mild soap, thorough rinsing, and non-alcohol remover wipes are all correct techniques.'),
  ('colostomy', 27, 'The nurse teaches a client to rinse the peristomal skin thoroughly after washing it. Which explanation supports this step?', '[{"id": "a", "text": "Soap residue irritates skin and affects the adhesive"}, {"id": "b", "text": "Rinsing improves blood flow to a dusky stoma"}, {"id": "c", "text": "Rinsing stimulates stoma output after surgery"}, {"id": "d", "text": "Soap residue makes the stool more formed"}]'::jsonb, '["a"]', 'Soap residue irritates the skin and affects the adhesive, so thorough rinsing is needed. A dusky stoma indicates poor perfusion and requires HCP notification, not rinsing.'),
  ('colostomy', 28, 'A client with a colostomy has excoriated peristomal skin. Which cause should the nurse suspect?', '[{"id": "a", "text": "Stoma ischemia from poor perfusion"}, {"id": "b", "text": "Gas-producing foods in the diet"}, {"id": "c", "text": "Inadequate daily fluid intake"}, {"id": "d", "text": "A poorly fitting appliance or leaking bag"}]'::jsonb, '["d"]', 'Excoriated peristomal skin indicates poor appliance fit or a leaking bag. Poor perfusion shows up as a pale, dusky, or black stoma, not skin excoriation.'),
  ('colostomy', 29, 'During colostomy care, which peristomal skin finding should the nurse document as normal?', '[{"id": "a", "text": "Redness around the wafer edge"}, {"id": "b", "text": "Intact skin without redness"}, {"id": "c", "text": "A rash beneath the barrier"}, {"id": "d", "text": "Small areas of skin breakdown"}]'::jsonb, '["b"]', 'Normal peristomal skin is intact with no redness. Redness, rash, and breakdown are abnormal findings.'),
  ('colostomy', 30, 'During a pouch change, the nurse notes redness, rash, and irritation of the peristomal skin. How should the nurse interpret this finding?', '[{"id": "a", "text": "Expected healing after surgery"}, {"id": "b", "text": "A sign of stoma ischemia"}, {"id": "c", "text": "An abnormal finding such as contact dermatitis"}, {"id": "d", "text": "A sign of excessive gas in the pouch"}]'::jsonb, '["c"]', 'Redness, irritation, rash, and breakdown of peristomal skin are abnormal and consistent with contact dermatitis. Ischemia is shown by stoma color changes, not peristomal rash.'),
  ('colostomy', 31, 'A client reports that the colostomy pouch frequently balloons with gas. Which teaching is most appropriate?', '[{"id": "a", "text": "Limit beans, broccoli, and carbonated drinks"}, {"id": "b", "text": "Reduce water intake to decrease output"}, {"id": "c", "text": "Change the pouching system every day"}, {"id": "d", "text": "Cut the wafer opening one inch larger"}]'::jsonb, '["a"]', 'Excessive gas causes bag ballooning, and gas-producing foods such as beans, broccoli, and carbonated drinks can be avoided if needed. Reducing water is wrong because hydration is encouraged to prevent constipation.'),
  ('colostomy', 32, 'A client with a new colostomy is distressed about a mild odor and some gas in the pouch. Which response by the nurse is accurate?', '[{"id": "a", "text": "This suggests your stoma is not getting enough blood flow."}, {"id": "b", "text": "This means the pouch must be changed right away."}, {"id": "c", "text": "This indicates a blockage that needs to be reported."}, {"id": "d", "text": "A mild odor and some gas are normal with a colostomy."}]'::jsonb, '["d"]', 'A mild odor and some gas are normal. Poor blood flow shows as a pale, dusky, or black stoma, and obstruction presents as no output.'),
  ('colostomy', 33, 'A client with a sigmoid colostomy asks how to prevent constipation. Which teaching should the nurse reinforce?', '[{"id": "a", "text": "Avoid eating broccoli and beans"}, {"id": "b", "text": "Maintain adequate fluid intake"}, {"id": "c", "text": "Change the pouch more often"}, {"id": "d", "text": "Use a moisturizing soap on the skin"}]'::jsonb, '["b"]', 'Hydration is encouraged to prevent constipation. Avoiding broccoli and beans addresses gas, not constipation.'),
  ('colostomy', 34, 'Which statement by a client with a new colostomy indicates understanding of discharge teaching?', '[{"id": "a", "text": "I''ll have to give up traveling now that I have a stoma."}, {"id": "b", "text": "I''ll need to stop all of my usual physical activities."}, {"id": "c", "text": "My colostomy usually won''t restrict my activities or travel."}, {"id": "d", "text": "I should stay close to home until the colostomy is reversed."}]'::jsonb, '["c"]', 'A colostomy does not usually restrict activities or travel. The other statements reflect unnecessary restrictions.'),
  ('colostomy', 35, 'A client with a new colostomy and no dietary contraindications asks about eating at home. Which instruction is appropriate?', '[{"id": "a", "text": "Resume your normal diet."}, {"id": "b", "text": "Follow a clear liquid diet permanently."}, {"id": "c", "text": "Avoid all fruits and vegetables."}, {"id": "d", "text": "Eat only soft, pureed foods."}]'::jsonb, '["a"]', 'Clients resume a normal diet unless it is contraindicated. Gas-producing foods are limited only if needed, so broad lifelong restrictions are not required.'),
  ('colostomy', 36, 'A client has a high-output colostomy. Which laboratory values should the nurse monitor most closely?', '[{"id": "a", "text": "Serum amylase and lipase"}, {"id": "b", "text": "Hemoglobin and hematocrit"}, {"id": "c", "text": "Liver enzymes and bilirubin"}, {"id": "d", "text": "Serum potassium and sodium"}]'::jsonb, '["d"]', 'A high-output colostomy requires monitoring for fluid and electrolyte imbalance, especially potassium and sodium. The other values are not the electrolytes at risk.'),
  ('colostomy', 37, 'A client with an ascending colostomy has excessive liquid output. The nurse should prioritize assessment for which complication?', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Dehydration"}, {"id": "c", "text": "Stoma prolapse"}, {"id": "d", "text": "Bowel obstruction"}]'::jsonb, '["b"]', 'High output places the client at risk for dehydration and electrolyte imbalance. Obstruction is suggested by no output, not excessive output.'),
  ('colostomy', 38, 'A client with a new colostomy says, ''I can''t stand to look at this. I feel disgusting.'' Which response by the nurse is most appropriate?', '[{"id": "a", "text": "You''ll get used to it, so try not to think about it."}, {"id": "b", "text": "Let''s focus on learning to change the pouch right now."}, {"id": "c", "text": "It''s common to feel this way. Tell me more about how you feel."}, {"id": "d", "text": "Many people have it much worse than you do."}]'::jsonb, '["c"]', 'Body image concerns are common, and the nurse should respond with empathy and support. Starting pouch teaching immediately ignores the need to assess readiness to learn first.'),
  ('colostomy', 39, 'Before beginning colostomy self-care teaching, which action should the nurse take first?', '[{"id": "a", "text": "Assess the client''s readiness to learn"}, {"id": "b", "text": "Demonstrate a complete pouch change"}, {"id": "c", "text": "Provide a written list of foods to avoid"}, {"id": "d", "text": "Have the client change the pouch alone"}]'::jsonb, '["a"]', 'Readiness to learn self-care is assessed before teaching begins. Demonstrations and independent practice follow once the client is ready.'),
  ('colostomy', 40, 'A client with a colostomy has had difficulty coping for several weeks after discharge. Which nursing action is appropriate?', '[{"id": "a", "text": "Advise the client to avoid discussing the stoma"}, {"id": "b", "text": "Recommend limiting social activities and travel"}, {"id": "c", "text": "Tell the client that coping problems are unusual"}, {"id": "d", "text": "Encourage the client to join a support group"}]'::jsonb, '["d"]', 'Support groups are encouraged when coping is difficult. Body image concerns are common, and a colostomy does not usually restrict activities or travel.'),
  ('colostomy', 41, 'Which outcome best indicates that colostomy teaching has been effective?', '[{"id": "a", "text": "The client lets the spouse perform all pouch changes"}, {"id": "b", "text": "The client empties and changes the appliance independently"}, {"id": "c", "text": "The client avoids looking at the stoma during care"}, {"id": "d", "text": "The client asks the nurse to empty the pouch daily"}]'::jsonb, '["b"]', 'The goal of teaching is for the client to use, empty, and change the appliance independently. Relying on others or avoiding the stoma shows the goal has not been met.'),
  ('colostomy', 42, 'The nurse is assessing a client''s colostomy. Which stoma finding should the nurse report?', '[{"id": "a", "text": "Round and slightly protruding"}, {"id": "b", "text": "Oval and slightly protruding"}, {"id": "c", "text": "Sunken below the skin surface"}, {"id": "d", "text": "Pink-red and moist"}]'::jsonb, '["c"]', 'A sunken or retracted stoma is abnormal. A normal stoma is round or oval, slightly protruding, and pink/red and moist.'),
  ('colostomy', 43, 'While cleaning a client''s stoma, the nurse notes a small amount of bleeding when the stoma is touched. How should the nurse interpret this?', '[{"id": "a", "text": "This is an expected finding"}, {"id": "b", "text": "This indicates stoma necrosis"}, {"id": "c", "text": "This requires immediate notification"}, {"id": "d", "text": "This indicates contact dermatitis"}]'::jsonb, '["a"]', 'A small amount of bleeding when the stoma is touched is normal. Only continuous or heavy bleeding is abnormal.'),
  ('colostomy', 44, 'The nurse is gathering supplies to change a client''s colostomy appliance. Which technique is appropriate?', '[{"id": "a", "text": "Sterile technique"}, {"id": "b", "text": "Surgical aseptic technique"}, {"id": "c", "text": "Full sterile barrier precautions"}, {"id": "d", "text": "Clean technique"}]'::jsonb, '["d"]', 'Supplies are set up using clean technique for colostomy appliance changes. Sterile or surgical aseptic approaches are not what is called for.'),
  ('colostomy', 45, 'The nurse notes that a client''s stoma, which was pink yesterday, is now pale. The nurse recognizes this as a sign of which problem?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Poor perfusion of the stoma"}, {"id": "c", "text": "Normal post-op healing"}, {"id": "d", "text": "Excessive gas production"}]'::jsonb, '["b"]', 'A pale, dusky, purple, or black stoma indicates ischemia or necrosis from poor perfusion. Contact dermatitis affects the peristomal skin, not the stoma color.'),
  ('colostomy', 46, 'The nurse receives report on four clients with colostomies. Which client should the nurse assess first?', '[{"id": "a", "text": "A client 2 days post-op with no stoma output yet"}, {"id": "b", "text": "A client with a sigmoid colostomy passing formed stool"}, {"id": "c", "text": "A client whose stoma has newly become dusky"}, {"id": "d", "text": "A client who reports a mild odor when emptying the pouch"}]'::jsonb, '["c"]', 'A dusky stoma reflects poor perfusion and is an emergency. No output on day 2 is within the expected 2-4 day window, and formed stool and mild odor are normal.'),
  ('colostomy', 47, 'Which statement by a client indicates understanding of what a colostomy is?', '[{"id": "a", "text": "Stool will leave my body through an opening from my colon."}, {"id": "b", "text": "Urine will drain through an opening from my bladder."}, {"id": "c", "text": "Food will enter my body through an opening in my stomach."}, {"id": "d", "text": "Stool will leave my body through an opening from my stomach."}]'::jsonb, '["a"]', 'A colostomy is a stoma created from the colon (large intestine) to the abdominal wall so stool can exit into a colostomy bag. It does not involve the bladder or stomach.'),
  ('colostomy', 48, 'A client whose colostomy previously functioned well now has no output. The nurse recognizes that this finding may indicate which problem?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Stoma ischemia"}, {"id": "c", "text": "Excessive gas"}, {"id": "d", "text": "Obstruction"}]'::jsonb, '["d"]', 'No output from a colostomy is abnormal and suggests obstruction. Ischemia is recognized by stoma color changes, not absent output.'),
  ('colostomy', 49, 'A client''s colostomy pouch begins leaking 2 days after it was applied. Which action is appropriate?', '[{"id": "a", "text": "Leave it in place until day 7"}, {"id": "b", "text": "Change the pouching system now"}, {"id": "c", "text": "Tape the edges and leave it on"}, {"id": "d", "text": "Leave it in place until day 3"}]'::jsonb, '["b"]', 'The pouching system is changed every 3-7 days or as needed, so a leaking pouch should be changed now. A leaking bag can also cause excoriated peristomal skin.'),
  ('colostomy', 50, 'The nurse notes a stoma located in the right abdomen that is draining liquid stool. Which type of colostomy does this client most likely have?', '[{"id": "a", "text": "Sigmoid"}, {"id": "b", "text": "Descending"}, {"id": "c", "text": "Ascending"}, {"id": "d", "text": "Transverse"}]'::jsonb, '["c"]', 'An ascending colostomy is in the right abdomen and produces liquid stool because digestive enzymes are still active. A sigmoid colostomy is in the lower left abdomen and produces formed stool.'),
  ('roux_en_y', 1, 'A client asks how Roux-en-Y gastric bypass produces weight loss. Which description by the nurse is accurate?', '[{"id": "a", "text": "It restricts intake and reduces nutrient absorption"}, {"id": "b", "text": "It restricts intake but does not affect absorption"}, {"id": "c", "text": "It reduces absorption but does not limit intake"}, {"id": "d", "text": "It removes the colon to reduce calorie absorption"}]'::jsonb, '["a"]', 'Roux-en-Y gastric bypass combines a restrictive mechanism (small stomach pouch) with a malabsorptive mechanism (bypassing the duodenum and part of the jejunum). Describing only one mechanism is incomplete.'),
  ('roux_en_y', 2, 'A client preparing for Roux-en-Y gastric bypass asks how much the new stomach pouch will hold. Which response is accurate?', '[{"id": "a", "text": "About 500 mL"}, {"id": "b", "text": "About 1 liter"}, {"id": "c", "text": "About 15 to 30 mL"}, {"id": "d", "text": "About 150 to 200 mL"}]'::jsonb, '["c"]', 'The surgery creates a small stomach pouch of about 15-30 mL to limit food intake. The larger volumes would not dramatically reduce stomach capacity.'),
  ('roux_en_y', 3, 'The nurse is explaining Roux-en-Y gastric bypass to a client. Which portion of the gastrointestinal tract does food bypass?', '[{"id": "a", "text": "The jejunum and the entire ileum"}, {"id": "b", "text": "The duodenum and part of the jejunum"}, {"id": "c", "text": "The esophagus and upper stomach"}, {"id": "d", "text": "The ileum and the ascending colon"}]'::jsonb, '["b"]', 'The surgery bypasses the duodenum and part of the jejunum, which reduces nutrient absorption. The ileum and colon are not the bypassed segments.'),
  ('roux_en_y', 4, 'A client asks what the ''Y'' in Roux-en-Y refers to. The nurse explains that it describes a connection between which structures?', '[{"id": "a", "text": "The esophagus and duodenum"}, {"id": "b", "text": "The gastric pouch and colon"}, {"id": "c", "text": "The duodenum and ileum"}, {"id": "d", "text": "The gastric pouch and jejunum"}]'::jsonb, '["d"]', 'Roux-en-Y refers to a Y-shaped connection between the small gastric pouch and the jejunum. The duodenum is bypassed, not connected to the pouch.'),
  ('roux_en_y', 5, 'The nurse is reviewing clients referred for bariatric surgery. Which client meets a BMI criterion for Roux-en-Y gastric bypass?', '[{"id": "a", "text": "BMI 36 with type 2 diabetes"}, {"id": "b", "text": "BMI 37 with no comorbidities"}, {"id": "c", "text": "BMI 33 with hypertension"}, {"id": "d", "text": "BMI 30 with sleep apnea"}]'::jsonb, '["a"]', 'A BMI of 35 or higher with a serious comorbidity such as type 2 diabetes is an indication. A BMI of 37 without comorbidities, or a BMI below 35, does not meet the criteria.'),
  ('roux_en_y', 6, 'A client with a BMI of 42 is being evaluated for Roux-en-Y gastric bypass. Which additional finding supports the client''s candidacy?', '[{"id": "a", "text": "Has not yet tried diet or exercise"}, {"id": "b", "text": "Plans to skip long-term follow-up"}, {"id": "c", "text": "Has failed nonsurgical weight-loss methods"}, {"id": "d", "text": "Expects to resume usual eating habits"}]'::jsonb, '["c"]', 'Failure of nonsurgical weight loss methods is an indication for surgery. Candidates must also be committed to lifestyle changes and follow-up, which the other options contradict.'),
  ('roux_en_y', 7, 'During pre-op screening for Roux-en-Y gastric bypass, which client statement should concern the nurse most?', '[{"id": "a", "text": "I''ve tried several diets without lasting results."}, {"id": "b", "text": "I don''t think I''ll need follow-up once I lose weight."}, {"id": "c", "text": "I''m ready to change how I eat for the rest of my life."}, {"id": "d", "text": "My sleep apnea and blood pressure keep getting worse."}]'::jsonb, '["b"]', 'Candidates must be committed to lifestyle changes and follow-up, so refusing follow-up is a concern. Failed diets and comorbidities such as sleep apnea and hypertension support candidacy.'),
  ('roux_en_y', 8, 'The nurse is monitoring a client after Roux-en-Y gastric bypass for an anastomotic leak. Which finding is typically the first sign?', '[{"id": "a", "text": "Decreased bowel sounds"}, {"id": "b", "text": "Low-grade fever"}, {"id": "c", "text": "Shoulder pain"}, {"id": "d", "text": "Increased heart rate"}]'::jsonb, '["d"]', 'An increased heart rate (tachycardia) is the first sign of an anastomotic leak and requires immediate surgeon notification. Fever and shoulder pain can occur but are not the first sign.'),
  ('roux_en_y', 9, 'The nurse receives report on four clients who had Roux-en-Y gastric bypass. Which client should the nurse assess first?', '[{"id": "a", "text": "Day 2 post-op with a rising heart rate and new shoulder pain"}, {"id": "b", "text": "Day 1 post-op requesting help to ambulate in the hall"}, {"id": "c", "text": "Day 3 post-op tolerating sugar-free clear liquids"}, {"id": "d", "text": "Two months post-op asking about vitamin supplements"}]'::jsonb, '["a"]', 'Increased heart rate with abdominal, back, or shoulder pain suggests an anastomotic leak, which is an emergency. The other clients reflect expected recovery and teaching needs.'),
  ('roux_en_y', 10, 'Two days after Roux-en-Y gastric bypass, a client has a heart rate of 126, respiratory rate of 26, temperature of 100.9°F, and severe abdominal pain. Which action should the nurse take?', '[{"id": "a", "text": "Encourage the client to ambulate"}, {"id": "b", "text": "Offer sugar-free clear liquids"}, {"id": "c", "text": "Notify the surgeon immediately"}, {"id": "d", "text": "Reassess vital signs in 4 hours"}]'::jsonb, '["c"]', 'Tachycardia, tachypnea, fever, and severe abdominal pain suggest an anastomotic leak, so the surgeon must be notified immediately. Waiting to reassess delays care for an emergency.'),
  ('roux_en_y', 11, 'A client who just returned from Roux-en-Y gastric bypass surgery asks for a drink of water. Which response by the nurse is appropriate?', '[{"id": "a", "text": "You can sip water now as long as it is sugar-free."}, {"id": "b", "text": "You''ll stay NPO until bowel function returns and leaks are ruled out."}, {"id": "c", "text": "You may have a protein shake instead of water for now."}, {"id": "d", "text": "You can drink as much as you want to prevent dehydration."}]'::jsonb, '["b"]', 'Immediately after surgery the client is NPO until bowel function returns and no leaks are confirmed. Clear liquids and protein shakes come later in the diet progression.'),
  ('roux_en_y', 12, 'A client is starting stage 1 of the diet after Roux-en-Y gastric bypass. Which beverage is appropriate?', '[{"id": "a", "text": "Sweetened apple juice served chilled"}, {"id": "b", "text": "Sugar-free carbonated cola beverage"}, {"id": "c", "text": "Regular caffeinated brewed coffee"}, {"id": "d", "text": "Sugar-free, caffeine-free flavored water"}]'::jsonb, '["d"]', 'Stage 1 clear liquids must be sugar-free, caffeine-free, and noncarbonated. Sugar-free cola is still carbonated, and coffee contains caffeine.'),
  ('roux_en_y', 13, 'Which statement by a client on stage 1 of the post-bariatric diet indicates a need for further teaching?', '[{"id": "a", "text": "I can have diet soda because it has no sugar."}, {"id": "b", "text": "I''ll choose drinks that are free of caffeine."}, {"id": "c", "text": "I''ll avoid anything carbonated for now."}, {"id": "d", "text": "I''ll pick clear liquids that are sugar-free."}]'::jsonb, '["a"]', 'Stage 1 beverages must be noncarbonated as well as sugar-free and caffeine-free, so diet soda is not allowed. The other statements are correct.'),
  ('roux_en_y', 14, 'A client has advanced to stage 2 of the diet after Roux-en-Y gastric bypass. Which item is appropriate?', '[{"id": "a", "text": "Scrambled eggs"}, {"id": "b", "text": "Pancakes with syrup"}, {"id": "c", "text": "High-protein shake"}, {"id": "d", "text": "Regular soda"}]'::jsonb, '["c"]', 'Stage 2 includes full liquids and pureed foods such as high-protein shakes, pureed meats, and yogurt. Eggs belong to stage 3, and high-sugar or carbonated items are avoided.'),
  ('roux_en_y', 15, 'A client is on stage 3 (soft foods) after Roux-en-Y gastric bypass. Which meal is consistent with this stage?', '[{"id": "a", "text": "Regular soda with crackers"}, {"id": "b", "text": "Tender fish with soft vegetables"}, {"id": "c", "text": "Fried chicken and french fries"}, {"id": "d", "text": "Sweetened juice and cake"}]'::jsonb, '["b"]', 'Stage 3 soft foods include eggs, tender fish, and soft vegetables. High-sugar and high-fat foods are avoided.'),
  ('roux_en_y', 16, 'Two months after Roux-en-Y gastric bypass, a client asks for help choosing breakfast. Which choice is most appropriate?', '[{"id": "a", "text": "Pancakes with syrup"}, {"id": "b", "text": "A sweet roll with juice"}, {"id": "c", "text": "Fried sausage and hash browns"}, {"id": "d", "text": "Scrambled eggs and soft-cooked vegetables"}]'::jsonb, '["d"]', 'Scrambled eggs and soft-cooked vegetables are an appropriate choice. Pancakes with syrup are high in sugar and can cause dumping syndrome.'),
  ('roux_en_y', 17, 'A client has progressed to a regular diet after Roux-en-Y gastric bypass. Which instruction is appropriate?', '[{"id": "a", "text": "Eat small, frequent meals and avoid high-sugar, high-fat foods"}, {"id": "b", "text": "Eat three large meals and include a dessert each day"}, {"id": "c", "text": "Return to your usual portions now that you have healed"}, {"id": "d", "text": "Choose high-fat foods to meet your daily calorie needs"}]'::jsonb, '["a"]', 'Stage 4 regular diet consists of small frequent meals while avoiding high-sugar and high-fat foods. Large portions and desserts contradict portion control.'),
  ('roux_en_y', 18, 'Which sequence reflects the correct diet progression after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "Soft foods, clear liquids, pureed foods, regular diet"}, {"id": "b", "text": "Clear liquids, soft foods, pureed foods, regular diet"}, {"id": "c", "text": "Clear liquids, pureed foods, soft foods, regular diet"}, {"id": "d", "text": "Pureed foods, clear liquids, regular diet, soft foods"}]'::jsonb, '["c"]', 'After NPO, the diet progresses from clear liquids to full liquids and pureed foods, then soft foods, then a regular diet. Soft foods do not come before pureed foods.'),
  ('roux_en_y', 19, 'The nurse is teaching a client about fluid intake after Roux-en-Y gastric bypass. Which instruction is correct?', '[{"id": "a", "text": "Drink fluids with meals to help food pass"}, {"id": "b", "text": "Wait 30 minutes before and after meals to drink"}, {"id": "c", "text": "Drink a full glass of water during each meal"}, {"id": "d", "text": "Drink fluids right after you finish eating"}]'::jsonb, '["b"]', 'Clients should not drink liquids with meals and should wait 30 minutes before and after eating to prevent dumping syndrome. Drinking during or right after meals violates this teaching.'),
  ('roux_en_y', 20, 'Which statement by a client recovering from Roux-en-Y gastric bypass indicates a need for further teaching?', '[{"id": "a", "text": "I''ll take small portions and eat slowly."}, {"id": "b", "text": "I''ll eat my protein before my vegetables."}, {"id": "c", "text": "I''ll keep taking my vitamins for life."}, {"id": "d", "text": "I''ll sip water with my meals to help food go down."}]'::jsonb, '["d"]', 'No liquids should be taken with meals, so this statement needs correction. Small portions, protein first, and lifelong vitamins are correct.'),
  ('roux_en_y', 21, 'A client 3 months after Roux-en-Y gastric bypass has a plate of grilled chicken, steamed carrots, and rice. Which food should the client eat first?', '[{"id": "a", "text": "Grilled chicken"}, {"id": "b", "text": "Steamed carrots"}, {"id": "c", "text": "Rice"}, {"id": "d", "text": "Whichever food is preferred"}]'::jsonb, '["a"]', 'Clients eat protein first, then vegetables, then carbohydrates. Rice is a carbohydrate and should be eaten last.'),
  ('roux_en_y', 22, 'Which client behavior indicates correct application of teaching after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "Eating quickly to finish meals before feeling full"}, {"id": "b", "text": "Eating large portions twice a day"}, {"id": "c", "text": "Eating small portions slowly"}, {"id": "d", "text": "Skipping protein to save room for carbohydrates"}]'::jsonb, '["c"]', 'Clients are taught to reduce portion size and eat slowly. Eating quickly, eating large portions, and skipping protein contradict the teaching.'),
  ('roux_en_y', 23, 'Which statement by a client indicates understanding of supplementation after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "I''ll stop my vitamins once I reach my goal weight."}, {"id": "b", "text": "I''ll need vitamin and mineral supplements for life."}, {"id": "c", "text": "I''ll only need supplements for the first 6 months."}, {"id": "d", "text": "I won''t need supplements if I eat enough protein."}]'::jsonb, '["b"]', 'Lifelong vitamin and mineral supplementation is mandatory after Roux-en-Y gastric bypass. Stopping at goal weight or after a few months is incorrect.'),
  ('roux_en_y', 24, 'The nurse is reviewing long-term nutritional risks after Roux-en-Y gastric bypass. Deficiency of which nutrients should the nurse monitor?', '[{"id": "a", "text": "Sodium, potassium, and chloride"}, {"id": "b", "text": "Vitamin C, niacin, and zinc"}, {"id": "c", "text": "Magnesium, phosphorus, and copper"}, {"id": "d", "text": "Iron, calcium, vitamin B12, and folate"}]'::jsonb, '["d"]', 'Nutritional deficiencies after this surgery include iron, calcium, vitamin B12, folate, and fat-soluble vitamins A, D, E, and K. The other groups are not the listed deficiencies.'),
  ('roux_en_y', 25, 'A client asks why vitamin and mineral deficiencies develop after Roux-en-Y gastric bypass. Which explanation is accurate?', '[{"id": "a", "text": "Food skips the upper small intestine, reducing absorption."}, {"id": "b", "text": "The colon is removed, so vitamins cannot be absorbed."}, {"id": "c", "text": "The pouch makes extra acid that destroys vitamins."}, {"id": "d", "text": "Liquids taken with meals wash vitamins out of food."}]'::jsonb, '["a"]', 'Bypassing the duodenum and part of the jejunum means food skips the upper small intestine, decreasing calorie and nutrient absorption. The colon is not removed in this surgery.'),
  ('roux_en_y', 26, 'A client has lost weight rapidly in the months after Roux-en-Y gastric bypass. The nurse recognizes the client is at increased risk for which complication?', '[{"id": "a", "text": "Anastomotic leak"}, {"id": "b", "text": "Dumping syndrome"}, {"id": "c", "text": "Gallstones"}, {"id": "d", "text": "Wound infection"}]'::jsonb, '["c"]', 'Gallstones are a complication that results from rapid weight loss. Dumping syndrome results from rapid gastric emptying, not weight loss.'),
  ('roux_en_y', 27, 'A client who had Roux-en-Y gastric bypass develops a small bowel obstruction. Which cause is associated with this complication?', '[{"id": "a", "text": "Rapid weight loss"}, {"id": "b", "text": "Adhesions or hernia"}, {"id": "c", "text": "Rapid carbohydrate absorption"}, {"id": "d", "text": "Liquids taken with meals"}]'::jsonb, '["b"]', 'Small bowel obstruction after this surgery results from adhesions or hernia. Rapid weight loss is linked to gallstones, and rapid carbohydrate absorption to hypoglycemia.'),
  ('roux_en_y', 28, 'The nurse encourages early ambulation for a client after Roux-en-Y gastric bypass. Which outcome is the nurse trying to achieve?', '[{"id": "a", "text": "Faster return to a regular diet"}, {"id": "b", "text": "Reduced risk of dumping syndrome"}, {"id": "c", "text": "Prevention of gallstone formation"}, {"id": "d", "text": "Prevention of DVT and better lung expansion"}]'::jsonb, '["d"]', 'Pain control and early ambulation help prevent DVT and improve lung expansion. Dumping is prevented through diet and meal habits, not ambulation.'),
  ('roux_en_y', 29, 'Which intervention best supports hydration for a client after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "Maintain strict I&O and encourage slow sipping"}, {"id": "b", "text": "Encourage drinking large amounts quickly"}, {"id": "c", "text": "Offer most fluids together with meals"}, {"id": "d", "text": "Restrict fluids to avoid stretching the pouch"}]'::jsonb, '["a"]', 'Hydration is assessed with strict I&O, and slow sipping is encouraged. Fluids should not be taken with meals.'),
  ('roux_en_y', 30, 'Which action by a UAP caring for a client after Roux-en-Y gastric bypass requires correction?', '[{"id": "a", "text": "Recording all intake and output"}, {"id": "b", "text": "Assisting the client to ambulate early"}, {"id": "c", "text": "Urging the client to gulp a full glass of water"}, {"id": "d", "text": "Reminding the client to sip fluids slowly"}]'::jsonb, '["c"]', 'Clients are encouraged to sip slowly, so urging the client to gulp water requires correction. Strict I&O and early ambulation are appropriate.'),
  ('roux_en_y', 31, 'A client asks why low blood sugar can occur after Roux-en-Y gastric bypass. Which explanation is accurate?', '[{"id": "a", "text": "The pouch stores sugar and releases it slowly."}, {"id": "b", "text": "Rapid carbohydrate absorption causes an insulin surge."}, {"id": "c", "text": "Bypassing the duodenum blocks all sugar absorption."}, {"id": "d", "text": "Liquids taken with meals dilute the blood sugar."}]'::jsonb, '["b"]', 'Hypoglycemia occurs because rapid carbohydrate absorption causes an insulin surge. Sugar absorption is rapid, not blocked.'),
  ('roux_en_y', 32, 'Three months after Roux-en-Y gastric bypass, a client reports nausea, cramping, diarrhea, and dizziness about 20 minutes after eating. Which problem do these findings suggest?', '[{"id": "a", "text": "Late dumping syndrome"}, {"id": "b", "text": "Small bowel obstruction"}, {"id": "c", "text": "Gallstones"}, {"id": "d", "text": "Early dumping syndrome"}]'::jsonb, '["d"]', 'Early dumping occurs 10-30 minutes after eating with nausea, cramping, diarrhea, dizziness, and tachycardia. Late dumping occurs 1-3 hours after eating with hypoglycemia.'),
  ('roux_en_y', 33, 'A client who had Roux-en-Y gastric bypass reports sweating, weakness, and confusion about 2 hours after eating. The nurse recognizes these findings as which problem?', '[{"id": "a", "text": "Late dumping with hypoglycemia"}, {"id": "b", "text": "Early dumping from fluid shift"}, {"id": "c", "text": "An anastomotic leak"}, {"id": "d", "text": "A small bowel obstruction"}]'::jsonb, '["a"]', 'Late dumping occurs 1-3 hours after eating and causes hypoglycemia with sweating, weakness, and confusion. Early dumping occurs 10-30 minutes after eating.'),
  ('roux_en_y', 34, 'Which instruction should the nurse give to help prevent dumping syndrome after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "Walk briskly right after eating"}, {"id": "b", "text": "Sit upright for an hour after meals"}, {"id": "c", "text": "Lie down for 20 to 30 minutes after eating"}, {"id": "d", "text": "Drink fluids along with each meal"}]'::jsonb, '["c"]', 'Lying down 20-30 minutes after eating slows gastric emptying and helps prevent dumping. Drinking fluids with meals promotes dumping.'),
  ('roux_en_y', 35, 'Which meal plan best helps prevent dumping syndrome after Roux-en-Y gastric bypass?', '[{"id": "a", "text": "Low protein, high fat, high carbohydrate"}, {"id": "b", "text": "High protein, moderate fat, low carbohydrate"}, {"id": "c", "text": "Low protein, low fat, high carbohydrate"}, {"id": "d", "text": "High carbohydrate, moderate fat, low protein"}]'::jsonb, '["b"]', 'Dumping prevention includes high-protein, moderate-fat, low-carbohydrate meals. High-carbohydrate plans promote rapid gastric emptying and dumping.'),
  ('roux_en_y', 36, 'A client recovering from Roux-en-Y gastric bypass asks which food is most likely to trigger dumping syndrome. Which food should the nurse identify?', '[{"id": "a", "text": "Tender baked fish"}, {"id": "b", "text": "Plain yogurt"}, {"id": "c", "text": "Scrambled eggs"}, {"id": "d", "text": "Pancakes with syrup"}]'::jsonb, '["d"]', 'Pancakes with syrup are high in sugar and can cause dumping. Fish, yogurt, and eggs are part of the post-op diet stages.'),
  ('roux_en_y', 37, 'A client asks what causes dumping syndrome after Roux-en-Y gastric bypass. Which explanation is accurate?', '[{"id": "a", "text": "Rapid gastric emptying"}, {"id": "b", "text": "Leakage at the surgical connection"}, {"id": "c", "text": "Adhesions in the small bowel"}, {"id": "d", "text": "Slow gastric emptying"}]'::jsonb, '["a"]', 'Dumping syndrome results from rapid gastric emptying, causing nausea, cramping, diarrhea, and hypoglycemia. Leakage at the connection is an anastomotic leak, and adhesions cause obstruction.'),
  ('roux_en_y', 38, 'Before discharge after Roux-en-Y gastric bypass, which topic must the nurse include in teaching?', '[{"id": "a", "text": "How to return to large portions"}, {"id": "b", "text": "When to stop vitamin supplements"}, {"id": "c", "text": "Signs of dumping syndrome"}, {"id": "d", "text": "Why liquids go best with meals"}]'::jsonb, '["c"]', 'The nurse teaches signs of dumping syndrome before discharge. Vitamin supplementation is lifelong, and liquids should not be taken with meals.'),
  ('roux_en_y', 39, 'Which client statement shows understanding of the restrictive effect of Roux-en-Y gastric bypass?', '[{"id": "a", "text": "I''ll absorb fewer nutrients because food skips part of my intestine."}, {"id": "b", "text": "My smaller stomach pouch will limit how much food I can eat."}, {"id": "c", "text": "My colon will be shortened so that food passes through faster."}, {"id": "d", "text": "My stomach will stay the same size but will empty more slowly."}]'::jsonb, '["b"]', 'The restrictive mechanism is the small stomach pouch that limits food intake. Reduced absorption from bypassing part of the intestine is the malabsorptive mechanism.'),
  ('roux_en_y', 40, 'When planning care after Roux-en-Y gastric bypass, the nurse includes interventions for standard post-op risks. Which complications fall in this category?', '[{"id": "a", "text": "Gallstones and dumping syndrome"}, {"id": "b", "text": "Iron and vitamin B12 deficiency"}, {"id": "c", "text": "Hypoglycemia and dumping syndrome"}, {"id": "d", "text": "Wound infection, DVT, and PE"}]'::jsonb, '["d"]', 'Wound infection, DVT, and PE are standard post-op risks. Gallstones, dumping, deficiencies, and hypoglycemia are listed as separate complications with their own causes.'),
  ('roux_en_y', 41, 'Which client meets the BMI indication for Roux-en-Y gastric bypass even without a serious comorbidity?', '[{"id": "a", "text": "A client with a BMI of 41"}, {"id": "b", "text": "A client with a BMI of 38"}, {"id": "c", "text": "A client with a BMI of 36"}, {"id": "d", "text": "A client with a BMI of 34"}]'::jsonb, '["a"]', 'A BMI of 40 or higher is an indication on its own. A BMI of 35-39 requires serious comorbidities, and a BMI of 34 does not meet either criterion.'),
  ('roux_en_y', 42, 'A client asks when late dumping symptoms typically occur after a meal following Roux-en-Y gastric bypass. Which response is accurate?', '[{"id": "a", "text": "Within 5 minutes of eating"}, {"id": "b", "text": "10 to 30 minutes after eating"}, {"id": "c", "text": "1 to 3 hours after eating"}, {"id": "d", "text": "6 to 8 hours after eating"}]'::jsonb, '["c"]', 'Late dumping occurs 1-3 hours after eating and causes hypoglycemia. Symptoms 10-30 minutes after eating describe early dumping.'),
  ('roux_en_y', 43, 'The nurse is reinforcing lifelong diet changes after Roux-en-Y gastric bypass. Which instruction is appropriate?', '[{"id": "a", "text": "Eat carbohydrates first for quick energy"}, {"id": "b", "text": "Practice portion control and eat protein first"}, {"id": "c", "text": "Add high-sugar snacks between meals"}, {"id": "d", "text": "Eat vegetables first and protein last"}]'::jsonb, '["b"]', 'Lifelong diet changes include portion control, protein first, and no high-sugar foods. Eating carbohydrates or vegetables before protein reverses the recommended order.'),
  ('roux_en_y', 44, 'A client who had Roux-en-Y gastric bypass has frequent dumping symptoms. Which meal pattern should the nurse recommend?', '[{"id": "a", "text": "Two large meals each day"}, {"id": "b", "text": "One large meal in the evening"}, {"id": "c", "text": "Three large meals with dessert"}, {"id": "d", "text": "Small, frequent meals"}]'::jsonb, '["d"]', 'Small, frequent meals help prevent dumping syndrome. Large meals and desserts contradict portion control and the avoidance of simple sugars.'),
  ('roux_en_y', 45, 'One year after Roux-en-Y gastric bypass, a client who feels well asks to stop taking vitamin B12. Which response by the nurse is best?', '[{"id": "a", "text": "Supplementation is needed long term, so continue it."}, {"id": "b", "text": "You may stop once your weight has stabilized."}, {"id": "c", "text": "You can stop as long as you eat plenty of protein."}, {"id": "d", "text": "You can take it only on days you feel tired."}]'::jsonb, '["a"]', 'Long-term supplementation is required, and vitamin B12 is among the nutrients needed for life. Stopping because the client feels well or weight is stable is incorrect.'),
  ('roux_en_y', 46, 'A client on stage 1 clear liquids after Roux-en-Y gastric bypass asks for yogurt. The nurse explains that yogurt is introduced at which stage?', '[{"id": "a", "text": "Stage 1 — Clear liquids"}, {"id": "b", "text": "Stage 4 — Regular diet"}, {"id": "c", "text": "Stage 2 — Full liquids and pureed foods"}, {"id": "d", "text": "Stage 3 — Soft foods"}]'::jsonb, '["c"]', 'Yogurt is part of stage 2, full liquids and pureed foods, along with high-protein shakes and pureed meats. Stage 3 soft foods include eggs, tender fish, and soft vegetables.'),
  ('roux_en_y', 47, 'A client who had Roux-en-Y gastric bypass asks for a between-meal option. Which choice is most appropriate?', '[{"id": "a", "text": "A candy bar"}, {"id": "b", "text": "A high-protein shake"}, {"id": "c", "text": "Sweetened fruit juice"}, {"id": "d", "text": "A slice of cake"}]'::jsonb, '["b"]', 'A high-protein, low-carbohydrate choice helps prevent dumping, and simple sugars should be avoided. Candy, juice, and cake are high-sugar foods.'),
  ('roux_en_y', 48, 'A client who had Roux-en-Y gastric bypass eats lunch at noon. If early dumping occurs, when would the nurse expect symptoms to begin?', '[{"id": "a", "text": "Between 1:00 and 3:00 PM"}, {"id": "b", "text": "Before the meal begins"}, {"id": "c", "text": "Around 6:00 PM"}, {"id": "d", "text": "Between 12:10 and 12:30 PM"}]'::jsonb, '["d"]', 'Early dumping occurs 10-30 minutes after eating. Symptoms 1-3 hours after eating describe late dumping.'),
  ('roux_en_y', 49, 'A nursing student is describing Roux-en-Y gastric bypass. Which statement by the student requires correction?', '[{"id": "a", "text": "It is a purely restrictive procedure."}, {"id": "b", "text": "It creates a small gastric pouch."}, {"id": "c", "text": "It bypasses the duodenum."}, {"id": "d", "text": "It connects the pouch to the jejunum."}]'::jsonb, '["a"]', 'Roux-en-Y combines restrictive and malabsorptive mechanisms, so calling it purely restrictive is incorrect. Creating a small pouch, bypassing the duodenum, and connecting the pouch to the jejunum are accurate.'),
  ('roux_en_y', 50, 'A client asks which symptoms would suggest early dumping after Roux-en-Y gastric bypass. Which findings should the nurse describe?', '[{"id": "a", "text": "Confusion and weakness 2 hours after eating"}, {"id": "b", "text": "Dizziness and tachycardia soon after eating"}, {"id": "c", "text": "Fever and shoulder pain days after surgery"}, {"id": "d", "text": "Hunger and sweating the next morning"}]'::jsonb, '["b"]', 'Early dumping (10-30 minutes) includes nausea, cramping, diarrhea, dizziness, and tachycardia. Confusion and weakness 1-3 hours later reflect late dumping with hypoglycemia.'),
  ('dumping', 1, 'The nurse is caring for four post-op clients. Which client is at greatest risk for dumping syndrome?', '[{"id": "a", "text": "A client after a Billroth II procedure"}, {"id": "b", "text": "A client after an appendectomy"}, {"id": "c", "text": "A client after a knee replacement"}, {"id": "d", "text": "A client after a thyroidectomy"}]'::jsonb, '["a"]', 'Gastric surgery such as Billroth I or II is a common cause of dumping syndrome. The other procedures do not involve the stomach.'),
  ('dumping', 2, 'A client reports cramping and diarrhea soon after meals. Which item in the client''s surgical history is a recognized cause of dumping syndrome?', '[{"id": "a", "text": "Cholecystectomy"}, {"id": "b", "text": "Appendectomy"}, {"id": "c", "text": "Vagotomy"}, {"id": "d", "text": "Hernia repair"}]'::jsonb, '["c"]', 'Vagotomy is listed among the common causes of dumping syndrome, along with gastric surgery and pyloric sphincter damage. The other procedures are not listed causes.'),
  ('dumping', 3, 'A client who had the pyloric sphincter removed asks how this relates to dumping syndrome. Which response by the nurse is accurate?', '[{"id": "a", "text": "The pylorus produces insulin, so blood sugar drops."}, {"id": "b", "text": "The pylorus is the valve between the stomach and small intestine."}, {"id": "c", "text": "The pylorus controls the release of bile into the colon."}, {"id": "d", "text": "The pylorus keeps fluid from leaving the small intestine."}]'::jsonb, '["b"]', 'The pyloric sphincter is the valve between the stomach and small intestine, and its removal or damage is a cause of dumping syndrome. Without it, food can move too quickly into the small intestine.'),
  ('dumping', 4, 'Which statement by a client indicates understanding of dumping syndrome?', '[{"id": "a", "text": "Food stays in my stomach too long after I eat."}, {"id": "b", "text": "Food moves too slowly through my small intestine."}, {"id": "c", "text": "Food backs up from my stomach into my esophagus."}, {"id": "d", "text": "Food moves too quickly from my stomach to my small intestine."}]'::jsonb, '["d"]', 'Dumping syndrome occurs when food moves too quickly from the stomach to the small intestine after eating. Food staying in the stomach too long describes the opposite problem.'),
  ('dumping', 5, 'A client with dumping syndrome develops tachycardia and dizziness 20 minutes after a meal. Which mechanism explains these findings?', '[{"id": "a", "text": "Fluid shifts into the intestine, causing hypovolemia"}, {"id": "b", "text": "An insulin surge causes hypoglycemia"}, {"id": "c", "text": "Food remains in the stomach too long"}, {"id": "d", "text": "Fluid shifts out of the intestine into the blood"}]'::jsonb, '["a"]', 'Undigested stomach contents dump into the small intestine, causing an osmotic fluid shift into the intestine and hypovolemia. An insulin surge with hypoglycemia causes late dumping 1-3 hours after eating.'),
  ('dumping', 6, 'The nurse is teaching a client with dumping syndrome about symptom timing. When do symptoms of early dumping usually occur?', '[{"id": "a", "text": "Shortly before a meal"}, {"id": "b", "text": "1 to 3 hours after eating"}, {"id": "c", "text": "15 to 30 minutes after eating"}, {"id": "d", "text": "6 to 8 hours after eating"}]'::jsonb, '["c"]', 'Early dumping occurs 15-30 minutes after eating. Symptoms 1-3 hours after eating describe late dumping.'),
  ('dumping', 7, 'A client with dumping syndrome asks when late dumping symptoms usually appear. Which response is accurate?', '[{"id": "a", "text": "15 to 30 minutes after eating"}, {"id": "b", "text": "1 to 3 hours after eating"}, {"id": "c", "text": "8 to 12 hours after eating"}, {"id": "d", "text": "Only during the night"}]'::jsonb, '["b"]', 'Late dumping occurs 1-3 hours after eating. Symptoms at 15-30 minutes describe early dumping.'),
  ('dumping', 8, 'A client who had a Billroth I procedure reports diarrhea, nausea, sweating, and a rapid heart rate 20 minutes after lunch. The nurse recognizes these findings as which problem?', '[{"id": "a", "text": "Late dumping syndrome"}, {"id": "b", "text": "Hypoglycemia"}, {"id": "c", "text": "Expected digestion"}, {"id": "d", "text": "Early dumping syndrome"}]'::jsonb, '["d"]', 'Nausea, diarrhea, tachycardia, and sweating 15-30 minutes after a meal are early dumping symptoms caused by a fluid shift. Hypoglycemia is the main problem in late dumping, 1-3 hours after eating.'),
  ('dumping', 9, 'Two hours after eating a slice of cake, a client with a history of gastric surgery reports weakness, confusion, and hunger. Which problem should the nurse suspect?', '[{"id": "a", "text": "Late dumping syndrome"}, {"id": "b", "text": "Early dumping syndrome"}, {"id": "c", "text": "Fluid volume excess"}, {"id": "d", "text": "Delayed gastric emptying"}]'::jsonb, '["a"]', 'Weakness, confusion, sweating, and hunger 1-3 hours after eating are late dumping symptoms caused by hypoglycemia. Early dumping occurs 15-30 minutes after a meal.'),
  ('dumping', 10, 'A client reports weakness, sweating, and confusion 2 hours after a meal following gastric surgery. Which action should the nurse take first?', '[{"id": "a", "text": "Have the client drink a large glass of water"}, {"id": "b", "text": "Have the client walk in the hallway"}, {"id": "c", "text": "Check the client''s blood glucose"}, {"id": "d", "text": "Wait to see if symptoms resolve"}]'::jsonb, '["c"]', 'Late dumping symptoms 2-3 hours after a meal call for checking blood glucose because the problem is hypoglycemia. Water and walking do not identify or treat hypoglycemia.'),
  ('dumping', 11, 'The nurse is reviewing the pathophysiology of dumping syndrome. Which explains the cause of late dumping?', '[{"id": "a", "text": "Osmotic fluid shift into the intestine"}, {"id": "b", "text": "Rapid sugar absorption causing an insulin surge"}, {"id": "c", "text": "Slow gastric emptying of fatty foods"}, {"id": "d", "text": "Drinking fluids between meals"}]'::jsonb, '["b"]', 'Late dumping results from rapid sugar absorption, which triggers an insulin surge and hypoglycemia. An osmotic fluid shift causes early dumping.'),
  ('dumping', 12, 'A client experiencing late dumping syndrome has a low blood glucose reading. Which intervention is appropriate?', '[{"id": "a", "text": "Withhold all food until the next meal"}, {"id": "b", "text": "Recline the client and restrict fluids"}, {"id": "c", "text": "Encourage fluids with the next meal"}, {"id": "d", "text": "Provide glucose as needed"}]'::jsonb, '["d"]', 'Treatment for late dumping is glucose if needed and keeping a small snack on hand. Reclining and avoiding liquids with meals are treatments for early dumping.'),
  ('dumping', 13, 'Which teaching helps a client manage late-phase dumping syndrome at home?', '[{"id": "a", "text": "Keep a small snack handy"}, {"id": "b", "text": "Drink juice with every meal"}, {"id": "c", "text": "Eat one large meal each day"}, {"id": "d", "text": "Avoid all protein foods"}]'::jsonb, '["a"]', 'In the late phase, the client watches for hypoglycemia and keeps a small snack handy. Juice is a simple sugar and fluids should not be taken with meals.'),
  ('dumping', 14, 'Which diet should the nurse recommend for a client with dumping syndrome?', '[{"id": "a", "text": "Low-protein, high-carbohydrate meals"}, {"id": "b", "text": "High-carbohydrate, low-fat meals"}, {"id": "c", "text": "High-protein, low-carbohydrate meals"}, {"id": "d", "text": "Clear liquids with every meal"}]'::jsonb, '["c"]', 'High-protein, low-carbohydrate meals are recommended for dumping syndrome. High-carbohydrate meals and fluids with meals worsen symptoms.'),
  ('dumping', 15, 'Which breakfast is most appropriate for a client with dumping syndrome?', '[{"id": "a", "text": "Orange juice and a sweet roll"}, {"id": "b", "text": "Eggs with lean meat"}, {"id": "c", "text": "Soda and a frosted pastry"}, {"id": "d", "text": "Sweetened cereal with juice"}]'::jsonb, '["b"]', 'A high-protein, low-carbohydrate breakfast is appropriate. Juice, soda, and sweets are simple sugars that should be avoided.'),
  ('dumping', 16, 'Which statement by a client with dumping syndrome indicates a need for further teaching?', '[{"id": "a", "text": "I''ll eat several small meals during the day."}, {"id": "b", "text": "I''ll include protein at every meal."}, {"id": "c", "text": "I''ll eat slowly and chew my food well."}, {"id": "d", "text": "I''ll have a glass of juice as my afternoon snack."}]'::jsonb, '["d"]', 'Juice is a simple sugar that should be avoided. Small frequent meals, protein, and eating slowly are correct strategies.'),
  ('dumping', 17, 'A client with dumping syndrome usually eats three large meals daily. Which change should the nurse recommend?', '[{"id": "a", "text": "Eat small, frequent meals"}, {"id": "b", "text": "Eat one large meal at night"}, {"id": "c", "text": "Skip breakfast and lunch"}, {"id": "d", "text": "Eat two large meals instead"}]'::jsonb, '["a"]', 'Small, frequent meals are recommended for dumping syndrome. Fewer, larger meals do not follow this teaching.'),
  ('dumping', 18, 'A client asks why adding protein and fat to meals helps with dumping syndrome. Which response is accurate?', '[{"id": "a", "text": "They speed movement of food into the intestine."}, {"id": "b", "text": "They raise blood sugar quickly after meals."}, {"id": "c", "text": "They delay emptying of the stomach."}, {"id": "d", "text": "They increase fluid shift into the intestine."}]'::jsonb, '["c"]', 'Adding fat and protein delays gastric emptying. Speeding food into the intestine is what causes dumping syndrome.'),
  ('dumping', 19, 'The nurse is teaching a client with dumping syndrome about fluids. Which instruction is correct?', '[{"id": "a", "text": "Drink a large glass of water with each meal"}, {"id": "b", "text": "Wait 30 to 60 minutes after eating to drink"}, {"id": "c", "text": "Drink fluids only while eating"}, {"id": "d", "text": "Drink fluids as soon as each meal ends"}]'::jsonb, '["b"]', 'No fluids should be taken with meals; the client waits 30-60 minutes after eating to drink. Drinking with or immediately after meals contradicts this teaching.'),
  ('dumping', 20, 'Which statement about fluids by a client with dumping syndrome indicates a need for further teaching?', '[{"id": "a", "text": "I''ll drink between meals instead of with them."}, {"id": "b", "text": "I''ll wait at least 30 minutes after eating to drink."}, {"id": "c", "text": "I''ll avoid soda and fruit juice."}, {"id": "d", "text": "I''ll drink a full glass of water with lunch."}]'::jsonb, '["d"]', 'No fluids should be taken with meals, so drinking water with lunch needs correction. Waiting 30-60 minutes after eating and avoiding soda and juice are correct.'),
  ('dumping', 21, 'A client with dumping syndrome has just finished lunch. Which position should the nurse recommend?', '[{"id": "a", "text": "Reclining in semi-Fowler''s position"}, {"id": "b", "text": "Sitting upright in a chair"}, {"id": "c", "text": "Standing and walking in the hall"}, {"id": "d", "text": "Sitting on the edge of the bed"}]'::jsonb, '["a"]', 'Reclining in semi-Fowler''s position or lying down for 30-60 minutes after meals slows gastric emptying. Upright positions and walking do not provide this benefit.'),
  ('dumping', 22, 'Which action by a UAP caring for a client with dumping syndrome requires correction?', '[{"id": "a", "text": "Helping the client recline after a meal"}, {"id": "b", "text": "Offering fluids between meals"}, {"id": "c", "text": "Walking the client in the hall right after lunch"}, {"id": "d", "text": "Serving small, frequent high-protein meals"}]'::jsonb, '["c"]', 'The client should recline for 30-60 minutes after meals to slow gastric emptying, so walking right after lunch needs correction. Fluids between meals and small high-protein meals are appropriate.'),
  ('dumping', 23, 'A client asks why lying down after meals is recommended for dumping syndrome. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It speeds food into the small intestine."}, {"id": "b", "text": "It slows gastric emptying."}, {"id": "c", "text": "It raises blood glucose levels."}, {"id": "d", "text": "It increases fluid shift into the intestine."}]'::jsonb, '["b"]', 'Reclining after meals slows gastric emptying. Speeding food into the small intestine and increasing fluid shift are what cause dumping symptoms.'),
  ('dumping', 24, 'Which eating behavior should the nurse teach a client with dumping syndrome?', '[{"id": "a", "text": "Eat quickly to finish before symptoms start"}, {"id": "b", "text": "Swallow food with large sips of fluid"}, {"id": "c", "text": "Eat one large meal to limit episodes"}, {"id": "d", "text": "Eat slowly and chew food thoroughly"}]'::jsonb, '["d"]', 'Clients are taught to eat slowly and chew thoroughly. Taking fluids with meals and eating large meals worsen dumping.'),
  ('dumping', 25, 'A client with dumping syndrome asks about adding fiber to the diet. Which response is accurate?', '[{"id": "a", "text": "Fiber such as pectin can slow digestion."}, {"id": "b", "text": "Fiber speeds emptying of the stomach."}, {"id": "c", "text": "Fiber causes a surge of insulin."}, {"id": "d", "text": "Fiber should be taken with fluids at meals."}]'::jsonb, '["a"]', 'Adding fiber such as pectin slows digestion. Fluids should not be taken with meals.'),
  ('dumping', 26, 'Which finding is more consistent with late dumping than with early dumping?', '[{"id": "a", "text": "Diarrhea and bloating"}, {"id": "b", "text": "Cramping and nausea"}, {"id": "c", "text": "Confusion and hunger"}, {"id": "d", "text": "Bloating and tachycardia"}]'::jsonb, '["c"]', 'Late dumping causes hypoglycemia symptoms such as weakness, confusion, sweating, and hunger. Diarrhea, bloating, cramping, nausea, and tachycardia are early dumping symptoms.'),
  ('dumping', 27, 'A client reports symptoms after a meal. Which finding is more consistent with early dumping than with late dumping?', '[{"id": "a", "text": "Hunger"}, {"id": "b", "text": "Diarrhea"}, {"id": "c", "text": "Confusion"}, {"id": "d", "text": "Weakness"}]'::jsonb, '["b"]', 'Diarrhea is an early dumping symptom caused by fluid shift into the intestine. Hunger, confusion, and weakness are late dumping symptoms of hypoglycemia.'),
  ('dumping', 28, 'Which statement by a client indicates that teaching about dumping syndrome has been effective?', '[{"id": "a", "text": "I drink a big glass of juice with breakfast."}, {"id": "b", "text": "I eat three large meals so I''m not hungry."}, {"id": "c", "text": "I go for a brisk walk right after every meal."}, {"id": "d", "text": "I wait at least 30 minutes after eating to drink."}]'::jsonb, '["d"]', 'Waiting 30-60 minutes after eating to drink reflects correct teaching. Juice is a simple sugar, large meals are discouraged, and reclining rather than walking is recommended after meals.'),
  ('dumping', 29, 'Which set of interventions is appropriate for early dumping syndrome?', '[{"id": "a", "text": "Recline, dietary changes, and no liquids with meals"}, {"id": "b", "text": "Glucose if needed and a small snack on hand"}, {"id": "c", "text": "Large meals with fluids to slow digestion"}, {"id": "d", "text": "Walking after meals and adding sweets"}]'::jsonb, '["a"]', 'Early dumping is treated by reclining, dietary changes, and no liquids with meals. Glucose and a small snack are the treatment for late dumping.'),
  ('dumping', 30, 'Which pairing correctly matches each phase of dumping syndrome with its main problem?', '[{"id": "a", "text": "Early: hypoglycemia; late: fluid shift"}, {"id": "b", "text": "Early: hyperglycemia; late: fluid shift"}, {"id": "c", "text": "Early: fluid shift; late: hypoglycemia"}, {"id": "d", "text": "Early: fluid shift; late: hyperglycemia"}]'::jsonb, '["c"]', 'Early dumping is caused by an osmotic fluid shift into the intestine, and late dumping by rapid sugar absorption leading to hypoglycemia. Reversing the phases or naming hyperglycemia is incorrect.'),
  ('dumping', 31, 'A client 6 weeks after Roux-en-Y gastric bypass reports nausea, diarrhea, and diaphoresis shortly after meals. How should the nurse view the client''s surgical history?', '[{"id": "a", "text": "It is unrelated to these symptoms"}, {"id": "b", "text": "It is a common cause of dumping syndrome"}, {"id": "c", "text": "It causes delayed gastric emptying"}, {"id": "d", "text": "It protects against dumping syndrome"}]'::jsonb, '["b"]', 'Roux-en-Y gastric bypass is a gastric surgery listed as a common cause of dumping syndrome. Dumping involves food moving too quickly, not delayed emptying.'),
  ('dumping', 32, 'A client with dumping syndrome asks which type of food most often triggers it. Which response is accurate?', '[{"id": "a", "text": "Lean proteins"}, {"id": "b", "text": "Foods high in fat"}, {"id": "c", "text": "High-fiber foods"}, {"id": "d", "text": "Foods high in sugar"}]'::jsonb, '["d"]', 'Dumping syndrome occurs when food, especially sugars, moves too quickly into the small intestine. Protein, fat, and fiber are added to slow emptying and digestion.'),
  ('dumping', 33, 'The nurse is reviewing a client''s history for risk factors for dumping syndrome. Which finding is listed among the common causes?', '[{"id": "a", "text": "Increased gastric motility"}, {"id": "b", "text": "Decreased gastric motility"}, {"id": "c", "text": "A high-protein diet"}, {"id": "d", "text": "Reclining after meals"}]'::jsonb, '["a"]', 'Increased gastric motility is a common cause of dumping syndrome. A high-protein diet and reclining after meals are used to manage it.'),
  ('dumping', 34, 'The nurse is assessing a client with suspected dumping syndrome after gastric surgery. Which group of findings should the nurse expect?', '[{"id": "a", "text": "Constipation and abdominal distention"}, {"id": "b", "text": "Bradycardia and dry skin"}, {"id": "c", "text": "Nausea, bloating, and diarrhea"}, {"id": "d", "text": "Hyperglycemia and thirst"}]'::jsonb, '["c"]', 'Signs of dumping syndrome include nausea, bloating, diarrhea, sweating, and tachycardia. Bradycardia, dry skin, constipation, and hyperglycemia run opposite to the expected findings.'),
  ('dumping', 35, 'Which lunch is most appropriate for a client with dumping syndrome?', '[{"id": "a", "text": "A sandwich with a cola"}, {"id": "b", "text": "Grilled chicken and vegetables"}, {"id": "c", "text": "Cookies and sweetened tea"}, {"id": "d", "text": "Pasta with fruit juice"}]'::jsonb, '["b"]', 'High-protein, low-carbohydrate meals are recommended. Cola, cookies, sweetened tea, and juice are simple sugars to avoid.'),
  ('dumping', 36, 'Which client statement shows understanding of why sugary foods should be avoided with dumping syndrome?', '[{"id": "a", "text": "Sugar slows how fast my stomach empties."}, {"id": "b", "text": "Sugar keeps fluid from moving into my intestine."}, {"id": "c", "text": "Sugar keeps my blood glucose from rising."}, {"id": "d", "text": "Sugar can trigger an insulin surge that drops my glucose."}]'::jsonb, '["d"]', 'Rapid sugar absorption causes an insulin surge that leads to hypoglycemia in late dumping. Sugar does not slow gastric emptying; foods with sugar move too quickly.'),
  ('dumping', 37, 'A client with dumping syndrome reports feeling faint after meals. How should the nurse interpret this report?', '[{"id": "a", "text": "It is a recognized symptom of dumping syndrome"}, {"id": "b", "text": "It rules out dumping syndrome as the cause"}, {"id": "c", "text": "It is an expected response to protein intake"}, {"id": "d", "text": "It indicates too much fiber in the diet"}]'::jsonb, '["a"]', 'Weakness, dizziness, and fainting are recognized signs of dumping syndrome. Protein and fiber are recommended to slow emptying and digestion.'),
  ('dumping', 38, 'A client with dumping syndrome eats lunch at noon. At what time would late dumping symptoms most likely occur?', '[{"id": "a", "text": "12:05 PM"}, {"id": "b", "text": "12:20 PM"}, {"id": "c", "text": "2:00 PM"}, {"id": "d", "text": "7:00 PM"}]'::jsonb, '["c"]', 'Late dumping occurs 1-3 hours after eating, so 2:00 PM fits. Symptoms at 12:20 PM would fall in the early dumping window of 15-30 minutes.'),
  ('dumping', 39, 'A client with dumping syndrome finishes breakfast at 8:00 AM. If early dumping occurs, at what time would symptoms most likely begin?', '[{"id": "a", "text": "7:45 AM"}, {"id": "b", "text": "8:20 AM"}, {"id": "c", "text": "10:30 AM"}, {"id": "d", "text": "1:00 PM"}]'::jsonb, '["b"]', 'Early dumping occurs 15-30 minutes after eating, so 8:20 AM fits. Symptoms 1-3 hours after eating describe late dumping.'),
  ('dumping', 40, 'A client reports palpitations, dizziness, and diarrhea right after meals. The nurse attributes these symptoms to which cause?', '[{"id": "a", "text": "Hypoglycemia from an insulin surge"}, {"id": "b", "text": "Slow emptying of the stomach"}, {"id": "c", "text": "Rapid sugar absorption hours later"}, {"id": "d", "text": "A fluid shift into the intestine"}]'::jsonb, '["d"]', 'Dizziness, palpitations, and diarrhea right after meals (15-30 minutes) reflect early dumping from a fluid shift. Hypoglycemia from an insulin surge causes late dumping.'),
  ('dumping', 41, 'Which statement by a client with dumping syndrome indicates a need for further teaching about positioning?', '[{"id": "a", "text": "I''ll sit straight up for an hour after eating."}, {"id": "b", "text": "I''ll lie down for 30 minutes after I eat."}, {"id": "c", "text": "I''ll recline in my chair after meals."}, {"id": "d", "text": "I''ll rest in a semi-Fowler''s position after lunch."}]'::jsonb, '["a"]', 'Reclining in semi-Fowler''s position or lying down for 30-60 minutes after meals slows gastric emptying, so sitting straight up needs correction. The other statements describe correct positioning.'),
  ('dumping', 42, 'A client with dumping syndrome asks for a drink between meals. Which choice is most appropriate?', '[{"id": "a", "text": "Regular soda"}, {"id": "b", "text": "Sweetened fruit juice"}, {"id": "c", "text": "Water"}, {"id": "d", "text": "Sweet tea"}]'::jsonb, '["c"]', 'Simple sugars such as juice, soda, and sweets should be avoided. Water does not contain simple sugars, and taking fluids between meals follows the teaching.'),
  ('dumping', 43, 'The fluid shift that occurs in early dumping syndrome can lead to which problem?', '[{"id": "a", "text": "Fluid volume excess"}, {"id": "b", "text": "Hypovolemia"}, {"id": "c", "text": "Hyperglycemia"}, {"id": "d", "text": "Constipation"}]'::jsonb, '["b"]', 'Stomach contents dump into the small intestine, causing an osmotic fluid shift into the intestine and hypovolemia. Diarrhea, not constipation, is a symptom.'),
  ('dumping', 44, 'Which daily meal plan shows that a client understands dumping syndrome teaching?', '[{"id": "a", "text": "Three large meals with juice"}, {"id": "b", "text": "Two large meals and a dessert"}, {"id": "c", "text": "One large meal with soda"}, {"id": "d", "text": "Six small high-protein meals"}]'::jsonb, '["d"]', 'Small, frequent, high-protein meals are recommended. Large meals with juice, soda, or desserts include simple sugars and larger portions.'),
  ('dumping', 45, 'Which dietary addition can help slow digestion in a client with dumping syndrome?', '[{"id": "a", "text": "Pectin"}, {"id": "b", "text": "Soda"}, {"id": "c", "text": "Candy"}, {"id": "d", "text": "Fruit juice"}]'::jsonb, '["a"]', 'Fiber such as pectin is added to slow digestion. Soda, candy, and juice are simple sugars to avoid.'),
  ('dumping', 46, 'A client with dumping syndrome eats meals high in simple carbohydrates. To delay gastric emptying, which change should the nurse suggest?', '[{"id": "a", "text": "Add more fruit juice"}, {"id": "b", "text": "Add more sweets"}, {"id": "c", "text": "Add protein and fat"}, {"id": "d", "text": "Add fluids with meals"}]'::jsonb, '["c"]', 'Adding fat and protein delays gastric emptying. Juice and sweets are simple sugars, and fluids should not be taken with meals.'),
  ('dumping', 47, 'The nurse observes a client with dumping syndrome eating rapidly. Which instruction is appropriate?', '[{"id": "a", "text": "Finish meals quickly to avoid symptoms"}, {"id": "b", "text": "Eat slowly and chew food thoroughly"}, {"id": "c", "text": "Drink fluids to wash the food down"}, {"id": "d", "text": "Eat a large meal and then rest"}]'::jsonb, '["b"]', 'Clients with dumping syndrome should eat slowly and chew thoroughly. Drinking fluids with meals and eating large meals worsen symptoms.'),
  ('dumping', 48, 'A client asks when dumping syndrome is most likely to develop. Which response by the nurse is accurate?', '[{"id": "a", "text": "After eating a high-protein meal"}, {"id": "b", "text": "During periods of fasting"}, {"id": "c", "text": "After any minor skin procedure"}, {"id": "d", "text": "After surgery on the stomach"}]'::jsonb, '["d"]', 'Dumping syndrome occurs particularly after gastric surgery. High-protein meals are recommended to manage it, not a cause of it.'),
  ('dumping', 49, 'A client with a history of gastric surgery calls reporting confusion and sweating 2 hours after eating a sugary dessert. Which instruction should the nurse give first?', '[{"id": "a", "text": "Check your blood glucose now"}, {"id": "b", "text": "Lie down and drink water"}, {"id": "c", "text": "Walk to improve circulation"}, {"id": "d", "text": "Wait until your next meal"}]'::jsonb, '["a"]', 'Symptoms 2-3 hours after a meal suggest late dumping, so blood glucose should be checked for hypoglycemia. Lying down and avoiding fluids with meals address early dumping, not low glucose.'),
  ('dumping', 50, 'Removal or damage of which structure increases a client''s risk for dumping syndrome?', '[{"id": "a", "text": "Lower esophageal sphincter"}, {"id": "b", "text": "Ileocecal valve"}, {"id": "c", "text": "Pyloric sphincter"}, {"id": "d", "text": "Anal sphincter"}]'::jsonb, '["c"]', 'Removal or damage of the pyloric sphincter, the valve between the stomach and small intestine, is a common cause of dumping syndrome. The other structures are not listed causes.'),
  ('gerd', 1, 'A client newly diagnosed with gastroesophageal reflux disease (GERD) asks what is causing the symptoms. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The lower esophageal sphincter is weak or overly relaxed, so acid backs up."}, {"id": "b", "text": "The stomach is not producing enough acid to digest food completely."}, {"id": "c", "text": "The esophagus is narrowed at the top, so food cannot pass easily."}, {"id": "d", "text": "The upper airway is not closing, so food enters the windpipe."}]'::jsonb, '["a"]', 'GERD is caused by a weak or overly relaxed lower esophageal sphincter (LES), which lets stomach acid flow back into the esophagus. The problem is acid flowing backward, not too little acid or a narrowed upper esophagus.'),
  ('gerd', 2, 'A client who is 30 weeks pregnant reports new heartburn and asks why pregnancy causes reflux. Which response by the nurse is accurate?', '[{"id": "a", "text": "Pregnancy increases protective mucus in the stomach."}, {"id": "b", "text": "Hormonal changes and increased pressure both promote reflux."}, {"id": "c", "text": "Pregnancy tightens the lower esophageal sphincter and traps acid."}, {"id": "d", "text": "Pregnancy lowers stomach acid, so food sits in the esophagus."}]'::jsonb, '["b"]', 'Pregnancy is a GERD trigger because of hormones plus increased pressure. Anything that relaxes the LES or increases stomach pressure can trigger GERD; a tightened sphincter would not cause reflux.'),
  ('gerd', 3, 'A client with GERD drinks two glasses of wine every evening and says, "Wine can''t affect my reflux because it isn''t spicy." Which response by the nurse is best?', '[{"id": "a", "text": "Alcohol matters only when it is taken with spicy foods."}, {"id": "b", "text": "Alcohol is a concern only for clients who also smoke."}, {"id": "c", "text": "Alcohol relaxes the lower esophageal sphincter and can trigger reflux."}, {"id": "d", "text": "Alcohol coats the esophagus and protects it from stomach acid."}]'::jsonb, '["c"]', 'Smoking and alcohol each relax the LES, so alcohol is a GERD trigger on its own. It does not need to be combined with spicy food or smoking to worsen reflux.'),
  ('gerd', 4, 'The nurse teaches an obese client with GERD about weight loss. Which client statement indicates understanding of why weight loss helps?', '[{"id": "a", "text": "Losing weight will strengthen the lining of my stomach."}, {"id": "b", "text": "Losing weight matters less than taking antacids every night."}, {"id": "c", "text": "Losing weight will help only if I also stop eating all fruit."}, {"id": "d", "text": "Losing weight will lower the extra abdominal pressure that promotes reflux."}]'::jsonb, '["d"]', 'Obesity is a GERD trigger because of extra abdominal pressure, and losing weight is a first-line lifestyle change. Lifestyle changes come before medications, so relying on antacids instead is incorrect.'),
  ('gerd', 5, 'A client with GERD reports eating one very large meal each evening. Which recommendation should the nurse make?', '[{"id": "a", "text": "Eat small, frequent meals throughout the day."}, {"id": "b", "text": "Eat the large meal earlier, then lie down to rest."}, {"id": "c", "text": "Skip breakfast and lunch to reduce stomach acid."}, {"id": "d", "text": "Eat the large meal faster to shorten digestion."}]'::jsonb, '["a"]', 'Large meals are a GERD trigger, so the nurse encourages small, frequent meals. Lying down after eating is also discouraged, which makes the second option unsafe.'),
  ('gerd', 6, 'When assessing a client with suspected GERD, which description of heartburn would the nurse expect the client to report?', '[{"id": "a", "text": "Burning chest pain that improves when lying flat"}, {"id": "b", "text": "Burning chest pain that worsens after eating or lying down"}, {"id": "c", "text": "Burning chest pain that occurs only during fasting"}, {"id": "d", "text": "Burning chest pain that is relieved by a large meal"}]'::jsonb, '["b"]', 'GERD heartburn is burning chest pain that is worse after eating or lying down. Lying flat and large meals worsen reflux rather than relieve it.'),
  ('gerd', 7, 'A client with long-standing GERD reports a hoarse voice for several weeks. The nurse recognizes this finding as most likely related to:', '[{"id": "a", "text": "Narrowing of the esophagus from scarring"}, {"id": "b", "text": "Slowed gastric emptying from medications"}, {"id": "c", "text": "Vocal cord irritation from refluxed acid"}, {"id": "d", "text": "A magnetic ring placed around the sphincter"}]'::jsonb, '["c"]', 'Hoarseness is a GERD symptom caused by vocal cord irritation from reflux. Esophageal narrowing (stricture) causes dysphagia, not hoarseness.'),
  ('gerd', 8, 'Which group of findings would the nurse expect when assessing a client with GERD?', '[{"id": "a", "text": "Jaundice, clay-colored stools, and dark urine"}, {"id": "b", "text": "Excessive thirst, frequent urination, and hunger"}, {"id": "c", "text": "Right lower quadrant pain, fever, and rebound pain"}, {"id": "d", "text": "Bitter taste, bad breath, and chronic sore throat"}]'::jsonb, '["d"]', 'GERD symptoms include a bitter taste in the mouth, bad breath (halitosis), and chronic cough or sore throat. The other groups are not GERD symptoms.'),
  ('gerd', 9, 'The nurse is screening clients at a health fair. Which client report most strongly suggests GERD?', '[{"id": "a", "text": "I get heartburn every few months after a big holiday meal."}, {"id": "b", "text": "I have heartburn three or four times every week."}, {"id": "c", "text": "I had heartburn one time last year after a spicy dinner."}, {"id": "d", "text": "I noticed heartburn once this month after drinking coffee."}]'::jsonb, '["b"]', 'Heartburn more than twice a week indicates likely GERD. Occasional heartburn after a trigger food, even a known trigger such as coffee or spicy food, does not meet that frequency.'),
  ('gerd', 10, 'A client with GERD is scheduled for a test to measure the strength of the lower esophageal sphincter. The nurse prepares the client for which test?', '[{"id": "a", "text": "Barium swallow X-ray"}, {"id": "b", "text": "24-hour pH monitoring"}, {"id": "c", "text": "Upper endoscopy (EGD)"}, {"id": "d", "text": "Manometry"}]'::jsonb, '["d"]', 'A manometry test measures LES muscle strength. 24-hour pH monitoring measures acid levels in the esophagus, not sphincter strength.'),
  ('gerd', 11, 'A client with GERD asks the purpose of the 24-hour pH monitoring that was ordered. Which response by the nurse is accurate?', '[{"id": "a", "text": "It measures acid levels in the esophagus."}, {"id": "b", "text": "It measures the strength of the sphincter muscle."}, {"id": "c", "text": "It uses a camera to look for esophageal ulcers."}, {"id": "d", "text": "It uses contrast liquid and X-rays to show reflux."}]'::jsonb, '["a"]', '24-hour pH monitoring measures acid levels in the esophagus. Sphincter strength is measured by manometry, and a camera exam is an EGD.'),
  ('gerd', 12, 'A client with long-standing GERD is suspected of having esophageal ulcers. Which test allows a camera to look directly at the esophagus for damage?', '[{"id": "a", "text": "Manometry"}, {"id": "b", "text": "Barium swallow X-ray"}, {"id": "c", "text": "Upper endoscopy (EGD)"}, {"id": "d", "text": "24-hour pH monitoring"}]'::jsonb, '["c"]', 'An EGD (upper endoscopy) uses a camera to look at the esophagus for damage or ulcers. A barium swallow uses contrast and X-ray rather than a camera.'),
  ('gerd', 13, 'A client with GERD is scheduled for a barium swallow and asks what the test involves. Which description should the nurse provide?', '[{"id": "a", "text": "A camera is passed into the esophagus to look for ulcers."}, {"id": "b", "text": "A contrast liquid is swallowed, and X-rays check for reflux."}, {"id": "c", "text": "A probe measures acid in the esophagus for a full day."}, {"id": "d", "text": "A pressure test measures how strongly the sphincter squeezes."}]'::jsonb, '["b"]', 'A barium swallow uses a contrast liquid plus X-ray to check for reflux. The camera exam describes an EGD, and the day-long acid probe describes pH monitoring.'),
  ('gerd', 14, 'A client with newly diagnosed GERD asks which treatment will be tried first. Which response by the nurse is accurate?', '[{"id": "a", "text": "Surgery to wrap the stomach around the esophagus"}, {"id": "b", "text": "A proton pump inhibitor taken before meals"}, {"id": "c", "text": "A magnetic ring placed around the sphincter"}, {"id": "d", "text": "Lifestyle changes such as avoiding trigger foods"}]'::jsonb, '["d"]', 'Lifestyle changes are first-line treatment for GERD and come before medications. PPIs are added after lifestyle changes, and surgery is reserved for GERD unresponsive to both.'),
  ('gerd', 15, 'A client with GERD finishes lunch at 1200 and wants to take a nap. Which is the earliest time the nurse should advise the client to lie down?', '[{"id": "a", "text": "1230"}, {"id": "b", "text": "1300"}, {"id": "c", "text": "1330"}, {"id": "d", "text": "1400"}]'::jsonb, '["d"]', 'Clients with GERD should not lie down for 2 to 3 hours after eating, so the earliest acceptable time is 1400. Lying down at 1230, 1300, or 1330 is less than 2 hours after the meal.'),
  ('gerd', 16, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with GERD. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raising the head of the bed before the client sleeps"}, {"id": "b", "text": "Offering the client several small meals during the day"}, {"id": "c", "text": "Assisting the client to lie flat right after dinner"}, {"id": "d", "text": "Encouraging the client to sit up in a chair after eating"}]'::jsonb, '["c"]', 'Clients with GERD should not lie down after eating and should wait 2 to 3 hours. Raising the head of the bed and offering small, frequent meals are correct GERD care.'),
  ('gerd', 17, 'A client with GERD reports reflux symptoms that wake them at night. Which bedtime instruction should the nurse give?', '[{"id": "a", "text": "Elevate the head of the bed."}, {"id": "b", "text": "Sleep flat without a pillow."}, {"id": "c", "text": "Eat a snack right before bed."}, {"id": "d", "text": "Lie down right after supper."}]'::jsonb, '["a"]', 'Elevating the head of the bed is a first-line lifestyle change for GERD. Sleeping flat or lying down soon after eating worsens heartburn.'),
  ('gerd', 18, 'The nurse reviews trigger foods with a client who has GERD. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I''ll stop ordering fried foods when I eat out."}, {"id": "b", "text": "I''ll choose smaller portions at each meal."}, {"id": "c", "text": "I''ll have coffee and chocolate cake for dessert."}, {"id": "d", "text": "I''ll quit smoking to help my symptoms improve."}]'::jsonb, '["c"]', 'Chocolate and caffeine are GERD trigger foods, so coffee with chocolate cake needs correction. Avoiding fried foods, eating smaller meals, and quitting smoking are correct lifestyle changes.'),
  ('gerd', 19, 'A client with GERD asks for help planning breakfast. Which item should the nurse suggest the client avoid?', '[{"id": "a", "text": "Oatmeal"}, {"id": "b", "text": "Orange juice"}, {"id": "c", "text": "Plain toast"}, {"id": "d", "text": "Rice cereal"}]'::jsonb, '["b"]', 'Citrus is a GERD trigger food, so orange juice should be avoided. The other choices are not spicy, fatty, fried, citrus, chocolate, caffeine, or alcohol.'),
  ('gerd', 20, 'Which dinner selection by a client with GERD indicates that diet teaching has been effective?', '[{"id": "a", "text": "Fried chicken with french fries"}, {"id": "b", "text": "Spicy beef tacos with hot salsa"}, {"id": "c", "text": "Baked fish with steamed rice"}, {"id": "d", "text": "Pepperoni pizza with extra sausage"}]'::jsonb, '["c"]', 'Spicy, fatty, and acidic foods trigger GERD, so baked fish with steamed rice is the best choice. Fried, spicy, and fatty meals are all triggers.'),
  ('gerd', 21, 'The health care provider prescribes pantoprazole once daily for a client with GERD. When should the nurse plan to give this medication?', '[{"id": "a", "text": "Before breakfast"}, {"id": "b", "text": "After breakfast"}, {"id": "c", "text": "With a bedtime snack"}, {"id": "d", "text": "Only when heartburn occurs"}]'::jsonb, '["a"]', 'Pantoprazole is a PPI, and PPIs work best before meals. Giving it after a meal or only as needed does not follow the recommended timing.'),
  ('gerd', 22, 'A client has taken omeprazole for GERD for several years. The nurse should teach the client about an increased risk for which complications?', '[{"id": "a", "text": "Tardive dyskinesia"}, {"id": "b", "text": "Osteoporosis and C. diff infection"}, {"id": "c", "text": "Esophageal strictures"}, {"id": "d", "text": "Electrolyte imbalances"}]'::jsonb, '["b"]', 'Long-term PPI use increases the risk of osteoporosis and C. diff infection. Tardive dyskinesia is a risk of metoclopramide, and electrolyte imbalances are linked to antacids.'),
  ('gerd', 23, 'Which statement by a client prescribed famotidine (Pepcid) for GERD indicates a need for further teaching?', '[{"id": "a", "text": "This medicine reduces the acid my stomach makes."}, {"id": "b", "text": "I should take this medicine before my meals."}, {"id": "c", "text": "This medicine is not as strong as a PPI."}, {"id": "d", "text": "I should take this medicine only after I eat."}]'::jsonb, '["d"]', 'Famotidine, an H2 blocker, should be taken before meals, so taking it only after eating needs correction. It reduces stomach acid and is less effective than PPIs.'),
  ('gerd', 24, 'A client with GERD asks whether famotidine works better than omeprazole. Which response by the nurse is accurate?', '[{"id": "a", "text": "Famotidine is more effective than omeprazole."}, {"id": "b", "text": "Famotidine and omeprazole work exactly the same way."}, {"id": "c", "text": "Famotidine is less effective than omeprazole."}, {"id": "d", "text": "Famotidine neutralizes acid faster than an antacid."}]'::jsonb, '["c"]', 'H2 blockers such as famotidine are less effective than PPIs such as omeprazole. Neutralizing acid is how antacids work, not H2 blockers.'),
  ('gerd', 25, 'A client uses Tums for occasional heartburn from GERD. Which statement about this medication is accurate?', '[{"id": "a", "text": "It acts quickly, but its relief is temporary."}, {"id": "b", "text": "It blocks acid production for a full day."}, {"id": "c", "text": "It speeds the emptying of the stomach."}, {"id": "d", "text": "It strengthens the lower esophageal sphincter."}]'::jsonb, '["a"]', 'Antacids such as Tums neutralize acid and act fast, but their effect is temporary. Blocking acid production describes PPIs, and speeding gastric emptying describes prokinetics.'),
  ('gerd', 26, 'A client with GERD reports taking Mylanta several times a day for weeks. The nurse should assess the client for which adverse effect?', '[{"id": "a", "text": "Tardive dyskinesia"}, {"id": "b", "text": "Osteoporosis"}, {"id": "c", "text": "Esophageal stricture"}, {"id": "d", "text": "Electrolyte imbalances"}]'::jsonb, '["d"]', 'Antacids such as Mylanta can cause electrolyte imbalances. Osteoporosis is a long-term PPI risk, and tardive dyskinesia is a metoclopramide risk.'),
  ('gerd', 27, 'A client with GERD is prescribed metoclopramide (Reglan) and asks how this drug helps. Which response by the nurse is accurate?', '[{"id": "a", "text": "It neutralizes acid already in the stomach."}, {"id": "b", "text": "It speeds the emptying of the stomach."}, {"id": "c", "text": "It blocks the production of stomach acid."}, {"id": "d", "text": "It forms a magnetic seal at the sphincter."}]'::jsonb, '["b"]', 'Metoclopramide is a prokinetic that speeds gastric emptying. Neutralizing acid describes antacids, and blocking acid production describes PPIs.'),
  ('gerd', 28, 'The nurse is caring for a client receiving metoclopramide for GERD. The nurse should monitor for which adverse effect associated with this medication?', '[{"id": "a", "text": "Osteoporosis"}, {"id": "b", "text": "C. diff infection"}, {"id": "c", "text": "Tardive dyskinesia"}, {"id": "d", "text": "Electrolyte imbalance"}]'::jsonb, '["c"]', 'Metoclopramide carries a risk of tardive dyskinesia. Osteoporosis and C. diff are long-term PPI risks, and electrolyte imbalance is an antacid risk.'),
  ('gerd', 29, 'The nurse reviews the medication list of a client with GERD. Which medication should the nurse identify as a proton pump inhibitor (PPI)?', '[{"id": "a", "text": "Famotidine"}, {"id": "b", "text": "Esomeprazole"}, {"id": "c", "text": "Metoclopramide"}, {"id": "d", "text": "Maalox"}]'::jsonb, '["b"]', 'Esomeprazole is a PPI, along with omeprazole and pantoprazole. Famotidine is an H2 blocker, metoclopramide is a prokinetic, and Maalox is an antacid.'),
  ('gerd', 30, 'A client with severe GERD is scheduled for a Nissen fundoplication. Which explanation of the procedure is accurate?', '[{"id": "a", "text": "A camera is passed to inspect the esophagus."}, {"id": "b", "text": "A magnetic ring is placed around the sphincter."}, {"id": "c", "text": "A contrast liquid is used to outline the esophagus."}, {"id": "d", "text": "The top of the stomach is wrapped around the esophagus."}]'::jsonb, '["d"]', 'Nissen fundoplication wraps the top of the stomach around the esophagus to strengthen the LES. A magnetic ring around the LES describes the LINX device.'),
  ('gerd', 31, 'A client with severe GERD asks about the LINX device. Which description by the nurse is accurate?', '[{"id": "a", "text": "A magnetic ring around the LES that prevents reflux"}, {"id": "b", "text": "A wrap of the upper stomach around the esophagus"}, {"id": "c", "text": "A probe that records esophageal acid for 24 hours"}, {"id": "d", "text": "A camera that inspects the esophagus for ulcers"}]'::jsonb, '["a"]', 'The LINX device is a magnetic ring placed around the LES to prevent reflux. Wrapping the stomach around the esophagus describes Nissen fundoplication.'),
  ('gerd', 32, 'Which client with GERD is the most appropriate candidate for surgical treatment?', '[{"id": "a", "text": "A client diagnosed last week who has not tried any treatment"}, {"id": "b", "text": "A client whose symptoms persist despite lifestyle changes and medications"}, {"id": "c", "text": "A client whose heartburn resolved after starting small, frequent meals"}, {"id": "d", "text": "A client who has heartburn once a month after eating spicy foods"}]'::jsonb, '["b"]', 'Surgery is reserved for GERD that does not respond to lifestyle changes and medications. A newly diagnosed client should start with lifestyle changes first.'),
  ('gerd', 33, 'A client with GERD is diagnosed with Barrett''s esophagus. Which follow-up should the nurse reinforce?', '[{"id": "a", "text": "Repeat manometry to measure sphincter strength"}, {"id": "b", "text": "A barium swallow only if hoarseness develops"}, {"id": "c", "text": "Regular endoscopy to monitor the esophagus"}, {"id": "d", "text": "No further testing once heartburn is controlled"}]'::jsonb, '["c"]', 'Barrett''s esophagus increases the risk of esophageal adenocarcinoma and needs regular endoscopy. Manometry measures LES strength and does not monitor the lining.'),
  ('gerd', 34, 'The nurse explains Barrett''s esophagus to a client with chronic GERD. Which client statement indicates understanding?', '[{"id": "a", "text": "It is a pre-cancerous change in my esophagus lining."}, {"id": "b", "text": "It is a narrowing that makes swallowing difficult."}, {"id": "c", "text": "It happens when stomach acid enters my lungs."}, {"id": "d", "text": "It is a weak sphincter that will heal by itself."}]'::jsonb, '["a"]', 'Barrett''s esophagus is a pre-cancerous change in the esophageal lining. Narrowing that causes dysphagia is an esophageal stricture, and acid entering the lungs is aspiration pneumonia.'),
  ('gerd', 35, 'A client with untreated GERD for many years reports that swallowing has become more and more difficult. Which complication should the nurse suspect?', '[{"id": "a", "text": "Aspiration pneumonia"}, {"id": "b", "text": "Esophageal stricture"}, {"id": "c", "text": "Barrett''s esophagus"}, {"id": "d", "text": "Tardive dyskinesia"}]'::jsonb, '["b"]', 'Esophageal strictures are a narrowing of the esophagus that causes dysphagia. Barrett''s esophagus is a pre-cancerous lining change, and aspiration pneumonia presents with coughing and wheezing.'),
  ('gerd', 36, 'A client with GERD begins coughing while eating and has new wheezing. Which complication should the nurse suspect?', '[{"id": "a", "text": "Esophageal stricture"}, {"id": "b", "text": "Esophagitis"}, {"id": "c", "text": "Barrett''s esophagus"}, {"id": "d", "text": "Aspiration pneumonia"}]'::jsonb, '["d"]', 'Coughing and wheezing signal aspiration pneumonia in a client with GERD. A stricture presents with dysphagia, and esophagitis with pain and ulcers.'),
  ('gerd', 37, 'The nurse is caring for a client with GERD. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "Coughing and wheezing while eating"}, {"id": "b", "text": "Bitter taste in the mouth after meals"}, {"id": "c", "text": "Heartburn after eating a large meal"}, {"id": "d", "text": "Bad breath noted during mouth care"}]'::jsonb, '["a"]', 'The nurse monitors for aspiration signs such as coughing while eating and wheezing, which suggest aspiration pneumonia. Bitter taste, heartburn after a large meal, and bad breath are expected GERD symptoms.'),
  ('gerd', 38, 'A client with untreated GERD is diagnosed with esophagitis. The nurse understands that this complication involves:', '[{"id": "a", "text": "A pre-cancerous change in the esophageal lining"}, {"id": "b", "text": "Inflammation, pain, and ulcers of the esophagus"}, {"id": "c", "text": "Acid entering the lungs during reflux"}, {"id": "d", "text": "Narrowing of the esophagus causing dysphagia"}]'::jsonb, '["b"]', 'Esophagitis is inflammation of the esophagus with pain and ulcers. A pre-cancerous lining change is Barrett''s esophagus, and narrowing with dysphagia is a stricture.'),
  ('gerd', 39, 'A client whose GERD symptoms have improved says, "Now that I feel better, I can go back to my usual late-night meals." Which response by the nurse is best?', '[{"id": "a", "text": "That is fine if you take an antacid each night."}, {"id": "b", "text": "Once symptoms improve, the sphincter is fully healed."}, {"id": "c", "text": "GERD is chronic, so lifestyle changes must continue long term."}, {"id": "d", "text": "Late-night meals are safe if you eat them quickly."}]'::jsonb, '["c"]', 'GERD is a chronic condition that requires long-term lifestyle changes and treatment. Antacids give only fast, temporary relief and do not replace lifestyle changes.'),
  ('gerd', 40, 'The nurse reviews the medications of a client with GERD. Which drug should the nurse identify as a prokinetic agent?', '[{"id": "a", "text": "Metoclopramide"}, {"id": "b", "text": "Famotidine"}, {"id": "c", "text": "Pantoprazole"}, {"id": "d", "text": "Mylanta"}]'::jsonb, '["a"]', 'Metoclopramide (Reglan) is the prokinetic used in GERD. Famotidine is an H2 blocker, pantoprazole is a PPI, and Mylanta is an antacid.'),
  ('gerd', 41, 'The nurse is teaching a client how to identify GERD triggers. Which principle should guide the client''s choices?', '[{"id": "a", "text": "Avoid only spicy foods; other triggers are minor."}, {"id": "b", "text": "Choose large meals so the stomach empties less often."}, {"id": "c", "text": "Lie down after meals to reduce stomach pressure."}, {"id": "d", "text": "Avoid anything that relaxes the LES or raises stomach pressure."}]'::jsonb, '["d"]', 'Anything that relaxes the LES or increases stomach pressure can trigger GERD. Large meals and lying down after eating promote reflux, and triggers include more than spicy foods.'),
  ('gerd', 42, 'A client reports taking omeprazole at bedtime after an evening snack and says it is not helping. Which instruction should the nurse reinforce?', '[{"id": "a", "text": "Take the omeprazole before meals for best effect."}, {"id": "b", "text": "Take a double dose of omeprazole at bedtime."}, {"id": "c", "text": "Stop the omeprazole and use antacids only."}, {"id": "d", "text": "Take the omeprazole only when heartburn starts."}]'::jsonb, '["a"]', 'The nurse reinforces medication adherence, because PPIs work best before meals. Switching to antacids alone gives only fast, temporary relief.'),
  ('gerd', 43, 'Which sequence reflects the usual order of treatment for a client with GERD?', '[{"id": "a", "text": "Surgery, then PPIs, then lifestyle changes"}, {"id": "b", "text": "PPIs, then lifestyle changes, then surgery"}, {"id": "c", "text": "Lifestyle changes, then PPIs, then surgery"}, {"id": "d", "text": "Lifestyle changes, then surgery, then PPIs"}]'::jsonb, '["c"]', 'First-line treatment is lifestyle changes, then PPIs, and surgery is reserved for GERD unresponsive to both. Starting with PPIs skips the first-line step.'),
  ('gerd', 44, 'A client with GERD takes both Maalox and omeprazole and asks how they differ. Which response by the nurse is accurate?', '[{"id": "a", "text": "Maalox blocks acid production; omeprazole neutralizes acid."}, {"id": "b", "text": "Maalox neutralizes acid; omeprazole blocks acid production."}, {"id": "c", "text": "Both medications speed the emptying of the stomach."}, {"id": "d", "text": "Both medications strengthen the esophageal sphincter."}]'::jsonb, '["b"]', 'Antacids such as Maalox neutralize acid, while PPIs such as omeprazole block acid production. The first option reverses the two mechanisms.'),
  ('gerd', 45, 'A client with GERD reports that sour fluid and bits of food come back up into the throat after meals. The nurse documents this symptom as:', '[{"id": "a", "text": "Dysphagia"}, {"id": "b", "text": "Hoarseness"}, {"id": "c", "text": "Halitosis"}, {"id": "d", "text": "Regurgitation"}]'::jsonb, '["d"]', 'Regurgitation is acid or food backing up to the throat or mouth. Dysphagia is difficulty swallowing, and halitosis is bad breath.'),
  ('gerd', 46, 'A client with GERD who smokes asks why quitting smoking is part of the treatment plan. Which response by the nurse is accurate?', '[{"id": "a", "text": "Smoking increases the strength of the sphincter."}, {"id": "b", "text": "Smoking relaxes the lower esophageal sphincter."}, {"id": "c", "text": "Smoking affects only the lungs, not reflux."}, {"id": "d", "text": "Smoking matters only during pregnancy."}]'::jsonb, '["b"]', 'Smoking relaxes the LES, which lets acid reflux, so quitting smoking is a first-line lifestyle change. Smoking weakens rather than strengthens the sphincter.'),
  ('gerd', 47, 'A client with GERD reports drinking four cups of coffee every day. Which teaching should the nurse provide?', '[{"id": "a", "text": "Coffee is safe because it is not spicy or fatty."}, {"id": "b", "text": "Coffee helps by neutralizing stomach acid."}, {"id": "c", "text": "Caffeine is a trigger and should be avoided."}, {"id": "d", "text": "Coffee can replace a meal to limit stomach volume."}]'::jsonb, '["c"]', 'Caffeine is a GERD trigger and should be avoided. Neutralizing stomach acid is the action of antacids, not coffee.'),
  ('gerd', 48, 'A client with GERD has ignored the symptoms for many years. Which long-term complication of untreated GERD should the nurse discuss?', '[{"id": "a", "text": "Permanent tightening of the sphincter"}, {"id": "b", "text": "Tardive dyskinesia"}, {"id": "c", "text": "Electrolyte imbalance"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["d"]', 'Esophageal cancer is a long-term risk of untreated GERD. Tardive dyskinesia and electrolyte imbalance are medication adverse effects, not complications of untreated reflux.'),
  ('gerd', 49, 'Which client report indicates that teaching about GERD lifestyle changes has been effective?', '[{"id": "a", "text": "I eat three large meals and lie down after each one."}, {"id": "b", "text": "I eat several small meals and wait 3 hours to lie down."}, {"id": "c", "text": "I sleep flat and drink coffee to help digestion."}, {"id": "d", "text": "I take antacids so I can keep eating fried foods."}]'::jsonb, '["b"]', 'Small, frequent meals and waiting 2 to 3 hours before lying down are correct lifestyle changes. Large meals, lying flat, caffeine, and fried foods all worsen GERD.'),
  ('gerd', 50, 'The nurse explains to a client with GERD why aspiration pneumonia is a possible complication. Which explanation is accurate?', '[{"id": "a", "text": "Refluxed acid can enter the lungs."}, {"id": "b", "text": "The esophagus becomes narrowed."}, {"id": "c", "text": "The esophageal lining becomes pre-cancerous."}, {"id": "d", "text": "The stomach empties too quickly."}]'::jsonb, '["a"]', 'Aspiration pneumonia occurs when acid enters the lungs. Narrowing is an esophageal stricture, and a pre-cancerous lining is Barrett''s esophagus.'),
  ('gastroesophageal', 1, 'A client with GERD asks why stomach acid damages the esophagus but not the stomach. Which response by the nurse is accurate?', '[{"id": "a", "text": "The esophagus lacks the protective mucus layer that the stomach has."}, {"id": "b", "text": "The esophagus produces its own acid, which adds to the damage."}, {"id": "c", "text": "The stomach lacks a sphincter, so acid drains out of it quickly."}, {"id": "d", "text": "The esophagus is not muscular, so it cannot push acid away."}]'::jsonb, '["a"]', 'Unlike the stomach, the esophagus lacks a protective mucus layer, making it vulnerable to acid damage. The esophagus is a muscular tube, so the last option is incorrect.'),
  ('gastroesophageal', 2, 'During teaching about swallowing, a client asks which structure keeps food from entering the airway. Which structure should the nurse identify?', '[{"id": "a", "text": "Lower esophageal sphincter"}, {"id": "b", "text": "Epiglottis"}, {"id": "c", "text": "Diaphragm"}, {"id": "d", "text": "Esophagus"}]'::jsonb, '["b"]', 'The epiglottis prevents food from entering the airway during swallowing. The lower esophageal sphincter sits at the bottom of the esophagus, not at the airway.'),
  ('gastroesophageal', 3, 'A client newly diagnosed with GERD asks where the lower esophageal sphincter (LES) is located. Which response by the nurse is accurate?', '[{"id": "a", "text": "At the upper end of the esophagus"}, {"id": "b", "text": "In the airway above the vocal cords"}, {"id": "c", "text": "At the bottom of the esophagus"}, {"id": "d", "text": "Where the stomach meets the intestine"}]'::jsonb, '["c"]', 'The esophagus is a muscular tube from the throat to the stomach with the LES at its bottom. The structure that guards the airway is the epiglottis, not the LES.'),
  ('gastroesophageal', 4, 'A nurse is explaining the cause of GERD to a client. Which statement best describes what happens in GERD?', '[{"id": "a", "text": "The epiglottis fails to close during swallowing."}, {"id": "b", "text": "The esophagus does not connect to the stomach."}, {"id": "c", "text": "The esophagus connects abnormally to the trachea."}, {"id": "d", "text": "The LES fails to function, allowing acid to flow back."}]'::jsonb, '["d"]', 'In GERD, the LES fails to function properly and stomach acid flows back into the esophagus. An esophagus that does not connect to the stomach is esophageal atresia, and an esophagus-trachea connection is TEF.'),
  ('gastroesophageal', 5, 'A client with GERD describes the following after-dinner habits. Which habit should the nurse advise the client to change?', '[{"id": "a", "text": "Taking a short walk around the block"}, {"id": "b", "text": "Sitting upright while reading a book"}, {"id": "c", "text": "Changing into loose-fitting clothes"}, {"id": "d", "text": "Drinking a cup of peppermint tea"}]'::jsonb, '["d"]', 'Peppermint is a GERD risk factor and should be avoided. Wearing loose clothing is a recommended lifestyle modification, not a habit to change.'),
  ('gastroesophageal', 6, 'During a health history, which finding should the nurse identify as a risk factor for a client''s GERD?', '[{"id": "a", "text": "Takes an NSAID daily for back pain"}, {"id": "b", "text": "Walks 30 minutes every morning"}, {"id": "c", "text": "Has never used tobacco products"}, {"id": "d", "text": "Sleeps with the head of bed raised"}]'::jsonb, '["a"]', 'Certain medications, such as NSAIDs, are listed GERD risk factors. Not smoking and elevating the head of the bed reduce reflux rather than cause it.'),
  ('gastroesophageal', 7, 'A client with GERD is found to have a hiatal hernia and asks what this means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The esophagus does not connect to the stomach."}, {"id": "b", "text": "Part of the stomach protrudes through the diaphragm."}, {"id": "c", "text": "The esophagus connects abnormally to the trachea."}, {"id": "d", "text": "The epiglottis does not cover the airway."}]'::jsonb, '["b"]', 'A hiatal hernia is the stomach protruding through the diaphragm, and it is a GERD risk factor. The first and third options describe esophageal atresia and TEF.'),
  ('gastroesophageal', 8, 'Which findings should the nurse expect when assessing an adult client with GERD?', '[{"id": "a", "text": "Excessive drooling and frothy saliva"}, {"id": "b", "text": "Cyanosis and apnea during meals"}, {"id": "c", "text": "Burping, bloating, and an acid taste"}, {"id": "d", "text": "Choking and cyanosis with every meal"}]'::jsonb, '["c"]', 'GERD symptoms include burping, bloating, and an acid taste or smell. Drooling, frothy saliva, apnea, choking, and cyanosis are signs of esophageal atresia or TEF in a newborn.'),
  ('gastroesophageal', 9, 'The nurse is reviewing the health histories of four clients. Which client has the greatest risk for GERD?', '[{"id": "a", "text": "A normal-weight client who eats a low-fat diet"}, {"id": "b", "text": "A nonsmoking client who avoids spicy foods"}, {"id": "c", "text": "A client who wears loose clothing to work"}, {"id": "d", "text": "An obese client who smokes cigarettes daily"}]'::jsonb, '["d"]', 'Obesity and smoking are both GERD risk factors. Avoiding fatty and spicy foods, not smoking, and wearing loose clothing lower reflux risk.'),
  ('gastroesophageal', 10, 'Which instruction about sleeping position should the nurse give a client with GERD?', '[{"id": "a", "text": "Keep the bed flat with one thin pillow."}, {"id": "b", "text": "Raise the foot of the bed 30 degrees."}, {"id": "c", "text": "Elevate the head of the bed 30 to 45 degrees."}, {"id": "d", "text": "Lie flat on the back right after meals."}]'::jsonb, '["c"]', 'Elevating the head of the bed 30 to 45 degrees is a GERD lifestyle modification. Raising the foot of the bed or lying flat does not elevate the head.'),
  ('gastroesophageal', 11, 'Which action by an unlicensed assistive personnel (UAP) caring for a client with GERD requires the nurse''s intervention?', '[{"id": "a", "text": "Raising the head of the bed to 40 degrees"}, {"id": "b", "text": "Helping the client into loose-fitting pajamas"}, {"id": "c", "text": "Removing peppermint candy from the bedside"}, {"id": "d", "text": "Lowering the head of the bed flat for sleep"}]'::jsonb, '["d"]', 'The head of the bed should be elevated 30 to 45 degrees for a client with GERD, so lowering it flat requires correction. Loose clothing and avoiding peppermint are appropriate.'),
  ('gastroesophageal', 12, 'The nurse teaches a client with GERD about lifestyle modifications. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I''ll wear a tight belt to support my stomach."}, {"id": "b", "text": "I''ll raise the head of my bed at night."}, {"id": "c", "text": "I''ll work on losing weight gradually."}, {"id": "d", "text": "I''ll avoid fatty and spicy foods."}]'::jsonb, '["a"]', 'Clients with GERD should wear loose clothing, so a tight belt needs correction. Elevating the head of the bed, losing weight, and avoiding triggers are correct.'),
  ('gastroesophageal', 13, 'An obese client with GERD smokes a pack of cigarettes daily. Which lifestyle modifications should the nurse recommend?', '[{"id": "a", "text": "Wear snug clothing and lie flat at night"}, {"id": "b", "text": "Lose weight and quit smoking"}, {"id": "c", "text": "Chew peppermint gum after every meal"}, {"id": "d", "text": "Take NSAIDs to manage the chest pain"}]'::jsonb, '["b"]', 'Quitting smoking and losing weight if obese are GERD lifestyle modifications. Peppermint and NSAIDs are risk factors, and snug clothing should be avoided.'),
  ('gastroesophageal', 14, 'A client with GERD takes Maalox and has another oral medication scheduled at 0900. Which is the earliest time the nurse should give the Maalox?', '[{"id": "a", "text": "0900"}, {"id": "b", "text": "0915"}, {"id": "c", "text": "0930"}, {"id": "d", "text": "1000"}]'::jsonb, '["d"]', 'Antacids should not be taken at the same time as other medications; wait at least 1 hour. 1000 is the first time that is a full hour after the 0900 dose.'),
  ('gastroesophageal', 15, 'Which statement by a client taking Tums for GERD indicates a need for further teaching?', '[{"id": "a", "text": "I will take Tums with my other pills to save time."}, {"id": "b", "text": "Tums neutralizes the acid in my stomach."}, {"id": "c", "text": "I will space Tums at least 1 hour from other medicines."}, {"id": "d", "text": "Tums works differently from my omeprazole."}]'::jsonb, '["a"]', 'Antacids must be separated from other medications by at least 1 hour, so taking Tums with other pills needs correction. Antacids neutralize acid, while PPIs reduce acid production.'),
  ('gastroesophageal', 16, 'The nurse reviews the medications of a client with GERD. Which medication works by neutralizing acid rather than reducing acid production?', '[{"id": "a", "text": "Omeprazole"}, {"id": "b", "text": "Esomeprazole"}, {"id": "c", "text": "Famotidine"}, {"id": "d", "text": "Maalox"}]'::jsonb, '["d"]', 'Antacids such as Maalox neutralize acid. Omeprazole and esomeprazole (PPIs) reduce acid production, and famotidine (an H2 blocker) decreases acid production.'),
  ('gastroesophageal', 17, 'The nurse is scheduling esomeprazole for a client with GERD. Which administration instruction is appropriate?', '[{"id": "a", "text": "Give it on an empty stomach."}, {"id": "b", "text": "Give it with a high-fat meal."}, {"id": "c", "text": "Give it together with Maalox."}, {"id": "d", "text": "Give it with the full meal tray."}]'::jsonb, '["a"]', 'PPIs such as esomeprazole should be taken on an empty stomach. Giving it with an antacid is incorrect because antacids are separated from other meds by at least 1 hour.'),
  ('gastroesophageal', 18, 'Which statement by a client prescribed omeprazole indicates a need for further teaching?', '[{"id": "a", "text": "I''ll take it on an empty stomach."}, {"id": "b", "text": "I''ll take it in the middle of breakfast."}, {"id": "c", "text": "I''ll avoid using it longer than prescribed."}, {"id": "d", "text": "I''ll ask about calcium and vitamin D3."}]'::jsonb, '["b"]', 'PPIs should be taken on an empty stomach, so taking omeprazole during breakfast needs correction. Avoiding long-term use and supplementing calcium and vitamin D3 are correct.'),
  ('gastroesophageal', 19, 'A client receiving a PPI for GERD asks why calcium and vitamin D3 supplements were recommended. Which response by the nurse is accurate?', '[{"id": "a", "text": "They help the PPI neutralize stomach acid."}, {"id": "b", "text": "They protect against C. diff infection."}, {"id": "c", "text": "They help offset the PPI risk of osteoporosis."}, {"id": "d", "text": "They strengthen the lower esophageal sphincter."}]'::jsonb, '["c"]', 'Long-term PPI use carries a risk of osteoporosis, and calcium plus vitamin D3 supplementation is recommended alongside this risk. PPIs reduce acid production rather than neutralize it.'),
  ('gastroesophageal', 20, 'A client has taken a PPI for GERD for many months. The nurse recognizes that the client is at increased risk for which infection?', '[{"id": "a", "text": "Urinary tract infection"}, {"id": "b", "text": "C. diff infection"}, {"id": "c", "text": "Strep throat"}, {"id": "d", "text": "Influenza"}]'::jsonb, '["b"]', 'Long-term PPI use increases the risk of C. diff infection, along with osteoporosis and pneumonia. The other infections are not listed PPI risks.'),
  ('gastroesophageal', 21, 'The nurse is teaching a client about long-term PPI use. Which respiratory complication should the nurse include?', '[{"id": "a", "text": "Asthma"}, {"id": "b", "text": "Tuberculosis"}, {"id": "c", "text": "Pneumonia"}, {"id": "d", "text": "Pulmonary embolism"}]'::jsonb, '["c"]', 'Pneumonia is a risk of long-term PPI use, along with osteoporosis and C. diff. The other respiratory conditions are not listed PPI risks.'),
  ('gastroesophageal', 22, 'A client with GERD who must take a PPI asks which supplements are recommended. Which response by the nurse is accurate?', '[{"id": "a", "text": "Iron and vitamin B12"}, {"id": "b", "text": "Potassium and magnesium"}, {"id": "c", "text": "Vitamin K and folic acid"}, {"id": "d", "text": "Calcium and vitamin D3"}]'::jsonb, '["d"]', 'Clients taking PPIs should supplement calcium and vitamin D3. The other supplements are not recommended for PPI therapy.'),
  ('gastroesophageal', 23, 'A client states, "Omeprazole works so well that I plan to take it for the rest of my life." Which response by the nurse is best?', '[{"id": "a", "text": "Long-term PPI use carries risks, so use is kept short-term."}, {"id": "b", "text": "That is fine, because PPIs have no long-term risks at all."}, {"id": "c", "text": "Take it only with high-fat meals to make it last."}, {"id": "d", "text": "Double the dose once your symptoms are gone."}]'::jsonb, '["a"]', 'PPIs are intended for short-term use to avoid osteoporosis, C. diff, and pneumonia. Saying PPIs have no long-term risks is incorrect.'),
  ('gastroesophageal', 24, 'A client prescribed famotidine for GERD asks how the medication works. Which response by the nurse is accurate?', '[{"id": "a", "text": "It neutralizes acid already in the stomach."}, {"id": "b", "text": "It coats the esophagus with protective mucus."}, {"id": "c", "text": "It strengthens the lower esophageal sphincter."}, {"id": "d", "text": "It decreases the production of stomach acid."}]'::jsonb, '["d"]', 'H2 blockers such as famotidine decrease acid production. Neutralizing acid already present is how antacids such as Tums and Maalox work.'),
  ('gastroesophageal', 25, 'The nurse reviews the medication list of a client with GERD. Which drug should the nurse identify as an H2 blocker?', '[{"id": "a", "text": "Famotidine"}, {"id": "b", "text": "Omeprazole"}, {"id": "c", "text": "Esomeprazole"}, {"id": "d", "text": "Tums"}]'::jsonb, '["a"]', 'Famotidine is an H2 blocker. Omeprazole and esomeprazole are PPIs, and Tums is an antacid.'),
  ('gastroesophageal', 26, 'Which sequence correctly describes how chronic GERD can progress to esophageal cancer?', '[{"id": "a", "text": "Barrett''s esophagus, then chronic acid exposure, then adenocarcinoma"}, {"id": "b", "text": "Chronic acid exposure, then adenocarcinoma, then Barrett''s esophagus"}, {"id": "c", "text": "Chronic acid exposure, then Barrett''s esophagus, then adenocarcinoma"}, {"id": "d", "text": "Adenocarcinoma, then Barrett''s esophagus, then chronic acid exposure"}]'::jsonb, '["c"]', 'Chronic acid exposure leads to Barrett''s esophagus (metaplasia), which can progress to adenocarcinoma. Barrett''s is the result of acid exposure, not its cause.'),
  ('gastroesophageal', 27, 'An endoscopy report for a client with chronic GERD shows metaplasia of the esophageal lining. The nurse recognizes this finding as:', '[{"id": "a", "text": "Barrett''s esophagus"}, {"id": "b", "text": "Esophageal atresia"}, {"id": "c", "text": "Hiatal hernia"}, {"id": "d", "text": "Tracheoesophageal fistula"}]'::jsonb, '["a"]', 'Barrett''s esophagus is metaplasia caused by chronic acid exposure from GERD. Esophageal atresia and TEF are congenital defects, and a hiatal hernia is the stomach protruding through the diaphragm.'),
  ('gastroesophageal', 28, 'The nurse is reviewing the histories of four clients. Which client has the greatest risk for esophageal cancer?', '[{"id": "a", "text": "A normal-weight client with no reflux symptoms"}, {"id": "b", "text": "A nonsmoking client with rare heartburn"}, {"id": "c", "text": "A client who took famotidine for one week"}, {"id": "d", "text": "An obese tobacco user with chronic GERD"}]'::jsonb, '["d"]', 'Risk factors for esophageal cancer are GERD, obesity, and tobacco use, and this client has all three. The other clients have none of these risk factors.'),
  ('gastroesophageal', 29, 'A client with Barrett''s esophagus has completed teaching. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I need regular endoscopies to watch for changes."}, {"id": "b", "text": "My Barrett''s came from years of acid reflux."}, {"id": "c", "text": "Since my heartburn is better, I can skip endoscopy."}, {"id": "d", "text": "Barrett''s raises my risk for esophageal cancer."}]'::jsonb, '["c"]', 'Barrett''s esophagus is a pre-cancerous lesion from chronic GERD that requires endoscopic surveillance, so skipping endoscopy needs correction. The other statements are accurate.'),
  ('gastroesophageal', 30, 'A newborn is diagnosed with esophageal atresia, and the parents ask what this means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The esophagus does not connect to the stomach."}, {"id": "b", "text": "The esophagus is connected to the trachea."}, {"id": "c", "text": "The stomach pushes up through the diaphragm."}, {"id": "d", "text": "The lower sphincter allows acid to flow back."}]'::jsonb, '["a"]', 'Esophageal atresia is a congenital condition in which the esophagus does not connect to the stomach. An abnormal esophagus-trachea connection is a TEF.'),
  ('gastroesophageal', 31, 'The parents of a newborn ask the nurse to explain a tracheoesophageal fistula (TEF). Which description is accurate?', '[{"id": "a", "text": "The esophagus ends before reaching the stomach."}, {"id": "b", "text": "An abnormal connection between the esophagus and trachea."}, {"id": "c", "text": "The stomach protrudes upward through the diaphragm."}, {"id": "d", "text": "The epiglottis fails to cover the airway."}]'::jsonb, '["b"]', 'A TEF is an abnormal connection between the esophagus and the trachea. An esophagus that does not connect to the stomach is esophageal atresia.'),
  ('gastroesophageal', 32, 'A preterm newborn coughs, chokes, and becomes cyanotic during the first feeding. Which condition should the nurse suspect?', '[{"id": "a", "text": "GERD"}, {"id": "b", "text": "Hiatal hernia"}, {"id": "c", "text": "Barrett''s esophagus"}, {"id": "d", "text": "Tracheoesophageal fistula"}]'::jsonb, '["d"]', 'A preterm baby with coughing, choking, and cyanosis during feeding should be suspected of having TEF. Barrett''s esophagus is a complication of chronic GERD, not a feeding emergency in a newborn.'),
  ('gastroesophageal', 33, 'A newborn with excessive drooling chokes and turns cyanotic during a bottle feeding. Which action should the nurse take first?', '[{"id": "a", "text": "Stop the feeding and keep the newborn NPO."}, {"id": "b", "text": "Thicken the formula and resume the feeding."}, {"id": "c", "text": "Switch to smaller, more frequent feedings."}, {"id": "d", "text": "Position the newborn upright and keep feeding."}]'::jsonb, '["a"]', 'A neonate with suspected esophageal atresia or TEF must be made NPO immediately and prepared for surgery. Any option that continues feeding is unsafe.'),
  ('gastroesophageal', 34, 'When assessing a newborn with suspected esophageal atresia and TEF, which findings should the nurse expect?', '[{"id": "a", "text": "A sunken abdomen and a dry mouth"}, {"id": "b", "text": "Heartburn and burping after feeds"}, {"id": "c", "text": "Excessive drooling and frothy saliva"}, {"id": "d", "text": "Bloating and an acid taste after feeds"}]'::jsonb, '["c"]', 'Excessive drooling and frothy saliva are signs of esophageal atresia and TEF. Heartburn, burping, bloating, and acid taste are GERD symptoms, and the abdomen is distended rather than sunken.'),
  ('gastroesophageal', 35, 'The nurse is assessing a newborn with suspected TEF. Which additional findings are consistent with this condition?', '[{"id": "a", "text": "A flat abdomen and regular breathing"}, {"id": "b", "text": "Pink color throughout every feeding"}, {"id": "c", "text": "Quiet, effortless swallowing of formula"}, {"id": "d", "text": "Apnea and a distended abdomen"}]'::jsonb, '["d"]', 'Apnea and a distended abdomen are listed signs of esophageal atresia and TEF, along with cyanosis during feeding. Pink color and effortless swallowing would not be expected.'),
  ('gastroesophageal', 36, 'The nurse is caring for a neonate diagnosed with esophageal atresia. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Small, frequent feedings of thickened formula"}, {"id": "b", "text": "NPO status and preparation for surgery"}, {"id": "c", "text": "Head-of-bed elevation and continued feeds"}, {"id": "d", "text": "Antacids given before each feeding"}]'::jsonb, '["b"]', 'Management of esophageal atresia is immediate NPO plus surgical intervention. Feeding in any form, even thickened or with the head elevated, is unsafe.'),
  ('gastroesophageal', 37, 'A nurse is precepting a new graduate caring for a neonate with suspected TEF. Which action by the new graduate requires correction?', '[{"id": "a", "text": "Keeping the neonate NPO"}, {"id": "b", "text": "Monitoring for cyanosis and apnea"}, {"id": "c", "text": "Offering a bottle to calm the neonate"}, {"id": "d", "text": "Preparing the neonate for surgery"}]'::jsonb, '["c"]', 'A neonate with suspected TEF must be kept NPO immediately, so offering a bottle is unsafe. Monitoring for cyanosis and apnea and preparing for surgery are appropriate.'),
  ('gastroesophageal', 38, 'The nurse is teaching nursery staff about the classic "3 C''s" of TEF. Which findings should the nurse include?', '[{"id": "a", "text": "Coughing, choking, and cyanosis"}, {"id": "b", "text": "Cramping, constipation, and chills"}, {"id": "c", "text": "Chest pain, cough, and chills"}, {"id": "d", "text": "Crying, colic, and constipation"}]'::jsonb, '["a"]', 'The 3 C''s of TEF are coughing, choking, and cyanosis during feeding. The other groups are not listed signs of TEF.'),
  ('gastroesophageal', 39, 'A mother tells the nurse that her newborn has had excessive drooling and frothy saliva since birth and has not yet been fed. Which action should the nurse take?', '[{"id": "a", "text": "Reassure the mother that this is normal."}, {"id": "b", "text": "Offer a bottle to see if the baby swallows."}, {"id": "c", "text": "Withhold feeding and notify the provider."}, {"id": "d", "text": "Feed smaller amounts more frequently."}]'::jsonb, '["c"]', 'Excessive drooling and frothy saliva suggest esophageal atresia or TEF, which requires immediate NPO and surgical intervention. Offering a bottle or feeding smaller amounts is unsafe.'),
  ('gastroesophageal', 40, 'A client asks the nurse to explain the role of the esophagus. Which explanation is accurate?', '[{"id": "a", "text": "It is a flap that keeps food out of the airway."}, {"id": "b", "text": "It is the muscle that separates chest and abdomen."}, {"id": "c", "text": "It is an organ protected by a thick mucus layer."}, {"id": "d", "text": "It is a muscular tube from the throat to the stomach."}]'::jsonb, '["d"]', 'The esophagus is a muscular tube connecting the throat to the stomach. The flap that keeps food out of the airway is the epiglottis, and the esophagus lacks a protective mucus layer.'),
  ('gastroesophageal', 41, 'Which plan of care best reflects lifestyle modifications for a client with GERD?', '[{"id": "a", "text": "Head of bed raised 30–45°, loose clothing, avoid triggers"}, {"id": "b", "text": "Head of bed flat, loose clothing, avoid trigger foods"}, {"id": "c", "text": "Head of bed raised 30–45°, tight belt, avoid triggers"}, {"id": "d", "text": "Head of bed raised 30–45°, loose clothing, peppermint tea"}]'::jsonb, '["a"]', 'GERD lifestyle modifications include elevating the head of the bed 30 to 45 degrees, wearing loose clothing, and avoiding triggers. Each other plan contains one error: a flat bed, a tight belt, or peppermint.'),
  ('gastroesophageal', 42, 'Which statement by a client with GERD indicates understanding of dietary modification?', '[{"id": "a", "text": "Peppermint tea after meals will soothe my reflux."}, {"id": "b", "text": "I''ll avoid fatty and spicy foods that trigger reflux."}, {"id": "c", "text": "Spicy foods are fine as long as I eat them early."}, {"id": "d", "text": "Fatty foods are fine if I also take an NSAID."}]'::jsonb, '["b"]', 'Fatty and spicy foods are GERD risk factors, so avoiding them is correct diet modification. Peppermint and NSAIDs are also risk factors.'),
  ('gastroesophageal', 43, 'The nurse is teaching parents about esophageal conditions in newborns. Which statement correctly distinguishes esophageal atresia from TEF?', '[{"id": "a", "text": "Atresia: esophagus not joined to stomach; TEF: esophagus joined to trachea"}, {"id": "b", "text": "Atresia: esophagus joined to trachea; TEF: esophagus not joined to stomach"}, {"id": "c", "text": "Atresia: stomach through the diaphragm; TEF: the LES fails to close"}, {"id": "d", "text": "Atresia: the epiglottis fails; TEF: the esophagus lacks mucus"}]'::jsonb, '["a"]', 'In esophageal atresia the esophagus does not connect to the stomach, while a TEF is an abnormal connection between the esophagus and trachea. The second option reverses the two.'),
  ('gastroesophageal', 44, 'A client with chronic GERD who smokes asks what can lower the risk of esophageal cancer. Which recommendation by the nurse is most appropriate?', '[{"id": "a", "text": "Take antacids with other medications."}, {"id": "b", "text": "Stop all tobacco use."}, {"id": "c", "text": "Chew peppermint gum after meals."}, {"id": "d", "text": "Take an NSAID every day."}]'::jsonb, '["b"]', 'Tobacco use is a risk factor for esophageal cancer, so stopping tobacco lowers risk. Peppermint and NSAIDs are GERD risk factors, and antacids should be separated from other medications.'),
  ('gastroesophageal', 45, 'An adult client reports epigastric pain and difficulty swallowing along with heartburn. These findings are most consistent with which condition?', '[{"id": "a", "text": "Esophageal atresia"}, {"id": "b", "text": "Tracheoesophageal fistula"}, {"id": "c", "text": "GERD"}, {"id": "d", "text": "Osteoporosis"}]'::jsonb, '["c"]', 'Heartburn, epigastric pain, and difficulty swallowing are GERD symptoms. Esophageal atresia and TEF are congenital and present in newborns with coughing, choking, and cyanosis during feeding.'),
  ('gastroesophageal', 46, 'A client with GERD is prescribed omeprazole and Maalox. Which timing instruction should the nurse give?', '[{"id": "a", "text": "Take omeprazole on an empty stomach; space Maalox 1 hour from other meds."}, {"id": "b", "text": "Take omeprazole with a large meal; take Maalox with all other meds."}, {"id": "c", "text": "Take omeprazole and Maalox together so both act at once."}, {"id": "d", "text": "Take Maalox first, then omeprazole right after with food."}]'::jsonb, '["a"]', 'PPIs are taken on an empty stomach, and antacids must be separated from other medications by at least 1 hour. Taking them together or with food is incorrect.'),
  ('gastroesophageal', 47, 'A client''s GERD symptoms remain uncontrolled on famotidine. The nurse anticipates a change to which medication class because it is more potent?', '[{"id": "a", "text": "Antacid"}, {"id": "b", "text": "Proton pump inhibitor"}, {"id": "c", "text": "NSAID"}, {"id": "d", "text": "Calcium supplement"}]'::jsonb, '["b"]', 'H2 blockers such as famotidine are less potent than PPIs, so a PPI is the stronger option. NSAIDs are a GERD risk factor, not a treatment.'),
  ('gastroesophageal', 48, 'A client with Barrett''s esophagus asks which type of cancer the condition can lead to. Which response by the nurse is accurate?', '[{"id": "a", "text": "Lymphoma"}, {"id": "b", "text": "Adenocarcinoma"}, {"id": "c", "text": "Melanoma"}, {"id": "d", "text": "Sarcoma"}]'::jsonb, '["b"]', 'Chronic acid exposure causes Barrett''s esophagus, which can progress to adenocarcinoma. The other cancers are not linked to Barrett''s esophagus.'),
  ('gastroesophageal', 49, 'An adult client with heartburn learns from an X-ray that they have a hiatal hernia and asks whether it is related to the reflux. Which response by the nurse is accurate?', '[{"id": "a", "text": "A hiatal hernia occurs only in newborns."}, {"id": "b", "text": "A hiatal hernia is a risk factor for GERD."}, {"id": "c", "text": "A hiatal hernia prevents acid from refluxing."}, {"id": "d", "text": "A hiatal hernia is caused by taking PPIs."}]'::jsonb, '["b"]', 'A hiatal hernia, in which the stomach protrudes through the diaphragm, is a listed risk factor for GERD. It promotes reflux rather than preventing it.'),
  ('gastroesophageal', 50, 'A client with GERD takes an NSAID daily and asks whether this could affect the reflux. Which response by the nurse is accurate?', '[{"id": "a", "text": "NSAIDs protect the esophagus from acid."}, {"id": "b", "text": "NSAIDs matter only if you also smoke."}, {"id": "c", "text": "NSAIDs are medications that can contribute to GERD."}, {"id": "d", "text": "NSAIDs strengthen the lower esophageal sphincter."}]'::jsonb, '["c"]', 'Certain medications, such as NSAIDs, are GERD risk factors. They do not protect the esophagus or strengthen the LES.'),
  ('pud_gastritis', 1, 'A client reports burning epigastric pain that is worse when the stomach is empty and that wakes the client at night. The pain improves after eating a snack. The nurse recognizes these findings as most consistent with which condition?', '[{"id": "a", "text": "Gastric ulcer"}, {"id": "b", "text": "Duodenal ulcer"}, {"id": "c", "text": "Ulcer perforation"}, {"id": "d", "text": "Gastric outlet obstruction"}]'::jsonb, '["b"]', 'Duodenal ulcer pain is worse on an empty stomach and at night and is relieved by eating or antacids. Gastric ulcer pain worsens with eating and is not relieved by food.'),
  ('pud_gastritis', 2, 'A client with a peptic ulcer reports that epigastric pain worsens with eating and that there has been recent weight loss. Which description of the ulcer would the nurse expect?', '[{"id": "a", "text": "Gastric ulcer located inside the stomach"}, {"id": "b", "text": "Duodenal ulcer located inside the stomach"}, {"id": "c", "text": "Duodenal ulcer in the first part of the small intestine"}, {"id": "d", "text": "Gastric ulcer in the first part of the small intestine"}]'::jsonb, '["a"]', 'Gastric ulcers are inside the stomach, their pain worsens with eating, and weight loss is associated with gastric ulcers. Duodenal ulcers are in the first part of the small intestine and are relieved by eating.'),
  ('pud_gastritis', 3, 'A nursing student is comparing gastric and duodenal ulcers. Which statement by the student is accurate?', '[{"id": "a", "text": "Gastric ulcer pain is relieved by eating; duodenal pain worsens with food."}, {"id": "b", "text": "Both ulcer types are reliably relieved by eating or antacids."}, {"id": "c", "text": "Duodenal ulcer pain is relieved by eating; gastric pain may worsen with food."}, {"id": "d", "text": "Both ulcer types cause pain that worsens immediately after eating."}]'::jsonb, '["c"]', 'Duodenal ulcers feel better with food, while gastric ulcer pain is not relieved by food and may worsen. Option a reverses the two ulcer types.'),
  ('pud_gastritis', 4, 'The nurse is teaching a community group about peptic ulcers. Which statement about duodenal ulcers should the nurse include?', '[{"id": "a", "text": "They are located inside the stomach itself."}, {"id": "b", "text": "Their pain typically worsens with eating."}, {"id": "c", "text": "They are commonly associated with weight loss."}, {"id": "d", "text": "They are the most common type of peptic ulcer."}]'::jsonb, '["d"]', 'Duodenal ulcers are the most common type and are located in the first part of the small intestine. Pain that worsens with eating and weight loss are features of gastric ulcers.'),
  ('pud_gastritis', 5, 'A client newly diagnosed with peptic ulcer disease asks what most commonly causes ulcers. Which response by the nurse is accurate?', '[{"id": "a", "text": "Eating spicy foods on a regular basis"}, {"id": "b", "text": "Ongoing emotional stress at work"}, {"id": "c", "text": "Infection with H. pylori"}, {"id": "d", "text": "A rare acid-producing tumor"}]'::jsonb, '["c"]', 'H. pylori infection is the most common cause of ulcers. A rare tumor (Zollinger-Ellison syndrome) can cause ulcers but is rare, and stress and spicy foods do not cause ulcers.'),
  ('pud_gastritis', 6, 'A client with a duodenal ulcer states, ''All the stress at my job and the hot sauce I eat caused my ulcer.'' Which response by the nurse is most accurate?', '[{"id": "a", "text": "Stress and spicy foods are the most common causes of ulcers."}, {"id": "b", "text": "Spicy foods cause ulcers, but stress has no effect on them."}, {"id": "c", "text": "Stress causes ulcers, but spicy foods have no effect on them."}, {"id": "d", "text": "Stress and spicy foods do not cause ulcers but can worsen symptoms."}]'::jsonb, '["d"]', 'Stress and spicy foods do not cause ulcers, but they can worsen symptoms. The most common cause of ulcers is H. pylori infection.'),
  ('pud_gastritis', 7, 'A client with a history of peptic ulcer disease has osteoarthritis and has been taking naproxen daily. Which pain reliever should the nurse anticipate recommending instead?', '[{"id": "a", "text": "Acetaminophen"}, {"id": "b", "text": "Ibuprofen"}, {"id": "c", "text": "Aspirin"}, {"id": "d", "text": "A higher naproxen dose"}]'::jsonb, '["a"]', 'Clients with PUD should avoid NSAIDs and use acetaminophen instead. Ibuprofen and aspirin are NSAIDs, like naproxen, and weaken the stomach lining.'),
  ('pud_gastritis', 8, 'The nurse is reviewing the health history of a client with epigastric pain. Which finding is a risk factor for peptic ulcer disease?', '[{"id": "a", "text": "Acetaminophen use for occasional headaches"}, {"id": "b", "text": "Long-term ibuprofen use for chronic back pain"}, {"id": "c", "text": "Eating small, frequent meals throughout the day"}, {"id": "d", "text": "Famotidine use as prescribed for heartburn"}]'::jsonb, '["b"]', 'Long-term NSAID use, including ibuprofen, weakens the stomach lining and is a risk factor for PUD. Acetaminophen is the recommended alternative to NSAIDs.'),
  ('pud_gastritis', 9, 'A client with recurrent peptic ulcers is found to have a rare tumor that causes excessive stomach acid. The nurse recognizes this condition as which disorder?', '[{"id": "a", "text": "Zollinger-Ellison syndrome"}, {"id": "b", "text": "Gastric outlet obstruction"}, {"id": "c", "text": "H. pylori infection"}, {"id": "d", "text": "Autoimmune gastritis"}]'::jsonb, '["a"]', 'Zollinger-Ellison syndrome is a rare tumor causing excessive stomach acid. Gastric outlet obstruction is narrowing from scarring, not a tumor.'),
  ('pud_gastritis', 10, 'The nurse is teaching a client with peptic ulcer disease about lifestyle changes. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will eat small, frequent meals."}, {"id": "b", "text": "I will use acetaminophen for my headaches."}, {"id": "c", "text": "I can keep smoking since it does not affect ulcers."}, {"id": "d", "text": "I will work on ways to reduce my stress."}]'::jsonb, '["c"]', 'Smoking irritates the stomach lining, and stopping smoking is a recommended lifestyle change. Small frequent meals, acetaminophen instead of NSAIDs, and stress reduction are all correct.'),
  ('pud_gastritis', 11, 'The provider wants to directly visualize a client''s stomach and duodenum to diagnose an ulcer and its complications. The nurse prepares the client for which test?', '[{"id": "a", "text": "Barium swallow X-ray"}, {"id": "b", "text": "Upper endoscopy (EGD)"}, {"id": "c", "text": "H. pylori breath test"}, {"id": "d", "text": "H. pylori stool test"}]'::jsonb, '["b"]', 'EGD uses a camera to examine the stomach and duodenum and is the best test for diagnosing ulcers and their complications. A barium swallow uses contrast and X-ray rather than direct visualization.'),
  ('pud_gastritis', 12, 'A client with suspected peptic ulcer disease is scheduled for H. pylori testing. Which client statement indicates understanding of this testing?', '[{"id": "a", "text": "It can be done using my blood, breath, stool, or a biopsy."}, {"id": "b", "text": "I will swallow contrast so X-rays can show the ulcer."}, {"id": "c", "text": "A camera will be passed to look directly at my ulcer."}, {"id": "d", "text": "It checks for a tumor that makes too much stomach acid."}]'::jsonb, '["a"]', 'H. pylori testing detects H. pylori infection and can use blood, breath, stool, or biopsy. Swallowing contrast describes a barium swallow, and a camera describes EGD.'),
  ('pud_gastritis', 13, 'A client scheduled for a barium swallow asks what the test involves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A camera is passed down to examine the stomach and duodenum."}, {"id": "b", "text": "A breath sample is collected to detect an infection."}, {"id": "c", "text": "A tissue sample is taken to check for H. pylori."}, {"id": "d", "text": "Contrast is swallowed and X-rays are taken to check for ulcers."}]'::jsonb, '["d"]', 'A barium swallow uses contrast plus X-ray to check for ulcers. A camera examining the stomach and duodenum describes an EGD.'),
  ('pud_gastritis', 14, 'A client with a gastric ulcer is prescribed omeprazole. Which instruction should the nurse include?', '[{"id": "a", "text": "Take it with your largest meal of the day."}, {"id": "b", "text": "Take it before meals."}, {"id": "c", "text": "Take it right after you finish eating."}, {"id": "d", "text": "Take it with a bedtime snack."}]'::jsonb, '["b"]', 'PPIs such as omeprazole should be taken before meals. Taking it with or after food does not follow this instruction.'),
  ('pud_gastritis', 15, 'A client has taken pantoprazole daily for several years. The nurse should provide teaching about the increased risk for which condition?', '[{"id": "a", "text": "Gastric outlet obstruction"}, {"id": "b", "text": "H. pylori infection"}, {"id": "c", "text": "Osteoporosis"}, {"id": "d", "text": "Zollinger-Ellison syndrome"}]'::jsonb, '["c"]', 'Long-term PPI use, such as pantoprazole, increases the risk of osteoporosis. Gastric outlet obstruction is a complication of PUD caused by scarring, not a PPI effect.'),
  ('pud_gastritis', 16, 'A client with chronic peptic ulcer symptoms will need acid-reducing therapy for an extended period. Which medication is considered safer for long-term use?', '[{"id": "a", "text": "Omeprazole"}, {"id": "b", "text": "Pantoprazole"}, {"id": "c", "text": "Famotidine"}, {"id": "d", "text": "Tums"}]'::jsonb, '["c"]', 'Famotidine, an H2 blocker, is considered safer for long-term use. PPIs such as omeprazole and pantoprazole carry an osteoporosis risk with long-term use, and antacids like Tums provide only temporary relief.'),
  ('pud_gastritis', 17, 'A client with a duodenal ulcer uses Maalox for symptom relief. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "Maalox works by neutralizing stomach acid."}, {"id": "b", "text": "Maalox should work fast when I take it."}, {"id": "c", "text": "The relief I get from Maalox is temporary."}, {"id": "d", "text": "Maalox gives long-lasting relief by itself."}]'::jsonb, '["d"]', 'Antacids such as Maalox neutralize acid and work fast, but their relief is temporary only. Expecting long-lasting relief indicates a need for further teaching.'),
  ('pud_gastritis', 18, 'A client taking antibiotics for H. pylori reports feeling much better after 4 days and wants to stop the medication. Which response by the nurse is best?', '[{"id": "a", "text": "You may stop once your pain has resolved."}, {"id": "b", "text": "You must finish the full course of antibiotics."}, {"id": "c", "text": "You can stop if you switch to an antacid."}, {"id": "d", "text": "You may skip doses on days you feel well."}]'::jsonb, '["b"]', 'Antibiotics for H. pylori kill the infection and the full course must be completed. Stopping when pain resolves or substituting an antacid, which only neutralizes acid, does not meet this requirement.'),
  ('pud_gastritis', 19, 'A client prescribed sucralfate asks how the medication helps the ulcer. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It coats and protects the ulcer."}, {"id": "b", "text": "It blocks acid production."}, {"id": "c", "text": "It kills H. pylori."}, {"id": "d", "text": "It neutralizes stomach acid."}]'::jsonb, '["a"]', 'Sucralfate is a mucosal protectant that coats and protects the ulcer. Blocking acid production describes PPIs, and neutralizing acid describes antacids.'),
  ('pud_gastritis', 20, 'The nurse is scheduling sucralfate for a client with a duodenal ulcer. Which administration plan is correct?', '[{"id": "a", "text": "Give it with each meal tray."}, {"id": "b", "text": "Give it immediately after meals."}, {"id": "c", "text": "Give it with a bedtime snack."}, {"id": "d", "text": "Give it on an empty stomach."}]'::jsonb, '["d"]', 'Sucralfate, a mucosal protectant, is taken on an empty stomach. Giving it with meals, after meals, or with a snack means it is not taken on an empty stomach.'),
  ('pud_gastritis', 21, 'The nurse is explaining how different ulcer medications work. Which description of antacids such as Tums is accurate?', '[{"id": "a", "text": "They block acid production."}, {"id": "b", "text": "They neutralize stomach acid."}, {"id": "c", "text": "They coat and protect the ulcer."}, {"id": "d", "text": "They kill H. pylori."}]'::jsonb, '["b"]', 'Antacids such as Tums and Maalox neutralize acid. Blocking acid production describes PPIs, and coating the ulcer describes mucosal protectants.'),
  ('pud_gastritis', 22, 'A client with a severe, complicated ulcer is scheduled for a vagotomy and asks about the purpose of the surgery. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It widens the outlet of the stomach."}, {"id": "b", "text": "It removes the H. pylori infection."}, {"id": "c", "text": "It cuts the vagus nerve to reduce acid production."}, {"id": "d", "text": "It allows a camera to view the duodenum."}]'::jsonb, '["c"]', 'A vagotomy cuts the vagus nerve to reduce acid production. Widening the stomach outlet describes pyloroplasty.'),
  ('pud_gastritis', 23, 'A client with a long history of peptic ulcers develops narrowing of the stomach outlet from scarring. Which surgical procedure does the nurse anticipate if surgery is needed?', '[{"id": "a", "text": "Vagotomy"}, {"id": "b", "text": "Barium swallow"}, {"id": "c", "text": "Upper endoscopy"}, {"id": "d", "text": "Pyloroplasty"}]'::jsonb, '["d"]', 'Pyloroplasty widens the stomach outlet when an ulcer causes narrowing. A vagotomy cuts the vagus nerve to reduce acid production and does not widen the outlet.'),
  ('pud_gastritis', 24, 'The nurse is reviewing four clients with peptic ulcer disease. Which client is most likely to be a candidate for surgical treatment?', '[{"id": "a", "text": "A client whose ulcer has perforated"}, {"id": "b", "text": "A client newly diagnosed with H. pylori"}, {"id": "c", "text": "A client with bloating and belching"}, {"id": "d", "text": "A client whose pain is relieved by antacids"}]'::jsonb, '["a"]', 'Surgery is reserved for severe ulcers with complications such as bleeding or perforation. A new H. pylori diagnosis is treated with antibiotics, not surgery.'),
  ('pud_gastritis', 25, 'A client admitted with peptic ulcer disease vomits a large amount of material that looks like coffee grounds. Which action should the nurse take?', '[{"id": "a", "text": "Give a prescribed antacid and reassess in 1 hour"}, {"id": "b", "text": "Report the finding immediately as a GI bleed"}, {"id": "c", "text": "Offer small, frequent meals to settle the stomach"}, {"id": "d", "text": "Document it as an expected finding of PUD"}]'::jsonb, '["b"]', 'Coffee-ground vomit is hematemesis, and bloody stool or vomit indicates a GI bleed, which is an emergency. Giving an antacid and waiting delays emergency care.'),
  ('pud_gastritis', 26, 'The nurse is assessing a client with a gastric ulcer. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Bloating after meals"}, {"id": "b", "text": "Frequent belching"}, {"id": "c", "text": "Black, tarry stools"}, {"id": "d", "text": "Mild nausea"}]'::jsonb, '["c"]', 'Black, tarry stools (melena) indicate a GI bleed, which is an emergency. Bloating, belching, and nausea are common PUD symptoms.'),
  ('pud_gastritis', 27, 'A client with a known duodenal ulcer suddenly reports severe abdominal pain. The nurse should suspect which complication?', '[{"id": "a", "text": "Gastric outlet obstruction"}, {"id": "b", "text": "Expected duodenal ulcer pain"}, {"id": "c", "text": "A flare of gastritis"}, {"id": "d", "text": "Ulcer perforation"}]'::jsonb, '["d"]', 'Sudden severe abdominal pain indicates ulcer perforation, an emergency. Expected duodenal ulcer pain is burning or gnawing and relieved by eating, not sudden and severe.'),
  ('pud_gastritis', 28, 'A client asks why an ulcer perforation is so dangerous. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The ulcer erodes through the stomach wall, leading to peritonitis."}, {"id": "b", "text": "Scar tissue narrows the stomach outlet and blocks food passage."}, {"id": "c", "text": "The vagus nerve is damaged, which stops all acid production."}, {"id": "d", "text": "A tumor begins producing excessive amounts of stomach acid."}]'::jsonb, '["a"]', 'In perforation, the ulcer erodes through the stomach wall, causing peritonitis. Narrowing from scarring describes gastric outlet obstruction.'),
  ('pud_gastritis', 29, 'A client with chronic peptic ulcer disease is diagnosed with gastric outlet obstruction. The nurse understands this complication is caused by which process?', '[{"id": "a", "text": "Erosion of the ulcer through the stomach wall"}, {"id": "b", "text": "Overproduction of acid from a rare tumor"}, {"id": "c", "text": "Narrowing of the outlet from ulcer scarring"}, {"id": "d", "text": "Irritation of the stomach lining by alcohol"}]'::jsonb, '["c"]', 'Gastric outlet obstruction is narrowing caused by scarring. Erosion through the stomach wall describes perforation.'),
  ('pud_gastritis', 30, 'A client asks the nurse whether gastritis and peptic ulcer disease are the same condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "Yes, both terms describe open sores in the stomach."}, {"id": "b", "text": "No, gastritis is irritation, while PUD involves open sores."}, {"id": "c", "text": "No, gastritis involves open sores, while PUD is irritation."}, {"id": "d", "text": "Yes, both terms describe irritation without any sores."}]'::jsonb, '["b"]', 'Gastritis is irritation of the stomach, while PUD involves open sores; they are different conditions. Option c reverses the two definitions.'),
  ('pud_gastritis', 31, 'The nurse is explaining the pathophysiology of peptic ulcer disease to a client. Which statement by the nurse is accurate?', '[{"id": "a", "text": "Spicy foods directly burn holes in the stomach lining."}, {"id": "b", "text": "Emotional stress creates open sores in the duodenum."}, {"id": "c", "text": "The stomach lining is irritated but remains intact."}, {"id": "d", "text": "Acid and digestive enzymes damage the protective lining."}]'::jsonb, '["d"]', 'PUD is caused by stomach acid and digestive enzymes damaging the protective lining, creating open sores. Stress and spicy foods do not cause ulcers, and irritation without sores describes gastritis.'),
  ('pud_gastritis', 32, 'A client diagnosed with gastritis asks what the most common cause of gastritis is. Which response by the nurse is accurate?', '[{"id": "a", "text": "H. pylori infection"}, {"id": "b", "text": "An autoimmune disorder"}, {"id": "c", "text": "Emotional stress"}, {"id": "d", "text": "Alcohol use"}]'::jsonb, '["a"]', 'H. pylori is the most common cause of gastritis. Autoimmune disorders, stress, and alcohol are also causes but are not the most common.'),
  ('pud_gastritis', 33, 'A client develops gastritis after weeks of taking ibuprofen for a sports injury. Which intervention is the priority in treating this client''s gastritis?', '[{"id": "a", "text": "Begin an antibiotic regimen"}, {"id": "b", "text": "Schedule a vagotomy"}, {"id": "c", "text": "Stop the ibuprofen"}, {"id": "d", "text": "Switch to naproxen"}]'::jsonb, '["c"]', 'Gastritis treatment begins with removing the cause, such as stopping NSAIDs. Antibiotics are required only if H. pylori is present, and naproxen is also an NSAID.'),
  ('pud_gastritis', 34, 'A client with gastritis tests positive for H. pylori. Which treatment does the nurse anticipate will be added to the plan of care?', '[{"id": "a", "text": "Pyloroplasty"}, {"id": "b", "text": "Vagotomy"}, {"id": "c", "text": "Ibuprofen"}, {"id": "d", "text": "Antibiotics"}]'::jsonb, '["d"]', 'When H. pylori is present in gastritis, antibiotics are required. Vagotomy and pyloroplasty are surgeries for severe ulcers, and ibuprofen is an NSAID that causes gastritis.'),
  ('pud_gastritis', 35, 'A client with gastritis reports burning stomach pain, nausea, and loss of appetite. Which additional finding indicates the client may be bleeding?', '[{"id": "a", "text": "Belching after meals"}, {"id": "b", "text": "Black, tarry stools"}, {"id": "c", "text": "Increased nausea"}, {"id": "d", "text": "Gnawing stomach pain"}]'::jsonb, '["b"]', 'Black tarry stools in gastritis occur if bleeding is present. Burning or gnawing pain and nausea are expected gastritis symptoms, not signs of bleeding.'),
  ('pud_gastritis', 36, 'A client with peptic ulcer disease usually skips breakfast and lunch and then eats one large dinner. Which recommendation should the nurse make?', '[{"id": "a", "text": "Eat small, frequent meals"}, {"id": "b", "text": "Eat three large meals daily"}, {"id": "c", "text": "Keep eating one large evening meal"}, {"id": "d", "text": "Skip meals to rest the stomach"}]'::jsonb, '["a"]', 'Eating small, frequent meals is a recommended lifestyle change for PUD. Large meals or skipping meals do not follow this recommendation.'),
  ('pud_gastritis', 37, 'The nurse receives report on four clients with peptic ulcer disease. Which client should the nurse assess first?', '[{"id": "a", "text": "A client reporting bloating and belching"}, {"id": "b", "text": "A client with burning pain relieved by eating"}, {"id": "c", "text": "A client with mild nausea after lunch"}, {"id": "d", "text": "A client who vomited coffee-ground material"}]'::jsonb, '["d"]', 'Coffee-ground vomit is hematemesis, a sign of GI bleeding and an emergency. Bloating, belching, nausea, and duodenal pain relieved by eating are common PUD symptoms.'),
  ('pud_gastritis', 38, 'A client hospitalized for a gastric ulcer calls the nurse and reports sudden, severe abdominal pain. Which action should the nurse take first?', '[{"id": "a", "text": "Give a prescribed antacid and reassess"}, {"id": "b", "text": "Offer a small snack to relieve the pain"}, {"id": "c", "text": "Notify the provider of a possible emergency"}, {"id": "d", "text": "Document the pain as expected for PUD"}]'::jsonb, '["c"]', 'Sudden severe pain suggests ulcer perforation, which is an emergency requiring prompt provider notification. An antacid only neutralizes acid temporarily and delays emergency care.'),
  ('pud_gastritis', 39, 'A client with a confirmed duodenal ulcer asks when the pain is likely to be worst. Which response by the nurse is accurate?', '[{"id": "a", "text": "Shortly after eating a large meal"}, {"id": "b", "text": "When the stomach is empty and at night"}, {"id": "c", "text": "Only after taking an antacid"}, {"id": "d", "text": "Mostly while eating meals"}]'::jsonb, '["b"]', 'Duodenal ulcer pain is worse on an empty stomach and at night and is relieved by eating or antacids. Pain that worsens with eating describes a gastric ulcer.'),
  ('pud_gastritis', 40, 'The nurse is assessing a client with a suspected gastric ulcer. Which finding would the nurse expect?', '[{"id": "a", "text": "Pain relieved by eating"}, {"id": "b", "text": "Pain worst on an empty stomach"}, {"id": "c", "text": "Unintentional weight loss"}, {"id": "d", "text": "Weight gain from frequent eating"}]'::jsonb, '["c"]', 'Weight loss is associated with gastric ulcers. Pain relieved by eating and pain worst on an empty stomach are features of duodenal ulcers.'),
  ('pud_gastritis', 41, 'The nurse is reviewing the medication list of a client with peptic ulcer disease. Which medication is a proton pump inhibitor (PPI)?', '[{"id": "a", "text": "Famotidine"}, {"id": "b", "text": "Sucralfate"}, {"id": "c", "text": "Maalox"}, {"id": "d", "text": "Pantoprazole"}]'::jsonb, '["d"]', 'Omeprazole and pantoprazole are PPIs that block acid production. Famotidine is an H2 blocker, sucralfate is a mucosal protectant, and Maalox is an antacid.'),
  ('pud_gastritis', 42, 'The nurse is observing a newly hired nurse caring for clients with peptic ulcer disease. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Giving omeprazole after the client finishes breakfast"}, {"id": "b", "text": "Offering acetaminophen to a client with a headache"}, {"id": "c", "text": "Encouraging the client to eat small, frequent meals"}, {"id": "d", "text": "Reminding the client to finish the antibiotic course"}]'::jsonb, '["a"]', 'PPIs such as omeprazole should be taken before meals, so giving it after breakfast requires correction. Acetaminophen instead of NSAIDs, small frequent meals, and completing antibiotics are all correct.'),
  ('pud_gastritis', 43, 'A client has been taking omeprazole for several years. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "This medicine blocks acid production."}, {"id": "b", "text": "Long-term use does not affect my bones."}, {"id": "c", "text": "I take it before meals each day."}, {"id": "d", "text": "It belongs to the PPI class of drugs."}]'::jsonb, '["b"]', 'Long-term PPI use increases the risk of osteoporosis, so this statement needs correction. Omeprazole is a PPI that blocks acid production and is taken before meals.'),
  ('pud_gastritis', 44, 'A client with peptic ulcer disease reports drinking several alcoholic beverages every night. Which teaching by the nurse is most appropriate?', '[{"id": "a", "text": "Limit alcohol because it irritates the stomach lining."}, {"id": "b", "text": "Alcohol is safe as long as it is taken with food."}, {"id": "c", "text": "Alcohol neutralizes acid and may ease ulcer pain."}, {"id": "d", "text": "Alcohol only matters for clients with gastritis."}]'::jsonb, '["a"]', 'Smoking and alcohol irritate the stomach lining, so clients with PUD should limit alcohol. Neutralizing acid is the action of antacids, not alcohol.'),
  ('pud_gastritis', 45, 'A client with gastritis is receiving treatment for burning stomach pain. Which medication would the nurse expect to be prescribed?', '[{"id": "a", "text": "Naproxen"}, {"id": "b", "text": "Famotidine"}, {"id": "c", "text": "Ibuprofen"}, {"id": "d", "text": "Aspirin"}]'::jsonb, '["b"]', 'Gastritis is treated with PPIs, H2 blockers, and antacids, and famotidine is an H2 blocker. Naproxen, ibuprofen, and aspirin are NSAIDs, which cause gastritis and should be stopped.'),
  ('pud_gastritis', 46, 'A nurse is supervising unlicensed assistive personnel (UAP) caring for a client with peptic ulcer disease. Which UAP action requires correction?', '[{"id": "a", "text": "Reporting that the client vomited coffee-ground material"}, {"id": "b", "text": "Offering the client small, frequent meals as ordered"}, {"id": "c", "text": "Reporting the client''s complaint of bloating"}, {"id": "d", "text": "Flushing a black, tarry stool without reporting it"}]'::jsonb, '["d"]', 'A black, tarry stool is melena, which signals a GI bleed and is an emergency that must be reported. Reporting coffee-ground vomit and offering small, frequent meals are appropriate actions.'),
  ('pud_gastritis', 47, 'An upper endoscopy shows irritation of a client''s stomach lining without any open sores. The nurse recognizes this finding as most consistent with which condition?', '[{"id": "a", "text": "Duodenal ulcer"}, {"id": "b", "text": "Gastric ulcer"}, {"id": "c", "text": "Gastritis"}, {"id": "d", "text": "Ulcer perforation"}]'::jsonb, '["c"]', 'Gastritis is irritation of the stomach, whereas PUD (gastric or duodenal ulcer) involves open sores. Perforation occurs when an ulcer erodes through the stomach wall.'),
  ('pud_gastritis', 48, 'A client with a history of peptic ulcers is being taught about over-the-counter pain relievers. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "Aspirin is a safe choice for my headaches."}, {"id": "b", "text": "I will use acetaminophen for minor pain."}, {"id": "c", "text": "I should avoid taking ibuprofen."}, {"id": "d", "text": "Naproxen can weaken my stomach lining."}]'::jsonb, '["a"]', 'Aspirin is an NSAID that weakens the stomach lining, so it is not a safe choice. Acetaminophen is the recommended alternative to NSAIDs.'),
  ('pud_gastritis', 49, 'A client with an uncomplicated duodenal ulcer reports several symptoms. Which symptom is expected and does not indicate an emergency?', '[{"id": "a", "text": "Coffee-ground vomit"}, {"id": "b", "text": "Sudden severe abdominal pain"}, {"id": "c", "text": "Bloating and belching"}, {"id": "d", "text": "Black, tarry stools"}]'::jsonb, '["c"]', 'Bloating and belching are common PUD symptoms. Coffee-ground vomit and black, tarry stools signal a GI bleed, and sudden severe pain signals perforation; all are emergencies.'),
  ('pud_gastritis', 50, 'The nurse is caring for four clients with gastritis. Which client requires antibiotic therapy?', '[{"id": "a", "text": "A client whose gastritis is caused by NSAIDs"}, {"id": "b", "text": "A client whose gastritis is related to alcohol"}, {"id": "c", "text": "A client whose gastritis is related to stress"}, {"id": "d", "text": "A client whose gastritis is caused by H. pylori"}]'::jsonb, '["d"]', 'H. pylori gastritis requires antibiotics. NSAID-induced gastritis is managed by stopping the drug, and alcohol-related gastritis by removing the cause.'),
  ('gastric_peptic', 1, 'A client with a newly diagnosed gastric ulcer asks how to plan meals at home. Which eating pattern should the nurse recommend?', '[{"id": "a", "text": "Two large meals with no snacks"}, {"id": "b", "text": "One large meal each evening"}, {"id": "c", "text": "Five small meals daily"}, {"id": "d", "text": "Three large meals daily"}]'::jsonb, '["c"]', 'Eating five small meals daily is recommended for better GI health because it reduces the acid load on the stomach. Fewer, larger meals do not follow this recommendation.'),
  ('gastric_peptic', 2, 'A client with a peptic ulcer asks why eating five small meals a day is recommended. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It reduces the acid load on the stomach."}, {"id": "b", "text": "It coats the ulcer to protect it."}, {"id": "c", "text": "It eradicates H. pylori from the stomach."}, {"id": "d", "text": "It replaces the need for a PPI."}]'::jsonb, '["a"]', 'Five small meals daily reduce the acid load on the stomach. Coating the ulcer is the action of sucralfate, and eradicating H. pylori requires triple therapy.'),
  ('gastric_peptic', 3, 'The nurse provides diet teaching to a client with a gastric ulcer. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will spread my food over five small meals."}, {"id": "b", "text": "Smaller meals put less acid load on my stomach."}, {"id": "c", "text": "Eating smaller meals is better for my GI health."}, {"id": "d", "text": "I will eat two large meals so my stomach can rest."}]'::jsonb, '["d"]', 'Five small meals daily are recommended because they reduce acid load on the stomach, so eating two large meals needs correction. The other statements reflect correct understanding.'),
  ('gastric_peptic', 4, 'A nurse is supervising unlicensed assistive personnel (UAP) helping a client with a peptic ulcer at mealtime. Which UAP action requires correction?', '[{"id": "a", "text": "Encouraging the client to eat one large meal"}, {"id": "b", "text": "Offering a small meal at the scheduled time"}, {"id": "c", "text": "Reporting that the client vomited blood"}, {"id": "d", "text": "Reporting the client''s tarry black stool"}]'::jsonb, '["a"]', 'Five small meals daily are recommended for GI health, so encouraging one large meal requires correction. Reporting bloody vomit and tarry black stools is appropriate because these are emergency findings.'),
  ('gastric_peptic', 5, 'A client asks the nurse how a peptic ulcer forms. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Excess mucus builds up and blocks the stomach outlet."}, {"id": "b", "text": "The protective stomach lining erodes and is exposed to acid."}, {"id": "c", "text": "The vagus nerve is cut, which causes acid to build up."}, {"id": "d", "text": "Stomach acid is neutralized, which damages the lining."}]'::jsonb, '["b"]', 'In ulcer formation, the mucus layer is damaged and the protective stomach lining erodes, exposing it to acid. Cutting the vagus nerve is a surgery (vagotomy) that reduces acid.'),
  ('gastric_peptic', 6, 'The nurse is reviewing the history of a client with epigastric pain. Which finding is a cause of mucus layer damage associated with gastric ulcers?', '[{"id": "a", "text": "Taking calcium and vitamin D3"}, {"id": "b", "text": "Eating five small meals daily"}, {"id": "c", "text": "Using enteric-coated medications"}, {"id": "d", "text": "Heavy daily alcohol intake"}]'::jsonb, '["d"]', 'Alcohol is a cause of mucus layer damage that leads to ulcers. Enteric-coated medications protect the stomach from direct irritation, and five small meals daily reduce acid load.'),
  ('gastric_peptic', 7, 'A client with an H. pylori-positive peptic ulcer is started on triple therapy. The nurse explains that the main goal of triple therapy is to:', '[{"id": "a", "text": "coat the ulcer to protect it from acid"}, {"id": "b", "text": "heal the ulcer by eradicating its cause"}, {"id": "c", "text": "neutralize acid already in the stomach"}, {"id": "d", "text": "widen a narrowed stomach outlet"}]'::jsonb, '["b"]', 'Triple therapy for H. pylori is part of healing treatment, which eradicates the cause. Coating the ulcer is protective treatment provided by sucralfate.'),
  ('gastric_peptic', 8, 'The nurse reviews prescriptions for a client with an H. pylori infection. Which combination reflects triple therapy?', '[{"id": "a", "text": "Amoxicillin, clarithromycin, and omeprazole"}, {"id": "b", "text": "Amoxicillin, sucralfate, and omeprazole"}, {"id": "c", "text": "Clarithromycin, antacids, and sucralfate"}, {"id": "d", "text": "Amoxicillin, clarithromycin, and sucralfate"}]'::jsonb, '["a"]', 'Triple therapy for H. pylori is amoxicillin plus clarithromycin plus omeprazole. Sucralfate is a protective coating agent, not part of triple therapy.'),
  ('gastric_peptic', 9, 'A client is receiving triple therapy for H. pylori. Which client statement indicates understanding of the treatment?', '[{"id": "a", "text": "I''ll stop the antibiotics once my pain is gone."}, {"id": "b", "text": "I''ll take the antibiotics only when I have pain."}, {"id": "c", "text": "I will finish the entire antibiotic course."}, {"id": "d", "text": "I can skip omeprazole if I take the antibiotics."}]'::jsonb, '["c"]', 'With triple therapy, the full antibiotic course must be completed. Omeprazole is one of the three drugs in triple therapy, so it should not be skipped.'),
  ('gastric_peptic', 10, 'A client with a peptic ulcer is prescribed a medication that works by coating the ulcer. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Omeprazole"}, {"id": "b", "text": "Amoxicillin"}, {"id": "c", "text": "Clarithromycin"}, {"id": "d", "text": "Sucralfate"}]'::jsonb, '["d"]', 'Sucralfate provides a protective coating over the ulcer. Omeprazole is a PPI, and amoxicillin and clarithromycin are antibiotics in triple therapy.'),
  ('gastric_peptic', 11, 'The nurse is grouping a client''s ulcer medications by purpose. Which medication belongs to the protective group that reduces acid and coats the ulcer?', '[{"id": "a", "text": "Amoxicillin"}, {"id": "b", "text": "Clarithromycin"}, {"id": "c", "text": "Antacids"}, {"id": "d", "text": "Calcium with vitamin D3"}]'::jsonb, '["c"]', 'Protective treatment includes sucralfate, antacids, H2 blockers, and PPIs. Amoxicillin and clarithromycin are part of triple therapy, which is healing treatment that eradicates the cause.'),
  ('gastric_peptic', 12, 'A client with a gastric ulcer asks why the provider ordered an enteric-coated form of a medication. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It protects the stomach from direct irritation."}, {"id": "b", "text": "It kills H. pylori in the stomach lining."}, {"id": "c", "text": "It neutralizes acid already in the stomach."}, {"id": "d", "text": "It reduces the risk of osteoporosis."}]'::jsonb, '["a"]', 'Enteric-coated medications protect the stomach from direct irritation. Killing H. pylori requires triple therapy, and osteoporosis risk is reduced with calcium and vitamin D3.'),
  ('gastric_peptic', 13, 'A client''s medication list includes esomeprazole. The nurse recognizes that this drug belongs to which group?', '[{"id": "a", "text": "Antibiotics used in triple therapy"}, {"id": "b", "text": "Proton pump inhibitors"}, {"id": "c", "text": "Ulcer-coating agents"}, {"id": "d", "text": "Calcium supplements"}]'::jsonb, '["b"]', 'Esomeprazole is one of the listed proton pump inhibitors. The antibiotics in triple therapy are amoxicillin and clarithromycin, and the ulcer-coating agent is sucralfate.'),
  ('gastric_peptic', 14, 'A client is prescribed dexlansoprazole for a peptic ulcer. Which instruction should the nurse provide?', '[{"id": "a", "text": "Take it with your evening meal."}, {"id": "b", "text": "Take it right after breakfast."}, {"id": "c", "text": "Take it with a bedtime snack."}, {"id": "d", "text": "Take it on an empty stomach before meals."}]'::jsonb, '["d"]', 'Dexlansoprazole is a PPI, and PPIs are taken on an empty stomach before meals. Taking it with or after food does not follow this rule.'),
  ('gastric_peptic', 15, 'The nurse evaluates teaching for a client prescribed pantoprazole. Which client statement indicates correct understanding?', '[{"id": "a", "text": "I take it with my heaviest meal of the day."}, {"id": "b", "text": "I take it on an empty stomach before breakfast."}, {"id": "c", "text": "I take it right after I finish my lunch."}, {"id": "d", "text": "I take it with a snack before going to bed."}]'::jsonb, '["b"]', 'Pantoprazole is a PPI, which is taken on an empty stomach before meals. The other statements describe taking it with or after food.'),
  ('gastric_peptic', 16, 'A charge nurse overhears a nurse explaining ulcer treatments to a client. Which statement by the nurse requires correction?', '[{"id": "a", "text": "Pyloroplasty cuts the vagus nerve to reduce acid."}, {"id": "b", "text": "Sucralfate forms a coating over the ulcer."}, {"id": "c", "text": "Enteric coating protects the stomach from irritation."}, {"id": "d", "text": "Five small meals reduce the acid load on the stomach."}]'::jsonb, '["a"]', 'Vagotomy, not pyloroplasty, cuts the vagus nerve to reduce acid overproduction; pyloroplasty widens the stomach outlet. The other statements are accurate.'),
  ('gastric_peptic', 17, 'A client has been taking omeprazole long term. Which supplements does the nurse anticipate will be recommended to reduce the client''s risk of osteoporosis?', '[{"id": "a", "text": "Calcium and vitamin D3"}, {"id": "b", "text": "Iron and vitamin C"}, {"id": "c", "text": "Potassium and magnesium"}, {"id": "d", "text": "Folic acid and vitamin B12"}]'::jsonb, '["a"]', 'Long-term PPI use carries an osteoporosis risk, which is addressed by supplementing calcium and vitamin D3. The other supplement pairs are not the recommended response to this risk.'),
  ('gastric_peptic', 18, 'The nurse teaches a client about the risks of long-term PPI use. Which client statement indicates understanding?', '[{"id": "a", "text": "Long-term use will make my bones stronger."}, {"id": "b", "text": "It can raise my risk of C. diff and pneumonia."}, {"id": "c", "text": "It is safe to take for years with no added risk."}, {"id": "d", "text": "It works best when taken right after meals."}]'::jsonb, '["b"]', 'Long-term PPI use increases the risk of C. diff infection and pneumonia, as well as osteoporosis. PPIs weaken rather than strengthen bone and are taken on an empty stomach.'),
  ('gastric_peptic', 19, 'The nurse is reviewing four clients with peptic ulcers. Which client has the greatest risk for complications related to proton pump inhibitor therapy?', '[{"id": "a", "text": "A client who completed a short PPI course"}, {"id": "b", "text": "A client who takes sucralfate as prescribed"}, {"id": "c", "text": "A client who eats five small meals daily"}, {"id": "d", "text": "A client who has taken a PPI daily for years"}]'::jsonb, '["d"]', 'Long-term PPI use increases the risk of osteoporosis, C. diff, and pneumonia. PPIs are intended for short-term use, so a completed short course carries less risk.'),
  ('gastric_peptic', 20, 'A client taking pantoprazole long term receives teaching about bone health. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will take calcium as recommended."}, {"id": "b", "text": "I will take vitamin D3 as recommended."}, {"id": "c", "text": "This medicine can raise my osteoporosis risk."}, {"id": "d", "text": "This medicine will help keep my bones strong."}]'::jsonb, '["d"]', 'Long-term PPI use raises osteoporosis risk, so believing it keeps bones strong needs correction. Supplementing calcium and vitamin D3 is the recommended approach.'),
  ('gastric_peptic', 21, 'A client with a gastric ulcer suddenly develops severe abdominal pain, fever, and a rigid, board-like abdomen. The nurse suspects which complication?', '[{"id": "a", "text": "Expected post-meal ulcer pain"}, {"id": "b", "text": "Dyspepsia from a large meal"}, {"id": "c", "text": "Ulcer perforation with peritonitis"}, {"id": "d", "text": "A side effect of PPI therapy"}]'::jsonb, '["c"]', 'Severe pain, fever, and a board-like abdomen are signs of gastric ulcer rupture or perforation with peritonitis. Dyspepsia is an expected ulcer symptom and does not cause a rigid abdomen.'),
  ('gastric_peptic', 22, 'A client with a peptic ulcer shows signs of ulcer perforation. Which intervention should the nurse anticipate as the priority?', '[{"id": "a", "text": "Preparing for immediate surgical intervention"}, {"id": "b", "text": "Giving an antacid and reassessing later"}, {"id": "c", "text": "Offering a small meal to ease the pain"}, {"id": "d", "text": "Starting triple therapy for H. pylori"}]'::jsonb, '["a"]', 'Gastric ulcer rupture or perforation is an emergency requiring immediate surgical intervention. Antacids and triple therapy are ulcer treatments that do not address perforation.'),
  ('gastric_peptic', 23, 'During evening rounds, a client admitted with a gastric ulcer reports new symptoms. Which finding requires immediate notification of the provider?', '[{"id": "a", "text": "Bloating after a meal"}, {"id": "b", "text": "Dyspepsia after lunch"}, {"id": "c", "text": "Epigastric pain after eating"}, {"id": "d", "text": "Fever with severe abdominal pain"}]'::jsonb, '["d"]', 'Severe pain and fever are signs of gastric ulcer rupture or perforation, an emergency. Bloating, dyspepsia, and epigastric pain after eating are expected ulcer symptoms.'),
  ('gastric_peptic', 24, 'A client has a peptic ulcer associated with acid overproduction that requires surgery. Which procedure and description does the nurse anticipate?', '[{"id": "a", "text": "Pyloroplasty, which widens the stomach outlet"}, {"id": "b", "text": "Vagotomy, which cuts the vagus nerve"}, {"id": "c", "text": "Pyloroplasty, which cuts the vagus nerve"}, {"id": "d", "text": "Vagotomy, which widens the stomach outlet"}]'::jsonb, '["b"]', 'Vagotomy is indicated to reduce acid overproduction and works by cutting the vagus nerve. Pyloroplasty widens the stomach outlet and is indicated for ulcer-induced narrowing, not acid overproduction.'),
  ('gastric_peptic', 25, 'A client with a gastric ulcer has severe pain and passes tarry black stools. The nurse documents the stool finding using which term?', '[{"id": "a", "text": "Dyspepsia"}, {"id": "b", "text": "Melena"}, {"id": "c", "text": "Hematemesis"}, {"id": "d", "text": "Distention"}]'::jsonb, '["b"]', 'Melena refers to tarry black stools and is listed among the signs of gastric ulcer rupture or perforation. Hematemesis refers to bloody vomit.'),
  ('gastric_peptic', 26, 'A client with a gastric ulcer asks when epigastric pain typically occurs. Which response by the nurse is accurate?', '[{"id": "a", "text": "Immediately after eating"}, {"id": "b", "text": "Only during the night"}, {"id": "c", "text": "When the stomach is empty"}, {"id": "d", "text": "Only after missing a meal"}]'::jsonb, '["a"]', 'Epigastric pain occurring immediately after eating is a symptom of gastric and peptic ulcers. Pain linked to an empty stomach or missed meals does not match this pattern.'),
  ('gastric_peptic', 27, 'Which cluster of findings should the nurse expect in a client with an uncomplicated gastric ulcer?', '[{"id": "a", "text": "Fever, severe pain, and a board-like abdomen"}, {"id": "b", "text": "Bloody vomit, fever, and tarry black stools"}, {"id": "c", "text": "Severe pain, fever, and bloody vomit"}, {"id": "d", "text": "Bloating, dyspepsia, and abdominal distention"}]'::jsonb, '["d"]', 'Bloating, dyspepsia, and abdominal distention are listed symptoms of gastric and peptic ulcers. Fever, severe pain, bloody vomit, and a board-like abdomen are signs of rupture or perforation.'),
  ('gastric_peptic', 28, 'The nurse receives report on four clients with gastric ulcers. Which client should the nurse see first?', '[{"id": "a", "text": "A client with bloating after breakfast"}, {"id": "b", "text": "A client with dyspepsia after lunch"}, {"id": "c", "text": "A client with a rigid, board-like abdomen"}, {"id": "d", "text": "A client asking about calcium supplements"}]'::jsonb, '["c"]', 'A board-like rigid abdomen indicates peritonitis, which is a surgical emergency. Bloating and dyspepsia are expected ulcer symptoms.'),
  ('gastric_peptic', 29, 'A client''s peptic ulcer has not responded to several months of medication therapy. How should the nurse interpret this situation?', '[{"id": "a", "text": "It is an indication for surgical treatment."}, {"id": "b", "text": "It is expected and requires no change."}, {"id": "c", "text": "It is a reason to stop all ulcer medications."}, {"id": "d", "text": "It is a reason to continue PPIs indefinitely."}]'::jsonb, '["a"]', 'Refractory ulcers that do not respond to medications are an indication for surgery. Continuing PPIs indefinitely is not appropriate because long-term PPI use carries risks of osteoporosis, C. diff, and pneumonia.'),
  ('gastric_peptic', 30, 'Diagnostic findings raise suspicion that a client''s gastric ulcer may be malignant. Which next step in management does the nurse anticipate?', '[{"id": "a", "text": "Antacids as needed"}, {"id": "b", "text": "Evaluation for surgery"}, {"id": "c", "text": "Five small meals daily"}, {"id": "d", "text": "Calcium and vitamin D3"}]'::jsonb, '["b"]', 'Suspicion of malignancy is an indication for surgery. Antacids and small meals are routine ulcer measures, and calcium with vitamin D3 addresses PPI-related osteoporosis risk.'),
  ('gastric_peptic', 31, 'A client with a peptic ulcer has active bleeding that cannot be controlled with medical treatment. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Adding antacids to the regimen"}, {"id": "b", "text": "Switching to five small meals"}, {"id": "c", "text": "Preparing the client for surgery"}, {"id": "d", "text": "Starting calcium and vitamin D3"}]'::jsonb, '["c"]', 'Active or uncontrolled bleeding is an indication for surgery. Antacids and small meals are routine measures that do not address uncontrolled bleeding.'),
  ('gastric_peptic', 32, 'A client scheduled for pyloroplasty asks what the procedure will do. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It cuts the vagus nerve to reduce acid."}, {"id": "b", "text": "It widens a stomach outlet narrowed by the ulcer."}, {"id": "c", "text": "It coats the ulcer to protect it from acid."}, {"id": "d", "text": "It removes H. pylori from the stomach."}]'::jsonb, '["b"]', 'Pyloroplasty widens the stomach outlet and is indicated for ulcer-induced narrowing. Cutting the vagus nerve describes vagotomy.'),
  ('gastric_peptic', 33, 'A client reports epigastric pain immediately after eating, bloating, and dyspepsia. While exploring possible causes of mucus layer damage, which factor should the nurse ask about?', '[{"id": "a", "text": "Sucralfate use"}, {"id": "b", "text": "Calcium with vitamin D3"}, {"id": "c", "text": "H. pylori infection"}, {"id": "d", "text": "Eating five small meals"}]'::jsonb, '["c"]', 'H. pylori is a cause of mucus layer damage leading to ulcers. Sucralfate coats and protects the ulcer, and five small meals daily reduce acid load.'),
  ('gastric_peptic', 34, 'A client with a peptic ulcer develops an obstruction and asks why surgery is being considered. Which response by the nurse is accurate?', '[{"id": "a", "text": "Obstruction is an indication for ulcer surgery."}, {"id": "b", "text": "Surgery is done for all ulcers that cause bloating."}, {"id": "c", "text": "Surgery is routinely done before triple therapy."}, {"id": "d", "text": "Surgery is needed whenever a PPI is prescribed."}]'::jsonb, '["a"]', 'Obstruction is one of the indications for surgery. Bloating is an expected ulcer symptom, and triple therapy and PPIs are medical treatments that do not by themselves call for surgery.'),
  ('gastric_peptic', 35, 'A client with a peptic ulcer reports drinking alcohol every day. Which teaching by the nurse is most appropriate?', '[{"id": "a", "text": "Alcohol neutralizes acid, so it may ease pain."}, {"id": "b", "text": "Alcohol is safe if taken with a small meal."}, {"id": "c", "text": "Alcohol can damage the stomach''s mucus layer."}, {"id": "d", "text": "Alcohol only matters during triple therapy."}]'::jsonb, '["c"]', 'Alcohol is a cause of mucus layer damage leading to ulcers, so lifestyle changes are part of healing. Neutralizing acid is the action of antacids, not alcohol.'),
  ('gastric_peptic', 36, 'A client with an H. pylori-positive ulcer asks how the infection led to the ulcer. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "H. pylori damages the protective mucus layer."}, {"id": "b", "text": "H. pylori widens the stomach outlet."}, {"id": "c", "text": "H. pylori neutralizes stomach acid."}, {"id": "d", "text": "H. pylori coats the stomach lining."}]'::jsonb, '["a"]', 'H. pylori causes mucus layer damage, so the protective lining erodes and is exposed to acid. Coating the lining is the protective action of sucralfate.'),
  ('gastric_peptic', 37, 'Which medication used for a client with an H. pylori ulcer is part of triple therapy and also belongs to the acid-reducing protective group?', '[{"id": "a", "text": "Amoxicillin"}, {"id": "b", "text": "Clarithromycin"}, {"id": "c", "text": "Sucralfate"}, {"id": "d", "text": "Omeprazole"}]'::jsonb, '["d"]', 'Omeprazole is a PPI, which is protective therapy, and it is part of triple therapy. Amoxicillin and clarithromycin are triple therapy antibiotics, and sucralfate is protective but not part of triple therapy.'),
  ('gastric_peptic', 38, 'Unlicensed assistive personnel (UAP) report four observations on clients with gastric ulcers. Which report requires the nurse''s immediate action?', '[{"id": "a", "text": "A client finished a small lunch"}, {"id": "b", "text": "A client reports mild bloating"}, {"id": "c", "text": "A client vomited bloody material"}, {"id": "d", "text": "A client reports dyspepsia"}]'::jsonb, '["c"]', 'Bloody vomit (hematemesis) is listed among the signs of gastric ulcer rupture or perforation, an emergency. Bloating and dyspepsia are expected ulcer symptoms.'),
  ('gastric_peptic', 39, 'A client with a peptic ulcer is diagnosed with perforation. Which statement by the nurse about treatment is accurate?', '[{"id": "a", "text": "Perforation is managed with antacids."}, {"id": "b", "text": "Perforation heals with five small meals."}, {"id": "c", "text": "Perforation resolves with triple therapy."}, {"id": "d", "text": "Perforation requires immediate surgery."}]'::jsonb, '["d"]', 'Gastric ulcer rupture or perforation is an emergency requiring immediate surgical intervention. Antacids, small meals, and triple therapy are routine ulcer treatments.'),
  ('gastric_peptic', 40, 'A client with a gastric ulcer reports dyspepsia after meals. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is an expected symptom of the ulcer."}, {"id": "b", "text": "It indicates ulcer perforation."}, {"id": "c", "text": "It is a sign of peritonitis."}, {"id": "d", "text": "It indicates PPI-related pneumonia."}]'::jsonb, '["a"]', 'Dyspepsia is a listed symptom of gastric and peptic ulcers. Peritonitis is indicated by a board-like abdomen, not dyspepsia.'),
  ('gastric_peptic', 41, 'The nurse palpates the abdomen of a client with a gastric ulcer. Which finding indicates a surgical emergency?', '[{"id": "a", "text": "Mild abdominal distention"}, {"id": "b", "text": "Rigid, board-like abdomen"}, {"id": "c", "text": "Bloating after meals"}, {"id": "d", "text": "Epigastric pain after eating"}]'::jsonb, '["b"]', 'A board-like abdomen indicates peritonitis, which is a surgical emergency. Abdominal distention and bloating are expected ulcer symptoms.'),
  ('gastric_peptic', 42, 'The nurse is explaining a client''s ulcer treatment plan. Which component is part of healing therapy aimed at eradicating the cause?', '[{"id": "a", "text": "Antacids"}, {"id": "b", "text": "H2 blockers"}, {"id": "c", "text": "Sucralfate coating"}, {"id": "d", "text": "Lifestyle changes"}]'::jsonb, '["d"]', 'Lifestyle changes are part of healing treatment, which eradicates the cause. Antacids, H2 blockers, and sucralfate coating are protective treatments that reduce acid and coat the ulcer.'),
  ('gastric_peptic', 43, 'A client with an H. pylori-positive ulcer has been taking only antacids and asks if this is enough. Which response by the nurse is best?', '[{"id": "a", "text": "Yes, antacids heal the ulcer by removing its cause."}, {"id": "b", "text": "No, antacids protect, but triple therapy treats the cause."}, {"id": "c", "text": "Yes, as long as you also eat five small meals daily."}, {"id": "d", "text": "No, you should switch to sucralfate by itself instead."}]'::jsonb, '["b"]', 'Antacids are protective treatment, while triple therapy is healing treatment that eradicates H. pylori. Sucralfate is also only protective and does not eradicate the cause.'),
  ('gastric_peptic', 44, 'The nurse reviews the medication list of a client admitted with pneumonia. Which long-term medication should the nurse recognize as possibly contributing to this risk?', '[{"id": "a", "text": "Amoxicillin"}, {"id": "b", "text": "Rabeprazole"}, {"id": "c", "text": "Sucralfate"}, {"id": "d", "text": "Clarithromycin"}]'::jsonb, '["b"]', 'Rabeprazole is a PPI, and long-term PPI use increases pneumonia risk. Amoxicillin and clarithromycin are antibiotics in triple therapy, and sucralfate is a coating agent.'),
  ('gastric_peptic', 45, 'The nurse teaches a client about H. pylori triple therapy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "Amoxicillin is one of my antibiotics."}, {"id": "b", "text": "Clarithromycin is one of my antibiotics."}, {"id": "c", "text": "Omeprazole is part of my triple therapy."}, {"id": "d", "text": "Sucralfate is part of my triple therapy."}]'::jsonb, '["d"]', 'Triple therapy is amoxicillin, clarithromycin, and omeprazole. Sucralfate is a protective coating agent and is not part of triple therapy.'),
  ('gastric_peptic', 46, 'A client with a peptic ulcer asks why an H2 blocker was prescribed. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It is protective therapy that reduces acid."}, {"id": "b", "text": "It is an antibiotic that kills H. pylori."}, {"id": "c", "text": "It widens the narrowed stomach outlet."}, {"id": "d", "text": "It supplements calcium to protect bones."}]'::jsonb, '["a"]', 'H2 blockers are part of protective treatment, which reduces acid and coats the ulcer. Eradicating H. pylori is done with triple therapy antibiotics.'),
  ('gastric_peptic', 47, 'A nursing student reviews indications for ulcer surgery. Which client situation should the student identify as an indication?', '[{"id": "a", "text": "A small ulcer healing with triple therapy"}, {"id": "b", "text": "An ulcer causing only mild dyspepsia"}, {"id": "c", "text": "A giant ulcer found on diagnostic testing"}, {"id": "d", "text": "An ulcer improving with sucralfate"}]'::jsonb, '["c"]', 'Giant ulcers are an indication for surgery. Ulcers that are healing or improving with medications and mild dyspepsia do not meet surgical indications.'),
  ('gastric_peptic', 48, 'A client with a gastric ulcer reports mild abdominal distention after meals but has no fever and a soft abdomen. Which nursing response is most appropriate?', '[{"id": "a", "text": "Prepare the client for emergency surgery"}, {"id": "b", "text": "Stop the client''s PPI immediately"}, {"id": "c", "text": "Recognize distention as a common ulcer symptom"}, {"id": "d", "text": "Hold all meals until the provider is notified"}]'::jsonb, '["c"]', 'Abdominal distention is a listed symptom of gastric and peptic ulcers. Emergency surgery is required for perforation, signaled by severe pain, fever, and a board-like abdomen.'),
  ('gastric_peptic', 49, 'A client who has taken omeprazole daily for a long time is receiving discharge teaching. Which medication-related risk should the nurse include?', '[{"id": "a", "text": "Peritonitis"}, {"id": "b", "text": "Gastric outlet narrowing"}, {"id": "c", "text": "C. difficile infection"}, {"id": "d", "text": "Ulcer perforation"}]'::jsonb, '["c"]', 'Long-term PPI use increases the risk of C. difficile infection, along with osteoporosis and pneumonia. Peritonitis, narrowing, and perforation are ulcer complications, not PPI risks.'),
  ('gastric_peptic', 50, 'The nurse teaches a client with a gastric ulcer which findings require immediate attention. Which client statement indicates understanding?', '[{"id": "a", "text": "I should report bloating after meals right away."}, {"id": "b", "text": "I should report dyspepsia as an emergency."}, {"id": "c", "text": "I should report mild distention immediately."}, {"id": "d", "text": "I should report fever with severe stomach pain."}]'::jsonb, '["d"]', 'Severe pain and fever are signs of gastric ulcer rupture or perforation, an emergency requiring immediate surgical intervention. Bloating, dyspepsia, and distention are expected ulcer symptoms.'),
  ('cholecystitis', 1, 'A client is admitted with acute cholecystitis. Which assessment finding does the nurse expect?', '[{"id": "a", "text": "Right upper quadrant pain radiating to the right shoulder"}, {"id": "b", "text": "Left lower quadrant pain radiating to the left groin"}, {"id": "c", "text": "Left upper quadrant pain radiating to the left arm"}, {"id": "d", "text": "Lower midline pain radiating to the inner thigh"}]'::jsonb, '["a"]', 'Classic cholecystitis pain is in the right upper quadrant and radiates to the right shoulder or back. Left-sided or lower abdominal pain patterns are not the classic presentation.'),
  ('cholecystitis', 2, 'The nurse is assessing a client with suspected cholecystitis for Murphy''s sign. Which finding indicates a positive Murphy''s sign?', '[{"id": "a", "text": "Bluish discoloration that appears around the umbilicus"}, {"id": "b", "text": "Itching of the skin that worsens after a fatty meal"}, {"id": "c", "text": "Pain when pressing under the right ribcage on deep inspiration"}, {"id": "d", "text": "Rigid abdomen with pain when the client lies flat"}]'::jsonb, '["c"]', 'Murphy''s sign is pain when the examiner presses under the right ribcage while the client breathes deeply. A rigid abdomen points to peritonitis, not Murphy''s sign.'),
  ('cholecystitis', 3, 'A client with gallstones reports episodes of nausea and vomiting. Which history is most consistent with these episodes?', '[{"id": "a", "text": "Symptoms that begin after drinking plain water"}, {"id": "b", "text": "Symptoms that begin after eating fatty foods"}, {"id": "c", "text": "Symptoms that improve after eating a large meal"}, {"id": "d", "text": "Symptoms that occur only during exercise"}]'::jsonb, '["b"]', 'Nausea and vomiting in cholecystitis classically occur after fatty foods. Water intake or exercise is not identified as the trigger.'),
  ('cholecystitis', 4, 'A client with cholelithiasis is being monitored for bile duct obstruction. Which group of findings should the nurse report as indicating obstructed bile flow?', '[{"id": "a", "text": "Pale urine, dark stools, and pink skin"}, {"id": "b", "text": "Jaundice, pale urine, and dark brown stools"}, {"id": "c", "text": "Fever, diarrhea, and green stools"}, {"id": "d", "text": "Jaundice, dark urine, and clay-colored stools"}]'::jsonb, '["d"]', 'Jaundice, dark urine, and clay-colored stools together signal obstructed bile flow. Pale urine and dark stools are the opposite of the expected pattern.'),
  ('cholecystitis', 5, 'A client with a blocked common bile duct asks why the stools have become pale and clay colored. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Bile is not reaching your intestines.\""}, {"id": "b", "text": "\"Your gallbladder is making too much bile.\""}, {"id": "c", "text": "\"Extra bilirubin is collecting in your stool.\""}, {"id": "d", "text": "\"Your liver has stopped storing bile.\""}]'::jsonb, '["a"]', 'Clay-colored stools occur because no bile is reaching the intestines. Excess bilirubin explains dark urine, not pale stools.'),
  ('cholecystitis', 6, 'A client with cholelithiasis has tea-colored urine and yellow sclerae. The nurse recognizes that the dark urine is most likely caused by which factor?', '[{"id": "a", "text": "Dehydration from fasting before surgery"}, {"id": "b", "text": "Bleeding from a perforated gallbladder"}, {"id": "c", "text": "Excess bilirubin from blocked bile flow"}, {"id": "d", "text": "Infection spreading to the urinary tract"}]'::jsonb, '["c"]', 'Dark urine with bile duct obstruction reflects excess bilirubin. The other explanations are not linked to dark urine in cholelithiasis.'),
  ('cholecystitis', 7, 'A jaundiced client with a bile duct obstruction reports intense itching of the skin. The nurse understands that this symptom results from which process?', '[{"id": "a", "text": "An allergic reaction to IV antibiotics"}, {"id": "b", "text": "Bile building up in the body"}, {"id": "c", "text": "Dry skin from prolonged NPO status"}, {"id": "d", "text": "Infection of the abdominal lining"}]'::jsonb, '["b"]', 'Pruritus with bile duct obstruction is itchy skin caused by bile buildup. Peritonitis is infection of the abdominal lining and does not explain itching.'),
  ('cholecystitis', 8, 'A client has a diagnosis of chronic cholecystitis. Which client report is most consistent with this condition?', '[{"id": "a", "text": "\"My stomach feels better after I eat fried food.\""}, {"id": "b", "text": "\"I only feel discomfort when I skip meals.\""}, {"id": "c", "text": "\"My skin itches only after I drink water.\""}, {"id": "d", "text": "\"I keep getting indigestion and bloating after fatty meals.\""}]'::jsonb, '["d"]', 'Chronic cholecystitis causes recurring indigestion (dyspepsia) and fat intolerance with bloating after fatty foods. Relief after fried food is the opposite of fat intolerance.'),
  ('cholecystitis', 9, 'A client newly diagnosed with acute cholecystitis asks what most commonly causes this condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A gallstone blocking the duct leading out of the gallbladder.\""}, {"id": "b", "text": "\"The gallbladder producing too little bile for digestion.\""}, {"id": "c", "text": "\"An infection that starts in the lining of the abdomen.\""}, {"id": "d", "text": "\"A shortage of fat-soluble vitamins in the diet.\""}]'::jsonb, '["a"]', 'The most common cause of cholecystitis is a gallstone blocking the cystic duct, which connects the gallbladder to the bile duct. Bile is produced by the liver, not the gallbladder.'),
  ('cholecystitis', 10, 'The nurse is reviewing the records of several clients. Which client is at greatest risk for acalculous cholecystitis?', '[{"id": "a", "text": "A client with seasonal allergies treated with nasal spray"}, {"id": "b", "text": "A client with a history of well-controlled hypertension"}, {"id": "c", "text": "A septic client in intensive care who has been fasting"}, {"id": "d", "text": "A client who eats three balanced meals each day"}]'::jsonb, '["c"]', 'Acalculous cholecystitis can result from trauma, sepsis, or fasting. The septic, fasting client has two of these risk factors.'),
  ('cholecystitis', 11, 'A client with severe trauma develops cholecystitis, and the ultrasound shows no gallstones. The family asks what this diagnosis means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The gallbladder has been removed without complications.\""}, {"id": "b", "text": "\"The gallbladder is inflamed even though no stones are present.\""}, {"id": "c", "text": "\"The gallstones have moved into the small intestine.\""}, {"id": "d", "text": "\"The gallbladder is normal, but the liver is inflamed.\""}]'::jsonb, '["b"]', 'Acalculous cholecystitis is inflammation of the gallbladder without gallstones, and trauma is one cause. It does not mean the stones have passed or that the gallbladder is normal.'),
  ('cholecystitis', 12, 'The nurse teaches a client about gallbladder disease. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"My gallbladder is a small organ under my liver.\""}, {"id": "b", "text": "\"Gallstones are hardened deposits of bile.\""}, {"id": "c", "text": "\"Bile helps my body absorb vitamins A, D, E, and K.\""}, {"id": "d", "text": "\"My gallbladder is the organ that makes my bile.\""}]'::jsonb, '["d"]', 'Bile is produced by the liver and stored in the gallbladder, so this statement needs correction. The other statements are accurate.'),
  ('cholecystitis', 13, 'A client with acute cholecystitis wants to delay treatment. The nurse explains that untreated cholecystitis may lead to which complication?', '[{"id": "a", "text": "Gangrene and perforation of the gallbladder"}, {"id": "b", "text": "Increased absorption of fat-soluble vitamins"}, {"id": "c", "text": "Overproduction of bile by the gallbladder"}, {"id": "d", "text": "Lowered bilirubin and lighter-colored urine"}]'::jsonb, '["a"]', 'Untreated cholecystitis can cause gangrene, perforation, and peritonitis. Bile obstruction decreases, not increases, fat-soluble vitamin absorption.'),
  ('cholecystitis', 14, 'A client with acute cholecystitis suddenly develops a rigid abdomen, severe abdominal pain, and fever. The nurse suspects which complication?', '[{"id": "a", "text": "Chronic cholecystitis"}, {"id": "b", "text": "Post-cholecystectomy syndrome"}, {"id": "c", "text": "Peritonitis"}, {"id": "d", "text": "Fat-soluble vitamin deficiency"}]'::jsonb, '["c"]', 'A rigid abdomen, severe pain, and fever are signs of peritonitis. Post-cholecystectomy syndrome is persistent pain after surgery, not acute rigidity with fever.'),
  ('cholecystitis', 15, 'A client being treated for cholecystitis develops a rigid abdomen with severe pain and a fever. Which action by the nurse is the priority?', '[{"id": "a", "text": "Encourage the client to ambulate to relieve gas"}, {"id": "b", "text": "Notify the provider immediately of the findings"}, {"id": "c", "text": "Offer clear liquids and recheck in four hours"}, {"id": "d", "text": "Document the findings as expected after NPO status"}]'::jsonb, '["b"]', 'These findings suggest peritonitis, which is a surgical emergency requiring immediate provider notification. Ambulation addresses gas pain, not peritonitis.'),
  ('cholecystitis', 16, 'A client with gallstones develops severe epigastric pain. Which laboratory results support the nurse''s suspicion that pancreatitis has developed?', '[{"id": "a", "text": "Decreased amylase and decreased lipase"}, {"id": "b", "text": "Decreased bilirubin and decreased WBC"}, {"id": "c", "text": "Normal amylase and decreased INR"}, {"id": "d", "text": "Increased amylase and increased lipase"}]'::jsonb, '["d"]', 'Pancreatitis as a complication presents with severe epigastric pain and elevated amylase and lipase. Decreased enzyme levels do not support pancreatitis.'),
  ('cholecystitis', 17, 'A client with cholelithiasis asks how a gallstone could cause pancreatitis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"A stone can block the common duct and stop pancreatic drainage.\""}, {"id": "b", "text": "\"A stone can travel through the blood to the pancreas.\""}, {"id": "c", "text": "\"A stone can make the pancreas produce extra bile.\""}, {"id": "d", "text": "\"A stone can lower the amylase made by the pancreas.\""}]'::jsonb, '["a"]', 'A gallstone may obstruct the common bile duct or ampulla and block pancreatic drainage. Pancreatitis raises, rather than lowers, amylase.'),
  ('cholecystitis', 18, 'Three months after a cholecystectomy, a client reports persistent pain similar to the pain before surgery. The nurse recognizes that this finding may indicate which problem?', '[{"id": "a", "text": "Expected gas pain from the laparoscopic procedure"}, {"id": "b", "text": "Retained stones or an injury to the bile duct"}, {"id": "c", "text": "Normal healing of the T-tube insertion site"}, {"id": "d", "text": "Fat intolerance from too many clear liquids"}]'::jsonb, '["b"]', 'Persistent pain after surgery suggests post-cholecystectomy syndrome, which may indicate retained stones or bile duct injury. It should not be dismissed as expected gas pain or normal healing.'),
  ('cholecystitis', 19, 'The provider suspects gallstones in a client with right upper quadrant pain. Which diagnostic test does the nurse anticipate will be ordered first?', '[{"id": "a", "text": "CT scan of the abdomen"}, {"id": "b", "text": "HIDA scan"}, {"id": "c", "text": "Abdominal ultrasound"}, {"id": "d", "text": "Serum bilirubin level"}]'::jsonb, '["c"]', 'Ultrasound is the first-line test and can show gallstones or inflammation. CT is used when perforation is suspected.'),
  ('cholecystitis', 20, 'A client with acute cholecystitis has worsening pain, and the provider suspects gallbladder perforation. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "CT scan"}, {"id": "b", "text": "Repeat ultrasound"}, {"id": "c", "text": "HIDA scan"}, {"id": "d", "text": "Serum WBC count"}]'::jsonb, '["a"]', 'A CT scan is used if perforation is suspected. Ultrasound is the first-line test for gallstones and inflammation.'),
  ('cholecystitis', 21, 'A client scheduled for a HIDA scan asks what the test involves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"A scope is passed through your mouth to remove stones.\""}, {"id": "b", "text": "\"You drink contrast and then have a series of x-rays.\""}, {"id": "c", "text": "\"A blood sample is drawn to measure liver enzymes.\""}, {"id": "d", "text": "\"A tracer is given IV, and images track your bile flow.\""}]'::jsonb, '["d"]', 'In a HIDA scan, a radioactive tracer is injected IV and imaging tracks bile flow from the liver into the gallbladder and small intestine. Liver enzymes are measured by blood tests, not by HIDA.'),
  ('cholecystitis', 22, 'A client with suspected acute cholecystitis has a HIDA scan. Which result supports the diagnosis?', '[{"id": "a", "text": "Normal bile flow into the small intestine"}, {"id": "b", "text": "A nonvisualized gallbladder"}, {"id": "c", "text": "A perforated bowel wall"}, {"id": "d", "text": "Decreased serum lipase"}]'::jsonb, '["b"]', 'In acute cholecystitis, HIDA helps show a blocked cystic duct or a nonvisualized gallbladder. Normal bile flow into the intestine would not support the diagnosis.'),
  ('cholecystitis', 23, 'A client with cholecystitis has an elevated white blood cell count. The nurse interprets this finding as indicating which problem?', '[{"id": "a", "text": "Blocked bile flow"}, {"id": "b", "text": "Vitamin K deficiency"}, {"id": "c", "text": "Infection"}, {"id": "d", "text": "Dehydration"}]'::jsonb, '["c"]', 'An elevated WBC count is a sign of infection. Blocked bile flow is reflected by elevated bilirubin.'),
  ('cholecystitis', 24, 'A client with gallstones has elevated ALP, AST, and ALT levels. The nurse interprets these results as indicating which problem?', '[{"id": "a", "text": "Liver or bile duct involvement"}, {"id": "b", "text": "Infection limited to the skin"}, {"id": "c", "text": "Rapid recovery after surgery"}, {"id": "d", "text": "Absorption of fat-soluble vitamins"}]'::jsonb, '["a"]', 'Elevated ALP, AST, and ALT indicate liver or bile duct involvement. Infection is indicated by an elevated WBC count.'),
  ('cholecystitis', 25, 'A client with cholelithiasis has yellow skin and an elevated serum bilirubin. The nurse interprets the bilirubin result as indicating which problem?', '[{"id": "a", "text": "Excess fat in the diet"}, {"id": "b", "text": "Expected post-op healing"}, {"id": "c", "text": "Low white blood cell count"}, {"id": "d", "text": "Blocked bile flow"}]'::jsonb, '["d"]', 'An elevated bilirubin indicates blocked bile flow, which also explains the jaundice. It is not an expected post-op finding.'),
  ('cholecystitis', 26, 'A client with mild acute cholecystitis asks why eating and drinking are not allowed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It keeps your stomach from making acid.\""}, {"id": "b", "text": "\"It gives your gallbladder a chance to rest.\""}, {"id": "c", "text": "\"It helps your liver produce more bile.\""}, {"id": "d", "text": "\"It lowers your risk of vitamin overdose.\""}]'::jsonb, '["b"]', 'NPO status is used to rest the gallbladder. It is not intended to increase bile production.'),
  ('cholecystitis', 27, 'The nurse reviews prescriptions for a client with mild acute cholecystitis being managed without surgery. Which prescription should the nurse question?', '[{"id": "a", "text": "IV fluids at a continuous rate"}, {"id": "b", "text": "IV antibiotics every 8 hours"}, {"id": "c", "text": "Regular diet high in fat as tolerated"}, {"id": "d", "text": "NSAID for pain as needed"}]'::jsonb, '["c"]', 'Nonsurgical treatment includes NPO status to rest the gallbladder, so a high-fat diet should be questioned. IV fluids, IV antibiotics, and NSAIDs such as ketorolac are expected.'),
  ('cholecystitis', 28, 'A client with acute cholecystitis is being managed nonsurgically. Which finding indicates that a nasogastric tube may be needed?', '[{"id": "a", "text": "Persistent vomiting with abdominal distention"}, {"id": "b", "text": "Mild pain controlled with an NSAID"}, {"id": "c", "text": "Itchy skin and a low-grade fever"}, {"id": "d", "text": "Dark urine with a normal abdomen"}]'::jsonb, '["a"]', 'An NG tube may be used for persistent vomiting, ileus, or abdominal distention. Mild pain controlled with an NSAID does not call for an NG tube.'),
  ('cholecystitis', 29, 'A client with acute cholecystitis reports moderate right upper quadrant pain. Which medication does the nurse anticipate is commonly used for this pain?', '[{"id": "a", "text": "Vitamin K injection"}, {"id": "b", "text": "IV antibiotic"}, {"id": "c", "text": "Fat-soluble vitamin tablet"}, {"id": "d", "text": "Ketorolac"}]'::jsonb, '["d"]', 'NSAIDs such as ketorolac are commonly used for cholecystitis pain. IV antibiotics treat infection rather than pain.'),
  ('cholecystitis', 30, 'A client with acute cholecystitis continues to have severe pain despite an NSAID. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Offer a low-fat meal to settle the stomach"}, {"id": "b", "text": "Clamp the NG tube to reduce discomfort"}, {"id": "c", "text": "Give an opioid as ordered for severe pain"}, {"id": "d", "text": "Encourage the client to lie still and wait"}]'::jsonb, '["c"]', 'Opioids may be used for severe pain as ordered. Offering a meal conflicts with NPO status for resting the gallbladder.'),
  ('cholecystitis', 31, 'The nurse teaches a client scheduled for a cholecystectomy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The laparoscopic method is minimally invasive.\""}, {"id": "b", "text": "\"An open procedure is preferred for most clients.\""}, {"id": "c", "text": "\"Recovery is usually quicker with laparoscopy.\""}, {"id": "d", "text": "\"An open surgery may be needed if infection is severe.\""}]'::jsonb, '["b"]', 'Laparoscopic cholecystectomy is the preferred approach because it is minimally invasive with quicker recovery. Open surgery is reserved for severe infection or complications.'),
  ('cholecystitis', 32, 'The nurse is caring for several clients needing a cholecystectomy. Which client is most likely to require an open rather than laparoscopic procedure?', '[{"id": "a", "text": "A client with mild symptoms and no complications"}, {"id": "b", "text": "A client with gallstones found on a routine ultrasound"}, {"id": "c", "text": "A client with a severe infection and complications"}, {"id": "d", "text": "A client who wants the quickest possible recovery"}]'::jsonb, '["c"]', 'Open cholecystectomy is used for severe infection or complications. Laparoscopic surgery is preferred for quicker recovery in uncomplicated cases.'),
  ('cholecystitis', 33, 'A client returns from surgery with a T-tube in place. The family asks why the tube was inserted. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It drains bile after the bile ducts were explored.\""}, {"id": "b", "text": "\"It delivers nutrition directly into the stomach.\""}, {"id": "c", "text": "\"It removes gas pain caused by the laparoscopy.\""}, {"id": "d", "text": "\"It gives IV antibiotics into the gallbladder.\""}]'::jsonb, '["a"]', 'A T-tube may be placed after bile duct exploration to drain bile. Gas pain after laparoscopy is managed with early ambulation, not a tube.'),
  ('cholecystitis', 34, 'A client is scheduled for a cholecystectomy this morning. Which action by the unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "Recording the client''s morning vital signs"}, {"id": "b", "text": "Reporting that the client''s urine looks dark"}, {"id": "c", "text": "Helping the client to the bathroom"}, {"id": "d", "text": "Bringing the client a breakfast tray"}]'::jsonb, '["d"]', 'The client must be kept NPO before surgery, so serving breakfast requires correction. Reporting dark urine is appropriate because it can signal bile duct obstruction.'),
  ('cholecystitis', 35, 'A client who had a laparoscopic cholecystectomy several hours ago reports gas pain. Which nursing action is most appropriate?', '[{"id": "a", "text": "Keep the client on strict bed rest"}, {"id": "b", "text": "Encourage the client to walk in the hall"}, {"id": "c", "text": "Offer a high-fat snack to promote digestion"}, {"id": "d", "text": "Clamp the drain to reduce abdominal pressure"}]'::jsonb, '["b"]', 'Early ambulation helps prevent gas pain after laparoscopic surgery. Bed rest would not provide this benefit.'),
  ('cholecystitis', 36, 'The nurse is caring for a client on the second day after a cholecystectomy. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Fever and redness at the incision site"}, {"id": "b", "text": "Tolerating clear liquids without nausea"}, {"id": "c", "text": "Ambulating in the hallway with assistance"}, {"id": "d", "text": "Green-brown drainage in the T-tube bag"}]'::jsonb, '["a"]', 'Fever and redness at the incision site are signs of infection that require reporting. Green-brown T-tube drainage is expected bile.'),
  ('cholecystitis', 37, 'A client is ready to begin oral intake after a cholecystectomy. Which item should the nurse offer first?', '[{"id": "a", "text": "A cheeseburger with fries"}, {"id": "b", "text": "A bowl of creamy soup"}, {"id": "c", "text": "Clear broth and gelatin"}, {"id": "d", "text": "Buttered toast and eggs"}]'::jsonb, '["c"]', 'Diet is advanced slowly after surgery, starting with clear liquids and avoiding fatty foods. Creamy soup and fried foods are higher in fat and not clear liquids.'),
  ('cholecystitis', 38, 'The nurse provides diet teaching to a client after a cholecystectomy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will start with clear liquids first.\""}, {"id": "b", "text": "\"I will add foods back gradually.\""}, {"id": "c", "text": "\"I will avoid greasy foods for now.\""}, {"id": "d", "text": "\"I can have fried chicken for my first meal.\""}]'::jsonb, '["d"]', 'After surgery, the diet is advanced slowly starting with clear liquids and avoiding fatty foods. Fried chicken as a first meal contradicts this plan.'),
  ('cholecystitis', 39, 'The nurse is planning the diet progression for a client after a cholecystectomy. Which sequence is correct?', '[{"id": "a", "text": "Regular diet first, then clear liquids if nausea develops"}, {"id": "b", "text": "Clear liquids first, then slow advancement with low fat"}, {"id": "c", "text": "High-fat liquids first, then solid foods as tolerated"}, {"id": "d", "text": "Solid foods first, then clear liquids at bedtime"}]'::jsonb, '["b"]', 'The diet starts with clear liquids and is advanced slowly while avoiding fatty foods. Starting with a regular or high-fat diet reverses the correct order.'),
  ('cholecystitis', 40, 'The nurse is caring for a client with a T-tube after a cholecystectomy. Which action by the nurse is correct?', '[{"id": "a", "text": "Hang the drainage bag above the incision"}, {"id": "b", "text": "Keep the drainage bag below the surgical site"}, {"id": "c", "text": "Clamp the tube during each position change"}, {"id": "d", "text": "Empty the bag only when the client is discharged"}]'::jsonb, '["b"]', 'The T-tube should be kept below the surgical site. Clamping the tube without a physician order is unsafe.'),
  ('cholecystitis', 41, 'The nurse assesses the drainage from a client''s T-tube on the first post-operative day. Which drainage should the nurse document as expected?', '[{"id": "a", "text": "Green-brown bile"}, {"id": "b", "text": "Cloudy yellow fluid"}, {"id": "c", "text": "Bright red blood"}, {"id": "d", "text": "Foul-smelling fluid"}]'::jsonb, '["a"]', 'Expected T-tube output is green-brown or yellow-brown bile. Cloudy, bloody, or foul-smelling drainage is abnormal.'),
  ('cholecystitis', 42, 'A client has a T-tube after bile duct exploration. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Yellow-brown drainage in the bag"}, {"id": "b", "text": "Bag positioned below the surgical site"}, {"id": "c", "text": "Cloudy, foul-smelling drainage"}, {"id": "d", "text": "Green-brown drainage after ambulation"}]'::jsonb, '["c"]', 'Cloudy, bloody, or foul-smelling T-tube drainage is abnormal and should be reported. Green-brown or yellow-brown bile is expected.'),
  ('cholecystitis', 43, 'The charge nurse observes a new nurse caring for a client with a T-tube. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Measuring and recording the bile output"}, {"id": "b", "text": "Checking the color of the drainage"}, {"id": "c", "text": "Keeping the bag lower than the incision"}, {"id": "d", "text": "Clamping the tube to see if the client tolerates it"}]'::jsonb, '["d"]', 'A T-tube must never be clamped without a physician order. Monitoring output and keeping the tube below the surgical site are correct.'),
  ('cholecystitis', 44, 'A client has had a bile duct obstruction for a prolonged period. Which laboratory value is most important for the nurse to monitor?', '[{"id": "a", "text": "Serum amylase"}, {"id": "b", "text": "PT/INR"}, {"id": "c", "text": "Serum calcium"}, {"id": "d", "text": "Blood glucose"}]'::jsonb, '["b"]', 'Prolonged bile obstruction can cause vitamin K deficiency, leading to clotting problems with increased INR/PT. Amylase is used to detect pancreatitis, not clotting problems.'),
  ('cholecystitis', 45, 'A client with long-standing cholestasis is prescribed vitamin supplements. The nurse anticipates supplementation of which vitamins?', '[{"id": "a", "text": "Vitamins B1, B6, and B12"}, {"id": "b", "text": "Vitamin C and folic acid"}, {"id": "c", "text": "Vitamins A, D, E, and K"}, {"id": "d", "text": "Vitamin B12 and vitamin C"}]'::jsonb, '["c"]', 'Bile is required to absorb the fat-soluble vitamins A, D, E, and K, so prolonged obstruction can cause their malabsorption. The other options are not fat-soluble vitamins named for supplementation.'),
  ('cholecystitis', 46, 'While palpating under a client''s right ribcage, the nurse asks the client to inhale deeply, and the client stops inhaling because of sudden pain. How should the nurse document this finding?', '[{"id": "a", "text": "Positive Murphy''s sign"}, {"id": "b", "text": "Post-cholecystectomy syndrome"}, {"id": "c", "text": "Fat intolerance"}, {"id": "d", "text": "Pruritus"}]'::jsonb, '["a"]', 'Murphy''s sign is pain on deep breath with right upper quadrant palpation. Post-cholecystectomy syndrome is persistent pain after surgery.'),
  ('cholecystitis', 47, 'A client with acute cholecystitis has a fever, chills, and an elevated WBC count. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "Clamping of the NG tube"}, {"id": "b", "text": "Vitamin K supplementation"}, {"id": "c", "text": "A regular low-fat diet"}, {"id": "d", "text": "IV antibiotics"}]'::jsonb, '["d"]', 'Fever, chills, and elevated WBC indicate infection, which is treated with IV antibiotics. A diet would conflict with NPO status used to rest the gallbladder.'),
  ('cholecystitis', 48, 'A client found to have gallstones on a routine scan asks why there have been no symptoms. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Gallstones cause symptoms only after the gallbladder is removed.\""}, {"id": "b", "text": "\"Symptoms usually occur when a stone blocks a bile duct.\""}, {"id": "c", "text": "\"Gallstones cause symptoms only in people who are fasting.\""}, {"id": "d", "text": "\"Symptoms usually occur when stones reach the bloodstream.\""}]'::jsonb, '["b"]', 'Gallstones cause symptoms when they obstruct the cystic duct or bile ducts. Fasting is a cause of acalculous cholecystitis, not a requirement for symptoms.'),
  ('cholecystitis', 49, 'A client with cholelithiasis develops new pain. Which finding best suggests pancreatitis rather than uncomplicated cholecystitis?', '[{"id": "a", "text": "Right upper quadrant pain after a fatty meal"}, {"id": "b", "text": "Pain on deep breath during right ribcage palpation"}, {"id": "c", "text": "Pain radiating to the right shoulder"}, {"id": "d", "text": "Severe epigastric pain with an elevated lipase"}]'::jsonb, '["d"]', 'Pancreatitis as a complication presents with severe epigastric pain and elevated amylase and lipase. Right upper quadrant pain, Murphy''s sign, and right shoulder radiation are classic cholecystitis findings.'),
  ('cholecystitis', 50, 'The nurse receives report on four clients on a surgical unit. Which client should the nurse assess first?', '[{"id": "a", "text": "A client after laparoscopic surgery reporting gas pain"}, {"id": "b", "text": "A client with chronic cholecystitis reporting bloating"}, {"id": "c", "text": "A client with a T-tube draining yellow-brown bile"}, {"id": "d", "text": "A client with cholecystitis who has a rigid abdomen and fever"}]'::jsonb, '["d"]', 'A rigid abdomen with fever suggests peritonitis, a surgical emergency. Yellow-brown T-tube bile is expected, and gas pain and bloating are not emergencies.'),
  ('pancreatitis', 1, 'A client is admitted with acute pancreatitis. Which assessment finding does the nurse expect?', '[{"id": "a", "text": "Severe epigastric pain radiating to the back"}, {"id": "b", "text": "Right lower quadrant pain radiating to the groin"}, {"id": "c", "text": "Dull left lower quadrant pain relieved by eating"}, {"id": "d", "text": "Mild periumbilical pain that worsens with walking"}]'::jsonb, '["a"]', 'Acute pancreatitis classically causes severe epigastric pain radiating to the back. The other locations are not the described pattern.'),
  ('pancreatitis', 2, 'A client with acute pancreatitis is restless and reports severe abdominal pain. Which position should the nurse assist the client into to promote comfort?', '[{"id": "a", "text": "Supine with the legs flat"}, {"id": "b", "text": "Prone with a pillow under the hips"}, {"id": "c", "text": "Sitting up and leaning forward"}, {"id": "d", "text": "Trendelenburg with the head lowered"}]'::jsonb, '["c"]', 'Pancreatitis pain is worse lying flat and better when sitting up or leaning forward. Supine positioning would worsen the pain.'),
  ('pancreatitis', 3, 'The nurse observes unlicensed assistive personnel (UAP) caring for a client with acute pancreatitis. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raising the head of the bed for the client"}, {"id": "b", "text": "Lowering the client flat to sleep for comfort"}, {"id": "c", "text": "Reporting that the client''s urine output is low"}, {"id": "d", "text": "Reporting a bluish color around the client''s navel"}]'::jsonb, '["b"]', 'Pancreatitis pain is worse when lying flat, so placing the client flat for comfort requires correction. Reporting low urine output or periumbilical bruising is appropriate.'),
  ('pancreatitis', 4, 'The nurse teaches comfort measures to a client with acute pancreatitis. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will lie flat on my back when the pain starts.\""}, {"id": "b", "text": "\"I will lie on my stomach to press on the pain.\""}, {"id": "c", "text": "\"I will keep my legs straight and my head flat.\""}, {"id": "d", "text": "\"I will sit up and lean forward when the pain flares.\""}]'::jsonb, '["d"]', 'Sitting up and leaning forward relieves pancreatitis pain. Lying flat makes the pain worse.'),
  ('pancreatitis', 5, 'While assessing a client with acute pancreatitis, the nurse notes bluish discoloration around the umbilicus. The nurse recognizes this finding as which sign?', '[{"id": "a", "text": "Cullen''s sign, indicating internal bleeding"}, {"id": "b", "text": "Grey Turner''s sign, indicating steatorrhea"}, {"id": "c", "text": "Cullen''s sign, indicating hyperglycemia"}, {"id": "d", "text": "Grey Turner''s sign, indicating atelectasis"}]'::jsonb, '["a"]', 'Cullen''s sign is a bluish belly button that indicates internal bleeding. Grey Turner''s sign involves bluish flanks.'),
  ('pancreatitis', 6, 'A client with acute pancreatitis develops bluish discoloration of both flanks. The nurse interprets this finding as indicating which problem?', '[{"id": "a", "text": "Fatty stool from poor fat digestion"}, {"id": "b", "text": "Retroperitoneal bleeding"}, {"id": "c", "text": "Collapsed lung segments"}, {"id": "d", "text": "Islet cell damage"}]'::jsonb, '["b"]', 'Grey Turner''s sign, bluish flanks, indicates retroperitoneal bleeding. Collapsed lung segments describe atelectasis, which is not a skin finding.'),
  ('pancreatitis', 7, 'A client with acute pancreatitis has both periumbilical and flank bruising. Which action should the nurse take first?', '[{"id": "a", "text": "Reposition the client to lean forward"}, {"id": "b", "text": "Document the findings as expected"}, {"id": "c", "text": "Recheck the abdomen at the next shift"}, {"id": "d", "text": "Notify the provider immediately"}]'::jsonb, '["d"]', 'Cullen''s and Grey Turner''s signs together indicate internal and retroperitoneal bleeding, which is an emergency. Repositioning for comfort does not address bleeding.'),
  ('pancreatitis', 8, 'The nurse reviews laboratory results for a client with suspected pancreatitis. Which result is most specific for diagnosing pancreatitis?', '[{"id": "a", "text": "Elevated amylase"}, {"id": "b", "text": "Decreased calcium"}, {"id": "c", "text": "Elevated lipase"}, {"id": "d", "text": "Elevated blood sugar"}]'::jsonb, '["c"]', 'Lipase is more specific than amylase for diagnosing pancreatitis. Amylase is also elevated but is less specific.'),
  ('pancreatitis', 9, 'A nursing student is discussing laboratory tests for pancreatitis. Which statement by the student requires correction by the nurse?', '[{"id": "a", "text": "\"Calcium levels may fall in pancreatitis.\""}, {"id": "b", "text": "\"Amylase is more specific than lipase.\""}, {"id": "c", "text": "\"Blood sugar may rise in pancreatitis.\""}, {"id": "d", "text": "\"Both amylase and lipase are elevated.\""}]'::jsonb, '["b"]', 'Lipase, not amylase, is the more specific test for pancreatitis. Decreased calcium, increased blood sugar, and elevated amylase and lipase are expected.'),
  ('pancreatitis', 10, 'The nurse is reviewing the serum electrolytes of a client with acute pancreatitis. Which result does the nurse expect?', '[{"id": "a", "text": "Decreased calcium"}, {"id": "b", "text": "Elevated calcium"}, {"id": "c", "text": "Decreased lipase"}, {"id": "d", "text": "Decreased glucose"}]'::jsonb, '["a"]', 'Pancreatitis labs include decreased calcium along with elevated amylase, lipase, and blood sugar. Decreased lipase or glucose is not expected.'),
  ('pancreatitis', 11, 'A client with acute pancreatitis has a capillary blood glucose that is well above the client''s usual level. Which nursing action is most appropriate?', '[{"id": "a", "text": "Offer a carbohydrate snack"}, {"id": "b", "text": "Withhold all IV fluids"}, {"id": "c", "text": "Place the client flat in bed"}, {"id": "d", "text": "Give insulin as prescribed"}]'::jsonb, '["d"]', 'Nursing care includes monitoring for hyperglycemia and giving insulin if needed. A snack would conflict with NPO status used to rest the pancreas.'),
  ('pancreatitis', 12, 'The nurse is planning care for a client with acute pancreatitis. Which blood sugar complication should the nurse monitor for?', '[{"id": "a", "text": "Hypoglycemia from excess glucagon"}, {"id": "b", "text": "Hyperglycemia"}, {"id": "c", "text": "Hypoglycemia from low amylase"}, {"id": "d", "text": "Hypoglycemia from high insulin"}]'::jsonb, '["b"]', 'Nurses monitor for hyperglycemia in pancreatitis, and blood sugar is typically elevated. Glucagon raises blood sugar, so excess glucagon would not cause hypoglycemia.'),
  ('pancreatitis', 13, 'A client with long-standing chronic pancreatitis is newly diagnosed with diabetes mellitus. The client asks why this happened. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Your diet was too high in protein.\""}, {"id": "b", "text": "\"Your gallbladder stopped storing bile.\""}, {"id": "c", "text": "\"Damage to the islet cells in your pancreas.\""}, {"id": "d", "text": "\"The enzyme replacement raised your sugar.\""}]'::jsonb, '["c"]', 'Diabetes mellitus in chronic pancreatitis results from islet cell damage. A high-protein diet is part of the recommended diet when eating resumes.'),
  ('pancreatitis', 14, 'The nurse is planning long-term care for a client with chronic pancreatitis. Which major risks should the nurse address?', '[{"id": "a", "text": "Malnutrition and insulin dependence"}, {"id": "b", "text": "Shock and atelectasis"}, {"id": "c", "text": "ARDS and hypovolemic shock"}, {"id": "d", "text": "Sudden fever and hypotension"}]'::jsonb, '["a"]', 'Major risks of chronic pancreatitis are malnutrition and insulin dependence. Shock, ARDS, and atelectasis are major risks of acute pancreatitis.'),
  ('pancreatitis', 15, 'A client newly diagnosed with acute pancreatitis asks what is happening inside the body. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your pancreas has stopped making any enzymes.\""}, {"id": "b", "text": "\"Enzymes activate too early and digest the pancreas.\""}, {"id": "c", "text": "\"Bile is backing up into your stomach.\""}, {"id": "d", "text": "\"Your pancreas is producing too much insulin.\""}]'::jsonb, '["b"]', 'In pancreatitis, enzymes activate too early, so the pancreas digests itself. This autodigestion causes tissue damage, necrosis, and swelling.'),
  ('pancreatitis', 16, 'A nurse is explaining normal pancreatic function to a nursing student. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Pancreatic enzymes become active inside the pancreas.\""}, {"id": "b", "text": "\"Pancreatic enzymes are never activated in healthy people.\""}, {"id": "c", "text": "\"Pancreatic enzymes digest the pancreas to renew its cells.\""}, {"id": "d", "text": "\"Pancreatic enzymes normally activate after leaving the pancreas.\""}]'::jsonb, '["d"]', 'Normally, pancreatic enzymes activate after leaving the pancreas. Activation inside the pancreas is what occurs in pancreatitis.'),
  ('pancreatitis', 17, 'A client with chronic pancreatitis has greasy stools. The client asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Too much bicarbonate is reaching your bowel.\""}, {"id": "b", "text": "\"Your pancreas is releasing too much insulin.\""}, {"id": "c", "text": "\"Fat is not being digested well, so it stays in stool.\""}, {"id": "d", "text": "\"Protein is not being broken down by amylase.\""}]'::jsonb, '["c"]', 'Steatorrhea is fatty, greasy stool from poor fat digestion; lipase is the enzyme that breaks down fats. Amylase breaks down carbohydrates, not protein.'),
  ('pancreatitis', 18, 'The nurse is reviewing the digestive functions of the pancreas with a client who has pancreatitis. Which enzyme-function pairing is correct?', '[{"id": "a", "text": "Protease breaks down proteins"}, {"id": "b", "text": "Amylase breaks down fats"}, {"id": "c", "text": "Lipase breaks down proteins"}, {"id": "d", "text": "Bicarbonate breaks down sugars"}]'::jsonb, '["a"]', 'Protease breaks down proteins. Amylase breaks down carbohydrates and lipase breaks down fats.'),
  ('pancreatitis', 19, 'A client asks which pancreatic secretion protects the intestine from stomach acid. Which response by the nurse is accurate?', '[{"id": "a", "text": "Amylase"}, {"id": "b", "text": "Bicarbonate"}, {"id": "c", "text": "Glucagon"}, {"id": "d", "text": "Lipase"}]'::jsonb, '["b"]', 'Bicarbonate from the pancreas neutralizes stomach acid. Glucagon is a hormone that raises blood sugar.'),
  ('pancreatitis', 20, 'A client with pancreatitis asks how the pancreas controls blood sugar. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Insulin raises blood sugar; glucagon lowers it.\""}, {"id": "b", "text": "\"Lipase lowers blood sugar; amylase raises it.\""}, {"id": "c", "text": "\"Insulin and glucagon both lower blood sugar.\""}, {"id": "d", "text": "\"Insulin lowers blood sugar; glucagon raises it.\""}]'::jsonb, '["d"]', 'Insulin lowers blood sugar and glucagon raises blood sugar. Lipase and amylase are digestive enzymes, not glucose-regulating hormones.'),
  ('pancreatitis', 21, 'A client asks where the pancreas is located. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is under the liver on the right side.\""}, {"id": "b", "text": "\"It is in the lower left part of the abdomen.\""}, {"id": "c", "text": "\"It is behind the stomach near the duodenum.\""}, {"id": "d", "text": "\"It is in front of the stomach near the colon.\""}]'::jsonb, '["c"]', 'The pancreas is located behind the stomach, near the duodenum. It is not described as lying in front of the stomach.'),
  ('pancreatitis', 22, 'The nurse is reviewing the history of a client admitted with acute pancreatitis. Which finding is the most common cause of this condition?', '[{"id": "a", "text": "Gallstones"}, {"id": "b", "text": "Cystic fibrosis"}, {"id": "c", "text": "Recent trauma"}, {"id": "d", "text": "Diuretic use"}]'::jsonb, '["a"]', 'Gallstones that block the ducts are the number one cause of acute pancreatitis. Cystic fibrosis is listed as a cause of chronic pancreatitis.'),
  ('pancreatitis', 23, 'A client has been diagnosed with chronic pancreatitis. Which history is the most common cause of this condition?', '[{"id": "a", "text": "A single episode of gallstones"}, {"id": "b", "text": "Long-term alcohol abuse"}, {"id": "c", "text": "Recent ERCP procedure"}, {"id": "d", "text": "Short-term steroid use"}]'::jsonb, '["b"]', 'Long-term alcohol abuse is the number one cause of chronic pancreatitis. ERCP complications are listed as a cause of acute pancreatitis.'),
  ('pancreatitis', 24, 'The nurse is reviewing a group of clients'' histories. Which client is at risk for chronic pancreatitis because of thick mucus blocking the pancreatic ducts?', '[{"id": "a", "text": "A client with recent abdominal trauma"}, {"id": "b", "text": "A client taking a daily diuretic"}, {"id": "c", "text": "A client recovering from an ERCP"}, {"id": "d", "text": "A client with cystic fibrosis"}]'::jsonb, '["d"]', 'Cystic fibrosis causes thick mucus that blocks the ducts and is a cause of chronic pancreatitis. Trauma, diuretics, and ERCP complications are listed as causes of acute pancreatitis.'),
  ('pancreatitis', 25, 'The nurse reviews the medication lists of several clients. Which medication history places a client at risk for acute pancreatitis?', '[{"id": "a", "text": "Pancreatic enzyme capsules"}, {"id": "b", "text": "Proton pump inhibitor"}, {"id": "c", "text": "Corticosteroid therapy"}, {"id": "d", "text": "Insulin as needed"}]'::jsonb, '["c"]', 'Medications such as steroids and diuretics are causes of acute pancreatitis. Pancreatic enzymes, PPIs, and insulin are used in pancreatitis treatment.'),
  ('pancreatitis', 26, 'Several hours after an ERCP, a client reports severe epigastric pain radiating to the back. The nurse suspects which complication?', '[{"id": "a", "text": "Acute pancreatitis"}, {"id": "b", "text": "Chronic pancreatitis"}, {"id": "c", "text": "Atelectasis"}, {"id": "d", "text": "Steatorrhea"}]'::jsonb, '["a"]', 'ERCP complications are a cause of acute pancreatitis, which presents with severe epigastric pain radiating to the back. Chronic pancreatitis is long-term, progressive, and causes dull pain.'),
  ('pancreatitis', 27, 'A family member asks how acute pancreatitis differs from chronic pancreatitis. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Acute is long-term and chronic is sudden.\""}, {"id": "b", "text": "\"Acute is often reversible; chronic is not.\""}, {"id": "c", "text": "\"Both forms always heal without damage.\""}, {"id": "d", "text": "\"Chronic is reversible; acute is not.\""}]'::jsonb, '["b"]', 'Acute pancreatitis is sudden and often reversible, while chronic pancreatitis causes long-term, irreversible damage. The other statements reverse or misstate this.'),
  ('pancreatitis', 28, 'The nurse is assessing a client with chronic pancreatitis. Which group of findings does the nurse expect?', '[{"id": "a", "text": "Sudden sharp pain, fever, and vomiting"}, {"id": "b", "text": "Bluish flanks, hypotension, and fever"}, {"id": "c", "text": "Pain relieved by lying flat and weight gain"}, {"id": "d", "text": "Dull pain, weight loss, and fatty stools"}]'::jsonb, '["d"]', 'Chronic pancreatitis causes chronic dull pain, weight loss, malabsorption, and steatorrhea. Sudden sharp pain with fever and vomiting describes acute pancreatitis.'),
  ('pancreatitis', 29, 'A client with chronic pancreatitis describes bowel movements. Which description is consistent with steatorrhea?', '[{"id": "a", "text": "Hard, dry, and small stools"}, {"id": "b", "text": "Black, tarry, and sticky stools"}, {"id": "c", "text": "Fatty, smelly, and floating stools"}, {"id": "d", "text": "Watery, clear, and odorless stools"}]'::jsonb, '["c"]', 'Steatorrhea is fatty, smelly, floating stool. Hard, dry stools do not reflect poor fat digestion.'),
  ('pancreatitis', 30, 'The nurse is assessing a client admitted with acute pancreatitis. Which set of vital sign findings does the nurse expect?', '[{"id": "a", "text": "Fever, tachycardia, and hypotension"}, {"id": "b", "text": "Low temperature, bradycardia, and hypertension"}, {"id": "c", "text": "Normal temperature, bradycardia, and hypotension"}, {"id": "d", "text": "Fever, bradycardia, and hypertension"}]'::jsonb, '["a"]', 'Acute pancreatitis presents with fever, tachycardia, and hypotension. Bradycardia and hypertension are the reverse of the expected findings.'),
  ('pancreatitis', 31, 'The nurse is monitoring a client with acute pancreatitis. Which set of findings indicates the client''s condition is worsening?', '[{"id": "a", "text": "Rising BP, slowing HR, and high urine output"}, {"id": "b", "text": "Falling BP, rising HR, and low urine output"}, {"id": "c", "text": "Normal HR and steadily increasing urine output"}, {"id": "d", "text": "Less pain when sitting up and leaning forward"}]'::jsonb, '["b"]', 'Worsening signs include decreased blood pressure, increased heart rate, decreased urine output, and ARDS. Relief when leaning forward is an expected comfort response.'),
  ('pancreatitis', 32, 'A client with severe acute pancreatitis becomes hypotensive. The family asks why the blood pressure is dropping. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Fluid is moving from tissues into the blood vessels.\""}, {"id": "b", "text": "\"The pancreas is making too much glucagon.\""}, {"id": "c", "text": "\"Fluid is shifting out of the blood vessels into tissues.\""}, {"id": "d", "text": "\"The lungs are absorbing extra fluid from the blood.\""}]'::jsonb, '["c"]', 'Hypovolemic shock in pancreatitis occurs as fluid shifts from the vascular space to the interstitial space, lowering blood pressure. The reverse direction would not lower blood pressure.'),
  ('pancreatitis', 33, 'A client with acute pancreatitis develops ARDS. The family asks what this means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Part of the lung has collapsed.\""}, {"id": "b", "text": "\"Fluid has shifted into the abdomen.\""}, {"id": "c", "text": "\"The pancreas is bleeding internally.\""}, {"id": "d", "text": "\"Fluid fills the air sacs, so oxygen drops.\""}]'::jsonb, '["d"]', 'ARDS is fluid in the alveoli that decreases oxygen. Collapsed lung segments describe atelectasis.'),
  ('pancreatitis', 34, 'A client with acute pancreatitis is diagnosed with atelectasis. The nurse explains this complication to the client as which problem?', '[{"id": "a", "text": "Collapsed segments of the lung"}, {"id": "b", "text": "Fluid filling the air sacs"}, {"id": "c", "text": "Bleeding behind the abdominal wall"}, {"id": "d", "text": "Fluid leaving the blood vessels"}]'::jsonb, '["a"]', 'Atelectasis refers to collapsed lung segments. Fluid in the alveoli describes ARDS.'),
  ('pancreatitis', 35, 'The nurse is planning care for a client with acute pancreatitis. Which complications are major risks for this client?', '[{"id": "a", "text": "Malnutrition and insulin dependence"}, {"id": "b", "text": "Shock and ARDS"}, {"id": "c", "text": "Steatorrhea and diabetes"}, {"id": "d", "text": "Weight loss and dull pain"}]'::jsonb, '["b"]', 'Major risks of acute pancreatitis are shock, ARDS, and atelectasis. Malnutrition and insulin dependence are major risks of chronic pancreatitis.'),
  ('pancreatitis', 36, 'A client with acute pancreatitis asks why food and fluids by mouth are not allowed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It helps your blood sugar stay low.\""}, {"id": "b", "text": "\"It makes the enzyme tests more accurate.\""}, {"id": "c", "text": "\"It allows your pancreas to rest.\""}, {"id": "d", "text": "\"It prevents bleeding into your flanks.\""}]'::jsonb, '["c"]', 'NPO status is used to rest the pancreas. It is not intended to change lab accuracy or prevent bleeding.'),
  ('pancreatitis', 37, 'A client admitted yesterday with acute pancreatitis is NPO. Which action by the unlicensed assistive personnel (UAP) requires correction?', '[{"id": "a", "text": "Helping the client sit up and lean forward"}, {"id": "b", "text": "Measuring and recording urine output"}, {"id": "c", "text": "Reporting that the client feels nauseated"}, {"id": "d", "text": "Bringing the client a lunch tray on request"}]'::jsonb, '["d"]', 'The client must stay NPO to rest the pancreas, so bringing a lunch tray requires correction. Helping the client lean forward supports comfort.'),
  ('pancreatitis', 38, 'A client is admitted with acute pancreatitis. Which group of interventions does the nurse anticipate as the priority?', '[{"id": "a", "text": "NPO status, IV fluids, and pain medication"}, {"id": "b", "text": "Regular diet, oral fluids, and ambulation"}, {"id": "c", "text": "Low-fat diet, enzymes, and an H2 blocker"}, {"id": "d", "text": "High-protein meals, insulin, and bed rest"}]'::jsonb, '["a"]', 'Priority care for pancreatitis is NPO, IV fluids, and pain medication. A low-fat, high-protein diet is resumed later.'),
  ('pancreatitis', 39, 'A client with severe pancreatitis is expected to remain NPO for an extended period. Which intervention does the nurse anticipate to support nutrition?', '[{"id": "a", "text": "Frequent high-fat oral snacks"}, {"id": "b", "text": "Total parenteral nutrition"}, {"id": "c", "text": "Pancreatic enzymes with water"}, {"id": "d", "text": "A clear liquid diet each day"}]'::jsonb, '["b"]', 'TPN is used if the client will be NPO long term. Oral intake would conflict with NPO status.'),
  ('pancreatitis', 40, 'A client recovering from acute pancreatitis is ready to resume eating. Which diet does the nurse anticipate?', '[{"id": "a", "text": "High-fat, low-protein diet"}, {"id": "b", "text": "Low-fat, low-protein diet"}, {"id": "c", "text": "Low-fat, high-protein diet"}, {"id": "d", "text": "High-fat, high-protein diet"}]'::jsonb, '["c"]', 'When eating resumes, the diet should be low in fat and high in protein. High-fat diets are not recommended.'),
  ('pancreatitis', 41, 'The nurse provides discharge teaching to a client recovering from pancreatitis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will choose lean protein foods.\""}, {"id": "b", "text": "\"I will keep my fat intake low.\""}, {"id": "c", "text": "\"I will not drink any alcohol.\""}, {"id": "d", "text": "\"I can have wine on special occasions.\""}]'::jsonb, '["d"]', 'Clients with pancreatitis should have no alcohol ever, so wine on special occasions indicates a need for further teaching. A low-fat, high-protein diet is correct.'),
  ('pancreatitis', 42, 'A client with chronic pancreatitis has lost weight. Which client statement about diet indicates a need for further teaching?', '[{"id": "a", "text": "\"I will eat high-fat foods to gain weight back.\""}, {"id": "b", "text": "\"I will include protein at every meal.\""}, {"id": "c", "text": "\"I will avoid all beer, wine, and liquor.\""}, {"id": "d", "text": "\"I will keep fatty foods to a minimum.\""}]'::jsonb, '["a"]', 'The diet after pancreatitis should be low in fat and high in protein, so a high-fat plan needs correction. Avoiding alcohol completely is correct.'),
  ('pancreatitis', 43, 'A client with acute pancreatitis is vomiting and has abdominal bloating. A nasogastric tube is inserted. The nurse explains that the tube serves which purpose?', '[{"id": "a", "text": "To give pancreatic enzymes"}, {"id": "b", "text": "To decompress and reduce pancreatic stimulation"}, {"id": "c", "text": "To deliver total parenteral nutrition"}, {"id": "d", "text": "To measure the blood sugar level"}]'::jsonb, '["b"]', 'An NG tube is used for decompression with vomiting or bloating and prevents further pancreatic stimulation. TPN is delivered intravenously, not through an NG tube.'),
  ('pancreatitis', 44, 'A client with chronic pancreatitis is prescribed a pancreatic enzyme (Creon). The client asks what the medication does. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It lowers your blood sugar.\""}, {"id": "b", "text": "\"It reduces your stomach acid.\""}, {"id": "c", "text": "\"It replaces pancreatic enzymes.\""}, {"id": "d", "text": "\"It treats a suspected infection.\""}]'::jsonb, '["c"]', 'Pancreatic enzymes such as Creon are used for enzyme replacement in chronic pancreatitis. PPIs and H2 blockers are used to reduce stomach acid.'),
  ('pancreatitis', 45, 'A client with pancreatitis is prescribed a proton pump inhibitor. The client asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It replaces your digestive enzymes.\""}, {"id": "b", "text": "\"It raises your blood sugar level.\""}, {"id": "c", "text": "\"It treats an infection in your pancreas.\""}, {"id": "d", "text": "\"It reduces the acid in your stomach.\""}]'::jsonb, '["d"]', 'PPIs and H2 blockers are given to reduce stomach acid. Enzyme replacement is the role of pancreatic enzymes such as Creon.'),
  ('pancreatitis', 46, 'The nurse reviews medications for clients with pancreatitis. Which medication is matched with its correct indication?', '[{"id": "a", "text": "Antibiotics when infection is suspected"}, {"id": "b", "text": "Creon for acute hyperglycemia"}, {"id": "c", "text": "H2 blocker to replace lipase"}, {"id": "d", "text": "Insulin to neutralize stomach acid"}]'::jsonb, '["a"]', 'Antibiotics are given if infection is suspected. Creon is enzyme replacement for chronic pancreatitis, and H2 blockers reduce stomach acid.'),
  ('pancreatitis', 47, 'A client admitted with acute pancreatitis has no history of gallstones. The nurse reviews the history for the second most common cause. Which finding does the nurse look for?', '[{"id": "a", "text": "Cystic fibrosis"}, {"id": "b", "text": "Alcohol abuse"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Steatorrhea"}]'::jsonb, '["b"]', 'Alcohol abuse is the number two cause of acute pancreatitis after gallstones. Cystic fibrosis is listed as a cause of chronic pancreatitis.'),
  ('pancreatitis', 48, 'A client with suspected pancreatitis is scheduled for an ERCP. The client asks what this test involves. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A blood test measures your lipase.\""}, {"id": "b", "text": "\"A cuff measures your blood pressure.\""}, {"id": "c", "text": "\"A scope is used to look at the ducts.\""}, {"id": "d", "text": "\"A stool sample is checked for fat.\""}]'::jsonb, '["c"]', 'ERCP is a scope for examining the ducts. Lipase is measured with a blood test, not ERCP.'),
  ('pancreatitis', 49, 'The nurse is caring for four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with chronic pancreatitis reporting dull pain"}, {"id": "b", "text": "A client with chronic pancreatitis reporting fatty stools"}, {"id": "c", "text": "A client with acute pancreatitis who prefers leaning forward"}, {"id": "d", "text": "A client with acute pancreatitis who has new bluish flanks"}]'::jsonb, '["d"]', 'Bluish flanks (Grey Turner''s sign) indicate retroperitoneal bleeding, an emergency. Dull pain and steatorrhea are expected in chronic pancreatitis, and leaning forward relieves pain.'),
  ('pancreatitis', 50, 'The nurse reviews laboratory results for a client with severe epigastric pain. Which combination is most consistent with acute pancreatitis?', '[{"id": "a", "text": "Decreased lipase and elevated calcium"}, {"id": "b", "text": "Decreased amylase and decreased glucose"}, {"id": "c", "text": "Normal lipase and elevated calcium"}, {"id": "d", "text": "Elevated lipase and decreased calcium"}]'::jsonb, '["d"]', 'Pancreatitis labs include elevated lipase and amylase with decreased calcium and elevated blood sugar. Elevated calcium and decreased lipase are the reverse of the expected findings.'),
  ('alcoholism', 1, 'A client with a long history of alcohol use is admitted with confusion, an unsteady gait, and nystagmus. The nurse suspects which condition?', '[{"id": "a", "text": "Wernicke''s encephalopathy"}, {"id": "b", "text": "Korsakoff syndrome"}, {"id": "c", "text": "Hypocalcemia"}, {"id": "d", "text": "Mild alcohol withdrawal"}]'::jsonb, '["a"]', 'Confusion, ataxia, and abnormal eye movements such as nystagmus form the classic triad of Wernicke''s encephalopathy. Korsakoff syndrome is the later stage with irreversible memory loss and confabulation.'),
  ('alcoholism', 2, 'The family of a client diagnosed with Wernicke''s encephalopathy asks what caused it. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A deficiency of vitamin B12\""}, {"id": "b", "text": "\"A deficiency of vitamin B1 (thiamine)\""}, {"id": "c", "text": "\"A low magnesium level\""}, {"id": "d", "text": "\"A low calcium level\""}]'::jsonb, '["b"]', 'Wernicke''s encephalopathy is caused by vitamin B1 (thiamine) deficiency. Vitamin B12 deficiency causes neuropathy and anemia.'),
  ('alcoholism', 3, 'A client with suspected alcoholism is admitted with a low blood glucose. The provider prescribes IV thiamine and IV dextrose. Which action should the nurse take first?', '[{"id": "a", "text": "Give the IV dextrose, then recheck glucose"}, {"id": "b", "text": "Give both medications at the same time"}, {"id": "c", "text": "Give the IV thiamine first"}, {"id": "d", "text": "Hold both until the glucose is rechecked"}]'::jsonb, '["c"]', 'IV thiamine must always be given before glucose in suspected alcoholism. Giving glucose first depletes thiamine and can precipitate or worsen Wernicke''s.'),
  ('alcoholism', 4, 'A nursing student asks why thiamine is given before glucose to a client with suspected alcoholism. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Glucose first raises magnesium and causes Torsades.\""}, {"id": "b", "text": "\"Glucose first lowers calcium and causes seizures.\""}, {"id": "c", "text": "\"Glucose first raises lipase and causes pancreatitis.\""}, {"id": "d", "text": "\"Glucose first depletes thiamine and worsens Wernicke''s.\""}]'::jsonb, '["d"]', 'Giving glucose first depletes thiamine and can precipitate or worsen Wernicke''s encephalopathy. Torsades is linked to low, not high, magnesium.'),
  ('alcoholism', 5, 'The charge nurse observes a new nurse caring for a confused client with chronic alcohol use. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Hanging IV dextrose before the IV thiamine is given"}, {"id": "b", "text": "Checking the client''s magnesium and calcium levels"}, {"id": "c", "text": "Assessing the client''s gait and eye movements"}, {"id": "d", "text": "Placing the client on continuous EKG monitoring"}]'::jsonb, '["a"]', 'IV thiamine must be given before IV glucose, so hanging dextrose first requires correction. Monitoring Mg, Ca, gait, eye movements, and the EKG are all appropriate.'),
  ('alcoholism', 6, 'The nurse is assessing a client with chronic alcohol use for Wernicke''s encephalopathy. Which finding is part of the classic triad?', '[{"id": "a", "text": "Hyperactive reflexes"}, {"id": "b", "text": "Abnormal eye movements"}, {"id": "c", "text": "Facial twitching on cheek tap"}, {"id": "d", "text": "Hand spasm with BP cuff inflation"}]'::jsonb, '["b"]', 'The classic triad is confusion, ataxia, and ophthalmoplegia (abnormal eye movements or nystagmus). Hyperactive reflexes and Chvostek''s and Trousseau''s signs indicate hypocalcemia.'),
  ('alcoholism', 7, 'A client with Wernicke''s encephalopathy did not receive treatment. The nurse recognizes the client is at risk for which condition?', '[{"id": "a", "text": "Delirium tremens"}, {"id": "b", "text": "Torsades de Pointes"}, {"id": "c", "text": "Korsakoff syndrome"}, {"id": "d", "text": "Acute pancreatitis"}]'::jsonb, '["c"]', 'If Wernicke''s encephalopathy is untreated, it can progress to Korsakoff syndrome. Delirium tremens is a withdrawal phase at 48 to 72 hours, not a result of untreated Wernicke''s.'),
  ('alcoholism', 8, 'A client with a long history of alcohol use has permanent memory loss and makes up stories to fill memory gaps. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Mild alcohol withdrawal"}, {"id": "b", "text": "Hypomagnesemia"}, {"id": "c", "text": "Vitamin B12 deficiency"}, {"id": "d", "text": "Korsakoff syndrome"}]'::jsonb, '["d"]', 'Korsakoff syndrome involves irreversible memory loss and confabulation. Vitamin B12 deficiency causes neuropathy and anemia.'),
  ('alcoholism', 9, 'A client with chronic alcohol use reports numbness and tingling in the feet, and the nurse notes peripheral neuropathy. Which deficiency is most likely contributing?', '[{"id": "a", "text": "Vitamin B12 (cobalamin)"}, {"id": "b", "text": "Vitamin B1 (thiamine)"}, {"id": "c", "text": "Magnesium"}, {"id": "d", "text": "Calcium"}]'::jsonb, '["a"]', 'Vitamin B12 deficiency in alcoholism causes neuropathy and anemia. Thiamine deficiency causes Wernicke''s encephalopathy.'),
  ('alcoholism', 10, 'A client with chronic alcohol use has a low serum magnesium level and asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Alcohol causes your body to store too much magnesium.\""}, {"id": "b", "text": "\"Chronic alcohol use leads to poor magnesium absorption.\""}, {"id": "c", "text": "\"Your thiamine treatment is using up your magnesium.\""}, {"id": "d", "text": "\"Low calcium is causing your kidneys to waste magnesium.\""}]'::jsonb, '["b"]', 'Hypomagnesemia in alcoholism is caused by poor absorption due to chronic alcohol use. The other explanations are not identified causes.'),
  ('alcoholism', 11, 'A client with chronic alcohol use has a low magnesium level. Which EKG finding should the nurse watch for?', '[{"id": "a", "text": "Sinus bradycardia"}, {"id": "b", "text": "Atrial fibrillation"}, {"id": "c", "text": "Torsades de Pointes"}, {"id": "d", "text": "Heart block"}]'::jsonb, '["c"]', 'Low magnesium in alcoholism increases the risk of arrhythmia, and Torsades de Pointes is the EKG finding to watch for. The other rhythms are not the finding associated with low magnesium.'),
  ('alcoholism', 12, 'A client with alcoholism and low magnesium is on a cardiac monitor. The nurse notes a lengthening QT interval. The nurse recognizes the client is at risk for which arrhythmia?', '[{"id": "a", "text": "Atrial flutter"}, {"id": "b", "text": "Sinus tachycardia"}, {"id": "c", "text": "Bradycardia"}, {"id": "d", "text": "Torsades de Pointes"}]'::jsonb, '["d"]', 'The nurse watches the EKG for Torsades de Pointes, which is associated with an increased QT interval in a client with low magnesium. The other rhythms are not the identified risk.'),
  ('alcoholism', 13, 'A client with chronic alcohol use has low magnesium and low calcium levels. Which nursing intervention is the priority?', '[{"id": "a", "text": "Monitor the EKG continuously"}, {"id": "b", "text": "Encourage a high-fat diet"}, {"id": "c", "text": "Give IV glucose before thiamine"}, {"id": "d", "text": "Restrict all oral fluids"}]'::jsonb, '["a"]', 'Low magnesium and low calcium in an alcoholic client call for EKG monitoring for Torsades de Pointes. Glucose should never be given before thiamine.'),
  ('alcoholism', 14, 'The nurse taps the cheek of a client with chronic alcohol use and observes twitching of the facial muscles. The nurse interprets this finding as indicating which problem?', '[{"id": "a", "text": "Thiamine deficiency"}, {"id": "b", "text": "Hypocalcemia"}, {"id": "c", "text": "Delirium tremens"}, {"id": "d", "text": "Vitamin B12 deficiency"}]'::jsonb, '["b"]', 'A facial twitch on cheek tap is a positive Chvostek''s sign, which indicates hypocalcemia. Thiamine deficiency causes Wernicke''s encephalopathy.'),
  ('alcoholism', 15, 'While taking the blood pressure of a client with chronic alcohol use, the nurse notes a spasm of the client''s hand during cuff inflation. Which electrolyte imbalance does this finding suggest?', '[{"id": "a", "text": "Low magnesium"}, {"id": "b", "text": "Low glucose"}, {"id": "c", "text": "Low calcium"}, {"id": "d", "text": "Low thiamine"}]'::jsonb, '["c"]', 'A hand spasm with BP cuff inflation is a positive Trousseau''s sign, which indicates hypocalcemia. Low magnesium is linked to arrhythmia and Torsades de Pointes.'),
  ('alcoholism', 16, 'The nurse is assessing a client with chronic alcohol use who has hypocalcemia. Which reflex finding does the nurse expect?', '[{"id": "a", "text": "Absent reflexes"}, {"id": "b", "text": "Diminished reflexes"}, {"id": "c", "text": "Normal reflexes"}, {"id": "d", "text": "Hyperactive reflexes"}]'::jsonb, '["d"]', 'Hypocalcemia causes hyperactive reflexes. Absent or diminished reflexes are not expected findings.'),
  ('alcoholism', 17, 'A client with chronic alcohol use and low magnesium suddenly develops polymorphic ventricular tachycardia on the monitor. The nurse identifies this rhythm as which arrhythmia?', '[{"id": "a", "text": "Torsades de Pointes"}, {"id": "b", "text": "Atrial fibrillation"}, {"id": "c", "text": "Sinus tachycardia"}, {"id": "d", "text": "Atrial flutter"}]'::jsonb, '["a"]', 'Torsades de Pointes is a polymorphic ventricular tachycardia that is deadly if untreated. It is the EKG finding linked to low magnesium.'),
  ('alcoholism', 18, 'A client with chronic alcohol use reports muscle cramps and has an irregular heart rhythm. Which electrolyte imbalance is most likely?', '[{"id": "a", "text": "Low calcium"}, {"id": "b", "text": "Low magnesium"}, {"id": "c", "text": "Low glucose"}, {"id": "d", "text": "Low vitamin B12"}]'::jsonb, '["b"]', 'Low magnesium in alcoholism causes arrhythmia risk and muscle cramps. Low calcium causes tetany, seizures, and Chvostek''s and Trousseau''s signs.'),
  ('alcoholism', 19, 'A client with chronic alcohol use develops tetany and a positive Trousseau''s sign. Which laboratory value does the nurse expect to be low?', '[{"id": "a", "text": "Thiamine"}, {"id": "b", "text": "Vitamin B12"}, {"id": "c", "text": "Calcium"}, {"id": "d", "text": "Lipase"}]'::jsonb, '["c"]', 'Low calcium causes tetany, seizures, and Chvostek''s and Trousseau''s signs. Lipase is elevated, not low, in pancreatitis.'),
  ('alcoholism', 20, 'A client is admitted 10 hours after the last alcoholic drink and reports anxiety, nausea, and shakiness. The nurse recognizes which stage of withdrawal?', '[{"id": "a", "text": "Life-threatening delirium tremens"}, {"id": "b", "text": "Severe withdrawal with seizures"}, {"id": "c", "text": "Korsakoff syndrome"}, {"id": "d", "text": "Mild early withdrawal"}]'::jsonb, '["d"]', 'Tremors, anxiety, nausea, and insomnia at 6 to 24 hours after the last drink indicate mild withdrawal. Seizures occur at 24 to 48 hours.'),
  ('alcoholism', 21, 'A client in alcohol withdrawal is now 30 hours past the last drink. Which complication is the most dangerous for the nurse to monitor for during this phase?', '[{"id": "a", "text": "Seizures"}, {"id": "b", "text": "Insomnia"}, {"id": "c", "text": "Mild tremors"}, {"id": "d", "text": "Nausea"}]'::jsonb, '["a"]', 'Seizures at 24 to 48 hours are the most dangerous early phase of withdrawal. Insomnia, tremors, and nausea are mild symptoms at 6 to 24 hours.'),
  ('alcoholism', 22, 'A client who had the last alcoholic drink 36 hours ago reports seeing things that are not there. How should the nurse interpret this finding?', '[{"id": "a", "text": "A mild symptom expected at this time"}, {"id": "b", "text": "A severe withdrawal symptom"}, {"id": "c", "text": "A sign of Korsakoff syndrome"}, {"id": "d", "text": "A sign of low vitamin B12"}]'::jsonb, '["b"]', 'Hallucinations at 24 to 48 hours after the last drink are part of the severe withdrawal phase. Mild withdrawal at 6 to 24 hours involves tremors, anxiety, nausea, and insomnia.'),
  ('alcoholism', 23, 'Sixty hours after the last drink, a client becomes confused, diaphoretic, and tachycardic with a high temperature and high blood pressure. The nurse suspects which condition?', '[{"id": "a", "text": "Mild withdrawal"}, {"id": "b", "text": "Wernicke''s encephalopathy"}, {"id": "c", "text": "Delirium tremens"}, {"id": "d", "text": "Hypocalcemia"}]'::jsonb, '["c"]', 'Delirium tremens occurs at 48 to 72 hours with confusion, hyperthermia, hypertension, tachycardia, and diaphoresis. Wernicke''s involves confusion with ataxia and eye movement problems, not fever and diaphoresis.'),
  ('alcoholism', 24, 'A client is diagnosed with delirium tremens. Which medication does the nurse anticipate administering?', '[{"id": "a", "text": "Vitamin B12"}, {"id": "b", "text": "IV glucose"}, {"id": "c", "text": "Pancreatic enzymes"}, {"id": "d", "text": "Lorazepam"}]'::jsonb, '["d"]', 'Delirium tremens is treated with benzodiazepines such as lorazepam or diazepam. IV glucose should not be given before thiamine in suspected alcoholism.'),
  ('alcoholism', 25, 'The nurse receives report on four clients in alcohol withdrawal. Which client should the nurse assess first?', '[{"id": "a", "text": "A client at 60 hours who is confused, febrile, and tachycardic"}, {"id": "b", "text": "A client at 8 hours who reports mild tremors and anxiety"}, {"id": "c", "text": "A client at 12 hours who reports trouble sleeping"}, {"id": "d", "text": "A client at 20 hours who reports nausea"}]'::jsonb, '["a"]', 'Confusion, hyperthermia, and tachycardia at 48 to 72 hours indicate delirium tremens, a life-threatening emergency. The other clients have mild withdrawal symptoms at 6 to 24 hours.'),
  ('alcoholism', 26, 'The nurse is teaching staff about alcohol withdrawal. Which sequence of manifestations, from earliest to latest, is correct?', '[{"id": "a", "text": "Seizures, then tremors, then delirium tremens"}, {"id": "b", "text": "Tremors, then seizures, then delirium tremens"}, {"id": "c", "text": "Delirium tremens, then seizures, then tremors"}, {"id": "d", "text": "Tremors, then delirium tremens, then seizures"}]'::jsonb, '["b"]', 'Tremors occur at 6 to 24 hours, seizures at 24 to 48 hours, and delirium tremens at 48 to 72 hours. The other options place these phases in the wrong order.'),
  ('alcoholism', 27, 'A nurse is planning care for a client admitted for alcohol use. During which time after the last drink should the nurse anticipate the greatest risk for withdrawal seizures?', '[{"id": "a", "text": "1 to 5 hours"}, {"id": "b", "text": "6 to 24 hours"}, {"id": "c", "text": "24 to 48 hours"}, {"id": "d", "text": "72 to 96 hours"}]'::jsonb, '["c"]', 'Withdrawal seizures occur at 24 to 48 hours, the most dangerous early phase. The 6 to 24 hour window involves mild symptoms such as tremors and anxiety.'),
  ('alcoholism', 28, 'A client''s last drink was at 8:00 AM on Monday. During which period should the nurse anticipate the highest risk of delirium tremens?', '[{"id": "a", "text": "Monday afternoon to Monday evening"}, {"id": "b", "text": "Monday evening to Tuesday morning"}, {"id": "c", "text": "Tuesday morning to Wednesday morning"}, {"id": "d", "text": "Wednesday morning to Thursday morning"}]'::jsonb, '["d"]', 'Delirium tremens occurs 48 to 72 hours after the last drink, which falls between Wednesday morning and Thursday morning. Tuesday to Wednesday morning (24 to 48 hours) is the seizure phase.'),
  ('alcoholism', 29, 'The nurse is monitoring a client 55 hours after the last drink. Which vital sign pattern suggests delirium tremens?', '[{"id": "a", "text": "High temperature, high blood pressure, and fast pulse"}, {"id": "b", "text": "Low temperature, low blood pressure, and slow pulse"}, {"id": "c", "text": "Normal temperature, low blood pressure, and slow pulse"}, {"id": "d", "text": "Low temperature, high blood pressure, and slow pulse"}]'::jsonb, '["a"]', 'Delirium tremens causes hyperthermia, hypertension, and tachycardia. Low temperature, low blood pressure, and slow pulse are the reverse of these findings.'),
  ('alcoholism', 30, 'A client is admitted 14 hours after the last drink. Which finding does the nurse expect at this time?', '[{"id": "a", "text": "Confusion with hyperthermia"}, {"id": "b", "text": "Insomnia and nausea"}, {"id": "c", "text": "Generalized seizures"}, {"id": "d", "text": "Diaphoresis with hypertension"}]'::jsonb, '["b"]', 'At 6 to 24 hours after the last drink, mild withdrawal includes tremors, anxiety, nausea, and insomnia. Confusion with hyperthermia indicates delirium tremens at 48 to 72 hours.'),
  ('alcoholism', 31, 'A client with chronic alcohol use reports severe epigastric pain that radiates to the back. The nurse suspects which complication?', '[{"id": "a", "text": "Wernicke''s encephalopathy"}, {"id": "b", "text": "Delirium tremens"}, {"id": "c", "text": "Acute pancreatitis"}, {"id": "d", "text": "Torsades de Pointes"}]'::jsonb, '["c"]', 'Acute pancreatitis is very common in chronic alcohol abusers, and the nurse monitors for epigastric pain radiating to the back. Wernicke''s presents with confusion, ataxia, and eye problems.'),
  ('alcoholism', 32, 'A client with chronic alcohol use is being evaluated for pancreatitis. Which laboratory findings support this diagnosis?', '[{"id": "a", "text": "Decreased lipase and amylase"}, {"id": "b", "text": "Decreased magnesium only"}, {"id": "c", "text": "Elevated vitamin B12"}, {"id": "d", "text": "Elevated lipase and amylase"}]'::jsonb, '["d"]', 'Signs of pancreatitis include epigastric pain radiating to the back and elevated lipase and amylase. Decreased enzyme levels do not support pancreatitis.'),
  ('alcoholism', 33, 'A nursing student asks how chronic alcohol use leads to acute pancreatitis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Alcohol damages acinar cells and triggers early enzyme activation.\""}, {"id": "b", "text": "\"Alcohol lowers calcium, which blocks the pancreatic ducts.\""}, {"id": "c", "text": "\"Alcohol depletes thiamine, which inflames the pancreas.\""}, {"id": "d", "text": "\"Alcohol raises magnesium, which digests the pancreas.\""}]'::jsonb, '["a"]', 'Alcohol directly damages pancreatic acinar cells and triggers premature enzyme activation, leading to autodigestion. Thiamine depletion causes Wernicke''s, not pancreatitis.'),
  ('alcoholism', 34, 'The nurse teaches a client with chronic alcohol use who was treated for acute pancreatitis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Alcohol can directly damage my pancreas.\""}, {"id": "b", "text": "\"Damage to my pancreas can never become permanent.\""}, {"id": "c", "text": "\"Pancreatitis is very common in heavy drinkers.\""}, {"id": "d", "text": "\"My pancreas can end up digesting itself.\""}]'::jsonb, '["b"]', 'Acute pancreatitis from alcohol can progress to chronic pancreatitis with irreversible damage, so this statement needs correction. The other statements are accurate.'),
  ('alcoholism', 35, 'The nurse is planning care for a client with chronic alcohol use. Which laboratory values should the nurse monitor regularly?', '[{"id": "a", "text": "Sodium and potassium"}, {"id": "b", "text": "Hemoglobin and platelets"}, {"id": "c", "text": "Magnesium and calcium"}, {"id": "d", "text": "Albumin and protein"}]'::jsonb, '["c"]', 'The nurse should regularly monitor magnesium and calcium levels in a client with chronic alcohol use. Low levels increase the risk for Torsades de Pointes and seizures.'),
  ('alcoholism', 36, 'The nurse is caring for a client with chronic alcohol use. Which new finding should the nurse report immediately as a possible sign of Wernicke''s encephalopathy?', '[{"id": "a", "text": "Mild nausea at 10 hours"}, {"id": "b", "text": "Numbness in both feet"}, {"id": "c", "text": "Muscle cramps in the legs"}, {"id": "d", "text": "Confusion and an unsteady gait"}]'::jsonb, '["d"]', 'The nurse watches closely for confusion, ataxia, and eye movement abnormalities, which signal Wernicke''s encephalopathy. Numbness reflects neuropathy from vitamin B12 deficiency.'),
  ('alcoholism', 37, 'A client with chronic alcohol use is suspected of having Wernicke''s encephalopathy. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "IV thiamine"}, {"id": "b", "text": "IV dextrose alone"}, {"id": "c", "text": "Oral calcium"}, {"id": "d", "text": "Vitamin B12 injection"}]'::jsonb, '["a"]', 'Wernicke''s is caused by thiamine deficiency, and IV thiamine is given before glucose. Giving dextrose alone can deplete thiamine and worsen Wernicke''s.'),
  ('alcoholism', 38, 'The nurse is assessing a client with chronic alcohol use for hypocalcemia. Which technique does the nurse use to assess for Chvostek''s sign?', '[{"id": "a", "text": "Inflate a blood pressure cuff on the upper arm"}, {"id": "b", "text": "Tap the client''s cheek and watch the face"}, {"id": "c", "text": "Ask the client to walk in a straight line"}, {"id": "d", "text": "Ask the client to follow a finger with the eyes"}]'::jsonb, '["b"]', 'Chvostek''s sign is a facial twitch on cheek tap. Inflating a BP cuff to observe hand spasm assesses Trousseau''s sign.'),
  ('alcoholism', 39, 'The nurse is assessing a client with chronic alcohol use for Trousseau''s sign. Which finding indicates a positive result?', '[{"id": "a", "text": "Twitching of the face after a cheek tap"}, {"id": "b", "text": "Rapid eye movements on lateral gaze"}, {"id": "c", "text": "Spasm of the hand during cuff inflation"}, {"id": "d", "text": "Unsteady gait when walking heel to toe"}]'::jsonb, '["c"]', 'A positive Trousseau''s sign is a hand spasm on BP cuff inflation, indicating hypocalcemia. Facial twitching after a cheek tap is Chvostek''s sign.'),
  ('alcoholism', 40, 'A nursing student is reviewing electrolyte findings in alcoholism. Which statement by the student requires correction?', '[{"id": "a", "text": "\"Low magnesium can lead to Torsades de Pointes.\""}, {"id": "b", "text": "\"Low calcium can cause hyperactive reflexes.\""}, {"id": "c", "text": "\"Low calcium and low magnesium can both cause seizures.\""}, {"id": "d", "text": "\"A positive Chvostek''s sign means calcium is high.\""}]'::jsonb, '["d"]', 'Chvostek''s and Trousseau''s signs indicate hypocalcemia, not high calcium, so this statement needs correction. The other statements are accurate.'),
  ('alcoholism', 41, 'The nurse teaches a client with chronic alcohol use about vitamin B12 deficiency. Which client statement indicates understanding?', '[{"id": "a", "text": "\"Low B12 can cause nerve problems and anemia.\""}, {"id": "b", "text": "\"Low B12 causes hand spasms and seizures.\""}, {"id": "c", "text": "\"Low B12 causes Torsades de Pointes.\""}, {"id": "d", "text": "\"Low B12 causes Wernicke''s encephalopathy.\""}]'::jsonb, '["a"]', 'Vitamin B12 deficiency causes neuropathy and anemia. Wernicke''s encephalopathy is caused by vitamin B1 (thiamine) deficiency.'),
  ('alcoholism', 42, 'Two clients are being treated for alcohol withdrawal. Which finding best indicates that a client has progressed to delirium tremens rather than mild withdrawal?', '[{"id": "a", "text": "Insomnia and mild anxiety"}, {"id": "b", "text": "Tremors and nausea"}, {"id": "c", "text": "Confusion with hyperthermia and diaphoresis"}, {"id": "d", "text": "Shakiness on the first morning"}]'::jsonb, '["c"]', 'Delirium tremens involves confusion, hyperthermia, hypertension, tachycardia, and diaphoresis. Insomnia, anxiety, tremors, and nausea are mild withdrawal symptoms.'),
  ('alcoholism', 43, 'A client 50 hours after the last drink is diagnosed with delirium tremens. Which prescribed medication is the treatment for this condition?', '[{"id": "a", "text": "Vitamin B12 injection"}, {"id": "b", "text": "IV glucose bolus"}, {"id": "c", "text": "Oral calcium tablets"}, {"id": "d", "text": "IV diazepam"}]'::jsonb, '["d"]', 'Delirium tremens is a life-threatening emergency treated with benzodiazepines such as diazepam or lorazepam. IV glucose should not be given before thiamine in suspected alcoholism.'),
  ('alcoholism', 44, 'The family of a client with Wernicke''s encephalopathy asks why prompt treatment matters. Which statement by the family indicates understanding of the nurse''s teaching?', '[{"id": "a", "text": "\"Without treatment, the memory loss may become permanent.\""}, {"id": "b", "text": "\"Without treatment, the confusion always goes away.\""}, {"id": "c", "text": "\"Without treatment, the only risk is mild tremors.\""}, {"id": "d", "text": "\"Without treatment, the memory loss will fully reverse.\""}]'::jsonb, '["a"]', 'Untreated Wernicke''s can progress to Korsakoff syndrome with irreversible memory loss and confabulation. Full reversal of memory loss contradicts this.'),
  ('alcoholism', 45, 'The nurse is caring for four clients with alcohol-related problems. Which client requires the nurse''s immediate attention?', '[{"id": "a", "text": "A client with B12 deficiency reporting foot numbness"}, {"id": "b", "text": "A client at 36 hours since the last drink who is seizing"}, {"id": "c", "text": "A client at 8 hours since the last drink with mild tremors"}, {"id": "d", "text": "A client with chronic use asking about magnesium levels"}]'::jsonb, '["b"]', 'Seizures at 24 to 48 hours are the most dangerous early phase of withdrawal and need immediate attention. Mild tremors at 6 to 24 hours are mild withdrawal.'),
  ('alcoholism', 46, 'A client with chronic alcohol use has low calcium and low magnesium levels. Which complication should the nurse monitor for?', '[{"id": "a", "text": "Increased bile production"}, {"id": "b", "text": "Elevated vitamin B12"}, {"id": "c", "text": "Seizure activity"}, {"id": "d", "text": "Low blood pressure from DTs"}]'::jsonb, '["c"]', 'The nurse monitors for seizure activity when calcium and magnesium are low. Delirium tremens causes hypertension, not low blood pressure.'),
  ('alcoholism', 47, 'A client with chronic alcohol use asks why drinking causes the pancreas to become inflamed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Alcohol lowers your magnesium, which swells the pancreas.\""}, {"id": "b", "text": "\"Alcohol blocks thiamine, which inflames the pancreas.\""}, {"id": "c", "text": "\"Alcohol raises your calcium, which irritates the pancreas.\""}, {"id": "d", "text": "\"Alcohol directly damages the cells that make enzymes.\""}]'::jsonb, '["d"]', 'Alcohol directly damages pancreatic acinar cells, triggering premature enzyme activation and autodigestion. Thiamine deficiency causes Wernicke''s encephalopathy, not pancreatitis.'),
  ('alcoholism', 48, 'The nurse teaches a client with chronic alcohol use about thiamine deficiency. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Low thiamine can make me confused.\""}, {"id": "b", "text": "\"Thiamine is the same as vitamin B1.\""}, {"id": "c", "text": "\"Low thiamine can affect my balance.\""}, {"id": "d", "text": "\"Wernicke''s is caused by low vitamin B12.\""}]'::jsonb, '["d"]', 'Wernicke''s encephalopathy is caused by vitamin B1 (thiamine) deficiency, not vitamin B12. Confusion and ataxia are accurate effects of thiamine deficiency.'),
  ('alcoholism', 49, 'The nurse is performing a focused neurological assessment on a newly admitted client with chronic alcohol use. Which assessments best screen for Wernicke''s encephalopathy?', '[{"id": "a", "text": "Mental status, gait, and eye movements"}, {"id": "b", "text": "Reflexes, cheek tap, and BP cuff test"}, {"id": "c", "text": "Pupil size, skin color, and hand grip"}, {"id": "d", "text": "Pain level, appetite, and bowel sounds"}]'::jsonb, '["a"]', 'Wernicke''s encephalopathy presents with confusion, ataxia, and abnormal eye movements, so these are assessed. Reflexes, cheek tap, and the BP cuff test screen for hypocalcemia.'),
  ('alcoholism', 50, 'A client with chronic alcohol use is found to have anemia. Which deficiency should the nurse recognize as a likely contributor?', '[{"id": "a", "text": "Vitamin B1 (thiamine)"}, {"id": "b", "text": "Vitamin B12 (cobalamin)"}, {"id": "c", "text": "Calcium"}, {"id": "d", "text": "Magnesium"}]'::jsonb, '["b"]', 'Vitamin B12 deficiency in alcoholism causes neuropathy and anemia. Thiamine deficiency causes Wernicke''s encephalopathy.'),
  ('cirrhosis', 1, 'A client newly diagnosed with cirrhosis asks the nurse what is happening to the liver. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Fat is temporarily coating the outside of your liver.\""}, {"id": "b", "text": "\"Your liver is swollen from a short-term viral infection.\""}, {"id": "c", "text": "\"Healthy liver tissue is being replaced by scar tissue.\""}, {"id": "d", "text": "\"Your bile ducts are making extra bile that pools there.\""}]'::jsonb, '["c"]', 'Cirrhosis is a chronic, progressive disease in which healthy liver tissue is replaced by fibrotic (scar) tissue that impairs liver function. It is not a short-term, temporary process.'),
  ('cirrhosis', 2, 'A client with obesity and type 2 diabetes who reports no alcohol use is diagnosed with cirrhosis. Which underlying cause is most consistent with this history?', '[{"id": "a", "text": "Non-alcoholic fatty liver disease"}, {"id": "b", "text": "Autoimmune hepatitis"}, {"id": "c", "text": "Bile duct disorder"}, {"id": "d", "text": "Wernicke encephalopathy"}]'::jsonb, '["a"]', 'NAFLD is a cause of cirrhosis linked to obesity and diabetes. Autoimmune hepatitis involves the immune system attacking liver cells, and Wernicke encephalopathy is a thiamine deficiency complication, not a cause.'),
  ('cirrhosis', 3, 'The nurse is reviewing health histories at a clinic. Which client history should the nurse recognize as a risk factor for cirrhosis?', '[{"id": "a", "text": "Long-standing seasonal allergies"}, {"id": "b", "text": "Recurrent urinary tract infections"}, {"id": "c", "text": "Childhood asthma treated with inhalers"}, {"id": "d", "text": "Chronic hepatitis C infection"}]'::jsonb, '["d"]', 'Viral hepatitis B and C cause long-term liver inflammation that leads to scarring. The other histories are not listed causes of cirrhosis.'),
  ('cirrhosis', 4, 'A client with cirrhosis has an elevated INR and PT. Which explanation for these results is accurate?', '[{"id": "a", "text": "The liver is storing too much vitamin K."}, {"id": "b", "text": "The liver cannot make enough clotting factors."}, {"id": "c", "text": "The spleen is producing too many platelets."}, {"id": "d", "text": "The liver is overproducing serum albumin."}]'::jsonb, '["b"]', 'An elevated INR/PT/PTT reflects clotting dysfunction because the damaged liver can''t make clotting factors. Platelets are decreased, not increased, in cirrhosis.'),
  ('cirrhosis', 5, 'A client with cirrhosis has a decreased serum albumin level. Which assessment finding should the nurse anticipate?', '[{"id": "a", "text": "Bright red blood in the stool"}, {"id": "b", "text": "Flapping tremor of the hands"}, {"id": "c", "text": "Ascites and peripheral edema"}, {"id": "d", "text": "Male breast enlargement"}]'::jsonb, '["c"]', 'Low albumin causes ascites and edema because albumin is needed for fluid balance. A flapping tremor reflects hepatic encephalopathy related to ammonia, not low albumin.'),
  ('cirrhosis', 6, 'A client with cirrhosis becomes newly confused. Which laboratory result best supports hepatic encephalopathy as the cause?', '[{"id": "a", "text": "Elevated serum ammonia"}, {"id": "b", "text": "Elevated serum albumin"}, {"id": "c", "text": "Decreased serum bilirubin"}, {"id": "d", "text": "Decreased AST and ALT"}]'::jsonb, '["a"]', 'In hepatic encephalopathy the liver fails to clear ammonia, so an elevated ammonia level supports this cause of confusion. Albumin decreases and bilirubin and AST/ALT increase in cirrhosis.'),
  ('cirrhosis', 7, 'A client with cirrhosis has elevated AST and ALT levels. The nurse interprets these results as indicating which problem?', '[{"id": "a", "text": "Excess clotting factor production"}, {"id": "b", "text": "Fluid volume deficit"}, {"id": "c", "text": "Improved ammonia clearance"}, {"id": "d", "text": "Liver cell damage"}]'::jsonb, '["d"]', 'Increased AST/ALT indicates liver cell damage. Clotting dysfunction in cirrhosis results from too few clotting factors, not excess production.'),
  ('cirrhosis', 8, 'A client with cirrhosis has decreased platelet and white blood cell counts. The nurse identifies that the client is at increased risk for which problems?', '[{"id": "a", "text": "Fluid deficit and hypotension"}, {"id": "b", "text": "Infection and bleeding"}, {"id": "c", "text": "Blood clots and stroke"}, {"id": "d", "text": "Ammonia buildup and coma"}]'::jsonb, '["b"]', 'Decreased platelets and WBCs create infection and bleeding risk. Low platelets increase bleeding, not clotting.'),
  ('cirrhosis', 9, 'A client with cirrhosis and portal hypertension has an enlarged spleen and a low platelet count. Which explanation for the low platelet count is accurate?', '[{"id": "a", "text": "Alcohol has destroyed the platelets in the blood."}, {"id": "b", "text": "Platelets are being lost into the ascitic fluid."}, {"id": "c", "text": "The enlarged spleen is trapping platelets and WBCs."}, {"id": "d", "text": "Lactulose therapy is suppressing platelet production."}]'::jsonb, '["c"]', 'Portal hypertension causes splenomegaly, and the spleen traps WBCs and platelets, increasing infection and bleeding risk. Ascites is fluid accumulation and does not explain the low platelets.'),
  ('cirrhosis', 10, 'A client with cirrhosis asks why portal hypertension has developed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The scarred liver restricts blood flow through the portal vein.\""}, {"id": "b", "text": "\"Low albumin levels speed up blood flow into the liver.\""}, {"id": "c", "text": "\"The enlarged spleen pumps blood into the liver faster.\""}, {"id": "d", "text": "\"Your beta-blocker medication raises your portal pressure.\""}]'::jsonb, '["a"]', 'The scarred liver restricts portal vein blood flow, which increases pressure. Beta-blockers such as propranolol reduce, not raise, portal pressure.'),
  ('cirrhosis', 11, 'A client with cirrhosis suddenly vomits a large amount of bright red blood. How should the nurse interpret this finding?', '[{"id": "a", "text": "An expected effect of lactulose therapy"}, {"id": "b", "text": "Lower GI bleeding from the colon"}, {"id": "c", "text": "A typical sign of hepatic encephalopathy"}, {"id": "d", "text": "A life-threatening variceal emergency"}]'::jsonb, '["d"]', 'Esophageal varices can rupture and cause hematemesis, and bleeding esophageal varices are a life-threatening emergency. Lower GI bleeding presents as bright red blood in the stool, not vomiting.'),
  ('cirrhosis', 12, 'The nurse is caring for four clients with cirrhosis. Which client should the nurse assess first?', '[{"id": "a", "text": "The client who has reddened palms"}, {"id": "b", "text": "The client vomiting coffee-ground material"}, {"id": "c", "text": "The client with spider angiomas on the chest"}, {"id": "d", "text": "The client reporting itchy skin"}]'::jsonb, '["b"]', 'Vomiting coffee-ground blood is hematemesis, indicating GI bleeding that must always be monitored for and can be life-threatening. Palmar erythema, spider angiomas, and pruritus are expected chronic signs of cirrhosis.'),
  ('cirrhosis', 13, 'A client with cirrhosis reports having black, tarry stools for the past day. The nurse interprets this finding as which condition?', '[{"id": "a", "text": "Lower GI bleeding"}, {"id": "b", "text": "Expected lactulose effect"}, {"id": "c", "text": "Upper GI bleeding"}, {"id": "d", "text": "Elevated bilirubin"}]'::jsonb, '["c"]', 'Melena, black tarry stool, indicates upper GI bleeding, such as from ruptured varices. Bright red blood in the stool, not black stool, indicates lower GI bleeding.'),
  ('cirrhosis', 14, 'A client with cirrhosis has bright red blood in the stool. The nurse recognizes that this finding most likely indicates bleeding from which location?', '[{"id": "a", "text": "The colon or rectum"}, {"id": "b", "text": "The esophageal veins"}, {"id": "c", "text": "The stomach lining"}, {"id": "d", "text": "The liver sinusoids"}]'::jsonb, '["a"]', 'Hematochezia, bright red blood in the stool, indicates lower GI bleeding from the colon or rectum. Black, tarry stool (melena) is the finding associated with upper GI bleeding.'),
  ('cirrhosis', 15, 'A client with cirrhosis and esophageal varices is started on propranolol. The client asks why this medication is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It lowers the ammonia level in your blood.\""}, {"id": "b", "text": "\"It relieves the itching from bile salts.\""}, {"id": "c", "text": "\"It removes extra fluid from your abdomen.\""}, {"id": "d", "text": "\"It lowers portal pressure to prevent bleeding.\""}]'::jsonb, '["d"]', 'Beta-blockers such as propranolol reduce portal pressure to prevent variceal bleeding. Lowering ammonia is the purpose of lactulose, and relieving itching is the purpose of cholestyramine.'),
  ('cirrhosis', 16, 'A client with cirrhosis and esophageal varices is scheduled for a TIPS procedure. Which statement by the nurse correctly describes the purpose of the procedure?', '[{"id": "a", "text": "\"It replaces your scarred liver with a donor liver.\""}, {"id": "b", "text": "\"It lowers portal pressure by bypassing the liver.\""}, {"id": "c", "text": "\"It drains fluid from your abdomen with a needle.\""}, {"id": "d", "text": "\"It delivers thiamine directly into your liver.\""}]'::jsonb, '["b"]', 'TIPS reroutes blood from the portal vein, bypassing the liver, which reduces portal pressure and prevents variceal bleeding. Replacing the liver describes a liver transplant, and draining abdominal fluid describes paracentesis.'),
  ('cirrhosis', 17, 'A client with cirrhosis had a TIPS procedure for esophageal varices. Which outcome indicates the procedure achieved its intended goal?', '[{"id": "a", "text": "The serum albumin level has risen."}, {"id": "b", "text": "The client''s skin itching has resolved."}, {"id": "c", "text": "No further variceal bleeding occurs."}, {"id": "d", "text": "The spider angiomas have disappeared."}]'::jsonb, '["c"]', 'A TIPS shunt prevents bleeding from esophageal varices, so absence of further variceal bleeding shows the goal was met. Itching from bile salts is treated with cholestyramine, not TIPS.'),
  ('cirrhosis', 18, 'A client with cirrhosis is newly confused, and the hands flap when the arms are held out with wrists extended. The nurse suspects which complication?', '[{"id": "a", "text": "Hepatic encephalopathy"}, {"id": "b", "text": "Hepatorenal syndrome"}, {"id": "c", "text": "Ruptured esophageal varices"}, {"id": "d", "text": "Splenomegaly"}]'::jsonb, '["a"]', 'Asterixis, a flapping tremor of the hands, together with confusion indicates hepatic encephalopathy. Hepatorenal syndrome is renal failure, and ruptured varices present with hematemesis and melena.'),
  ('cirrhosis', 19, 'The nurse is assessing a client with cirrhosis for hepatic encephalopathy. Which finding is consistent with this complication?', '[{"id": "a", "text": "Bright red blood in the stool"}, {"id": "b", "text": "Enlarged breast tissue"}, {"id": "c", "text": "Generalized skin itching"}, {"id": "d", "text": "A musty odor to the breath"}]'::jsonb, '["d"]', 'Hepatic fetor, a musty breath odor, is a symptom of hepatic encephalopathy along with confusion, asterixis, and coma. Itching results from high bilirubin and gynecomastia from increased estrogen, not from encephalopathy.'),
  ('cirrhosis', 20, 'A client with hepatic encephalopathy is prescribed lactulose. Which explanation of how the medication helps is accurate?', '[{"id": "a", "text": "\"It raises your platelet count to reduce bleeding.\""}, {"id": "b", "text": "\"It lowers ammonia, which leaves the body in stool.\""}, {"id": "c", "text": "\"It reduces the fluid that collects in your abdomen.\""}, {"id": "d", "text": "\"It replaces the thiamine your body is missing.\""}]'::jsonb, '["b"]', 'Lactulose decreases ammonia absorption, and the ammonia is excreted via stool, preventing and treating hepatic encephalopathy. Replacing thiamine is the role of IV thiamine for Wernicke encephalopathy.'),
  ('cirrhosis', 21, 'A client with cirrhosis has been receiving lactulose for hepatic encephalopathy. Which finding indicates the medication is effective?', '[{"id": "a", "text": "Larger abdominal girth and weight gain"}, {"id": "b", "text": "Lower albumin level and more edema"}, {"id": "c", "text": "Improved orientation and lower ammonia"}, {"id": "d", "text": "Higher platelets and less bruising"}]'::jsonb, '["c"]', 'Lactulose lowers ammonia, and the nurse monitors mental status and ammonia levels, so improved orientation with a lower ammonia level shows effectiveness. Platelet counts are monitored for bleeding risk, not to evaluate lactulose.'),
  ('cirrhosis', 22, 'The nurse is teaching a client with cirrhosis about lactulose. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"This medicine helps lower my ammonia level.\""}, {"id": "b", "text": "\"I should report it if I become more confused.\""}, {"id": "c", "text": "\"The ammonia leaves my body through my stool.\""}, {"id": "d", "text": "\"This medicine will reduce the swelling in my legs.\""}]'::jsonb, '["d"]', 'Lactulose lowers ammonia to treat hepatic encephalopathy; edema is managed with a low sodium diet and diuretics such as spironolactone and furosemide. The other statements are accurate.'),
  ('cirrhosis', 23, 'A client with cirrhosis and hepatic encephalopathy has a rising ammonia level. Which nursing action is the priority?', '[{"id": "a", "text": "Monitor neurological status closely"}, {"id": "b", "text": "Measure abdominal girth every shift"}, {"id": "c", "text": "Inspect the chest for spider angiomas"}, {"id": "d", "text": "Assess the palms for redness"}]'::jsonb, '["a"]', 'Ammonia can cause brain swelling, and cerebral edema is life-threatening, so neuro status must be monitored. Spider angiomas and palmar erythema are expected signs of cirrhosis, not life-threatening.'),
  ('cirrhosis', 24, 'A client with a long history of alcohol use is admitted with confusion, poor coordination, and vision problems. Which prescription should the nurse anticipate?', '[{"id": "a", "text": "Oral cholestyramine"}, {"id": "b", "text": "IV thiamine (vitamin B1)"}, {"id": "c", "text": "Oral spironolactone"}, {"id": "d", "text": "Oral propranolol"}]'::jsonb, '["b"]', 'Confusion, poor coordination, and vision problems in a client who uses alcohol suggest Wernicke encephalopathy, which is treated with IV thiamine to prevent brain damage. Cholestyramine treats itching, and spironolactone treats ascites and edema.'),
  ('cirrhosis', 25, 'The nurse is explaining Wernicke encephalopathy to a client with alcohol-related cirrhosis. The nurse explains that this condition results from which problem?', '[{"id": "a", "text": "A buildup of ammonia"}, {"id": "b", "text": "A low albumin level"}, {"id": "c", "text": "A thiamine deficiency"}, {"id": "d", "text": "An excess of estrogen"}]'::jsonb, '["c"]', 'Wernicke encephalopathy is caused by thiamine (B1) deficiency, especially in alcoholics. Ammonia buildup causes hepatic encephalopathy, a different complication.'),
  ('cirrhosis', 26, 'A client with alcohol-related cirrhosis is at risk for Wernicke encephalopathy. Which findings should the nurse monitor for?', '[{"id": "a", "text": "Itching and yellow skin"}, {"id": "b", "text": "Black stools and bloody vomit"}, {"id": "c", "text": "Spider angiomas and red palms"}, {"id": "d", "text": "Confusion and poor coordination"}]'::jsonb, '["d"]', 'Wernicke encephalopathy symptoms include confusion, poor coordination, and vision problems. Black stools and bloody vomit indicate GI bleeding, not Wernicke encephalopathy.'),
  ('cirrhosis', 27, 'A male client with cirrhosis is embarrassed about breast enlargement. The nurse explains that this change is related to which factor?', '[{"id": "a", "text": "Increased estrogen"}, {"id": "b", "text": "Decreased ammonia"}, {"id": "c", "text": "Abdominal fluid"}, {"id": "d", "text": "Low thiamine"}]'::jsonb, '["a"]', 'Gynecomastia, male breast enlargement, occurs with cirrhosis because of increased estrogen. Low thiamine causes Wernicke encephalopathy, not breast enlargement.'),
  ('cirrhosis', 28, 'A client with cirrhosis reports severe, constant itching. Which medication should the nurse anticipate the provider will prescribe for this symptom?', '[{"id": "a", "text": "Propranolol"}, {"id": "b", "text": "Cholestyramine"}, {"id": "c", "text": "Furosemide"}, {"id": "d", "text": "Lactulose"}]'::jsonb, '["b"]', 'Cholestyramine reduces itching (pruritus) from bile salts. Lactulose lowers ammonia, and furosemide is a diuretic for ascites and edema.'),
  ('cirrhosis', 29, 'The nurse is performing a skin assessment on a client with cirrhosis. Which findings should the nurse expect?', '[{"id": "a", "text": "Pale, cool palms"}, {"id": "b", "text": "Bluish nail beds"}, {"id": "c", "text": "Spider angiomas and red palms"}, {"id": "d", "text": "Purple abdominal stretch marks"}]'::jsonb, '["c"]', 'Spider angiomas and red palms (palmar erythema) are signs of cirrhosis. Pale palms are the opposite of the expected palmar erythema.'),
  ('cirrhosis', 30, 'A client with cirrhosis has yellowing of the sclera and skin. Which laboratory value should the nurse expect to be elevated?', '[{"id": "a", "text": "Albumin"}, {"id": "b", "text": "Platelets"}, {"id": "c", "text": "White blood cells"}, {"id": "d", "text": "Bilirubin"}]'::jsonb, '["d"]', 'Increased bilirubin causes jaundice, the yellowing of the eyes and skin. Albumin, platelets, and WBCs are decreased in cirrhosis.'),
  ('cirrhosis', 31, 'A client with advanced cirrhosis develops renal failure. The nurse recognizes this complication as which condition?', '[{"id": "a", "text": "Hepatorenal syndrome"}, {"id": "b", "text": "Hepatic encephalopathy"}, {"id": "c", "text": "Wernicke encephalopathy"}, {"id": "d", "text": "Splenomegaly"}]'::jsonb, '["a"]', 'Renal failure in cirrhosis is hepatorenal syndrome. Hepatic encephalopathy results from ammonia affecting the brain, not the kidneys.'),
  ('cirrhosis', 32, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a client with cirrhosis and a low platelet count. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting a black stool to the nurse"}, {"id": "b", "text": "Using a stiff-bristled toothbrush for mouth care"}, {"id": "c", "text": "Weighing the client each morning"}, {"id": "d", "text": "Reporting vomit that looks like coffee grounds"}]'::jsonb, '["b"]', 'Bleeding prevention in cirrhosis includes using a soft toothbrush, so a stiff-bristled brush must be corrected. Reporting melena or coffee-ground emesis and obtaining daily weights are appropriate.'),
  ('cirrhosis', 33, 'The nurse is planning care to prevent bleeding in a client with cirrhosis. Which laboratory values should the nurse check?', '[{"id": "a", "text": "Ammonia and bilirubin"}, {"id": "b", "text": "AST and ALT"}, {"id": "c", "text": "Platelets and PT/INR"}, {"id": "d", "text": "Albumin and sodium"}]'::jsonb, '["c"]', 'Bleeding prevention includes checking platelets and PT/INR. Ammonia reflects hepatic encephalopathy and AST/ALT reflect liver cell damage, not bleeding risk.'),
  ('cirrhosis', 34, 'A client with cirrhosis has ascites and peripheral edema. Which diet should the nurse reinforce?', '[{"id": "a", "text": "High-sodium, high-calorie diet"}, {"id": "b", "text": "Low-calorie, high-sodium diet"}, {"id": "c", "text": "Low-calorie, high-fat diet"}, {"id": "d", "text": "Low-sodium, high-calorie diet"}]'::jsonb, '["d"]', 'Ascites and edema are managed with a low sodium diet, and nutrition in cirrhosis is high-calorie. The other options include high sodium or low calories.'),
  ('cirrhosis', 35, 'The nurse reinforces dietary teaching for a client with cirrhosis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will add salt to my meals to improve my appetite.\""}, {"id": "b", "text": "\"I will make sure I eat enough calories each day.\""}, {"id": "c", "text": "\"I will take my vitamin supplements as prescribed.\""}, {"id": "d", "text": "\"I will not drink any alcohol at all from now on.\""}]'::jsonb, '["a"]', 'The cirrhosis diet is low sodium, so adding salt shows a need for further teaching. A high-calorie diet, vitamin supplements, and complete alcohol avoidance are correct.'),
  ('cirrhosis', 36, 'A client with cirrhosis has increasing ascites and edema. Which medications should the nurse anticipate?', '[{"id": "a", "text": "Lactulose and thiamine"}, {"id": "b", "text": "Spironolactone and furosemide"}, {"id": "c", "text": "Propranolol and cholestyramine"}, {"id": "d", "text": "Lactulose and propranolol"}]'::jsonb, '["b"]', 'Spironolactone and furosemide are diuretics used for ascites and edema. Lactulose lowers ammonia, and propranolol reduces portal pressure to prevent variceal bleeding.'),
  ('cirrhosis', 37, 'A client with cirrhosis has severe ascites despite a low sodium diet and diuretics. Which procedure should the nurse anticipate?', '[{"id": "a", "text": "IV thiamine infusion"}, {"id": "b", "text": "Lactulose therapy"}, {"id": "c", "text": "Paracentesis"}, {"id": "d", "text": "Cholestyramine therapy"}]'::jsonb, '["c"]', 'Paracentesis is used for severe ascites. Lactulose treats hepatic encephalopathy and IV thiamine treats Wernicke encephalopathy, not ascites.'),
  ('cirrhosis', 38, 'The nurse reviews daily weights for a client with cirrhosis. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "A gain of 0.5 lb since yesterday"}, {"id": "b", "text": "No weight change over the past week"}, {"id": "c", "text": "A loss of 1 lb after diuretic therapy"}, {"id": "d", "text": "A gain of 3 lb since yesterday"}]'::jsonb, '["d"]', 'Daily weights monitor fluid retention, and a gain of more than 2 lb/day or 5 lb/week should be reported. A 0.5-lb gain in one day is below this threshold.'),
  ('cirrhosis', 39, 'A client with cirrhosis has gained about 1 lb each day for 6 days, for a total of 6 lb this week. Which action should the nurse take?', '[{"id": "a", "text": "Report the weight gain to the provider"}, {"id": "b", "text": "Continue routine monitoring only"}, {"id": "c", "text": "Encourage more salt in the diet"}, {"id": "d", "text": "Stop the daily weight checks"}]'::jsonb, '["a"]', 'Although no single day exceeded 2 lb, a gain of more than 5 lb in a week indicates fluid retention and should be reported. Adding salt would worsen fluid retention because the diet is low sodium.'),
  ('cirrhosis', 40, 'A client with cirrhosis states, "I''ll cut back to just one beer a day." Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"One drink a day is a safe amount with cirrhosis.\""}, {"id": "b", "text": "\"Alcohol needs to be avoided completely now.\""}, {"id": "c", "text": "\"Switching to wine would be a safer choice.\""}, {"id": "d", "text": "\"Limiting drinks to weekends would be safer.\""}]'::jsonb, '["b"]', 'Clients with cirrhosis must avoid alcohol completely because further hepatocyte damage accelerates cirrhosis. Any amount or type of alcohol is unsafe.'),
  ('cirrhosis', 41, 'A client with end-stage cirrhosis asks whether any treatment can cure the disease. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A TIPS procedure will cure the cirrhosis.\""}, {"id": "b", "text": "\"Lactulose will reverse the liver scarring.\""}, {"id": "c", "text": "\"A liver transplant is the only definitive cure.\""}, {"id": "d", "text": "\"Propranolol will heal the damaged liver.\""}]'::jsonb, '["c"]', 'Liver transplant is the only definitive cure for end-stage cirrhosis. TIPS reduces portal pressure and prevents variceal bleeding but does not cure the disease.'),
  ('cirrhosis', 42, 'The nurse is reviewing the nutrition plan for a client with cirrhosis. Which supplements should the nurse expect to be included?', '[{"id": "a", "text": "Vitamin C and calcium"}, {"id": "b", "text": "Potassium and magnesium"}, {"id": "c", "text": "Sodium chloride tablets"}, {"id": "d", "text": "Vitamins A, D, E, K, B12, and iron"}]'::jsonb, '["d"]', 'Nutrition in cirrhosis includes vitamins A, D, E, K, B12, and iron. Sodium chloride tablets conflict with the low sodium diet.'),
  ('cirrhosis', 43, 'A client with cirrhosis asks why the provider carefully reviewed every medication on the home list. Which response by the nurse is best?', '[{"id": "a", "text": "\"Your liver normally detoxifies drugs, so extra caution is needed.\""}, {"id": "b", "text": "\"Most medications cause fluid to collect in your abdomen.\""}, {"id": "c", "text": "\"Your kidneys can no longer absorb any medications at all.\""}, {"id": "d", "text": "\"Medications are reviewed only before a liver transplant.\""}]'::jsonb, '["a"]', 'The liver detoxifies drugs and toxins, and caution is needed with all medications metabolized by the liver in cirrhosis. The other statements are not supported.'),
  ('cirrhosis', 44, 'A client with cirrhosis asks why fluid is collecting in the abdomen and legs. The nurse explains that the damaged liver cannot produce enough of which substance?', '[{"id": "a", "text": "Bilirubin"}, {"id": "b", "text": "Albumin"}, {"id": "c", "text": "Ammonia"}, {"id": "d", "text": "Estrogen"}]'::jsonb, '["b"]', 'The liver produces albumin for fluid balance, and decreased albumin causes ascites and edema. Bilirubin and ammonia increase in cirrhosis rather than being underproduced.'),
  ('cirrhosis', 45, 'A client with cirrhosis asks the nurse, "What are esophageal varices?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They are ulcers in the lining of your stomach.\""}, {"id": "b", "text": "\"They are small tears caused by forceful vomiting.\""}, {"id": "c", "text": "\"They are dilated veins in your esophagus from high portal pressure.\""}, {"id": "d", "text": "\"They are growths that narrow your esophagus.\""}]'::jsonb, '["c"]', 'Esophageal varices are dilated veins in the esophagus due to portal hypertension, and they can rupture. They are not ulcers, tears, or growths.'),
  ('cirrhosis', 46, 'The nurse is assessing a client with cirrhosis. Which new finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Mild redness of both palms"}, {"id": "b", "text": "Spider angiomas on the chest"}, {"id": "c", "text": "Long-standing breast enlargement"}, {"id": "d", "text": "New confusion and hand-flapping tremor"}]'::jsonb, '["d"]', 'New confusion with asterixis signals hepatic encephalopathy, and the nurse must watch for confusion in cirrhosis. Palmar erythema, spider angiomas, and gynecomastia are expected chronic signs.'),
  ('cirrhosis', 47, 'The nurse is admitting a client with cirrhosis. Which set of assessment findings should the nurse expect?', '[{"id": "a", "text": "Jaundiced sclera and loss of appetite"}, {"id": "b", "text": "Elevated platelets and high WBCs"}, {"id": "c", "text": "Elevated serum albumin and no edema"}, {"id": "d", "text": "Low serum ammonia and low bilirubin"}]'::jsonb, '["a"]', 'Jaundice and loss of appetite are signs of cirrhosis. Platelets, WBCs, and albumin are decreased, and ammonia and bilirubin are increased.'),
  ('cirrhosis', 48, 'A client with cirrhosis states, "My vomit looked like coffee grounds this morning." Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Hematochezia"}, {"id": "b", "text": "Hematemesis"}, {"id": "c", "text": "Melena"}, {"id": "d", "text": "Asterixis"}]'::jsonb, '["b"]', 'Hematemesis is vomiting bright red or coffee-ground blood. Melena refers to black, tarry stools, and hematochezia is bright red blood in the stool.'),
  ('cirrhosis', 49, 'A client with cirrhosis has developed portal hypertension. Which group of complications results directly from the increased portal pressure?', '[{"id": "a", "text": "Wernicke encephalopathy and gynecomastia"}, {"id": "b", "text": "Pruritus and jaundice"}, {"id": "c", "text": "Varices, splenomegaly, and ascites"}, {"id": "d", "text": "Hepatorenal syndrome and pruritus"}]'::jsonb, '["c"]', 'Increased portal pressure leads to esophageal and gastric varices, splenomegaly, and ascites. Wernicke encephalopathy results from thiamine deficiency and gynecomastia from increased estrogen.'),
  ('cirrhosis', 50, 'A client with cirrhosis has no history of alcohol use, viral hepatitis, or bile duct disease. Testing shows the client''s immune system is attacking the liver cells. Which cause of cirrhosis does this describe?', '[{"id": "a", "text": "Non-alcoholic fatty liver disease"}, {"id": "b", "text": "Bile duct disorder"}, {"id": "c", "text": "Viral hepatitis"}, {"id": "d", "text": "Autoimmune hepatitis"}]'::jsonb, '["d"]', 'In autoimmune hepatitis the immune system attacks liver cells, leading to cirrhosis. NAFLD is linked to obesity and diabetes rather than an immune attack.'),
  ('portal_vein', 1, 'The nurse is teaching a client about liver circulation. Which statement about the liver''s blood supply is accurate?', '[{"id": "a", "text": "It receives blood from both the hepatic artery and portal vein."}, {"id": "b", "text": "It receives all of its blood from the hepatic artery alone."}, {"id": "c", "text": "It sends blood out of the liver through the portal vein."}, {"id": "d", "text": "It receives all of its blood from the portal vein alone."}]'::jsonb, '["a"]', 'The liver has a dual blood supply, entering via the hepatic artery and portal vein, and blood exits via the hepatic veins. The portal vein brings blood in rather than carrying it out.'),
  ('portal_vein', 2, 'A nursing student asks how blood in the portal vein differs from arterial blood. How should the nurse describe portal vein blood?', '[{"id": "a", "text": "Oxygen-rich and nutrient-poor"}, {"id": "b", "text": "Nutrient-rich and oxygen-poor"}, {"id": "c", "text": "Oxygen-rich and nutrient-rich"}, {"id": "d", "text": "Oxygen-poor and nutrient-poor"}]'::jsonb, '["b"]', 'Portal vein blood is nutrient-rich and oxygen-poor. Oxygen-rich, nutrient-poor blood describes the hepatic artery.'),
  ('portal_vein', 3, 'The nurse is reviewing liver circulation with a nursing student. Which statement by the student about the hepatic artery requires correction?', '[{"id": "a", "text": "\"It carries oxygen-rich blood to the liver.\""}, {"id": "b", "text": "\"It is a branch of the celiac artery.\""}, {"id": "c", "text": "\"It carries nutrient-rich blood from the intestines.\""}, {"id": "d", "text": "\"It is one of two vessels supplying the liver.\""}]'::jsonb, '["c"]', 'The hepatic artery carries oxygen-rich, nutrient-poor blood; nutrient-rich blood from the GI organs arrives through the portal vein. The other statements are accurate.'),
  ('portal_vein', 4, 'The nurse is reviewing abdominal arterial anatomy. From which vessel does the hepatic artery branch?', '[{"id": "a", "text": "Superior mesenteric artery"}, {"id": "b", "text": "Inferior mesenteric artery"}, {"id": "c", "text": "Portal vein"}, {"id": "d", "text": "Celiac artery"}]'::jsonb, '["d"]', 'The hepatic artery is a branch of the celiac artery. The superior mesenteric artery supplies the pancreas, small intestines, and part of the colon.'),
  ('portal_vein', 5, 'Venous blood from which organs drains into the portal vein before reaching the liver?', '[{"id": "a", "text": "GI organs, pancreas, and spleen"}, {"id": "b", "text": "Heart, lungs, and aorta"}, {"id": "c", "text": "Kidneys, ureters, and bladder"}, {"id": "d", "text": "Brain, spinal cord, and nerves"}]'::jsonb, '["a"]', 'The portal vein drains the GI organs, pancreas, and spleen, carrying nutrient-rich, oxygen-poor blood to the liver. The other organ groups do not drain into the portal vein.'),
  ('portal_vein', 6, 'The nurse compares the blood flow delivered to the liver by its two incoming vessels. Which statement is accurate?', '[{"id": "a", "text": "The hepatic artery carries the larger flow."}, {"id": "b", "text": "The portal vein carries the larger flow."}, {"id": "c", "text": "Both vessels carry identical flow volumes."}, {"id": "d", "text": "The hepatic veins carry the larger inflow."}]'::jsonb, '["b"]', 'Portal vein flow is about 1000–1300 mL/min, compared with 300–500 mL/min in the hepatic artery. The hepatic veins carry blood out of the liver, not into it.'),
  ('portal_vein', 7, 'A client has just finished eating a large meal. The majority of the blood now entering the client''s liver arrives through which vessel?', '[{"id": "a", "text": "Hepatic artery"}, {"id": "b", "text": "Inferior vena cava"}, {"id": "c", "text": "Portal vein"}, {"id": "d", "text": "Hepatic veins"}]'::jsonb, '["c"]', 'After a meal, most of the liver''s blood comes from the portal vein. The hepatic veins and inferior vena cava carry blood away from the liver.'),
  ('portal_vein', 8, 'Which sequence correctly describes the path of venous blood leaving the GI tract?', '[{"id": "a", "text": "GI organs → hepatic veins → sinusoids → portal vein"}, {"id": "b", "text": "GI organs → vena cava → portal vein → sinusoids"}, {"id": "c", "text": "GI organs → sinusoids → portal vein → hepatic veins"}, {"id": "d", "text": "GI organs → portal vein → sinusoids → hepatic veins"}]'::jsonb, '["d"]', 'GI venous blood converges into the portal vein, enters the liver sinusoids, and exits via the hepatic veins to the inferior vena cava. Blood reaches the sinusoids only after passing through the portal vein.'),
  ('portal_vein', 9, 'A nursing student asks how blood leaves the liver. Which response by the nurse is accurate?', '[{"id": "a", "text": "Through the hepatic veins into the inferior vena cava"}, {"id": "b", "text": "Through the portal vein directly back to the heart"}, {"id": "c", "text": "Through the hepatic artery into the abdominal aorta"}, {"id": "d", "text": "Through the superior mesenteric artery to the colon"}]'::jsonb, '["a"]', 'Blood exits the liver via the hepatic veins into the inferior vena cava and back to the heart. The portal vein and hepatic artery are the two routes by which blood enters the liver.'),
  ('portal_vein', 10, 'The nurse explains the role of the liver sinusoids. Which function of the sinusoids should the nurse include?', '[{"id": "a", "text": "Adding oxygen to portal blood"}, {"id": "b", "text": "Filtering bacteria from blood"}, {"id": "c", "text": "Pumping blood to the spleen"}, {"id": "d", "text": "Producing blood in the colon"}]'::jsonb, '["b"]', 'Portal vein and hepatic artery blood enters the liver sinusoids, which filter bacteria. The sinusoids do not pump blood or add oxygen.'),
  ('portal_vein', 11, 'The nurse is reviewing the abdominal arteries. Which structures are supplied by the superior mesenteric artery?', '[{"id": "a", "text": "Only part of the colon"}, {"id": "b", "text": "Hepatic artery, spleen, and stomach"}, {"id": "c", "text": "Pancreas, small intestines, and part of colon"}, {"id": "d", "text": "Hepatic veins and inferior vena cava"}]'::jsonb, '["c"]', 'The superior mesenteric artery supplies the pancreas, small intestines, and part of the colon. The hepatic artery, spleen, and stomach are supplied by the celiac artery.'),
  ('portal_vein', 12, 'Which structures receive blood from the celiac artery?', '[{"id": "a", "text": "Pancreas, small intestines, and part of colon"}, {"id": "b", "text": "Only part of the colon"}, {"id": "c", "text": "Hepatic veins and inferior vena cava"}, {"id": "d", "text": "Hepatic artery, spleen, and stomach"}]'::jsonb, '["d"]', 'The celiac artery branches to the hepatic artery, spleen, and stomach. The pancreas, small intestines, and part of the colon are supplied by the superior mesenteric artery.'),
  ('portal_vein', 13, 'The nurse is reviewing the branches of the abdominal aorta. Which area is supplied by the inferior mesenteric artery?', '[{"id": "a", "text": "Part of the colon"}, {"id": "b", "text": "The stomach and spleen"}, {"id": "c", "text": "The small intestines"}, {"id": "d", "text": "The hepatic artery"}]'::jsonb, '["a"]', 'The inferior mesenteric artery supplies part of the colon. The stomach and spleen are supplied through the celiac artery, and the small intestines through the superior mesenteric artery.'),
  ('portal_vein', 14, 'A nursing student asks how the healthy portal system functions. How should the nurse describe the normal portal system?', '[{"id": "a", "text": "Low volume, high pressure"}, {"id": "b", "text": "High volume, low pressure"}, {"id": "c", "text": "Low volume, low pressure"}, {"id": "d", "text": "High volume, high pressure"}]'::jsonb, '["b"]', 'The portal system is normally a high-volume, low-pressure system. High pressure in the portal system indicates portal hypertension.'),
  ('portal_vein', 15, 'A client with cirrhosis has an incoming portal pressure measured at 18 mmHg. How should the nurse interpret this value?', '[{"id": "a", "text": "Within the normal range"}, {"id": "b", "text": "Below the normal range"}, {"id": "c", "text": "Consistent with portal hypertension"}, {"id": "d", "text": "An expected change after a meal"}]'::jsonb, '["c"]', 'Normal incoming portal pressure is about 9 mmHg, and in portal hypertension it rises to 15–20 mmHg, so 18 mmHg indicates portal hypertension. It is well above, not within or below, normal.'),
  ('portal_vein', 16, 'Which incoming portal pressure reading should the nurse recognize as normal?', '[{"id": "a", "text": "15 mmHg"}, {"id": "b", "text": "18 mmHg"}, {"id": "c", "text": "20 mmHg"}, {"id": "d", "text": "9 mmHg"}]'::jsonb, '["d"]', 'Normal incoming portal pressure is about 9 mmHg. Readings of 15–20 mmHg are seen with portal hypertension.'),
  ('portal_vein', 17, 'A client with alcohol-related cirrhosis asks why the pressure in the portal vein is high. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Scarred sinusoids increase resistance to blood flow.\""}, {"id": "b", "text": "\"The hepatic artery is pumping too much blood in.\""}, {"id": "c", "text": "\"Your spleen has shrunk and pushed blood forward.\""}, {"id": "d", "text": "\"Your blood is carrying too much oxygen to the liver.\""}]'::jsonb, '["a"]', 'Liver damage creates fibrotic sinusoids, which increase resistance and raise portal pressure. The spleen enlarges in portal hypertension rather than shrinking.'),
  ('portal_vein', 18, 'The nurse is reviewing the histories of four clients. Which client is at greatest risk for developing portal hypertension?', '[{"id": "a", "text": "A client with an appendectomy last year"}, {"id": "b", "text": "A client with long-term alcoholism"}, {"id": "c", "text": "A client with well-controlled asthma"}, {"id": "d", "text": "A client with a recent knee replacement"}]'::jsonb, '["b"]', 'Liver damage from alcoholism, hepatitis, or cirrhosis leads to fibrotic sinusoids and portal hypertension. The other histories do not involve liver damage.'),
  ('portal_vein', 19, 'A client with portal hypertension asks how esophageal varices form. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Stomach acid wears away the lining of the esophagus.\""}, {"id": "b", "text": "\"Low platelets cause the veins in the esophagus to swell.\""}, {"id": "c", "text": "\"Backed-up blood dilates collateral veins in the esophagus.\""}, {"id": "d", "text": "\"Ammonia irritates the esophagus and causes swollen veins.\""}]'::jsonb, '["c"]', 'In portal hypertension, blood backs up and dilates collateral veins in the esophagus, forming varices. Low platelets result from splenomegaly and do not cause varices.'),
  ('portal_vein', 20, 'The nurse is caring for a client with portal hypertension. Which finding indicates a life-threatening complication?', '[{"id": "a", "text": "Visible veins around the navel"}, {"id": "b", "text": "Mild abdominal distention"}, {"id": "c", "text": "Enlarged spleen on palpation"}, {"id": "d", "text": "Vomiting of blood"}]'::jsonb, '["d"]', 'Hematemesis from esophageal varices is a life-threatening bleed. Visible periumbilical veins (caput medusae) are a sign of portal hypertension but not an emergency.'),
  ('portal_vein', 21, 'A client with portal hypertension begins vomiting large amounts of blood. Which action should the nurse take first?', '[{"id": "a", "text": "Maintain the client''s airway"}, {"id": "b", "text": "Establish IV access"}, {"id": "c", "text": "Administer octreotide"}, {"id": "d", "text": "Prepare for endoscopy"}]'::jsonb, '["a"]', 'In a variceal bleed the airway is the first priority, followed by IV access, octreotide, and emergent endoscopy. IV access is important but comes after the airway.'),
  ('portal_vein', 22, 'A client with an esophageal variceal bleed has a secure, patent airway. Which action should the nurse take next?', '[{"id": "a", "text": "Prepare for emergent endoscopy"}, {"id": "b", "text": "Establish IV access"}, {"id": "c", "text": "Measure abdominal girth"}, {"id": "d", "text": "Administer lactulose"}]'::jsonb, '["b"]', 'After the airway, IV access is the next priority in a variceal bleed, followed by transfusion, octreotide/vasopressin, and emergent endoscopy. Endoscopy comes after these steps.'),
  ('portal_vein', 23, 'A client is admitted with an actively bleeding esophageal varix. Which medication should the nurse anticipate administering for the bleed?', '[{"id": "a", "text": "Lactulose"}, {"id": "b", "text": "Furosemide"}, {"id": "c", "text": "Octreotide"}, {"id": "d", "text": "Acetaminophen"}]'::jsonb, '["c"]', 'Octreotide or vasopressin is part of emergency management of a variceal bleed. Lactulose lowers ammonia for hepatic encephalopathy and does not treat bleeding.'),
  ('portal_vein', 24, 'The nurse is planning emergency care for a client with an esophageal variceal bleed. Which sequence of interventions is correct?', '[{"id": "a", "text": "IV access, airway, endoscopy, octreotide"}, {"id": "b", "text": "Endoscopy, octreotide, airway, IV access"}, {"id": "c", "text": "Octreotide, IV access, endoscopy, airway"}, {"id": "d", "text": "Airway, IV access, octreotide, endoscopy"}]'::jsonb, '["d"]', 'For a variceal bleed the airway comes first, then IV access and octreotide, then emergent endoscopy. Placing IV access before the airway reverses the first priority.'),
  ('portal_vein', 25, 'A client with portal hypertension and a low serum albumin level develops ascites. Which explanation for the ascites is accurate?', '[{"id": "a", "text": "High portal pressure and low albumin let fluid leak into the abdomen."}, {"id": "b", "text": "Low portal pressure and high albumin pull fluid into the abdomen."}, {"id": "c", "text": "Bleeding varices fill the abdomen with blood instead of fluid."}, {"id": "d", "text": "An enlarged spleen releases stored fluid into the abdomen."}]'::jsonb, '["a"]', 'Ascites results from increased portal pressure plus decreased albumin, causing fluid to leak into the peritoneum. Portal pressure is high and albumin is low, not the reverse.'),
  ('portal_vein', 26, 'The nurse is assessing a client with portal hypertension who has developed ascites. Which findings should the nurse expect?', '[{"id": "a", "text": "Flapping tremor of the hands"}, {"id": "b", "text": "Distended abdomen with a fluid wave"}, {"id": "c", "text": "Vomiting of bright red blood"}, {"id": "d", "text": "Confusion with musty breath"}]'::jsonb, '["b"]', 'Ascites presents as a distended abdomen with a fluid wave. A flapping tremor (asterixis) indicates hepatic encephalopathy.'),
  ('portal_vein', 27, 'The nurse reviews the laboratory results of a client with portal hypertension. Which result contributes to the development of ascites?', '[{"id": "a", "text": "Increased serum albumin"}, {"id": "b", "text": "Increased platelet count"}, {"id": "c", "text": "Decreased serum albumin"}, {"id": "d", "text": "Decreased serum ammonia"}]'::jsonb, '["c"]', 'Decreased albumin, combined with increased portal pressure, allows fluid to leak into the peritoneum. Increased albumin would not contribute to ascites.'),
  ('portal_vein', 28, 'A client with portal hypertension has an enlarged spleen and a low platelet count. The client asks why the spleen is enlarged. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Alcohol has caused the spleen to make extra cells.\""}, {"id": "b", "text": "\"Fluid from your abdomen has seeped into the spleen.\""}, {"id": "c", "text": "\"Lactulose therapy has caused the spleen to swell.\""}, {"id": "d", "text": "\"Blood is backing up into the spleen and enlarging it.\""}]'::jsonb, '["d"]', 'In portal hypertension, blood backs into the spleen, causing enlargement and decreased platelets. Fluid leaking into the peritoneum is the mechanism of ascites, not splenomegaly.'),
  ('portal_vein', 29, 'A client with portal hypertension has splenomegaly. For which complication should the nurse closely monitor this client?', '[{"id": "a", "text": "Bleeding"}, {"id": "b", "text": "Blood clots"}, {"id": "c", "text": "High blood pressure"}, {"id": "d", "text": "Low blood glucose"}]'::jsonb, '["a"]', 'Splenomegaly decreases platelets (thrombocytopenia), increasing bleeding risk. Low platelets raise the risk of bleeding, not clotting.'),
  ('portal_vein', 30, 'A client with splenomegaly from portal hypertension has a low platelet count. Which term should the nurse use to document this laboratory finding?', '[{"id": "a", "text": "Thrombocytosis"}, {"id": "b", "text": "Thrombocytopenia"}, {"id": "c", "text": "Asterixis"}, {"id": "d", "text": "Hematemesis"}]'::jsonb, '["b"]', 'Decreased platelets are called thrombocytopenia, a consequence of splenomegaly. Asterixis is a flapping tremor and hematemesis is vomiting blood.'),
  ('portal_vein', 31, 'While assessing a client with portal hypertension, the nurse observes engorged veins radiating around the umbilicus. The nurse documents this finding as which condition?', '[{"id": "a", "text": "Ascites"}, {"id": "b", "text": "Splenomegaly"}, {"id": "c", "text": "Caput medusae"}, {"id": "d", "text": "Esophageal varices"}]'::jsonb, '["c"]', 'Caput medusae is dilated periumbilical veins visible on the abdomen. Ascites presents as a distended abdomen with a fluid wave instead.'),
  ('portal_vein', 32, 'A client with portal hypertension asks why large veins have appeared around the belly button. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Low platelets are causing bruises around your navel.\""}, {"id": "b", "text": "\"Fluid leaking into your abdomen is stretching the skin.\""}, {"id": "c", "text": "\"Toxins that bypass your liver are irritating the skin.\""}, {"id": "d", "text": "\"High portal pressure has dilated the veins near your navel.\""}]'::jsonb, '["d"]', 'Caput medusae is a consequence of portal hypertension in which periumbilical veins become dilated and visible. Fluid leaking into the peritoneum describes ascites.'),
  ('portal_vein', 33, 'A client with portal hypertension becomes confused. The family asks why this is happening. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Toxins are bypassing the liver''s filtering and affecting the brain.\""}, {"id": "b", "text": "\"Blood is backing up into the spleen and enlarging it.\""}, {"id": "c", "text": "\"Low albumin is causing fluid to leak into the abdomen.\""}, {"id": "d", "text": "\"Collateral veins in the esophagus have become dilated.\""}]'::jsonb, '["a"]', 'Hepatic encephalopathy occurs when toxins bypass liver filtration, causing confusion and asterixis. Blood backing into the spleen explains splenomegaly, not confusion.'),
  ('portal_vein', 34, 'A client with portal hypertension is newly disoriented to time and place. The nurse suspects which complication?', '[{"id": "a", "text": "Ascites"}, {"id": "b", "text": "Hepatic encephalopathy"}, {"id": "c", "text": "Splenomegaly"}, {"id": "d", "text": "Caput medusae"}]'::jsonb, '["b"]', 'Confusion is a clinical sign of hepatic encephalopathy, which occurs when toxins bypass liver filtration. Ascites presents as abdominal distention with a fluid wave.'),
  ('portal_vein', 35, 'A client with portal hypertension is diagnosed with hepatic encephalopathy. Which medication should the nurse anticipate?', '[{"id": "a", "text": "Octreotide"}, {"id": "b", "text": "Vasopressin"}, {"id": "c", "text": "Lactulose"}, {"id": "d", "text": "Packed red blood cells"}]'::jsonb, '["c"]', 'Hepatic encephalopathy is treated with lactulose, which lowers ammonia. Octreotide, vasopressin, and blood transfusion are used for a variceal bleed.'),
  ('portal_vein', 36, 'A client with hepatic encephalopathy has been receiving lactulose. Which finding indicates that the treatment is effective?', '[{"id": "a", "text": "Platelet count has increased"}, {"id": "b", "text": "Fluid wave is no longer present"}, {"id": "c", "text": "Periumbilical veins are smaller"}, {"id": "d", "text": "Confusion has decreased"}]'::jsonb, '["d"]', 'Lactulose lowers ammonia to treat hepatic encephalopathy, whose signs include confusion and asterixis, so decreased confusion shows effectiveness. A fluid wave relates to ascites, not encephalopathy.'),
  ('portal_vein', 37, 'The nurse teaches a client with portal hypertension about lactulose. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Lactulose will stop my varices from bleeding.\""}, {"id": "b", "text": "\"Lactulose helps lower my ammonia level.\""}, {"id": "c", "text": "\"This medicine treats my confusion episodes.\""}, {"id": "d", "text": "\"Confusion happens when toxins bypass my liver.\""}]'::jsonb, '["a"]', 'Lactulose lowers ammonia to treat hepatic encephalopathy; a variceal bleed is managed with airway, IV access, octreotide/vasopressin, and emergent endoscopy. The other statements are accurate.'),
  ('portal_vein', 38, 'A client with cirrhosis has a distended abdomen, a low platelet count, and visible veins around the umbilicus. These findings are most directly caused by which underlying problem?', '[{"id": "a", "text": "Hepatic artery blockage"}, {"id": "b", "text": "Portal hypertension"}, {"id": "c", "text": "Excess oxygen in portal blood"}, {"id": "d", "text": "Low portal vein pressure"}]'::jsonb, '["b"]', 'Portal hypertension causes ascites, splenomegaly with low platelets, and caput medusae. Low portal pressure is the normal state, not the cause of these complications.'),
  ('portal_vein', 39, 'A client asks the nurse which vessel supplies the liver with oxygen-rich blood. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The portal vein brings oxygen-rich blood to the liver.\""}, {"id": "b", "text": "\"The hepatic veins bring oxygen-rich blood to the liver.\""}, {"id": "c", "text": "\"The hepatic artery brings oxygen-rich blood to the liver.\""}, {"id": "d", "text": "\"The vena cava brings oxygen-rich blood to the liver.\""}]'::jsonb, '["c"]', 'The hepatic artery carries oxygen-rich, nutrient-poor blood, while the portal vein carries nutrient-rich, oxygen-poor blood. The hepatic veins carry blood out of the liver.'),
  ('portal_vein', 40, 'A nursing student asks why blood in the portal vein is low in oxygen. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It comes straight from the abdominal aorta.\""}, {"id": "b", "text": "\"It has mixed with hepatic artery blood first.\""}, {"id": "c", "text": "\"It has already left the liver sinusoids.\""}, {"id": "d", "text": "\"It has already passed through the GI organs.\""}]'::jsonb, '["d"]', 'GI organs drain deoxygenated, nutrient-rich venous blood that converges into the portal vein. Portal blood mixes with hepatic artery blood only after entering the liver sinusoids.'),
  ('portal_vein', 41, 'After a client eats, nutrients absorbed from the intestines first reach the liver through which vessel?', '[{"id": "a", "text": "Portal vein"}, {"id": "b", "text": "Hepatic artery"}, {"id": "c", "text": "Hepatic veins"}, {"id": "d", "text": "Inferior vena cava"}]'::jsonb, '["a"]', 'The portal vein carries nutrient-rich, oxygen-poor blood from the GI organs to the liver. The hepatic artery carries nutrient-poor blood.'),
  ('portal_vein', 42, 'The nurse is caring for four clients with portal hypertension. Which client should the nurse see first?', '[{"id": "a", "text": "The client with a fluid wave on assessment"}, {"id": "b", "text": "The client who is vomiting blood"}, {"id": "c", "text": "The client with visible periumbilical veins"}, {"id": "d", "text": "The client with a mildly enlarged spleen"}]'::jsonb, '["b"]', 'An esophageal variceal bleed, shown by vomiting blood, is an emergency. Ascites, caput medusae, and splenomegaly are consequences of portal hypertension but not immediately life-threatening.'),
  ('portal_vein', 43, 'A client''s liver disease progresses to portal hypertension. Which change in the portal circulation should the nurse expect?', '[{"id": "a", "text": "Portal pressure falls below normal"}, {"id": "b", "text": "Resistance in the sinusoids decreases"}, {"id": "c", "text": "Resistance rises and portal pressure increases"}, {"id": "d", "text": "Portal blood becomes oxygen-rich"}]'::jsonb, '["c"]', 'In portal hypertension, fibrotic sinusoids increase resistance and portal pressure rises to 15–20 mmHg. Resistance increases, not decreases.'),
  ('portal_vein', 44, 'The nurse is explaining liver circulation to a client. In which structure do blood from the portal vein and blood from the hepatic artery come together?', '[{"id": "a", "text": "Hepatic veins"}, {"id": "b", "text": "Inferior vena cava"}, {"id": "c", "text": "Celiac artery"}, {"id": "d", "text": "Liver sinusoids"}]'::jsonb, '["d"]', 'Portal vein and hepatic artery blood enters the liver sinusoids. Blood then exits via the hepatic veins to the inferior vena cava.'),
  ('portal_vein', 45, 'The nurse is reviewing liver circulation with a nursing student. Which statement by the student requires correction?', '[{"id": "a", "text": "\"The portal vein carries blood out of the liver to the heart.\""}, {"id": "b", "text": "\"The hepatic veins drain into the inferior vena cava.\""}, {"id": "c", "text": "\"The liver receives blood from two incoming vessels.\""}, {"id": "d", "text": "\"The portal vein drains blood from the spleen.\""}]'::jsonb, '["a"]', 'Blood exits the liver via the hepatic veins to the inferior vena cava; the portal vein brings blood into the liver. The other statements are accurate.'),
  ('portal_vein', 46, 'A client''s portal pressure has risen from 9 mmHg to 17 mmHg as liver disease worsens. For which complication should the nurse monitor?', '[{"id": "a", "text": "Rising platelet count"}, {"id": "b", "text": "Vomiting blood from varices"}, {"id": "c", "text": "Shrinking abdominal girth"}, {"id": "d", "text": "Rising serum albumin"}]'::jsonb, '["b"]', 'A rise to the 15–20 mmHg range indicates portal hypertension, which leads to varices, ascites, splenomegaly, and encephalopathy. Platelets decrease, not increase, with splenomegaly.'),
  ('portal_vein', 47, 'The nurse is assessing a client with portal hypertension. Which finding should the nurse expect?', '[{"id": "a", "text": "Decreased abdominal girth"}, {"id": "b", "text": "Elevated platelet count"}, {"id": "c", "text": "Engorged periumbilical veins"}, {"id": "d", "text": "Below-normal portal pressure"}]'::jsonb, '["c"]', 'Caput medusae, visible engorged veins around the navel, is a consequence of portal hypertension. Platelets decrease because of splenomegaly.'),
  ('portal_vein', 48, 'A client with an esophageal variceal bleed has a secure airway and IV access. Which additional intervention should the nurse anticipate?', '[{"id": "a", "text": "Delaying endoscopy for 48 hours"}, {"id": "b", "text": "Encouraging oral fluid intake"}, {"id": "c", "text": "Withholding octreotide"}, {"id": "d", "text": "Preparing for blood transfusion"}]'::jsonb, '["d"]', 'Variceal bleed priorities include airway, IV access, blood transfusion, octreotide/vasopressin, and emergent endoscopy. Endoscopy is emergent, not delayed.'),
  ('portal_vein', 49, 'The nurse assesses a client with portal hypertension. Which finding suggests hepatic encephalopathy rather than another complication of portal hypertension?', '[{"id": "a", "text": "Vomiting of blood"}, {"id": "b", "text": "Flapping tremor of the hands"}, {"id": "c", "text": "Fluid wave in the abdomen"}, {"id": "d", "text": "Engorged veins around the navel"}]'::jsonb, '["b"]', 'Asterixis, a flapping tremor, is a sign of hepatic encephalopathy. Vomiting blood indicates esophageal varices, a fluid wave indicates ascites, and navel veins indicate caput medusae.'),
  ('portal_vein', 50, 'The nurse is reviewing normal liver blood flow with a nursing student. Which flow rate is typical of the hepatic artery?', '[{"id": "a", "text": "1000–1300 mL/min"}, {"id": "b", "text": "About 5 L/min"}, {"id": "c", "text": "300–500 mL/min"}, {"id": "d", "text": "Over 2000 mL/min"}]'::jsonb, '["c"]', 'Hepatic artery flow is 300–500 mL/min. A flow of 1000–1300 mL/min describes the portal vein, and about 5 L/min is the heart''s output through the aorta.'),
  ('celiac', 1, 'A client newly diagnosed with celiac disease asks the nurse, ''Is this just a food intolerance like my friend has?'' Which response by the nurse is most accurate?', '[{"id": "a", "text": "It is an autoimmune disease in which gluten triggers the immune system."}, {"id": "b", "text": "It is a food intolerance caused by a shortage of a digestive enzyme."}, {"id": "c", "text": "It is an infection of the small intestine caused by contaminated grain."}, {"id": "d", "text": "It is a temporary sensitivity that fades once the bowel is rested."}]'::jsonb, '["a"]', 'Celiac disease is an autoimmune disease triggered by gluten, not simply a food intolerance. Describing it as an enzyme-related intolerance misrepresents the immune-mediated damage to the intestinal villi.'),
  ('celiac', 2, 'A nursing student asks why a client with celiac disease develops malabsorption. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Gluten blocks the release of pancreatic enzymes needed to digest fat."}, {"id": "b", "text": "Immune damage flattens the intestinal villi and reduces absorptive surface."}, {"id": "c", "text": "Gluten inflames the colon and speeds stool through the large bowel."}, {"id": "d", "text": "Immune damage thickens the villi so nutrients are trapped in the wall."}]'::jsonb, '["b"]', 'Gluten intake causes immune-mediated damage that flattens the villi (villous atrophy), decreasing the absorptive surface area and causing malabsorption. The villi flatten rather than thicken, and the damage is in the small intestine.'),
  ('celiac', 3, 'The nurse provides teaching to a client with newly diagnosed celiac disease. Which statement by the client indicates understanding of the treatment?', '[{"id": "a", "text": "I can stop the special diet once my diarrhea goes away."}, {"id": "b", "text": "I only need to avoid gluten when my symptoms flare up."}, {"id": "c", "text": "I will need to follow a gluten-free diet for the rest of my life."}, {"id": "d", "text": "My medication will let me eat regular bread again soon."}]'::jsonb, '["c"]', 'The only treatment for celiac disease is a strict, lifelong gluten-free diet. Stopping the diet when symptoms resolve or avoiding gluten only during flares does not meet the requirement for lifelong avoidance.'),
  ('celiac', 4, 'A nurse is assessing a client with suspected celiac disease. Which description of the client''s stools is the nurse most likely to obtain?', '[{"id": "a", "text": "Black, tarry stools"}, {"id": "b", "text": "Hard, pellet-like stools"}, {"id": "c", "text": "Bright red, bloody stools"}, {"id": "d", "text": "Chronic pale, fatty stools"}]'::jsonb, '["d"]', 'Celiac disease causes chronic diarrhea that is often fatty and pale, along with steatorrhea. Hard, pellet-like stools do not reflect the chronic diarrhea expected with malabsorption.'),
  ('celiac', 5, 'A client with celiac disease shows the nurse an itchy, blistering rash on the forearms. The nurse recognizes this as which systemic manifestation of celiac disease?', '[{"id": "a", "text": "Psoriasis"}, {"id": "b", "text": "Dermatitis herpetiformis"}, {"id": "c", "text": "Herpes zoster"}, {"id": "d", "text": "Contact urticaria"}]'::jsonb, '["b"]', 'Dermatitis herpetiformis, an itchy blistering rash, is a systemic symptom of celiac disease. The other skin conditions are not manifestations of celiac disease.'),
  ('celiac', 6, 'A nurse reviews the laboratory results of a client with untreated celiac disease who reports fatigue. Which finding should the nurse expect?', '[{"id": "a", "text": "High hemoglobin and high iron"}, {"id": "b", "text": "Low hemoglobin and high iron"}, {"id": "c", "text": "Low hemoglobin and low iron"}, {"id": "d", "text": "High hemoglobin and low iron"}]'::jsonb, '["c"]', 'Villous atrophy causes malabsorption of iron, so iron-deficiency anemia with low hemoglobin and low iron is expected. A high iron level would be the reverse of the iron malabsorption that occurs.'),
  ('celiac', 7, 'A nurse in a pediatric clinic reviews the growth chart of a 6-year-old child with untreated celiac disease. Which finding is the nurse most likely to see?', '[{"id": "a", "text": "Weight above the expected range for age"}, {"id": "b", "text": "Height above the expected range for age"}, {"id": "c", "text": "Rapid weight gain since the last visit"}, {"id": "d", "text": "Height and weight below expected for age"}]'::jsonb, '["d"]', 'Delayed growth in children and weight loss are manifestations of celiac disease caused by malabsorption. Weight above the expected range or rapid weight gain is the opposite of what is expected.'),
  ('celiac', 8, 'A client with celiac disease reports aching bones and joints. The nurse explains that this symptom is most likely related to which problem?', '[{"id": "a", "text": "Decreased absorption of calcium"}, {"id": "b", "text": "Excess absorption of calcium"}, {"id": "c", "text": "Autoimmune attack on the joint lining"}, {"id": "d", "text": "Fluid loss from chronic diarrhea"}]'::jsonb, '["a"]', 'Bone and joint pain in celiac disease results from calcium malabsorption caused by damaged villi. Calcium absorption is decreased, not increased, and the immune attack targets the intestinal villi rather than the joints.'),
  ('celiac', 9, 'A client with untreated celiac disease has steatorrhea. The nurse anticipates malabsorption of which group of nutrients?', '[{"id": "a", "text": "Sodium and chloride"}, {"id": "b", "text": "Vitamin C and thiamine"}, {"id": "c", "text": "Vitamins A, D, E, and K"}, {"id": "d", "text": "Potassium and magnesium"}]'::jsonb, '["c"]', 'Villous atrophy results in malabsorption of the fat-soluble vitamins A, D, E, and K, along with iron, calcium, B12, and folate. The other groups are not among the nutrients identified as malabsorbed in celiac disease.'),
  ('celiac', 10, 'A client has had celiac disease for many years and has not followed a gluten-free diet. Because of reduced calcium and vitamin D absorption, the nurse should monitor for which complication?', '[{"id": "a", "text": "Kidney stones"}, {"id": "b", "text": "Hypercalcemia"}, {"id": "c", "text": "Gouty arthritis"}, {"id": "d", "text": "Osteoporosis"}]'::jsonb, '["d"]', 'Osteoporosis is a complication of untreated celiac disease caused by decreased calcium and vitamin D absorption. Hypercalcemia reflects the opposite direction of the actual calcium deficit.'),
  ('celiac', 11, 'A client with celiac disease continues to eat gluten despite teaching. The nurse explains that chronic intestinal inflammation increases the risk of which complication?', '[{"id": "a", "text": "Intestinal T-cell lymphoma"}, {"id": "b", "text": "Acute appendicitis"}, {"id": "c", "text": "Gastric ulcer disease"}, {"id": "d", "text": "Colonic diverticulitis"}]'::jsonb, '["a"]', 'Untreated celiac disease causes chronic inflammation that increases the risk of intestinal T-cell lymphoma. The other conditions are not listed complications of untreated celiac disease.'),
  ('celiac', 12, 'A client with untreated celiac disease reports new numbness and tingling in both feet. The nurse recognizes that this finding is associated with a deficiency of which nutrients?', '[{"id": "a", "text": "Vitamins A and K"}, {"id": "b", "text": "Vitamin B12 and folate"}, {"id": "c", "text": "Calcium and vitamin D"}, {"id": "d", "text": "Iron and vitamin E"}]'::jsonb, '["b"]', 'Neurologic complications such as peripheral neuropathy are caused by B12 and folate deficiency from malabsorption. Calcium and vitamin D deficiency is linked to osteoporosis rather than neuropathy.'),
  ('celiac', 13, 'A client with long-standing untreated celiac disease tells the nurse she has been unable to become pregnant. The nurse understands that infertility in celiac disease is related to which mechanism?', '[{"id": "a", "text": "Antibodies directly destroying the ovaries"}, {"id": "b", "text": "Iron overload from excess absorption"}, {"id": "c", "text": "Malnutrition and hormonal disruption"}, {"id": "d", "text": "Excess vitamin absorption in the bowel"}]'::jsonb, '["c"]', 'Infertility in untreated celiac disease results from malnutrition and hormonal disruption. Iron and vitamins are malabsorbed, so overload or excess absorption is the reverse of what occurs.'),
  ('celiac', 14, 'A client with celiac disease asks for help choosing a lunch from the hospital menu. Which selection is most appropriate?', '[{"id": "a", "text": "Turkey sandwich on wheat bread"}, {"id": "b", "text": "Spaghetti with meat sauce"}, {"id": "c", "text": "Barley and vegetable soup"}, {"id": "d", "text": "Grilled chicken with rice"}]'::jsonb, '["d"]', 'Plain meat and rice are gluten-free foods. Wheat bread, pasta, and barley contain gluten and must be avoided.'),
  ('celiac', 15, 'The nurse reviews diet teaching with a client who has celiac disease. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I can still have a beer with my friends on weekends."}, {"id": "b", "text": "I will choose rice or quinoa as my main grain."}, {"id": "c", "text": "I will read the label of every food product I buy."}, {"id": "d", "text": "I will use separate utensils when I cook my meals."}]'::jsonb, '["a"]', 'Beer is barley-based and contains gluten, so it must be avoided. Choosing rice or quinoa, reading labels, and preventing cross-contamination with separate utensils are all correct.'),
  ('celiac', 16, 'A client with celiac disease is planning to make a stir-fry at home. Which ingredient should the nurse advise the client to avoid?', '[{"id": "a", "text": "Steamed white rice"}, {"id": "b", "text": "Regular soy sauce"}, {"id": "c", "text": "Fresh mixed vegetables"}, {"id": "d", "text": "Plain chicken breast"}]'::jsonb, '["b"]', 'Soy sauce usually contains wheat and should be avoided. Rice, vegetables, and plain meat are safe gluten-free foods.'),
  ('celiac', 17, 'A client with celiac disease is shopping for bread products. Which item should the client avoid?', '[{"id": "a", "text": "Corn tortillas"}, {"id": "b", "text": "Plain rice cakes"}, {"id": "c", "text": "Rye bread"}, {"id": "d", "text": "Potato bread labeled certified gluten-free"}]'::jsonb, '["c"]', 'Rye contains gluten and is one of the grains to avoid (W.B.R.O.). Corn, rice, and certified gluten-free products are safe.'),
  ('celiac', 18, 'A client with celiac disease asks the nurse for a safe breakfast. Which option is most appropriate?', '[{"id": "a", "text": "Pancakes made with wheat flour"}, {"id": "b", "text": "Barley porridge with honey"}, {"id": "c", "text": "Wheat toast with butter"}, {"id": "d", "text": "Scrambled eggs with fresh fruit"}]'::jsonb, '["d"]', 'Plain eggs and fruits are gluten-free foods. Wheat flour, wheat toast, and barley contain gluten.'),
  ('celiac', 19, 'A client with celiac disease says, ''A small slice of regular birthday cake once in a while won''t hurt me.'' Which response by the nurse is best?', '[{"id": "a", "text": "Small amounts are fine as long as you have no symptoms afterward."}, {"id": "b", "text": "Even trace amounts of gluten can damage your intestine."}, {"id": "c", "text": "An occasional treat is acceptable once your villi have healed."}, {"id": "d", "text": "A small amount is safe if you take a vitamin supplement after."}]'::jsonb, '["b"]', 'Gluten avoidance must be strict and lifelong because even trace amounts can cause intestinal damage. Absence of symptoms or healed villi does not make occasional gluten safe.'),
  ('celiac', 20, 'The spouse of a client with celiac disease prepares the family''s meals. Which action by the spouse requires correction by the nurse?', '[{"id": "a", "text": "Washing the cutting board before preparing the client''s food"}, {"id": "b", "text": "Keeping a separate set of utensils for gluten-free cooking"}, {"id": "c", "text": "Cutting gluten-free bread with the knife just used on wheat bread"}, {"id": "d", "text": "Checking packaged foods for a certified gluten-free label"}]'::jsonb, '["c"]', 'Shared utensils and cooking surfaces create a cross-contamination risk, so using a knife just used on wheat bread is unsafe. Cleaning surfaces, using separate utensils, and checking labels are appropriate.'),
  ('celiac', 21, 'A client with celiac disease asks how to tell which packaged foods are safe to eat. Which instruction by the nurse is most appropriate?', '[{"id": "a", "text": "Assume foods labeled ''natural'' are free of gluten."}, {"id": "b", "text": "Check labels only on bread and pasta products."}, {"id": "c", "text": "Avoid only products with ''gluten'' in their name."}, {"id": "d", "text": "Read every food label carefully before buying."}]'::jsonb, '["d"]', 'Clients with celiac disease must read all food labels carefully. Gluten can be present in products such as soy sauce, so checking only bread and pasta or relying on product names is unsafe.'),
  ('celiac', 22, 'A nurse is planning care for a client newly diagnosed with celiac disease. Which referral is most important to include in the plan?', '[{"id": "a", "text": "Dietitian for education and meal planning"}, {"id": "b", "text": "Physical therapist for strength training"}, {"id": "c", "text": "Surgeon to evaluate for bowel resection"}, {"id": "d", "text": "Occupational therapist for home safety"}]'::jsonb, '["a"]', 'Clients with celiac disease should always be referred to a dietitian for education and meal planning because treatment is a strict gluten-free diet. Surgery is not part of treatment.'),
  ('celiac', 23, 'A client with celiac disease has documented nutritional deficiencies. Which supplements should the nurse anticipate the provider prescribing?', '[{"id": "a", "text": "Potassium and sodium bicarbonate"}, {"id": "b", "text": "Calcium with vitamin D, iron, and B vitamins"}, {"id": "c", "text": "Vitamin C and zinc lozenges"}, {"id": "d", "text": "Magnesium and sodium chloride tablets"}]'::jsonb, '["b"]', 'Clients with celiac disease are supplemented as needed with calcium plus vitamin D, iron, and B vitamins. The other combinations do not address the deficiencies caused by villous atrophy.'),
  ('celiac', 24, 'A client who started a strict gluten-free diet asks how long it will take for the intestine to heal. Which response by the nurse is accurate?', '[{"id": "a", "text": "The villi heal within 24 hours of the first gluten-free meal."}, {"id": "b", "text": "The villi cannot regenerate once they have been damaged."}, {"id": "c", "text": "The villi regenerate within months of a strict gluten-free diet."}, {"id": "d", "text": "The villi regenerate only after surgical repair of the bowel."}]'::jsonb, '["c"]', 'Symptoms resolve and villi regenerate within months of a strict gluten-free diet. Stating that villi cannot regenerate is incorrect, and healing does not occur within a single day.'),
  ('celiac', 25, 'A client asks which test is considered the gold standard for diagnosing celiac disease. The nurse should identify which test?', '[{"id": "a", "text": "Stool culture"}, {"id": "b", "text": "Abdominal x-ray"}, {"id": "c", "text": "Serum amylase level"}, {"id": "d", "text": "Small bowel biopsy"}]'::jsonb, '["d"]', 'Small bowel biopsy is the gold standard for confirming celiac disease. A stool culture, abdominal x-ray, and serum amylase are not used to confirm the diagnosis.'),
  ('celiac', 26, 'A client with chronic diarrhea and weight loss is being evaluated for celiac disease. Which blood tests should the nurse anticipate?', '[{"id": "a", "text": "Anti-TTG IgA and anti-endomysial IgA"}, {"id": "b", "text": "Serum amylase and serum lipase"}, {"id": "c", "text": "Serum ammonia and bilirubin"}, {"id": "d", "text": "Troponin and creatine kinase"}]'::jsonb, '["a"]', 'Serologic testing for celiac disease includes anti-TTG IgA and anti-endomysial IgA, followed by small bowel biopsy. The other tests are not part of the celiac diagnostic workup.'),
  ('celiac', 27, 'A client with celiac disease asks where in the digestive tract the damage from gluten occurs. The nurse should identify which structure?', '[{"id": "a", "text": "The lining of the stomach"}, {"id": "b", "text": "The villi of the small intestine"}, {"id": "c", "text": "The wall of the large intestine"}, {"id": "d", "text": "The lower esophageal sphincter"}]'::jsonb, '["b"]', 'When a person with celiac disease eats gluten, the immune system attacks the small intestinal villi. The stomach and colon are not the site of villous damage.'),
  ('celiac', 28, 'A nurse is assessing an adult client with untreated celiac disease. Which set of findings should the nurse expect?', '[{"id": "a", "text": "Weight gain with firm, formed stools"}, {"id": "b", "text": "Constipation with ribbon-like stools"}, {"id": "c", "text": "Weight loss with abdominal bloating"}, {"id": "d", "text": "High fever with bright red stools"}]'::jsonb, '["c"]', 'GI symptoms of celiac disease include bloating, abdominal pain, chronic diarrhea, and weight loss. Weight gain with formed stools and constipation are not expected findings.'),
  ('celiac', 29, 'A nurse is explaining the disease process of celiac disease to a client. Which sequence of events is correct?', '[{"id": "a", "text": "Villous atrophy, gluten intake, immune damage, malabsorption"}, {"id": "b", "text": "Malabsorption, immune damage, gluten intake, villous atrophy"}, {"id": "c", "text": "Immune damage, malabsorption, villous atrophy, gluten intake"}, {"id": "d", "text": "Gluten intake, immune damage, villous atrophy, malabsorption"}]'::jsonb, '["d"]', 'Gluten intake triggers immune-mediated damage to the villi, which flatten (villous atrophy), decreasing absorptive surface and causing malabsorption. Malabsorption is the end result, not the starting point.'),
  ('celiac', 30, 'A client with celiac disease has followed a strict gluten-free diet for several months. Which finding best indicates that treatment is effective?', '[{"id": "a", "text": "Resolution of diarrhea and bloating"}, {"id": "b", "text": "Continued unintentional weight loss"}, {"id": "c", "text": "Persistent pale, fatty stools"}, {"id": "d", "text": "Increasing fatigue during the day"}]'::jsonb, '["a"]', 'With a strict gluten-free diet, symptoms resolve and villi regenerate within months, so resolution of diarrhea and bloating shows effectiveness. Continued weight loss, fatty stools, and fatigue indicate ongoing malabsorption.'),
  ('celiac', 31, 'A client with celiac disease is diagnosed with anemia. The nurse explains that the anemia is most likely caused by which mechanism?', '[{"id": "a", "text": "Blood loss from bleeding gastric ulcers"}, {"id": "b", "text": "Malabsorption of iron, B12, and folate"}, {"id": "c", "text": "Excess fluid intake diluting the blood"}, {"id": "d", "text": "Gluten antibodies destroying red cells"}]'::jsonb, '["b"]', 'Anemia in celiac disease results from iron and/or B12/folate malabsorption due to villous damage. The immune attack is directed at the intestinal villi, not red blood cells.'),
  ('celiac', 32, 'A client with celiac disease wants a side dish for dinner. Which choice is most appropriate?', '[{"id": "a", "text": "Whole wheat crackers with cheese"}, {"id": "b", "text": "Rye toast with butter"}, {"id": "c", "text": "Barley salad with vegetables"}, {"id": "d", "text": "Baked potato with steamed broccoli"}]'::jsonb, '["d"]', 'Potatoes and vegetables are gluten-free. Wheat, rye, and barley all contain gluten and must be avoided.'),
  ('celiac', 33, 'The nurse reviews a client''s dinner selections after teaching about celiac disease. Which selection indicates a need for further teaching?', '[{"id": "a", "text": "Regular pasta with tomato sauce"}, {"id": "b", "text": "Quinoa bowl with roasted vegetables"}, {"id": "c", "text": "Grilled fish with steamed rice"}, {"id": "d", "text": "Corn tortillas with plain chicken"}]'::jsonb, '["a"]', 'Regular pasta is made from wheat, which contains gluten. Quinoa, rice, corn, vegetables, fish, and plain chicken are safe gluten-free choices.'),
  ('celiac', 34, 'A client with celiac disease wants to keep eating sandwiches. Which bread should the nurse recommend?', '[{"id": "a", "text": "Multigrain wheat bread"}, {"id": "b", "text": "Certified gluten-free bread"}, {"id": "c", "text": "Dark rye bread"}, {"id": "d", "text": "Bread made with barley flour"}]'::jsonb, '["b"]', 'Certified gluten-free products are safe for clients with celiac disease. Wheat, rye, and barley contain gluten.'),
  ('celiac', 35, 'A client with celiac disease is hospitalized. Which action by the unlicensed assistive personnel (UAP) requires the nurse to intervene?', '[{"id": "a", "text": "Checking that the meal tray is marked gluten-free"}, {"id": "b", "text": "Offering a wheat roll from another tray as a snack"}, {"id": "c", "text": "Bringing the client a cup of fresh fruit as a snack"}, {"id": "d", "text": "Reporting the client''s diarrhea episodes to the nurse"}]'::jsonb, '["b"]', 'Clients with celiac disease require strict gluten avoidance because even trace amounts can cause damage, so a wheat roll is unsafe. Checking for a gluten-free tray and offering fruit are appropriate.'),
  ('celiac', 36, 'A client''s serologic testing is positive for anti-TTG IgA antibodies. The nurse anticipates which test next to confirm the diagnosis of celiac disease?', '[{"id": "a", "text": "Abdominal ultrasound"}, {"id": "b", "text": "Upper GI barium swallow"}, {"id": "c", "text": "Small bowel biopsy"}, {"id": "d", "text": "Stool ova and parasites"}]'::jsonb, '["c"]', 'Celiac disease is confirmed by serologic testing plus small bowel biopsy, which is the gold standard. Imaging and stool studies do not confirm celiac disease.'),
  ('celiac', 37, 'A client with celiac disease asks why calcium and vitamin D supplements were prescribed. Which explanation by the nurse is correct?', '[{"id": "a", "text": "They help treat the itchy, blistering skin rash."}, {"id": "b", "text": "They reduce the risk of intestinal lymphoma."}, {"id": "c", "text": "They replace nutrients normally provided by gluten."}, {"id": "d", "text": "They help prevent bone loss from poor absorption."}]'::jsonb, '["d"]', 'Decreased calcium and vitamin D absorption in celiac disease leads to osteoporosis, so these supplements protect bone. Lymphoma risk is linked to chronic inflammation, not calcium deficiency.'),
  ('celiac', 38, 'A client with celiac disease who has no current symptoms asks why gluten must still be avoided. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Gluten is stored in fat tissue and released later."}, {"id": "b", "text": "Gluten causes permanent scarring of the pancreas."}, {"id": "c", "text": "Chronic inflammation raises the risk of lymphoma."}, {"id": "d", "text": "Gluten eventually stops all water absorption."}]'::jsonb, '["c"]', 'Untreated celiac disease causes chronic inflammation that increases the risk of intestinal T-cell lymphoma, so avoidance must continue even without symptoms. The other explanations are not described mechanisms of celiac disease.'),
  ('celiac', 39, 'A nurse is reviewing findings for a client with celiac disease who has not followed the prescribed diet. Which finding should the nurse report as a possible complication?', '[{"id": "a", "text": "Formed stool once daily"}, {"id": "b", "text": "Stable weight over 3 months"}, {"id": "c", "text": "New tingling in hands and feet"}, {"id": "d", "text": "Hemoglobin within normal range"}]'::jsonb, '["c"]', 'Peripheral neuropathy is a neurologic complication of untreated celiac disease caused by B12/folate deficiency. Formed stools, stable weight, and normal hemoglobin are expected findings, not complications.'),
  ('celiac', 40, 'A client with untreated celiac disease reports fatigue, and laboratory results show low hemoglobin. Which complication should the nurse suspect?', '[{"id": "a", "text": "Anemia"}, {"id": "b", "text": "Osteoporosis"}, {"id": "c", "text": "Infertility"}, {"id": "d", "text": "Dermatitis herpetiformis"}]'::jsonb, '["a"]', 'Fatigue with low hemoglobin reflects anemia, which in celiac disease results from iron and/or B12/folate malabsorption. Osteoporosis relates to calcium and vitamin D loss, not hemoglobin.'),
  ('celiac', 41, 'A client with celiac disease lives with family members who eat regular bread and pasta. Which instruction should the nurse include?', '[{"id": "a", "text": "Prepare gluten-free food on the board just used for wheat bread."}, {"id": "b", "text": "Use separate cooking surfaces and utensils for gluten-free food."}, {"id": "c", "text": "Share serving spoons between dishes to reduce dish washing."}, {"id": "d", "text": "Toast regular and gluten-free bread together on the same tray."}]'::jsonb, '["b"]', 'Clients must be advised about cross-contamination risks from shared cooking surfaces and utensils. Sharing boards, spoons, or trays with wheat products exposes the client to gluten.'),
  ('celiac', 42, 'A client newly diagnosed with celiac disease says, ''I have no idea what I''m supposed to eat now.'' Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Provide a list of favorite wheat-based recipes."}, {"id": "b", "text": "Advise the client to eliminate all carbohydrates."}, {"id": "c", "text": "Arrange a referral to a dietitian for meal planning."}, {"id": "d", "text": "Tell the client to eat only fruits for several weeks."}]'::jsonb, '["c"]', 'A dietitian referral is recommended for education and meal planning in celiac disease. Eliminating all carbohydrates is unnecessary because rice, corn, potatoes, and quinoa are safe.'),
  ('celiac', 43, 'A client with celiac disease has developed peripheral neuropathy. Which type of supplement should the nurse anticipate being added to the plan of care?', '[{"id": "a", "text": "B vitamins"}, {"id": "b", "text": "Vitamin A"}, {"id": "c", "text": "Potassium"}, {"id": "d", "text": "Sodium chloride"}]'::jsonb, '["a"]', 'Peripheral neuropathy in celiac disease is related to B12/folate deficiency, and B vitamins are supplemented as needed. Vitamin A, potassium, and sodium do not address the cause of the neuropathy.'),
  ('celiac', 44, 'A nurse is teaching a group of clients about celiac disease. Which statement by a participant indicates a need for further teaching?', '[{"id": "a", "text": "Gluten causes my immune system to attack my intestine."}, {"id": "b", "text": "The damage happens to the villi in my small intestine."}, {"id": "c", "text": "My treatment is a gluten-free diet for the rest of my life."}, {"id": "d", "text": "This is just a food intolerance that I will grow out of."}]'::jsonb, '["d"]', 'Celiac disease is autoimmune, not just a food intolerance, and requires a lifelong gluten-free diet. The other statements correctly describe the immune attack on the small intestinal villi and lifelong treatment.'),
  ('celiac', 45, 'A nurse checks the lunch tray of a client with celiac disease. Which item should the nurse remove from the tray?', '[{"id": "a", "text": "Baked potato"}, {"id": "b", "text": "Steamed rice"}, {"id": "c", "text": "Fresh fruit cup"}, {"id": "d", "text": "Barley soup"}]'::jsonb, '["d"]', 'Barley contains gluten and must be avoided. Potatoes, rice, and fruit are gluten-free foods.'),
  ('celiac', 46, 'A client with celiac disease is evaluated on understanding of food selection. Which statement indicates the client understands the teaching?', '[{"id": "a", "text": "I only need to check the labels on bread products."}, {"id": "b", "text": "Soy sauce is safe since it is made from soybeans."}, {"id": "c", "text": "I will read the label on every packaged food I buy."}, {"id": "d", "text": "If a food doesn''t taste like wheat, it is gluten-free."}]'::jsonb, '["c"]', 'Clients must read all food labels carefully. Soy sauce usually contains wheat, so assuming it is safe indicates a need for more teaching.'),
  ('celiac', 47, 'A client with celiac disease is ordering a stir-fry at a restaurant. Which request by the client is most appropriate?', '[{"id": "a", "text": "Please add extra soy sauce on the side."}, {"id": "b", "text": "Please prepare my dish without soy sauce."}, {"id": "c", "text": "Please serve my meal with a barley side."}, {"id": "d", "text": "Please wrap the filling in a wheat tortilla."}]'::jsonb, '["b"]', 'Soy sauce usually contains wheat, so requesting the dish without it avoids gluten. Barley and wheat both contain gluten.'),
  ('celiac', 48, 'A nurse is assessing a 4-year-old child with suspected celiac disease. Which group of GI findings is consistent with this condition?', '[{"id": "a", "text": "Constipation, weight gain, and hard stools"}, {"id": "b", "text": "Bloody stools, high fever, and stiff neck"}, {"id": "c", "text": "Abdominal bloating, diarrhea, and weight loss"}, {"id": "d", "text": "Black stools, vomiting blood, and dizziness"}]'::jsonb, '["c"]', 'GI symptoms of celiac disease include chronic diarrhea, bloating and abdominal pain, nausea/vomiting, and weight loss. Constipation with weight gain does not match the malabsorption pattern.'),
  ('celiac', 49, 'A client with celiac disease has followed a strict gluten-free diet for 6 months and is now symptom-free. The client asks about slowly adding wheat back into meals. Which response by the nurse is best?', '[{"id": "a", "text": "You may add wheat back slowly now that your villi have healed."}, {"id": "b", "text": "You may eat wheat on weekends as long as symptoms stay away."}, {"id": "c", "text": "You will need to stay strictly gluten-free for life."}, {"id": "d", "text": "You may resume wheat after one more year without symptoms."}]'::jsonb, '["c"]', 'Treatment is a strict, lifelong gluten-free diet even after symptoms resolve and villi regenerate. Healed villi do not make reintroducing wheat safe.'),
  ('celiac', 50, 'A nurse is planning long-term follow-up for a client with celiac disease. Which laboratory values should the nurse plan to monitor periodically?', '[{"id": "a", "text": "Amylase, lipase, and bilirubin"}, {"id": "b", "text": "Ammonia, ALT, and AST"}, {"id": "c", "text": "Troponin, BNP, and CK"}, {"id": "d", "text": "Iron, calcium, vitamin D, B12, and folate"}]'::jsonb, '["d"]', 'Clients with celiac disease are monitored for nutritional deficiencies of iron, calcium, vitamin D, B12, and folate. The other panels do not reflect the malabsorption caused by villous damage.'),
  ('lactose', 1, 'A client recently diagnosed with lactose intolerance asks the nurse what causes the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "An allergy to the protein found in cow''s milk"}, {"id": "b", "text": "A deficiency of lactase, the enzyme that digests milk sugar"}, {"id": "c", "text": "An immune attack on the intestine triggered by dairy"}, {"id": "d", "text": "An overproduction of the enzyme that digests milk sugar"}]'::jsonb, '["b"]', 'Lactose intolerance results from a lactase deficiency; lactase is the enzyme that breaks down lactose, a sugar found in milk. Overproduction of the enzyme is the reverse of the actual problem.'),
  ('lactose', 2, 'A client with lactose intolerance asks why drinking milk causes diarrhea. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Undigested lactose retains water in the bowel, causing osmotic diarrhea."}, {"id": "b", "text": "Bacteria in the milk invade the intestinal wall and cause an infection."}, {"id": "c", "text": "The immune system damages the villi and blocks absorption of milk."}, {"id": "d", "text": "Lactose speeds stomach emptying, which pushes food out too quickly."}]'::jsonb, '["a"]', 'The diarrhea of lactose intolerance is osmotic, caused by water retention in the bowel from undigested lactose. It is not an infectious process, which is supported by the absence of fever.'),
  ('lactose', 3, 'A client with lactose intolerance reports excessive flatulence after eating dairy. The nurse explains that the gas is caused by which process?', '[{"id": "a", "text": "Swallowing air while drinking milk quickly"}, {"id": "b", "text": "Excess stomach acid reacting with milk"}, {"id": "c", "text": "Fermentation of undigested lactose in the colon"}, {"id": "d", "text": "A bacterial infection acquired from the dairy"}]'::jsonb, '["c"]', 'Undigested lactose ferments in the colon, producing gas. Infection is not the cause, as lactose intolerance produces no fever or systemic symptoms.'),
  ('lactose', 4, 'A client reports diarrhea, gas, and bloating that began after drinking a large glass of milk. Which assessment finding best supports lactose intolerance rather than an infectious cause?', '[{"id": "a", "text": "Temperature of 39.2°C (102.6°F)"}, {"id": "b", "text": "Chills and generalized body aches"}, {"id": "c", "text": "Fever that began the day before"}, {"id": "d", "text": "Absence of fever or systemic symptoms"}]'::jsonb, '["d"]', 'Lactose intolerance produces no fever or systemic symptoms, which helps rule out an infectious cause. Fever, chills, and body aches point away from lactose intolerance.'),
  ('lactose', 5, 'A nurse is teaching a client with lactose intolerance which symptoms are expected after accidental dairy intake. Which symptom should the nurse instruct the client to report because it is not expected with lactose intolerance?', '[{"id": "a", "text": "Abdominal bloating"}, {"id": "b", "text": "Fever"}, {"id": "c", "text": "Flatulence"}, {"id": "d", "text": "Loose stools"}]'::jsonb, '["b"]', 'The key symptom pattern of lactose intolerance is diarrhea, gas, and bloating with no fever; fever suggests another cause such as infection. Bloating, gas, and loose stools are expected.'),
  ('lactose', 6, 'A nurse is assessing a client with lactose intolerance 1 hour after the client drank milk. Which finding should the nurse expect?', '[{"id": "a", "text": "Abdominal bloating and distension"}, {"id": "b", "text": "Fever with shaking chills"}, {"id": "c", "text": "Hard stools and constipation"}, {"id": "d", "text": "Black, tarry stools"}]'::jsonb, '["a"]', 'Abdominal bloating and distension are expected symptoms of lactose intolerance. Fever is not expected, and the diarrhea is osmotic rather than constipation.'),
  ('lactose', 7, 'A client with suspected lactose intolerance describes symptoms that occur after eating dairy. Which additional symptoms are consistent with this condition?', '[{"id": "a", "text": "Fever and joint pain"}, {"id": "b", "text": "Yellowing of the sclera"}, {"id": "c", "text": "Itchy, blistering rash"}, {"id": "d", "text": "Nausea and indigestion"}]'::jsonb, '["d"]', 'Symptoms of lactose intolerance include nausea and vomiting and dyspepsia (indigestion). Fever and systemic symptoms are not part of lactose intolerance.'),
  ('lactose', 8, 'A client is scheduled for a hydrogen breath test. The client asks what result would indicate lactose intolerance. Which response by the nurse is correct?', '[{"id": "a", "text": "Exhaled hydrogen decreases after you drink lactose."}, {"id": "b", "text": "Exhaled hydrogen increases after you drink lactose."}, {"id": "c", "text": "Exhaled hydrogen stays the same after you drink lactose."}, {"id": "d", "text": "Exhaled hydrogen disappears after you drink lactose."}]'::jsonb, '["b"]', 'The hydrogen breath test is positive if exhaled hydrogen increases after lactose ingestion. A decrease or no change would not indicate lactose intolerance.'),
  ('lactose', 9, 'A client undergoing a lactose tolerance test asks what the blood samples will show if lactose intolerance is present. Which response by the nurse is accurate?', '[{"id": "a", "text": "Your blood glucose will rise sharply after the lactose drink."}, {"id": "b", "text": "Your blood glucose will rise slowly over several days."}, {"id": "c", "text": "Your blood glucose will fail to rise after the lactose drink."}, {"id": "d", "text": "Your blood glucose will rise only if you also eat cheese."}]'::jsonb, '["c"]', 'In the lactose tolerance test, blood glucose fails to rise after lactose ingestion when lactose intolerance is present. A sharp rise would indicate that lactose was digested normally.'),
  ('lactose', 10, 'A client with recurring diarrhea, gas, and bloating after dairy meals is being evaluated for lactose intolerance. Which diagnostic tests should the nurse anticipate?', '[{"id": "a", "text": "Stool culture and blood cultures"}, {"id": "b", "text": "Abdominal CT scan and colonoscopy"}, {"id": "c", "text": "Upper endoscopy and gastric pH test"}, {"id": "d", "text": "Hydrogen breath test and lactose tolerance test"}]'::jsonb, '["d"]', 'Lactose intolerance is diagnosed with the hydrogen breath test or the lactose tolerance test. Cultures are not indicated because the absence of fever helps rule out infection.'),
  ('lactose', 11, 'A nurse reviews the results of a client''s lactose tolerance test and notes that the blood glucose remained essentially unchanged after the lactose load. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is consistent with lactose intolerance."}, {"id": "b", "text": "It shows that lactose was digested normally."}, {"id": "c", "text": "It suggests an infectious cause of diarrhea."}, {"id": "d", "text": "It indicates the test must use more dairy."}]'::jsonb, '["a"]', 'A blood glucose that fails to rise after lactose ingestion indicates lactose intolerance because the lactose was not broken down. Normal digestion would produce a rise in glucose.'),
  ('lactose', 12, 'A client''s hydrogen breath test shows a rise in exhaled hydrogen after lactose ingestion. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "The test is negative for lactose intolerance."}, {"id": "b", "text": "The test is positive for lactose intolerance."}, {"id": "c", "text": "The test result is inconclusive."}, {"id": "d", "text": "The test indicates an intestinal infection."}]'::jsonb, '["b"]', 'The hydrogen breath test is positive when exhaled hydrogen increases after lactose ingestion. A rise therefore indicates lactose intolerance, not a negative result.'),
  ('lactose', 13, 'A client with lactose intolerance asks which dairy item should be avoided. Which item should the nurse identify?', '[{"id": "a", "text": "Aged cheddar cheese"}, {"id": "b", "text": "Lactose-free milk"}, {"id": "c", "text": "Heavy cream"}, {"id": "d", "text": "Almond milk"}]'::jsonb, '["c"]', 'Milk and cream should be avoided in lactose intolerance. Aged cheddar, lactose-free milk, and almond milk are usually tolerated.'),
  ('lactose', 14, 'A client with lactose intolerance is choosing cheese for a party platter. Which type of cheese should the client avoid?', '[{"id": "a", "text": "Parmesan"}, {"id": "b", "text": "Cheddar"}, {"id": "c", "text": "Gouda"}, {"id": "d", "text": "A soft cheese"}]'::jsonb, '["d"]', 'Soft cheeses should be avoided in lactose intolerance. Aged cheeses such as cheddar, parmesan, and gouda are usually tolerated because of their low lactose content.'),
  ('lactose', 15, 'A client with lactose intolerance wants to include some cheese in the diet. Which choice is usually tolerated?', '[{"id": "a", "text": "Parmesan cheese"}, {"id": "b", "text": "Soft cheese spread"}, {"id": "c", "text": "Cheese sauce made with cream"}, {"id": "d", "text": "Soft cheese mixed with milk"}]'::jsonb, '["a"]', 'Aged cheeses such as parmesan, cheddar, and gouda are usually tolerated. Soft cheeses, cream, and milk should be avoided.'),
  ('lactose', 16, 'A client with lactose intolerance asks why aged cheddar does not cause symptoms while milk does. Which response by the nurse is accurate?', '[{"id": "a", "text": "Aged cheeses contain added lactase enzyme."}, {"id": "b", "text": "Aged cheeses have a low lactose content."}, {"id": "c", "text": "Aged cheeses are made without any milk."}, {"id": "d", "text": "Aged cheeses coat the colon and stop gas."}]'::jsonb, '["b"]', 'Aged cheeses are considered safe dairy because of their low lactose content. They are not lactase-fortified; the enzyme aid is Lactaid taken before dairy.'),
  ('lactose', 17, 'A client with lactose intolerance asks for a beverage to have with breakfast. Which choice should the nurse recommend?', '[{"id": "a", "text": "A glass of whole milk"}, {"id": "b", "text": "Coffee with heavy cream"}, {"id": "c", "text": "A glass of almond milk"}, {"id": "d", "text": "Hot cocoa made with milk"}]'::jsonb, '["c"]', 'Soy, oat, and almond milk alternatives are usually tolerated. Milk and cream should be avoided.'),
  ('lactose', 18, 'The nurse reviews diet teaching with a client who has lactose intolerance. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I can use soy milk on my cereal."}, {"id": "b", "text": "Aged gouda is usually a safe cheese for me."}, {"id": "c", "text": "I should limit soft cheeses and cream."}, {"id": "d", "text": "I must avoid lactose-free milk since it is milk."}]'::jsonb, '["d"]', 'Lactose-free milk is usually tolerated and does not need to be avoided. Soy milk, aged gouda, and limiting soft cheeses and cream are correct.'),
  ('lactose', 19, 'A client newly diagnosed with lactose intolerance asks, ''Will I have to give up all dairy forever?'' Which response by the nurse is best?', '[{"id": "a", "text": "Yes, every dairy product must be avoided for life."}, {"id": "b", "text": "No, you can resume all dairy as soon as diarrhea stops."}, {"id": "c", "text": "No, dairy can be slowly reintroduced to test your tolerance."}, {"id": "d", "text": "Yes, but you may have dairy if you also take an antibiotic."}]'::jsonb, '["c"]', 'Gradual reintroduction of dairy is used to test personal tolerance. Resuming all dairy at once is not gradual, and total lifelong avoidance is not required.'),
  ('lactose', 20, 'A client with lactose intolerance is prescribed a lactase enzyme supplement (Lactaid). When should the nurse instruct the client to take it?', '[{"id": "a", "text": "Before eating dairy foods"}, {"id": "b", "text": "After symptoms begin"}, {"id": "c", "text": "At bedtime each night"}, {"id": "d", "text": "Two hours after dairy"}]'::jsonb, '["a"]', 'Lactaid should be taken before dairy intake. Taking it after symptoms begin or hours after dairy does not follow the instruction.'),
  ('lactose', 21, 'The nurse evaluates a client''s understanding of lactase enzyme (Lactaid) use. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I keep my Lactaid with me when I eat out."}, {"id": "b", "text": "I take my Lactaid after I finish drinking milk."}, {"id": "c", "text": "I take Lactaid before meals that include dairy."}, {"id": "d", "text": "Lactaid helps my body break down milk sugar."}]'::jsonb, '["b"]', 'Lactaid must be taken before dairy intake, so taking it after drinking milk indicates a need for further teaching. Taking it before dairy and understanding that it supplies the enzyme for lactose are correct.'),
  ('lactose', 22, 'A client with lactose intolerance avoids most dairy products. Which supplements are the key supplements the nurse should anticipate for this client?', '[{"id": "a", "text": "Iron and folate"}, {"id": "b", "text": "Potassium and sodium"}, {"id": "c", "text": "Vitamin C and zinc"}, {"id": "d", "text": "Calcium and vitamin D"}]'::jsonb, '["d"]', 'Calcium and vitamin D are the key supplements in lactose intolerance to prevent bone loss. Iron and folate are not identified as the key supplements.'),
  ('lactose', 23, 'A client with lactose intolerance asks why calcium and vitamin D supplements were recommended. Which response by the nurse is correct?', '[{"id": "a", "text": "They stop the diarrhea after dairy."}, {"id": "b", "text": "They replace the missing lactase."}, {"id": "c", "text": "They help prevent bone loss."}, {"id": "d", "text": "They reduce gas in the colon."}]'::jsonb, '["c"]', 'Calcium and vitamin D are key supplements that prevent bone loss. Replacing lactase is the role of the enzyme aid Lactaid, not calcium.'),
  ('lactose', 24, 'An afebrile toddler has diarrhea, gas, and bloating after drinking milk. The child recovered from a GI infection 1 week ago. Which condition should the nurse suspect?', '[{"id": "a", "text": "Recurrent bacterial infection"}, {"id": "b", "text": "Lactose intolerance"}, {"id": "c", "text": "Acute appendicitis"}, {"id": "d", "text": "Viral gastroenteritis"}]'::jsonb, '["b"]', 'Lactose intolerance is common after GI infections in toddlers and causes diarrhea, gas, and bloating without fever. The absence of fever helps rule out an infectious cause.'),
  ('lactose', 25, 'An infant is diagnosed with lactose intolerance. Which feeding should the nurse anticipate the provider recommending?', '[{"id": "a", "text": "Soy-based formula"}, {"id": "b", "text": "Diluted whole milk"}, {"id": "c", "text": "Formula mixed with cream"}, {"id": "d", "text": "Whole milk at room temperature"}]'::jsonb, '["a"]', 'Infants with lactose intolerance should be switched to soy-based or lactose-free formulas. Milk and cream should be avoided.'),
  ('lactose', 26, 'The parent of an infant with lactose intolerance asks whether the baby will have the condition forever. Which response by the nurse is accurate?', '[{"id": "a", "text": "It is always permanent in infants."}, {"id": "b", "text": "It always resolves within one day."}, {"id": "c", "text": "It is usually temporary in infants."}, {"id": "d", "text": "It turns into an infection over time."}]'::jsonb, '["c"]', 'Lactose intolerance is usually temporary in infants but can persist in some populations. Stating it is always permanent is inaccurate.'),
  ('lactose', 27, 'A client with lactose intolerance asks why the nurse recommends reading labels on processed foods and medications. Which response is accurate?', '[{"id": "a", "text": "Lactose is often hidden in processed foods and medications."}, {"id": "b", "text": "Medications often contain lactase that worsens symptoms."}, {"id": "c", "text": "Processed foods contain bacteria that cause osmotic diarrhea."}, {"id": "d", "text": "Labels are needed only to track calories and protein."}]'::jsonb, '["a"]', 'Label reading is taught because lactose is often hidden in processed foods and medications. Lactase is the enzyme that breaks down lactose and does not worsen symptoms.'),
  ('lactose', 28, 'The nurse reviews label-reading teaching with a client who has lactose intolerance. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will check medication labels for lactose."}, {"id": "b", "text": "I will read labels on packaged snack foods."}, {"id": "c", "text": "I will ask the pharmacist about my pills."}, {"id": "d", "text": "I only need to check foods that look like dairy."}]'::jsonb, '["d"]', 'Lactose is often hidden in processed foods and medications, so checking only foods that look like dairy is unsafe. Checking medications and packaged foods is correct.'),
  ('lactose', 29, 'A nurse is planning care for a client with long-standing lactose intolerance who avoids dairy. Which nutrient deficiencies should the nurse plan to monitor for?', '[{"id": "a", "text": "Sodium and potassium"}, {"id": "b", "text": "Calcium and vitamin D"}, {"id": "c", "text": "Iron and folic acid"}, {"id": "d", "text": "Glucose and protein"}]'::jsonb, '["b"]', 'Nursing considerations include monitoring for nutrient deficiencies such as calcium and vitamin D. Sodium and potassium are not the deficiencies identified for monitoring.'),
  ('lactose', 30, 'A client with lactose intolerance has stopped drinking milk and is concerned about getting enough nutrients. Which nursing intervention is most appropriate?', '[{"id": "a", "text": "Teach about alternative calcium and protein sources."}, {"id": "b", "text": "Advise the client to restrict all protein in the diet."}, {"id": "c", "text": "Instruct the client to stop all calcium-containing foods."}, {"id": "d", "text": "Encourage the client to return to drinking whole milk."}]'::jsonb, '["a"]', 'Nurses should educate clients on alternative calcium and protein sources. Restricting protein or calcium would worsen nutritional risk, and milk should be avoided.'),
  ('lactose', 31, 'A client with lactose intolerance has had several episodes of diarrhea after unknowingly eating dairy. Which nursing action is the priority?', '[{"id": "a", "text": "Restrict oral fluids to slow the diarrhea."}, {"id": "b", "text": "Ensure the client maintains adequate hydration."}, {"id": "c", "text": "Give a glass of milk to coat the stomach."}, {"id": "d", "text": "Obtain blood cultures to identify infection."}]'::jsonb, '["b"]', 'Adequate hydration must be ensured when diarrhea is present. Restricting fluids is unsafe, and milk should be avoided.'),
  ('lactose', 32, 'A client with lactose intolerance has frequent loose stools. Which action by the unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "Recording the number of loose stools"}, {"id": "b", "text": "Offering lactose-free milk with a meal"}, {"id": "c", "text": "Limiting the client''s fluids to reduce stools"}, {"id": "d", "text": "Keeping the call light within the client''s reach"}]'::jsonb, '["c"]', 'Adequate hydration should be ensured when diarrhea is present, so limiting fluids requires correction. Lactose-free milk is usually tolerated and is appropriate.'),
  ('lactose', 33, 'After teaching about lactose intolerance, which statement by the client indicates understanding of the cause?', '[{"id": "a", "text": "I am allergic to the protein in milk."}, {"id": "b", "text": "My immune system attacks my bowel when I eat dairy."}, {"id": "c", "text": "Dairy products give me an intestinal infection."}, {"id": "d", "text": "I don''t make enough of the enzyme that breaks down milk sugar."}]'::jsonb, '["d"]', 'Lactose intolerance results from lactase deficiency; lactase is the enzyme that breaks down lactose, a milk sugar. It is not an infection, as shown by the lack of fever.'),
  ('lactose', 34, 'A nurse is explaining the sequence of events in lactose intolerance to a client. Which order is correct?', '[{"id": "a", "text": "Lactase deficiency, undigested lactose, fermentation in colon, diarrhea and gas"}, {"id": "b", "text": "Undigested lactose, diarrhea and gas, lactase deficiency, fermentation in colon"}, {"id": "c", "text": "Fermentation in colon, lactase deficiency, diarrhea and gas, undigested lactose"}, {"id": "d", "text": "Diarrhea and gas, fermentation in colon, undigested lactose, lactase deficiency"}]'::jsonb, '["a"]', 'Lactase deficiency leaves lactose undigested; the undigested lactose ferments in the colon, causing osmotic diarrhea, gas, and bloating. Diarrhea and gas are the result, not the starting point.'),
  ('lactose', 35, 'A client with lactose intolerance asks for help choosing a snack. Which combination is most appropriate?', '[{"id": "a", "text": "Whole milk with a soft cheese"}, {"id": "b", "text": "Lactose-free milk with sliced cheddar"}, {"id": "c", "text": "Coffee with cream and soft cheese"}, {"id": "d", "text": "Regular milk with a cream pastry"}]'::jsonb, '["b"]', 'Lactose-free milk and aged cheeses such as cheddar are usually tolerated. Milk, cream, and soft cheeses should be avoided.'),
  ('lactose', 36, 'The nurse reviews dairy teaching with a client who has lactose intolerance. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I must avoid cheddar and parmesan because all cheese has lactose."}, {"id": "b", "text": "I can use oat milk or almond milk instead of regular milk."}, {"id": "c", "text": "I should take my Lactaid before I eat any dairy product."}, {"id": "d", "text": "I can slowly add small amounts of dairy to see what I tolerate."}]'::jsonb, '["a"]', 'Aged cheeses such as cheddar and parmesan have low lactose content and are usually tolerated, so avoiding them reflects a misunderstanding. The other statements are correct.'),
  ('lactose', 37, 'A client with lactose intolerance asks which milk substitute to buy. Which option should the nurse suggest?', '[{"id": "a", "text": "Half-and-half"}, {"id": "b", "text": "Heavy whipping cream"}, {"id": "c", "text": "Whole milk"}, {"id": "d", "text": "Oat milk"}]'::jsonb, '["d"]', 'Soy, oat, and almond milk alternatives are usually tolerated. Cream and milk should be avoided.'),
  ('lactose', 38, 'A client with lactose intolerance tells the nurse about plans for adding dairy back into the diet. Which statement indicates correct understanding?', '[{"id": "a", "text": "I will drink a large glass of milk to see what happens."}, {"id": "b", "text": "I will add small amounts of dairy slowly to find my limit."}, {"id": "c", "text": "I will add every dairy food back at once when I feel well."}, {"id": "d", "text": "I will never eat any dairy food again for the rest of my life."}]'::jsonb, '["b"]', 'Gradual reintroduction is used to test personal tolerance. Adding all dairy at once or a large amount of milk is not gradual.'),
  ('lactose', 39, 'A client asks how a lactase enzyme supplement (Lactaid) reduces symptoms. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It coats the colon to stop fermentation."}, {"id": "b", "text": "It kills the bacteria that produce gas."}, {"id": "c", "text": "It supplies the enzyme that breaks down lactose."}, {"id": "d", "text": "It replaces calcium lost from avoiding dairy."}]'::jsonb, '["c"]', 'Lactaid is a lactase enzyme, and lactase is the enzyme that breaks down lactose. Replacing calcium is the role of calcium and vitamin D supplements.'),
  ('lactose', 40, 'A toddler developed lactose intolerance after a recent GI infection. Which instruction should the nurse give the parents?', '[{"id": "a", "text": "Continue giving whole milk at every meal."}, {"id": "b", "text": "Add cream to the formula for extra calories."}, {"id": "c", "text": "Withhold all fluids until the diarrhea stops."}, {"id": "d", "text": "Switch to a soy-based or lactose-free formula."}]'::jsonb, '["d"]', 'For lactose intolerance after a GI infection, the child should be switched to soy-based or lactose-free formulas. Milk and cream should be avoided, and hydration must be maintained during diarrhea.'),
  ('lactose', 41, 'The nurse teaches the parent of an infant with lactose intolerance. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "My baby will definitely need special formula for life."}, {"id": "b", "text": "I will use a lactose-free formula for my baby."}, {"id": "c", "text": "This is usually temporary in babies, but it can last."}, {"id": "d", "text": "A soy-based formula is an option for my baby."}]'::jsonb, '["a"]', 'Lactose intolerance is usually temporary in infants, although it can persist in some populations, so ''definitely for life'' is incorrect. Soy-based and lactose-free formulas are appropriate.'),
  ('lactose', 42, 'A client with lactose intolerance who carefully avoids dairy reports bloating and diarrhea since starting a new tablet medication. Which explanation should the nurse consider first?', '[{"id": "a", "text": "The client has developed an intestinal infection."}, {"id": "b", "text": "The medication may contain hidden lactose."}, {"id": "c", "text": "The medication increases lactase production."}, {"id": "d", "text": "The client now needs to stop all fluids."}]'::jsonb, '["b"]', 'Lactose is often hidden in processed foods and medications, so a new medication may be the source. Increased lactase would improve, not worsen, lactose digestion.'),
  ('lactose', 43, 'A nurse is assessing a client who reports symptoms after eating a dairy-rich meal. Which set of findings is most consistent with lactose intolerance?', '[{"id": "a", "text": "Fever, diarrhea, and body aches"}, {"id": "b", "text": "Constipation and rectal bleeding"}, {"id": "c", "text": "Diarrhea, flatulence, and bloating"}, {"id": "d", "text": "Jaundice and dark amber urine"}]'::jsonb, '["c"]', 'Lactose intolerance causes osmotic diarrhea, flatulence, and abdominal bloating without fever. Fever with body aches suggests a systemic or infectious cause.'),
  ('lactose', 44, 'A nurse is developing a care plan for an adult with lactose intolerance. Which nursing intervention should be included?', '[{"id": "a", "text": "Monitor for calcium and vitamin D deficiency."}, {"id": "b", "text": "Monitor for elevated blood glucose after meals."}, {"id": "c", "text": "Monitor for fever every 2 hours as expected."}, {"id": "d", "text": "Monitor for weight gain from excess dairy."}]'::jsonb, '["a"]', 'Nursing considerations include monitoring for nutrient deficiencies such as calcium and vitamin D. Fever is not an expected finding in lactose intolerance.'),
  ('lactose', 45, 'A nurse reviews a hospitalized client''s meal tray. The client has lactose intolerance. Which item should the nurse question?', '[{"id": "a", "text": "A carton of lactose-free milk"}, {"id": "b", "text": "A carton of almond milk"}, {"id": "c", "text": "A slice of aged cheddar"}, {"id": "d", "text": "A carton of regular milk"}]'::jsonb, '["d"]', 'Milk should be avoided in lactose intolerance. Lactose-free milk, almond milk, and aged cheddar are usually tolerated.'),
  ('lactose', 46, 'A nursing student asks where undigested lactose is fermented in a client with lactose intolerance. Which response by the nurse is correct?', '[{"id": "a", "text": "In the stomach"}, {"id": "b", "text": "In the esophagus"}, {"id": "c", "text": "In the colon"}, {"id": "d", "text": "In the liver"}]'::jsonb, '["c"]', 'Undigested lactose ferments in the colon, causing osmotic diarrhea, gas, and bloating. Fermentation does not occur in the stomach.'),
  ('lactose', 47, 'The nurse evaluates teaching about supplements for a client with lactose intolerance. Which statement by the client indicates understanding?', '[{"id": "a", "text": "I''ll take iron tablets to keep my bones strong."}, {"id": "b", "text": "I''ll take Lactaid instead of a calcium supplement."}, {"id": "c", "text": "I don''t need calcium since I avoid dairy foods."}, {"id": "d", "text": "I''ll take calcium and vitamin D to protect my bones."}]'::jsonb, '["d"]', 'Calcium and vitamin D are the key supplements to prevent bone loss. Lactaid is an enzyme aid for digesting lactose and does not replace calcium.'),
  ('lactose', 48, 'A client with lactose intolerance plans to eat a dish made with soft cheese at a family dinner. Which advice by the nurse is most appropriate?', '[{"id": "a", "text": "Take Lactaid after the symptoms begin."}, {"id": "b", "text": "Take Lactaid before eating the dish."}, {"id": "c", "text": "Drink a glass of milk before the meal."}, {"id": "d", "text": "Avoid drinking fluids during the meal."}]'::jsonb, '["b"]', 'Lactaid should be taken before dairy intake. Taking it after symptoms start does not follow the instruction, and milk should be avoided.'),
  ('lactose', 49, 'A nurse in a pediatric clinic is reviewing the histories of several children. Which child is at greatest risk for developing lactose intolerance?', '[{"id": "a", "text": "A school-age child with a broken arm"}, {"id": "b", "text": "A toddler recovering from a GI infection"}, {"id": "c", "text": "An adolescent with seasonal allergies"}, {"id": "d", "text": "A school-age child with a recent sprain"}]'::jsonb, '["b"]', 'Lactose intolerance is common after GI infections in toddlers. The other histories are not associated with lactose intolerance.'),
  ('lactose', 50, 'A nurse is preparing discharge teaching for a client with lactose intolerance. Which instruction should the nurse include?', '[{"id": "a", "text": "Read labels for lactose hidden in processed foods."}, {"id": "b", "text": "Avoid all aged cheeses such as cheddar and gouda."}, {"id": "c", "text": "Take Lactaid after finishing meals with dairy."}, {"id": "d", "text": "Limit fluid intake whenever diarrhea is present."}]'::jsonb, '["a"]', 'Clients should be taught label reading because lactose is often hidden in processed foods and medications. Aged cheeses are usually tolerated, Lactaid is taken before dairy, and hydration should be ensured during diarrhea.'),
  ('pku', 1, 'The parents of a newborn diagnosed with phenylketonuria (PKU) ask the nurse what the disorder means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The body cannot digest the sugar found in milk."}, {"id": "b", "text": "The body cannot absorb fat from the intestine."}, {"id": "c", "text": "The body cannot metabolize the amino acid phenylalanine."}, {"id": "d", "text": "The immune system attacks the bowel after eating gluten."}]'::jsonb, '["c"]', 'PKU is a genetic disorder in which the body cannot metabolize phenylalanine, an essential amino acid found in protein-rich foods. It is not a problem with milk sugar or fat absorption.'),
  ('pku', 2, 'A parent asks the nurse whether something done during pregnancy caused the baby''s phenylketonuria (PKU). Which statement by the nurse accurately describes the cause?', '[{"id": "a", "text": "PKU is an autosomal recessive genetic disorder."}, {"id": "b", "text": "PKU results from too much protein in early infancy."}, {"id": "c", "text": "PKU develops after exposure to artificial sweeteners."}, {"id": "d", "text": "PKU is an autoimmune disorder triggered by gluten."}]'::jsonb, '["a"]', 'PKU is an autosomal recessive genetic disorder. Dietary protein and aspartame raise phenylalanine levels in a person with PKU but do not cause the disorder.'),
  ('pku', 3, 'A nursing student is studying phenylketonuria (PKU). Which enzyme does the student correctly identify as deficient in this disorder?', '[{"id": "a", "text": "Lactase"}, {"id": "b", "text": "Phenylalanine hydroxylase"}, {"id": "c", "text": "Pancreatic lipase"}, {"id": "d", "text": "Salivary amylase"}]'::jsonb, '["b"]', 'In PKU the deficient enzyme is phenylalanine hydroxylase (PAH), so phenylalanine cannot be metabolized. Lactase, lipase, and amylase are not involved.'),
  ('pku', 4, 'A parent asks why phenylketonuria (PKU) can damage a child''s brain. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Phenylalanine is too low in the brain to support growth."}, {"id": "b", "text": "Low blood glucose deprives the brain of energy."}, {"id": "c", "text": "Ammonia from liver failure builds up in the brain."}, {"id": "d", "text": "Phenylalanine builds up in the blood and brain and is neurotoxic."}]'::jsonb, '["d"]', 'Phenylalanine accumulates in the blood and brain and is neurotoxic. Phenylalanine is elevated, not deficient, in untreated PKU.'),
  ('pku', 5, 'A nurse is assessing an infant with untreated phenylketonuria (PKU). Which finding should the nurse expect?', '[{"id": "a", "text": "Fruity-smelling breath"}, {"id": "b", "text": "Musty-smelling urine"}, {"id": "c", "text": "Sweet-smelling urine"}, {"id": "d", "text": "Fishy body odor"}]'::jsonb, '["b"]', 'A musty urine odor (phenylacetate) occurs in untreated PKU. The other odors are not associated with PKU.'),
  ('pku', 6, 'A nurse is teaching parents about the consequences of untreated phenylketonuria (PKU). Which complications should the nurse include?', '[{"id": "a", "text": "Osteoporosis and infertility"}, {"id": "b", "text": "Jaundice and liver failure"}, {"id": "c", "text": "Intellectual disability and seizures"}, {"id": "d", "text": "Osmotic diarrhea and bloating"}]'::jsonb, '["c"]', 'Untreated PKU leads to intellectual disability and seizures because phenylalanine is neurotoxic. The other complications are not described for PKU.'),
  ('pku', 7, 'A school-age child with phenylketonuria (PKU) has not followed the prescribed diet for many months. Which finding should the nurse anticipate?', '[{"id": "a", "text": "Behavioral problems"}, {"id": "b", "text": "Improved concentration"}, {"id": "c", "text": "Increased bone density"}, {"id": "d", "text": "Accelerated growth"}]'::jsonb, '["a"]', 'Untreated PKU causes severe intellectual disability, seizures, and behavioral problems. Improved concentration is the opposite of the neurotoxic effect of high phenylalanine.'),
  ('pku', 8, 'A nurse reviews the laboratory results of a 4-year-old child with phenylketonuria (PKU). The blood phenylalanine level is 4 mg/dL. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Notify the provider that the level is above goal."}, {"id": "b", "text": "Initiate seizure precautions for a critical level."}, {"id": "c", "text": "Instruct the family to add more high-protein foods."}, {"id": "d", "text": "Reinforce the current diet since the level is at goal."}]'::jsonb, '["d"]', 'The goal blood phenylalanine level is 2–6 mg/dL, so 4 mg/dL is within goal and the current diet should be reinforced. Adding high-protein foods would raise phenylalanine.'),
  ('pku', 9, 'A child with phenylketonuria (PKU) has a blood phenylalanine level of 14 mg/dL. How should the nurse interpret this result?', '[{"id": "a", "text": "The level is within the goal range."}, {"id": "b", "text": "The level is below goal and needs more protein."}, {"id": "c", "text": "The level is above goal and risks brain damage."}, {"id": "d", "text": "The level no longer matters after infancy."}]'::jsonb, '["c"]', 'The goal phenylalanine level is 2–6 mg/dL, so 14 mg/dL is above goal and places the child at risk for neurologic damage. Phenylalanine control continues for life.'),
  ('pku', 10, 'The nurse teaches the parents of a child with phenylketonuria (PKU) about blood monitoring. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "We will keep the level between 10 and 20 mg/dL."}, {"id": "b", "text": "We will keep the level between 2 and 6 mg/dL."}, {"id": "c", "text": "We will keep the level as high as possible."}, {"id": "d", "text": "We will check the level only if seizures occur."}]'::jsonb, '["b"]', 'Regular monitoring of blood phenylalanine with a goal of 2–6 mg/dL is required. Higher levels are neurotoxic, and monitoring is regular rather than only after symptoms.'),
  ('pku', 11, 'A pregnant client asks how her baby will be checked for phenylketonuria (PKU) after birth. Which response by the nurse is accurate?', '[{"id": "a", "text": "A heel stick blood test in the newborn period"}, {"id": "b", "text": "A urine culture at the 2-year checkup"}, {"id": "c", "text": "A small bowel biopsy if diarrhea occurs"}, {"id": "d", "text": "A breath test when solid foods are started"}]'::jsonb, '["a"]', 'PKU is diagnosed by the mandatory newborn heel stick test. Waiting until later childhood would miss the chance for early detection.'),
  ('pku', 12, 'A parent of a healthy-appearing newborn asks whether the phenylketonuria (PKU) screening test is necessary. Which response by the nurse is correct?', '[{"id": "a", "text": "It is done only if a newborn shows symptoms."}, {"id": "b", "text": "It is done only when there is a family history."}, {"id": "c", "text": "It is mandatory in the U.S. for all newborns."}, {"id": "d", "text": "It is done only at the 1-year well-child visit."}]'::jsonb, '["c"]', 'The heel stick blood test is mandatory in the U.S. for all newborns. Screening is not limited to symptomatic infants or those with a family history.'),
  ('pku', 13, 'A parent asks why phenylketonuria (PKU) screening is done in newborns before any symptoms appear. Which response by the nurse is best?', '[{"id": "a", "text": "Treatment can safely wait until seizures appear."}, {"id": "b", "text": "Treatment before symptoms leads to normal development."}, {"id": "c", "text": "Screening is used only for future family planning."}, {"id": "d", "text": "Screening shows when to start high-protein foods."}]'::jsonb, '["b"]', 'Early detection is critical because treatment begun before symptoms results in normal development. Waiting for seizures allows neurologic damage to occur.'),
  ('pku', 14, 'A nurse is teaching the parents of a child with phenylketonuria (PKU) about food choices. Which food should the parents avoid?', '[{"id": "a", "text": "Apple slices"}, {"id": "b", "text": "Carrot sticks"}, {"id": "c", "text": "Steamed rice"}, {"id": "d", "text": "Baked chicken"}]'::jsonb, '["d"]', 'Meat, poultry, and fish must be avoided in PKU. Fruits, vegetables, and rice are safe foods.'),
  ('pku', 15, 'A school nurse reviews the packed lunch of a child with phenylketonuria (PKU). Which item requires follow-up with the parents?', '[{"id": "a", "text": "A cheese omelet"}, {"id": "b", "text": "A fruit salad"}, {"id": "c", "text": "Steamed vegetables"}, {"id": "d", "text": "Plain corn"}]'::jsonb, '["a"]', 'Dairy products and eggs must be avoided in PKU. Fruits, vegetables, and corn are safe foods.'),
  ('pku', 16, 'A child with phenylketonuria (PKU) wants an after-school snack. Which snack should the child avoid?', '[{"id": "a", "text": "Fresh grapes"}, {"id": "b", "text": "Rice cakes"}, {"id": "c", "text": "Mixed nuts"}, {"id": "d", "text": "Cucumber slices"}]'::jsonb, '["c"]', 'Nuts and legumes must be avoided in PKU. Fruits, vegetables, and rice are safe foods.'),
  ('pku', 17, 'An adolescent with phenylketonuria (PKU) asks about drinking a sugar-free beverage sweetened with aspartame. Which response by the nurse is correct?', '[{"id": "a", "text": "It is safe because it contains no sugar."}, {"id": "b", "text": "It is safe if you limit it to one per day."}, {"id": "c", "text": "It should be avoided because aspartame contains phenylalanine."}, {"id": "d", "text": "It is better than regular drinks for lowering phenylalanine."}]'::jsonb, '["c"]', 'Aspartame is an artificial sweetener that contains phenylalanine and must be avoided. Being sugar-free does not make it safe for a person with PKU.'),
  ('pku', 18, 'The parents of a child with phenylketonuria (PKU) ask what to look for on packaged food labels. Which label statement should the nurse teach them to watch for?', '[{"id": "a", "text": "Gluten-free product"}, {"id": "b", "text": "Contains Phenylalanine"}, {"id": "c", "text": "Lactose-free product"}, {"id": "d", "text": "No added sugar"}]'::jsonb, '["b"]', 'Products containing aspartame are labeled ''Contains Phenylalanine,'' and families should read all labels for this warning. The other labels do not address phenylalanine.'),
  ('pku', 19, 'The nurse reviews dietary teaching with the parent of a child with phenylketonuria (PKU). Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I will read every food label before buying it."}, {"id": "b", "text": "Fruits and vegetables are safe for my child."}, {"id": "c", "text": "My child will stay on a special diet for life."}, {"id": "d", "text": "Aspartame is a safe sugar substitute for my child."}]'::jsonb, '["d"]', 'Aspartame contains phenylalanine and must be avoided, so this statement needs correction. Reading labels, choosing fruits and vegetables, and lifelong dieting are correct.'),
  ('pku', 20, 'A toddler with phenylketonuria (PKU) needs a snack at day care. Which snack is most appropriate?', '[{"id": "a", "text": "Fresh fruit"}, {"id": "b", "text": "Cheese cubes"}, {"id": "c", "text": "Boiled egg"}, {"id": "d", "text": "Mixed nuts"}]'::jsonb, '["a"]', 'Fruits are safe foods in PKU. Dairy, eggs, and nuts must be avoided.'),
  ('pku', 21, 'The parents of a child with phenylketonuria (PKU) are planning dinner. Which meal is most appropriate?', '[{"id": "a", "text": "Grilled fish with a side of nuts"}, {"id": "b", "text": "Scrambled eggs with cheese"}, {"id": "c", "text": "Rice with steamed vegetables"}, {"id": "d", "text": "Beef patty with a glass of milk"}]'::jsonb, '["c"]', 'Rice and vegetables are safe foods in PKU. Fish, nuts, eggs, cheese, beef, and milk are protein-rich foods that must be avoided.'),
  ('pku', 22, 'A child with phenylketonuria (PKU) needs a breakfast option. Which choice is most appropriate?', '[{"id": "a", "text": "Eggs with melted cheese"}, {"id": "b", "text": "Low-protein cereal with fruit"}, {"id": "c", "text": "Cereal topped with nuts"}, {"id": "d", "text": "Fish with a glass of milk"}]'::jsonb, '["b"]', 'Some low-protein cereals and fruits are safe foods in PKU. Eggs, cheese, nuts, fish, and dairy must be avoided.'),
  ('pku', 23, 'A newborn has just been diagnosed with phenylketonuria (PKU). Which formula should the nurse anticipate for this infant?', '[{"id": "a", "text": "Standard infant formula"}, {"id": "b", "text": "Lactose-free formula"}, {"id": "c", "text": "High-protein formula"}, {"id": "d", "text": "Phenyl-Free formula"}]'::jsonb, '["d"]', 'A special formula such as Phenyl-Free provides essential amino acids without phenylalanine. Standard formula is a source of phenylalanine, and high-protein foods must be avoided.'),
  ('pku', 24, 'A parent asks why the infant with phenylketonuria (PKU) needs a special formula such as Phenyl-Free. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It provides extra phenylalanine for brain growth."}, {"id": "b", "text": "It provides essential amino acids without phenylalanine."}, {"id": "c", "text": "It supplies the lactase enzyme the baby is missing."}, {"id": "d", "text": "It is free of gluten to protect the intestinal villi."}]'::jsonb, '["b"]', 'Phenyl-Free formula provides essential amino acids without phenylalanine. Adding phenylalanine would be neurotoxic, and the missing enzyme is phenylalanine hydroxylase, not lactase.'),
  ('pku', 25, 'The parent of a child with phenylketonuria (PKU) asks when the child can stop the special diet. Which response by the nurse is correct?', '[{"id": "a", "text": "The diet can stop once your child starts school."}, {"id": "b", "text": "The diet can stop after your child reaches puberty."}, {"id": "c", "text": "The diet must continue for your child''s entire life."}, {"id": "d", "text": "The diet can stop when blood levels are normal once."}]'::jsonb, '["c"]', 'Treatment is a strict low-phenylalanine diet for life. Stopping at school age or puberty would allow phenylalanine to rise.'),
  ('pku', 26, 'The nurse reviews long-term care with the parents of a child with phenylketonuria (PKU). Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "We will keep regular appointments for blood checks."}, {"id": "b", "text": "Once our son is an adult, he can eat a regular diet."}, {"id": "c", "text": "We will see the dietitian to help plan his meals."}, {"id": "d", "text": "We will read labels for the phenylalanine warning."}]'::jsonb, '["b"]', 'PKU requires a strict diet for life, so resuming a regular diet in adulthood is incorrect. Regular blood checks, dietitian support, and label reading are correct.'),
  ('pku', 27, 'A nurse is planning ongoing care for a child with phenylketonuria (PKU). Which assessment is the priority for evaluating dietary control?', '[{"id": "a", "text": "Daily urine glucose checks"}, {"id": "b", "text": "Weekly stool cultures"}, {"id": "c", "text": "Regular blood phenylalanine levels"}, {"id": "d", "text": "Monthly hydrogen breath tests"}]'::jsonb, '["c"]', 'Regular blood checks of phenylalanine are required to keep levels within the 2–6 mg/dL goal. The other tests do not measure phenylalanine.'),
  ('pku', 28, 'A parent asks why the child with phenylketonuria (PKU) needs regular growth and development checkups. Which response by the nurse is accurate?', '[{"id": "a", "text": "To adjust the diet as the child grows"}, {"id": "b", "text": "To decide when the diet can be stopped"}, {"id": "c", "text": "To schedule surgery to replace the enzyme"}, {"id": "d", "text": "To decide when to begin aspartame products"}]'::jsonb, '["a"]', 'Regular growth and development checkups are used for dietary adjustment. The diet is never stopped, and aspartame must be avoided.'),
  ('pku', 29, 'A woman with phenylketonuria (PKU) tells the nurse she is planning a pregnancy. Which teaching is the priority?', '[{"id": "a", "text": "Relax the diet during pregnancy to get extra protein."}, {"id": "b", "text": "Maintain strict phenylalanine control throughout pregnancy."}, {"id": "c", "text": "Phenylalanine control matters only after the baby is born."}, {"id": "d", "text": "Only the baby will need a low-phenylalanine diet."}]'::jsonb, '["b"]', 'Women with PKU who become pregnant must maintain strict phenylalanine control throughout pregnancy because high levels cause fetal brain damage. Relaxing the diet would expose the fetus to high phenylalanine.'),
  ('pku', 30, 'A pregnant client with phenylketonuria (PKU) has blood phenylalanine levels well above goal. The nurse recognizes that the fetus is at risk for which outcome?', '[{"id": "a", "text": "Fetal bone fractures"}, {"id": "b", "text": "Fetal liver failure"}, {"id": "c", "text": "Fetal lactose intolerance"}, {"id": "d", "text": "Fetal brain damage"}]'::jsonb, '["d"]', 'High phenylalanine levels during pregnancy cause fetal brain damage. The other outcomes are not described for maternal PKU.'),
  ('pku', 31, 'A nurse in a metabolic clinic is reviewing clients with phenylketonuria (PKU). For which client is regular blood phenylalanine monitoring especially important?', '[{"id": "a", "text": "A woman with PKU who is 10 weeks pregnant"}, {"id": "b", "text": "A man with PKU whose levels have been stable"}, {"id": "c", "text": "A healthy newborn with a normal heel stick test"}, {"id": "d", "text": "The father of a school-age child with PKU"}]'::jsonb, '["a"]', 'Regular blood checks are especially important in pregnancy because high phenylalanine causes fetal brain damage. A newborn with a normal screen and a parent without PKU do not require phenylalanine monitoring.'),
  ('pku', 32, 'A nurse is developing the discharge plan for a newborn diagnosed with phenylketonuria (PKU). Which referral is most important?', '[{"id": "a", "text": "Neurosurgeon"}, {"id": "b", "text": "Dietitian"}, {"id": "c", "text": "Physical therapist"}, {"id": "d", "text": "Speech therapist"}]'::jsonb, '["b"]', 'A dietitian referral is needed for meal planning because treatment is a strict low-phenylalanine diet. Surgery and therapy referrals do not address dietary management.'),
  ('pku', 33, 'The parents of a child with phenylketonuria (PKU) tell the nurse they feel overwhelmed by the lifelong diet. Which nursing action is most appropriate?', '[{"id": "a", "text": "Suggest relaxing the diet on weekends."}, {"id": "b", "text": "Reassure them the diet is only temporary."}, {"id": "c", "text": "Refer them to a support group for families."}, {"id": "d", "text": "Advise them to stop the special formula."}]'::jsonb, '["c"]', 'Support groups and psychological support for the patient and family are part of PKU nursing care. The diet is lifelong, so relaxing it or calling it temporary is incorrect.'),
  ('pku', 34, 'A nurse is preparing teaching for the family of a newborn with phenylketonuria (PKU). Which teaching point should the nurse emphasize?', '[{"id": "a", "text": "Diet restrictions end after the first year of life."}, {"id": "b", "text": "Diet restrictions apply only when the child is ill."}, {"id": "c", "text": "Diet restrictions can be relaxed if growth is normal."}, {"id": "d", "text": "Diet restrictions are strict and lifelong."}]'::jsonb, '["d"]', 'Nurses should teach the family about strict lifelong dietary restrictions. Ending or relaxing the diet would allow phenylalanine to rise.'),
  ('pku', 35, 'A parent asks why it matters to keep the child''s phenylalanine level between 2 and 6 mg/dL. Which response by the nurse is correct?', '[{"id": "a", "text": "It prevents neurologic damage."}, {"id": "b", "text": "It prevents chronic dehydration."}, {"id": "c", "text": "It prevents loss of bone density."}, {"id": "d", "text": "It prevents failure of the liver."}]'::jsonb, '["a"]', 'Phenylalanine levels are maintained at 2–6 mg/dL to prevent neurologic damage because phenylalanine is neurotoxic. The other outcomes are not the stated reason for the goal.'),
  ('pku', 36, 'The parent of a child with phenylketonuria (PKU) asks for a simple general rule for choosing foods. Which rule should the nurse teach?', '[{"id": "a", "text": "Limit fruits and vegetables."}, {"id": "b", "text": "Limit rice and corn products."}, {"id": "c", "text": "Limit high-protein foods."}, {"id": "d", "text": "Limit low-protein cereals."}]'::jsonb, '["c"]', 'High-protein foods generally must be avoided because phenylalanine is found in protein-rich foods. Fruits, vegetables, rice, corn, and low-protein cereals are safe.'),
  ('pku', 37, 'A parent asks why meat must be restricted for a child with phenylketonuria (PKU). Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Phenylalanine is found in protein-rich foods."}, {"id": "b", "text": "Meat contains gluten that damages the bowel."}, {"id": "c", "text": "Meat contains lactose that ferments in the colon."}, {"id": "d", "text": "Meat is high in sugar that harms the brain."}]'::jsonb, '["a"]', 'Phenylalanine is an essential amino acid found in protein-rich foods such as meat. Gluten and lactose are not the concern in PKU.'),
  ('pku', 38, 'The nurse reviews a weekly menu planned by the parents of a child with phenylketonuria (PKU). Which meal indicates a need for further teaching?', '[{"id": "a", "text": "Rice with mixed vegetables"}, {"id": "b", "text": "Corn with fresh fruit"}, {"id": "c", "text": "Low-protein cereal with fruit"}, {"id": "d", "text": "Baked fish with rice"}]'::jsonb, '["d"]', 'Fish must be avoided in PKU, so this meal needs correction. Rice, corn, vegetables, fruit, and low-protein cereals are safe.'),
  ('pku', 39, 'A 6-month-old infant who did not receive newborn screening is brought to the clinic with seizures and a musty urine odor. Which condition should the nurse suspect?', '[{"id": "a", "text": "Lactose intolerance"}, {"id": "b", "text": "Untreated phenylketonuria"}, {"id": "c", "text": "Celiac disease"}, {"id": "d", "text": "Viral gastroenteritis"}]'::jsonb, '["b"]', 'Seizures and a musty urine odor are signs of untreated PKU. Early detection through newborn screening allows treatment before these symptoms develop.'),
  ('pku', 40, 'The nurse teaches new parents about newborn screening for phenylketonuria (PKU). Which statement by a parent indicates understanding?', '[{"id": "a", "text": "The test is done only if our baby develops symptoms."}, {"id": "b", "text": "The heel stick finds PKU early so treatment starts before symptoms."}, {"id": "c", "text": "A urine test at age 1 will tell us if our baby has PKU."}, {"id": "d", "text": "We can skip the test because no one in our family has PKU."}]'::jsonb, '["b"]', 'The mandatory newborn heel stick allows early detection so treatment can begin before symptoms, resulting in normal development. Screening is not limited to symptomatic infants or those with a family history.'),
  ('pku', 41, 'An infant was diagnosed with phenylketonuria (PKU) through newborn screening and started on dietary treatment right away. Which outcome should the nurse expect if the diet is followed strictly?', '[{"id": "a", "text": "Severe intellectual disability"}, {"id": "b", "text": "Seizures within the first year"}, {"id": "c", "text": "Normal development"}, {"id": "d", "text": "Inevitable behavioral problems"}]'::jsonb, '["c"]', 'Treatment before symptoms results in normal development. Intellectual disability, seizures, and behavioral problems are consequences of untreated PKU.'),
  ('pku', 42, 'A home health nurse reviews the groceries purchased by the family of a child with phenylketonuria (PKU). Which item should the nurse question?', '[{"id": "a", "text": "A bag of fresh apples"}, {"id": "b", "text": "A bag of white rice"}, {"id": "c", "text": "A can of Phenyl-Free formula"}, {"id": "d", "text": "Gum labeled ''Contains Phenylalanine''"}]'::jsonb, '["d"]', 'Products labeled ''Contains Phenylalanine'' contain aspartame and must be avoided. Fruits, rice, and Phenyl-Free formula are appropriate.'),
  ('pku', 43, 'The parents of a child with phenylketonuria (PKU) are choosing products at a specialty store. Which product is most appropriate?', '[{"id": "a", "text": "A high-protein snack bar made with nuts"}, {"id": "b", "text": "A specially formulated low-phenylalanine product"}, {"id": "c", "text": "A package of salted mixed nuts and legumes"}, {"id": "d", "text": "A block of cheddar cheese made from milk"}]'::jsonb, '["b"]', 'Specially formulated low-phenylalanine products are safe foods in PKU. High-protein foods, nuts, and dairy must be avoided.'),
  ('pku', 44, 'A nurse observes an unlicensed assistive personnel (UAP) preparing a feeding for an infant with phenylketonuria (PKU). Which action by the UAP requires correction?', '[{"id": "a", "text": "Mixing standard infant formula for the feeding"}, {"id": "b", "text": "Checking the formula label before preparing it"}, {"id": "c", "text": "Preparing the Phenyl-Free formula as ordered"}, {"id": "d", "text": "Documenting the amount the infant consumed"}]'::jsonb, '["a"]', 'Infants with PKU need a special formula such as Phenyl-Free that provides amino acids without phenylalanine; standard formula is a source of phenylalanine. Preparing Phenyl-Free formula and checking labels are correct.'),
  ('pku', 45, 'An adolescent with phenylketonuria (PKU) says, ''I feel fine, so I want to stop the diet and the blood tests.'' Which response by the nurse is best?', '[{"id": "a", "text": "You can stop both once you turn 18 years old."}, {"id": "b", "text": "You can stop the blood tests but keep the diet."}, {"id": "c", "text": "You can stop the diet if your next level is normal."}, {"id": "d", "text": "The diet and regular blood checks continue for life."}]'::jsonb, '["d"]', 'PKU requires a strict diet for life with regular blood phenylalanine checks. Stopping either would allow phenylalanine to rise and harm the brain.'),
  ('pku', 46, 'The nurse teaches the parents of a newborn with phenylketonuria (PKU) about the cause. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "Our baby makes too much phenylalanine hydroxylase."}, {"id": "b", "text": "Our baby cannot break down phenylalanine normally."}, {"id": "c", "text": "Phenylalanine can build up in our baby''s brain."}, {"id": "d", "text": "PKU is a genetic disorder our baby was born with."}]'::jsonb, '["a"]', 'In PKU, phenylalanine hydroxylase is deficient, not overproduced. The other statements correctly describe the inability to metabolize phenylalanine, its buildup in the brain, and the genetic cause.'),
  ('pku', 47, 'The parents of a newborn diagnosed with phenylketonuria (PKU) ask, ''How will we know what foods to buy?'' Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Advise them to judge protein content by taste."}, {"id": "b", "text": "Tell them to avoid all fruits and vegetables."}, {"id": "c", "text": "Recommend that they follow a high-protein plan."}, {"id": "d", "text": "Arrange a dietitian referral for meal planning."}]'::jsonb, '["d"]', 'A dietitian referral provides meal planning for the strict low-phenylalanine diet. Fruits and vegetables are safe, and high-protein foods must be avoided.'),
  ('pku', 48, 'An adolescent with phenylketonuria (PKU) is frustrated about eating differently from friends. Which nursing action is most appropriate?', '[{"id": "a", "text": "Allow occasional high-protein meals with friends."}, {"id": "b", "text": "Explain that the diet ends at 18 years of age."}, {"id": "c", "text": "Refer the adolescent to a PKU support group."}, {"id": "d", "text": "Suggest skipping blood checks to reduce stress."}]'::jsonb, '["c"]', 'Support groups and psychological support are part of PKU care. The diet is lifelong, so relaxing it or ending it at 18 is incorrect.'),
  ('pku', 49, 'A nurse is performing a well-child visit for a toddler with phenylketonuria (PKU). Which nursing action is most important?', '[{"id": "a", "text": "Recommend starting whole milk at this age."}, {"id": "b", "text": "Suggest nut butter as a new protein source."}, {"id": "c", "text": "Assess growth to guide dietary adjustment."}, {"id": "d", "text": "Advise stopping formula now that solids began."}]'::jsonb, '["c"]', 'Regular growth and development checkups guide dietary adjustment. Dairy and nuts must be avoided in PKU.'),
  ('pku', 50, 'The nurse reviews snack choices with the parent of a child with phenylketonuria (PKU). Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "Fresh fruit is a good snack for my child."}, {"id": "b", "text": "Raw vegetables are a safe snack for my child."}, {"id": "c", "text": "Low-protein cereal is a fine snack for my child."}, {"id": "d", "text": "Nuts are a healthy snack choice for my child."}]'::jsonb, '["d"]', 'Nuts and legumes must be avoided in PKU. Fruits, vegetables, and low-protein cereals are safe foods.'),
  ('vitamins', 1, 'A client with a low serum potassium level asks for a snack that will help raise it. Which snack should the nurse recommend?', '[{"id": "a", "text": "A banana with avocado slices"}, {"id": "b", "text": "Hard cheese with whole wheat crackers"}, {"id": "c", "text": "Oatmeal with apple slices"}, {"id": "d", "text": "Egg yolks with fortified cereal"}]'::jsonb, '["a"]', 'Bananas and avocados are listed potassium sources. Cheese is a calcium source, oats and apples are soluble fiber sources, and egg yolks are a vitamin D source.'),
  ('vitamins', 2, 'A client is admitted with hypokalemia. Which assessment is the priority for the nurse?', '[{"id": "a", "text": "Assess for a positive Chvostek''s sign"}, {"id": "b", "text": "Inspect venipuncture sites for prolonged bleeding"}, {"id": "c", "text": "Review the blood smear for microcytic cells"}, {"id": "d", "text": "Monitor the cardiac rhythm for arrhythmias"}]'::jsonb, '["d"]', 'Low potassium (hypokalemia) is linked to arrhythmias, so cardiac rhythm monitoring is the priority. Chvostek''s sign relates to low calcium, prolonged bleeding to vitamin K, and microcytic cells to low iron.'),
  ('vitamins', 3, 'A client''s laboratory results show a low calcium level. Which assessment finding should the nurse anticipate?', '[{"id": "a", "text": "A positive Trousseau''s sign"}, {"id": "b", "text": "Microcytic red blood cells"}, {"id": "c", "text": "Prolonged bleeding after injections"}, {"id": "d", "text": "A decreased serum potassium level"}]'::jsonb, '["a"]', 'Low calcium causes tetany with positive Chvostek''s/Trousseau''s signs. Microcytic red cells reflect low iron, and prolonged bleeding reflects a lack of vitamin K needed for clotting.'),
  ('vitamins', 4, 'A client who does not consume dairy products has a low calcium intake. Which foods should the nurse suggest?', '[{"id": "a", "text": "Fortified plant-based milk and tofu"}, {"id": "b", "text": "Bananas and fresh tomatoes"}, {"id": "c", "text": "Red meat and roasted poultry"}, {"id": "d", "text": "Carrots and dried apricots"}]'::jsonb, '["a"]', 'Fortified plant-based milks and tofu are listed calcium sources that contain no dairy. Bananas and tomatoes are potassium sources, red meat and poultry are iron sources, and carrots and apricots are vitamin A sources.'),
  ('vitamins', 5, 'A client with a low calcium level asks for a dinner suggestion. Which meal best supports calcium intake?', '[{"id": "a", "text": "Turkey with green beans"}, {"id": "b", "text": "Beef with a baked sweet potato"}, {"id": "c", "text": "Sardines with a kale salad"}, {"id": "d", "text": "Chicken with sliced tomatoes"}]'::jsonb, '["c"]', 'Sardines and leafy greens such as kale are listed calcium sources. Turkey, beef, and chicken are listed as iron or protein sources, and sweet potatoes and tomatoes are potassium sources.'),
  ('vitamins', 6, 'A client with a low calcium level is prescribed vitamin D along with a calcium supplement and asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "Vitamin D is required to enhance iron absorption."}, {"id": "b", "text": "Vitamin D is required for normal blood clotting."}, {"id": "c", "text": "Vitamin D is required to prevent hypokalemia."}, {"id": "d", "text": "Vitamin D is required for calcium absorption."}]'::jsonb, '["d"]', 'Vitamin D is required for calcium absorption. Enhancing iron absorption is the role of vitamin C, and clotting requires vitamin K.'),
  ('vitamins', 7, 'A client needs to increase vitamin D intake. Which breakfast should the nurse recommend?', '[{"id": "a", "text": "Oatmeal topped with apple slices"}, {"id": "b", "text": "Scrambled eggs with fortified milk"}, {"id": "c", "text": "Strawberries with kiwi slices"}, {"id": "d", "text": "Whole wheat toast with avocado"}]'::jsonb, '["b"]', 'Egg yolks and fortified milk are listed vitamin D sources. Oats and apples are soluble fiber sources, strawberries and kiwi are vitamin C sources, and whole wheat and avocado are fiber and potassium sources.'),
  ('vitamins', 8, 'The nurse teaches a client about food sources of vitamin D. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "Mushrooms exposed to sunlight supply vitamin D."}, {"id": "b", "text": "Mackerel is a good vitamin D source."}, {"id": "c", "text": "Egg yolks contain vitamin D."}, {"id": "d", "text": "Bell peppers are a good vitamin D source."}]'::jsonb, '["d"]', 'Bell peppers are listed as a vitamin C source, not a vitamin D source. Mushrooms (sunlight), fatty fish such as mackerel, and egg yolks are all listed vitamin D sources.'),
  ('vitamins', 9, 'A client has prolonged bleeding related to low vitamin K intake. Which foods should the nurse encourage?', '[{"id": "a", "text": "Kale and Brussels sprouts"}, {"id": "b", "text": "Oranges and dried apricots"}, {"id": "c", "text": "Bananas and sliced tomatoes"}, {"id": "d", "text": "Red meat and roasted poultry"}]'::jsonb, '["a"]', 'Kale and Brussels sprouts are listed vitamin K sources. Oranges are a vitamin C source, apricots a vitamin A source, bananas and tomatoes potassium sources, and red meat and poultry iron sources.'),
  ('vitamins', 10, 'A client with easy bruising asks how vitamin K affects bleeding. The nurse explains that vitamin K is required for which clotting factors?', '[{"id": "a", "text": "Factors II, VII, IX, and X"}, {"id": "b", "text": "Factors I, V, VIII, and XI"}, {"id": "c", "text": "Factors III, IV, VI, and XII"}, {"id": "d", "text": "Factors V, VIII, XI, and XIII"}]'::jsonb, '["a"]', 'Vitamin K is required for clotting factors II, VII, IX, and X. The other combinations do not match the factors that depend on vitamin K.'),
  ('vitamins', 11, 'The nurse is caring for a client with a vitamin K deficiency. Which finding should the nurse anticipate?', '[{"id": "a", "text": "A positive Chvostek''s sign on assessment"}, {"id": "b", "text": "Prolonged bleeding from a venipuncture site"}, {"id": "c", "text": "Muscle cramps followed by a seizure"}, {"id": "d", "text": "New-onset arrhythmias on the cardiac monitor"}]'::jsonb, '["b"]', 'Vitamin K is required for clotting, so a deficiency leads to prolonged bleeding. Chvostek''s sign reflects low calcium, cramps and seizures reflect low magnesium, and arrhythmias reflect low potassium.'),
  ('vitamins', 12, 'A client with iron-deficiency anemia plans to eat a lentil dish. Which side should the nurse suggest to improve iron absorption?', '[{"id": "a", "text": "Cheese cubes"}, {"id": "b", "text": "Sliced bell peppers"}, {"id": "c", "text": "An olive oil drizzle"}, {"id": "d", "text": "A whole wheat roll"}]'::jsonb, '["b"]', 'Bell peppers are a vitamin C source, and vitamin C enhances iron absorption. Cheese is a calcium source, olive oil is a healthy fat, and whole wheat is a fiber and complex carbohydrate source.'),
  ('vitamins', 13, 'A client''s complete blood count shows microcytic anemia. The nurse suspects a deficiency of which nutrient?', '[{"id": "a", "text": "Vitamin D"}, {"id": "b", "text": "Potassium"}, {"id": "c", "text": "Magnesium"}, {"id": "d", "text": "Iron"}]'::jsonb, '["d"]', 'Low iron causes microcytic anemia. Low potassium is associated with arrhythmias, low magnesium with muscle cramps and seizures, and vitamin D is needed for calcium absorption.'),
  ('vitamins', 14, 'A client with microcytic anemia asks which dinner would best raise iron levels. Which meal should the nurse recommend?', '[{"id": "a", "text": "Oatmeal with apples and carrots"}, {"id": "b", "text": "Beef with lentils and spinach"}, {"id": "c", "text": "Cauliflower with baked potatoes"}, {"id": "d", "text": "A salad of carrots and apricots"}]'::jsonb, '["b"]', 'Red meat, lentils, and spinach are listed iron sources. Oats, apples, and carrots are soluble fiber sources, cauliflower and potatoes are insoluble fiber sources, and carrots and apricots are vitamin A sources.'),
  ('vitamins', 15, 'A client with low iron levels is taught about iron-rich foods. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Fortified cereals can add iron to my diet."}, {"id": "b", "text": "Lentils and beans contain iron."}, {"id": "c", "text": "Turkey and chicken provide iron."}, {"id": "d", "text": "Butternut squash is my best iron source."}]'::jsonb, '["d"]', 'Butternut squash is listed as a vitamin E source, not an iron source. Fortified cereals, lentils and beans, and poultry such as chicken and turkey are listed iron sources.'),
  ('vitamins', 16, 'A client with a low vitamin C intake requests a snack. Which choice should the nurse suggest?', '[{"id": "a", "text": "Hard-boiled eggs and cheese"}, {"id": "b", "text": "Whole wheat crackers and almonds"}, {"id": "c", "text": "Sardines on whole grain toast"}, {"id": "d", "text": "Kiwi and bell pepper strips"}]'::jsonb, '["d"]', 'Kiwi and bell peppers are listed vitamin C sources. Eggs and cheese are protein, vitamin D, and calcium sources, whole wheat and almonds are fiber, magnesium, and vitamin E sources, and sardines are a calcium source.'),
  ('vitamins', 17, 'A client''s serum magnesium level is low. Which nursing action is the priority?', '[{"id": "a", "text": "Assess for prolonged bleeding"}, {"id": "b", "text": "Implement seizure precautions"}, {"id": "c", "text": "Monitor for microcytic anemia"}, {"id": "d", "text": "Encourage soluble fiber intake"}]'::jsonb, '["b"]', 'Low magnesium can cause muscle cramps and seizures, so seizure precautions are the priority. Prolonged bleeding relates to vitamin K, and microcytic anemia relates to low iron.'),
  ('vitamins', 18, 'A client with a low magnesium level asks for a snack suggestion. Which snack should the nurse recommend?', '[{"id": "a", "text": "Almonds and pumpkin seeds"}, {"id": "b", "text": "Oranges and kiwi slices"}, {"id": "c", "text": "Carrots and dried apricots"}, {"id": "d", "text": "Egg yolks and cheese"}]'::jsonb, '["a"]', 'Nuts and seeds such as almonds and pumpkin seeds are listed magnesium sources. Oranges and kiwi are vitamin C sources, carrots and apricots are vitamin A sources, and egg yolks and cheese are vitamin D and calcium sources.'),
  ('vitamins', 19, 'Which finding would the nurse expect in a client with a low magnesium level?', '[{"id": "a", "text": "Microcytic red blood cells"}, {"id": "b", "text": "A prolonged bleeding time"}, {"id": "c", "text": "Reports of muscle cramps"}, {"id": "d", "text": "A faster intestinal transit time"}]'::jsonb, '["c"]', 'Low magnesium causes muscle cramps and seizures. Microcytic red cells reflect low iron, prolonged bleeding reflects low vitamin K, and faster transit is an effect of insoluble fiber.'),
  ('vitamins', 20, 'A client with a zinc deficiency asks which dinner would best increase zinc intake. Which choice should the nurse recommend?', '[{"id": "a", "text": "Sliced apples and carrots"}, {"id": "b", "text": "Steamed oysters and crab"}, {"id": "c", "text": "An orange and kiwi salad"}, {"id": "d", "text": "A tomato and sweet potato bake"}]'::jsonb, '["b"]', 'Shellfish such as oysters and crab are listed zinc sources. Apples and carrots are soluble fiber sources, oranges and kiwi are vitamin C sources, and tomatoes and sweet potatoes are potassium sources.'),
  ('vitamins', 21, 'A client is taught about dietary sources of zinc. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Chickpeas and lentils supply zinc."}, {"id": "b", "text": "Pumpkin and sesame seeds supply zinc."}, {"id": "c", "text": "Cashews and almonds supply zinc."}, {"id": "d", "text": "Apricots are a top source of zinc."}]'::jsonb, '["d"]', 'Apricots are listed as a vitamin A source, not a zinc source. Legumes (chickpeas, lentils), seeds (pumpkin, sesame), and nuts (cashews, almonds) are listed zinc sources.'),
  ('vitamins', 22, 'A client needs to increase vitamin A intake. Which snack should the nurse suggest?', '[{"id": "a", "text": "Carrot sticks and dried apricots"}, {"id": "b", "text": "Almonds and sunflower seeds"}, {"id": "c", "text": "Steamed oysters and crab"}, {"id": "d", "text": "Whole wheat crackers and oats"}]'::jsonb, '["a"]', 'Carrots and apricots are listed vitamin A sources. Almonds and sunflower seeds are vitamin E sources, oysters and crab are zinc sources, and whole wheat and oats are fiber sources.'),
  ('vitamins', 23, 'A client asks for a snack that is high in vitamin E. Which option should the nurse recommend?', '[{"id": "a", "text": "Egg yolks and fortified milk"}, {"id": "b", "text": "Oranges and strawberries"}, {"id": "c", "text": "Sunflower seeds and almonds"}, {"id": "d", "text": "Steamed oysters and crab"}]'::jsonb, '["c"]', 'Almonds and sunflower seeds are listed vitamin E sources. Egg yolks and fortified milk are vitamin D sources, oranges and strawberries are vitamin C sources, and oysters and crab are zinc sources.'),
  ('vitamins', 24, 'A client asks which nutrients sweet potatoes provide. The nurse identifies sweet potatoes as a source of which nutrients?', '[{"id": "a", "text": "Potassium and vitamin A"}, {"id": "b", "text": "Vitamin D and zinc"}, {"id": "c", "text": "Calcium and vitamin K"}, {"id": "d", "text": "Iron and magnesium"}]'::jsonb, '["a"]', 'Sweet potatoes are listed under both potassium and vitamin A. They are not listed as sources of vitamin D, zinc, calcium, vitamin K, iron, or magnesium.'),
  ('vitamins', 25, 'A client asks which minerals avocados provide. Which response by the nurse is accurate?', '[{"id": "a", "text": "Potassium and magnesium"}, {"id": "b", "text": "Calcium and zinc"}, {"id": "c", "text": "Iron and calcium"}, {"id": "d", "text": "Zinc and iron only"}]'::jsonb, '["a"]', 'Avocados are listed as sources of potassium and magnesium (and vitamin E and healthy fats). They are not listed under calcium, zinc, or iron.'),
  ('vitamins', 26, 'A client is taught about food sources of vitamin C. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Bell peppers are a rich vitamin C source."}, {"id": "b", "text": "Egg yolks are a rich vitamin C source."}, {"id": "c", "text": "Kiwi is a rich vitamin C source."}, {"id": "d", "text": "Oranges are a rich vitamin C source."}]'::jsonb, '["b"]', 'Egg yolks are listed as a vitamin D source, not a vitamin C source. Oranges, bell peppers, and kiwi are listed vitamin C sources.'),
  ('vitamins', 27, 'A client asks how soluble fiber differs from insoluble fiber. Which description of soluble fiber is accurate?', '[{"id": "a", "text": "It adds bulk and speeds transit time."}, {"id": "b", "text": "It does not dissolve and slows digestion."}, {"id": "c", "text": "It dissolves in water and speeds transit."}, {"id": "d", "text": "It dissolves in water and slows digestion."}]'::jsonb, '["d"]', 'Soluble fiber dissolves in water and slows digestion. Adding bulk and speeding transit time describes insoluble fiber.'),
  ('vitamins', 28, 'A client wants foods that add bulk and speed transit time. Which choice should the nurse recommend?', '[{"id": "a", "text": "Oatmeal topped with sliced apples"}, {"id": "b", "text": "Citrus fruits and barley soup"}, {"id": "c", "text": "Whole wheat bread and brown rice"}, {"id": "d", "text": "Olive oil drizzled over salmon"}]'::jsonb, '["c"]', 'Insoluble fiber adds bulk and speeds transit time; whole wheat products and brown rice are listed insoluble fiber sources. Oats, apples, citrus, and barley are soluble fiber sources that slow digestion, and olive oil and salmon are healthy fats.'),
  ('vitamins', 29, 'A client wants a breakfast high in soluble fiber. Which choice should the nurse suggest?', '[{"id": "a", "text": "Egg yolks with fortified milk"}, {"id": "b", "text": "Cauliflower and potato hash"}, {"id": "c", "text": "Oatmeal with sliced apples"}, {"id": "d", "text": "Brown rice with green beans"}]'::jsonb, '["c"]', 'Oats and apples are listed soluble fiber sources. Cauliflower, potatoes, brown rice, and green beans are listed insoluble fiber sources, and egg yolks and fortified milk are vitamin D sources.'),
  ('vitamins', 30, 'A client is taught about dietary fiber. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Carrots and citrus contain soluble fiber."}, {"id": "b", "text": "Soluble fiber speeds up my transit time."}, {"id": "c", "text": "Cauliflower and green beans add bulk."}, {"id": "d", "text": "Barley is a source of soluble fiber."}]'::jsonb, '["b"]', 'Speeding transit time is a property of insoluble fiber; soluble fiber dissolves in water and slows digestion. Carrots, citrus, and barley are soluble fiber sources, and cauliflower and green beans are insoluble fiber that adds bulk.'),
  ('vitamins', 31, 'A client who does not eat meat needs more protein after surgery. Which foods should the nurse suggest?', '[{"id": "a", "text": "Olive oil and avocados"}, {"id": "b", "text": "Tofu, tempeh, and eggs"}, {"id": "c", "text": "Apples and citrus fruits"}, {"id": "d", "text": "Carrots and apricots"}]'::jsonb, '["b"]', 'Tofu, tempeh, and eggs are listed protein sources that contain no meat. Olive oil and avocados are healthy fats, apples and citrus are soluble fiber sources, and carrots and apricots are vitamin A sources.'),
  ('vitamins', 32, 'A client asks for snack ideas that contain healthy fats. Which snack should the nurse suggest?', '[{"id": "a", "text": "Apples with oranges"}, {"id": "b", "text": "Brown rice with quinoa"}, {"id": "c", "text": "Walnuts with flaxseeds"}, {"id": "d", "text": "Carrots with green beans"}]'::jsonb, '["c"]', 'Nuts and seeds such as walnuts and flaxseeds are listed healthy fats. Apples and oranges are fiber and vitamin C sources, brown rice and quinoa are complex carbohydrates, and carrots and green beans are fiber sources.'),
  ('vitamins', 33, 'A client is advised to choose complex carbohydrates. Which selection reflects this advice?', '[{"id": "a", "text": "Quinoa and barley"}, {"id": "b", "text": "Olive oil and walnuts"}, {"id": "c", "text": "Eggs and salmon"}, {"id": "d", "text": "Cheese and yogurt"}]'::jsonb, '["a"]', 'Brown rice, quinoa, and barley are listed complex carbohydrates. Olive oil and walnuts are healthy fats, eggs and salmon are protein sources, and cheese and yogurt are dairy calcium sources.'),
  ('vitamins', 34, 'A client is taught about healthy fats. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Whole wheat pasta is a healthy fat."}, {"id": "b", "text": "Olive oil is a healthy fat."}, {"id": "c", "text": "Salmon provides healthy fats."}, {"id": "d", "text": "Dark chocolate is a healthy fat source."}]'::jsonb, '["a"]', 'Whole wheat bread and pasta are listed complex carbohydrates, not healthy fats. Olive oil, fatty fish such as salmon, and dark chocolate are listed healthy fats.'),
  ('vitamins', 35, 'The nurse recommends salmon twice weekly for a client. Salmon provides which combination of nutrients?', '[{"id": "a", "text": "Vitamin D and healthy fats"}, {"id": "b", "text": "Vitamin C and soluble fiber"}, {"id": "c", "text": "Vitamin K and complex carbohydrates"}, {"id": "d", "text": "Vitamin A and insoluble fiber"}]'::jsonb, '["a"]', 'Fatty fish such as salmon is listed under both vitamin D and healthy fats. It is not listed as a source of vitamin C, vitamin K, vitamin A, fiber, or complex carbohydrates.'),
  ('vitamins', 36, 'A client who avoids dairy asks what fortified plant-based milk provides. The nurse identifies which nutrients?', '[{"id": "a", "text": "Vitamin C and zinc"}, {"id": "b", "text": "Vitamin K and iron"}, {"id": "c", "text": "Potassium and vitamin A"}, {"id": "d", "text": "Calcium and vitamin D"}]'::jsonb, '["d"]', 'Fortified plant-based milks are listed under both calcium and vitamin D. They are not listed under vitamin C, zinc, vitamin K, iron, potassium, or vitamin A.'),
  ('vitamins', 37, 'A client with iron deficiency wants a breakfast that maximizes iron absorption. Which choice should the nurse recommend?', '[{"id": "a", "text": "Oatmeal topped with walnuts"}, {"id": "b", "text": "Whole wheat toast with avocado"}, {"id": "c", "text": "Fortified cereal with kiwi slices"}, {"id": "d", "text": "Plain yogurt with flaxseeds"}]'::jsonb, '["c"]', 'Fortified cereal is an iron source, and kiwi supplies vitamin C, which enhances iron absorption. The other choices lack a listed vitamin C source paired with an iron source.'),
  ('vitamins', 38, 'A client with hypokalemia is taught about potassium-rich foods. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Tomatoes and sweet potatoes provide potassium."}, {"id": "b", "text": "Bananas help raise my potassium."}, {"id": "c", "text": "Egg yolks are my best potassium source."}, {"id": "d", "text": "Spinach is a source of potassium."}]'::jsonb, '["c"]', 'Egg yolks are listed as a vitamin D source, not a potassium source. Bananas, sweet potatoes, spinach, avocados, and tomatoes are listed potassium sources.'),
  ('vitamins', 39, 'A client with low magnesium is taught about food sources. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Black beans provide magnesium."}, {"id": "b", "text": "Whole grains provide magnesium."}, {"id": "c", "text": "Oranges are a main magnesium source."}, {"id": "d", "text": "Pumpkin seeds provide magnesium."}]'::jsonb, '["c"]', 'Oranges are listed as a vitamin C source, not a magnesium source. Black beans, whole grains, and nuts and seeds such as pumpkin seeds are listed magnesium sources.'),
  ('vitamins', 40, 'The nurse is reviewing nutrient deficiencies with a group of clients. Which pairing of deficiency and clinical finding is correct?', '[{"id": "a", "text": "Low potassium — tetany"}, {"id": "b", "text": "Low iron — microcytic anemia"}, {"id": "c", "text": "Low magnesium — microcytic anemia"}, {"id": "d", "text": "Low vitamin D — impaired clotting"}]'::jsonb, '["b"]', 'Low iron causes microcytic anemia. Tetany is linked to low calcium, low potassium to arrhythmias, low magnesium to cramps and seizures, and clotting depends on vitamin K.'),
  ('vitamins', 41, 'A client asks about the roles of several vitamins. Which nutrient–function pairing stated by the nurse is correct?', '[{"id": "a", "text": "Vitamin K — required for clotting"}, {"id": "b", "text": "Vitamin D — required for clotting"}, {"id": "c", "text": "Vitamin K — calcium absorption"}, {"id": "d", "text": "Vitamin E — enhances iron absorption"}]'::jsonb, '["a"]', 'Vitamin K is required for clotting factors II, VII, IX, and X. Vitamin D is required for calcium absorption, and vitamin C (not vitamin E) enhances iron absorption.'),
  ('vitamins', 42, 'A client reports frequent muscle cramps and then has a seizure. Which nutrient deficiency is most consistent with these findings?', '[{"id": "a", "text": "Iron"}, {"id": "b", "text": "Vitamin K"}, {"id": "c", "text": "Magnesium"}, {"id": "d", "text": "Vitamin C"}]'::jsonb, '["c"]', 'Low magnesium causes muscle cramps and seizures. Low iron causes microcytic anemia, vitamin K is needed for clotting, and vitamin C enhances iron absorption.'),
  ('vitamins', 43, 'A client on telemetry develops a new arrhythmia, and the nurse reviews the client''s nutritional status. A deficiency of which nutrient is most consistent with this finding?', '[{"id": "a", "text": "Iron"}, {"id": "b", "text": "Zinc"}, {"id": "c", "text": "Vitamin E"}, {"id": "d", "text": "Potassium"}]'::jsonb, '["d"]', 'Low potassium (hypokalemia) is associated with arrhythmias. Low iron is associated with microcytic anemia, and zinc and vitamin E deficiencies are not linked to arrhythmias.'),
  ('vitamins', 44, 'A client who drinks milk daily continues to have a low calcium level. The nurse suspects an additional deficiency of which vitamin?', '[{"id": "a", "text": "Vitamin K"}, {"id": "b", "text": "Vitamin D"}, {"id": "c", "text": "Vitamin C"}, {"id": "d", "text": "Vitamin E"}]'::jsonb, '["b"]', 'Vitamin D is required for calcium absorption, so a deficiency can keep calcium low despite intake. Vitamin K is needed for clotting, and vitamin C enhances iron absorption.'),
  ('vitamins', 45, 'A client with iron-deficiency anemia is taught how to improve iron absorption. Which statement by the client indicates understanding?', '[{"id": "a", "text": "I''ll drink fortified milk with my lentils."}, {"id": "b", "text": "I''ll add olive oil to my spinach."}, {"id": "c", "text": "I''ll eat sardines along with my beef."}, {"id": "d", "text": "I''ll eat strawberries with my fortified cereal."}]'::jsonb, '["d"]', 'Strawberries are a vitamin C source, and vitamin C enhances iron absorption from foods such as fortified cereal. Fortified milk, olive oil, and sardines are not vitamin C sources.'),
  ('vitamins', 46, 'A client with low calcium is taught about calcium sources. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Tofu is a good calcium source."}, {"id": "b", "text": "Sardines are a good calcium source."}, {"id": "c", "text": "Apples are a good calcium source."}, {"id": "d", "text": "Yogurt is a good calcium source."}]'::jsonb, '["c"]', 'Apples are listed as a soluble fiber source, not a calcium source. Dairy such as yogurt, sardines, and tofu are listed calcium sources.'),
  ('vitamins', 47, 'A client asks why lentils are included in a meal plan. The nurse explains that lentils provide which nutrients?', '[{"id": "a", "text": "Vitamin D and vitamin A"}, {"id": "b", "text": "Protein and iron"}, {"id": "c", "text": "Healthy fats and vitamin D"}, {"id": "d", "text": "Vitamin C and vitamin E"}]'::jsonb, '["b"]', 'Lentils and beans are listed iron sources, and legumes are listed protein sources. Lentils are not listed under vitamin D, vitamin A, healthy fats, vitamin C, or vitamin E.'),
  ('vitamins', 48, 'A client needs a lunch based on complex carbohydrates. Which selection should the nurse recommend?', '[{"id": "a", "text": "Salmon with an olive oil drizzle"}, {"id": "b", "text": "A plate of cheese and yogurt"}, {"id": "c", "text": "Walnuts with dark chocolate"}, {"id": "d", "text": "Barley soup with whole wheat bread"}]'::jsonb, '["d"]', 'Barley and whole wheat bread are listed complex carbohydrates. Salmon, olive oil, walnuts, and dark chocolate are healthy fats, and cheese and yogurt are dairy calcium sources.'),
  ('vitamins', 49, 'A client is taught about vitamin A sources. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Carrots are a good vitamin A source."}, {"id": "b", "text": "Sunflower seeds are my best vitamin A source."}, {"id": "c", "text": "Apricots are a good vitamin A source."}, {"id": "d", "text": "Sweet potatoes supply vitamin A for me."}]'::jsonb, '["b"]', 'Sunflower seeds are listed as a vitamin E source, not a vitamin A source. Carrots, sweet potatoes, spinach/kale, and apricots are listed vitamin A sources.'),
  ('vitamins', 50, 'A client asks for a list of foods rich in vitamin E. Which list should the nurse provide?', '[{"id": "a", "text": "Oranges, kiwi, red bell peppers"}, {"id": "b", "text": "Carrots, apricots, sweet potatoes"}, {"id": "c", "text": "Almonds, sunflower seeds, butternut squash"}, {"id": "d", "text": "Oysters, crab, lean beef, and pork"}]'::jsonb, '["c"]', 'Almonds, sunflower seeds, and butternut squash are listed vitamin E sources. Oranges, kiwi, and bell peppers are vitamin C sources, carrots, apricots, and sweet potatoes are vitamin A sources, and oysters, crab, and beef are zinc sources.'),
  ('vegan', 1, 'A client tells the nurse about starting a vegan diet last month. Which food should the nurse identify as excluded from this diet?', '[{"id": "a", "text": "Quinoa"}, {"id": "b", "text": "Honey"}, {"id": "c", "text": "Tempeh"}, {"id": "d", "text": "Bok choy"}]'::jsonb, '["b"]', 'A vegan diet excludes all animal-derived products, including honey. Quinoa and tempeh are listed vegan protein sources, and bok choy is a listed vegan calcium source.'),
  ('vegan', 2, 'The nurse is developing a teaching plan for a client who recently became vegan. Which topic is the priority to include?', '[{"id": "a", "text": "Avoiding all soy-based protein foods"}, {"id": "b", "text": "Limiting intake of leafy green vegetables"}, {"id": "c", "text": "Need for a B12 supplement or fortified foods"}, {"id": "d", "text": "Avoiding fortified plant-based milks"}]'::jsonb, '["c"]', 'Vitamin B12 is not found in plants, so vegans require supplements or fortified foods. Tofu, leafy greens, and fortified plant milks are recommended vegan sources and should not be avoided.'),
  ('vegan', 3, 'The nurse reviews a meal tray for a client who follows a vegetarian diet. Which item is inappropriate for this client?', '[{"id": "a", "text": "Scrambled eggs"}, {"id": "b", "text": "Plain Greek yogurt"}, {"id": "c", "text": "Baked fish fillet"}, {"id": "d", "text": "Lentil vegetable soup"}]'::jsonb, '["c"]', 'A vegetarian diet excludes meat, poultry, and fish but may include eggs and dairy. Eggs, yogurt, and lentil soup are acceptable.'),
  ('vegan', 4, 'Which menu item is acceptable for a client following a vegetarian diet but NOT for a client following a vegan diet?', '[{"id": "a", "text": "Grilled chicken"}, {"id": "b", "text": "Cheese omelet"}, {"id": "c", "text": "Tofu stir-fry"}, {"id": "d", "text": "Baked salmon"}]'::jsonb, '["b"]', 'Vegetarians may include eggs and dairy, while vegans exclude all animal-derived products, so a cheese omelet fits only the vegetarian diet. Chicken and salmon are excluded from both diets, and tofu fits both.'),
  ('vegan', 5, 'A vegan client states, "I eat plenty of leafy greens, so I get enough vitamin B12." Which response by the nurse is best?', '[{"id": "a", "text": "Leafy greens provide enough B12 as long as you eat them daily."}, {"id": "b", "text": "Adding chia seeds to meals will meet your B12 needs."}, {"id": "c", "text": "Regular sunlight exposure will meet your daily B12 needs."}, {"id": "d", "text": "B12 is not in plants, so you need fortified foods or a supplement."}]'::jsonb, '["d"]', 'Vitamin B12 is not found in plants, so fortified foods or supplements are required. Chia seeds are an omega-3 source, and sunlight is a vitamin D source.'),
  ('vegan', 6, 'The nurse is admitting a client who follows a vegan diet. Which assessment is most important to include?', '[{"id": "a", "text": "Signs of excess protein from tofu intake"}, {"id": "b", "text": "Signs of excess calcium from leafy greens"}, {"id": "c", "text": "Signs of excess vitamin D from sunlight"}, {"id": "d", "text": "Signs of B12 deficiency, such as neuropathy"}]'::jsonb, '["d"]', 'Vegan clients should always be assessed for B12 deficiency, which may present as neuropathy or anemia. The diet''s concerns are deficiencies, not excesses of protein, calcium, or vitamin D.'),
  ('vegan', 7, 'A vegan client reports numbness and tingling in both feet, and laboratory results show anemia. The nurse suspects a deficiency of which nutrient?', '[{"id": "a", "text": "Omega-3"}, {"id": "b", "text": "Protein"}, {"id": "c", "text": "Vitamin B12"}, {"id": "d", "text": "Vitamin D"}]'::jsonb, '["c"]', 'B12 deficiency in vegan clients may present as neuropathy or anemia, matching this client''s findings. Omega-3, protein, and vitamin D are not identified as causes of neuropathy with anemia.'),
  ('vegan', 8, 'A vegan client with low iron plans a lentil dinner. Which addition should the nurse suggest to increase iron absorption?', '[{"id": "a", "text": "A handful of walnuts"}, {"id": "b", "text": "Red bell pepper strips"}, {"id": "c", "text": "A sprinkle of flaxseeds"}, {"id": "d", "text": "A side of plain quinoa"}]'::jsonb, '["b"]', 'Non-heme iron should be combined with vitamin C sources such as citrus or peppers to increase absorption. Walnuts and flaxseeds are omega-3 sources, and quinoa is a protein source.'),
  ('vegan', 9, 'A vegan client needs more iron. Which meal provides the best sources of non-heme iron?', '[{"id": "a", "text": "Chickpea and tofu curry with enriched rice"}, {"id": "b", "text": "Orange and grapefruit slices with bell peppers"}, {"id": "c", "text": "A flaxseed oil dressing over mixed greens"}, {"id": "d", "text": "A tall glass of fortified plant milk"}]'::jsonb, '["a"]', 'Chickpeas, tofu, and enriched grains are listed non-heme iron sources. Citrus fruit is a vitamin C source that aids absorption, flaxseed is an omega-3 source, and fortified plant milk is a calcium source.'),
  ('vegan', 10, 'The nurse is caring for several clients who follow vegetarian diets. Which client should the nurse monitor most closely for iron deficiency?', '[{"id": "a", "text": "A 26-year-old menstruating woman"}, {"id": "b", "text": "A 45-year-old man"}, {"id": "c", "text": "A 72-year-old postmenopausal woman"}, {"id": "d", "text": "A 30-year-old man who eats eggs"}]'::jsonb, '["a"]', 'Iron should still be monitored in vegetarians, especially in menstruating women. The other clients do not have this added risk factor.'),
  ('vegan', 11, 'Which vegetarian client is at greatest risk for vitamin B12 deficiency?', '[{"id": "a", "text": "A client who eats both eggs and dairy"}, {"id": "b", "text": "A client who eats eggs, dairy, and fortified cereal"}, {"id": "c", "text": "A client who eats eggs and dairy and takes B12"}, {"id": "d", "text": "A client who eats dairy but no eggs"}]'::jsonb, '["d"]', 'Among vegetarians, B12 is a particular concern in lacto-vegetarians, who eat dairy only and no eggs. Clients eating both eggs and dairy, or using fortified foods or supplements, have lower risk.'),
  ('vegan', 12, 'A client who has followed a vegetarian diet plans to become vegan. Which statement by the nurse is accurate?', '[{"id": "a", "text": "You will need to plan more for protein, B12, and calcium."}, {"id": "b", "text": "Your B12 needs will be easier to meet than before."}, {"id": "c", "text": "Your calcium needs will be easier to meet than before."}, {"id": "d", "text": "Your nutrient needs will stay the same as they are now."}]'::jsonb, '["a"]', 'Vegetarians typically meet protein, B12, and calcium needs more easily than vegans, so switching to a vegan diet requires closer planning. The other statements reverse or ignore this difference.'),
  ('vegan', 13, 'A vegan client has a low calcium intake. Which foods should the nurse recommend?', '[{"id": "a", "text": "Lentils with enriched rice"}, {"id": "b", "text": "Fortified plant milk and bok choy"}, {"id": "c", "text": "Citrus fruit and bell peppers"}, {"id": "d", "text": "Quinoa with walnuts"}]'::jsonb, '["b"]', 'Fortified plant milks and leafy greens such as bok choy are listed vegan calcium sources. Lentils and enriched grains are iron sources, citrus and peppers are vitamin C sources, and quinoa and walnuts are protein and omega-3 sources.'),
  ('vegan', 14, 'A vegan client asks how to obtain enough vitamin D. Which response by the nurse is accurate?', '[{"id": "a", "text": "Sunlight, fortified foods, or supplements"}, {"id": "b", "text": "Leafy greens such as kale or bok choy"}, {"id": "c", "text": "Walnuts, chia seeds, and flaxseeds"}, {"id": "d", "text": "Lentils, chickpeas, and enriched grains"}]'::jsonb, '["a"]', 'For vegans, vitamin D comes from sunlight, fortified foods, or supplements. Kale is a calcium source, walnuts and chia are omega-3 sources, and lentils and chickpeas are iron and protein sources.'),
  ('vegan', 15, 'A vegan client asks how to obtain omega-3 fatty acids. Which recommendation by the nurse is appropriate?', '[{"id": "a", "text": "Flaxseeds, chia seeds, and walnuts"}, {"id": "b", "text": "Fish oil capsules taken with meals"}, {"id": "c", "text": "Enriched grains and lentils"}, {"id": "d", "text": "Bok choy, kale, and almonds"}]'::jsonb, '["a"]', 'Flaxseeds, chia seeds, and walnuts are listed vegan omega-3 (ALA) sources. Fish oil is animal-derived and excluded from a vegan diet, enriched grains and lentils are iron sources, and bok choy and kale are calcium sources.'),
  ('vegan', 16, 'A vegan client asks about taking an algae-based supplement. The nurse explains that this supplement is considered to provide which nutrient?', '[{"id": "a", "text": "Calcium"}, {"id": "b", "text": "Omega-3 DHA"}, {"id": "c", "text": "Iron"}, {"id": "d", "text": "Protein"}]'::jsonb, '["b"]', 'Algae-based DHA supplements are suggested for omega-3 intake in vegans. Calcium, iron, and protein come from foods such as fortified plant milks, lentils, and tofu.'),
  ('vegan', 17, 'A vegan client asks how to avoid foods with hidden animal ingredients. Which instruction should the nurse give?', '[{"id": "a", "text": "Choose any product labeled vegetarian."}, {"id": "b", "text": "Avoid only the foods that contain any meat."}, {"id": "c", "text": "Read food labels for animal-derived ingredients."}, {"id": "d", "text": "Assume all packaged breads are plant-based."}]'::jsonb, '["c"]', 'Vegan clients should be taught label reading to identify hidden animal-derived ingredients. Vegetarian products may contain eggs and dairy, and vegans exclude all animal products, not just meat.'),
  ('vegan', 18, 'A client who follows a vegan diet is prescribed enteral feedings through an NG tube. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Give any available formula since nutrition is the priority."}, {"id": "b", "text": "Ask the client to suspend the vegan diet while hospitalized."}, {"id": "c", "text": "Verify the formula aligns with the client''s vegan diet."}, {"id": "d", "text": "Hold feedings until the client can eat by mouth."}]'::jsonb, '["c"]', 'NG and hospital diets should respect the client''s dietary preferences, so the nurse verifies the formula fits a vegan diet. Ignoring or suspending the preference, or withholding feeding, is inappropriate.'),
  ('vegan', 19, 'A pregnant client who follows a vegan diet asks for help planning meals. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Advise stopping the vegan diet during pregnancy."}, {"id": "b", "text": "Collaborate with a dietitian on a meal plan."}, {"id": "c", "text": "Tell the client B12 is not needed in pregnancy."}, {"id": "d", "text": "Recommend a vegetarian diet instead."}]'::jsonb, '["b"]', 'Complex cases such as pregnant vegan clients call for collaboration with a dietitian. Telling the client to abandon the diet ignores dietary preferences, and B12 remains a high-risk nutrient for vegans.'),
  ('vegan', 20, 'A vegan client asks why tofu is often recommended. Which response by the nurse is accurate?', '[{"id": "a", "text": "It naturally provides vitamin B12."}, {"id": "b", "text": "It is a source of algae-based DHA."}, {"id": "c", "text": "It provides iron, protein, and calcium."}, {"id": "d", "text": "It replaces the need for vitamin D."}]'::jsonb, '["c"]', 'Tofu is listed as a vegan source of non-heme iron, protein, and calcium. B12 is not found in plants, DHA comes from algae-based supplements, and vitamin D comes from sunlight, fortified foods, or supplements.'),
  ('vegan', 21, 'A nurse plans nutrition screening for a client who recently became vegan. Deficiency of which nutrient carries the highest risk for this client?', '[{"id": "a", "text": "Vitamin B12"}, {"id": "b", "text": "Protein"}, {"id": "c", "text": "Calcium"}, {"id": "d", "text": "Omega-3"}]'::jsonb, '["a"]', 'Vitamin B12 is rated a high risk for vegans, and vegan clients should always be assessed for B12 deficiency. Protein is low–moderate risk, and calcium and omega-3 are moderate risk.'),
  ('vegan', 22, 'Which statement by a vegan client indicates a need for further teaching about protein?', '[{"id": "a", "text": "Beans and lentils are good protein sources."}, {"id": "b", "text": "Tempeh and tofu provide protein."}, {"id": "c", "text": "Quinoa, nuts, and seeds add protein."}, {"id": "d", "text": "I cannot get protein without eating meat or eggs."}]'::jsonb, '["d"]', 'Vegans can obtain protein from beans, lentils, tofu, quinoa, tempeh, nuts, and seeds. The belief that protein requires meat or eggs needs correction.'),
  ('vegan', 23, 'A vegan client asks for a lunch that is high in protein. Which meal should the nurse suggest?', '[{"id": "a", "text": "Kale salad with orange slices"}, {"id": "b", "text": "Bell pepper strips with citrus"}, {"id": "c", "text": "Steamed bok choy with peppers"}, {"id": "d", "text": "Tempeh and quinoa bowl with seeds"}]'::jsonb, '["d"]', 'Tempeh, quinoa, and seeds are listed vegan protein sources. Kale and bok choy are calcium sources, and oranges, citrus, and peppers are vitamin C sources.'),
  ('vegan', 24, 'A client who follows a vegetarian diet asks about meeting protein needs. Which response by the nurse is appropriate?', '[{"id": "a", "text": "Protein is less of a concern; eat a variety."}, {"id": "b", "text": "Daily protein supplements are required."}, {"id": "c", "text": "Protein is your highest-risk nutrient."}, {"id": "d", "text": "Protein needs cannot be met without eating meat."}]'::jsonb, '["a"]', 'For vegetarians, protein is less of a concern, but variety should be emphasized. Supplements are not required, and protein is a low risk for vegetarians.'),
  ('vegan', 25, 'A lacto-vegetarian client states, "Because I eat dairy, I never need to think about vitamin B12." How should the nurse interpret this statement?', '[{"id": "a", "text": "It indicates a need for teaching about B12 risk."}, {"id": "b", "text": "It is accurate because dairy removes all B12 risk."}, {"id": "c", "text": "It is accurate because B12 is found in plants."}, {"id": "d", "text": "It indicates the client should avoid all dairy."}]'::jsonb, '["a"]', 'B12 is a particular concern in lacto-vegetarians (dairy only, no eggs), so the client needs teaching. B12 is not in plants, and avoiding dairy is not recommended.'),
  ('vegan', 26, 'A vegan client began B12 supplementation for a deficiency. Which finding indicates the treatment is effective?', '[{"id": "a", "text": "New tingling in the hands"}, {"id": "b", "text": "Resolution of numbness and anemia"}, {"id": "c", "text": "Worsening fatigue and pallor"}, {"id": "d", "text": "Persistent anemia on lab results"}]'::jsonb, '["b"]', 'B12 deficiency may present as neuropathy or anemia, so resolution of numbness and anemia shows improvement. New tingling, worsening fatigue, or persistent anemia indicates ongoing deficiency.'),
  ('vegan', 27, 'The nurse observes a UAP delivering meal trays. Which action by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "Serving a cheese sandwich to a vegetarian client"}, {"id": "b", "text": "Serving scrambled eggs to a vegetarian client"}, {"id": "c", "text": "Serving lentil soup to a vegan client"}, {"id": "d", "text": "Serving chicken noodle soup to a vegetarian client"}]'::jsonb, '["d"]', 'Vegetarian diets exclude meat, poultry, and fish, so chicken soup is inappropriate. Vegetarians may include eggs and dairy, and lentils fit a vegan diet.'),
  ('vegan', 28, 'Which meal delivery by the UAP requires correction?', '[{"id": "a", "text": "Serving a tofu stir-fry to a vegan client"}, {"id": "b", "text": "Serving egg salad to a vegetarian client"}, {"id": "c", "text": "Serving quinoa salad to a vegan client"}, {"id": "d", "text": "Serving a yogurt parfait to a vegan client"}]'::jsonb, '["d"]', 'A vegan diet excludes all animal-derived products, including dairy such as yogurt. Tofu and quinoa fit a vegan diet, and eggs may be included in a vegetarian diet.'),
  ('vegan', 29, 'Which statement by a vegan client indicates a need for further teaching about calcium?', '[{"id": "a", "text": "Almonds and tofu provide calcium."}, {"id": "b", "text": "Fortified plant milks provide me calcium."}, {"id": "c", "text": "Without dairy, no food can give me calcium."}, {"id": "d", "text": "Kale and bok choy provide calcium."}]'::jsonb, '["c"]', 'Vegans can obtain calcium from fortified plant milks, leafy greens such as kale and bok choy, tofu, and almonds. The belief that no food can provide calcium without dairy is incorrect.'),
  ('vegan', 30, 'A client who follows a vegetarian diet reports increasing fatigue. The nurse should assess for deficiency of which nutrients?', '[{"id": "a", "text": "Vitamin B12 or iron"}, {"id": "b", "text": "Protein or omega-3"}, {"id": "c", "text": "Calcium or vitamin D"}, {"id": "d", "text": "Omega-3 or calcium"}]'::jsonb, '["a"]', 'Anemia, fatigue, and neurological symptoms should prompt monitoring for B12 or iron deficiency. The other nutrient pairs are not identified as causes of fatigue.'),
  ('vegan', 31, 'Which finding in a client who follows a vegan diet should the nurse report to the health care provider?', '[{"id": "a", "text": "New numbness and tingling in both feet"}, {"id": "b", "text": "A preference for tofu at most meals"}, {"id": "c", "text": "Daily use of fortified plant-based milk"}, {"id": "d", "text": "Eating walnuts as a daily afternoon snack"}]'::jsonb, '["a"]', 'B12 deficiency in vegans may present as neuropathy, so new numbness and tingling should be reported. Tofu, fortified plant milk, and walnuts are appropriate vegan food choices.'),
  ('vegan', 32, 'A vegan client asks what to eat with chickpeas to absorb more iron. Which food should the nurse recommend?', '[{"id": "a", "text": "Almonds"}, {"id": "b", "text": "Citrus fruit"}, {"id": "c", "text": "Flaxseeds"}, {"id": "d", "text": "Fortified plant milk"}]'::jsonb, '["b"]', 'Non-heme iron should be combined with vitamin C sources such as citrus to increase absorption. Almonds and fortified plant milk are calcium sources, and flaxseeds are an omega-3 source.'),
  ('vegan', 33, 'Which statement by a vegan client indicates a need for further teaching about iron?', '[{"id": "a", "text": "Lentils and chickpeas provide iron."}, {"id": "b", "text": "Enriched grains provide iron."}, {"id": "c", "text": "Walnuts with lentils boost iron absorption."}, {"id": "d", "text": "Adding peppers helps me absorb more iron."}]'::jsonb, '["c"]', 'Iron absorption is increased by combining iron sources with vitamin C such as citrus or peppers, not walnuts, which are an omega-3 source. Lentils, chickpeas, and enriched grains are listed non-heme iron sources.'),
  ('vegan', 34, 'Which statement by a vegan client indicates a need for further teaching about vitamin D?', '[{"id": "a", "text": "Fortified foods can provide vitamin D."}, {"id": "b", "text": "A supplement can provide vitamin D."}, {"id": "c", "text": "Kale is my main source of vitamin D."}, {"id": "d", "text": "Sunlight helps provide vitamin D."}]'::jsonb, '["c"]', 'For vegans, vitamin D comes from sunlight, fortified foods, or supplements. Kale is listed as a calcium source, not a vitamin D source.'),
  ('vegan', 35, 'Which statement by a vegan client indicates a need for further teaching about vitamin B12?', '[{"id": "a", "text": "I''ll use fortified foods for my B12."}, {"id": "b", "text": "More lentils will cover my B12 needs."}, {"id": "c", "text": "I may need to take a B12 supplement."}, {"id": "d", "text": "B12 is not found in plant foods."}]'::jsonb, '["b"]', 'Vitamin B12 is not found in plants, so lentils cannot meet B12 needs; supplements or fortified foods are required. The other statements are accurate.'),
  ('vegan', 36, 'A vegan client wants a snack rich in omega-3 fatty acids. Which snack should the nurse suggest?', '[{"id": "a", "text": "Walnuts and chia seeds"}, {"id": "b", "text": "Bell pepper strips"}, {"id": "c", "text": "Enriched grain crackers"}, {"id": "d", "text": "Steamed bok choy"}]'::jsonb, '["a"]', 'Walnuts and chia seeds are listed vegan omega-3 sources. Bell peppers are a vitamin C source, enriched grains an iron source, and bok choy a calcium source.'),
  ('vegan', 37, 'A client following a vegan diet is ordering breakfast. Which choice is appropriate?', '[{"id": "a", "text": "Oatmeal made with whole cow''s milk"}, {"id": "b", "text": "Whole wheat toast with butter and honey"}, {"id": "c", "text": "Oatmeal made with fortified plant milk"}, {"id": "d", "text": "Scrambled eggs on whole wheat toast"}]'::jsonb, '["c"]', 'A vegan diet excludes all animal-derived products, including dairy, eggs, and honey. Fortified plant milk is an appropriate vegan choice.'),
  ('vegan', 38, 'Which statement by a vegan client indicates understanding of label-reading teaching?', '[{"id": "a", "text": "If a food has no meat, it is vegan."}, {"id": "b", "text": "Foods labeled vegetarian are always vegan."}, {"id": "c", "text": "I only need to check labels on meat products."}, {"id": "d", "text": "Some products contain hidden animal ingredients."}]'::jsonb, '["d"]', 'Vegan clients read labels because products can contain hidden animal-derived ingredients. Vegan diets exclude dairy, eggs, and honey as well as meat, and vegetarian foods may include eggs and dairy.'),
  ('vegan', 39, 'The nurse is reviewing referrals. Which client is the priority for a dietitian consultation?', '[{"id": "a", "text": "A pregnant client following a vegan diet"}, {"id": "b", "text": "An adult vegetarian with no symptoms"}, {"id": "c", "text": "An adult who includes eggs and dairy"}, {"id": "d", "text": "A vegetarian who eats varied proteins"}]'::jsonb, '["a"]', 'Complex cases, such as pregnant vegan clients, call for collaboration with a dietitian. The other clients have no identified complicating factors.'),
  ('vegan', 40, 'A client who follows a vegan diet is admitted to the hospital. Which nursing action best respects the client''s dietary preference?', '[{"id": "a", "text": "Order a regular tray and let the client choose items."}, {"id": "b", "text": "Order a vegan meal tray and document the preference."}, {"id": "c", "text": "Order a vegetarian tray that includes eggs and dairy."}, {"id": "d", "text": "Defer the diet preference until discharge."}]'::jsonb, '["b"]', 'Hospital diets should respect the client''s dietary preferences, so a vegan tray is ordered. A vegetarian tray may include eggs and dairy, which a vegan diet excludes.'),
  ('vegan', 41, 'A vegetarian client is a 25-year-old menstruating woman. Which nursing plan is appropriate?', '[{"id": "a", "text": "Omit iron monitoring because the risk is low."}, {"id": "b", "text": "Focus monitoring on protein as the top concern."}, {"id": "c", "text": "Monitor for omega-3 toxicity from flaxseed."}, {"id": "d", "text": "Continue to monitor her iron status."}]'::jsonb, '["d"]', 'Iron should still be monitored in vegetarians, especially menstruating women. Protein is less of a concern for vegetarians.'),
  ('vegan', 42, 'A vegan client asks what type of iron plant foods provide. Which response by the nurse is accurate?', '[{"id": "a", "text": "Heme iron, better absorbed with vitamin C"}, {"id": "b", "text": "Non-heme iron, better absorbed with vitamin C"}, {"id": "c", "text": "Non-heme iron, better absorbed with honey"}, {"id": "d", "text": "Heme iron, better absorbed with walnuts"}]'::jsonb, '["b"]', 'Vegan iron sources such as lentils, chickpeas, tofu, and enriched grains provide non-heme iron, which should be combined with vitamin C to increase absorption. Honey is excluded from a vegan diet, and walnuts are an omega-3 source.'),
  ('vegan', 43, 'A vegan client works night shifts and has little sun exposure. Which recommendation should the nurse make regarding vitamin D?', '[{"id": "a", "text": "Eat more lentils and chickpeas each day."}, {"id": "b", "text": "Add ground flaxseeds to each meal."}, {"id": "c", "text": "Use fortified foods or a vitamin D supplement."}, {"id": "d", "text": "Increase leafy green intake at meals."}]'::jsonb, '["c"]', 'Vegan vitamin D sources are sunlight, fortified foods, or supplements; with limited sun, fortified foods or supplements are needed. Lentils and chickpeas are iron sources, flaxseeds omega-3, and leafy greens calcium.'),
  ('vegan', 44, 'Which lunch best meets the calcium needs of a client who follows a vegan diet?', '[{"id": "a", "text": "Lentil soup with enriched grain bread"}, {"id": "b", "text": "Tofu with kale and fortified plant milk"}, {"id": "c", "text": "Quinoa salad with red bell peppers"}, {"id": "d", "text": "Chickpeas with fresh citrus slices"}]'::jsonb, '["b"]', 'Tofu, kale, and fortified plant milks are listed vegan calcium sources. Lentils, enriched grains, and chickpeas are iron sources, quinoa is a protein source, and peppers and citrus are vitamin C sources.'),
  ('vegan', 45, 'A vegan client who trains for marathons asks about protein-rich snacks. Which choice should the nurse suggest?', '[{"id": "a", "text": "Citrus fruit slices"}, {"id": "b", "text": "Bell pepper strips"}, {"id": "c", "text": "Nuts and seeds"}, {"id": "d", "text": "Steamed bok choy"}]'::jsonb, '["c"]', 'Nuts and seeds are listed vegan protein sources. Citrus and bell peppers are vitamin C sources, and bok choy is a calcium source.'),
  ('vegan', 46, 'Which client is at highest risk for vitamin B12 deficiency?', '[{"id": "a", "text": "A lacto-vegetarian client"}, {"id": "b", "text": "A vegetarian who eats eggs and dairy"}, {"id": "c", "text": "A vegetarian who uses fortified foods"}, {"id": "d", "text": "A client following a vegan diet"}]'::jsonb, '["d"]', 'B12 risk is high for vegans and moderate for lacto-vegetarians; vegans must always be assessed for B12 deficiency. Vegetarians who eat eggs and dairy or use fortified foods have lower risk.'),
  ('vegan', 47, 'Which statement by a vegan client indicates a need for further teaching about omega-3 fatty acids?', '[{"id": "a", "text": "Flaxseeds are a good omega-3 source."}, {"id": "b", "text": "Fish oil is a good omega-3 choice for me."}, {"id": "c", "text": "Chia seeds are a good omega-3 source."}, {"id": "d", "text": "Algae-based DHA is an option for me."}]'::jsonb, '["b"]', 'Fish oil is animal-derived and excluded from a vegan diet. Flaxseeds, chia seeds, walnuts, and algae-based DHA are appropriate vegan omega-3 sources.'),
  ('vegan', 48, 'A client who follows a vegetarian diet reports new numbness and difficulty concentrating. The nurse should assess for which deficiency?', '[{"id": "a", "text": "Omega-3 fatty acid excess"}, {"id": "b", "text": "Calcium or vitamin D excess"}, {"id": "c", "text": "Protein or omega-3 excess"}, {"id": "d", "text": "Vitamin B12 or iron deficiency"}]'::jsonb, '["d"]', 'Neurological symptoms in vegetarian clients should prompt monitoring for B12 or iron deficiency. The concern is deficiency, not excess of omega-3, calcium, or protein.'),
  ('vegan', 49, 'Which hospital diet order is appropriate for a vegetarian client who reports eating eggs and dairy?', '[{"id": "a", "text": "Vegetarian diet including eggs and dairy"}, {"id": "b", "text": "Regular diet with standard meat entrées"}, {"id": "c", "text": "Diet including fish but no red meat"}, {"id": "d", "text": "Diet including poultry but no beef or pork"}]'::jsonb, '["a"]', 'Hospital diets should respect the client''s preferences; a vegetarian diet may include eggs and dairy but excludes meat, poultry, and fish.'),
  ('vegan', 50, 'A vegan client asks whether a vegetarian friend faces the same nutrient challenges. The nurse explains that vegetarians typically meet which needs more easily than vegans?', '[{"id": "a", "text": "Omega-3, iron, and fiber"}, {"id": "b", "text": "Iron and omega-3 only"}, {"id": "c", "text": "None; the risks are identical"}, {"id": "d", "text": "Protein, B12, and calcium"}]'::jsonb, '["d"]', 'Vegetarians typically meet protein, B12, and calcium needs more easily than vegans. Iron still requires monitoring in vegetarians, so the risks are not identical.'),
  ('metabolic', 1, 'A male client has a waist circumference of 42 inches, BP 138/88 mmHg, fasting glucose 110 mg/dL, triglycerides 120 mg/dL, and HDL 45 mg/dL. How should the nurse interpret these findings?', '[{"id": "a", "text": "Does not meet criteria; only 2 of 5 present"}, {"id": "b", "text": "Meets criteria for metabolic syndrome; 3 of 5 present"}, {"id": "c", "text": "Meets criteria for metabolic syndrome; 5 of 5 present"}, {"id": "d", "text": "Does not meet criteria; 4 of 5 are required"}]'::jsonb, '["b"]', 'Waist >40 in (men), BP >130/85, and fasting glucose >100 are met, while triglycerides (not >150) and HDL (not <40 for men) are not; 3 of 5 meets the diagnosis. Diagnosis requires at least 3, not 4, criteria.'),
  ('metabolic', 2, 'A female client has a waist circumference of 33 inches, BP 124/78 mmHg, fasting glucose 96 mg/dL, triglycerides 180 mg/dL, and HDL 45 mg/dL. How should the nurse interpret these findings?', '[{"id": "a", "text": "Does not meet criteria; 2 of 5 present"}, {"id": "b", "text": "Meets criteria; 3 of 5 present"}, {"id": "c", "text": "Meets criteria; 4 of 5 present"}, {"id": "d", "text": "Does not meet criteria; 1 of 5 present"}]'::jsonb, '["a"]', 'Triglycerides >150 and HDL <50 for a woman are met, but waist (not >35), BP, and glucose are not, so only 2 of 5 criteria are present. An HDL of 45 counts as low for a woman, so there are 2 criteria, not 1.'),
  ('metabolic', 3, 'The nurse reviews lipid results for several clients. Which client''s HDL level meets a metabolic syndrome criterion?', '[{"id": "a", "text": "A man with an HDL of 46 mg/dL"}, {"id": "b", "text": "A woman with an HDL of 58 mg/dL"}, {"id": "c", "text": "A man with an HDL of 44 mg/dL"}, {"id": "d", "text": "A woman with an HDL of 46 mg/dL"}]'::jsonb, '["d"]', 'Low HDL is defined as <40 mg/dL for men and <50 mg/dL for women, so 46 mg/dL meets the criterion only for a woman. Men with HDL of 44 or 46 mg/dL are above the male cutoff.'),
  ('metabolic', 4, 'The nurse measures waist circumference for several clients. Which client meets the abdominal obesity criterion for metabolic syndrome?', '[{"id": "a", "text": "A man with a 38-inch waist"}, {"id": "b", "text": "A woman with a 33-inch waist"}, {"id": "c", "text": "A man with a 36-inch waist"}, {"id": "d", "text": "A woman with a 37-inch waist"}]'::jsonb, '["d"]', 'Abdominal obesity is a waist >35 in for women or >40 in for men, so a woman with a 37-inch waist meets it. The men listed are below 40 in, and 33 in is below the female cutoff.'),
  ('metabolic', 5, 'The nurse reviews a client''s recent results. Which finding meets a metabolic syndrome criterion?', '[{"id": "a", "text": "Fasting glucose of 92 mg/dL"}, {"id": "b", "text": "Triglycerides of 190 mg/dL"}, {"id": "c", "text": "HDL of 58 mg/dL in a man"}, {"id": "d", "text": "Blood pressure of 122/78 mmHg"}]'::jsonb, '["b"]', 'High triglycerides are defined as >150 mg/dL, so 190 mg/dL meets the criterion. Fasting glucose must exceed 100 mg/dL, low HDL in a man is <40 mg/dL, and BP must exceed 130/85 mmHg.'),
  ('metabolic', 6, 'A female client has a waist of 36 inches, fasting glucose 108 mg/dL, BP 126/80 mmHg, triglycerides 140 mg/dL, and HDL 52 mg/dL. Which additional finding would confirm metabolic syndrome?', '[{"id": "a", "text": "HDL of 55 mg/dL"}, {"id": "b", "text": "Blood pressure of 128/82 mmHg"}, {"id": "c", "text": "Triglycerides of 175 mg/dL"}, {"id": "d", "text": "Waist circumference of 38 inches"}]'::jsonb, '["c"]', 'The client already meets 2 criteria (waist >35 in and glucose >100), so a third new criterion such as triglycerides >150 mg/dL confirms the diagnosis. A larger waist does not add a new criterion, and the HDL and BP values listed are not abnormal.'),
  ('metabolic', 7, 'A client newly diagnosed with metabolic syndrome is taught about the condition. Which statement by the client indicates understanding?', '[{"id": "a", "text": "It raises my risk for heart disease and stroke."}, {"id": "b", "text": "It only affects my weight and my appearance."}, {"id": "c", "text": "It is caused by a lack of the lactase enzyme."}, {"id": "d", "text": "It is a deficiency of one vitamin in my diet."}]'::jsonb, '["a"]', 'Metabolic syndrome is a cluster of conditions that increase the risk of heart disease, diabetes, and stroke. Lactase deficiency causes lactose intolerance, and the syndrome is not a single-vitamin deficiency.'),
  ('metabolic', 8, 'A client with triglycerides of 210 mg/dL says, "I feel fine, so this can''t be a problem." Which response by the nurse is best?', '[{"id": "a", "text": "High triglycerides usually cause painful swelling of the big toe."}, {"id": "b", "text": "High triglycerides usually cause no symptoms but raise heart risk."}, {"id": "c", "text": "High triglycerides usually cause bleeding gums and easy bruising."}, {"id": "d", "text": "High triglycerides usually cause bloating after eating dairy."}]'::jsonb, '["b"]', 'High triglycerides usually produce no symptoms but increase heart disease risk. Big-toe swelling describes gout, bleeding gums describe scurvy, and bloating after dairy describes lactose intolerance.'),
  ('metabolic', 9, 'A male client has an HDL of 35 mg/dL and no symptoms. The nurse explains that this finding increases his risk for which problem?', '[{"id": "a", "text": "Scurvy"}, {"id": "b", "text": "Clogged arteries"}, {"id": "c", "text": "Osteoporosis"}, {"id": "d", "text": "Lactose intolerance"}]'::jsonb, '["b"]', 'Low HDL (<40 mg/dL in men) causes no symptoms but increases the risk of clogged arteries. Scurvy results from vitamin C deficiency, osteoporosis from calcium deficiency, and lactose intolerance from lack of lactase.'),
  ('metabolic', 10, 'A client with metabolic syndrome asks how the condition can affect the kidneys. Which response by the nurse is accurate?', '[{"id": "a", "text": "Low HDL levels directly cause repeated kidney infections."}, {"id": "b", "text": "High blood glucose and blood pressure can damage the kidneys."}, {"id": "c", "text": "High triglycerides form stones within the kidney tissue."}, {"id": "d", "text": "Abdominal fat compresses and blocks blood flow to the kidneys."}]'::jsonb, '["b"]', 'Kidney disease is a complication of metabolic syndrome because high blood glucose and blood pressure damage the kidneys. The other mechanisms are not identified as causes of kidney disease.'),
  ('metabolic', 11, 'A client with metabolic syndrome asks which complication results from blocked arteries. Which response by the nurse is accurate?', '[{"id": "a", "text": "Chronic kidney disease"}, {"id": "b", "text": "Type 2 diabetes mellitus"}, {"id": "c", "text": "Heart attack and stroke"}, {"id": "d", "text": "Celiac disease"}]'::jsonb, '["c"]', 'Heart attack and stroke are complications caused by blocked arteries. Kidney disease results from high blood glucose and blood pressure, type 2 diabetes from being unable to use insulin properly, and celiac disease is an autoimmune reaction to gluten.'),
  ('metabolic', 12, 'During a health history, which finding should the nurse identify as a risk factor for metabolic syndrome?', '[{"id": "a", "text": "A deficiency of the lactase enzyme"}, {"id": "b", "text": "An autoimmune reaction to gluten"}, {"id": "c", "text": "A family history of diabetes"}, {"id": "d", "text": "Limited exposure to sunlight"}]'::jsonb, '["c"]', 'Genetics, such as a family history of diabetes or heart disease, is a cause of metabolic syndrome. Lactase deficiency causes lactose intolerance, a gluten reaction causes celiac disease, and lack of sunlight causes vitamin D deficiency.'),
  ('metabolic', 13, 'A client reports eating sweets daily and rarely exercising. Which factors should the nurse identify as contributing to metabolic syndrome?', '[{"id": "a", "text": "High-sugar diet and lack of exercise"}, {"id": "b", "text": "Lack of sunlight and low dairy intake"}, {"id": "c", "text": "Gluten intake and low lactase levels"}, {"id": "d", "text": "Low fruit intake and poor sun exposure"}]'::jsonb, '["a"]', 'An unhealthy diet with too much sugar and fat and a lack of exercise are causes of metabolic syndrome. The other factors relate to vitamin D, calcium, or vitamin C deficiencies, celiac disease, and lactose intolerance.'),
  ('metabolic', 14, 'A client with metabolic syndrome weighs 220 lb. Which initial weight-loss goal should the nurse recommend to reduce risk?', '[{"id": "a", "text": "11 to 22 lb"}, {"id": "b", "text": "2 to 4 lb"}, {"id": "c", "text": "44 to 66 lb"}, {"id": "d", "text": "88 to 110 lb"}]'::jsonb, '["a"]', 'Losing 5–10% of body weight reduces risk; 5–10% of 220 lb is 11 to 22 lb. The other ranges are far below or far above 5–10%.'),
  ('metabolic', 15, 'Which exercise plan meets the recommendation for a client with metabolic syndrome?', '[{"id": "a", "text": "Walking 10 minutes a day, 3 days a week"}, {"id": "b", "text": "Walking 60 minutes once a week"}, {"id": "c", "text": "Walking 30 minutes a day, 5 days a week"}, {"id": "d", "text": "Walking 20 minutes a day, 2 days a week"}]'::jsonb, '["c"]', 'The exercise recommendation for metabolic syndrome is 30 minutes a day, 5 days a week. The other plans provide less total and less frequent activity.'),
  ('metabolic', 16, 'A client with a BMI of 33 is taught about exercise. Which statement by the client indicates understanding?', '[{"id": "a", "text": "I''ll exercise 45 minutes once a week."}, {"id": "b", "text": "I''ll aim for at least 150 minutes each week."}, {"id": "c", "text": "I''ll aim for 60 minutes each week."}, {"id": "d", "text": "I''ll exercise 30 minutes on weekends only."}]'::jsonb, '["b"]', 'Obesity treatment includes exercise of at least 150 minutes per week. The other plans fall well short of 150 minutes weekly.'),
  ('metabolic', 17, 'A client with metabolic syndrome is taught about diet. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll choose more high-fiber foods daily."}, {"id": "b", "text": "I''ll limit how much saturated fat I eat."}, {"id": "c", "text": "I''ll cut back on sugar in my diet."}, {"id": "d", "text": "I''ll try a fad diet to lose weight fast."}]'::jsonb, '["d"]', 'Small, sustainable lifestyle changes are encouraged over fad diets. A diet low in sugar and saturated fat and high in fiber is recommended.'),
  ('metabolic', 18, 'A client with metabolic syndrome is prescribed metformin and asks about its purpose. Which response by the nurse is accurate?', '[{"id": "a", "text": "It lowers cholesterol."}, {"id": "b", "text": "It lowers blood pressure."}, {"id": "c", "text": "It lowers uric acid."}, {"id": "d", "text": "It lowers blood sugar."}]'::jsonb, '["d"]', 'Metformin lowers blood sugar. Statins lower cholesterol, and antihypertensives lower blood pressure.'),
  ('metabolic', 19, 'A client with metabolic syndrome is prescribed metformin, a statin, and an antihypertensive. Which medication–purpose pairing is correct?', '[{"id": "a", "text": "Metformin — lowers blood pressure"}, {"id": "b", "text": "Antihypertensive — lowers blood sugar"}, {"id": "c", "text": "Statin — lowers blood sugar"}, {"id": "d", "text": "Statin — lowers cholesterol"}]'::jsonb, '["d"]', 'Statins lower cholesterol. Metformin lowers blood sugar, and antihypertensives lower blood pressure.'),
  ('metabolic', 20, 'A client''s BMI is calculated as 32. How should the nurse interpret this finding?', '[{"id": "a", "text": "Not obese, because obesity begins at a BMI of 35"}, {"id": "b", "text": "Obesity, with increased risk for scurvy"}, {"id": "c", "text": "Obesity, with increased risk for type 2 diabetes"}, {"id": "d", "text": "Not obese, because obesity begins at a BMI of 40"}]'::jsonb, '["c"]', 'A BMI ≥30 indicates obesity, which increases the risk for type 2 diabetes and heart disease. Scurvy is caused by a lack of fruits and vegetables, not obesity.'),
  ('metabolic', 21, 'The nurse is planning care for a client with a BMI of 34. Which complication of obesity should the nurse assess for?', '[{"id": "a", "text": "Sleep apnea"}, {"id": "b", "text": "Scurvy"}, {"id": "c", "text": "Pernicious anemia"}, {"id": "d", "text": "Lactose intolerance"}]'::jsonb, '["a"]', 'Sleep apnea is a listed complication of obesity (BMI ≥30). Scurvy results from vitamin C deficiency, pernicious anemia from B12 deficiency, and lactose intolerance from lack of lactase.'),
  ('metabolic', 22, 'A client with obesity asks how excess weight can affect the liver. Which response by the nurse is accurate?', '[{"id": "a", "text": "It can lead to fatty liver disease."}, {"id": "b", "text": "It can lead to celiac disease."}, {"id": "c", "text": "It can lead to kwashiorkor."}, {"id": "d", "text": "It can lead to lactose intolerance."}]'::jsonb, '["a"]', 'Fatty liver disease (NAFLD) is a complication of obesity. Celiac disease is an autoimmune reaction to gluten, kwashiorkor results from severe protein malnutrition, and lactose intolerance from lack of lactase.'),
  ('metabolic', 23, 'A client with a BMI of 38 reports chronic knee pain. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Pernicious anemia from B12 loss"}, {"id": "b", "text": "Joint pain from extra weight"}, {"id": "c", "text": "Kwashiorkor from low protein"}, {"id": "d", "text": "Lactose intolerance"}]'::jsonb, '["b"]', 'Joint pain from extra weight is a listed complication of obesity. Pernicious anemia, kwashiorkor, and lactose intolerance are deficiency or intolerance disorders, not obesity complications.'),
  ('metabolic', 24, 'A client with obesity asks to start orlistat before trying any diet changes. Which response by the nurse is accurate?', '[{"id": "a", "text": "Medications are the first step in obesity treatment."}, {"id": "b", "text": "Orlistat replaces the need for diet and exercise."}, {"id": "c", "text": "Medications are considered if lifestyle changes fail."}, {"id": "d", "text": "Surgery must be tried before any medications."}]'::jsonb, '["c"]', 'Orlistat and liraglutide are used if lifestyle changes fail, after a healthy diet and exercise. Bariatric surgery is reserved for severe obesity.'),
  ('metabolic', 25, 'Which sequence reflects the treatment approach for obesity?', '[{"id": "a", "text": "Diet and exercise, then medications, then surgery if severe"}, {"id": "b", "text": "Medications, then diet and exercise, then surgery if severe"}, {"id": "c", "text": "Surgery, then medications, then diet and exercise if needed"}, {"id": "d", "text": "Diet and exercise, then surgery, then medications if severe"}]'::jsonb, '["a"]', 'Treatment begins with a healthy diet and exercise, adds medications if lifestyle fails, and reserves bariatric surgery for severe obesity.'),
  ('metabolic', 26, 'A pregnant client reports fatigue, dizziness, pale skin, and brittle nails. Which deficiency does the nurse suspect?', '[{"id": "a", "text": "Vitamin B12"}, {"id": "b", "text": "Vitamin C"}, {"id": "c", "text": "Iron"}, {"id": "d", "text": "Calcium"}]'::jsonb, '["c"]', 'Iron-deficiency anemia causes fatigue, pale skin, brittle nails, and dizziness, and pregnancy is a cause. B12 deficiency causes numbness and a red swollen tongue, vitamin C deficiency causes bleeding gums, and calcium deficiency causes osteoporosis and cramps.'),
  ('metabolic', 27, 'A client with iron-deficiency anemia asks which foods to eat. Which should the nurse recommend?', '[{"id": "a", "text": "Red meat, spinach, and beans"}, {"id": "b", "text": "Citrus fruits and strawberries"}, {"id": "c", "text": "Dairy products and almonds"}, {"id": "d", "text": "Fish and regular sun exposure"}]'::jsonb, '["a"]', 'Red meat, spinach, beans, and fortified cereals are listed iron sources. Citrus and strawberries are vitamin C sources, dairy and almonds are calcium sources, and fish and sun exposure are vitamin D sources.'),
  ('metabolic', 28, 'Which client should the nurse identify as at greatest risk for iron-deficiency anemia?', '[{"id": "a", "text": "A client who is in menopause"}, {"id": "b", "text": "A client with limited sun exposure"}, {"id": "c", "text": "A client with a high-purine diet"}, {"id": "d", "text": "A client with ongoing blood loss"}]'::jsonb, '["d"]', 'Blood loss, poor diet, and pregnancy cause iron-deficiency anemia. Menopause is a cause of calcium deficiency, lack of sunlight causes vitamin D deficiency, and a high-purine diet causes gout.'),
  ('metabolic', 29, 'A client reports numbness, memory loss, fatigue, and a red, swollen tongue. Which deficiency does the nurse suspect?', '[{"id": "a", "text": "Iron"}, {"id": "b", "text": "Vitamin D"}, {"id": "c", "text": "Vitamin C"}, {"id": "d", "text": "Vitamin B12"}]'::jsonb, '["d"]', 'Vitamin B12 deficiency (pernicious anemia) causes numbness, memory loss, fatigue, and a red swollen tongue. Iron deficiency causes pale skin and brittle nails, vitamin D deficiency bone pain, and vitamin C deficiency bleeding gums.'),
  ('metabolic', 30, 'A client has a long history of gastritis. The nurse should monitor for a deficiency of which nutrient?', '[{"id": "a", "text": "Vitamin C"}, {"id": "b", "text": "Vitamin B12"}, {"id": "c", "text": "Calcium"}, {"id": "d", "text": "Vitamin D"}]'::jsonb, '["b"]', 'Pernicious anemia is caused by a lack of B12 or gastric problems such as gastritis. Vitamin C deficiency stems from a lack of fruits and vegetables, calcium deficiency from poor diet, menopause, or kidney disease, and vitamin D deficiency from lack of sunlight.'),
  ('metabolic', 31, 'A client with vitamin B12 deficiency is taught about food sources. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Eggs are a source of B12."}, {"id": "b", "text": "Bell peppers are a good B12 source."}, {"id": "c", "text": "Dairy products contain B12."}, {"id": "d", "text": "Fortified cereals can provide B12."}]'::jsonb, '["b"]', 'Meat, dairy, eggs, and fortified cereals are listed B12 sources; bell peppers are listed as a vitamin C source.'),
  ('metabolic', 32, 'A homebound client with little sunlight exposure reports bone pain and muscle weakness. Which deficiency does the nurse suspect?', '[{"id": "a", "text": "Vitamin D"}, {"id": "b", "text": "Vitamin B12"}, {"id": "c", "text": "Vitamin C"}, {"id": "d", "text": "Protein"}]'::jsonb, '["a"]', 'Vitamin D deficiency is caused by lack of sunlight and causes bone pain, muscle weakness, and depression. B12 deficiency causes numbness and a red tongue, vitamin C deficiency bleeding gums, and protein deficiency a swollen belly or severe weight loss.'),
  ('metabolic', 33, 'Which recommendation should the nurse give a client with vitamin D deficiency?', '[{"id": "a", "text": "Eat strawberries and bell peppers"}, {"id": "b", "text": "Eat red meat and beans"}, {"id": "c", "text": "Get sun exposure and eat fish"}, {"id": "d", "text": "Follow a gluten-free diet"}]'::jsonb, '["c"]', 'Sun exposure, fish, dairy, and fortified cereals are vitamin D sources. Strawberries and bell peppers are vitamin C sources, red meat and beans are iron sources, and a gluten-free diet treats celiac disease.'),
  ('metabolic', 34, 'A postmenopausal client has osteoporosis and reports muscle cramps. Which deficiency does the nurse suspect?', '[{"id": "a", "text": "Vitamin C"}, {"id": "b", "text": "Iron"}, {"id": "c", "text": "Vitamin B12"}, {"id": "d", "text": "Calcium"}]'::jsonb, '["d"]', 'Calcium deficiency, which can be caused by menopause, presents with osteoporosis and muscle cramps. Vitamin C deficiency causes bleeding gums, iron deficiency pale skin and fatigue, and B12 deficiency numbness and memory loss.'),
  ('metabolic', 35, 'Which snack should the nurse suggest for a client with a calcium deficiency?', '[{"id": "a", "text": "Yogurt with almonds"}, {"id": "b", "text": "Strawberries with oranges"}, {"id": "c", "text": "Bell peppers with beans"}, {"id": "d", "text": "Beef with red peppers"}]'::jsonb, '["a"]', 'Dairy, leafy greens, and almonds are listed calcium sources. Strawberries, oranges, and bell peppers are vitamin C sources, and beef and beans are iron sources.'),
  ('metabolic', 36, 'Which client should the nurse identify as at increased risk for calcium deficiency?', '[{"id": "a", "text": "A client with chronic gastritis"}, {"id": "b", "text": "A client with a high-purine diet"}, {"id": "c", "text": "A client with ongoing blood loss"}, {"id": "d", "text": "A client with kidney disease"}]'::jsonb, '["d"]', 'Poor diet, menopause, and kidney disease cause calcium deficiency. Gastritis is linked to B12 deficiency, a high-purine diet to gout, and blood loss to iron-deficiency anemia.'),
  ('metabolic', 37, 'A client whose diet lacks fruits and vegetables has bleeding gums, bruising, and a slow-healing wound. Which deficiency does the nurse suspect?', '[{"id": "a", "text": "Vitamin D"}, {"id": "b", "text": "Iron"}, {"id": "c", "text": "Calcium"}, {"id": "d", "text": "Vitamin C"}]'::jsonb, '["d"]', 'Vitamin C deficiency (scurvy) results from a lack of fruits and vegetables and causes bleeding gums, poor wound healing, and bruising. Vitamin D deficiency causes bone pain, iron deficiency pale skin, and calcium deficiency osteoporosis.'),
  ('metabolic', 38, 'A client with scurvy asks for snack ideas. Which snack should the nurse recommend?', '[{"id": "a", "text": "Strawberries and orange slices"}, {"id": "b", "text": "Cheese cubes and almonds"}, {"id": "c", "text": "Red meat and baked beans"}, {"id": "d", "text": "Eggs and fortified cereal"}]'::jsonb, '["a"]', 'Citrus fruits, bell peppers, and strawberries are listed vitamin C sources. Cheese and almonds are calcium sources, red meat and beans iron sources, and eggs and fortified cereal B12 sources.'),
  ('metabolic', 39, 'A client is being treated for scurvy. Which finding indicates that treatment is effective?', '[{"id": "a", "text": "Cold intolerance has improved"}, {"id": "b", "text": "Bloating after dairy has resolved"}, {"id": "c", "text": "Big toe swelling has resolved"}, {"id": "d", "text": "Gums no longer bleed and wounds heal"}]'::jsonb, '["d"]', 'Scurvy causes bleeding gums, poor wound healing, and bruising, so their resolution shows improvement. Cold intolerance relates to anorexia nervosa, bloating after dairy to lactose intolerance, and big-toe swelling to gout.'),
  ('metabolic', 40, 'A child with severe protein malnutrition has a swollen belly. Which condition does the nurse recognize?', '[{"id": "a", "text": "Marasmus"}, {"id": "b", "text": "Scurvy"}, {"id": "c", "text": "Kwashiorkor"}, {"id": "d", "text": "Celiac disease"}]'::jsonb, '["c"]', 'A swollen belly with protein malnutrition indicates kwashiorkor, whereas marasmus presents with severe weight loss. Scurvy is vitamin C deficiency, and celiac disease is an autoimmune reaction to gluten.'),
  ('metabolic', 41, 'A child with protein malnutrition from poverty presents with severe weight loss rather than a swollen belly. Which condition does the nurse recognize?', '[{"id": "a", "text": "Kwashiorkor"}, {"id": "b", "text": "Gout"}, {"id": "c", "text": "Bulimia nervosa"}, {"id": "d", "text": "Marasmus"}]'::jsonb, '["d"]', 'Severe weight loss from protein malnutrition indicates marasmus, while kwashiorkor presents with a swollen belly. Gout causes painful joints, and bulimia involves binge eating and purging.'),
  ('metabolic', 42, 'A client with celiac disease is taught about diet. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will avoid foods made with wheat."}, {"id": "b", "text": "I will avoid rye bread."}, {"id": "c", "text": "Barley soup is safe for me to eat."}, {"id": "d", "text": "I need to follow a gluten-free diet."}]'::jsonb, '["c"]', 'Celiac disease requires a gluten-free diet with no wheat, barley, or rye, so barley soup is not safe.'),
  ('metabolic', 43, 'Which item should the nurse remove from the meal tray of a client with celiac disease?', '[{"id": "a", "text": "Baked potato"}, {"id": "b", "text": "Rye toast"}, {"id": "c", "text": "Fresh fruit cup"}, {"id": "d", "text": "Scrambled eggs"}]'::jsonb, '["b"]', 'Celiac disease requires avoiding gluten in wheat, barley, and rye, so rye toast must be removed. The other items are not wheat, barley, or rye.'),
  ('metabolic', 44, 'A client reports gas, bloating, and diarrhea after drinking milk and is diagnosed with lactose intolerance. Which management should the nurse anticipate?', '[{"id": "a", "text": "Gluten-free diet without wheat or rye"}, {"id": "b", "text": "Lactose-free diet or lactase supplements"}, {"id": "c", "text": "Low-purine diet and allopurinol"}, {"id": "d", "text": "CBT and antidepressant therapy"}]'::jsonb, '["b"]', 'Lactose intolerance, caused by a lack of lactase, is managed with a lactose-free diet and lactase supplements. A gluten-free diet treats celiac disease, a low-purine diet and allopurinol treat gout, and CBT and antidepressants treat bulimia.'),
  ('metabolic', 45, 'A client reports bloating and diarrhea after eating dairy but has no symptoms after eating wheat bread. Which condition is most consistent with these findings?', '[{"id": "a", "text": "Lactose intolerance"}, {"id": "b", "text": "Celiac disease"}, {"id": "c", "text": "Gout"}, {"id": "d", "text": "Bulimia nervosa"}]'::jsonb, '["a"]', 'Gas, bloating, and diarrhea after dairy indicate lactose intolerance. Celiac disease is a reaction to gluten, which wheat bread contains, so the absence of symptoms after bread makes it less likely.'),
  ('metabolic', 46, 'Which assessment finding would the nurse expect in a client with anorexia nervosa?', '[{"id": "a", "text": "Tooth decay and swollen cheeks"}, {"id": "b", "text": "Hair loss and cold intolerance"}, {"id": "c", "text": "Painful swelling of the big toe"}, {"id": "d", "text": "A red, swollen tongue"}]'::jsonb, '["b"]', 'Anorexia nervosa causes severe weight loss, hair loss, and cold intolerance. Tooth decay and swollen cheeks suggest bulimia, big-toe swelling suggests gout, and a red swollen tongue suggests B12 deficiency.'),
  ('metabolic', 47, 'A client reports episodes of binge eating followed by purging. Which assessment finding should the nurse expect?', '[{"id": "a", "text": "Hair loss and cold intolerance"}, {"id": "b", "text": "A swollen belly"}, {"id": "c", "text": "Tooth decay and swollen cheeks"}, {"id": "d", "text": "Bleeding gums and bruising"}]'::jsonb, '["c"]', 'Bulimia nervosa (binge eating plus purging) causes tooth decay, swollen cheeks, and irregular periods. Hair loss and cold intolerance suggest anorexia, a swollen belly suggests kwashiorkor, and bleeding gums suggest scurvy.'),
  ('metabolic', 48, 'Which treatment should the nurse anticipate for a client diagnosed with bulimia nervosa?', '[{"id": "a", "text": "Low-purine diet and allopurinol"}, {"id": "b", "text": "Lactase supplements"}, {"id": "c", "text": "CBT and antidepressants"}, {"id": "d", "text": "Gluten-free diet"}]'::jsonb, '["c"]', 'Bulimia nervosa is treated with CBT and antidepressants. Allopurinol treats gout, lactase supplements treat lactose intolerance, and a gluten-free diet treats celiac disease.'),
  ('metabolic', 49, 'A client with gout is taught about managing the condition. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will follow a low-purine diet from now on."}, {"id": "b", "text": "I can keep drinking alcohol while on allopurinol."}, {"id": "c", "text": "I will limit how much red meat I eat."}, {"id": "d", "text": "I will take my allopurinol as prescribed."}]'::jsonb, '["b"]', 'Gout is managed with a low-purine diet and allopurinol, avoiding alcohol and red meat. Continuing alcohol is incorrect even while taking allopurinol.'),
  ('metabolic', 50, 'The nurse is categorizing nutritional disorders. Which client''s disorder is classified as malabsorption?', '[{"id": "a", "text": "A client with Crohn''s disease"}, {"id": "b", "text": "A client with obesity from overeating"}, {"id": "c", "text": "A client with scurvy from low produce intake"}, {"id": "d", "text": "A client with marasmus from poverty"}]'::jsonb, '["a"]', 'Malabsorption means the body cannot absorb nutrients properly, as in celiac disease or Crohn''s disease. Obesity from overeating is an excess, and scurvy and marasmus are deficiencies.'),
  ('crohns', 1, 'A client newly diagnosed with Crohn''s disease asks which parts of the digestive tract the disease can affect. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Only the colon and the rectum can be affected.\""}, {"id": "b", "text": "\"Any part of the tract from the mouth to the anus.\""}, {"id": "c", "text": "\"Only the stomach and the first part of the small intestine.\""}, {"id": "d", "text": "\"Only the rectum, spreading upward without gaps.\""}]'::jsonb, '["b"]', 'Crohn''s disease can affect any part of the GI tract from mouth to anus. Involvement of the colon and rectum only, spreading continuously from the rectum, describes ulcerative colitis.'),
  ('crohns', 2, 'A client with suspected Crohn''s disease reports abdominal pain. The nurse expects the pain to be located in which area, reflecting the most commonly affected site?', '[{"id": "a", "text": "Left lower quadrant"}, {"id": "b", "text": "Left upper quadrant"}, {"id": "c", "text": "Right lower quadrant"}, {"id": "d", "text": "Directly over the rectum"}]'::jsonb, '["c"]', 'Crohn''s most commonly affects the terminal ileum, producing RLQ abdominal pain. LLQ pain is the pattern described for ulcerative colitis.'),
  ('crohns', 3, 'A nursing student asks how the inflammation of Crohn''s disease affects the intestinal wall. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It is transmural, involving all layers of the wall."}, {"id": "b", "text": "It is limited to the mucosal lining of the wall."}, {"id": "c", "text": "It is continuous, starting at the rectum and moving up."}, {"id": "d", "text": "It is confined to the outer layer of the colon wall."}]'::jsonb, '["a"]', 'Crohn''s involves transmural inflammation of all layers of the intestinal wall. Mucosal/submucosal-only inflammation that is continuous from the rectum describes ulcerative colitis.'),
  ('crohns', 4, 'A client with chronic diarrhea and RLQ pain undergoes colonoscopy. Which finding would the nurse expect if the client has Crohn''s disease?', '[{"id": "a", "text": "Pseudopolyps with continuous ulceration"}, {"id": "b", "text": "Continuous inflammation beginning at the rectum"}, {"id": "c", "text": "Normal-appearing mucosa throughout the colon"}, {"id": "d", "text": "Cobblestone mucosa with skip lesions"}]'::jsonb, '["d"]', 'Colonoscopy in Crohn''s shows cobblestone mucosa and skip lesions. Pseudopolyps with continuous ulceration are the endoscopic picture of ulcerative colitis.'),
  ('crohns', 5, 'A client with Crohn''s disease reads "skip lesions" on a procedure report and asks what this means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Inflammation spreads without any gaps.\""}, {"id": "b", "text": "\"Healthy tissue lies between inflamed areas.\""}, {"id": "c", "text": "\"Deep ulcers are found only in the rectum.\""}, {"id": "d", "text": "\"Pus has collected in a walled-off pocket.\""}]'::jsonb, '["b"]', 'Skip lesions are areas of healthy tissue between inflamed areas, giving Crohn''s a patchy pattern. Inflammation without gaps describes the continuous pattern of ulcerative colitis.'),
  ('crohns', 6, 'The nurse is explaining the "cobblestone" appearance seen on endoscopy in a client with Crohn''s disease. Which description is accurate?', '[{"id": "a", "text": "Healthy tissue separates patchy inflamed areas."}, {"id": "b", "text": "Small growths rise from a continuously ulcerated lining."}, {"id": "c", "text": "Raised inflamed areas sit between deep ulcers."}, {"id": "d", "text": "An abnormal tunnel connects two nearby organs."}]'::jsonb, '["c"]', 'Cobblestone appearance refers to raised inflamed areas between deep ulcers. Healthy tissue between inflamed areas defines skip lesions, and an abnormal connection between organs is a fistula.'),
  ('crohns', 7, 'A client undergoes colonoscopy with biopsy for suspected inflammatory bowel disease. Which pathology finding supports a diagnosis of Crohn''s disease?', '[{"id": "a", "text": "Granulomas within the biopsied tissue"}, {"id": "b", "text": "Inflammation limited to the mucosal layer"}, {"id": "c", "text": "Disease confined to the colon and rectum"}, {"id": "d", "text": "Ulceration continuous from the rectum upward"}]'::jsonb, '["a"]', 'Granulomas may be seen on biopsy in Crohn''s disease. Mucosal-only inflammation confined to the colon and rectum and continuous from the rectum describes ulcerative colitis.'),
  ('crohns', 8, 'A client with Crohn''s disease has an abdominal CT scan. Which finding would the nurse expect in the report?', '[{"id": "a", "text": "Thinning of the intestinal wall"}, {"id": "b", "text": "Thickening of the bowel wall"}, {"id": "c", "text": "Inflammation limited to the rectum"}, {"id": "d", "text": "Uniformly normal small intestine"}]'::jsonb, '["b"]', 'Crohn''s disease shows bowel wall thickening on CT/MRI, which may also reveal fistulas. A thinned wall is the reverse of the expected finding.'),
  ('crohns', 9, 'The nurse is assessing the bowel pattern of a client with Crohn''s disease involving the terminal ileum. Which stool description is most consistent with this disease?', '[{"id": "a", "text": "Frequent bloody stools filled with mucus"}, {"id": "b", "text": "Infrequent hard stools requiring straining"}, {"id": "c", "text": "Formed stools with no change from baseline"}, {"id": "d", "text": "Fatty, greasy stools that are often non-bloody"}]'::jsonb, '["d"]', 'Crohn''s causes chronic diarrhea that is often non-bloody, along with steatorrhea (fatty, greasy stool). Bloody, mucus-filled diarrhea is the pattern of ulcerative colitis.'),
  ('crohns', 10, 'A client with Crohn''s disease has lost 6 kg over 3 months despite eating regularly. The nurse understands that this weight loss is primarily caused by which factor?', '[{"id": "a", "text": "Malabsorption of nutrients"}, {"id": "b", "text": "Excess protein in the diet"}, {"id": "c", "text": "Overproduction of albumin"}, {"id": "d", "text": "Rapid healing of the bowel"}]'::jsonb, '["a"]', 'Weight loss in Crohn''s results from malabsorption. Albumin is decreased, not overproduced, because of malnutrition and malabsorption.'),
  ('crohns', 11, 'The nurse is performing a systemic assessment on a client with active Crohn''s disease. Which finding is an expected manifestation of the disease?', '[{"id": "a", "text": "Unexplained weight gain"}, {"id": "b", "text": "Elevated hemoglobin level"}, {"id": "c", "text": "Aphthous ulcers in the mouth"}, {"id": "d", "text": "Increased serum albumin"}]'::jsonb, '["c"]', 'Mouth (aphthous) ulcers are a systemic symptom of Crohn''s disease. The other options reverse expected findings: Crohn''s causes weight loss, low hemoglobin, and low albumin.'),
  ('crohns', 12, 'The parents of a 12-year-old child with Crohn''s disease ask how the illness may affect their child. Which effect should the nurse include in the discussion?', '[{"id": "a", "text": "Accelerated growth"}, {"id": "b", "text": "Delayed growth"}, {"id": "c", "text": "Rapid weight gain"}, {"id": "d", "text": "Increased energy"}]'::jsonb, '["b"]', 'Delayed growth in children is a systemic manifestation of Crohn''s disease. Weight loss and fatigue, not weight gain or increased energy, are expected.'),
  ('crohns', 13, 'The nurse reviews laboratory results for a client admitted with a Crohn''s disease flare. Which pair of results is consistent with active disease?', '[{"id": "a", "text": "Elevated CRP and elevated WBC"}, {"id": "b", "text": "Decreased ESR and decreased WBC"}, {"id": "c", "text": "Decreased CRP and elevated albumin"}, {"id": "d", "text": "Elevated albumin and elevated Hct"}]'::jsonb, '["a"]', 'ESR and CRP rise as inflammation markers and WBC rises with infection/inflammation in Crohn''s. Albumin and Hgb/Hct are decreased, so options showing them elevated reverse the expected direction.'),
  ('crohns', 14, 'A client with Crohn''s disease has a low serum albumin level. The nurse recognizes that this result most likely reflects which problem?', '[{"id": "a", "text": "Acute infection of a fistula"}, {"id": "b", "text": "Active inflammation markers"}, {"id": "c", "text": "Malnutrition and malabsorption"}, {"id": "d", "text": "Narrowing of the bowel lumen"}]'::jsonb, '["c"]', 'Decreased albumin in Crohn''s reflects malnutrition/malabsorption. Inflammation is reflected by elevated ESR and CRP, not by albumin.'),
  ('crohns', 15, 'A client with Crohn''s disease reports increasing fatigue. Laboratory results show decreased hemoglobin and hematocrit. The nurse interprets these findings as indicating which condition?', '[{"id": "a", "text": "Infection"}, {"id": "b", "text": "Malnutrition"}, {"id": "c", "text": "Obstruction"}, {"id": "d", "text": "Anemia"}]'::jsonb, '["d"]', 'Decreased Hgb/Hct indicates anemia, which commonly accompanies fatigue in Crohn''s. Malnutrition is reflected by a low albumin level, and infection by an elevated WBC.'),
  ('crohns', 16, 'A client is being evaluated for Crohn''s disease. Which diagnostic result would the nurse expect?', '[{"id": "a", "text": "Positive fecal occult blood test"}, {"id": "b", "text": "Decreased erythrocyte sedimentation rate"}, {"id": "c", "text": "Elevated hemoglobin and hematocrit"}, {"id": "d", "text": "Thinning of the bowel wall on MRI"}]'::jsonb, '["a"]', 'A positive fecal occult blood test is a listed lab finding in Crohn''s. ESR is elevated, Hgb/Hct are decreased, and the bowel wall is thickened, so the other options reverse expected results.'),
  ('crohns', 17, 'A client is admitted with a Crohn''s disease flare-up. Which dietary instruction should the nurse provide?', '[{"id": "a", "text": "\"Add high-fiber foods to bulk your stools.\""}, {"id": "b", "text": "\"Follow a low-residue, high-protein diet.\""}, {"id": "c", "text": "\"Choose low-calorie, low-protein foods.\""}, {"id": "d", "text": "\"Eat three large meals each day.\""}]'::jsonb, '["b"]', 'During flares, a low-residue (low-fiber), high-calorie, high-protein diet is recommended. High-fiber foods should be limited during flares.'),
  ('crohns', 18, 'The nurse teaches a client about diet during a Crohn''s disease flare. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will eat small meals more often.\""}, {"id": "b", "text": "\"I will choose high-calorie, high-protein foods.\""}, {"id": "c", "text": "\"I will eat more fried foods to regain weight.\""}, {"id": "d", "text": "\"I will limit alcohol while my symptoms are active.\""}]'::jsonb, '["c"]', 'During flares, the client should limit fatty/fried foods, so this statement needs correction. Small frequent meals, high-calorie high-protein foods, and limiting alcohol are all correct.'),
  ('crohns', 19, 'A client with Crohn''s disease reports poor appetite and feeling full quickly. Which meal pattern should the nurse recommend?', '[{"id": "a", "text": "One large meal in the evening"}, {"id": "b", "text": "Skipping meals when pain occurs"}, {"id": "c", "text": "Three large meals with snacks avoided"}, {"id": "d", "text": "Small, frequent meals throughout the day"}]'::jsonb, '["d"]', 'Small, frequent meals are part of Crohn''s nutrition teaching, along with a high-calorie, high-protein diet. Large or skipped meals do not support the nutritional goals.'),
  ('crohns', 20, 'A client with Crohn''s disease who is lactose intolerant asks about dairy products during a flare. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Limit lactose during flares because you are intolerant.\""}, {"id": "b", "text": "\"Increase dairy intake to raise your protein level.\""}, {"id": "c", "text": "\"Dairy is required during flares to heal the bowel.\""}, {"id": "d", "text": "\"Lactose will not affect your symptoms during flares.\""}]'::jsonb, '["a"]', 'During flares, clients should limit lactose if intolerant, along with high-fiber, fatty/fried foods and alcohol. Increasing dairy would conflict with this guidance.'),
  ('crohns', 21, 'A client with Crohn''s disease has severe malnutrition and a bowel obstruction. Which nutrition order does the nurse anticipate?', '[{"id": "a", "text": "High-fiber oral diet"}, {"id": "b", "text": "Total parenteral nutrition"}, {"id": "c", "text": "Regular diet as tolerated"}, {"id": "d", "text": "Large, high-fat oral meals"}]'::jsonb, '["b"]', 'Enteral nutrition or TPN may be required with severe malnutrition, bowel rest, obstruction, or poor absorption. An oral high-fiber or high-fat diet is inappropriate, and severe flare/obstruction calls for NPO status.'),
  ('crohns', 22, 'A client with Crohn''s disease is being discharged on prednisone. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will taper the dose exactly as prescribed.\""}, {"id": "b", "text": "\"This medication treats acute inflammation.\""}, {"id": "c", "text": "\"I can stop the pills once I start feeling better.\""}, {"id": "d", "text": "\"Stopping suddenly could cause adrenal problems.\""}]'::jsonb, '["c"]', 'Corticosteroids must be tapered slowly and never stopped abruptly because of adrenal insufficiency risk. The other statements correctly reflect prednisone teaching.'),
  ('crohns', 23, 'A client with Crohn''s disease who has taken prednisone daily for several months ran out of medication 2 days ago and did not refill it. The nurse is most concerned about which complication?', '[{"id": "a", "text": "Vitamin B12 deficiency"}, {"id": "b", "text": "Fistula formation"}, {"id": "c", "text": "Toxic megacolon"}, {"id": "d", "text": "Adrenal insufficiency"}]'::jsonb, '["d"]', 'Corticosteroids must never be stopped abruptly because of the risk of adrenal insufficiency. B12 deficiency is linked to terminal ileum disease or resection, not steroid withdrawal.'),
  ('crohns', 24, 'A client with severe Crohn''s disease is scheduled to start infliximab. Which action should the nurse verify before the first dose?', '[{"id": "a", "text": "Screening for tuberculosis and hepatitis was completed"}, {"id": "b", "text": "The client has been on a high-fiber diet for a week"}, {"id": "c", "text": "A dose of loperamide was given to slow stool output"}, {"id": "d", "text": "The prednisone was stopped abruptly the night before"}]'::jsonb, '["a"]', 'Clients must be screened for TB/hepatitis before anti-TNF therapy. Prednisone should never be stopped abruptly, and high-fiber foods are limited during active disease.'),
  ('crohns', 25, 'A client with Crohn''s disease receives adalimumab. Which finding should the nurse report to the health care provider promptly?', '[{"id": "a", "text": "Increased appetite"}, {"id": "b", "text": "New fever"}, {"id": "c", "text": "Formed stools"}, {"id": "d", "text": "Stable weight"}]'::jsonb, '["b"]', 'Clients on anti-TNF biologics must be monitored for infection, so a new fever warrants prompt reporting. The other findings suggest improvement rather than a complication.'),
  ('crohns', 26, 'A client with Crohn''s disease asks why azathioprine has been prescribed. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It will permanently cure the disease.\""}, {"id": "b", "text": "\"It treats fistulas and abscesses.\""}, {"id": "c", "text": "\"It helps prevent flare-ups.\""}, {"id": "d", "text": "\"It quickly slows your diarrhea.\""}]'::jsonb, '["c"]', 'Immunosuppressants such as azathioprine and methotrexate are used to prevent flare-ups. Antibiotics treat fistulas or abscesses, and Crohn''s has no cure.'),
  ('crohns', 27, 'A client with Crohn''s disease develops an abscess near a fistula. Which medication does the nurse anticipate will be prescribed for this complication?', '[{"id": "a", "text": "Sulfasalazine"}, {"id": "b", "text": "Methotrexate"}, {"id": "c", "text": "Loperamide"}, {"id": "d", "text": "Metronidazole"}]'::jsonb, '["d"]', 'Antibiotics such as metronidazole and ciprofloxacin are used for fistulas or abscesses. Methotrexate is an immunosuppressant used to prevent flare-ups.'),
  ('crohns', 28, 'The nurse is reviewing as-needed loperamide orders for several clients with Crohn''s disease. For which client should the nurse question the order?', '[{"id": "a", "text": "A client with fever and suspected bowel obstruction"}, {"id": "b", "text": "A client in remission reporting mild loose stools"}, {"id": "c", "text": "A client with stable vital signs and formed stools"}, {"id": "d", "text": "A client with mild symptoms and no abdominal distention"}]'::jsonb, '["a"]', 'Antidiarrheals should be avoided with suspected obstruction, severe flare, fever, bloody diarrhea, or toxic megacolon risk. The other clients lack these contraindications.'),
  ('crohns', 29, 'A client with Crohn''s disease is prescribed sulfasalazine. The client asks how the drug works. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It blocks a specific inflammation pathway called TNF.\""}, {"id": "b", "text": "\"It decreases inflammation in the colon.\""}, {"id": "c", "text": "\"It treats infection in fistulas and abscesses.\""}, {"id": "d", "text": "\"It slows the movement of stool for relief.\""}]'::jsonb, '["b"]', 'Sulfasalazine is an aminosalicylate used to decrease inflammation in the colon. Blocking specific inflammation pathways describes anti-TNF biologics such as infliximab.'),
  ('crohns', 30, 'A client with Crohn''s disease scheduled for a bowel resection says, "After this surgery, I will never have Crohn''s again." Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, removing the diseased part cures it.\""}, {"id": "b", "text": "\"Yes, as long as you avoid fiber afterward.\""}, {"id": "c", "text": "\"The disease can come back after surgery.\""}, {"id": "d", "text": "\"Only a colectomy would make you disease-free.\""}]'::jsonb, '["c"]', 'Surgery is not curative for Crohn''s, and the disease can recur after surgery. Colectomy is described as curative for ulcerative colitis, not for Crohn''s.'),
  ('crohns', 31, 'A client with Crohn''s disease has a severe stricture. The surgeon plans to widen the narrowed segment rather than remove it. The nurse recognizes this procedure as which?', '[{"id": "a", "text": "Resection"}, {"id": "b", "text": "Abscess drainage"}, {"id": "c", "text": "Fistula repair"}, {"id": "d", "text": "Strictureplasty"}]'::jsonb, '["d"]', 'Strictureplasty is the widening of narrowed areas. Resection removes the diseased bowel segment rather than widening it.'),
  ('crohns', 32, 'The nurse is caring for several clients with Crohn''s disease. Which client finding is an indication for surgical management?', '[{"id": "a", "text": "Intestinal perforation"}, {"id": "b", "text": "Mild diarrhea controlled by medication"}, {"id": "c", "text": "A single small aphthous mouth ulcer"}, {"id": "d", "text": "Fatigue with a stable hemoglobin"}]'::jsonb, '["a"]', 'Surgical indications include perforation, bleeding, refractory disease, obstruction or severe stricture, and fistula or abscess. Controlled mild symptoms do not indicate surgery.'),
  ('crohns', 33, 'A client had a resection of the terminal ileum for Crohn''s disease. Which statement by the nurse about long-term nutrition is accurate?', '[{"id": "a", "text": "\"Removing the ileum eliminates any risk of deficiency.\""}, {"id": "b", "text": "\"You are at risk for vitamin B12 deficiency.\""}, {"id": "c", "text": "\"Your iron and folate levels cannot be affected.\""}, {"id": "d", "text": "\"Surgery cured the disease, so no follow-up is needed.\""}]'::jsonb, '["b"]', 'Malabsorption with B12 deficiency occurs especially with terminal ileum disease or resection, and iron/folate deficiencies can also occur. Surgery does not cure Crohn''s.'),
  ('crohns', 34, 'A client with Crohn''s disease is told that a fistula has developed. The client asks what a fistula is. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A pocket of pus caused by infection.\""}, {"id": "b", "text": "\"A narrowing of the inside of the bowel.\""}, {"id": "c", "text": "\"An abnormal connection between organs.\""}, {"id": "d", "text": "\"Healthy tissue between inflamed areas.\""}]'::jsonb, '["c"]', 'Fistulas are abnormal connections between organs. A pus-filled infection is an abscess, and bowel narrowing is a stricture.'),
  ('crohns', 35, 'The nurse is reviewing complications of Crohn''s disease with a group of new graduates. Which complication is considered the hallmark of Crohn''s disease?', '[{"id": "a", "text": "Toxic megacolon"}, {"id": "b", "text": "Pseudopolyps"}, {"id": "c", "text": "Continuous ulceration"}, {"id": "d", "text": "Fistulas"}]'::jsonb, '["d"]', 'Fistulas are the hallmark complication of Crohn''s disease. Toxic megacolon is a complication of ulcerative colitis, and pseudopolyps with continuous ulceration are its endoscopic findings.'),
  ('crohns', 36, 'A client in a Crohn''s disease flare suddenly reports severe abdominal pain. The client''s temperature is elevated and the heart rate is 124/min. The nurse suspects which complication?', '[{"id": "a", "text": "Perforation or sepsis"}, {"id": "b", "text": "Expected flare discomfort"}, {"id": "c", "text": "Resolving bowel obstruction"}, {"id": "d", "text": "Corticosteroid side effect"}]'::jsonb, '["a"]', 'Sudden severe pain, fever, and tachycardia are signs of perforation/sepsis that the nurse must monitor for during a flare. These are not expected flare findings.'),
  ('crohns', 37, 'The nurse is caring for a client hospitalized with a Crohn''s disease flare. Which finding should be reported to the health care provider immediately?', '[{"id": "a", "text": "Chronic RLQ discomfort unchanged from admission"}, {"id": "b", "text": "Sudden severe abdominal pain with tachycardia"}, {"id": "c", "text": "Two loose, non-bloody stools during the shift"}, {"id": "d", "text": "A small aphthous ulcer on the inner cheek"}]'::jsonb, '["b"]', 'Sudden severe pain with fever or tachycardia suggests perforation/sepsis and requires immediate reporting. Unchanged RLQ pain, non-bloody diarrhea, and mouth ulcers are expected Crohn''s findings.'),
  ('crohns', 38, 'A client with Crohn''s disease is vomiting and has abdominal distention, and a bowel obstruction is suspected. Which orders does the nurse anticipate?', '[{"id": "a", "text": "High-fiber diet to stimulate the bowel"}, {"id": "b", "text": "Loperamide to slow stool output"}, {"id": "c", "text": "NPO status and nasogastric tube insertion"}, {"id": "d", "text": "Laxative to relieve the obstruction"}]'::jsonb, '["c"]', 'In severe flare or obstruction the client is NPO, with an NG tube if vomiting, distention, or obstruction is suspected. Loperamide is avoided with suspected obstruction, and laxatives are avoided during flares.'),
  ('crohns', 39, 'A client is admitted with a severe Crohn''s disease flare, frequent diarrheal stools, and NPO status. Which nursing action is the priority?', '[{"id": "a", "text": "Teach the client a long-term meal plan"}, {"id": "b", "text": "Discuss surgical options with the client"}, {"id": "c", "text": "Encourage high-fiber foods when eating"}, {"id": "d", "text": "Give IV fluids and electrolytes as ordered"}]'::jsonb, '["d"]', 'IV fluids and electrolytes are a nursing priority during a flare, particularly when the client is NPO with ongoing stool losses. High-fiber foods are avoided during flares.'),
  ('crohns', 40, 'The nurse is supervising an unlicensed assistive personnel (UAP) caring for a client in a Crohn''s disease flare. Which action by the UAP requires correction?', '[{"id": "a", "text": "Weighing the client once a week"}, {"id": "b", "text": "Recording each liquid stool on the output record"}, {"id": "c", "text": "Measuring the client''s intake and output"}, {"id": "d", "text": "Reporting the client''s new severe abdominal pain"}]'::jsonb, '["a"]', 'Clients in a flare require daily weights and I&O, so weekly weights need correction. Recording stool output and reporting sudden severe pain are appropriate.'),
  ('crohns', 41, 'Which set of nursing interventions is appropriate for a client hospitalized with a Crohn''s disease flare?', '[{"id": "a", "text": "Encourage high-fiber foods and weigh weekly"}, {"id": "b", "text": "Monitor bowel sounds and weigh daily"}, {"id": "c", "text": "Give laxatives and monitor stool output"}, {"id": "d", "text": "Offer fried foods and record weekly weights"}]'::jsonb, '["b"]', 'Flare priorities include monitoring bowel sounds and stool output and obtaining daily weights and I&O. Laxatives and high-fiber foods are avoided during flares.'),
  ('crohns', 42, 'The charge nurse observes care being given to clients in a Crohn''s disease flare. Which action by a staff nurse requires correction?', '[{"id": "a", "text": "Administering corticosteroids as ordered"}, {"id": "b", "text": "Recording the client''s daily weight"}, {"id": "c", "text": "Offering a laxative for abdominal cramping"}, {"id": "d", "text": "Monitoring the client''s bowel sounds"}]'::jsonb, '["c"]', 'Laxatives and high-fiber foods should be avoided during flares. Giving corticosteroids as ordered, daily weights, and monitoring bowel sounds are appropriate flare care.'),
  ('crohns', 43, 'A young adult with long-standing Crohn''s disease says, "I hate the way my body looks, and I feel hopeless most days." The nurse recognizes this statement as which?', '[{"id": "a", "text": "A sign of bowel perforation"}, {"id": "b", "text": "An expected response needing no action"}, {"id": "c", "text": "A sign of adrenal insufficiency"}, {"id": "d", "text": "A psychosocial complication of the disease"}]'::jsonb, '["d"]', 'Psychosocial complications of Crohn''s include depression and body image concerns. Perforation presents with sudden severe pain, fever, and tachycardia, not hopelessness.'),
  ('crohns', 44, 'A client who has had Crohn''s disease involving the colon for many years asks about the risk of colon cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Long-standing colon involvement increases the risk.\""}, {"id": "b", "text": "\"Crohn''s disease carries no colon cancer risk.\""}, {"id": "c", "text": "\"The risk exists only if you also have fistulas.\""}, {"id": "d", "text": "\"Surgery has already removed any cancer risk.\""}]'::jsonb, '["a"]', 'Colon cancer risk is a complication with long-standing colonic involvement in Crohn''s. Surgery is not curative for Crohn''s, so it does not remove ongoing disease risks.'),
  ('crohns', 45, 'The nurse is comparing two clients with inflammatory bowel disease. Which finding is more consistent with ulcerative colitis than with Crohn''s disease?', '[{"id": "a", "text": "Steatorrhea"}, {"id": "b", "text": "Bloody, mucus-filled diarrhea"}, {"id": "c", "text": "Skip lesions on endoscopy"}, {"id": "d", "text": "Fistula formation"}]'::jsonb, '["b"]', 'Ulcerative colitis causes bloody, mucus-filled diarrhea. Crohn''s diarrhea is often non-bloody with steatorrhea, and skip lesions and fistulas are features of Crohn''s.'),
  ('crohns', 46, 'A client with Crohn''s disease says, "My friend with ulcerative colitis was cured by having her colon removed. Why can''t surgery cure me?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Surgery can cure you once your diet improves.\""}, {"id": "b", "text": "\"Colectomy is curative for both diseases.\""}, {"id": "c", "text": "\"Crohn''s tends to recur even after surgery.\""}, {"id": "d", "text": "\"Surgery for Crohn''s only treats the rectum.\""}]'::jsonb, '["c"]', 'Colectomy is curative for ulcerative colitis, but surgery is not curative for Crohn''s because the disease recurs. The claim that colectomy cures both reverses the stated contrast.'),
  ('crohns', 47, 'The nurse is teaching about complications that differ between Crohn''s disease and ulcerative colitis. Which complication is associated with ulcerative colitis rather than Crohn''s disease?', '[{"id": "a", "text": "Fistulas"}, {"id": "b", "text": "Abscesses"}, {"id": "c", "text": "Strictures"}, {"id": "d", "text": "Toxic megacolon"}]'::jsonb, '["d"]', 'Toxic megacolon and colon cancer are listed complications of ulcerative colitis. Fistulas, abscesses, and strictures are complications of Crohn''s disease.'),
  ('crohns', 48, 'A client''s colonoscopy and biopsy report describes patchy inflammation that extends through all layers of the bowel wall. The nurse recognizes that these findings are most consistent with which condition?', '[{"id": "a", "text": "Crohn''s disease, which is transmural and patchy"}, {"id": "b", "text": "Ulcerative colitis, which is transmural and continuous"}, {"id": "c", "text": "Ulcerative colitis, which is mucosal and patchy"}, {"id": "d", "text": "Crohn''s disease, which is mucosal and continuous"}]'::jsonb, '["a"]', 'Crohn''s disease is transmural with skip lesions (patchy). Ulcerative colitis is mucosal/submucosal and continuous from the rectum upward.'),
  ('crohns', 49, 'The nurse provides medication teaching to a client with Crohn''s disease who is now symptom-free. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I can stop my medicines since I feel well.\""}, {"id": "b", "text": "\"I will keep taking my medicines as prescribed.\""}, {"id": "c", "text": "\"I only need medicine when I have diarrhea.\""}, {"id": "d", "text": "\"I will take my medicines only during flares.\""}]'::jsonb, '["b"]', 'Nurses educate on medication adherence, and immunosuppressants are used to prevent flare-ups. Stopping medications when feeling well conflicts with adherence teaching.'),
  ('crohns', 50, 'A client is admitted with an acute Crohn''s disease flare. Which medication does the nurse anticipate administering to control the acute inflammation?', '[{"id": "a", "text": "Loperamide"}, {"id": "b", "text": "Metronidazole"}, {"id": "c", "text": "Prednisone"}, {"id": "d", "text": "Azathioprine"}]'::jsonb, '["c"]', 'Corticosteroids such as prednisone treat acute inflammation and are administered during flares. Azathioprine is used to prevent flare-ups rather than to treat acute inflammation.'),
  ('uc', 1, 'A client newly diagnosed with ulcerative colitis asks which part of the body the disease affects. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The lining of the colon and rectum.\""}, {"id": "b", "text": "\"Any part from the mouth to the anus.\""}, {"id": "c", "text": "\"All layers of the small intestine.\""}, {"id": "d", "text": "\"The stomach and the esophagus.\""}]'::jsonb, '["a"]', 'Ulcerative colitis causes inflammation and ulcers in the lining of the colon and rectum only. Involvement anywhere from mouth to anus describes Crohn''s disease.'),
  ('uc', 2, 'The nurse is teaching a client about how ulcerative colitis spreads within the bowel. Which description is accurate?', '[{"id": "a", "text": "Patchy areas separated by healthy tissue"}, {"id": "b", "text": "Continuous inflammation from the rectum upward"}, {"id": "c", "text": "Inflammation that begins high and moves downward"}, {"id": "d", "text": "Scattered lesions from the mouth to the anus"}]'::jsonb, '["b"]', 'UC starts at the rectum and spreads upward in a continuous, not patchy, pattern. Patchy skip lesions anywhere from mouth to anus describe Crohn''s disease.'),
  ('uc', 3, 'A client with ulcerative colitis has had no symptoms for 4 months and asks, "Does this mean my disease is gone?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, being symptom-free means you are cured.\""}, {"id": "b", "text": "\"No, symptoms of this disease never fully stop.\""}, {"id": "c", "text": "\"The disease cycles between flares and remissions.\""}, {"id": "d", "text": "\"It means the disease is now limited to the rectum.\""}]'::jsonb, '["c"]', 'UC occurs in flares (active disease) and remissions (symptom-free). A symptom-free period is remission, not cure.'),
  ('uc', 4, 'A community health nurse is reviewing risk patterns for ulcerative colitis. Which client is in the age group in which the disease is most common?', '[{"id": "a", "text": "A 72-year-old retired teacher"}, {"id": "b", "text": "A 6-year-old first grader"}, {"id": "c", "text": "A 58-year-old office manager"}, {"id": "d", "text": "A 24-year-old graduate student"}]'::jsonb, '["d"]', 'UC is more common in young adults aged 15-35 years. The other clients fall outside this age range.'),
  ('uc', 5, 'A client with ulcerative colitis asks why the disease causes diarrhea. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The inflamed colon cannot absorb water well.\""}, {"id": "b", "text": "\"Fat is not absorbed in the small intestine.\""}, {"id": "c", "text": "\"Too much fiber is moving through the colon.\""}, {"id": "d", "text": "\"The bowel has become completely blocked.\""}]'::jsonb, '["a"]', 'In UC, the colon loses its ability to absorb water, which causes diarrhea. Fatty (non-bloody) diarrhea is the pattern listed for Crohn''s disease in the comparison.'),
  ('uc', 6, 'The nurse is assessing a client admitted with suspected ulcerative colitis. Which finding is the hallmark symptom of this disease?', '[{"id": "a", "text": "Fatty, greasy stools"}, {"id": "b", "text": "Frequent bloody diarrhea"}, {"id": "c", "text": "Hard stools with straining"}, {"id": "d", "text": "Right lower quadrant pain"}]'::jsonb, '["b"]', 'Frequent bloody diarrhea is the hallmark of UC. Fatty stools and RLQ pain are features of Crohn''s disease.'),
  ('uc', 7, 'A client with ulcerative colitis describes abdominal cramping. Which pattern of cramping does the nurse expect the client to report?', '[{"id": "a", "text": "Cramping located in the right lower quadrant"}, {"id": "b", "text": "Cramping that occurs only during sleep"}, {"id": "c", "text": "Cramping that worsens before bowel movements"}, {"id": "d", "text": "Cramping that is absent during active flares"}]'::jsonb, '["c"]', 'Abdominal cramping in UC is worse before bowel movements. RLQ pain is the location associated with Crohn''s disease.'),
  ('uc', 8, 'The nurse is interviewing a client with suspected ulcerative colitis. Which client statement is most consistent with this disease?', '[{"id": "a", "text": "\"My stools are greasy and look fatty.\""}, {"id": "b", "text": "\"I pass a hard stool about every 4 days.\""}, {"id": "c", "text": "\"My pain is mostly in my lower right side.\""}, {"id": "d", "text": "\"I have to rush to the toilet and see mucus.\""}]'::jsonb, '["d"]', 'Urgency to defecate and mucus in stool are GI symptoms of UC. Fatty stools and RLQ pain are listed for Crohn''s disease in the comparison.'),
  ('uc', 9, 'A client is admitted with a severe ulcerative colitis flare. The nurse anticipates the client''s stool frequency will most likely be in which range?', '[{"id": "a", "text": "10 to 20 stools per day"}, {"id": "b", "text": "1 to 2 stools per day"}, {"id": "c", "text": "1 stool every 3 days"}, {"id": "d", "text": "3 to 4 stools per week"}]'::jsonb, '["a"]', 'Frequent bloody diarrhea in severe UC can reach 10-20 stools per day. The lower frequencies do not reflect a severe flare.'),
  ('uc', 10, 'A client with ulcerative colitis has had many bloody stools over the past week, and the hemoglobin is low. How should the nurse interpret the low hemoglobin?', '[{"id": "a", "text": "Expected concentration from fluid loss"}, {"id": "b", "text": "Anemia resulting from blood loss"}, {"id": "c", "text": "A sign the disease is in remission"}, {"id": "d", "text": "A lab error, since bleeding is not linked"}]'::jsonb, '["b"]', 'Anemia in UC results from blood loss, and a CBC shows decreased RBCs. Ongoing bloody stools indicate active disease, not remission.'),
  ('uc', 11, 'The nurse is caring for a client experiencing a severe ulcerative colitis flare. Which group of systemic findings does the nurse expect?', '[{"id": "a", "text": "Weight gain and increased energy"}, {"id": "b", "text": "Hard stools and normal temperature"}, {"id": "c", "text": "Fever, fatigue, and weight loss"}, {"id": "d", "text": "Weight gain with formed stools"}]'::jsonb, '["c"]', 'Systemic symptoms of UC include weight loss, fatigue and weakness, and fever during severe flares. Weight gain and increased energy reverse the expected findings.'),
  ('uc', 12, 'A client with a severe ulcerative colitis flare reports severe abdominal pain. The abdomen is distended, the temperature is elevated, and the client has had no bowel movements since yesterday. The nurse suspects which complication?', '[{"id": "a", "text": "Entry into remission"}, {"id": "b", "text": "Expected treatment response"}, {"id": "c", "text": "Constipation from a low-fiber diet"}, {"id": "d", "text": "Toxic megacolon"}]'::jsonb, '["d"]', 'Severe abdominal pain, distension, fever, and no bowel movements are the signs of toxic megacolon, an emergency. Cessation of stools here is a danger sign, not improvement.'),
  ('uc', 13, 'The nurse suspects toxic megacolon in a client with ulcerative colitis. Which action should the nurse take first?', '[{"id": "a", "text": "Notify the health care provider immediately"}, {"id": "b", "text": "Administer the as-needed loperamide"}, {"id": "c", "text": "Prepare the client for a colonoscopy"}, {"id": "d", "text": "Offer the client high-fiber foods"}]'::jsonb, '["a"]', 'Toxic megacolon is an emergency because the overstretched colon may rupture, so immediate notification is required. Antidiarrheals and colonoscopy are avoided in severe flares.'),
  ('uc', 14, 'The family of a client with ulcerative colitis asks what toxic megacolon is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The colon shrinks and stops absorbing food.\""}, {"id": "b", "text": "\"The colon becomes overstretched and may rupture.\""}, {"id": "c", "text": "\"Ulcers heal and leave the colon lining smooth.\""}, {"id": "d", "text": "\"A tunnel forms between the colon and bladder.\""}]'::jsonb, '["b"]', 'In toxic megacolon, the colon becomes overstretched and may rupture, making it an emergency. An abnormal connection between organs describes a fistula, which is a Crohn''s complication.'),
  ('uc', 15, 'The nurse teaches a client with ulcerative colitis about toxic megacolon. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"If I stop having stools, my colitis is improving.\""}, {"id": "b", "text": "\"Swelling and fever are normal in flares, so I''ll wait.\""}, {"id": "c", "text": "\"I''ll get emergency care for swelling, fever, and no stools.\""}, {"id": "d", "text": "\"I''ll take loperamide if my belly becomes swollen.\""}]'::jsonb, '["c"]', 'Severe pain, distension, fever, and no bowel movements signal toxic megacolon, an emergency. Antidiarrheals increase the risk of toxic megacolon and should not be used.'),
  ('uc', 16, 'A client who has had ulcerative colitis for 12 years asks why the provider keeps scheduling colonoscopies. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They check whether the disease has reached your mouth.\""}, {"id": "b", "text": "\"They are needed only during severe flares.\""}, {"id": "c", "text": "\"They show whether surgery has cured you.\""}, {"id": "d", "text": "\"Colon cancer risk rises after 10+ years of UC.\""}]'::jsonb, '["d"]', 'Colon cancer risk increases after 10+ years of UC, so regular colonoscopies are needed for screening. Colonoscopy is avoided during severe flares because of perforation risk.'),
  ('uc', 17, 'The nurse teaches a client with long-standing ulcerative colitis about follow-up care. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I won''t need colonoscopies once my symptoms are controlled.\""}, {"id": "b", "text": "\"Regular colonoscopies help screen me for colon cancer.\""}, {"id": "c", "text": "\"My cancer risk grows the longer I have this disease.\""}, {"id": "d", "text": "\"I should not have a colonoscopy during a severe flare.\""}]'::jsonb, '["a"]', 'Patients with UC need regular colonoscopies to screen for colon cancer, regardless of symptom control. Avoiding colonoscopy during severe flares is correct because of perforation risk.'),
  ('uc', 18, 'A client is being evaluated for possible ulcerative colitis. Which diagnostic test does the nurse recognize as the gold standard for confirming the diagnosis?', '[{"id": "a", "text": "Stool sample"}, {"id": "b", "text": "Colonoscopy with biopsy"}, {"id": "c", "text": "Complete blood count"}, {"id": "d", "text": "Erythrocyte sedimentation rate"}]'::jsonb, '["b"]', 'Colonoscopy with biopsy is the gold standard that confirms UC by showing continuous inflammation in the colon. A stool sample rules out infection but does not confirm UC.'),
  ('uc', 19, 'A client with bloody diarrhea is being evaluated for ulcerative colitis, and a stool sample is ordered. The client asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It confirms the diagnosis of ulcerative colitis.\""}, {"id": "b", "text": "\"It measures your inflammatory markers.\""}, {"id": "c", "text": "\"It rules out bacterial, viral, or parasitic infection.\""}, {"id": "d", "text": "\"It checks whether you have become anemic.\""}]'::jsonb, '["c"]', 'A stool sample rules out bacterial, viral, and parasitic infections. Colonoscopy with biopsy confirms UC, and the CBC detects anemia.'),
  ('uc', 20, 'The nurse reviews the complete blood count of a client with an active ulcerative colitis flare. Which findings does the nurse expect?', '[{"id": "a", "text": "Elevated RBCs and decreased WBCs"}, {"id": "b", "text": "Elevated RBCs and elevated WBCs"}, {"id": "c", "text": "Normal RBCs and decreased WBCs"}, {"id": "d", "text": "Decreased RBCs and elevated WBCs"}]'::jsonb, '["d"]', 'The CBC in UC shows anemia (decreased RBCs) and elevated WBCs from inflammation. The other options reverse one or both directions.'),
  ('uc', 21, 'A client with ulcerative colitis has elevated ESR and CRP results. How should the nurse interpret these findings?', '[{"id": "a", "text": "They indicate active inflammation."}, {"id": "b", "text": "They confirm a parasitic infection."}, {"id": "c", "text": "They confirm the client is anemic."}, {"id": "d", "text": "They confirm the client has cancer."}]'::jsonb, '["a"]', 'ESR and CRP are elevated inflammatory markers in UC. Infection is ruled out by stool sample, and anemia is identified by the CBC.'),
  ('uc', 22, 'A client is admitted with a severe ulcerative colitis flare, and a colonoscopy is scheduled for the next morning. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Proceed with the bowel preparation as ordered"}, {"id": "b", "text": "Question the order because of perforation risk"}, {"id": "c", "text": "Give loperamide before the procedure"}, {"id": "d", "text": "Offer high-fiber foods the night before"}]'::jsonb, '["b"]', 'Colonoscopy should be avoided during severe flares because of the risk of perforation. Antidiarrheals and high-fiber foods are also avoided in severe flares.'),
  ('uc', 23, 'A client is newly diagnosed with mild ulcerative colitis. Which medication does the nurse anticipate as first-line treatment?', '[{"id": "a", "text": "Prednisone"}, {"id": "b", "text": "Infliximab"}, {"id": "c", "text": "Mesalamine"}, {"id": "d", "text": "Loperamide"}]'::jsonb, '["c"]', 'Mesalamine, an aminosalicylate, is first-line treatment for UC. Biologics like infliximab are reserved for severe cases, and corticosteroids are for acute flares only.'),
  ('uc', 24, 'A client with ulcerative colitis is prescribed sulfasalazine. Which instruction should the nurse include in the teaching?', '[{"id": "a", "text": "\"Take it on an empty stomach.\""}, {"id": "b", "text": "\"Stop it once your stools are formed.\""}, {"id": "c", "text": "\"Take it only during severe flares.\""}, {"id": "d", "text": "\"Take each dose with food.\""}]'::jsonb, '["d"]', 'Aminosalicylates should be taken with food, with monitoring of kidney and liver function. Stopping when stools form conflicts with adherence teaching, which prevents flares.'),
  ('uc', 25, 'A client with ulcerative colitis takes mesalamine long-term. Which monitoring does the nurse anticipate will be ordered periodically for this medication?', '[{"id": "a", "text": "Kidney and liver function"}, {"id": "b", "text": "Bone mineral density"}, {"id": "c", "text": "Infusion-related reactions"}, {"id": "d", "text": "Fecal fat measurement"}]'::jsonb, '["a"]', 'Aminosalicylates such as mesalamine require kidney and liver monitoring. Osteoporosis is a concern with corticosteroids, and allergic reactions are monitored with biologics.'),
  ('uc', 26, 'A client with ulcerative colitis asks why prednisone cannot be taken long-term to keep the disease under control. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It stops working after the first week.\""}, {"id": "b", "text": "\"Long-term use risks osteoporosis and infection.\""}, {"id": "c", "text": "\"It directly causes toxic megacolon.\""}, {"id": "d", "text": "\"It is reserved for colon cancer treatment.\""}]'::jsonb, '["b"]', 'Corticosteroids are short-term only because of osteoporosis and infection risk. Toxic megacolon risk is linked to antidiarrheals in severe flares, not corticosteroids.'),
  ('uc', 27, 'The nurse teaches a client with ulcerative colitis about prednisone. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"Prednisone will be my long-term daily maintenance drug.\""}, {"id": "b", "text": "\"Prednisone has no effect on my risk of infection.\""}, {"id": "c", "text": "\"Prednisone is used short-term for acute flares only.\""}, {"id": "d", "text": "\"Prednisone is the first-line drug for my condition.\""}]'::jsonb, '["c"]', 'Corticosteroids are for acute flares only and are short-term because of osteoporosis and infection risk. Mesalamine, not prednisone, is first-line treatment.'),
  ('uc', 28, 'A client with ulcerative colitis is taking azathioprine to prevent attacks. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "Fewer stools per day"}, {"id": "b", "text": "A 1-lb weight gain"}, {"id": "c", "text": "Improved energy level"}, {"id": "d", "text": "A new fever"}]'::jsonb, '["d"]', 'Immunosuppressants such as azathioprine require monitoring for infections, so a new fever should be reported. The other findings suggest improvement.'),
  ('uc', 29, 'A client with ulcerative colitis is receiving an infliximab infusion. In addition to infection, which problem should the nurse monitor for during therapy?', '[{"id": "a", "text": "Allergic reactions"}, {"id": "b", "text": "Osteoporosis"}, {"id": "c", "text": "Fatty stools"}, {"id": "d", "text": "Fistula formation"}]'::jsonb, '["a"]', 'Biologics such as infliximab require monitoring for allergic reactions and infections. Osteoporosis is a risk of long-term corticosteroid use.'),
  ('uc', 30, 'The nurse is reviewing the medication plan for several clients with ulcerative colitis. For which client is adalimumab most appropriate?', '[{"id": "a", "text": "A client newly diagnosed with mild disease"}, {"id": "b", "text": "A client with severe disease"}, {"id": "c", "text": "A client in remission with no symptoms"}, {"id": "d", "text": "A client needing short-term diarrhea relief"}]'::jsonb, '["b"]', 'Biologics such as adalimumab and infliximab are used for severe cases. Mesalamine is first-line for UC, and loperamide is the antidiarrheal.'),
  ('uc', 31, 'A client in a severe ulcerative colitis flare asks for loperamide to reduce the number of stools. Which response by the nurse is best?', '[{"id": "a", "text": "\"I will give it now to reduce your fluid losses.\""}, {"id": "b", "text": "\"It is safe because it only slows your bowel.\""}, {"id": "c", "text": "\"It is avoided in severe flares due to toxic megacolon risk.\""}, {"id": "d", "text": "\"You may take it as long as you also take mesalamine.\""}]'::jsonb, '["c"]', 'Antidiarrheals are avoided in severe flares because of the risk of toxic megacolon. Taking mesalamine does not remove this risk.'),
  ('uc', 32, 'The charge nurse observes a new nurse caring for clients with ulcerative colitis. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Encouraging oral fluid intake"}, {"id": "b", "text": "Monitoring stools for blood"}, {"id": "c", "text": "Teaching stress-reduction methods"}, {"id": "d", "text": "Giving loperamide during a severe flare"}]'::jsonb, '["d"]', 'The nurse should remind clients that no antidiarrheals are used during severe flares. Encouraging hydration, monitoring for bloody diarrhea, and promoting stress reduction are appropriate.'),
  ('uc', 33, 'A client is hospitalized with an ulcerative colitis flare. Which dietary instruction should the nurse give?', '[{"id": "a", "text": "\"Choose a low-fiber, high-protein diet.\""}, {"id": "b", "text": "\"Choose a high-fiber, low-protein diet.\""}, {"id": "c", "text": "\"Choose a low-calorie, low-protein diet.\""}, {"id": "d", "text": "\"Choose high-fiber foods to firm stools.\""}]'::jsonb, '["a"]', 'A low-fiber diet reduces colon irritation, and a high-calorie, high-protein diet is recommended. High-fiber foods are avoided during flares.'),
  ('uc', 34, 'The nurse teaches a client about diet during ulcerative colitis flares. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will choose high-calorie, high-protein foods.\""}, {"id": "b", "text": "\"I will add extra high-fiber foods during flares.\""}, {"id": "c", "text": "\"A low-fiber diet helps reduce colon irritation.\""}, {"id": "d", "text": "\"I will keep drinking fluids to stay hydrated.\""}]'::jsonb, '["b"]', 'No high-fiber foods should be eaten during flares, so this statement needs correction. High-calorie, high-protein, low-fiber eating and hydration are appropriate.'),
  ('uc', 35, 'A client with ulcerative colitis has lost weight and appears fatigued. Which diet should the nurse recommend to support nutrition?', '[{"id": "a", "text": "Low-calorie, low-protein"}, {"id": "b", "text": "High-fiber, high-fat"}, {"id": "c", "text": "High-calorie, high-protein"}, {"id": "d", "text": "Low-calorie, high-fiber"}]'::jsonb, '["c"]', 'UC diet teaching includes a high-calorie, high-protein diet. High-fiber foods are avoided during flares.'),
  ('uc', 36, 'A client with severe ulcerative colitis that has not responded to medications asks whether surgery could cure the disease. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No, surgery can only manage the symptoms.\""}, {"id": "b", "text": "\"No, the disease always returns after surgery.\""}, {"id": "c", "text": "\"Yes, but only removal of the rectum is needed.\""}, {"id": "d", "text": "\"Yes, removing the colon and rectum is a cure.\""}]'::jsonb, '["d"]', 'Proctocolectomy, removal of the entire colon and rectum, is a permanent cure for UC. Recurrence after surgery describes Crohn''s disease.'),
  ('uc', 37, 'A client with ulcerative colitis is scheduled for a proctocolectomy with an ileostomy. The client asks what an ileostomy is. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"An opening that lets waste exit through a stoma.\""}, {"id": "b", "text": "\"A procedure that widens a narrowed bowel.\""}, {"id": "c", "text": "\"A removal of only the lower rectum.\""}, {"id": "d", "text": "\"A tube placed through the nose to the stomach.\""}]'::jsonb, '["a"]', 'An ileostomy is a surgical opening for waste to exit through a stoma. Proctocolectomy removes the entire colon and rectum, not only the rectum.'),
  ('uc', 38, 'A nursing student is comparing surgical outcomes in inflammatory bowel disease. Which statement by the student is accurate?', '[{"id": "a", "text": "\"Neither UC nor Crohn''s can be cured by surgery.\""}, {"id": "b", "text": "\"UC can be cured with surgery, but Crohn''s cannot.\""}, {"id": "c", "text": "\"Crohn''s can be cured with surgery, but UC cannot.\""}, {"id": "d", "text": "\"Both UC and Crohn''s are cured by surgery.\""}]'::jsonb, '["b"]', 'Unlike Crohn''s disease, UC can be cured with surgery. Crohn''s is managed only and is not curable.'),
  ('uc', 39, 'The nurse is comparing assessment findings in two clients with inflammatory bowel disease. Which finding is more consistent with Crohn''s disease than with ulcerative colitis?', '[{"id": "a", "text": "Bloody diarrhea 10 to 20 times a day"}, {"id": "b", "text": "Inflammation continuous from the rectum"}, {"id": "c", "text": "Pain in the right lower quadrant"}, {"id": "d", "text": "Inflammation limited to the mucosa"}]'::jsonb, '["c"]', 'RLQ pain from terminal ileum involvement is associated with Crohn''s, while UC pain is in the LLQ. Bloody frequent diarrhea, continuous spread, and mucosal-only inflammation describe UC.'),
  ('uc', 40, 'The nurse is caring for two clients with inflammatory bowel disease. One has bloody diarrhea; the other has fatty, non-bloody diarrhea. Which interpretation is correct?', '[{"id": "a", "text": "Both stool patterns point to ulcerative colitis."}, {"id": "b", "text": "Bloody stools suggest Crohn''s; fatty stools suggest UC."}, {"id": "c", "text": "Both stool patterns point to Crohn''s disease."}, {"id": "d", "text": "Bloody stools suggest UC; fatty stools suggest Crohn''s."}]'::jsonb, '["d"]', 'Bloody diarrhea points to UC, while fatty/non-bloody diarrhea points to Crohn''s. The reversed pairing is a common error.'),
  ('uc', 41, 'A client''s biopsy report is being compared for ulcerative colitis versus Crohn''s disease. Which depth of inflammation is characteristic of ulcerative colitis?', '[{"id": "a", "text": "Limited to the mucosal layer"}, {"id": "b", "text": "Through all layers of the wall"}, {"id": "c", "text": "Only the outer muscular layer"}, {"id": "d", "text": "Patchy through the full wall"}]'::jsonb, '["a"]', 'UC involves the mucosal layer only. Transmural inflammation through all layers is characteristic of Crohn''s disease.'),
  ('uc', 42, 'The nurse is planning care for a client with ulcerative colitis. Which complication should the nurse monitor for that is associated with UC rather than Crohn''s disease?', '[{"id": "a", "text": "Fistulas"}, {"id": "b", "text": "Toxic megacolon"}, {"id": "c", "text": "Abscesses"}, {"id": "d", "text": "Strictures"}]'::jsonb, '["b"]', 'Toxic megacolon and colon cancer are complications of UC. Fistulas, abscesses, and strictures are complications of Crohn''s disease.'),
  ('uc', 43, 'A client with ulcerative colitis reports that flares often occur during exam weeks at school. Which nursing intervention is most appropriate?', '[{"id": "a", "text": "Increase fiber intake before exams"}, {"id": "b", "text": "Take loperamide daily during exams"}, {"id": "c", "text": "Promote stress-reduction techniques"}, {"id": "d", "text": "Stop mesalamine during exam weeks"}]'::jsonb, '["c"]', 'The nurse promotes stress reduction because stress triggers flares. Stopping medications conflicts with adherence teaching, which prevents flares.'),
  ('uc', 44, 'A client with ulcerative colitis in remission says, "I feel great, so I''m going to stop taking my mesalamine." Which response by the nurse is best?', '[{"id": "a", "text": "\"That is fine once you have no symptoms.\""}, {"id": "b", "text": "\"Switch to prednisone for long-term control.\""}, {"id": "c", "text": "\"Take it only on days you have bloody stools.\""}, {"id": "d", "text": "\"Taking it as prescribed helps prevent flares.\""}]'::jsonb, '["d"]', 'Education on medication adherence prevents flares. Prednisone is short-term only and is not used for long-term control.'),
  ('uc', 45, 'A client with ulcerative colitis has frequent diarrhea. Which nursing action is most appropriate?', '[{"id": "a", "text": "Encourage hydration and proper nutrition"}, {"id": "b", "text": "Restrict fluids to decrease stool output"}, {"id": "c", "text": "Encourage high-fiber foods with each meal"}, {"id": "d", "text": "Give an antidiarrheal during a severe flare"}]'::jsonb, '["a"]', 'Nursing care includes encouraging hydration and proper nutrition. Antidiarrheals are avoided during severe flares, and high-fiber foods are avoided during flares.'),
  ('uc', 46, 'The nurse is monitoring the stools of a client with ulcerative colitis for blood. The nurse understands that this monitoring is primarily done because of the risk for which problem?', '[{"id": "a", "text": "Fatty stools"}, {"id": "b", "text": "Anemia"}, {"id": "c", "text": "Fistula formation"}, {"id": "d", "text": "Weight gain"}]'::jsonb, '["b"]', 'Monitoring for bloody diarrhea is done because of the risk of anemia. Fatty stools and fistulas are associated with Crohn''s disease.'),
  ('uc', 47, 'A client with ulcerative colitis asks which complications to watch for. Which list includes only complications of ulcerative colitis?', '[{"id": "a", "text": "Fistulas, abscesses, and bowel strictures"}, {"id": "b", "text": "Toxic megacolon, fistulas, and steatorrhea"}, {"id": "c", "text": "Toxic megacolon, GI bleeding, and colon cancer"}, {"id": "d", "text": "Abscesses, colon cancer, and bowel strictures"}]'::jsonb, '["c"]', 'UC complications include toxic megacolon, severe GI bleeding, colon cancer, malnutrition, and anemia. Fistulas, abscesses, and strictures are complications of Crohn''s disease.'),
  ('uc', 48, 'A client with ulcerative colitis is started on an aminosalicylate. Which medication does the nurse expect to administer?', '[{"id": "a", "text": "Hydrocortisone"}, {"id": "b", "text": "Azathioprine"}, {"id": "c", "text": "Adalimumab"}, {"id": "d", "text": "Sulfasalazine"}]'::jsonb, '["d"]', 'Sulfasalazine and mesalamine are aminosalicylates. Hydrocortisone is a corticosteroid, azathioprine an immunosuppressant, and adalimumab a biologic.'),
  ('uc', 49, 'A client with ulcerative colitis asks why there is blood in the stool. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Chronic inflammation causes ulcers that bleed.\""}, {"id": "b", "text": "\"Unabsorbed fat irritates the small bowel.\""}, {"id": "c", "text": "\"Stress alone causes the colon to bleed.\""}, {"id": "d", "text": "\"Hard stools tear the lining of the rectum.\""}]'::jsonb, '["a"]', 'In UC, chronic inflammation leads to ulcers and bleeding. Stress triggers flares but is not described as the direct cause of bleeding.'),
  ('uc', 50, 'The nurse receives report on four clients with ulcerative colitis. Which client should the nurse assess first?', '[{"id": "a", "text": "A client reporting mucus in the stool"}, {"id": "b", "text": "A client with fever, distension, and no stools"}, {"id": "c", "text": "A client reporting urgency to defecate"}, {"id": "d", "text": "A client with cramping before bowel movements"}]'::jsonb, '["b"]', 'Fever, distension, and no bowel movements are signs of toxic megacolon, an emergency in which the colon may rupture. Mucus, urgency, and cramping before bowel movements are expected UC symptoms.'),
  ('ibs', 1, 'A nursing student asks how irritable bowel syndrome (IBS) affects the bowel. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It is a functional disorder with no tissue damage.\""}, {"id": "b", "text": "\"It causes chronic inflammation with damage to the mucosa.\""}, {"id": "c", "text": "\"It causes transmural inflammation and deep ulceration.\""}, {"id": "d", "text": "\"It causes bleeding ulcers in the lining of the colon.\""}]'::jsonb, '["a"]', 'IBS involves no inflammation, no bleeding, and no tissue damage; it is a functional disorder only. Chronic inflammation with mucosal/transmural damage describes Crohn''s and UC.'),
  ('ibs', 2, 'A client with chronic abdominal pain and bloating asks how the provider will determine whether the problem is IBS. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A biopsy must show ulcers in your colon lining.\""}, {"id": "b", "text": "\"It is based on symptoms and ruling out other causes.\""}, {"id": "c", "text": "\"Your CRP and ESR levels must be elevated first.\""}, {"id": "d", "text": "\"A stool test must show blood in the stool.\""}]'::jsonb, '["b"]', 'IBS is diagnosed by symptoms and exclusion of other conditions. Elevated CRP/ESR and blood in stool point to IBD rather than IBS.'),
  ('ibs', 3, 'The nurse is assessing a client with suspected IBS who reports abdominal cramping. Which description of the cramping is the key characteristic of IBS?', '[{"id": "a", "text": "Cramping that worsens after each bowel movement"}, {"id": "b", "text": "Cramping accompanied by fever and bloody stools"}, {"id": "c", "text": "Cramping that is relieved by a bowel movement"}, {"id": "d", "text": "Cramping that occurs only during sleep at night"}]'::jsonb, '["c"]', 'Pain relieved by a bowel movement is the key IBS characteristic. Fever and bloody stools suggest Crohn''s or UC rather than IBS.'),
  ('ibs', 4, 'A client with a known diagnosis of IBS calls the clinic. Which reported finding should the nurse recognize as inconsistent with IBS?', '[{"id": "a", "text": "Mucus in the stool"}, {"id": "b", "text": "Bloating and gas"}, {"id": "c", "text": "Urgency to defecate"}, {"id": "d", "text": "Blood in the stool"}]'::jsonb, '["d"]', 'Mucus in stool is acceptable in IBS, but blood in stool is not IBS. Bloating, gas, and urgency are expected IBS symptoms.'),
  ('ibs', 5, 'A client with IBS is worried after noticing mucus in the stool. There is no blood present. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Mucus can occur with IBS, but report any blood.\""}, {"id": "b", "text": "\"Mucus means your bowel is inflamed and damaged.\""}, {"id": "c", "text": "\"Mucus means you have developed colon cancer.\""}, {"id": "d", "text": "\"Mucus means IBS has become ulcerative colitis.\""}]'::jsonb, '["a"]', 'Mucus in stool without blood is a symptom of IBS. IBS involves no inflammation or tissue damage, so mucus alone does not indicate damage.'),
  ('ibs', 6, 'A client with a long history of IBS reports a new fever and a 5-kg unintentional weight loss over the past month. How should the nurse interpret these findings?', '[{"id": "a", "text": "They are typical of an IBS flare."}, {"id": "b", "text": "They suggest IBD rather than IBS."}, {"id": "c", "text": "They show the diet is working."}, {"id": "d", "text": "They are expected with IBS-M."}]'::jsonb, '["b"]', 'Blood, fever, and weight loss suggest IBD (Crohn''s or UC), not IBS. These are not expected IBS findings of any type.'),
  ('ibs', 7, 'A client newly diagnosed with IBS asks what usually sets off the symptoms. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A bacterial infection is the only cause.\""}, {"id": "b", "text": "\"Bleeding ulcers in the colon start them.\""}, {"id": "c", "text": "\"Stress, food, and hormones often trigger them.\""}, {"id": "d", "text": "\"Symptoms have no relation to diet or stress.\""}]'::jsonb, '["c"]', 'IBS is often triggered by stress, food, and hormones. IBS involves no bleeding or tissue damage.'),
  ('ibs', 8, 'The nurse is completing a health history for a client with IBS. Which group of symptoms does the nurse expect the client to report?', '[{"id": "a", "text": "Fever, bloody stools, and weight loss"}, {"id": "b", "text": "Bloody diarrhea and new-onset fever"}, {"id": "c", "text": "Weight loss and bright red rectal blood"}, {"id": "d", "text": "Bloating, gas, and incomplete evacuation"}]'::jsonb, '["d"]', 'IBS symptoms include bloating and gas and a sensation of incomplete evacuation. Blood, fever, and weight loss suggest Crohn''s or UC.'),
  ('ibs', 9, 'A client with IBS reports periods of diarrhea that alternate with periods of constipation. The nurse recognizes this pattern as which type of IBS?', '[{"id": "a", "text": "IBS-M"}, {"id": "b", "text": "IBS-D"}, {"id": "c", "text": "IBS-C"}, {"id": "d", "text": "IBD"}]'::jsonb, '["a"]', 'IBS-M is the mixed (alternating) type. IBS-D is diarrhea-predominant and IBS-C is constipation-predominant.'),
  ('ibs', 10, 'A client has constipation-predominant IBS. Which medication does the nurse anticipate will be prescribed for the constipation?', '[{"id": "a", "text": "Loperamide"}, {"id": "b", "text": "Polyethylene glycol"}, {"id": "c", "text": "Dicyclomine"}, {"id": "d", "text": "A biologic agent"}]'::jsonb, '["b"]', 'Laxatives such as polyethylene glycol are used for IBS-C. Loperamide is used for IBS-D, and biologics are an IBD treatment.'),
  ('ibs', 11, 'A client with diarrhea-predominant IBS asks for medication to control the diarrhea. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Polyethylene glycol"}, {"id": "b", "text": "An immunosuppressant"}, {"id": "c", "text": "Loperamide"}, {"id": "d", "text": "A biologic agent"}]'::jsonb, '["c"]', 'Antidiarrheals such as loperamide are used for IBS-D. Polyethylene glycol is a laxative for IBS-C, and immunosuppressants and biologics are IBD treatments.'),
  ('ibs', 12, 'A client with IBS is prescribed dicyclomine and asks what it is for. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It relieves constipation.\""}, {"id": "b", "text": "\"It slows down diarrhea.\""}, {"id": "c", "text": "\"It cures the disorder.\""}, {"id": "d", "text": "\"It relieves pain and cramps.\""}]'::jsonb, '["d"]', 'Antispasmodics such as dicyclomine are used for pain/cramp relief. Laxatives treat constipation, and IBS has no cure.'),
  ('ibs', 13, 'A client with severe IBS is prescribed a low-dose tricyclic antidepressant and says, "Does my provider think I''m just depressed?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Low doses help modulate the gut-brain axis.\""}, {"id": "b", "text": "\"It is used to heal ulcers in your bowel.\""}, {"id": "c", "text": "\"It is used to reduce inflammation in the colon.\""}, {"id": "d", "text": "\"It is used to stop bleeding from the bowel.\""}]'::jsonb, '["a"]', 'Low-dose antidepressants (TCAs, SSRIs) are used for severe symptoms to modulate the gut-brain axis. IBS involves no inflammation, ulcers, or bleeding.'),
  ('ibs', 14, 'A client with IBS asks whether probiotics might help. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They will cure IBS permanently.\""}, {"id": "b", "text": "\"They may improve gut flora balance.\""}, {"id": "c", "text": "\"They heal ulcers in the colon.\""}, {"id": "d", "text": "\"They reduce bowel inflammation.\""}]'::jsonb, '["b"]', 'Probiotics may improve gut flora balance. IBS has no cure and involves no ulcers or inflammation.'),
  ('ibs', 15, 'A client is newly diagnosed with IBS. Which dietary approach should the nurse teach as the primary dietary treatment?', '[{"id": "a", "text": "High insoluble fiber diet"}, {"id": "b", "text": "High-fat, high-calorie diet"}, {"id": "c", "text": "Low FODMAP diet"}, {"id": "d", "text": "High-lactose dairy diet"}]'::jsonb, '["c"]', 'The low FODMAP diet is the primary dietary treatment for IBS. Fiber should be soluble, not insoluble, and fatty foods should be avoided.'),
  ('ibs', 16, 'A client with IBS asks about adding fiber to the diet. Which recommendation by the nurse is correct?', '[{"id": "a", "text": "\"Increase insoluble fiber with every meal.\""}, {"id": "b", "text": "\"Avoid all forms of fiber completely.\""}, {"id": "c", "text": "\"Fiber has no effect on IBS symptoms.\""}, {"id": "d", "text": "\"Increase soluble fiber such as oats.\""}]'::jsonb, '["d"]', 'Clients with IBS should increase soluble fiber, such as oats and psyllium, not insoluble fiber.'),
  ('ibs', 17, 'The nurse teaches a client with IBS about fiber. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll focus on insoluble fiber for my symptoms.\""}, {"id": "b", "text": "\"I can add oats to my breakfast each day.\""}, {"id": "c", "text": "\"Psyllium is a soluble fiber I may use.\""}, {"id": "d", "text": "\"Soluble fiber is the kind I should increase.\""}]'::jsonb, '["a"]', 'Teaching specifies soluble fiber (oats, psyllium), not insoluble fiber, so this statement needs correction.'),
  ('ibs', 18, 'The nurse reviews dietary changes with a client who has IBS. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will limit the alcohol I drink.\""}, {"id": "b", "text": "\"I will drink extra coffee each morning.\""}, {"id": "c", "text": "\"I will cut back on fatty foods.\""}, {"id": "d", "text": "\"I will avoid my own trigger foods.\""}]'::jsonb, '["b"]', 'Clients with IBS should avoid caffeine, alcohol, and fatty foods, so drinking extra coffee needs correction. Identifying and avoiding personal trigger foods is appropriate.'),
  ('ibs', 19, 'A client following a low FODMAP diet asks which foods are sources of fructans (oligosaccharides). Which foods should the nurse identify?', '[{"id": "a", "text": "Milk and yogurt"}, {"id": "b", "text": "Apples and honey"}, {"id": "c", "text": "Wheat, onions, and garlic"}, {"id": "d", "text": "Sorbitol and mannitol"}]'::jsonb, '["c"]', 'Oligosaccharides such as fructans are found in wheat, onions, and garlic. Milk and yogurt contain lactose (a disaccharide), and apples and honey contain excess fructose (a monosaccharide).'),
  ('ibs', 20, 'The nurse teaches a client with IBS about the disaccharide group of FODMAPs. Which foods belong to this group?', '[{"id": "a", "text": "Wheat and onions"}, {"id": "b", "text": "Apples and honey"}, {"id": "c", "text": "Sugar-free gum"}, {"id": "d", "text": "Milk and yogurt"}]'::jsonb, '["d"]', 'The disaccharide in FODMAP is lactose, found in milk and yogurt. Apples and honey are sources of excess fructose, a monosaccharide.'),
  ('ibs', 21, 'A client with IBS reports bloating after a snack high in excess fructose. Which snack did the client most likely eat?', '[{"id": "a", "text": "Apple slices with honey"}, {"id": "b", "text": "Garlic bread with butter"}, {"id": "c", "text": "A cup of plain yogurt"}, {"id": "d", "text": "A glass of cold milk"}]'::jsonb, '["a"]', 'Excess fructose (a monosaccharide) is found in apples and honey. Garlic and wheat contain oligosaccharides, and milk and yogurt contain lactose.'),
  ('ibs', 22, 'A client with IBS chews sugar-free gum sweetened with sorbitol throughout the day and reports bloating. The nurse explains that sorbitol belongs to which FODMAP group?', '[{"id": "a", "text": "Oligosaccharides"}, {"id": "b", "text": "Polyols"}, {"id": "c", "text": "Disaccharides"}, {"id": "d", "text": "Monosaccharides"}]'::jsonb, '["b"]', 'Polyols are sugar alcohols such as sorbitol and mannitol found in artificial sweeteners. Disaccharides refer to lactose, and monosaccharides to excess fructose.'),
  ('ibs', 23, 'A client with IBS asks why high-FODMAP foods cause symptoms. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"They cause bleeding ulcers in the colon.\""}, {"id": "b", "text": "\"They inflame all layers of the bowel wall.\""}, {"id": "c", "text": "\"Poorly absorbed carbs are fermented by gut bacteria.\""}, {"id": "d", "text": "\"They are completely absorbed before the colon.\""}]'::jsonb, '["c"]', 'FODMAPs are short-chain carbohydrates poorly absorbed in the small intestine that are fermented by gut bacteria, causing gas, bloating, and diarrhea. They are not completely absorbed, and IBS involves no inflammation or bleeding.'),
  ('ibs', 24, 'A client with IBS is planning breakfast. Which choice is most consistent with IBS dietary teaching?', '[{"id": "a", "text": "Yogurt topped with honey"}, {"id": "b", "text": "Toast with garlic butter"}, {"id": "c", "text": "Coffee with an apple"}, {"id": "d", "text": "Oatmeal made with water"}]'::jsonb, '["d"]', 'Oats are a recommended soluble fiber. Yogurt and honey, garlic and wheat, and apples are high-FODMAP foods, and caffeine should be avoided.'),
  ('ibs', 25, 'A client with IBS is unsure which foods trigger symptoms. Which approach should the nurse teach to identify trigger foods?', '[{"id": "a", "text": "Eliminate suspected foods and monitor the response"}, {"id": "b", "text": "Eat all foods freely and treat symptoms with medicine"}, {"id": "c", "text": "Add high-FODMAP foods daily to build tolerance"}, {"id": "d", "text": "Skip meals whenever symptoms begin to appear"}]'::jsonb, '["a"]', 'The nurse teaches the low FODMAP diet and has the client identify trigger foods through elimination. Skipping meals should be avoided.'),
  ('ibs', 26, 'A client with IBS reports often skipping breakfast and lunch on busy workdays. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Skipping meals gives the bowel time to rest.\""}, {"id": "b", "text": "\"Eat meals on a regular schedule each day.\""}, {"id": "c", "text": "\"Eat one large meal at the end of the day.\""}, {"id": "d", "text": "\"Meal timing has no effect on IBS symptoms.\""}]'::jsonb, '["b"]', 'Lifestyle modifications for IBS include a regular meal schedule and avoiding skipped meals.'),
  ('ibs', 27, 'A client with IBS reports that symptoms become much worse during work deadlines. Which nursing intervention is most appropriate?', '[{"id": "a", "text": "Recommend skipping meals during busy weeks"}, {"id": "b", "text": "Recommend more caffeine to manage fatigue"}, {"id": "c", "text": "Recommend stress reduction strategies"}, {"id": "d", "text": "Recommend limiting fluids at work"}]'::jsonb, '["c"]', 'Stress directly worsens IBS, so stress reduction is a key lifestyle modification. Caffeine should be avoided, and adequate hydration and regular meals are encouraged.'),
  ('ibs', 28, 'The nurse is teaching lifestyle modifications to a client with IBS. Which recommendation is appropriate?', '[{"id": "a", "text": "\"Limit fluids to reduce diarrhea.\""}, {"id": "b", "text": "\"Avoid all physical activity.\""}, {"id": "c", "text": "\"Skip meals when you feel bloated.\""}, {"id": "d", "text": "\"Exercise regularly and stay hydrated.\""}]'::jsonb, '["d"]', 'IBS lifestyle modifications include regular exercise, adequate hydration, stress reduction, and a regular meal schedule. Skipping meals and limiting fluids conflict with this teaching.'),
  ('ibs', 29, 'A client newly diagnosed with IBS says, "My uncle had colon cancer. Does IBS mean I''ll get cancer too?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"IBS does not increase your cancer risk.\""}, {"id": "b", "text": "\"IBS greatly raises your colon cancer risk.\""}, {"id": "c", "text": "\"IBS turns into cancer after 10 years.\""}, {"id": "d", "text": "\"IBS carries the same risk as Crohn''s.\""}]'::jsonb, '["a"]', 'The nurse educates that IBS does not increase cancer risk, unlike IBD.'),
  ('ibs', 30, 'A client with IBS asks, "Will this ever go away completely?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, surgery can cure it permanently.\""}, {"id": "b", "text": "\"No cure exists, but symptoms are manageable.\""}, {"id": "c", "text": "\"Yes, medication cures it within weeks.\""}, {"id": "d", "text": "\"No, and the symptoms cannot be controlled.\""}]'::jsonb, '["b"]', 'IBS has no cure, but symptoms are manageable with lifestyle changes. Surgery is listed as an IBD treatment, not an IBS treatment.'),
  ('ibs', 31, 'A client with IBS says, "I''m afraid all these years of symptoms have destroyed my intestines." Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Yes, your intestines likely have deep ulcers.\""}, {"id": "b", "text": "\"Yes, scarring from IBS builds up over time.\""}, {"id": "c", "text": "\"IBS does not cause permanent bowel damage.\""}, {"id": "d", "text": "\"Your bowel lining is probably bleeding.\""}]'::jsonb, '["c"]', 'The nurse reassures that IBS causes no permanent bowel damage. Ulcers and scarring are tissue damage associated with IBD.'),
  ('ibs', 32, 'A client with presumed IBS has laboratory tests drawn. Which result pattern should prompt the nurse to suspect IBD instead of IBS?', '[{"id": "a", "text": "Normal CRP, ESR, and hemoglobin"}, {"id": "b", "text": "Low CRP and ESR, high hemoglobin"}, {"id": "c", "text": "Normal ESR with a high hemoglobin"}, {"id": "d", "text": "Elevated CRP and ESR, low hemoglobin"}]'::jsonb, '["d"]', 'IBD causes elevated CRP and ESR and decreased Hgb, while IBS is associated with normal labs.'),
  ('ibs', 33, 'The nurse is evaluating a client who has chronic bowel symptoms. Which finding is more suggestive of inflammatory bowel disease than IBS?', '[{"id": "a", "text": "Unintentional weight loss"}, {"id": "b", "text": "Bloating and gas"}, {"id": "c", "text": "Mucus in the stool"}, {"id": "d", "text": "Cramps relieved by stooling"}]'::jsonb, '["a"]', 'No blood, no fever, and no weight loss are expected in IBS; weight loss suggests Crohn''s or UC. Bloating, mucus, and cramps relieved by bowel movements are IBS features.'),
  ('ibs', 34, 'A client who has been diagnosed with IBS for several years reports blood in the stool. What should the nurse anticipate?', '[{"id": "a", "text": "Reassurance that this is part of IBS"}, {"id": "b", "text": "Further investigation for IBD or cancer"}, {"id": "c", "text": "An increase in soluble fiber intake"}, {"id": "d", "text": "A new prescription for loperamide"}]'::jsonb, '["b"]', 'Blood in stool is not IBS and should be investigated for Crohn''s, UC, or colon cancer. Reassuring the client would miss a serious condition.'),
  ('ibs', 35, 'A client with IBS says, "My sister has Crohn''s and takes strong drugs. Will I need immunosuppressants and surgery too?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, IBS is treated the same as Crohn''s.\""}, {"id": "b", "text": "\"Yes, surgery is usually needed for IBS.\""}, {"id": "c", "text": "\"IBS is treated with diet and symptom management.\""}, {"id": "d", "text": "\"You will need biologics if diet does not help.\""}]'::jsonb, '["c"]', 'IBS treatment is dietary plus symptom management, while IBD is treated with immunosuppressants, biologics, and surgery.'),
  ('ibs', 36, 'A nursing student is comparing IBS with Crohn''s disease and ulcerative colitis. Which statement by the student is correct?', '[{"id": "a", "text": "\"IBS and IBD both cause chronic inflammation.\""}, {"id": "b", "text": "\"IBS causes ulcers, while IBD does not.\""}, {"id": "c", "text": "\"IBS causes tissue damage, unlike IBD.\""}, {"id": "d", "text": "\"IBD involves chronic inflammation; IBS does not.\""}]'::jsonb, '["d"]', 'Crohn''s and UC involve chronic inflammation with mucosal/transmural damage, while IBS has no inflammation, bleeding, or tissue damage.'),
  ('ibs', 37, 'The nurse is reviewing an admission assessment for a client with IBS. Which finding is expected and does not need to be reported as a new concern?', '[{"id": "a", "text": "Bloating and gas after meals"}, {"id": "b", "text": "Bright red blood in the stool"}, {"id": "c", "text": "A new fever of unknown cause"}, {"id": "d", "text": "Unplanned weight loss this month"}]'::jsonb, '["a"]', 'Bloating and gas are typical IBS symptoms. Blood, fever, and weight loss suggest IBD and should be reported.'),
  ('ibs', 38, 'A client with IBS reports that diarrhea is the main bowel problem, with rare constipation. The nurse documents which type of IBS?', '[{"id": "a", "text": "IBS-C"}, {"id": "b", "text": "IBS-D"}, {"id": "c", "text": "IBS-M"}, {"id": "d", "text": "IBD"}]'::jsonb, '["b"]', 'IBS-D is diarrhea-predominant. IBS-C is constipation-predominant, and IBS-M is mixed (alternating).'),
  ('ibs', 39, 'A client asks the nurse to explain what irritable bowel syndrome is. Which description is accurate?', '[{"id": "a", "text": "An acute infection that clears up within a few days"}, {"id": "b", "text": "A chronic inflammatory disease of the colon lining"}, {"id": "c", "text": "A chronic functional disorder with pain and bowel changes"}, {"id": "d", "text": "A disorder that causes bleeding ulcers and fever"}]'::jsonb, '["c"]', 'IBS is a chronic functional GI disorder causing abdominal pain, bloating, diarrhea, constipation, or both. Chronic inflammation and bleeding describe IBD.'),
  ('ibs', 40, 'A client with IBS notices that symptoms flare at certain points in the menstrual cycle. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"This suggests the bowel is now inflamed.\""}, {"id": "b", "text": "\"This means you have ulcerative colitis.\""}, {"id": "c", "text": "\"This pattern is unrelated to IBS.\""}, {"id": "d", "text": "\"Hormones are a known trigger for IBS.\""}]'::jsonb, '["d"]', 'IBS is often triggered by stress, food, and hormones. IBS involves no inflammation, so a hormonal pattern does not indicate inflamed bowel.'),
  ('ibs', 41, 'The charge nurse reviews care for clients with IBS. Which action by a staff nurse requires correction?', '[{"id": "a", "text": "Giving loperamide to a client with IBS-C"}, {"id": "b", "text": "Giving polyethylene glycol for IBS-C"}, {"id": "c", "text": "Giving dicyclomine for abdominal cramps"}, {"id": "d", "text": "Teaching a low FODMAP diet to a client"}]'::jsonb, '["a"]', 'Loperamide is an antidiarrheal for IBS-D, not for constipation-predominant IBS. Polyethylene glycol is the laxative used for IBS-C.'),
  ('ibs', 42, 'A client with IBS started dicyclomine 2 weeks ago. Which client report best indicates that the medication is effective?', '[{"id": "a", "text": "\"My stools have become more frequent.\""}, {"id": "b", "text": "\"My abdominal cramps happen much less.\""}, {"id": "c", "text": "\"I no longer have any mucus at all.\""}, {"id": "d", "text": "\"My hard stools are now softer.\""}]'::jsonb, '["b"]', 'Dicyclomine is an antispasmodic used for pain/cramp relief, so fewer cramps shows effectiveness. Softer stools would reflect a laxative used for IBS-C.'),
  ('ibs', 43, 'A client learning the low FODMAP diet asks what the "P" in FODMAP stands for. Which response by the nurse is correct?', '[{"id": "a", "text": "Proteins"}, {"id": "b", "text": "Peptides"}, {"id": "c", "text": "Polyols"}, {"id": "d", "text": "Phosphates"}]'::jsonb, '["c"]', 'FODMAP stands for Fermentable Oligosaccharides Disaccharides Monosaccharides And Polyols. Polyols are sugar alcohols such as sorbitol and mannitol.'),
  ('ibs', 44, 'A client asks what the word "fermentable" means in the FODMAP diet. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Fully absorbed in the stomach.\""}, {"id": "b", "text": "\"Destroyed by cooking at high heat.\""}, {"id": "c", "text": "\"Converted to fat by the liver.\""}, {"id": "d", "text": "\"Broken down by gut bacteria.\""}]'::jsonb, '["d"]', 'Fermentable means broken down by gut bacteria. FODMAPs are poorly absorbed, not fully absorbed.'),
  ('ibs', 45, 'A client with IBS asks for ways to manage stress. Which interventions should the nurse encourage?', '[{"id": "a", "text": "Therapy, relaxation, and exercise"}, {"id": "b", "text": "Skipping meals and extra caffeine"}, {"id": "c", "text": "Alcohol in the evening to relax"}, {"id": "d", "text": "Limiting fluids and avoiding exercise"}]'::jsonb, '["a"]', 'The nurse encourages stress management through therapy, relaxation, and exercise. Caffeine and alcohol should be avoided, and skipping meals is discouraged.'),
  ('ibs', 46, 'A nursing student compares long-term risks of IBS and IBD. Which statement by the student is accurate?', '[{"id": "a", "text": "\"IBS and IBD carry equal colon cancer risk.\""}, {"id": "b", "text": "\"IBD carries colon cancer risk; IBS does not.\""}, {"id": "c", "text": "\"IBS carries colon cancer risk; IBD does not.\""}, {"id": "d", "text": "\"Neither IBS nor IBD affects cancer risk.\""}]'::jsonb, '["b"]', 'IBD carries colon cancer risk, while IBS carries no cancer risk.'),
  ('ibs', 47, 'The nurse is reviewing IBS treatment plans. For which client would the nurse expect a low-dose antidepressant to be considered?', '[{"id": "a", "text": "A client with mild, occasional bloating"}, {"id": "b", "text": "A client whose symptoms are well controlled"}, {"id": "c", "text": "A client with severe, persistent symptoms"}, {"id": "d", "text": "A client newly diagnosed with mild IBS-C"}]'::jsonb, '["c"]', 'Low-dose antidepressants (TCAs, SSRIs) are used for severe IBS symptoms. Mild or well-controlled symptoms do not meet this indication.'),
  ('ibs', 48, 'The nurse teaches a client with IBS about the low FODMAP diet. Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "\"I''ll limit oats and psyllium.\""}, {"id": "b", "text": "\"I''ll eat more apples and honey.\""}, {"id": "c", "text": "\"I''ll choose sorbitol-sweetened candy.\""}, {"id": "d", "text": "\"I''ll limit wheat, onions, and garlic.\""}]'::jsonb, '["d"]', 'Low FODMAP means avoiding foods high in fermentable carbohydrates such as wheat, onions, and garlic. Apples, honey, and sorbitol are also high-FODMAP, while oats and psyllium are recommended soluble fibers.'),
  ('ibs', 49, 'A client with IBS says, "My colonoscopy and labs were normal, so the doctor must think my pain is all in my head." Which response by the nurse is best?', '[{"id": "a", "text": "\"IBS is real and is diagnosed by ruling out other causes.\""}, {"id": "b", "text": "\"Normal tests mean you do not have any bowel disorder.\""}, {"id": "c", "text": "\"Normal tests mean your IBS has been cured.\""}, {"id": "d", "text": "\"Normal tests mean you need surgery to find the cause.\""}]'::jsonb, '["a"]', 'IBS is a chronic functional disorder diagnosed by symptoms and exclusion of other conditions, and normal labs are expected. IBS has no cure, so normal tests do not mean cure.'),
  ('ibs', 50, 'A client with IBS reports that symptoms worsen after fried, high-fat meals. Which teaching should the nurse provide?', '[{"id": "a", "text": "\"Increase fatty foods to firm your stools.\""}, {"id": "b", "text": "\"Avoid fatty foods as part of your diet plan.\""}, {"id": "c", "text": "\"Fat intake has no effect on IBS symptoms.\""}, {"id": "d", "text": "\"Replace fatty meals with extra caffeine.\""}]'::jsonb, '["b"]', 'Dietary modification for IBS includes avoiding caffeine, alcohol, and fatty foods. Replacing fat with caffeine would not follow this teaching.'),
  ('diverticular', 1, 'A client is admitted with suspected acute diverticulitis. Which assessment finding does the nurse expect to be the most common?', '[{"id": "a", "text": "Right lower quadrant pain"}, {"id": "b", "text": "Right upper quadrant pain"}, {"id": "c", "text": "Left lower quadrant pain"}, {"id": "d", "text": "Midepigastric pain"}]'::jsonb, '["c"]', 'Left lower quadrant (LLQ) pain is the most common finding in diverticulitis. Pain in the other quadrants is not the classic presentation of diverticular disease.'),
  ('diverticular', 2, 'A client reports left lower quadrant pain and has a temperature of 101.8°F (38.8°C). Which laboratory finding would further support a diagnosis of diverticulitis?', '[{"id": "a", "text": "Elevated white blood cell count"}, {"id": "b", "text": "Decreased white blood cell count"}, {"id": "c", "text": "Decreased red blood cell count"}, {"id": "d", "text": "Elevated platelet count"}]'::jsonb, '["a"]', 'LLQ pain plus fever plus an elevated WBC count points to diverticulitis; the WBC rises as a marker of infection. A low WBC would not support an infectious process.'),
  ('diverticular', 3, 'The provider suspects acute diverticulitis in a client with left lower quadrant pain and fever. Which test does the nurse anticipate will be ordered to confirm the diagnosis?', '[{"id": "a", "text": "Colonoscopy during the admission"}, {"id": "b", "text": "Complete blood count alone"}, {"id": "c", "text": "CT scan with contrast"}, {"id": "d", "text": "Urinalysis for fecaluria"}]'::jsonb, '["c"]', 'A CT scan with contrast is the best imaging test to confirm diverticulitis. Colonoscopy is not done during an acute flare, and a CBC supports but does not confirm the diagnosis.'),
  ('diverticular', 4, 'A client hospitalized with an acute diverticulitis flare asks when the colonoscopy will be done. Which response by the nurse is accurate?', '[{"id": "a", "text": "It will be done today to confirm the diagnosis."}, {"id": "b", "text": "It replaces the CT scan during a flare."}, {"id": "c", "text": "It is done only if the CT scan is normal."}, {"id": "d", "text": "It will be scheduled after the flare resolves."}]'::jsonb, '["d"]', 'Colonoscopy is not performed during an acute flare; it is done later to assess the diverticula. The CT scan, not colonoscopy, confirms acute diverticulitis.'),
  ('diverticular', 5, 'The nurse reviews the admission prescriptions for a client with acute diverticulitis. Which prescription should the nurse question?', '[{"id": "a", "text": "NPO status with IV fluids"}, {"id": "b", "text": "IV antibiotic therapy"}, {"id": "c", "text": "Colonoscopy tomorrow morning"}, {"id": "d", "text": "Acetaminophen for pain"}]'::jsonb, '["c"]', 'Colonoscopy is avoided during an acute flare and is done only after the flare resolves. NPO, IV fluids, IV antibiotics, and acetaminophen are all appropriate during the flare.'),
  ('diverticular', 6, 'A client with mild diverticulitis is being managed at home. Which analgesic does the nurse expect to be recommended?', '[{"id": "a", "text": "Ibuprofen every 6 hours"}, {"id": "b", "text": "Naproxen twice daily"}, {"id": "c", "text": "Ketorolac as needed"}, {"id": "d", "text": "Acetaminophen as directed"}]'::jsonb, '["d"]', 'Acetaminophen is the recommended analgesic for diverticulitis. NSAIDs such as ibuprofen, naproxen, and ketorolac are avoided because they worsen bleeding.'),
  ('diverticular', 7, 'The nurse teaches a client being treated at home for mild diverticulitis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will take acetaminophen if my belly hurts."}, {"id": "b", "text": "I will take ibuprofen for my abdominal cramps."}, {"id": "c", "text": "I will stay on clear liquids for now."}, {"id": "d", "text": "I will finish both of my antibiotics."}]'::jsonb, '["b"]', 'NSAIDs such as ibuprofen should be avoided in diverticulitis because they worsen bleeding; acetaminophen is used instead. Clear liquids and completing the oral antibiotics are correct.'),
  ('diverticular', 8, 'A client in an acute diverticulitis flare reports constipation and asks for an enema. Which response by the nurse is best?', '[{"id": "a", "text": "An enema is safe once your antibiotics have started."}, {"id": "b", "text": "An enema will help clear stool trapped in the pouches."}, {"id": "c", "text": "A laxative would be a better choice than an enema now."}, {"id": "d", "text": "Enemas raise pressure in the colon, so they are avoided now."}]'::jsonb, '["d"]', 'Laxatives and enemas are avoided during an acute flare because they increase colon pressure. Substituting a laxative is equally unsafe.'),
  ('diverticular', 9, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with acute diverticulitis. Which action by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "Offering clear liquids as prescribed"}, {"id": "b", "text": "Preparing an enema for the client''s constipation"}, {"id": "c", "text": "Reporting a temperature of 102°F (38.9°C)"}, {"id": "d", "text": "Recording the client''s intake and output"}]'::jsonb, '["b"]', 'Enemas are avoided during an acute flare because they increase colon pressure. Offering prescribed clear liquids and reporting a fever are appropriate actions.'),
  ('diverticular', 10, 'A client hospitalized for diverticulitis suddenly develops a rigid, board-like abdomen, severe pain, a temperature of 103°F (39.4°C), and a heart rate of 118/min. Which complication does the nurse suspect?', '[{"id": "a", "text": "Colovesical fistula"}, {"id": "b", "text": "Peritonitis"}, {"id": "c", "text": "Uncomplicated diverticulosis"}, {"id": "d", "text": "Expected response to antibiotics"}]'::jsonb, '["b"]', 'A rigid board-like abdomen with severe pain, high fever, and tachycardia indicates peritonitis. A colovesical fistula presents with fecaluria rather than a rigid abdomen.'),
  ('diverticular', 11, 'The nurse is caring for a client admitted with diverticulitis. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Mild bloating after clear liquids"}, {"id": "b", "text": "Nausea relieved by an antiemetic"}, {"id": "c", "text": "One loose stool this shift"}, {"id": "d", "text": "Rigid, board-like abdomen"}]'::jsonb, '["d"]', 'A rigid, board-like abdomen signals peritonitis, a complication the nurse must monitor for and report. Bloating, loose stool, and nausea are classic symptoms of diverticulitis.'),
  ('diverticular', 12, 'A client with diverticulitis reports sudden, severe abdominal pain. Blood pressure is 82/48 mm Hg and heart rate is 124/min. Which complication does the nurse suspect?', '[{"id": "a", "text": "Perforation"}, {"id": "b", "text": "Abscess"}, {"id": "c", "text": "Fistula"}, {"id": "d", "text": "Diverticulosis"}]'::jsonb, '["a"]', 'Sudden severe pain with hypotension and signs of shock indicates perforation. An abscess presents with persistent fever and worsening pain despite antibiotics rather than sudden shock.'),
  ('diverticular', 13, 'A client has received IV antibiotics for diverticulitis for 3 days but remains febrile, and the abdominal pain is worsening. Which complication should the nurse suspect?', '[{"id": "a", "text": "Perforation"}, {"id": "b", "text": "Abscess"}, {"id": "c", "text": "Fistula"}, {"id": "d", "text": "Expected recovery"}]'::jsonb, '["b"]', 'Persistent fever and worsening pain despite antibiotics suggest an abscess. Perforation presents with sudden severe pain, hypotension, and shock.'),
  ('diverticular', 14, 'A client with a history of diverticulitis reports seeing particles of stool in the urine. Which complication does the nurse suspect?', '[{"id": "a", "text": "Colovesical fistula"}, {"id": "b", "text": "Peritonitis"}, {"id": "c", "text": "Abscess"}, {"id": "d", "text": "Bowel obstruction"}]'::jsonb, '["a"]', 'Fecaluria (stool in urine) occurs with a colovesical fistula, an abnormal connection between the colon and bladder. Peritonitis presents with a rigid abdomen and high fever.'),
  ('diverticular', 15, 'A client recovering from diverticulitis reports passing stool through the vagina. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Fistula between colon and vagina"}, {"id": "b", "text": "Perforation of the colon"}, {"id": "c", "text": "Abscess within a diverticulum"}, {"id": "d", "text": "Obstruction of the colon"}]'::jsonb, '["a"]', 'A fistula is an abnormal connection between the colon and the bladder or vagina, allowing stool to pass. Perforation presents with sudden severe pain and shock instead.'),
  ('diverticular', 16, 'A client being treated for diverticulitis develops severe bloating, repeated vomiting, and has had no bowel movements. Which complication does the nurse suspect?', '[{"id": "a", "text": "Bowel obstruction"}, {"id": "b", "text": "Abscess"}, {"id": "c", "text": "Fistula"}, {"id": "d", "text": "Peritonitis"}]'::jsonb, '["a"]', 'Severe bloating, vomiting, and no bowel movements indicate bowel obstruction. Peritonitis is marked by a rigid abdomen and high fever.'),
  ('diverticular', 17, 'A client with diverticulitis asks, ''Why might I need surgery?'' The nurse explains that colectomy is indicated for which complication?', '[{"id": "a", "text": "Perforation of the colon"}, {"id": "b", "text": "Mild left lower quadrant cramping"}, {"id": "c", "text": "Low-grade fever on the first day"}, {"id": "d", "text": "Bloating and gas after meals"}]'::jsonb, '["a"]', 'Colectomy is reserved for perforation, abscess, or obstruction. Cramping, low-grade fever, and bloating are classic symptoms managed medically.'),
  ('diverticular', 18, 'A client is hospitalized with severe diverticulitis. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "Regular diet as tolerated"}, {"id": "b", "text": "High-fiber diet with bran"}, {"id": "c", "text": "NPO status with IV fluids"}, {"id": "d", "text": "Daily oral laxative"}]'::jsonb, '["c"]', 'Severe diverticulitis is treated with NPO bowel rest and IV fluids to prevent dehydration. Fiber is increased only after symptoms improve, and laxatives are avoided during a flare.'),
  ('diverticular', 19, 'A client hospitalized with severe diverticulitis is vomiting repeatedly and has marked abdominal bloating. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Ibuprofen for abdominal discomfort"}, {"id": "b", "text": "Administration of a tap-water enema"}, {"id": "c", "text": "Advancement to a full liquid diet"}, {"id": "d", "text": "Insertion of a nasogastric tube"}]'::jsonb, '["d"]', 'An NG tube is used in severe diverticulitis when there is severe vomiting or bloating. Enemas are avoided because they increase colon pressure.'),
  ('diverticular', 20, 'A client with severe diverticulitis who is NPO asks why IV fluids are running. Which response by the nurse is accurate?', '[{"id": "a", "text": "They flush bacteria out of the inflamed pouches."}, {"id": "b", "text": "They soften the stool trapped in the pouches."}, {"id": "c", "text": "They prevent dehydration while you rest your bowel."}, {"id": "d", "text": "They replace the fiber you are not eating."}]'::jsonb, '["c"]', 'IV fluids are given in severe diverticulitis to prevent dehydration during NPO bowel rest. They do not act on stool or bacteria within the diverticula.'),
  ('diverticular', 21, 'A client with an acute diverticulitis flare asks why food is being withheld. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It prevents seeds from entering pouches."}, {"id": "b", "text": "It rests the bowel during the flare."}, {"id": "c", "text": "It is required before a colonoscopy."}, {"id": "d", "text": "It increases pressure inside the colon."}]'::jsonb, '["b"]', 'NPO or clear liquids rest the bowel during an acute flare. Seeds are not restricted, and colonoscopy is not done during a flare.'),
  ('diverticular', 22, 'A client with mild diverticulitis is being discharged for outpatient treatment. Which medication regimen does the nurse expect to reinforce?', '[{"id": "a", "text": "A daily enema plus oral fiber"}, {"id": "b", "text": "Oral naproxen plus a daily laxative"}, {"id": "c", "text": "Oral ciprofloxacin plus metronidazole"}, {"id": "d", "text": "No antibiotics until a colonoscopy"}]'::jsonb, '["c"]', 'Mild outpatient diverticulitis is treated with oral ciprofloxacin plus metronidazole. NSAIDs, laxatives, and enemas are avoided during a flare.'),
  ('diverticular', 23, 'The nurse teaches a client with mild diverticulitis who will be treated at home. Which diet should the client follow while symptoms are present?', '[{"id": "a", "text": "High-fiber foods starting right away"}, {"id": "b", "text": "Clear liquids to rest the bowel"}, {"id": "c", "text": "Regular meals with extra bran"}, {"id": "d", "text": "Full meals with prune juice"}]'::jsonb, '["b"]', 'Mild cases are treated with NPO or a clear liquid diet to rest the bowel. Fiber is added gradually only once symptoms improve.'),
  ('diverticular', 24, 'A client whose mild diverticulitis symptoms have now resolved asks about fiber intake. Which instruction by the nurse is correct?', '[{"id": "a", "text": "Add fiber only after a normal colonoscopy result."}, {"id": "b", "text": "Begin a very high-fiber diet as soon as a flare starts."}, {"id": "c", "text": "Avoid all fiber permanently to prevent another flare."}, {"id": "d", "text": "Increase fiber gradually now that symptoms have improved."}]'::jsonb, '["d"]', 'Fiber is gradually increased once symptoms improve. Fiber is not started during the flare, and a high-fiber diet is the long-term prevention strategy rather than something to avoid.'),
  ('diverticular', 25, 'The nurse reviews meal choices with a client who is recovering from diverticulitis and wants to prevent future flares. Which meal best supports prevention?', '[{"id": "a", "text": "White toast with butter and coffee"}, {"id": "b", "text": "Whole-grain cereal with fresh berries"}, {"id": "c", "text": "Cheeseburger on a white bun"}, {"id": "d", "text": "White rice with cream sauce"}]'::jsonb, '["b"]', 'Long-term prevention relies on a high-fiber diet of fruits, vegetables, and whole grains. The other meals are low in fiber, and a low-fiber diet is a risk factor.'),
  ('diverticular', 26, 'The nurse provides prevention teaching to a client with diverticulosis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I must stop eating seeds, nuts, and popcorn."}, {"id": "b", "text": "I will drink more fluids every day."}, {"id": "c", "text": "I will add more vegetables to my meals."}, {"id": "d", "text": "I will start walking on a regular basis."}]'::jsonb, '["a"]', 'Current evidence does not support restricting seeds, nuts, corn, or popcorn. More vegetables, more fluids, and regular exercise are correct prevention measures.'),
  ('diverticular', 27, 'A client with diverticulosis asks, ''Can I still eat strawberries and nuts?'' Which response by the nurse is correct?', '[{"id": "a", "text": "Yes, seeds and nuts do not need to be avoided."}, {"id": "b", "text": "No, seeds and nuts can lodge in the pouches."}, {"id": "c", "text": "Only if the seeds are strained out first."}, {"id": "d", "text": "Only after a normal follow-up colonoscopy."}]'::jsonb, '["a"]', 'Seeds and nuts are not restricted; the older teaching that they lodge in diverticula is not supported by current evidence.'),
  ('diverticular', 28, 'The nurse reinforces long-term prevention teaching with a client who has started a high-fiber diet for diverticulosis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will limit my fluids to keep stools firm."}, {"id": "b", "text": "I will add whole grains to my breakfast."}, {"id": "c", "text": "I will eat fruit as a snack each day."}, {"id": "d", "text": "I will exercise most days of the week."}]'::jsonb, '["a"]', 'Increasing fluid intake is part of long-term prevention along with a high-fiber diet and exercise. Limiting fluids contradicts this teaching.'),
  ('diverticular', 29, 'A client who has recovered from a diverticulitis flare asks how to prevent another one. Which client statement shows correct understanding?', '[{"id": "a", "text": "I will start walking most days of the week."}, {"id": "b", "text": "I will eat a low-fiber diet to rest my colon."}, {"id": "c", "text": "I will take ibuprofen daily to prevent pain."}, {"id": "d", "text": "I will use a laxative every day to avoid straining."}]'::jsonb, '["a"]', 'Regular exercise is a long-term prevention measure, and lack of exercise is a risk factor. A low-fiber diet is a risk factor, NSAIDs are avoided, and laxatives raise colon pressure.'),
  ('diverticular', 30, 'The nurse reviews the health histories of four clients at a clinic. Which client is at greatest risk for developing diverticular disease?', '[{"id": "a", "text": "A 19-year-old who exercises daily and drinks plenty of fluids"}, {"id": "b", "text": "A 24-year-old athlete who eats many fruits and vegetables"}, {"id": "c", "text": "A 30-year-old nonsmoker who walks daily and eats whole grains"}, {"id": "d", "text": "A 74-year-old who eats a low-fiber diet and strains with stools"}]'::jsonb, '["d"]', 'Aging and a low-fiber diet leading to constipation and straining are risk factors for diverticular disease. The other clients have protective factors such as fiber, fluids, and exercise.'),
  ('diverticular', 31, 'A client newly diagnosed with diverticulosis asks how diet contributed to the condition. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A low-fiber diet leads to constipation and straining."}, {"id": "b", "text": "A high-fiber diet stretches and weakens the colon."}, {"id": "c", "text": "Eating seeds and nuts causes the pouches to form."}, {"id": "d", "text": "Drinking extra fluids thins the wall of the colon."}]'::jsonb, '["a"]', 'A low-fiber diet causes constipation and straining, a key risk factor. High fiber is preventive, and seeds and nuts are not restricted.'),
  ('diverticular', 32, 'A 78-year-old client asks why diverticular disease is more common in older adults. Which response by the nurse is best?', '[{"id": "a", "text": "Older adults are given colonoscopies more often."}, {"id": "b", "text": "Older adults absorb too much dietary fiber."}, {"id": "c", "text": "Aging increases the number of colon bacteria."}, {"id": "d", "text": "Aging weakens the walls of the intestine."}]'::jsonb, '["d"]', 'Aging is a risk factor because it weakens the intestinal walls. Fiber is protective rather than harmful.'),
  ('diverticular', 33, 'A client with known diverticulosis is reviewing current medications with the nurse. Which item in the client''s history increases the risk of complications?', '[{"id": "a", "text": "Acetaminophen as needed for headaches"}, {"id": "b", "text": "Regular use of naproxen for knee pain"}, {"id": "c", "text": "Daily whole-grain cereal at breakfast"}, {"id": "d", "text": "Increased water intake with meals"}]'::jsonb, '["b"]', 'NSAID use, such as naproxen, increases the risk of complications in diverticular disease. Acetaminophen is the preferred analgesic, and fiber and fluids are preventive.'),
  ('diverticular', 34, 'The nurse obtains a medication history from a client with diverticulosis. Which medication should the nurse identify as increasing the client''s risk of complications?', '[{"id": "a", "text": "Acetaminophen for occasional aches"}, {"id": "b", "text": "Oxycodone for chronic back pain"}, {"id": "c", "text": "Metronidazole from a past infection"}, {"id": "d", "text": "Ciprofloxacin from a past infection"}]'::jsonb, '["b"]', 'Opioid use, like NSAID use, increases the risk of complications in diverticular disease. Acetaminophen is the recommended analgesic, and ciprofloxacin and metronidazole are used to treat diverticulitis.'),
  ('diverticular', 35, 'A client without symptoms learns that a screening colonoscopy showed diverticula. The client asks, ''Do I have an infection?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "You need a CT scan today to see how severe the infection is."}, {"id": "b", "text": "Your pouches are infected and will need IV antibiotics right away."}, {"id": "c", "text": "You have small pouches in the colon wall that often cause no symptoms."}, {"id": "d", "text": "You must stay NPO to rest the bowel until the infection clears."}]'::jsonb, '["c"]', 'Diverticulosis is the presence of small pouches in the colon wall and is often asymptomatic. Infection or inflammation of the pouches is diverticulitis, which is treated with antibiotics.'),
  ('diverticular', 36, 'A client with asymptomatic diverticulosis asks what treatment is needed. Which treatment does the nurse expect to reinforce?', '[{"id": "a", "text": "NPO bowel rest"}, {"id": "b", "text": "IV antibiotic therapy"}, {"id": "c", "text": "A high-fiber diet"}, {"id": "d", "text": "A planned colectomy"}]'::jsonb, '["c"]', 'Diverticulosis is treated with a high-fiber diet. Antibiotics, NPO, and surgery are treatments for diverticulitis and its complications.'),
  ('diverticular', 37, 'A client newly diagnosed with diverticulitis asks what caused the pouches to become infected. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Too much fiber stretched the pouches until they tore."}, {"id": "b", "text": "Seeds from food became lodged inside the pouches."}, {"id": "c", "text": "Stomach acid flowed back into the large intestine."}, {"id": "d", "text": "Stool and bacteria became trapped inside the pouches."}]'::jsonb, '["d"]', 'Diverticulitis is inflammation or infection of the diverticula from trapped stool and bacteria. The idea that seeds lodge in the pouches is older teaching not supported by current evidence.'),
  ('diverticular', 38, 'A nursing student compares diagnostic imaging for diverticular disease. Which pairing by the student is correct?', '[{"id": "a", "text": "Diverticulosis: elective colonoscopy; diverticulitis: CT scan"}, {"id": "b", "text": "Diverticulosis: CT scan; diverticulitis: urgent colonoscopy"}, {"id": "c", "text": "Diverticulosis: urgent colonoscopy; diverticulitis: colonoscopy"}, {"id": "d", "text": "Diverticulosis: CT scan; diverticulitis: no imaging needed"}]'::jsonb, '["a"]', 'Diverticulosis is evaluated by elective colonoscopy, while acute diverticulitis is evaluated by CT scan. Colonoscopy is avoided during an acute flare.'),
  ('diverticular', 39, 'The nurse is triaging four clients with known diverticular disease. Which client most likely has diverticulitis rather than diverticulosis?', '[{"id": "a", "text": "A client scheduled for an elective colonoscopy"}, {"id": "b", "text": "A client with pouches found on routine screening"}, {"id": "c", "text": "A client with no symptoms who eats a high-fiber diet"}, {"id": "d", "text": "A client with LLQ pain, fever, and nausea"}]'::jsonb, '["d"]', 'Diverticulitis presents with LLQ pain, fever, and nausea, whereas diverticulosis usually causes no symptoms and is found on elective colonoscopy.'),
  ('diverticular', 40, 'The nurse is admitting a client with suspected diverticulitis. Which group of findings is the nurse most likely to assess?', '[{"id": "a", "text": "Board-like abdomen, hypotension, and shock"}, {"id": "b", "text": "LLQ pain, hypothermia, and no nausea"}, {"id": "c", "text": "No pain, no fever, and normal bowel habits"}, {"id": "d", "text": "LLQ pain, fever, chills, and nausea"}]'::jsonb, '["d"]', 'Classic diverticulitis symptoms include LLQ pain, fever and chills from infection, and nausea. A board-like abdomen with shock indicates complications such as peritonitis or perforation rather than the classic picture.'),
  ('diverticular', 41, 'A client is being evaluated for diverticulitis. Which client statement about bowel habits is consistent with this condition?', '[{"id": "a", "text": "I''ve had cramping on my lower left side, bloating, and diarrhea."}, {"id": "b", "text": "I''ve had no change in my bowel habits and no abdominal pain."}, {"id": "c", "text": "I''ve had pain on my upper right side after eating fried food."}, {"id": "d", "text": "I''ve had pain around my belly button that moved to the right."}]'::jsonb, '["a"]', 'Diverticulitis classically causes LLQ pain, bloating and gas, and constipation or diarrhea. Pain in other locations does not match the classic presentation.'),
  ('diverticular', 42, 'The nurse reviews prescriptions for a client admitted with an acute diverticulitis flare. Which prescription should the nurse clarify with the provider?', '[{"id": "a", "text": "NPO status for bowel rest"}, {"id": "b", "text": "IV antibiotics every 8 hours"}, {"id": "c", "text": "Bisacodyl laxative daily"}, {"id": "d", "text": "Acetaminophen as needed"}]'::jsonb, '["c"]', 'Laxatives are avoided during an acute flare because they increase colon pressure. IV antibiotics, NPO, and acetaminophen are appropriate.'),
  ('diverticular', 43, 'A client has been receiving IV antibiotics for diverticulitis. Which finding best indicates that treatment is effective?', '[{"id": "a", "text": "Abdomen has become rigid and board-like"}, {"id": "b", "text": "Fever persists and LLQ pain is worsening"}, {"id": "c", "text": "Fever has resolved and LLQ pain is decreasing"}, {"id": "d", "text": "Particles of stool are noted in the urine"}]'::jsonb, '["c"]', 'Resolution of fever and decreasing pain show improvement. Persistent fever with worsening pain despite antibiotics suggests an abscess, a rigid abdomen suggests peritonitis, and fecaluria suggests a fistula.'),
  ('diverticular', 44, 'The nurse receives report on four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with diverticulosis asking about eating popcorn"}, {"id": "b", "text": "A client with mild diverticulitis tolerating clear liquids"}, {"id": "c", "text": "A client with diverticulitis with sudden severe pain and BP 84/50"}, {"id": "d", "text": "A client awaiting an elective colonoscopy next week"}]'::jsonb, '["c"]', 'Sudden severe pain with hypotension suggests perforation, a complication that can progress to shock. The other clients are stable.'),
  ('diverticular', 45, 'A client is hospitalized with severe diverticulitis. By which route does the nurse expect antibiotics to be given?', '[{"id": "a", "text": "Topical"}, {"id": "b", "text": "Oral only"}, {"id": "c", "text": "Rectal enema"}, {"id": "d", "text": "Intravenous"}]'::jsonb, '["d"]', 'Severe cases requiring hospitalization receive IV antibiotics. Oral ciprofloxacin plus metronidazole is used for mild outpatient cases, and enemas are avoided.'),
  ('diverticular', 46, 'The nurse is reviewing four clients with diverticulitis. Which client is the most appropriate candidate for outpatient management?', '[{"id": "a", "text": "A client with a rigid abdomen and a high fever"}, {"id": "b", "text": "A client with mild LLQ pain who tolerates clear liquids"}, {"id": "c", "text": "A client with hypotension after sudden severe pain"}, {"id": "d", "text": "A client with severe vomiting who needs an NG tube"}]'::jsonb, '["b"]', 'Mild cases are managed as outpatients with clear liquids and oral antibiotics. A rigid abdomen, hypotension, or severe vomiting needing an NG tube indicates severe disease or complications requiring hospitalization.'),
  ('diverticular', 47, 'A client presents with left lower quadrant pain, fever, and an elevated WBC count. Which diagnostic test should the nurse prepare the client for next?', '[{"id": "a", "text": "Colonoscopy"}, {"id": "b", "text": "CT scan"}, {"id": "c", "text": "Repeat CBC only"}, {"id": "d", "text": "No further testing"}]'::jsonb, '["b"]', 'LLQ pain, fever, and an elevated WBC suggest diverticulitis, and a CT scan confirms it. Colonoscopy is deferred until after the flare resolves.'),
  ('diverticular', 48, 'A client with severe diverticulitis has a newly inserted nasogastric tube. Which finding best indicates the NG tube is achieving its purpose?', '[{"id": "a", "text": "Bowel movements have become more frequent"}, {"id": "b", "text": "Vomiting has stopped and bloating is decreasing"}, {"id": "c", "text": "The client is now tolerating a regular diet"}, {"id": "d", "text": "The client''s fiber intake has increased"}]'::jsonb, '["b"]', 'An NG tube is used in severe diverticulitis for severe vomiting and bloating, so improvement in these symptoms shows effectiveness.'),
  ('diverticular', 49, 'The nurse observes the unlicensed assistive personnel (UAP) caring for a client admitted with severe diverticulitis who is NPO. Which action by the UAP requires correction?', '[{"id": "a", "text": "Measuring and recording the client''s urine output"}, {"id": "b", "text": "Reporting that the client''s temperature is rising"}, {"id": "c", "text": "Delivering a regular breakfast tray to the client"}, {"id": "d", "text": "Helping the client into a comfortable position"}]'::jsonb, '["c"]', 'Severe diverticulitis is treated with NPO for bowel rest, so delivering a meal tray is incorrect. Reporting a rising temperature is appropriate monitoring.'),
  ('diverticular', 50, 'A nursing student is teaching a peer about diverticular disease. Which statement by the student is accurate?', '[{"id": "a", "text": "Diverticulosis means the pouches have become inflamed or infected."}, {"id": "b", "text": "Diverticulitis means the pouches have become inflamed or infected."}, {"id": "c", "text": "Diverticulitis is usually found without any symptoms present."}, {"id": "d", "text": "Diverticulosis is always treated with antibiotics and surgery."}]'::jsonb, '["b"]', 'Diverticulitis is defined by inflamed or infected pouches, whereas diverticulosis is simply the presence of pouches and usually causes no symptoms.'),
  ('sbo_lbo', 1, 'A client is 4 days post-op after abdominal surgery. The nurse finds absent bowel sounds in all four quadrants, abdominal distention, and no passage of flatus. Which condition does the nurse suspect?', '[{"id": "a", "text": "Normal return of peristalsis"}, {"id": "b", "text": "Expected effect of anesthesia"}, {"id": "c", "text": "Paralytic ileus"}, {"id": "d", "text": "Resolved bowel obstruction"}]'::jsonb, '["c"]', 'Absent bowel sounds more than 3 days after surgery suggest paralytic ileus and require intervention. Absent bowel sounds are attributed to anesthesia only in the first 2 days.'),
  ('sbo_lbo', 2, 'A client returned from abdominal surgery 18 hours ago. The nurse auscultates and hears no bowel sounds. How should the nurse interpret this finding?', '[{"id": "a", "text": "Sign of bowel perforation"}, {"id": "b", "text": "Paralytic ileus requiring intervention"}, {"id": "c", "text": "Mechanical large bowel obstruction"}, {"id": "d", "text": "Expected finding related to anesthesia"}]'::jsonb, '["d"]', 'Absent bowel sounds less than 2 days after surgery are normal because of anesthesia. Ileus is suspected only when they remain absent beyond 3 days.'),
  ('sbo_lbo', 3, 'On post-op day 4, a client has absent bowel sounds and a distended abdomen. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Give an opioid to relieve the abdominal discomfort"}, {"id": "b", "text": "Document the finding as expected and advance the diet"}, {"id": "c", "text": "Administer a stimulant laxative to restart peristalsis"}, {"id": "d", "text": "Notify the provider and anticipate NPO and an NG tube"}]'::jsonb, '["d"]', 'Absent bowel sounds beyond 3 days post-op suggest paralytic ileus, which calls for intervention such as NPO and an NG tube. Laxatives and opioids are avoided.'),
  ('sbo_lbo', 4, 'The family of a client with paralytic ileus asks, ''What is blocking the bowel?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "There is no physical blockage; the bowel is paralyzed."}, {"id": "b", "text": "A tumor is pressing on the large intestine."}, {"id": "c", "text": "A twisted loop of bowel is causing a blockage."}, {"id": "d", "text": "Hard stool has formed a mechanical blockage."}]'::jsonb, '["a"]', 'Paralytic ileus is neurogenic, with no physical blockage; the bowel is paralyzed. Tumor, volvulus, and fecal impaction are mechanical causes of large bowel obstruction.'),
  ('sbo_lbo', 5, 'The nurse is caring for four clients. Which client is at greatest risk for developing paralytic ileus?', '[{"id": "a", "text": "A client with a newly diagnosed colon cancer"}, {"id": "b", "text": "A client after abdominal surgery receiving opioids"}, {"id": "c", "text": "A client with a sigmoid volvulus"}, {"id": "d", "text": "A client with a large fecal impaction"}]'::jsonb, '["b"]', 'Paralytic ileus often follows abdominal surgery or opioid use. Colon cancer, volvulus, and fecal impaction are causes of mechanical large bowel obstruction.'),
  ('sbo_lbo', 6, 'A client admitted after spinal trauma develops abdominal distention, no flatus, and absent bowel sounds in all four quadrants. Which condition does the nurse suspect?', '[{"id": "a", "text": "Paralytic ileus"}, {"id": "b", "text": "Volvulus"}, {"id": "c", "text": "Colon tumor"}, {"id": "d", "text": "Hernia"}]'::jsonb, '["a"]', 'Spinal trauma is a common cause of paralytic ileus, which presents with absent or hypoactive bowel sounds in all four quadrants. Volvulus, tumor, and hernia cause mechanical large bowel obstruction.'),
  ('sbo_lbo', 7, 'A post-op client develops paralytic ileus. Which laboratory finding should the nurse recognize as a possible contributing cause?', '[{"id": "a", "text": "High serum potassium"}, {"id": "b", "text": "Low serum potassium"}, {"id": "c", "text": "Low white blood cell count"}, {"id": "d", "text": "High hemoglobin level"}]'::jsonb, '["b"]', 'Electrolyte imbalance, specifically hypokalemia, is a common cause of paralytic ileus. An elevated, not low, WBC is a sign to monitor for perforation.'),
  ('sbo_lbo', 8, 'A client with suspected paralytic ileus has an abdominal x-ray. Which finding does the nurse expect in the report?', '[{"id": "a", "text": "Gas in both small and large intestines with uniform distention"}, {"id": "b", "text": "Air-fluid levels with no gas beyond a point of blockage"}, {"id": "c", "text": "A distended colon with a mass at the point of narrowing"}, {"id": "d", "text": "Gas limited to the colon with collapsed small intestine"}]'::jsonb, '["a"]', 'Paralytic ileus shows gas in both the small and large intestines with uniform distention. Air-fluid levels with no gas beyond the blockage indicate large bowel obstruction.'),
  ('sbo_lbo', 9, 'A client with colon cancer is suspected of having a large bowel obstruction. Which CT finding does the nurse expect?', '[{"id": "a", "text": "Uniform gas throughout small and large intestines"}, {"id": "b", "text": "Distended colon with no gas beyond the blockage"}, {"id": "c", "text": "Normal bowel caliber with no air-fluid levels"}, {"id": "d", "text": "Collapsed colon with gas only in the stomach"}]'::jsonb, '["b"]', 'Large bowel obstruction shows air-fluid levels, a distended colon, and no gas beyond the blockage. Uniform gas throughout both intestines is typical of paralytic ileus.'),
  ('sbo_lbo', 10, 'The nurse reviews an imaging report that states, ''Air-fluid levels, distended colon, no gas distal to the obstruction.'' Which condition does this report indicate?', '[{"id": "a", "text": "Large bowel obstruction"}, {"id": "b", "text": "Paralytic ileus"}, {"id": "c", "text": "Normal postoperative bowel"}, {"id": "d", "text": "Uncomplicated anesthesia effect"}]'::jsonb, '["a"]', 'Air-fluid levels, a distended colon, and no gas beyond the blockage are imaging findings of mechanical large bowel obstruction. Paralytic ileus shows gas in both intestines with uniform distention.'),
  ('sbo_lbo', 11, 'The nurse asks a post-op client with paralytic ileus to describe the abdominal pain. Which description is the nurse most likely to hear?', '[{"id": "a", "text": "Burning pain after each meal"}, {"id": "b", "text": "Crampy, severe, and intermittent"}, {"id": "c", "text": "Sharp and limited to one spot"}, {"id": "d", "text": "Dull, generalized discomfort"}]'::jsonb, '["d"]', 'Paralytic ileus causes dull, generalized abdominal discomfort. Crampy, severe, intermittent pain is typical of large bowel obstruction.'),
  ('sbo_lbo', 12, 'A client with a large bowel obstruction from a colon tumor describes the abdominal pain. Which description is consistent with this condition?', '[{"id": "a", "text": "Dull, generalized ache"}, {"id": "b", "text": "Mild discomfort only after eating"}, {"id": "c", "text": "Crampy, severe, intermittent pain"}, {"id": "d", "text": "No pain, only a feeling of fullness"}]'::jsonb, '["c"]', 'Pain in large bowel obstruction is crampy, severe, and intermittent. Dull, generalized discomfort is characteristic of paralytic ileus.'),
  ('sbo_lbo', 13, 'The nurse auscultates the abdomen of a client with an early large bowel obstruction. Which bowel sound finding does the nurse expect?', '[{"id": "a", "text": "Absent sounds in all four quadrants from the start"}, {"id": "b", "text": "Hypoactive sounds that soon become normal"}, {"id": "c", "text": "Normal sounds in all four quadrants"}, {"id": "d", "text": "High-pitched tinkling above the obstruction"}]'::jsonb, '["d"]', 'Mechanical obstruction produces high-pitched tinkling above the obstruction that later becomes silent. Absent sounds in all four quadrants are characteristic of paralytic ileus.'),
  ('sbo_lbo', 14, 'Yesterday a client with a large bowel obstruction had high-pitched, tinkling bowel sounds. Today the bowel sounds are silent. How should the nurse interpret this change?', '[{"id": "a", "text": "The pattern is consistent with a progressing obstruction."}, {"id": "b", "text": "The obstruction has resolved and peristalsis is normal."}, {"id": "c", "text": "The finding is an expected effect of anesthesia."}, {"id": "d", "text": "A laxative is now needed to restart the bowel."}]'::jsonb, '["a"]', 'Tinkling bowel sounds followed by silence is the pattern of obstruction. Silent bowel sounds do not indicate resolution.'),
  ('sbo_lbo', 15, 'The nurse is assessing a client with paralytic ileus. Which bowel sound finding does the nurse expect?', '[{"id": "a", "text": "High-pitched tinkling in one quadrant"}, {"id": "b", "text": "Hyperactive and loud in all four quadrants"}, {"id": "c", "text": "Absent or hypoactive in all four quadrants"}, {"id": "d", "text": "Normal in the upper and absent in the lower"}]'::jsonb, '["c"]', 'Paralytic ileus causes absent or hypoactive bowel sounds in all four quadrants. High-pitched tinkling is heard above a mechanical obstruction.'),
  ('sbo_lbo', 16, 'A nursing student asks how bowel sounds help distinguish paralytic ileus from a mechanical obstruction. Which response by the nurse is correct?', '[{"id": "a", "text": "Ileus causes absent sounds; obstruction causes tinkling, then silence."}, {"id": "b", "text": "Ileus causes tinkling sounds; obstruction causes absent sounds."}, {"id": "c", "text": "Both conditions cause loud, hyperactive sounds in all quadrants."}, {"id": "d", "text": "Bowel sounds are always normal in both of these conditions."}]'::jsonb, '["a"]', 'Absent bowel sounds indicate ileus, whereas tinkling sounds that later go silent indicate obstruction. The reversed pairing is incorrect.'),
  ('sbo_lbo', 17, 'The nurse obtains a history from a client with abdominal pain and distention. Which history is more consistent with a large bowel obstruction than a small bowel obstruction?', '[{"id": "a", "text": "Symptoms began suddenly a few hours ago"}, {"id": "b", "text": "Early vomiting began with the first pain"}, {"id": "c", "text": "Symptoms developed gradually over several days"}, {"id": "d", "text": "Flatus is still passing normally"}]'::jsonb, '["c"]', 'Large bowel obstruction has a gradual onset, whereas small bowel obstruction is abrupt with early nausea and vomiting.'),
  ('sbo_lbo', 18, 'A client with a large bowel obstruction from a colon tumor begins vomiting. Which characteristic of the vomiting does the nurse expect?', '[{"id": "a", "text": "Occurs early and is the first symptom"}, {"id": "b", "text": "Occurs late and may be fecal-smelling"}, {"id": "c", "text": "Occurs only after laxatives are given"}, {"id": "d", "text": "Occurs early and contains bright blood"}]'::jsonb, '["b"]', 'Vomiting in large bowel obstruction is a late symptom and may be fecal-smelling, whereas early nausea and vomiting occur in small bowel obstruction.'),
  ('sbo_lbo', 19, 'The nurse assesses a client with a complete large bowel obstruction. Which finding does the nurse expect regarding elimination?', '[{"id": "a", "text": "Frequent loose stools with flatus"}, {"id": "b", "text": "Small soft stools passed daily"}, {"id": "c", "text": "No passage of stool or gas"}, {"id": "d", "text": "Passage of gas but no stool"}]'::jsonb, '["c"]', 'Large bowel obstruction causes absolute constipation with no passage of stool or gas.'),
  ('sbo_lbo', 20, 'The nurse is reviewing the histories of four clients. Which client condition is a common cause of large bowel obstruction?', '[{"id": "a", "text": "Recent abdominal surgery"}, {"id": "b", "text": "Colon cancer"}, {"id": "c", "text": "Spinal trauma"}, {"id": "d", "text": "Low serum potassium"}]'::jsonb, '["b"]', 'Colon cancer is a common cause of mechanical large bowel obstruction. Abdominal surgery, spinal trauma, and hypokalemia are common causes of paralytic ileus.'),
  ('sbo_lbo', 21, 'A client is diagnosed with a large bowel obstruction caused by a volvulus. The client asks how this differs from ileus. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The opioids have stopped bowel movement."}, {"id": "b", "text": "The bowel is paralyzed with no blockage."}, {"id": "c", "text": "The anesthesia has slowed the bowel down."}, {"id": "d", "text": "The large intestine is mechanically blocked."}]'::jsonb, '["d"]', 'Large bowel obstruction is a mechanical blockage in the large intestine, such as from volvulus. A paralyzed bowel without a blockage describes paralytic ileus.'),
  ('sbo_lbo', 22, 'A client with a large bowel obstruction caused by a tumor asks whether surgery will be needed. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Surgery is needed only for post-op paralytic ileus."}, {"id": "b", "text": "Surgery is never needed; laxatives will relieve it."}, {"id": "c", "text": "Surgery is only needed if bowel sounds are present."}, {"id": "d", "text": "Surgery is often required for this type of obstruction."}]'::jsonb, '["d"]', 'Treatment of large bowel obstruction includes NPO, NG tube, and IV fluids, and surgery is often required. Laxatives are never given in complete obstruction.'),
  ('sbo_lbo', 23, 'A client with a large bowel obstruction develops abdominal rigidity, a temperature of 102.4°F (39.1°C), and an elevated WBC count. Which complication does the nurse suspect?', '[{"id": "a", "text": "Return of normal peristalsis"}, {"id": "b", "text": "Expected progression of ileus"}, {"id": "c", "text": "Perforation with possible sepsis"}, {"id": "d", "text": "Expected effect of anesthesia"}]'::jsonb, '["c"]', 'Abdominal rigidity, fever, and an elevated WBC are signs of perforation or sepsis that must be monitored for in large bowel obstruction.'),
  ('sbo_lbo', 24, 'The nurse is caring for a client with a large bowel obstruction. Which new finding should be reported to the provider immediately?', '[{"id": "a", "text": "Abdominal distention"}, {"id": "b", "text": "No passage of flatus"}, {"id": "c", "text": "Crampy abdominal pain"}, {"id": "d", "text": "Abdominal rigidity"}]'::jsonb, '["d"]', 'Abdominal rigidity is a sign of perforation or sepsis. Distention, lack of flatus, and crampy pain are expected findings of large bowel obstruction.'),
  ('sbo_lbo', 25, 'The nurse reviews prescriptions for a client with a complete large bowel obstruction. Which prescription should the nurse question?', '[{"id": "a", "text": "NPO status"}, {"id": "b", "text": "NG tube to suction"}, {"id": "c", "text": "IV fluid infusion"}, {"id": "d", "text": "Stimulant laxative"}]'::jsonb, '["d"]', 'Laxatives and other measures that stimulate peristalsis are never given in complete obstruction because they may cause perforation. NPO, NG tube, and IV fluids are standard treatment.'),
  ('sbo_lbo', 26, 'A nursing student asks why laxatives are contraindicated for a client with a complete bowel obstruction. Which explanation by the nurse is correct?', '[{"id": "a", "text": "They may cause the bowel to perforate."}, {"id": "b", "text": "They will make the vomiting fecal-smelling."}, {"id": "c", "text": "They mask the signs of a paralytic ileus."}, {"id": "d", "text": "They slow gut motility and worsen distention."}]'::jsonb, '["a"]', 'Stimulating peristalsis in complete obstruction may cause perforation. Slowing gut motility is the concern with opioids, not laxatives.'),
  ('sbo_lbo', 27, 'The spouse of a client with a complete large bowel obstruction says, ''I brought a laxative from home to get things moving.'' Which response by the nurse is best?', '[{"id": "a", "text": "Laxatives can be given if bowel sounds are tinkling."}, {"id": "b", "text": "Laxatives are helpful once the NG tube is placed."}, {"id": "c", "text": "Laxatives work best if given with the IV fluids."}, {"id": "d", "text": "Laxatives are not given because they may cause perforation."}]'::jsonb, '["d"]', 'Laxatives are never given in complete obstruction because stimulating peristalsis may cause perforation.'),
  ('sbo_lbo', 28, 'A client with a bowel obstruction asks why a nasogastric tube is being inserted. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It provides nutrition while you are NPO."}, {"id": "b", "text": "It stimulates the bowel to start moving."}, {"id": "c", "text": "It allows laxatives to be given directly."}, {"id": "d", "text": "It relieves the distention and vomiting."}]'::jsonb, '["d"]', 'An NG tube is used for both ileus and large bowel obstruction to relieve distention and vomiting. Stimulating peristalsis is avoided in complete obstruction.'),
  ('sbo_lbo', 29, 'The nurse is caring for one client with paralytic ileus and another with a large bowel obstruction. Which intervention does the nurse anticipate for both clients?', '[{"id": "a", "text": "Stimulant laxative"}, {"id": "b", "text": "Cleansing enema"}, {"id": "c", "text": "Nasogastric tube"}, {"id": "d", "text": "High-fiber diet"}]'::jsonb, '["c"]', 'Both conditions are treated with NPO, an NG tube, and IV fluids. Laxatives and stimulating peristalsis are avoided in complete obstruction.'),
  ('sbo_lbo', 30, 'A client with paralytic ileus asks for something to eat. Which response by the nurse is correct?', '[{"id": "a", "text": "You can have a light meal of soft foods."}, {"id": "b", "text": "You can eat once you take a laxative."}, {"id": "c", "text": "You need to stay NPO for now."}, {"id": "d", "text": "You should start a high-fiber diet."}]'::jsonb, '["c"]', 'Treatment of paralytic ileus includes NPO status, an NG tube, and IV fluids. Laxatives are not used to restart a stalled bowel.'),
  ('sbo_lbo', 31, 'A client is 4 days post-op with paralytic ileus and reports abdominal discomfort. Which prescription should the nurse clarify with the provider?', '[{"id": "a", "text": "Morphine IV every 2 hours as needed"}, {"id": "b", "text": "NG tube to low suction"}, {"id": "c", "text": "IV fluids at a continuous rate"}, {"id": "d", "text": "NPO status until further notice"}]'::jsonb, '["a"]', 'Opioids slow gut motility and worsen obstruction and ileus. IV fluids, NG tube, and NPO are standard treatment.'),
  ('sbo_lbo', 32, 'A nursing student asks why opioids are avoided for a client with a bowel obstruction. Which response by the nurse is accurate?', '[{"id": "a", "text": "Opioids cause tinkling sounds."}, {"id": "b", "text": "Opioids speed up peristalsis."}, {"id": "c", "text": "Opioids slow gut motility."}, {"id": "d", "text": "Opioids cause bowel perforation."}]'::jsonb, '["c"]', 'Opioids slow gut motility and worsen obstruction. Perforation is the risk associated with laxatives and stimulating peristalsis.'),
  ('sbo_lbo', 33, 'A client who has taken opioids for several weeks develops abdominal distention, lack of flatus, and hypoactive bowel sounds in all four quadrants. There is no history of surgery. Which condition does the nurse suspect?', '[{"id": "a", "text": "Volvulus"}, {"id": "b", "text": "Paralytic ileus"}, {"id": "c", "text": "Colon cancer"}, {"id": "d", "text": "Hernia"}]'::jsonb, '["b"]', 'Opioid use is a common cause of paralytic ileus. Volvulus, colon cancer, and hernia are mechanical causes of large bowel obstruction.'),
  ('sbo_lbo', 34, 'A client is admitted with a suspected bowel obstruction of unknown type. Which finding does the nurse expect regardless of whether it is ileus or large bowel obstruction?', '[{"id": "a", "text": "Abdominal distention"}, {"id": "b", "text": "Fecal-smelling vomiting"}, {"id": "c", "text": "Tinkling bowel sounds"}, {"id": "d", "text": "Uniform gas on x-ray"}]'::jsonb, '["a"]', 'Pain, abdominal distention, and lack of flatus are common to both conditions. Fecal-smelling vomiting and tinkling sounds point to large bowel obstruction, and uniform gas on x-ray points to ileus.'),
  ('sbo_lbo', 35, 'A newly hired nurse is discussing postoperative assessment findings. Which statement by the new nurse requires correction?', '[{"id": "a", "text": "Absent bowel sounds on post-op day 4 should make me suspect ileus."}, {"id": "b", "text": "Absent bowel sounds on post-op day 1 mean the client has an ileus."}, {"id": "c", "text": "Anesthesia can cause absent bowel sounds in the first 2 days."}, {"id": "d", "text": "Absent bowel sounds beyond 3 days after surgery need intervention."}]'::jsonb, '["b"]', 'Absent bowel sounds less than 2 days after surgery are normal because of anesthesia. Ileus is suspected when bowel sounds remain absent beyond 3 days.'),
  ('sbo_lbo', 36, 'The nurse is reviewing assessment findings for four postoperative clients. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Post-op day 1 with absent bowel sounds"}, {"id": "b", "text": "Post-op day 4 with absent bowel sounds"}, {"id": "c", "text": "Post-op hour 12 with absent bowel sounds"}, {"id": "d", "text": "Post-op hour 30 with absent bowel sounds"}]'::jsonb, '["b"]', 'Absent bowel sounds more than 3 days after surgery suggest paralytic ileus and require intervention. Absent bowel sounds within the first 2 days are expected from anesthesia.'),
  ('sbo_lbo', 37, 'The radiology report for a postoperative client states, ''Gas throughout both the small and large intestines with uniform distention; no point of obstruction.'' The nurse recognizes this finding as consistent with which condition?', '[{"id": "a", "text": "Large bowel obstruction"}, {"id": "b", "text": "Colon volvulus"}, {"id": "c", "text": "Fecal impaction"}, {"id": "d", "text": "Paralytic ileus"}]'::jsonb, '["d"]', 'Gas in both the small and large intestines with uniform distention is the x-ray picture of paralytic ileus. Large bowel obstruction, including volvulus and fecal impaction, shows no gas beyond the blockage.'),
  ('sbo_lbo', 38, 'The nurse is assessing a client with abdominal distention. Which finding suggests a large bowel obstruction rather than paralytic ileus?', '[{"id": "a", "text": "Crampy, severe, intermittent pain"}, {"id": "b", "text": "Dull, generalized abdominal discomfort"}, {"id": "c", "text": "Absent bowel sounds in all quadrants"}, {"id": "d", "text": "Gas in both small and large intestines"}]'::jsonb, '["a"]', 'Large bowel obstruction causes crampy, severe, intermittent pain. Dull generalized pain, absent bowel sounds in all quadrants, and gas in both intestines are features of paralytic ileus.'),
  ('sbo_lbo', 39, 'An older adult with a known fecal impaction now has increasing abdominal distention and has passed no stool or gas for 3 days. Which condition should the nurse suspect?', '[{"id": "a", "text": "Paralytic ileus"}, {"id": "b", "text": "Expected postoperative finding"}, {"id": "c", "text": "Large bowel obstruction"}, {"id": "d", "text": "Effect of anesthesia"}]'::jsonb, '["c"]', 'Fecal impaction is a common cause of mechanical large bowel obstruction, which produces absolute constipation with no stool or gas. Paralytic ileus has no physical blockage.'),
  ('sbo_lbo', 40, 'A client is admitted with a complete large bowel obstruction, abdominal distention, and vomiting. Which intervention should the nurse anticipate implementing?', '[{"id": "a", "text": "Encourage oral fluids and frequent ambulation"}, {"id": "b", "text": "Administer a cleansing enema to clear the colon"}, {"id": "c", "text": "Maintain NPO and prepare for NG tube insertion"}, {"id": "d", "text": "Administer an opioid for the crampy abdominal pain"}]'::jsonb, '["c"]', 'Large bowel obstruction is treated with NPO, an NG tube, and IV fluids, and opioids are avoided. Stimulating peristalsis in complete obstruction may cause perforation.'),
  ('sbo_lbo', 41, 'A client with a large bowel obstruction had an NG tube placed 6 hours ago. Which finding best indicates that the NG tube is effective?', '[{"id": "a", "text": "Bowel sounds have changed from tinkling to silent"}, {"id": "b", "text": "Abdominal distention has decreased and vomiting has stopped"}, {"id": "c", "text": "The client is now passing a large amount of stool"}, {"id": "d", "text": "The client''s white blood cell count has increased"}]'::jsonb, '["b"]', 'The NG tube relieves distention and vomiting. Tinkling sounds becoming silent indicate a progressing obstruction, and a rising WBC is a sign of perforation or sepsis.'),
  ('sbo_lbo', 42, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with paralytic ileus who has an NG tube. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting that the abdomen looks more distended"}, {"id": "b", "text": "Giving the client a cup of water when asked"}, {"id": "c", "text": "Recording the client''s vital signs on time"}, {"id": "d", "text": "Helping the client reposition in bed"}]'::jsonb, '["b"]', 'A client with paralytic ileus is kept NPO with an NG tube and IV fluids, so giving water is incorrect. Reporting increased distention is appropriate.'),
  ('sbo_lbo', 43, 'The nurse is interviewing a client admitted with abdominal pain. Which client statement is most consistent with a large bowel obstruction?', '[{"id": "a", "text": "My pain started suddenly this morning, and I vomited right away."}, {"id": "b", "text": "My belly has swollen gradually this week, and no stool or gas has passed."}, {"id": "c", "text": "I had surgery yesterday, and the nurse can''t hear any bowel sounds."}, {"id": "d", "text": "I have a dull ache everywhere, and gas fills my whole intestine."}]'::jsonb, '["b"]', 'Large bowel obstruction has a gradual onset with absolute constipation and no stool or gas. Abrupt onset with early vomiting fits small bowel obstruction, and absent sounds the day after surgery are expected.'),
  ('sbo_lbo', 44, 'A client with a large bowel obstruction has been NPO for 2 days. The nurse notes that the client''s emesis now has a fecal odor. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is consistent with the late vomiting of large bowel obstruction."}, {"id": "b", "text": "It is an expected effect of the anesthesia from earlier surgery."}, {"id": "c", "text": "It indicates that the obstruction has been completely relieved."}, {"id": "d", "text": "It confirms paralytic ileus with uniform intestinal distention."}]'::jsonb, '["a"]', 'Vomiting in large bowel obstruction occurs late and may be fecal-smelling. It does not indicate relief of the obstruction.'),
  ('sbo_lbo', 45, 'A charge nurse is teaching a new nurse about monitoring a client with a large bowel obstruction. Which group of findings should the new nurse monitor for as signs of perforation or sepsis?', '[{"id": "a", "text": "Abdominal rigidity, fever, and elevated WBC"}, {"id": "b", "text": "Passage of flatus, soft stool, and hunger"}, {"id": "c", "text": "Tinkling bowel sounds and crampy pain only"}, {"id": "d", "text": "Gradual distention and absence of stool only"}]'::jsonb, '["a"]', 'Abdominal rigidity, fever, and an elevated WBC are signs of perforation or sepsis. Tinkling sounds, crampy pain, gradual distention, and no stool are expected features of the obstruction itself.'),
  ('sbo_lbo', 46, 'A nursing student is comparing paralytic ileus with large bowel obstruction. Which statement by the student is accurate?', '[{"id": "a", "text": "Ileus is a mechanical blockage; LBO has no physical blockage."}, {"id": "b", "text": "Ileus has no physical blockage; LBO is a mechanical blockage."}, {"id": "c", "text": "Both conditions are caused by a physical blockage in the colon."}, {"id": "d", "text": "Neither condition involves distention of the abdomen."}]'::jsonb, '["b"]', 'Paralytic ileus is neurogenic with no physical blockage, whereas large bowel obstruction is a mechanical blockage in the large intestine.'),
  ('sbo_lbo', 47, 'A client with paralytic ileus after abdominal surgery says, ''So something is stuck inside my bowel?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "Yes, a tumor is blocking your large intestine."}, {"id": "b", "text": "Yes, a twisted loop of bowel is blocking it."}, {"id": "c", "text": "No, the bowel is paralyzed rather than blocked."}, {"id": "d", "text": "No, the bowel is moving faster than normal."}]'::jsonb, '["c"]', 'Paralytic ileus is neurogenic: there is no physical blockage, and the bowel is paralyzed. Tumor and volvulus are mechanical causes of large bowel obstruction.'),
  ('sbo_lbo', 48, 'The nurse is reviewing four clients'' histories. Which client is at greatest risk for a large bowel obstruction?', '[{"id": "a", "text": "A client with a known colon stricture"}, {"id": "b", "text": "A client on post-op day 2 receiving opioids"}, {"id": "c", "text": "A client recovering from spinal trauma"}, {"id": "d", "text": "A client with a low serum potassium level"}]'::jsonb, '["a"]', 'A stricture is a mechanical cause of large bowel obstruction. Surgery, opioids, spinal trauma, and hypokalemia are causes of paralytic ileus.'),
  ('sbo_lbo', 49, 'A client who had abdominal surgery yesterday is worried because the nurse could not hear bowel sounds. Which response by the nurse is best?', '[{"id": "a", "text": "This means you need a laxative right away."}, {"id": "b", "text": "This means you have developed an ileus."}, {"id": "c", "text": "This means your bowel is blocked by stool."}, {"id": "d", "text": "This is expected so soon after anesthesia."}]'::jsonb, '["d"]', 'Absent bowel sounds less than 2 days after surgery are normal because of anesthesia. Ileus is suspected only after more than 3 days, and laxatives are not given.'),
  ('sbo_lbo', 50, 'A client is admitted with a bowel obstruction. Which finding does the nurse expect in both paralytic ileus and large bowel obstruction?', '[{"id": "a", "text": "Fecal-smelling emesis"}, {"id": "b", "text": "Lack of flatus"}, {"id": "c", "text": "Air-fluid levels on CT"}, {"id": "d", "text": "Uniform gas on x-ray"}]'::jsonb, '["b"]', 'Pain, abdominal distention, and lack of flatus are symptoms common to both conditions. Fecal-smelling emesis and air-fluid levels point to large bowel obstruction, and uniform gas points to ileus.'),
  ('lower_gi_obstruction', 1, 'A client returned from abdominal surgery 20 hours ago. The nurse cannot hear bowel sounds in any quadrant. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Request a laxative to stimulate bowel activity"}, {"id": "b", "text": "Notify the provider of a suspected paralytic ileus"}, {"id": "c", "text": "Prepare to insert a nasogastric tube immediately"}, {"id": "d", "text": "Continue routine monitoring because this is expected"}]'::jsonb, '["d"]', 'Absent bowel sounds less than 2 days after surgery are normal and expected due to anesthesia. Ileus is suspected only when they remain absent more than 3 days post-op.'),
  ('lower_gi_obstruction', 2, 'A client is on post-op day 4 after abdominal surgery and still has absent bowel sounds. Which action should the nurse take?', '[{"id": "a", "text": "Document the finding as an expected anesthesia effect"}, {"id": "b", "text": "Reassess in 3 more days before taking any action"}, {"id": "c", "text": "Advance the diet to stimulate the return of bowel sounds"}, {"id": "d", "text": "Notify the provider because paralytic ileus is suspected"}]'::jsonb, '["d"]', 'Absent bowel sounds more than 3 days post-op suggest paralytic ileus and require intervention. Attributing them to anesthesia applies only to the first 2 days.'),
  ('lower_gi_obstruction', 3, 'Twelve hours after surgery, a client asks why the nurse cannot hear any bowel sounds. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A twisted loop of bowel is blocking your intestine."}, {"id": "b", "text": "Your bowel is blocked, and you will need an NG tube."}, {"id": "c", "text": "You have developed a paralytic ileus from the surgery."}, {"id": "d", "text": "Anesthesia temporarily causes this, so it is expected."}]'::jsonb, '["d"]', 'Absent bowel sounds in the first 2 days after surgery are normal and expected due to anesthesia. Paralytic ileus is suspected only after more than 3 days.'),
  ('lower_gi_obstruction', 4, 'The charge nurse reviews bowel sound assessments on four postoperative clients. Which client requires intervention?', '[{"id": "a", "text": "Absent bowel sounds 12 hours after surgery"}, {"id": "b", "text": "Absent bowel sounds 4 days after surgery"}, {"id": "c", "text": "Absent bowel sounds 1 day after surgery"}, {"id": "d", "text": "Absent bowel sounds 36 hours after surgery"}]'::jsonb, '["b"]', 'Absent bowel sounds for more than 3 days post-op suggest paralytic ileus and require intervention. Absent sounds within the first 2 days are expected from anesthesia.'),
  ('lower_gi_obstruction', 5, 'A newly licensed nurse is caring for a client on post-op day 1 who has absent bowel sounds. Which statement by the new nurse requires correction by the preceptor?', '[{"id": "a", "text": "I will report this now because it means ileus."}, {"id": "b", "text": "I will keep assessing bowel sounds each shift."}, {"id": "c", "text": "This is expected because of the anesthesia."}, {"id": "d", "text": "I would worry if this lasts beyond 3 days."}]'::jsonb, '["a"]', 'Absent bowel sounds less than 2 days post-op are normal due to anesthesia, so labeling this as ileus is incorrect. Ileus is suspected when absence lasts beyond 3 days.'),
  ('lower_gi_obstruction', 6, 'A nursing student is explaining the postoperative bowel sound timeline. Which statement by the student is correct?', '[{"id": "a", "text": "Absent sounds are expected under 2 days and suggest ileus after 3 days."}, {"id": "b", "text": "Absent sounds suggest ileus under 2 days and are expected after 3 days."}, {"id": "c", "text": "Absent sounds are expected at any time during the first postoperative week."}, {"id": "d", "text": "Absent sounds always indicate ileus, regardless of the postoperative day."}]'::jsonb, '["a"]', 'Absent bowel sounds are normal less than 2 days post-op due to anesthesia, and paralytic ileus is suspected when they are absent more than 3 days post-op.'),
  ('lower_gi_obstruction', 7, 'A client is admitted with a small bowel obstruction (SBO). Which characteristic of vomiting does the nurse expect?', '[{"id": "a", "text": "Vomiting only after a laxative is given"}, {"id": "b", "text": "Late vomiting after several days"}, {"id": "c", "text": "No vomiting at any point in the illness"}, {"id": "d", "text": "Early vomiting that may be bilious"}]'::jsonb, '["d"]', 'SBO presents with early vomiting that may be bilious. Late vomiting is characteristic of large bowel obstruction.'),
  ('lower_gi_obstruction', 8, 'The nurse is comparing two clients with bowel obstruction. Which finding is more consistent with a large bowel obstruction (LBO) than with a small bowel obstruction (SBO)?', '[{"id": "a", "text": "Early bilious vomiting"}, {"id": "b", "text": "Vomiting at the onset of pain"}, {"id": "c", "text": "Abrupt onset of symptoms"}, {"id": "d", "text": "Constipation with late vomiting"}]'::jsonb, '["d"]', 'LBO presents with constipation and late vomiting. Early, possibly bilious vomiting and abrupt onset are features of SBO.'),
  ('lower_gi_obstruction', 9, 'A client is diagnosed with a large bowel obstruction (LBO). Which onset pattern does the nurse expect the client to describe?', '[{"id": "a", "text": "Symptoms that started abruptly within an hour"}, {"id": "b", "text": "Symptoms that began right after anesthesia"}, {"id": "c", "text": "Symptoms that developed gradually over time"}, {"id": "d", "text": "Symptoms that appeared only after a laxative"}]'::jsonb, '["c"]', 'LBO is mechanical and has a gradual onset, whereas SBO has an abrupt onset.'),
  ('lower_gi_obstruction', 10, 'The nurse reviews four clients'' diagnoses. Which client is at risk for a large bowel obstruction (LBO)?', '[{"id": "a", "text": "A client with absent bowel sounds on day 1"}, {"id": "b", "text": "A client 1 day after anesthesia"}, {"id": "c", "text": "A client with a sigmoid volvulus"}, {"id": "d", "text": "A client receiving IV fluids for hydration"}]'::jsonb, '["c"]', 'LBO is a mechanical obstruction caused by conditions such as tumor or volvulus. Absent bowel sounds in the first day after anesthesia are expected.'),
  ('lower_gi_obstruction', 11, 'A client has a large bowel obstruction caused by a colon tumor. Which treatment should the nurse anticipate will often be needed?', '[{"id": "a", "text": "Surgery"}, {"id": "b", "text": "Laxatives"}, {"id": "c", "text": "Opioids"}, {"id": "d", "text": "High-fiber diet"}]'::jsonb, '["a"]', 'Surgery is often required for LBO caused by tumors, volvulus, or strictures. Laxatives risk perforation in complete obstruction, and opioids worsen obstruction.'),
  ('lower_gi_obstruction', 12, 'The nurse is assessing a client with a suspected lower GI obstruction of unknown type. Which group of findings is expected in both small and large bowel obstruction?', '[{"id": "a", "text": "Pain, distention, and no flatus"}, {"id": "b", "text": "Early bilious vomiting only"}, {"id": "c", "text": "Constipation with late vomiting"}, {"id": "d", "text": "Normal bowel sounds and hunger"}]'::jsonb, '["a"]', 'Pain, abdominal distention, and no flatus occur in both SBO and LBO. Early bilious vomiting is specific to SBO, and constipation with late vomiting is specific to LBO.'),
  ('lower_gi_obstruction', 13, 'A client with a small bowel obstruction asks for breakfast. Which response by the nurse is correct?', '[{"id": "a", "text": "You can have clear liquids for breakfast."}, {"id": "b", "text": "You can eat once your pain is controlled."}, {"id": "c", "text": "You can eat once you have a bowel movement."}, {"id": "d", "text": "You need to have nothing by mouth for now."}]'::jsonb, '["d"]', 'Treatment of SBO includes NPO status, meaning nothing by mouth, along with an NG tube and IV fluids.'),
  ('lower_gi_obstruction', 14, 'A client with a small bowel obstruction asks why a nasogastric (NG) tube is needed. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It stimulates the bowel to begin moving again."}, {"id": "b", "text": "It delivers nutrition while you cannot eat or drink."}, {"id": "c", "text": "It allows the nurse to give laxatives directly."}, {"id": "d", "text": "It manages the vomiting and decompresses the bowel."}]'::jsonb, '["d"]', 'The NG tube in SBO is used to manage vomiting and decompress the bowel. Stimulating peristalsis is avoided in complete obstruction.'),
  ('lower_gi_obstruction', 15, 'A client with a large bowel obstruction (LBO) asks, ''My roommate with a small bowel obstruction has an NG tube. Will I need one too?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "No, NG tubes are only used for small bowel obstruction."}, {"id": "b", "text": "Yes, an NG tube is used for both types of obstruction."}, {"id": "c", "text": "No, the NG tube is needed only after abdominal surgery."}, {"id": "d", "text": "Yes, but only after you have had a bowel movement."}]'::jsonb, '["b"]', 'An NG tube is used for both SBO and LBO to relieve distention and vomiting.'),
  ('lower_gi_obstruction', 16, 'A nasogastric tube was inserted 4 hours ago for a client with a bowel obstruction. Which finding best indicates the intervention is effective?', '[{"id": "a", "text": "Abdominal distention and vomiting have decreased."}, {"id": "b", "text": "The client has had a large, formed bowel movement."}, {"id": "c", "text": "The client now reports hunger and asks for food."}, {"id": "d", "text": "The client''s abdomen has become firm and rigid."}]'::jsonb, '["a"]', 'The NG tube relieves distention and vomiting, so a decrease in both shows effectiveness. A rigid abdomen is a sign of perforation.'),
  ('lower_gi_obstruction', 17, 'A client with a small bowel obstruction who is NPO asks why IV fluids are infusing. Which response by the nurse is accurate?', '[{"id": "a", "text": "They replace the need for the nasogastric tube."}, {"id": "b", "text": "They flush the blockage through your intestine."}, {"id": "c", "text": "They stimulate your bowel to start moving again."}, {"id": "d", "text": "They maintain your hydration while you are NPO."}]'::jsonb, '["d"]', 'IV fluids are given in SBO to maintain hydration. They do not relieve the obstruction or replace NG decompression.'),
  ('lower_gi_obstruction', 18, 'A client on post-op day 4 has paralytic ileus and reports abdominal pain. Which prescription should the nurse clarify with the provider?', '[{"id": "a", "text": "NPO status"}, {"id": "b", "text": "IV fluid infusion"}, {"id": "c", "text": "NG tube to suction"}, {"id": "d", "text": "Hydromorphone IV as needed"}]'::jsonb, '["d"]', 'Opioids are avoided in SBO and paralytic ileus because they worsen constipation. NPO, IV fluids, and NG decompression are standard treatment.'),
  ('lower_gi_obstruction', 19, 'A client with a bowel obstruction asks why the provider is avoiding opioid pain medication. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Opioids increase peristalsis and risk perforation."}, {"id": "b", "text": "Opioids slow gut motility and worsen obstruction."}, {"id": "c", "text": "Opioids cause the bowel sounds to become loud."}, {"id": "d", "text": "Opioids make the vomiting become bilious."}]'::jsonb, '["b"]', 'Opioids slow gut motility and worsen obstruction. The perforation risk from stimulating peristalsis relates to laxatives.'),
  ('lower_gi_obstruction', 20, 'A nursing student is planning care for a client with a lower GI obstruction. Which statement by the student requires correction?', '[{"id": "a", "text": "I will keep the client NPO as prescribed."}, {"id": "b", "text": "I will monitor for abdominal rigidity and fever."}, {"id": "c", "text": "I will offer opioids first to relax the bowel."}, {"id": "d", "text": "I will check that the NG tube is decompressing."}]'::jsonb, '["c"]', 'Opioids are avoided because they slow gut motility and worsen obstruction. NPO, monitoring for perforation, and NG decompression are appropriate.'),
  ('lower_gi_obstruction', 21, 'The nurse reviews prescriptions for a client with a complete bowel obstruction. Which prescription should the nurse question?', '[{"id": "a", "text": "Bisacodyl laxative daily"}, {"id": "b", "text": "NG tube decompression"}, {"id": "c", "text": "IV fluids for hydration"}, {"id": "d", "text": "Strict NPO status"}]'::jsonb, '["a"]', 'Laxatives must never be given in complete obstruction because of the perforation risk. NG decompression, IV fluids, and NPO are standard care.'),
  ('lower_gi_obstruction', 22, 'A nursing student asks why stimulating peristalsis is unsafe for a client with a complete bowel obstruction. Which response by the nurse is correct?', '[{"id": "a", "text": "It makes the vomiting occur later."}, {"id": "b", "text": "It causes hypoactive bowel sounds."}, {"id": "c", "text": "It increases the risk of perforation."}, {"id": "d", "text": "It slows the motility of the gut."}]'::jsonb, '["c"]', 'Laxatives or other measures that stimulate peristalsis in complete obstruction carry a perforation risk. Slowing gut motility is the effect of opioids.'),
  ('lower_gi_obstruction', 23, 'The daughter of a client with a complete large bowel obstruction says, ''I''ll give Mom a laxative so she can finally go.'' Which response by the nurse is best?', '[{"id": "a", "text": "That is a good idea once her NG tube is removed."}, {"id": "b", "text": "Please give it with a full glass of water."}, {"id": "c", "text": "A laxative is safe if she also gets IV fluids."}, {"id": "d", "text": "Laxatives could cause her bowel to perforate."}]'::jsonb, '["d"]', 'Laxatives are never given in complete obstruction because of the perforation risk, regardless of other treatments.'),
  ('lower_gi_obstruction', 24, 'A client with a large bowel obstruction develops a rigid abdomen, a temperature of 102.6°F (39.2°C), and an elevated WBC count. Which complication does the nurse suspect?', '[{"id": "a", "text": "Expected anesthesia effect"}, {"id": "b", "text": "Perforation"}, {"id": "c", "text": "Resolving obstruction"}, {"id": "d", "text": "Normal postoperative course"}]'::jsonb, '["b"]', 'Abdominal rigidity, fever, and an elevated WBC are signs of perforation.'),
  ('lower_gi_obstruction', 25, 'The nurse is caring for a client with a large bowel obstruction. Which new finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Abdominal distention"}, {"id": "b", "text": "Abdominal rigidity"}, {"id": "c", "text": "No passage of flatus"}, {"id": "d", "text": "Constipation"}]'::jsonb, '["b"]', 'Abdominal rigidity is a sign of perforation that must be monitored for and reported. Distention, no flatus, and constipation are expected features of LBO.'),
  ('lower_gi_obstruction', 26, 'The nurse reviews the morning laboratory results of a client with a bowel obstruction. Which result, together with a new fever, suggests perforation?', '[{"id": "a", "text": "Decreased WBC count"}, {"id": "b", "text": "Elevated WBC count"}, {"id": "c", "text": "Normal WBC count"}, {"id": "d", "text": "Unchanged WBC count"}]'::jsonb, '["b"]', 'An elevated WBC count with fever and abdominal rigidity is a sign of perforation.'),
  ('lower_gi_obstruction', 27, 'A client is admitted with a large bowel obstruction (LBO). Which diet prescription does the nurse expect?', '[{"id": "a", "text": "Clear liquids"}, {"id": "b", "text": "NPO"}, {"id": "c", "text": "High-fiber diet"}, {"id": "d", "text": "Regular diet"}]'::jsonb, '["b"]', 'Diet modification for LBO is NPO, as it is for SBO.'),
  ('lower_gi_obstruction', 28, 'The nurse auscultates the abdomen of a postoperative client who has developed paralytic ileus. Which bowel sound pattern does the nurse expect?', '[{"id": "a", "text": "Hyperactive progressing to loud"}, {"id": "b", "text": "Hypoactive progressing to absent"}, {"id": "c", "text": "Normal in all four quadrants"}, {"id": "d", "text": "Absent progressing to hyperactive"}]'::jsonb, '["b"]', 'In paralytic ileus, bowel sounds are hypoactive and progress to absent.'),
  ('lower_gi_obstruction', 29, 'A client with a small bowel obstruction is vomiting repeatedly and has marked abdominal distention. Which prescription does the nurse anticipate to address both problems?', '[{"id": "a", "text": "Oral laxative twice daily"}, {"id": "b", "text": "Nasogastric tube decompression"}, {"id": "c", "text": "Opioid analgesic every 4 hours"}, {"id": "d", "text": "Clear liquids as tolerated"}]'::jsonb, '["b"]', 'The NG tube manages vomiting and decompresses the bowel, relieving distention. Opioids worsen obstruction, and the client is kept NPO.'),
  ('lower_gi_obstruction', 30, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with a small bowel obstruction. Which action by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "Reporting that the client vomited bile-colored fluid"}, {"id": "b", "text": "Giving the client sips of juice when the client is thirsty"}, {"id": "c", "text": "Measuring the client''s NG tube output at end of shift"}, {"id": "d", "text": "Telling the nurse the client has not passed any flatus"}]'::jsonb, '["b"]', 'A client with SBO is NPO, which means nothing by mouth, so giving juice is incorrect. Reporting vomiting and absent flatus is appropriate.'),
  ('lower_gi_obstruction', 31, 'A client is admitted with a small bowel obstruction. Which set of prescriptions does the nurse anticipate?', '[{"id": "a", "text": "Clear liquids, laxative, IV opioids"}, {"id": "b", "text": "NPO, NG tube decompression, IV fluids"}, {"id": "c", "text": "Regular diet, enema, oral opioids"}, {"id": "d", "text": "NPO, stimulant laxative, IV opioids"}]'::jsonb, '["b"]', 'SBO is treated with NPO, NG tube decompression, and IV fluids while avoiding opioids. Laxatives are never given in complete obstruction.'),
  ('lower_gi_obstruction', 32, 'A client reports that abdominal pain began suddenly a few hours ago, followed soon by greenish vomiting. The abdomen is distended and the client has not passed flatus. Which condition is most consistent with these findings?', '[{"id": "a", "text": "Expected postoperative course"}, {"id": "b", "text": "Large bowel obstruction"}, {"id": "c", "text": "Small bowel obstruction"}, {"id": "d", "text": "Effect of recent anesthesia"}]'::jsonb, '["c"]', 'SBO presents with pain, distention, no flatus, and early vomiting that may be bilious. LBO has a gradual onset with late vomiting.'),
  ('lower_gi_obstruction', 33, 'The nurse is assessing a client with a large bowel obstruction (LBO). Which elimination finding does the nurse expect?', '[{"id": "a", "text": "Frequent loose stools"}, {"id": "b", "text": "Constipation"}, {"id": "c", "text": "Daily soft stools"}, {"id": "d", "text": "Increased flatus"}]'::jsonb, '["b"]', 'LBO presents with pain, distention, no flatus, constipation, and late vomiting. Loose or soft stools and increased flatus do not fit an obstruction with no flatus.'),
  ('lower_gi_obstruction', 34, 'A nursing student is describing a large bowel obstruction (LBO). Which statement by the student is accurate?', '[{"id": "a", "text": "LBO is caused by anesthesia and resolves in 2 days."}, {"id": "b", "text": "LBO is functional and begins abruptly."}, {"id": "c", "text": "LBO is mechanical and develops gradually."}, {"id": "d", "text": "LBO always causes early, bilious vomiting."}]'::jsonb, '["c"]', 'LBO is a mechanical obstruction, such as from tumor or volvulus, with a gradual onset. Early bilious vomiting and abrupt onset are features of SBO.'),
  ('lower_gi_obstruction', 35, 'A client with a large bowel obstruction asks, ''What could be causing this blockage?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "The IV fluids you received caused it."}, {"id": "b", "text": "The anesthesia from surgery causes it."}, {"id": "c", "text": "A tumor or a twisted bowel can cause it."}, {"id": "d", "text": "Not eating while NPO has caused it."}]'::jsonb, '["c"]', 'LBO is a mechanical obstruction caused by conditions such as tumor or volvulus. Absent bowel sounds from anesthesia are expected only in the first 2 days after surgery.'),
  ('lower_gi_obstruction', 36, 'A client with a suspected bowel obstruction tells the nurse, ''I haven''t passed any gas since yesterday.'' How should the nurse interpret this statement?', '[{"id": "a", "text": "It rules out an obstruction and suggests a normal bowel."}, {"id": "b", "text": "It occurs only with large bowel obstruction, not small."}, {"id": "c", "text": "It occurs only with small bowel obstruction, not large."}, {"id": "d", "text": "It is consistent with both small and large bowel obstruction."}]'::jsonb, '["d"]', 'No flatus is a symptom of both SBO and LBO, along with pain and distention.'),
  ('lower_gi_obstruction', 37, 'A client with a small bowel obstruction is NPO and has an NG tube to suction. Which prescription maintains the client''s hydration?', '[{"id": "a", "text": "IV fluids"}, {"id": "b", "text": "Oral fluids"}, {"id": "c", "text": "Opioid analgesic"}, {"id": "d", "text": "Clear liquids"}]'::jsonb, '["a"]', 'IV fluids maintain hydration in SBO while the client is NPO. Oral fluids are not allowed because the client is NPO.'),
  ('lower_gi_obstruction', 38, 'A client with a large bowel obstruction has a rigid abdomen and a new fever. Which action should the nurse take first?', '[{"id": "a", "text": "Notify the provider of possible perforation"}, {"id": "b", "text": "Administer a laxative to relieve pressure"}, {"id": "c", "text": "Give an opioid for the abdominal pain"}, {"id": "d", "text": "Offer clear liquids to maintain hydration"}]'::jsonb, '["a"]', 'Abdominal rigidity and fever are signs of perforation and require prompt reporting. Laxatives raise perforation risk, opioids worsen obstruction, and the client is NPO.'),
  ('lower_gi_obstruction', 39, 'The nurse is caring for one client with a small bowel obstruction and another with a large bowel obstruction. Which intervention is appropriate for both clients?', '[{"id": "a", "text": "NPO status"}, {"id": "b", "text": "Stimulant laxative"}, {"id": "c", "text": "Opioid analgesia"}, {"id": "d", "text": "Regular diet"}]'::jsonb, '["a"]', 'Both SBO and LBO are treated with NPO and an NG tube. Laxatives risk perforation and opioids worsen obstruction.'),
  ('lower_gi_obstruction', 40, 'The nurse reviews prescriptions for a newly admitted client with a large bowel obstruction. Which prescription should the nurse question?', '[{"id": "a", "text": "NG tube insertion"}, {"id": "b", "text": "Monitor WBC count"}, {"id": "c", "text": "Regular diet as tolerated"}, {"id": "d", "text": "Avoid opioid analgesics"}]'::jsonb, '["c"]', 'Diet modification for LBO is NPO, so a regular diet is inappropriate. An NG tube, WBC monitoring, and avoiding opioids are appropriate.'),
  ('lower_gi_obstruction', 41, 'The nurse obtains a history from a client with abdominal pain and distention. Which history best supports a large bowel obstruction rather than a small bowel obstruction?', '[{"id": "a", "text": "Vomiting started early and was bilious"}, {"id": "b", "text": "Symptoms began abruptly this morning"}, {"id": "c", "text": "Symptoms developed gradually over a week"}, {"id": "d", "text": "Surgery was performed 20 hours ago"}]'::jsonb, '["c"]', 'LBO has a gradual onset, whereas SBO is abrupt with early, possibly bilious vomiting.'),
  ('lower_gi_obstruction', 42, 'Which client with abdominal pain is most likely to have a small bowel obstruction rather than a large bowel obstruction?', '[{"id": "a", "text": "A client with early vomiting that may be bilious"}, {"id": "b", "text": "A client with constipation and late vomiting"}, {"id": "c", "text": "A client with a slowly growing colon tumor"}, {"id": "d", "text": "A client with symptoms that began gradually"}]'::jsonb, '["a"]', 'Early vomiting that may be bilious is a feature of SBO. Constipation, late vomiting, tumor, and gradual onset point to LBO.'),
  ('lower_gi_obstruction', 43, 'A client has been developing paralytic ileus after surgery. Which documented change in bowel sounds indicates the condition is progressing?', '[{"id": "a", "text": "Hypoactive bowel sounds have become absent."}, {"id": "b", "text": "Absent bowel sounds have become hypoactive."}, {"id": "c", "text": "Hypoactive bowel sounds have become normal."}, {"id": "d", "text": "Normal bowel sounds have become active."}]'::jsonb, '["a"]', 'In paralytic ileus, bowel sounds progress from hypoactive to absent.'),
  ('lower_gi_obstruction', 44, 'On post-op day 4, the nurse notes that a client''s bowel sounds, which were hypoactive yesterday, are now absent. Which action should the nurse take?', '[{"id": "a", "text": "Give a stimulant laxative to restore motility"}, {"id": "b", "text": "Document this as an expected anesthesia effect"}, {"id": "c", "text": "Report suspected paralytic ileus to the provider"}, {"id": "d", "text": "Encourage the client to eat a large meal"}]'::jsonb, '["c"]', 'Absent bowel sounds more than 3 days post-op suggest paralytic ileus, which requires intervention. The anesthesia explanation applies only in the first 2 days.'),
  ('lower_gi_obstruction', 45, 'The family of a client with a large bowel obstruction asks why the client has not vomited yet even though the abdomen is distended. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Vomiting never occurs in this type of obstruction."}, {"id": "b", "text": "Vomiting tends to occur early in this type of obstruction."}, {"id": "c", "text": "Vomiting tends to occur late in this type of obstruction."}, {"id": "d", "text": "Vomiting occurs only after the client takes a laxative."}]'::jsonb, '["c"]', 'Vomiting in LBO occurs late, whereas early, possibly bilious vomiting is characteristic of SBO.'),
  ('lower_gi_obstruction', 46, 'The nurse is assessing a client admitted with a small bowel obstruction. Along with pain and absence of flatus, which finding does the nurse expect?', '[{"id": "a", "text": "Abdominal distention"}, {"id": "b", "text": "Flat, soft abdomen"}, {"id": "c", "text": "Frequent loose stools"}, {"id": "d", "text": "Increased appetite"}]'::jsonb, '["a"]', 'SBO presents with pain, distention, no flatus, and early vomiting. A flat abdomen and loose stools do not fit an obstruction with no flatus.'),
  ('lower_gi_obstruction', 47, 'The nurse teaches a client with a small bowel obstruction about pain management. Which client statement indicates understanding?', '[{"id": "a", "text": "Opioids will help my bowel start moving again."}, {"id": "b", "text": "Opioids could slow my bowel and worsen the blockage."}, {"id": "c", "text": "Opioids are the only safe option for this pain."}, {"id": "d", "text": "Opioids will prevent the need for the NG tube."}]'::jsonb, '["b"]', 'Opioids are avoided because they slow gut motility and worsen obstruction.'),
  ('lower_gi_obstruction', 48, 'A client with a complete bowel obstruction has a laxative prescribed. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Give the laxative after the NG tube is placed"}, {"id": "b", "text": "Give the laxative with a full glass of water"}, {"id": "c", "text": "Withhold the laxative and contact the provider"}, {"id": "d", "text": "Give half the dose and reassess in one hour"}]'::jsonb, '["c"]', 'Laxatives must never be given in complete obstruction because of the perforation risk, so the nurse withholds it and clarifies the prescription.'),
  ('lower_gi_obstruction', 49, 'The nurse is caring for four clients. Which client''s condition is most likely to require surgery?', '[{"id": "a", "text": "A client with a large bowel obstruction from volvulus"}, {"id": "b", "text": "A client with absent bowel sounds 1 day after surgery"}, {"id": "c", "text": "A client 12 hours after anesthesia with no bowel sounds"}, {"id": "d", "text": "A client receiving IV fluids who is now passing flatus"}]'::jsonb, '["a"]', 'Surgery is often required for LBO caused by tumors, volvulus, or strictures. Absent bowel sounds within 2 days of surgery are expected.'),
  ('lower_gi_obstruction', 50, 'A client with a small bowel obstruction states, ''I don''t understand why I need this IV.'' Which client statement after teaching indicates understanding?', '[{"id": "a", "text": "The IV gives me opioids to speed up my bowel."}, {"id": "b", "text": "The IV pushes the blockage through my intestine."}, {"id": "c", "text": "The IV gives me laxatives to clear my bowel."}, {"id": "d", "text": "The IV keeps me hydrated while I can''t eat or drink."}]'::jsonb, '["d"]', 'IV fluids maintain hydration in SBO while the client is NPO. Laxatives and opioids are both avoided.'),
  ('appendicitis', 1, 'A client with suspected appendicitis reports that abdominal pain began around the belly button yesterday. Where does the nurse expect the pain to be localized as the condition progresses?', '[{"id": "a", "text": "Left lower quadrant"}, {"id": "b", "text": "Right lower quadrant"}, {"id": "c", "text": "Right upper quadrant"}, {"id": "d", "text": "Left upper quadrant"}]'::jsonb, '["b"]', 'Early appendicitis pain is periumbilical and then migrates to the right lower quadrant. Pain staying in or moving to the left lower quadrant does not fit the classic pattern.'),
  ('appendicitis', 2, 'A nurse is teaching a client newly diagnosed with appendicitis about the cause of the condition. Which process most often starts appendicitis?', '[{"id": "a", "text": "Acid erosion of the appendix lining"}, {"id": "b", "text": "Spread of infection from the gallbladder"}, {"id": "c", "text": "Obstruction of the appendix"}, {"id": "d", "text": "Twisting of the appendix on itself"}]'::jsonb, '["c"]', 'Appendicitis is inflammation of the appendix that usually starts with obstruction, such as a fecalith or lymphoid hyperplasia. Acid erosion and gallbladder infection are not described as causes.'),
  ('appendicitis', 3, 'A client asks the nurse how a blockage in the appendix leads to appendicitis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“Trapped mucus and bacteria cause swelling, infection, and possible ischemia.”"}, {"id": "b", "text": "“The blockage drains bacteria away, so the appendix shrinks and hardens.”"}, {"id": "c", "text": "“The blockage dries out the mucus, so the appendix wall cracks open.”"}, {"id": "d", "text": "“The blockage limits blood flow, which stops the inflammation early.”"}]'::jsonb, '["a"]', 'Obstruction traps mucus and bacteria, leading to swelling, infection, and possible ischemia. The blockage does not drain bacteria away or stop inflammation.'),
  ('appendicitis', 4, 'A nurse is reviewing the causes of appendiceal obstruction with a nursing student. In addition to a fecalith, which cause should the nurse include?', '[{"id": "a", "text": "Migration of a gallstone into the bowel"}, {"id": "b", "text": "Herniation of bowel through the abdominal wall"}, {"id": "c", "text": "Excess acid production by the stomach lining"}, {"id": "d", "text": "Swelling of immune tissue inside the appendix"}]'::jsonb, '["d"]', 'Lymphoid hyperplasia, which is swelling of immune tissue inside the appendix, can obstruct the appendix along with a fecalith. Gallstones, hernias, and stomach acid are not listed causes.'),
  ('appendicitis', 5, 'The family of a client with appendicitis asks what could happen if treatment is delayed. Which sequence of events should the nurse describe?', '[{"id": "a", "text": "Sepsis, then rupture, then peritonitis"}, {"id": "b", "text": "Rupture, then peritonitis, then sepsis"}, {"id": "c", "text": "Peritonitis, then rupture, then sepsis"}, {"id": "d", "text": "Rupture, then sepsis, then peritonitis"}]'::jsonb, '["b"]', 'If untreated, the inflamed appendix ruptures, causing peritonitis, which can progress to sepsis. The other sequences place the events in the wrong order.'),
  ('appendicitis', 6, 'A client reports dull pain around the umbilicus that started 6 hours ago. Which additional findings does the nurse expect at this early stage of appendicitis?', '[{"id": "a", "text": "Mild nausea and loss of appetite"}, {"id": "b", "text": "Rigid abdomen and hypotension"}, {"id": "c", "text": "High fever and tachycardia"}, {"id": "d", "text": "Confusion and altered mental status"}]'::jsonb, '["a"]', 'Early appendicitis presents with periumbilical pain, mild nausea, and loss of appetite. A rigid abdomen, high fever, tachycardia, hypotension, and confusion indicate rupture, peritonitis, or sepsis.'),
  ('appendicitis', 7, 'The nurse is assessing a client with right lower quadrant pain. Which finding should the nurse document as McBurney''s point tenderness?', '[{"id": "a", "text": "Right lower quadrant pain when the left lower quadrant is pressed"}, {"id": "b", "text": "Right lower quadrant pain when the right hip is extended"}, {"id": "c", "text": "Pain when pressing directly over the appendix area"}, {"id": "d", "text": "Right lower quadrant pain when the right hip is rotated inward"}]'::jsonb, '["c"]', 'McBurney''s point tenderness is pain when pressing over the appendix. Pain in the RLQ when the LLQ is pressed is Rovsing''s sign, and pain with hip extension or internal rotation is the psoas or obturator sign.'),
  ('appendicitis', 8, 'A nurse is about to palpate McBurney''s point on a client with suspected appendicitis. Where should the nurse locate this point?', '[{"id": "a", "text": "One-third of the way from the umbilicus to the xiphoid process"}, {"id": "b", "text": "One-third of the way from the left ASIS to the umbilicus"}, {"id": "c", "text": "Directly over the umbilicus at the midline of the abdomen"}, {"id": "d", "text": "One-third of the way from the right ASIS to the umbilicus"}]'::jsonb, '["d"]', 'McBurney''s point is in the right lower quadrant, one-third of the way from the ASIS to the umbilicus. The left-sided and upper abdominal locations are not over the appendix.'),
  ('appendicitis', 9, 'During an abdominal assessment, the nurse presses deeply on the client''s abdomen and then quickly lets go. The client cries out in pain when the pressure is released. How should the nurse document this finding?', '[{"id": "a", "text": "Positive Rovsing''s sign"}, {"id": "b", "text": "Rebound tenderness"}, {"id": "c", "text": "Positive psoas sign"}, {"id": "d", "text": "Positive obturator sign"}]'::jsonb, '["b"]', 'Rebound tenderness is pain upon releasing deep pressure on the abdomen. Rovsing''s sign involves pressing the LLQ, and the psoas and obturator signs involve moving the right hip.'),
  ('appendicitis', 10, 'While the nurse presses on the left lower quadrant of a client''s abdomen, the client reports sharp pain in the right lower quadrant. Which finding has the nurse elicited?', '[{"id": "a", "text": "Positive Rovsing''s sign"}, {"id": "b", "text": "Positive psoas sign"}, {"id": "c", "text": "Positive obturator sign"}, {"id": "d", "text": "McBurney''s point tenderness"}]'::jsonb, '["a"]', 'Rovsing''s sign is RLQ pain when pressing on the LLQ. McBurney''s point tenderness occurs when pressing directly over the appendix in the RLQ.'),
  ('appendicitis', 11, 'The provider asks the nurse to help position a client to check for a psoas sign. Which maneuver and response indicate a positive psoas sign?', '[{"id": "a", "text": "Pressing the LLQ causes pain in the RLQ"}, {"id": "b", "text": "Rotating the right hip inward causes RLQ pain"}, {"id": "c", "text": "Extending the right hip causes RLQ pain"}, {"id": "d", "text": "Releasing deep abdominal pressure causes pain"}]'::jsonb, '["c"]', 'The psoas sign is RLQ pain when extending the right hip. RLQ pain with internal rotation of the right hip is the obturator sign.'),
  ('appendicitis', 12, 'A client with suspected appendicitis reports right lower quadrant pain when the provider internally rotates the client''s right hip. The nurse recognizes this as which sign?', '[{"id": "a", "text": "Psoas sign"}, {"id": "b", "text": "Rovsing''s sign"}, {"id": "c", "text": "Rebound tenderness"}, {"id": "d", "text": "Obturator sign"}]'::jsonb, '["d"]', 'The obturator sign is RLQ pain when internally rotating the right hip because the appendix is inflamed near the obturator muscle. The psoas sign is elicited by extending the right hip.'),
  ('appendicitis', 13, 'A nurse is assessing a client with classic, unruptured appendicitis. Which temperature finding is most consistent with this stage?', '[{"id": "a", "text": "No temperature elevation at any point"}, {"id": "b", "text": "A low-grade fever"}, {"id": "c", "text": "A high fever with hypotension"}, {"id": "d", "text": "A temperature below normal"}]'::jsonb, '["b"]', 'Classic appendicitis symptoms include a low-grade fever. A high fever with hypotension suggests rupture with sepsis.'),
  ('appendicitis', 14, 'A client admitted with appendicitis has had severe right lower quadrant pain all morning. The client now tells the nurse, “My pain is suddenly gone.” What is the nurse''s best interpretation?', '[{"id": "a", "text": "The appendix may have ruptured"}, {"id": "b", "text": "The inflammation has resolved"}, {"id": "c", "text": "The IV antibiotics have cured it"}, {"id": "d", "text": "The fecalith has passed safely"}]'::jsonb, '["a"]', 'Sudden pain relief may indicate rupture and is not a good sign. Assuming the inflammation has resolved could delay recognition of an emergency.'),
  ('appendicitis', 15, 'A family member asks why the nurse is concerned that the client''s appendicitis pain suddenly eased. The nurse explains that if the appendix has ruptured, the brief relief is typically followed by which change?', '[{"id": "a", "text": "Permanent resolution of all abdominal pain"}, {"id": "b", "text": "Pain that moves back to the umbilicus"}, {"id": "c", "text": "Worsening pain that spreads across the abdomen"}, {"id": "d", "text": "Pain that shifts to the left lower quadrant only"}]'::jsonb, '["c"]', 'After rupture there may be temporary pain relief followed by worsening diffuse pain from peritonitis. The relief is not a sign of recovery.'),
  ('appendicitis', 16, 'A nurse is caring for a client awaiting an appendectomy. Which assessment finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Decreased appetite"}, {"id": "b", "text": "Mild nausea"}, {"id": "c", "text": "Tenderness at McBurney''s point"}, {"id": "d", "text": "Rigid, board-like abdomen"}]'::jsonb, '["d"]', 'A rigid, board-like abdomen is a rupture symptom and an emergency. Decreased appetite, mild nausea, and McBurney''s point tenderness are expected findings of appendicitis.'),
  ('appendicitis', 17, 'A nurse reviews the vital signs of four clients with appendicitis. Which set of vital signs best suggests the appendix has ruptured and sepsis is developing?', '[{"id": "a", "text": "T 98.6°F (37°C), HR 76, BP 124/78"}, {"id": "b", "text": "T 103.8°F (39.9°C), HR 128, BP 82/50"}, {"id": "c", "text": "T 100.4°F (38°C), HR 84, BP 128/80"}, {"id": "d", "text": "T 99.0°F (37.2°C), HR 70, BP 136/88"}]'::jsonb, '["b"]', 'Rupture with sepsis causes high fever, tachycardia, and hypotension. A temperature of 100.4°F with a normal heart rate and blood pressure fits uncomplicated appendicitis with low-grade fever.'),
  ('appendicitis', 18, 'The nurse reviews the complete blood count of a client admitted with right lower quadrant pain. Which result supports the diagnosis of appendicitis?', '[{"id": "a", "text": "Elevated white blood cell count"}, {"id": "b", "text": "Decreased white blood cell count"}, {"id": "c", "text": "Elevated red blood cell count"}, {"id": "d", "text": "Decreased red blood cell count"}]'::jsonb, '["a"]', 'An elevated WBC count indicates infection and supports appendicitis. A decreased WBC count does not fit the expected finding.'),
  ('appendicitis', 19, 'A client who is 20 weeks pregnant is evaluated for suspected appendicitis. Which diagnostic test does the nurse anticipate as first-line?', '[{"id": "a", "text": "Abdominal CT scan"}, {"id": "b", "text": "Barium enema study"}, {"id": "c", "text": "Abdominal ultrasound"}, {"id": "d", "text": "Delay imaging until after delivery"}]'::jsonb, '["c"]', 'Ultrasound is first-line for children and pregnant women. CT is the most accurate test for adults who are not in these groups, and enemas are avoided because they can cause rupture.'),
  ('appendicitis', 20, 'A nonpregnant 35-year-old adult has right lower quadrant pain and an elevated WBC count. Which imaging study provides the most accurate diagnosis of appendicitis for this client?', '[{"id": "a", "text": "Abdominal ultrasound"}, {"id": "b", "text": "Abdominal CT scan"}, {"id": "c", "text": "Rovsing''s sign assessment"}, {"id": "d", "text": "Complete blood count"}]'::jsonb, '["b"]', 'CT scan is the most accurate diagnosis for adults. Ultrasound is first-line for children and pregnant women.'),
  ('appendicitis', 21, 'The parent of a 7-year-old child with suspected appendicitis asks which imaging test the child will most likely have first. Which response by the nurse is accurate?', '[{"id": "a", "text": "“A CT scan is always the first test for children.”"}, {"id": "b", "text": "“An enema will be given to clear the bowel first.”"}, {"id": "c", "text": "“No imaging is used in children with this problem.”"}, {"id": "d", "text": "“An ultrasound is usually the first test for children.”"}]'::jsonb, '["d"]', 'Ultrasound is first-line for children and pregnant women, while CT is the most accurate test for adults. Enemas are avoided in appendicitis because they can cause rupture.'),
  ('appendicitis', 22, 'A client with suspected appendicitis says, “I haven''t had a bowel movement in two days. Can I have a laxative?” Which response by the nurse is appropriate?', '[{"id": "a", "text": "“Laxatives are avoided because they can cause your appendix to rupture.”"}, {"id": "b", "text": "“I''ll get you a mild stool softener to take with a glass of water.”"}, {"id": "c", "text": "“An enema would work faster, so I''ll ask the provider for one.”"}, {"id": "d", "text": "“A glass of prune juice should help your bowels move naturally.”"}]'::jsonb, '["a"]', 'Laxatives and enemas are avoided before surgery because they can cause rupture. The client must also remain NPO, so oral fluids such as prune juice are not appropriate.'),
  ('appendicitis', 23, 'A charge nurse observes care being provided to a client with suspected appendicitis. Which action by the staff nurse requires correction?', '[{"id": "a", "text": "Keeping the client NPO"}, {"id": "b", "text": "Starting the prescribed IV fluids"}, {"id": "c", "text": "Placing a heating pad on the right lower quadrant"}, {"id": "d", "text": "Monitoring for sudden relief of pain"}]'::jsonb, '["c"]', 'Heat is avoided because it may increase blood flow and inflammation and risk rupture. Keeping the client NPO, starting IV fluids, and monitoring for sudden pain relief are correct preoperative actions.'),
  ('appendicitis', 24, 'A nurse is supervising an assistive personnel (AP) caring for a client with suspected appendicitis. Which action by the AP requires the nurse to intervene?', '[{"id": "a", "text": "Reporting the client''s pain rating to the nurse"}, {"id": "b", "text": "Preparing a tap-water enema to relieve cramping"}, {"id": "c", "text": "Removing the water pitcher from the bedside"}, {"id": "d", "text": "Measuring and recording the client''s vital signs"}]'::jsonb, '["b"]', 'Enemas must be avoided in appendicitis because they can cause rupture. Removing the water pitcher supports NPO status, and reporting pain and vital signs are appropriate.'),
  ('appendicitis', 25, 'A client with suspected appendicitis asks for a warm pack for abdominal pain. Which explanation by the nurse best supports declining this request?', '[{"id": "a", "text": "“Heat decreases blood flow to the appendix and causes ischemia.”"}, {"id": "b", "text": "“Heat is safe only if it is placed on the left side of the abdomen.”"}, {"id": "c", "text": "“Heat can be used once your pain medication starts to work.”"}, {"id": "d", "text": "“Heat may increase blood flow and inflammation and risk rupture.”"}]'::jsonb, '["d"]', 'Applying heat may increase blood flow and inflammation and risk rupture, so it is avoided. Heat increases, not decreases, blood flow, and it is not made safe by changing the location or timing.'),
  ('appendicitis', 26, 'A client scheduled for an appendectomy asks the nurse for a small glass of juice. Which response by the nurse is appropriate?', '[{"id": "a", "text": "“You need to have nothing by mouth before surgery.”"}, {"id": "b", "text": "“Clear juices are allowed until you go to surgery.”"}, {"id": "c", "text": "“Small sips are fine as long as you aren''t nauseated.”"}, {"id": "d", "text": "“You may have juice if you also eat some crackers.”"}]'::jsonb, '["a"]', 'Clients with appendicitis are kept NPO, with nothing by mouth before surgery. Clear liquids are started only after surgery as the diet is advanced.'),
  ('appendicitis', 27, 'A client with suspected appendicitis rates pain 9/10. A colleague says, “We shouldn''t treat the pain until after surgery.” What is the nurse''s best action?', '[{"id": "a", "text": "Withhold all pain medication until after the appendectomy"}, {"id": "b", "text": "Apply a warm compress to the abdomen in place of medication"}, {"id": "c", "text": "Assess the pain and obtain provider orders to treat it"}, {"id": "d", "text": "Ask the client to wait until the pain reaches 10/10"}]'::jsonb, '["c"]', 'Pain can be treated after assessment and provider orders, and severe pain should not be ignored. Heat is avoided because it may increase inflammation and risk rupture.'),
  ('appendicitis', 28, 'A client with appendicitis asks why IV fluids were started before surgery. Which response by the nurse is accurate?', '[{"id": "a", "text": "“They soften stool so the blockage can pass.”"}, {"id": "b", "text": "“They prevent dehydration while you cannot eat or drink.”"}, {"id": "c", "text": "“They dilute the bacteria inside your appendix.”"}, {"id": "d", "text": "“They replace the need for IV antibiotics.”"}]'::jsonb, '["b"]', 'IV fluids are given to prevent dehydration while the client is NPO. IV antibiotics are a separate part of treatment, not replaced by fluids.'),
  ('appendicitis', 29, 'A client asks, “Why do I need IV antibiotics if my appendix is going to be removed anyway?” Which response by the nurse is accurate?', '[{"id": "a", "text": "“They soften the stool that is blocking the appendix.”"}, {"id": "b", "text": "“They make it safe to apply heat to your abdomen.”"}, {"id": "c", "text": "“They allow you to drink fluids before the surgery.”"}, {"id": "d", "text": "“They treat infection and lower the risk of complications.”"}]'::jsonb, '["d"]', 'IV antibiotics treat and reduce infection and lower complication risk. They do not change NPO status or make heat application safe.'),
  ('appendicitis', 30, 'A client scheduled for a laparoscopic appendectomy asks how it differs from other surgery. Which statement by the nurse is accurate?', '[{"id": "a", "text": "“It is minimally invasive and usually allows a faster recovery.”"}, {"id": "b", "text": "“It removes the need for IV antibiotics before the surgery.”"}, {"id": "c", "text": "“It allows you to eat a regular diet right after the surgery.”"}, {"id": "d", "text": "“It eliminates the need to get out of bed early after surgery.”"}]'::jsonb, '["a"]', 'Laparoscopic appendectomy is minimally invasive with faster recovery. Postoperative care still includes early ambulation and slowly advancing the diet.'),
  ('appendicitis', 31, 'A client who had an appendectomy yesterday is reluctant to get out of bed. Which explanation by the nurse best encourages early ambulation?', '[{"id": "a", "text": "“Walking keeps your incision from becoming red.”"}, {"id": "b", "text": "“Walking lets you start eating solid foods today.”"}, {"id": "c", "text": "“Walking helps prevent blood clots and gas pain.”"}, {"id": "d", "text": "“Walking prevents your appendix from rupturing.”"}]'::jsonb, '["c"]', 'Early ambulation after surgery prevents blood clots and gas pain. Diet is advanced slowly from clear liquids to solids regardless of ambulation.'),
  ('appendicitis', 32, 'A nurse is caring for a client 3 days after an appendectomy. Which finding indicates a possible postoperative infection?', '[{"id": "a", "text": "Incisional pain controlled with prescribed analgesic"}, {"id": "b", "text": "Fever with redness and swelling at the incision"}, {"id": "c", "text": "Passing flatus after walking in the hallway"}, {"id": "d", "text": "Tolerating clear liquids without nausea"}]'::jsonb, '["b"]', 'Postoperative infection is monitored by watching for fever, redness, and swelling at the incision. Controlled pain, passing flatus, and tolerating liquids are expected recovery findings.'),
  ('appendicitis', 33, 'A client who had an appendectomy this morning asks when eating can resume. Which response by the nurse is accurate?', '[{"id": "a", "text": "“Your first meal will be a regular solid-food tray.”"}, {"id": "b", "text": "“You will start with solid foods and then switch to liquids.”"}, {"id": "c", "text": "“You will remain on nothing by mouth for the next week.”"}, {"id": "d", "text": "“Your diet will be advanced slowly from clear liquids to solids.”"}]'::jsonb, '["d"]', 'After surgery, the diet is advanced slowly from clear liquids to solid foods. Starting with solids reverses the correct order.'),
  ('appendicitis', 34, 'A nurse provides discharge teaching to a client after an appendectomy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "“My first meal after surgery should be a large regular meal.”"}, {"id": "b", "text": "“I should walk soon after surgery to help prevent blood clots.”"}, {"id": "c", "text": "“I should report any redness or swelling at my incision.”"}, {"id": "d", "text": "“I should take deep breaths and keep my pain under control.”"}]'::jsonb, '["a"]', 'The diet is advanced slowly from clear liquids to solid foods, so a large regular first meal is incorrect. Early ambulation, monitoring the incision, and deep breathing with pain control are correct.'),
  ('appendicitis', 35, 'A nurse is planning care for a client on the first day after an appendectomy. Which intervention should the nurse include?', '[{"id": "a", "text": "Keep the client on bed rest for 3 days"}, {"id": "b", "text": "Withhold analgesics to watch for infection"}, {"id": "c", "text": "Provide pain control and encourage deep breathing"}, {"id": "d", "text": "Keep the client NPO until discharge"}]'::jsonb, '["c"]', 'Postoperative care includes pain control with deep breathing, early ambulation, and slowly advancing the diet. Prolonged bed rest and NPO status until discharge contradict this care.'),
  ('appendicitis', 36, 'A client''s appendix ruptured before surgery. Which cluster of findings should alert the nurse to peritonitis?', '[{"id": "a", "text": "Periumbilical pain, mild nausea, poor appetite"}, {"id": "b", "text": "Rigid abdomen, high fever, tachycardia, rebound tenderness"}, {"id": "c", "text": "RLQ tenderness, low-grade fever, nausea, vomiting"}, {"id": "d", "text": "Soft abdomen, normal temperature, normal heart rate"}]'::jsonb, '["b"]', 'Peritonitis after rupture presents with a rigid abdomen, high fever, tachycardia, and rebound tenderness. Periumbilical pain with nausea and poor appetite are early appendicitis symptoms.'),
  ('appendicitis', 37, 'A client with a ruptured appendix becomes confused, and the blood pressure drops from 118/76 to 84/52 mm Hg. Which complication does the nurse suspect?', '[{"id": "a", "text": "Early uncomplicated appendicitis"}, {"id": "b", "text": "Expected response to IV antibiotics"}, {"id": "c", "text": "Positive obturator sign"}, {"id": "d", "text": "Sepsis"}]'::jsonb, '["d"]', 'Sepsis, a widespread infection, presents with hypotension, confusion, and altered mental status. These findings are not expected in early uncomplicated appendicitis.'),
  ('appendicitis', 38, 'A nurse is reviewing the typical progression of appendicitis with a client who later ruptured. Which sequence of pain is most consistent with this course?', '[{"id": "a", "text": "Periumbilical pain, then RLQ pain, then sudden relief, then diffuse pain"}, {"id": "b", "text": "RLQ pain, then periumbilical pain, then diffuse pain, then sudden relief"}, {"id": "c", "text": "Diffuse pain, then sudden relief, then RLQ pain, then periumbilical pain"}, {"id": "d", "text": "Sudden relief, then periumbilical pain, then RLQ pain, then diffuse pain"}]'::jsonb, '["a"]', 'Pain starts around the umbilicus and moves to the RLQ; after rupture there may be temporary relief followed by worsening diffuse pain. The other sequences reverse these steps.'),
  ('appendicitis', 39, 'A nurse receives report on four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with appendicitis who reports mild nausea"}, {"id": "b", "text": "A client 1 day after appendectomy with incision pain of 3/10"}, {"id": "c", "text": "A client with appendicitis whose severe pain suddenly stopped"}, {"id": "d", "text": "A client with appendicitis who has a low-grade fever"}]'::jsonb, '["c"]', 'Sudden pain relief may indicate rupture, which is an emergency. Mild nausea, low-grade fever, and mild incisional pain are expected findings.'),
  ('appendicitis', 40, 'A nurse is preparing a client with appendicitis for an appendectomy. Which group of preoperative actions is appropriate?', '[{"id": "a", "text": "Offer clear liquids, apply heat, and give an enema"}, {"id": "b", "text": "Maintain NPO, start IV fluids, and explain the procedure"}, {"id": "c", "text": "Give a laxative, encourage ambulation, and offer a meal"}, {"id": "d", "text": "Apply heat, give oral fluids, and withhold pain assessment"}]'::jsonb, '["b"]', 'Preoperative care includes keeping the client NPO, starting IV fluids, and explaining the procedure. Heat, laxatives, and enemas are avoided because they risk rupture.'),
  ('appendicitis', 41, 'A client with appendicitis awaiting surgery has severe pain, and the provider prescribes an analgesic. Which route does the nurse anticipate?', '[{"id": "a", "text": "Oral tablet with a sip of water"}, {"id": "b", "text": "Heat pack in place of medication"}, {"id": "c", "text": "No analgesic until after surgery"}, {"id": "d", "text": "Intravenous analgesic"}]'::jsonb, '["d"]', 'Treatment includes IV analgesics for pain management while the client is NPO. Heat is avoided because it may increase inflammation and risk rupture.'),
  ('appendicitis', 42, 'A nurse is assessing a client with abdominal pain. Which combination of findings most strongly supports appendicitis?', '[{"id": "a", "text": "McBurney''s point tenderness, rebound tenderness, elevated WBC"}, {"id": "b", "text": "Left lower quadrant pain, soft abdomen, decreased WBC"}, {"id": "c", "text": "Pain that stays at the umbilicus, no tenderness, normal WBC"}, {"id": "d", "text": "Pain relieved by pressing the LLQ, no fever, normal WBC"}]'::jsonb, '["a"]', 'McBurney''s point tenderness, rebound tenderness, and an elevated WBC count are key findings of appendicitis. A decreased or normal WBC and absent tenderness do not support the diagnosis.'),
  ('appendicitis', 43, 'A nursing student is asked to describe Rovsing''s sign. Which description by the student is correct?', '[{"id": "a", "text": "Pain in the LLQ when the RLQ is pressed"}, {"id": "b", "text": "Pain when deep abdominal pressure is released"}, {"id": "c", "text": "Pain in the RLQ when the LLQ is pressed"}, {"id": "d", "text": "Pain in the RLQ when the right hip is extended"}]'::jsonb, '["c"]', 'Rovsing''s sign is RLQ pain when pressing on the LLQ. Pain on release of pressure is rebound tenderness, and pain with right hip extension is the psoas sign.'),
  ('appendicitis', 44, 'A nurse hears a nursing student describing rebound tenderness to a client with suspected appendicitis. Which statement by the student requires correction?', '[{"id": "a", "text": "“The pain is felt when deep pressure is released.”"}, {"id": "b", "text": "“The pain is felt only while pressure is pushed in.”"}, {"id": "c", "text": "“It is one of the classic signs of appendicitis.”"}, {"id": "d", "text": "“It can also occur with peritonitis after rupture.”"}]'::jsonb, '["b"]', 'Rebound tenderness is pain when releasing pressure, not while pressure is applied. It is a classic sign of appendicitis and is also a finding of peritonitis.'),
  ('appendicitis', 45, 'A provider documents a positive psoas sign in a client with right lower quadrant pain. The nurse understands that this finding indicates which condition?', '[{"id": "a", "text": "The appendix is inflamed near the obturator muscle"}, {"id": "b", "text": "Pain is being referred from the left lower quadrant"}, {"id": "c", "text": "The appendix has already ruptured and drained"}, {"id": "d", "text": "The appendix is inflamed against the iliopsoas muscle"}]'::jsonb, '["d"]', 'A positive psoas sign means the appendix is inflamed against the iliopsoas muscle. Inflammation near the obturator muscle produces the obturator sign.'),
  ('appendicitis', 46, 'The provider plans to check for an obturator sign in a client with suspected appendicitis. Which maneuver should the nurse expect the provider to perform?', '[{"id": "a", "text": "Internally rotating the right hip"}, {"id": "b", "text": "Extending the right hip"}, {"id": "c", "text": "Pressing on the left lower quadrant"}, {"id": "d", "text": "Releasing deep abdominal pressure"}]'::jsonb, '["a"]', 'The obturator sign is RLQ pain when internally rotating the right hip. Extending the right hip tests the psoas sign.'),
  ('appendicitis', 47, 'A nurse reinforces preoperative teaching with a client who has appendicitis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "“I shouldn''t eat or drink anything before my surgery.”"}, {"id": "b", "text": "“I should tell the nurse if my pain suddenly goes away.”"}, {"id": "c", "text": "“A heating pad on my belly will help the swelling go down.”"}, {"id": "d", "text": "“I shouldn''t take a laxative even though I''m constipated.”"}]'::jsonb, '["c"]', 'Heat is avoided because it may increase blood flow and inflammation and risk rupture. Staying NPO, reporting sudden pain relief, and avoiding laxatives are correct.'),
  ('appendicitis', 48, 'A nurse is triaging clients with abdominal complaints. Which finding is an early symptom of appendicitis rather than a classic or rupture symptom?', '[{"id": "a", "text": "Rigid, board-like abdomen"}, {"id": "b", "text": "Periumbilical pain with poor appetite"}, {"id": "c", "text": "RLQ pain when the LLQ is pressed"}, {"id": "d", "text": "High fever with hypotension"}]'::jsonb, '["b"]', 'Early symptoms are periumbilical pain with mild nausea and loss of appetite. Rovsing''s sign is a classic symptom, while a rigid abdomen and high fever with hypotension indicate rupture.'),
  ('appendicitis', 49, 'A provider tells a client that a fecalith caused the appendicitis. The client asks the nurse what a fecalith is. Which response is accurate?', '[{"id": "a", "text": "“A gallstone that has moved into the appendix.”"}, {"id": "b", "text": "“A twist in the appendix that cuts off blood flow.”"}, {"id": "c", "text": "“A tear in the wall of the appendix.”"}, {"id": "d", "text": "“A piece of hardened stool blocking the appendix.”"}]'::jsonb, '["d"]', 'A fecalith is hardened stool blocking the appendix and is a common cause of obstruction. Gallstones, twisting, and tears are not how a fecalith is described.'),
  ('appendicitis', 50, 'A client has a rigid abdomen and rebound tenderness after appendiceal rupture. Which new finding best indicates that the infection is progressing to sepsis?', '[{"id": "a", "text": "New confusion with low blood pressure"}, {"id": "b", "text": "Continued rebound tenderness"}, {"id": "c", "text": "Persistent right lower quadrant pain"}, {"id": "d", "text": "Abdomen that remains rigid on palpation"}]'::jsonb, '["a"]', 'Sepsis presents with hypotension, confusion, and altered mental status. Rebound tenderness and a rigid abdomen are findings of peritonitis already present.'),
  ('peritonitis', 1, 'The spouse of a client admitted with peritonitis asks the nurse what the condition is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“It is inflammation of the appendix that blocks the bowel.”"}, {"id": "b", "text": "“It is inflammation of the stomach lining caused by acid.”"}, {"id": "c", "text": "“It is inflammation of the thin lining of the abdominal cavity.”"}, {"id": "d", "text": "“It is inflammation of the colon caused by trapped stool.”"}]'::jsonb, '["c"]', 'Peritonitis is inflammation of the peritoneum, the thin lining of the abdominal cavity, often caused by infection from a ruptured organ. A ruptured appendix can cause peritonitis, but appendicitis itself is not peritonitis.'),
  ('peritonitis', 2, 'A nurse is assessing a client with a perforated duodenal ulcer. Which finding is the hallmark sign of peritonitis?', '[{"id": "a", "text": "Rigid, board-like abdomen"}, {"id": "b", "text": "Hyperactive bowel sounds"}, {"id": "c", "text": "Soft, nondistended abdomen"}, {"id": "d", "text": "Pain relieved on release of pressure"}]'::jsonb, '["a"]', 'A rigid, board-like abdomen is the hallmark sign of peritonitis. Bowel sounds are decreased or absent, and pain increases, not decreases, when pressure is released.'),
  ('peritonitis', 3, 'A nurse is caring for four clients on a medical unit. Which client''s condition is a recognized cause of peritonitis?', '[{"id": "a", "text": "A client with lactose intolerance after eating cheese"}, {"id": "b", "text": "A client with chronic constipation treated with fiber"}, {"id": "c", "text": "A client with external hemorrhoids and mild itching"}, {"id": "d", "text": "A client on peritoneal dialysis with a catheter infection"}]'::jsonb, '["d"]', 'Peritoneal dialysis catheter infection is a listed cause of peritonitis. The other conditions are not described as causes.'),
  ('peritonitis', 4, 'A client with a history of peptic ulcer disease suddenly reports severe, sharp abdominal pain. How should the nurse interpret this change?', '[{"id": "a", "text": "Expected ulcer discomfort that can wait"}, {"id": "b", "text": "Possible perforation requiring emergency care"}, {"id": "c", "text": "A sign that the ulcer has begun to heal"}, {"id": "d", "text": "Gas pain that will improve with walking"}]'::jsonb, '["b"]', 'A perforated peptic ulcer is a cause of peritonitis, and sudden severe abdominal pain after perforation is an emergency. Treating it as routine discomfort delays care.'),
  ('peritonitis', 5, 'A nurse is reviewing the histories of newly admitted clients. Which client is at risk for peritonitis?', '[{"id": "a", "text": "A client with blunt abdominal trauma from a car crash"}, {"id": "b", "text": "A client with seasonal allergies who is sneezing"}, {"id": "c", "text": "A client with a sprained ankle from a fall"}, {"id": "d", "text": "A client with a tension headache after work"}]'::jsonb, '["a"]', 'Abdominal trauma is a listed cause of peritonitis. The other conditions do not involve the abdominal cavity.'),
  ('peritonitis', 6, 'While assessing a client with suspected peritonitis, the nurse presses deeply on the abdomen and then quickly releases. Which client response indicates rebound tenderness?', '[{"id": "a", "text": "Pain decreases when the pressure is released"}, {"id": "b", "text": "Pain occurs only while pressure is applied"}, {"id": "c", "text": "Pain increases when the pressure is released"}, {"id": "d", "text": "Pain is unchanged by pressing or releasing"}]'::jsonb, '["c"]', 'Rebound tenderness means pain increases when pressure is released. Pain that occurs only during pressure or decreases on release is not rebound tenderness.'),
  ('peritonitis', 7, 'A nurse is admitting a client with peritonitis. Which set of vital signs does the nurse expect?', '[{"id": "a", "text": "T 98.2°F (36.8°C), HR 64, BP 132/84"}, {"id": "b", "text": "T 98.6°F (37°C), HR 58, BP 150/92"}, {"id": "c", "text": "T 97.9°F (36.6°C), HR 76, BP 120/80"}, {"id": "d", "text": "T 102°F (38.9°C), HR 116, BP 88/54"}]'::jsonb, '["d"]', 'Peritonitis causes fever, tachycardia, and hypotension. The other sets show a normal temperature with a normal or slow heart rate and normal or high blood pressure.'),
  ('peritonitis', 8, 'The nurse auscultates the abdomen of a client with peritonitis. Which finding should the nurse expect?', '[{"id": "a", "text": "Hyperactive, high-pitched bowel sounds"}, {"id": "b", "text": "Decreased or absent bowel sounds"}, {"id": "c", "text": "Normal bowel sounds in all quadrants"}, {"id": "d", "text": "Loud gurgling every few seconds"}]'::jsonb, '["b"]', 'Peritonitis causes decreased or absent bowel sounds. Hyperactive or frequent gurgling sounds are not expected.'),
  ('peritonitis', 9, 'A nurse is assessing a client with peritonitis from a ruptured diverticulum. Which additional findings should the nurse expect?', '[{"id": "a", "text": "Nausea, vomiting, and abdominal distension"}, {"id": "b", "text": "Increased appetite and a flat abdomen"}, {"id": "c", "text": "Soft abdomen and active bowel sounds"}, {"id": "d", "text": "Normal temperature and a slow pulse"}]'::jsonb, '["a"]', 'Peritonitis signs include nausea, vomiting, and abdominal distension, along with a rigid abdomen, decreased bowel sounds, and fever. A soft abdomen with active bowel sounds is not expected.'),
  ('peritonitis', 10, 'A client is evaluated for sudden severe abdominal pain after a suspected bowel perforation. Which combination of diagnostic findings best supports peritonitis from a perforation?', '[{"id": "a", "text": "Normal WBC count and no free air on CT"}, {"id": "b", "text": "Low lactic acid and a normal WBC count"}, {"id": "c", "text": "Normal WBC count with free air on X-ray"}, {"id": "d", "text": "Elevated WBC count with free air on X-ray"}]'::jsonb, '["d"]', 'Peritonitis causes an elevated WBC count (leukocytosis), and free air on abdominal X-ray or CT indicates perforation. A normal WBC count does not support the infection.'),
  ('peritonitis', 11, 'The provider orders blood cultures for a client with peritonitis. The client asks why the test is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "“They show how well your kidneys are working.”"}, {"id": "b", "text": "“They check for free air inside your abdomen.”"}, {"id": "c", "text": "“They identify the organism causing the infection.”"}, {"id": "d", "text": "“They measure the lactic acid level in your blood.”"}]'::jsonb, '["c"]', 'Blood cultures are drawn to identify the organism. Free air is found on abdominal X-ray or CT, and lactate is a separate level.'),
  ('peritonitis', 12, 'A client with sudden severe abdominal pain has an abdominal X-ray that shows free air. How should the nurse interpret this result?', '[{"id": "a", "text": "A normal finding after a recent meal"}, {"id": "b", "text": "A perforation in the GI tract"}, {"id": "c", "text": "Constipation from decreased motility"}, {"id": "d", "text": "An infection that is resolving"}]'::jsonb, '["b"]', 'Free air on abdominal X-ray or CT indicates perforation. It is not a normal or reassuring finding.'),
  ('peritonitis', 13, 'A client with suspected peritonitis is scheduled for a paracentesis and asks what the procedure involves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“A needle removes fluid from your abdomen for testing.”"}, {"id": "b", "text": "“A tube is passed through your nose into your stomach.”"}, {"id": "c", "text": "“Blood is drawn from your arm to look for bacteria.”"}, {"id": "d", "text": "“An X-ray is taken to look for air in your abdomen.”"}]'::jsonb, '["a"]', 'Paracentesis is needle aspiration of peritoneal fluid for testing. A tube through the nose is an NG tube, and blood drawn for bacteria is a blood culture.'),
  ('peritonitis', 14, 'A nasogastric (NG) tube is inserted for a client with peritonitis. The client asks why it is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "“It will be used to give you tube feedings.”"}, {"id": "b", "text": "“It allows us to give your antibiotics by mouth.”"}, {"id": "c", "text": "“It drains infected fluid from your peritoneum.”"}, {"id": "d", "text": "“It decompresses your bowel.”"}]'::jsonb, '["d"]', 'The NG tube is used to decompress the bowel. The client is kept NPO and antibiotics are given IV, and peritoneal fluid is sampled by paracentesis.'),
  ('peritonitis', 15, 'A client with peritonitis has a blood pressure of 88/52 mm Hg and dry mucous membranes. Which prescribed treatment directly addresses these findings?', '[{"id": "a", "text": "NG tube to decompress the bowel"}, {"id": "b", "text": "Paracentesis for fluid testing"}, {"id": "c", "text": "IV fluid administration"}, {"id": "d", "text": "Analgesic administration"}]'::jsonb, '["c"]', 'IV fluids are given to correct dehydration and hypotension in peritonitis. The NG tube decompresses the bowel and paracentesis is diagnostic.'),
  ('peritonitis', 16, 'A nurse is reviewing the treatment plan for a client with peritonitis. Which antibiotic therapy should the nurse anticipate?', '[{"id": "a", "text": "Oral narrow-spectrum antibiotics"}, {"id": "b", "text": "Broad-spectrum IV antibiotics"}, {"id": "c", "text": "No antibiotics until surgery"}, {"id": "d", "text": "Topical antibiotics on the abdomen"}]'::jsonb, '["b"]', 'Peritonitis is treated with broad-spectrum IV antibiotics. Oral medications are not appropriate because the client is kept NPO.'),
  ('peritonitis', 17, 'A client with peritonitis from a ruptured diverticulum asks why surgery is necessary. Which response by the nurse is accurate?', '[{"id": "a", "text": "“Surgery repairs the cause and removes infected material.”"}, {"id": "b", "text": "“Surgery places a feeding tube so you can be nourished.”"}, {"id": "c", "text": "“Surgery removes the entire lining of your abdomen.”"}, {"id": "d", "text": "“Surgery inserts a catheter for peritoneal dialysis.”"}]'::jsonb, '["a"]', 'Surgery is done to repair the cause and remove infected material. A peritoneal dialysis catheter is a possible cause of peritonitis, not a treatment.'),
  ('peritonitis', 18, 'A nurse is supervising an assistive personnel (AP) caring for a client with peritonitis. Which action by the AP requires the nurse to intervene?', '[{"id": "a", "text": "Reporting a temperature of 102°F (38.9°C)"}, {"id": "b", "text": "Measuring and recording urine output"}, {"id": "c", "text": "Helping the client change position in bed"}, {"id": "d", "text": "Bringing the client a lunch tray"}]'::jsonb, '["d"]', 'The client with peritonitis must be kept NPO. Reporting fever and measuring urine output support monitoring for sepsis.'),
  ('peritonitis', 19, 'A nurse is planning care for a client admitted with peritonitis. Which intervention is most important to include?', '[{"id": "a", "text": "Encourage a high-fiber diet to promote bowel movements"}, {"id": "b", "text": "Check vital signs once per shift if the client is stable"}, {"id": "c", "text": "Monitor vital signs closely and watch for signs of sepsis"}, {"id": "d", "text": "Encourage oral fluids to correct dehydration"}]'::jsonb, '["c"]', 'Nursing care includes monitoring vital signs closely and monitoring for signs of sepsis. The client is kept NPO, so diet and oral fluids are not appropriate.'),
  ('peritonitis', 20, 'A client develops peritonitis from a bowel obstruction with perforation. Which nursing action is appropriate?', '[{"id": "a", "text": "Provide a regular diet as tolerated"}, {"id": "b", "text": "Prepare the client for possible surgery"}, {"id": "c", "text": "Remove the NG tube to improve comfort"}, {"id": "d", "text": "Hold antibiotics until after surgery"}]'::jsonb, '["b"]', 'Bowel obstruction with perforation is a cause of peritonitis, and nursing care includes preparing for possible surgery. The client stays NPO, and IV antibiotics are administered.'),
  ('peritonitis', 21, 'The family of a client with peritonitis asks the nurse what sepsis means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“It is an infection that stays limited to one organ.”"}, {"id": "b", "text": "“It is an allergic reaction to the antibiotics given.”"}, {"id": "c", "text": "“It is fluid loss caused by vomiting and fever.”"}, {"id": "d", "text": "“It is a body-wide response to infection that can harm organs.”"}]'::jsonb, '["d"]', 'Sepsis is a systemic, life-threatening response to infection that can lead to organ dysfunction and shock. It is not limited to one organ.'),
  ('peritonitis', 22, 'A nurse teaches a client with peritonitis about the risk of sepsis. Which client statement indicates understanding?', '[{"id": "a", "text": "“My infection could spread through my body if it isn''t treated early.”"}, {"id": "b", "text": "“Only infections that start in the blood can turn into sepsis.”"}, {"id": "c", "text": "“Sepsis cannot happen once I am already in the hospital.”"}, {"id": "d", "text": "“An infection in my abdomen cannot lead to sepsis.”"}]'::jsonb, '["a"]', 'Any infection, including peritonitis, can cause sepsis if not treated early. Sepsis is not limited to infections that start in the blood.'),
  ('peritonitis', 23, 'A client being treated for peritonitis grips the nurse''s hand and says, “I feel like I might die.” What is the nurse''s best interpretation of this statement?', '[{"id": "a", "text": "Normal anxiety that needs only reassurance"}, {"id": "b", "text": "A request for more pain medication"}, {"id": "c", "text": "A possible warning sign of sepsis"}, {"id": "d", "text": "An expected effect of the NG tube"}]'::jsonb, '["c"]', 'In the S.E.P.S.I.S. mnemonic, “I feel like I might die” is a sign of sepsis and warrants prompt assessment. Dismissing it as anxiety could delay recognition.'),
  ('peritonitis', 24, 'A client with peritonitis who was alert this morning is now sleepy and confused. Which condition should the nurse suspect?', '[{"id": "a", "text": "Normal fatigue from being NPO"}, {"id": "b", "text": "Sepsis with altered mental status"}, {"id": "c", "text": "An expected effect of paracentesis"}, {"id": "d", "text": "Rebound tenderness from palpation"}]'::jsonb, '["b"]', 'Being sleepy or confused reflects altered mental status, a sign of sepsis. It should not be dismissed as normal fatigue.'),
  ('peritonitis', 25, 'A nurse is monitoring a client with peritonitis. Which findings should the nurse report as possible signs of sepsis?', '[{"id": "a", "text": "Warm, pink skin and easy, even breathing"}, {"id": "b", "text": "Normal skin color and a calm, alert manner"}, {"id": "c", "text": "Pink skin and relief of abdominal pain"}, {"id": "d", "text": "Pale or discolored skin and shortness of breath"}]'::jsonb, '["d"]', 'The S.E.P.S.I.S. mnemonic includes pale or discolored skin and shortness of breath. Warm, pink skin with easy breathing does not suggest sepsis.'),
  ('peritonitis', 26, 'A nurse provides discharge teaching to a client recovering from peritonitis about warning signs of sepsis. Which client statement indicates understanding?', '[{"id": "a", "text": "“I will seek care right away if I have shivering, fever, or chills.”"}, {"id": "b", "text": "“Feeling sleepy and confused is normal while I recover at home.”"}, {"id": "c", "text": "“Shortness of breath is expected and does not need to be reported.”"}, {"id": "d", "text": "“Pale skin means that my body is healing from the infection.”"}]'::jsonb, '["a"]', 'Shivering, fever, and chills are sepsis warning signs, and education focuses on signs of infection and early treatment. Confusion, shortness of breath, and pale skin are also signs of sepsis, not normal recovery.'),
  ('peritonitis', 27, 'A nurse is reviewing temperatures of a client with peritonitis. Which temperature meets a diagnostic criterion for sepsis?', '[{"id": "a", "text": "98.9°F (37.2°C)"}, {"id": "b", "text": "99.7°F (37.6°C)"}, {"id": "c", "text": "96.3°F (35.7°C)"}, {"id": "d", "text": "98.2°F (36.8°C)"}]'::jsonb, '["c"]', 'Sepsis criteria include a temperature above 38°C (100.4°F) or below 36°C (96.8°F), so 35.7°C qualifies. The other readings fall between 36°C and 38°C.'),
  ('peritonitis', 28, 'A nurse reviews the assessment data of a client 2 days after abdominal surgery. Which data meet sepsis diagnostic criteria?', '[{"id": "a", "text": "T 99.3°F (37.4°C), HR 82"}, {"id": "b", "text": "T 101.5°F (38.6°C), HR 108"}, {"id": "c", "text": "T 97.5°F (36.4°C), HR 88"}, {"id": "d", "text": "T 100.0°F (37.8°C), HR 76"}]'::jsonb, '["b"]', 'Sepsis criteria include a temperature above 38°C (100.4°F) and a heart rate above 90 bpm. The other options have a temperature between 36°C and 38°C and a heart rate of 90 or less.'),
  ('peritonitis', 29, 'A nursing student says, “This client''s WBC count is low, so sepsis is ruled out.” Which response by the nurse is accurate?', '[{"id": "a", "text": "“That''s correct; sepsis always raises the WBC count.”"}, {"id": "b", "text": "“The WBC count is not used to evaluate sepsis.”"}, {"id": "c", "text": "“Only a normal WBC count would rule out sepsis.”"}, {"id": "d", "text": "“Sepsis criteria include a high or a low WBC count.”"}]'::jsonb, '["d"]', 'Sepsis diagnostic criteria include a WBC count that is either increased or decreased. A low count therefore does not rule out sepsis.'),
  ('peritonitis', 30, 'The nurse notes that a client with peritonitis has an elevated lactic acid level. The nurse recognizes that this result indicates which problem?', '[{"id": "a", "text": "Poor tissue perfusion"}, {"id": "b", "text": "Adequate tissue perfusion"}, {"id": "c", "text": "Improving kidney function"}, {"id": "d", "text": "A resolving infection"}]'::jsonb, '["a"]', 'Elevated lactic acid is an indicator of poor perfusion. It does not indicate adequate perfusion or improvement.'),
  ('peritonitis', 31, 'A client with sepsis from peritonitis has received an IV fluid bolus, but the blood pressure remains 80/46 mm Hg. Which condition does the nurse recognize?', '[{"id": "a", "text": "Early uncomplicated peritonitis"}, {"id": "b", "text": "Septic shock"}, {"id": "c", "text": "Expected response to fluids"}, {"id": "d", "text": "Resolved dehydration"}]'::jsonb, '["b"]', 'In septic shock, blood pressure stays low despite IV fluid resuscitation. Persistent hypotension after fluids is not an expected or reassuring response.'),
  ('peritonitis', 32, 'A client in septic shock remains hypotensive after IV fluid resuscitation. Which therapy should the nurse anticipate next?', '[{"id": "a", "text": "Stopping all IV fluids"}, {"id": "b", "text": "Switching to oral fluids"}, {"id": "c", "text": "Vasopressors to maintain BP"}, {"id": "d", "text": "Discontinuing antibiotics"}]'::jsonb, '["c"]', 'Septic shock requires vasopressors to maintain blood pressure when fluids do not restore it. Stopping fluids or antibiotics would worsen the condition.'),
  ('peritonitis', 33, 'A client with sepsis has completed IV fluid resuscitation. Which lactate level supports a diagnosis of septic shock?', '[{"id": "a", "text": "0.8 mmol/L"}, {"id": "b", "text": "1.2 mmol/L"}, {"id": "c", "text": "1.6 mmol/L"}, {"id": "d", "text": "3.6 mmol/L"}]'::jsonb, '["d"]', 'Septic shock includes a lactate level greater than 2 mmol/L despite fluids. The other values are below 2 mmol/L.'),
  ('peritonitis', 34, 'A client with suspected sepsis has orders for blood cultures and broad-spectrum IV antibiotics. Which action should the nurse complete before hanging the antibiotic?', '[{"id": "a", "text": "Draw the blood cultures"}, {"id": "b", "text": "Start a vasopressor infusion"}, {"id": "c", "text": "Wait for culture results"}, {"id": "d", "text": "Insert an NG tube"}]'::jsonb, '["a"]', 'Blood cultures are drawn before antibiotics. Antibiotics should start immediately, so waiting for culture results is incorrect.'),
  ('peritonitis', 35, 'Blood cultures have just been drawn for a client with suspected sepsis. When should the nurse start the prescribed broad-spectrum antibiotics?', '[{"id": "a", "text": "After the culture results return"}, {"id": "b", "text": "Immediately, within the first hour"}, {"id": "c", "text": "After the lactate level normalizes"}, {"id": "d", "text": "After vasopressors are started"}]'::jsonb, '["b"]', 'The sepsis bundle calls for broad-spectrum antibiotics to start immediately within the first hour. Waiting for culture results delays treatment.'),
  ('peritonitis', 36, 'A client with sepsis weighs 80 kg. The provider prescribes IV fluids according to the sepsis bundle. Which total volume should the nurse anticipate?', '[{"id": "a", "text": "800 mL"}, {"id": "b", "text": "1,600 mL"}, {"id": "c", "text": "2,400 mL"}, {"id": "d", "text": "3,200 mL"}]'::jsonb, '["c"]', 'The sepsis bundle calls for 30 mL/kg of NS or LR, so 30 mL × 80 kg = 2,400 mL. 1,600 mL reflects only 20 mL/kg.'),
  ('peritonitis', 37, 'A nurse is caring for a client with suspected sepsis. Which action is part of the first-hour sepsis bundle?', '[{"id": "a", "text": "Hold antibiotics until cultures result"}, {"id": "b", "text": "Hold IV fluids until the BP drops"}, {"id": "c", "text": "Start vasopressors before any fluids"}, {"id": "d", "text": "Check a lactate level"}]'::jsonb, '["d"]', 'Checking a lactate level to assess perfusion is part of the first-hour bundle. Antibiotics start immediately, and vasopressors are used only if fluids do not restore BP.'),
  ('peritonitis', 38, 'A nurse is caring for a client with suspected sepsis. Which sequence of actions is consistent with the sepsis bundle?', '[{"id": "a", "text": "Draw cultures, start antibiotics, give IV fluids, add vasopressors if BP stays low"}, {"id": "b", "text": "Start antibiotics, draw cultures, add vasopressors, then give IV fluids"}, {"id": "c", "text": "Add vasopressors, give IV fluids, draw cultures, then start antibiotics"}, {"id": "d", "text": "Give IV fluids, start antibiotics, draw cultures, add vasopressors if BP stays low"}]'::jsonb, '["a"]', 'Blood cultures are drawn before antibiotics, and vasopressors are added if fluids don''t restore BP. The other sequences give antibiotics before cultures or vasopressors before fluids.'),
  ('peritonitis', 39, 'A nurse is measuring hourly urine output for a client with sepsis. What is the primary purpose of this assessment?', '[{"id": "a", "text": "To measure NG tube drainage"}, {"id": "b", "text": "To detect free air in the abdomen"}, {"id": "c", "text": "To evaluate kidney perfusion"}, {"id": "d", "text": "To identify the infecting organism"}]'::jsonb, '["c"]', 'Urine output is monitored to evaluate kidney perfusion in sepsis. Blood cultures identify the organism, and free air is detected by X-ray or CT.'),
  ('peritonitis', 40, 'A client with peritonitis has a temperature of 101.8°F (38.8°C), a heart rate of 112 bpm, and new confusion. What is the nurse''s priority action?', '[{"id": "a", "text": "Recheck the vital signs in 4 hours"}, {"id": "b", "text": "Notify the provider STAT of suspected sepsis"}, {"id": "c", "text": "Document the findings and continue routine care"}, {"id": "d", "text": "Offer oral fluids to treat the fever"}]'::jsonb, '["b"]', 'Temperature above 38°C, heart rate above 90, and altered mental status suggest sepsis, and the provider should be notified STAT. Waiting or continuing routine care delays treatment.'),
  ('peritonitis', 41, 'A client with suspected sepsis reports shortness of breath. Which nursing action is a priority?', '[{"id": "a", "text": "Administer oxygen"}, {"id": "b", "text": "Encourage oral fluids"}, {"id": "c", "text": "Hold all IV fluids"}, {"id": "d", "text": "Reassess in 4 hours"}]'::jsonb, '["a"]', 'Administering oxygen is a nursing priority for sepsis, and airway is a key nursing priority. Holding fluids or delaying reassessment is unsafe.'),
  ('peritonitis', 42, 'A client with suspected sepsis has no IV access. Which action should the nurse take immediately?', '[{"id": "a", "text": "Wait for lactate results before inserting an IV"}, {"id": "b", "text": "Encourage the client to drink more fluids"}, {"id": "c", "text": "Delay IV insertion until surgery is scheduled"}, {"id": "d", "text": "Establish IV access and begin IV fluids"}]'::jsonb, '["d"]', 'Nursing priorities for sepsis include starting IV access and fluids immediately. Delaying for lab results or surgery postpones fluid resuscitation.'),
  ('peritonitis', 43, 'A nurse provides discharge teaching to a client who recovered from sepsis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "“I will report fever and chills to my provider right away.”"}, {"id": "b", "text": "“Treating an infection early can help prevent sepsis.”"}, {"id": "c", "text": "“I''ll wait a week to see if an infection clears on its own.”"}, {"id": "d", "text": "“I''ll call if I feel confused or short of breath.”"}]'::jsonb, '["c"]', 'Clients are taught signs of infection and the importance of early treatment, so waiting a week is unsafe. Reporting fever, chills, confusion, or shortness of breath is correct.'),
  ('peritonitis', 44, 'A client develops a postoperative abdominal infection. Which assessment cluster most suggests the infection has progressed to sepsis?', '[{"id": "a", "text": "High BP, slow heart rate, alert and oriented"}, {"id": "b", "text": "Low BP, fast heart rate, altered mental status"}, {"id": "c", "text": "Normal BP, slow heart rate, alert and oriented"}, {"id": "d", "text": "High BP, fast heart rate, alert and oriented"}]'::jsonb, '["b"]', 'Sepsis is a systemic infection causing decreased BP, increased HR, and altered mental status. High BP with a normal mental status does not fit.'),
  ('peritonitis', 45, 'A charge nurse observes a new nurse caring for a client with suspected sepsis. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Sending a lactate level to the lab"}, {"id": "b", "text": "Starting IV fluids at 30 mL/kg"}, {"id": "c", "text": "Monitoring hourly urine output"}, {"id": "d", "text": "Hanging antibiotics before drawing blood cultures"}]'::jsonb, '["d"]', 'Blood cultures must be drawn before antibiotics are given. Checking lactate, giving 30 mL/kg of IV fluids, and monitoring urine output are correct.'),
  ('peritonitis', 46, 'A client''s appendix has burst. The family asks why the client needs urgent treatment. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“Pus can leak into the abdomen and cause peritonitis.”"}, {"id": "b", "text": "“Pus stays sealed inside the appendix after it bursts.”"}, {"id": "c", "text": "“The inflammation will stay limited to the stomach lining.”"}, {"id": "d", "text": "“The infection cannot spread beyond the appendix.”"}]'::jsonb, '["a"]', 'A ruptured appendix leaks pus and is a cause of peritonitis, a life-threatening emergency. The infection is not contained inside the appendix.'),
  ('peritonitis', 47, 'A nurse is reviewing the prescribed treatment plan for a client with peritonitis. Which set of orders is consistent with standard treatment?', '[{"id": "a", "text": "Regular diet, oral antibiotics, and ambulation"}, {"id": "b", "text": "Clear liquids, oral antibiotics, and no NG tube"}, {"id": "c", "text": "NPO, IV fluids, IV antibiotics, and an NG tube"}, {"id": "d", "text": "Regular diet, IV fluids, and no antibiotics"}]'::jsonb, '["c"]', 'Peritonitis is treated with NPO status, IV fluids, broad-spectrum IV antibiotics, and an NG tube to decompress the bowel. Diets and oral antibiotics conflict with NPO status.'),
  ('peritonitis', 48, 'A nurse is comparing two clients with sepsis. Which finding distinguishes septic shock from sepsis?', '[{"id": "a", "text": "Temperature above 38°C (100.4°F)"}, {"id": "b", "text": "Hypotension that persists despite IV fluids"}, {"id": "c", "text": "Heart rate above 90 bpm"}, {"id": "d", "text": "An elevated WBC count"}]'::jsonb, '["b"]', 'Septic shock is defined by hypotension persisting despite fluids with poor organ perfusion. Fever, heart rate above 90, and WBC changes are criteria for sepsis itself.'),
  ('peritonitis', 49, 'A nurse manager is reviewing sepsis care with staff. Which focus reflects the nursing priority for clients with sepsis?', '[{"id": "a", "text": "Waiting for culture results before treating"}, {"id": "b", "text": "Encouraging oral fluids and rest at home"}, {"id": "c", "text": "Checking vital signs once per shift"}, {"id": "d", "text": "Early recognition, fluid resuscitation, and airway"}]'::jsonb, '["d"]', 'The nursing priority in sepsis is early recognition, fluid resuscitation, airway, and perfusion monitoring. Waiting for culture results delays treatment.'),
  ('peritonitis', 50, 'A client 3 days after abdominal surgery develops severe abdominal pain, fever, and a rigid, board-like abdomen. Which condition does the nurse suspect?', '[{"id": "a", "text": "Peritonitis from a postoperative infection"}, {"id": "b", "text": "Expected postoperative incisional discomfort"}, {"id": "c", "text": "A normal inflammatory healing response"}, {"id": "d", "text": "Constipation from reduced activity"}]'::jsonb, '["a"]', 'Post-op abdominal infection is a cause of peritonitis, and a rigid, board-like abdomen with severe pain and fever are its signs. These findings are not expected after surgery.'),
  ('botulism', 1, 'A client hospitalized with botulism asks the nurse what causes the illness. Which response by the nurse is accurate?', '[{"id": "a", "text": "“A virus that attacks the nerves in your spinal cord.”"}, {"id": "b", "text": "“A toxin produced by the bacterium Clostridium botulinum.”"}, {"id": "c", "text": "“An allergic reaction to a food you recently ate.”"}, {"id": "d", "text": "“A parasite that lives in undercooked meat.”"}]'::jsonb, '["b"]', 'Botulism is a paralytic illness caused by a toxin produced by Clostridium botulinum. It is not caused by a virus, allergy, or parasite.'),
  ('botulism', 2, 'A nursing student asks how the botulinum toxin causes paralysis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“It increases acetylcholine release and causes muscle spasms.”"}, {"id": "b", "text": "“It destroys muscle fibers so they can no longer contract.”"}, {"id": "c", "text": "“It inflames the brain and causes fever and confusion.”"}, {"id": "d", "text": "“It blocks acetylcholine release at the neuromuscular junction.”"}]'::jsonb, '["d"]', 'The toxin blocks acetylcholine release at neuromuscular junctions, causing flaccid paralysis. It does not increase acetylcholine release, and botulism presents without fever and with normal mental status.'),
  ('botulism', 3, 'A nurse is assessing a client admitted with botulism. Which type of paralysis should the nurse expect?', '[{"id": "a", "text": "Flaccid and descending"}, {"id": "b", "text": "Spastic and descending"}, {"id": "c", "text": "Flaccid and ascending"}, {"id": "d", "text": "Spastic and ascending"}]'::jsonb, '["a"]', 'Botulism causes flaccid, descending paralysis that starts in the cranial nerves and moves downward. Ascending or spastic paralysis does not fit.'),
  ('botulism', 4, 'The family of a client with botulism asks why the client''s muscles are so weak. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“The muscles have been damaged by a bacterial infection.”"}, {"id": "b", "text": "“The muscles are constantly contracting and become fatigued.”"}, {"id": "c", "text": "“The nerve signal never reaches the muscle to make it contract.”"}, {"id": "d", "text": "“The spinal cord is swollen and pressing on the nerves.”"}]'::jsonb, '["c"]', 'In botulism, muscles cannot contract because the nerve signal is never transmitted. The muscles are not constantly contracting; the paralysis is flaccid.'),
  ('botulism', 5, 'An adult client develops double vision and difficulty swallowing. Which item in the client''s recent diet history should most raise the nurse''s suspicion of foodborne botulism?', '[{"id": "a", "text": "Freshly grilled chicken from a restaurant"}, {"id": "b", "text": "Home-canned green beans from a relative"}, {"id": "c", "text": "Fresh apples bought at a grocery store"}, {"id": "d", "text": "A salad made with fresh garden lettuce"}]'::jsonb, '["b"]', 'Foodborne botulism comes from preformed toxin in improperly canned or preserved foods, such as home-canned vegetables. Freshly prepared foods are not the described sources.'),
  ('botulism', 6, 'A nurse is taking a history from an adult with suspected foodborne botulism. Which recently eaten food is a recognized high-risk source?', '[{"id": "a", "text": "Freshly baked bread"}, {"id": "b", "text": "Freshly steamed rice"}, {"id": "c", "text": "Homemade fermented fish"}, {"id": "d", "text": "Fresh-squeezed orange juice"}]'::jsonb, '["c"]', 'The anaerobic environment of home-canned vegetables and fermented fish allows the toxin to form. The other foods are not described as sources.'),
  ('botulism', 7, 'A client asks why botulism is linked to sealed, home-canned foods. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“The bacteria grow in places that have no oxygen.”"}, {"id": "b", "text": "“The bacteria need plenty of oxygen to grow.”"}, {"id": "c", "text": "“The bacteria grow only in foods left open to air.”"}, {"id": "d", "text": "“The bacteria grow only in honey and sweet foods.”"}]'::jsonb, '["a"]', 'Clostridium botulinum is an obligate anaerobe that needs no oxygen, so sealed, anaerobic environments such as home-canned foods support it. It does not require oxygen to grow.'),
  ('botulism', 8, 'The parent of an infant diagnosed with botulism asks how honey caused the illness. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“Honey contains an already-formed toxin that acts at once.”"}, {"id": "b", "text": "“Honey caused an allergic reaction in your baby''s nerves.”"}, {"id": "c", "text": "“The sugar in honey damaged your baby''s muscle fibers.”"}, {"id": "d", "text": "“Spores in honey grew in the intestines and released toxin.”"}]'::jsonb, '["d"]', 'In infant botulism, ingested spores (such as from honey) colonize the intestines and release toxin. Ingestion of preformed toxin describes foodborne botulism.'),
  ('botulism', 9, 'A community health nurse is preparing a presentation on botulism. Which form should the nurse identify as the most common in the United States?', '[{"id": "a", "text": "Foodborne botulism"}, {"id": "b", "text": "Infant botulism"}, {"id": "c", "text": "Wound botulism"}, {"id": "d", "text": "Iatrogenic botulism"}]'::jsonb, '["b"]', 'Infant botulism is the most common form in the US. Foodborne, wound, and iatrogenic forms are not described as most common.'),
  ('botulism', 10, 'The parent of a 9-month-old asks whether a little honey can be added to the infant''s oatmeal. Which response by the nurse is appropriate?', '[{"id": "a", "text": "“Honey should not be given to infants under 12 months.”"}, {"id": "b", "text": "“Honey is safe to give once an infant is 6 months old.”"}, {"id": "c", "text": "“Honey is safe if it is cooked into the oatmeal first.”"}, {"id": "d", "text": "“Honey is safe if you give only a very small amount.”"}]'::jsonb, '["a"]', 'Honey should never be given to infants under 12 months because it can contain spores that cause infant botulism. There is no safe age before 12 months or safe small amount.'),
  ('botulism', 11, 'A nurse in an emergency department is assessing several adults. Which client has the greatest risk for wound botulism?', '[{"id": "a", "text": "A client with a sunburn on both shoulders"}, {"id": "b", "text": "A client with a healed surgical scar"}, {"id": "c", "text": "A client who injects drugs and has an injection-site wound"}, {"id": "d", "text": "A client with a superficial paper cut"}]'::jsonb, '["c"]', 'Wound botulism occurs when spores enter a puncture wound or IV drug use site. IV drug users are a high-yield risk group.'),
  ('botulism', 12, 'A client is diagnosed with wound botulism. Which antimicrobial therapy should the nurse anticipate?', '[{"id": "a", "text": "An aminoglycoside antibiotic"}, {"id": "b", "text": "No antimicrobial therapy"}, {"id": "c", "text": "An oral antifungal medication"}, {"id": "d", "text": "IV penicillin or metronidazole"}]'::jsonb, '["d"]', 'Wound botulism is treated with IV penicillin or metronidazole. Aminoglycosides are avoided because they worsen neuromuscular blockade.'),
  ('botulism', 13, 'A nurse is monitoring a client with botulism for progression of paralysis. In which order does the nurse expect the paralysis to progress?', '[{"id": "a", "text": "Legs, arms, face, then diaphragm"}, {"id": "b", "text": "Face, arms, legs, then diaphragm"}, {"id": "c", "text": "Diaphragm, legs, arms, then face"}, {"id": "d", "text": "Arms, face, diaphragm, then legs"}]'::jsonb, '["b"]', 'Paralysis starts in the cranial nerves (face, eyes, throat) and progresses to the arms, legs, and diaphragm. Starting in the legs describes ascending, not descending, paralysis.'),
  ('botulism', 14, 'An adult client who ate home-canned food 1 day ago is being assessed for early botulism. Where should the nurse expect weakness to appear first?', '[{"id": "a", "text": "Face, eyes, and throat"}, {"id": "b", "text": "Legs and feet"}, {"id": "c", "text": "Diaphragm"}, {"id": "d", "text": "Arms and hands"}]'::jsonb, '["a"]', 'Botulism paralysis starts in the cranial nerves affecting the face, eyes, and throat. The diaphragm is involved late in the progression.'),
  ('botulism', 15, 'The family of a client with botulism asks why the nurse checks the client''s breathing so often. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“The toxin causes a high fever that speeds up breathing.”"}, {"id": "b", "text": "“The infection spreads first to the lungs and causes pneumonia.”"}, {"id": "c", "text": "“The paralysis can reach the diaphragm and cause respiratory failure.”"}, {"id": "d", "text": "“Breathing is checked only because of the medications given.”"}]'::jsonb, '["c"]', 'Descending paralysis can progress to the diaphragm, causing respiratory failure. Botulism does not cause fever.'),
  ('botulism', 16, 'A nurse is caring for a client with new cranial nerve weakness. Which pair of findings helps distinguish botulism from other neurological infections?', '[{"id": "a", "text": "High fever and confusion"}, {"id": "b", "text": "High fever and an alert mental status"}, {"id": "c", "text": "No fever and confusion"}, {"id": "d", "text": "No fever and a normal mental status"}]'::jsonb, '["d"]', 'No fever and normal mental status distinguish botulism from other neurological infections. Fever or confusion would point away from botulism.'),
  ('botulism', 17, 'A nurse is assessing an adult with suspected foodborne botulism. Which findings should the nurse expect?', '[{"id": "a", "text": "Double vision and drooping eyelids"}, {"id": "b", "text": "High fever and confusion"}, {"id": "c", "text": "Stiff, spastic leg muscles"}, {"id": "d", "text": "Weakness rising from the feet"}]'::jsonb, '["a"]', 'Adults with botulism develop diplopia (double vision) and ptosis (drooping eyelids). Fever, confusion, spasticity, and ascending weakness do not fit.'),
  ('botulism', 18, 'An adult client with botulism has slurred speech and difficulty swallowing. How should the nurse document these findings?', '[{"id": "a", "text": "Diplopia and ptosis"}, {"id": "b", "text": "Dysarthria and dysphagia"}, {"id": "c", "text": "Dysphagia and diplopia"}, {"id": "d", "text": "Ptosis and dysarthria"}]'::jsonb, '["b"]', 'Dysarthria is slurred speech and dysphagia is difficulty swallowing. Diplopia is double vision and ptosis is drooping eyelids.'),
  ('botulism', 19, 'A nurse is assessing the oral cavity of an adult with botulism. Which finding should the nurse expect?', '[{"id": "a", "text": "Excessive drooling"}, {"id": "b", "text": "Bleeding gums"}, {"id": "c", "text": "Dry mouth"}, {"id": "d", "text": "Swollen tongue"}]'::jsonb, '["c"]', 'Dry mouth is a clinical manifestation of botulism in adults. Excessive drooling is not described.'),
  ('botulism', 20, 'An adult with ptosis and dysphagia from suspected botulism is alert and oriented. How should the nurse interpret the client''s mental status?', '[{"id": "a", "text": "It rules out botulism"}, {"id": "b", "text": "It shows the toxin has cleared"}, {"id": "c", "text": "It means breathing checks can stop"}, {"id": "d", "text": "It is expected in botulism"}]'::jsonb, '["d"]', 'Adults with botulism have no fever and an alert mental status. A normal mental status does not rule out the disease or remove the need for respiratory monitoring.'),
  ('botulism', 21, 'The parent of a 3-month-old asks what the earliest sign of infant botulism usually is. Which response by the nurse is accurate?', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Weak cry"}, {"id": "c", "text": "Loss of head control"}, {"id": "d", "text": "Lethargy"}]'::jsonb, '["a"]', 'Constipation is the first sign of infant botulism. Weak cry, lethargy, and loss of head control develop as the illness progresses.'),
  ('botulism', 22, 'A 4-month-old is brought to the clinic because the infant seems “floppy,” is feeding poorly, and has a weak cry. Which condition should the nurse suspect?', '[{"id": "a", "text": "A normal growth spurt"}, {"id": "b", "text": "Infant botulism"}, {"id": "c", "text": "Normal sleepiness"}, {"id": "d", "text": "Teething discomfort"}]'::jsonb, '["b"]', 'A floppy infant with poor feeding and a weak cry is an emergency and botulism should be suspected. These findings are not normal.'),
  ('botulism', 23, 'A 3-month-old is brought to the emergency department with constipation, a weak cry, and poor feeding. Which question should the nurse ask the parent?', '[{"id": "a", "text": "“Has the baby had a high fever?”"}, {"id": "b", "text": "“Has the baby been around sick children?”"}, {"id": "c", "text": "“Has the baby consumed honey?”"}, {"id": "d", "text": "“Has the baby had frequent diarrhea?”"}]'::jsonb, '["c"]', 'Constipation, weak cry, and poor feeding suggest infant botulism, so the nurse should ask about honey exposure. Botulism presents without fever.'),
  ('botulism', 24, 'A nurse is assessing an infant with suspected botulism. Which findings are consistent with this diagnosis?', '[{"id": "a", "text": "Strong cry and stiff limbs"}, {"id": "b", "text": "Vigorous feeding and high tone"}, {"id": "c", "text": "Loud cry and rigid posture"}, {"id": "d", "text": "Weak cry and reduced muscle tone"}]'::jsonb, '["d"]', 'Infant botulism (“floppy baby syndrome”) causes a weak cry and generalized hypotonia. Stiff or rigid muscles with a strong cry do not fit.'),
  ('botulism', 25, 'The provider prescribes antitoxin for a client with suspected botulism based on symptoms and exposure history. Serum toxin results are still pending. What should the nurse do?', '[{"id": "a", "text": "Give the antitoxin as prescribed"}, {"id": "b", "text": "Hold it until toxin results return"}, {"id": "c", "text": "Hold it until a stool culture returns"}, {"id": "d", "text": "Ask to repeat the exam tomorrow"}]'::jsonb, '["a"]', 'Antitoxin should not be delayed while waiting for lab confirmation. Holding it for serum or stool results delays treatment.'),
  ('botulism', 26, 'A nurse is collecting specimens for an adult with suspected foodborne botulism. Which samples can confirm the diagnosis by detecting the toxin?', '[{"id": "a", "text": "Throat swab or sputum"}, {"id": "b", "text": "Serum, stool, or food"}, {"id": "c", "text": "Urine or skin scraping"}, {"id": "d", "text": "Sputum or urine"}]'::jsonb, '["b"]', 'Botulism is confirmed by detecting toxin in serum, stool, or food samples. Throat, sputum, urine, and skin samples are not described.'),
  ('botulism', 27, 'An infant is admitted with suspected botulism. Which diagnostic test does the nurse anticipate for this infant?', '[{"id": "a", "text": "Throat culture for bacteria"}, {"id": "b", "text": "Urine test for toxin"}, {"id": "c", "text": "Stool culture for spores"}, {"id": "d", "text": "Skin swab for spores"}]'::jsonb, '["c"]', 'Infant botulism is diagnosed with a stool culture for C. botulinum spores, since infants ingest spores that colonize the intestines.'),
  ('botulism', 28, 'A client with suspected botulism asks how treatment can start before test results are available. Which response by the nurse is accurate?', '[{"id": "a", "text": "“Treatment is started only after the toxin is found in your blood.”"}, {"id": "b", "text": "“Treatment is started once a fever confirms the diagnosis.”"}, {"id": "c", "text": "“Treatment is started only after a food sample is tested.”"}, {"id": "d", "text": "“Your symptoms and exposure history are often enough to start.”"}]'::jsonb, '["d"]', 'Clinical signs plus exposure history are often sufficient to start treatment, and antitoxin should not be delayed for lab confirmation. Botulism does not cause fever.'),
  ('botulism', 29, 'A 40-year-old client is diagnosed with foodborne botulism. Which antitoxin should the nurse anticipate administering?', '[{"id": "a", "text": "Heptavalent Botulinum Antitoxin (HBAT)"}, {"id": "b", "text": "Botulism Immune Globulin (BabyBIG)"}, {"id": "c", "text": "An aminoglycoside antibiotic"}, {"id": "d", "text": "Oral metronidazole tablets"}]'::jsonb, '["a"]', 'HBAT is the antitoxin for adults and older children. BabyBIG is used for infants, and aminoglycosides are avoided.'),
  ('botulism', 30, 'A 5-month-old is diagnosed with infant botulism. Which antitoxin should the nurse anticipate?', '[{"id": "a", "text": "Heptavalent Botulinum Antitoxin (HBAT)"}, {"id": "b", "text": "Botulism Immune Globulin (BabyBIG)"}, {"id": "c", "text": "An aminoglycoside antibiotic"}, {"id": "d", "text": "IV penicillin infusion"}]'::jsonb, '["b"]', 'Infants receive Botulism Immune Globulin (BabyBIG). HBAT is for adults and older children.'),
  ('botulism', 31, 'A nurse is reviewing botulism antitoxins with a nursing student. Which statement by the student requires correction?', '[{"id": "a", "text": "“HBAT is used for adults and older children.”"}, {"id": "b", "text": "“BabyBIG is used for infants with botulism.”"}, {"id": "c", "text": "“BabyBIG is used for adults with foodborne illness.”"}, {"id": "d", "text": "“Antitoxin should not wait for lab confirmation.”"}]'::jsonb, '["c"]', 'BabyBIG is for infants, while adults and older children receive HBAT. The other statements are correct.'),
  ('botulism', 32, 'A nurse is caring for an adult admitted with botulism. Which assessment is the nurse''s highest priority?', '[{"id": "a", "text": "Bowel sounds"}, {"id": "b", "text": "Pupil size"}, {"id": "c", "text": "Skin integrity"}, {"id": "d", "text": "Respiratory status"}]'::jsonb, '["d"]', 'Respiratory status is the number one priority, including monitoring oxygen and ABGs and preparing for intubation, because diaphragm paralysis causes respiratory failure.'),
  ('botulism', 33, 'A client with botulism has weakening respiratory effort and worsening ABGs. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Intubation and mechanical ventilation"}, {"id": "b", "text": "Insertion of an NG tube for feeding"}, {"id": "c", "text": "Administration of an aminoglycoside"}, {"id": "d", "text": "Waiting for toxin lab confirmation"}]'::jsonb, '["a"]', 'Mechanical ventilation for respiratory failure is the number one priority in supportive care. Nutrition is important but secondary to the airway, and aminoglycosides are avoided.'),
  ('botulism', 34, 'An adult develops ptosis and diplopia 1 week after stepping on a nail that caused a deep puncture wound. The client has eaten no home-canned foods. Which form of botulism is most likely?', '[{"id": "a", "text": "Foodborne botulism"}, {"id": "b", "text": "Infant botulism"}, {"id": "c", "text": "Wound botulism"}, {"id": "d", "text": "Iatrogenic botulism"}]'::jsonb, '["c"]', 'Wound botulism occurs when spores enter a puncture wound or IV drug use site. Foodborne botulism requires eating preformed toxin in improperly canned or preserved foods.'),
  ('botulism', 35, 'An adult with botulism has severe dysphagia. Which method of nutritional support should the nurse anticipate?', '[{"id": "a", "text": "Regular diet by mouth"}, {"id": "b", "text": "Thin liquids by mouth"}, {"id": "c", "text": "NG tube feeding or TPN"}, {"id": "d", "text": "No nutrition until recovery"}]'::jsonb, '["c"]', 'Supportive care includes nutritional support by NG tube or TPN. Oral intake is unsafe with severe dysphagia.'),
  ('botulism', 36, 'A nurse reviews the prescriptions for a client with wound botulism. Which prescription should the nurse question?', '[{"id": "a", "text": "IV penicillin"}, {"id": "b", "text": "IV metronidazole"}, {"id": "c", "text": "HBAT antitoxin"}, {"id": "d", "text": "An aminoglycoside"}]'::jsonb, '["d"]', 'Aminoglycosides should be avoided because they worsen neuromuscular blockade. IV penicillin or metronidazole and HBAT are appropriate.'),
  ('botulism', 37, 'A nursing student asks why aminoglycosides are avoided in clients with botulism. Which response by the nurse is accurate?', '[{"id": "a", "text": "“They worsen the neuromuscular blockade.”"}, {"id": "b", "text": "“They make the antitoxin stop working.”"}, {"id": "c", "text": "“They cause a high fever in these clients.”"}, {"id": "d", "text": "“They cause the spores to multiply faster.”"}]'::jsonb, '["a"]', 'Aminoglycosides worsen neuromuscular blockade and are avoided. The concern is added paralysis, not fever or antitoxin failure.'),
  ('botulism', 38, 'A nurse teaches a client who home-cans vegetables how to prevent botulism. Which client statement indicates understanding?', '[{"id": "a", "text": "“I will taste the food first to make sure it is safe.”"}, {"id": "b", "text": "“I will boil my home-canned foods before eating them.”"}, {"id": "c", "text": "“I will store the cans in the refrigerator overnight.”"}, {"id": "d", "text": "“I will add honey to the jars to preserve the food.”"}]'::jsonb, '["b"]', 'Boiling home-canned foods before eating is a prevention measure. Tasting the food does not make it safe.'),
  ('botulism', 39, 'A client asks the nurse what boiling home-canned food does to prevent botulism. Which response by the nurse is accurate?', '[{"id": "a", "text": "“Boiling kills the spores but not the toxin.”"}, {"id": "b", "text": "“Boiling has no effect on the toxin or spores.”"}, {"id": "c", "text": "“Boiling destroys the toxin but not the spores.”"}, {"id": "d", "text": "“Boiling only works if honey is added first.”"}]'::jsonb, '["c"]', 'Boiling home-canned foods kills the toxin but not the spores. Stating that it kills spores but not toxin reverses the fact.'),
  ('botulism', 40, 'A nurse is teaching a client who injects drugs how to reduce the risk of wound botulism. Which instruction is most appropriate?', '[{"id": "a", "text": "“Boil your food before eating.”"}, {"id": "b", "text": "“Avoid eating honey at all.”"}, {"id": "c", "text": "“Avoid eating fermented fish.”"}, {"id": "d", "text": "“Use sterile injection technique.”"}]'::jsonb, '["d"]', 'Proper wound care and sterile injection techniques prevent wound botulism, which occurs when spores enter an IV drug use site. The other measures address foodborne or infant botulism.'),
  ('botulism', 41, 'A nurse provides teaching to the parent of a 6-month-old about infant botulism. Which parent statement indicates a need for further teaching?', '[{"id": "a", "text": "“I can dip my baby''s pacifier in a little honey.”"}, {"id": "b", "text": "“I''ll call if my baby is constipated and feeding poorly.”"}, {"id": "c", "text": "“Honey can be given after my baby''s first birthday.”"}, {"id": "d", "text": "“I''ll report it if my baby''s cry becomes weak.”"}]'::jsonb, '["a"]', 'Honey should never be given to infants under 12 months, so a honey-dipped pacifier is unsafe. Reporting constipation, poor feeding, and a weak cry is correct.'),
  ('botulism', 42, 'An afebrile, alert adult has new ptosis and diplopia. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "Botulism is unlikely because the client is alert"}, {"id": "b", "text": "Botulism is suspected because cranial nerves are affected without fever"}, {"id": "c", "text": "Botulism is ruled out because there is no fever"}, {"id": "d", "text": "Infection is unlikely because mental status is normal"}]'::jsonb, '["b"]', 'Cranial nerve dysfunction with no fever should raise suspicion of botulism, which presents with an alert mental status. Absence of fever does not rule it out.'),
  ('botulism', 43, 'A nurse is assessing a 2-month-old infant with suspected botulism. Which additional findings should the nurse expect?', '[{"id": "a", "text": "Strong, vigorous cry"}, {"id": "b", "text": "Active, frequent kicking"}, {"id": "c", "text": "Lethargy and poor head control"}, {"id": "d", "text": "Steady head control"}]'::jsonb, '["c"]', 'Infant botulism causes lethargy and loss of head control along with hypotonia. Vigorous activity and steady head control do not fit.'),
  ('botulism', 44, 'A nurse is teaching a nursing student about forms of botulism. Which statement by the student correctly distinguishes foodborne from infant botulism?', '[{"id": "a", "text": "“Foodborne involves spores; infant involves preformed toxin.”"}, {"id": "b", "text": "“Both forms require spores to enter a puncture wound.”"}, {"id": "c", "text": "“Infant botulism occurs only from home-canned vegetables.”"}, {"id": "d", "text": "“Foodborne involves preformed toxin; infant involves spores.”"}]'::jsonb, '["d"]', 'Foodborne botulism is ingestion of preformed toxin in improperly canned or preserved foods, while infant botulism is ingestion of spores that colonize the intestines. The first option reverses these.'),
  ('botulism', 45, 'A charge nurse observes care of an infant with suspected botulism. Which action by the staff nurse requires correction?', '[{"id": "a", "text": "Holding BabyBIG until the stool culture results return"}, {"id": "b", "text": "Monitoring the infant''s oxygen saturation closely"}, {"id": "c", "text": "Asking the parents about honey exposure"}, {"id": "d", "text": "Providing nutrition through an NG tube"}]'::jsonb, '["a"]', 'Antitoxin should not be delayed for lab confirmation. Monitoring oxygenation, asking about honey, and NG nutrition are appropriate.'),
  ('botulism', 46, 'A nurse observes drooping of both upper eyelids in a client with suspected botulism. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Diplopia"}, {"id": "b", "text": "Ptosis"}, {"id": "c", "text": "Dysarthria"}, {"id": "d", "text": "Dysphagia"}]'::jsonb, '["b"]', 'Ptosis is drooping eyelids. Diplopia is double vision, dysarthria is slurred speech, and dysphagia is difficulty swallowing.'),
  ('botulism', 47, 'An adult presents with diplopia and difficulty swallowing but no fever. Which question is most relevant for the nurse to ask?', '[{"id": "a", "text": "“Have you had any seasonal allergies?”"}, {"id": "b", "text": "“Have you had a recent head injury?”"}, {"id": "c", "text": "“Have you eaten home-canned foods lately?”"}, {"id": "d", "text": "“Have you started a new exercise routine?”"}]'::jsonb, '["c"]', 'Cranial nerve symptoms without fever suggest botulism, and exposure history such as home-canned foods supports the diagnosis. The other questions do not address a botulism source.'),
  ('botulism', 48, 'A nurse is supervising an assistive personnel (AP) caring for an adult with botulism and dysphagia. Which action by the AP requires the nurse to intervene?', '[{"id": "a", "text": "Reporting a drop in oxygen saturation"}, {"id": "b", "text": "Positioning the client with the head raised"}, {"id": "c", "text": "Recording the client''s vital signs"}, {"id": "d", "text": "Offering the client a glass of water"}]'::jsonb, '["d"]', 'Dysphagia (difficulty swallowing) makes oral fluids unsafe, and nutrition is given by NG tube or TPN. Reporting a drop in oxygen saturation supports the respiratory priority.'),
  ('botulism', 49, 'A nurse teaches a community group about botulism. Which participant statement indicates correct understanding?', '[{"id": "a", "text": "“It is a rare but serious illness that causes paralysis.”"}, {"id": "b", "text": "“It is a common, mild stomach illness that passes quickly.”"}, {"id": "c", "text": "“It usually causes a high fever and confusion.”"}, {"id": "d", "text": "“It causes paralysis that starts in the legs.”"}]'::jsonb, '["a"]', 'Botulism is a rare but serious paralytic illness with descending paralysis, no fever, and normal mental status. It is not mild, and paralysis does not start in the legs.'),
  ('botulism', 50, 'An adult with botulism had weakness that began in the face and has now spread to the arms and legs. Which assessment is most important for the nurse to perform next?', '[{"id": "a", "text": "Checking the bowel sounds"}, {"id": "b", "text": "Assessing breathing and oxygenation"}, {"id": "c", "text": "Testing hand grip strength"}, {"id": "d", "text": "Inspecting the skin for breakdown"}]'::jsonb, '["b"]', 'Paralysis progresses from the face to the arms, legs, and then the diaphragm, causing respiratory failure. Respiratory status, including oxygen and ABGs, is the number one priority.'),
  ('pyloric', 1, 'A parent brings a 4-week-old infant to the clinic for repeated vomiting. Which description by the parent is most consistent with pyloric stenosis?', '[{"id": "a", "text": "\"He vomits green fluid after most of his feedings.\""}, {"id": "b", "text": "\"He vomits forcefully after feedings, and it is never green.\""}, {"id": "c", "text": "\"He refuses his bottle and seems uninterested in eating.\""}, {"id": "d", "text": "\"He brings up a small dribble of milk when he burps.\""}]'::jsonb, '["b"]', 'Projectile, non-bilious vomiting after feeding is the hallmark of pyloric stenosis. Green (bilious) vomiting does not fit, and these infants feed eagerly rather than refusing feedings.'),
  ('pyloric', 2, 'The nurse is palpating the abdomen of a 5-week-old infant with suspected pyloric stenosis. Which finding does the nurse expect?', '[{"id": "a", "text": "An olive-shaped mass in the right upper quadrant"}, {"id": "b", "text": "An olive-shaped mass in the left lower quadrant"}, {"id": "c", "text": "A sausage-shaped mass in the left upper quadrant"}, {"id": "d", "text": "A soft abdomen with no palpable mass anywhere"}]'::jsonb, '["a"]', 'An olive-shaped mass in the right upper quadrant is a classic physical finding of pyloric stenosis. The left-sided locations and a mass-free abdomen do not match the classic presentation.'),
  ('pyloric', 3, 'Which combination of physical examination findings supports a diagnosis of pyloric stenosis in a 3-week-old infant?', '[{"id": "a", "text": "Olive-shaped mass in the left upper quadrant and absent peristalsis"}, {"id": "b", "text": "Olive-shaped mass in the right upper quadrant and a bulging fontanelle"}, {"id": "c", "text": "Olive-shaped mass in the right upper quadrant and visible peristalsis"}, {"id": "d", "text": "Visible peristalsis and bright green vomitus after each feeding"}]'::jsonb, '["c"]', 'The physical exam in pyloric stenosis shows an olive-shaped right upper quadrant mass with visible peristalsis. A bulging fontanelle and green vomitus are not expected; the fontanelle is sunken from dehydration and the vomitus is non-bilious.'),
  ('pyloric', 4, 'The parent of a 6-week-old infant with forceful vomiting states, "He cries to be fed again right after he throws up." How should the nurse interpret this behavior?', '[{"id": "a", "text": "It shows the obstruction has started to resolve."}, {"id": "b", "text": "It means the infant is being overfed at each feeding."}, {"id": "c", "text": "It indicates that the infant''s hydration is improving."}, {"id": "d", "text": "It is the constant hunger expected with pyloric stenosis."}]'::jsonb, '["d"]', 'Infants with pyloric stenosis remain constantly hungry and feed eagerly despite vomiting. The hunger does not indicate that the obstruction is resolving; food still cannot pass from the stomach into the small intestine.'),
  ('pyloric', 5, 'A 6-week-old infant has had projectile vomiting for several days. Which assessment finding indicates that the infant is dehydrated?', '[{"id": "a", "text": "Bulging anterior fontanelle"}, {"id": "b", "text": "Sunken anterior fontanelle"}, {"id": "c", "text": "Increased number of wet diapers"}, {"id": "d", "text": "Weight gain since the last visit"}]'::jsonb, '["b"]', 'A sunken fontanelle is a systemic sign of dehydration in pyloric stenosis. Dehydration causes decreased urine output and weight loss, not more wet diapers or weight gain.'),
  ('pyloric', 6, 'The nurse reviews the laboratory results of an infant admitted with pyloric stenosis. Which pattern of findings does the nurse expect?', '[{"id": "a", "text": "High potassium, low chloride, metabolic alkalosis"}, {"id": "b", "text": "Low potassium, high chloride, metabolic acidosis"}, {"id": "c", "text": "High potassium, high chloride, metabolic acidosis"}, {"id": "d", "text": "Low potassium, low chloride, metabolic alkalosis"}]'::jsonb, '["d"]', 'The classic triad in pyloric stenosis is hypokalemia, hypochloremia, and metabolic alkalosis. Options with high potassium, high chloride, or acidosis reverse these findings.'),
  ('pyloric', 7, 'A nursing student asks why an infant with pyloric stenosis develops metabolic alkalosis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Bicarbonate is lost when the infant vomits bile."}, {"id": "b", "text": "Acid is retained in the blocked stomach."}, {"id": "c", "text": "Loss of HCl in vomit lets bicarbonate accumulate."}, {"id": "d", "text": "Eager feeding adds too much base to the blood."}]'::jsonb, '["c"]', 'Vomiting causes loss of HCl, so excess bicarbonate (base) accumulates, producing metabolic alkalosis. The acid is lost in vomit rather than retained, and the vomitus is non-bilious.'),
  ('pyloric', 8, 'The parent of an infant with pyloric stenosis asks why the baby''s chloride level is low. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Stomach acid, which contains chloride, is lost when he vomits.\""}, {"id": "b", "text": "\"Chloride is lost because his vomit contains a lot of bile.\""}, {"id": "c", "text": "\"Chloride is low because his kidneys are holding on to it.\""}, {"id": "d", "text": "\"Chloride is low because he is not hungry enough to feed.\""}]'::jsonb, '["a"]', 'Hypochloremia occurs because HCl is lost in the gastric vomit. The vomitus is non-bilious, and infants with pyloric stenosis are constantly hungry.'),
  ('pyloric', 9, 'An infant with pyloric stenosis has an elevated hematocrit and an elevated BUN. How should the nurse interpret these results?', '[{"id": "a", "text": "They indicate bleeding from the stomach lining."}, {"id": "b", "text": "They reflect hemoconcentration from dehydration."}, {"id": "c", "text": "They show that the infant is fluid overloaded."}, {"id": "d", "text": "They confirm that the alkalosis has been corrected."}]'::jsonb, '["b"]', 'Elevated hematocrit and BUN reflect hemoconcentration caused by dehydration. They point to fluid deficit, not fluid overload, and they do not measure acid-base correction.'),
  ('pyloric', 10, 'A 5-week-old infant presents with projectile vomiting and a palpable mass in the right upper quadrant. Which diagnostic test does the nurse anticipate first to confirm the diagnosis?', '[{"id": "a", "text": "Upper endoscopy"}, {"id": "b", "text": "Rectal suction biopsy"}, {"id": "c", "text": "Abdominal ultrasound"}, {"id": "d", "text": "Barium contrast enema"}]'::jsonb, '["c"]', 'Abdominal ultrasound is the first-line test and confirms pyloric thickening. It is the gold standard diagnostic tool for pyloric stenosis, so the other tests are not anticipated first.'),
  ('pyloric', 11, 'An infant with pyloric stenosis is admitted with dehydration and metabolic alkalosis, and surgery is planned. Which action is the nurse''s priority?', '[{"id": "a", "text": "Keep the infant NPO and start the prescribed IV fluids."}, {"id": "b", "text": "Offer small oral feedings of an electrolyte solution."}, {"id": "c", "text": "Transfer the infant to surgery as quickly as possible."}, {"id": "d", "text": "Resume formula feedings to replace the weight lost."}]'::jsonb, '["a"]', 'Pre-operative stabilization comes first: NPO with IV fluids to correct dehydration and electrolyte imbalances. Rushing to surgery before correction is dangerous, and oral feedings are not given while NPO.'),
  ('pyloric', 12, 'An infant is scheduled for a pyloromyotomy this morning. Which finding should the nurse report to the surgeon before the infant is taken to the operating room?', '[{"id": "a", "text": "The infant has remained NPO since admission."}, {"id": "b", "text": "The IV fluids are infusing at the prescribed rate."}, {"id": "c", "text": "The NG tube is in place and draining as expected."}, {"id": "d", "text": "The latest blood gas still shows metabolic alkalosis."}]'::jsonb, '["d"]', 'Electrolytes and metabolic alkalosis must be corrected before surgery because operating on an alkalotic infant is dangerous. NPO status, infusing IV fluids, and a draining NG tube are expected pre-operative measures.'),
  ('pyloric', 13, 'The parent of an infant newly diagnosed with pyloric stenosis asks, "Why can''t they operate right now?" Which response by the nurse is best?', '[{"id": "a", "text": "\"The surgeon wants to see if the muscle thins out first.\""}, {"id": "b", "text": "\"His fluids and electrolytes must be corrected first.\""}, {"id": "c", "text": "\"He needs to gain back the weight he has lost first.\""}, {"id": "d", "text": "\"He must show he can keep down feedings first.\""}]'::jsonb, '["b"]', 'Correcting dehydration, potassium, chloride, and metabolic alkalosis comes before surgery because operating on an alkalotic infant is dangerous. The infant stays NPO, so tolerating feedings or gaining weight is not a pre-operative goal.'),
  ('pyloric', 14, 'A nasogastric (NG) tube is inserted in an infant with pyloric stenosis who is awaiting surgery. The nurse explains that the main purpose of the tube is to:', '[{"id": "a", "text": "provide formula feedings until surgery."}, {"id": "b", "text": "give potassium replacement by mouth."}, {"id": "c", "text": "decompress the stomach to prevent aspiration."}, {"id": "d", "text": "collect bile samples for laboratory testing."}]'::jsonb, '["c"]', 'Before surgery, the NG tube is used for decompression, which prevents aspiration. The infant is NPO, so the tube is not used for feedings.'),
  ('pyloric', 15, 'The nurse is supervising a nursing student caring for an infant with pyloric stenosis who is awaiting surgery. Which action by the student requires correction?', '[{"id": "a", "text": "Checking the IV site for proper infusion"}, {"id": "b", "text": "Recording the infant''s urine output"}, {"id": "c", "text": "Reviewing the latest electrolyte results"}, {"id": "d", "text": "Offering a bottle because the infant is hungry"}]'::jsonb, '["d"]', 'Pre-operative stabilization includes keeping the infant NPO, so offering a bottle is unsafe even though these infants are constantly hungry. Monitoring IV fluids, output, and electrolytes is appropriate care.'),
  ('pyloric', 16, 'The nurse is teaching the parents of an infant scheduled for a pyloromyotomy. Which statement by a parent indicates understanding of the procedure?', '[{"id": "a", "text": "\"The thickened muscle will be cut lengthwise to open the outlet.\""}, {"id": "b", "text": "\"Part of his stomach will be removed along with the pylorus.\""}, {"id": "c", "text": "\"The thickened muscle will be cut out and thrown away.\""}, {"id": "d", "text": "\"A tube will be placed to bypass the blocked stomach outlet.\""}]'::jsonb, '["a"]', 'Pyloromyotomy cuts the thickened pyloric muscle lengthwise, relieving the obstruction without removing tissue. Statements describing removal of stomach or muscle tissue are incorrect.'),
  ('pyloric', 17, 'The nurse reviews the Ramstedt procedure with the parents of a 4-week-old infant. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"This surgery should relieve the blockage.\""}, {"id": "b", "text": "\"They will cut the muscle that is too thick.\""}, {"id": "c", "text": "\"They will remove the thick piece of muscle.\""}, {"id": "d", "text": "\"The cut is made along the length of the muscle.\""}]'::jsonb, '["c"]', 'The pyloromyotomy (Ramstedt procedure) relieves the obstruction without removing tissue, so a statement about removing muscle needs correction. The other statements correctly describe a lengthwise cut that relieves the obstruction.'),
  ('pyloric', 18, 'An infant has just returned from a pyloromyotomy, and feedings have been prescribed. Which feeding plan is appropriate?', '[{"id": "a", "text": "Offer full-volume feedings as soon as the infant awakens."}, {"id": "b", "text": "Start with small volumes and increase them slowly."}, {"id": "c", "text": "Keep the infant NPO until the day of discharge."}, {"id": "d", "text": "Give large feedings spaced farther apart."}]'::jsonb, '["b"]', 'Post-operative care includes gradual refeeding, starting with small volumes and increasing slowly. Full-volume or large feedings skip this gradual approach.'),
  ('pyloric', 19, 'Several hours after a pyloromyotomy, an infant vomits a small amount after the first feeding. How should the nurse interpret this finding?', '[{"id": "a", "text": "The surgery has failed to relieve the obstruction."}, {"id": "b", "text": "The incision has most likely become infected."}, {"id": "c", "text": "The infant needs to return to surgery right away."}, {"id": "d", "text": "Some vomiting is expected after this surgery."}]'::jsonb, '["d"]', 'Some vomiting after pyloromyotomy is normal because of residual swelling. It is persistent vomiting, not a single small emesis, that may indicate an incomplete pyloromyotomy.'),
  ('pyloric', 20, 'The nurse is caring for an infant after a pyloromyotomy. Which finding should the nurse report to the surgeon?', '[{"id": "a", "text": "Persistent vomiting after every feeding"}, {"id": "b", "text": "One small emesis after the first feeding"}, {"id": "c", "text": "Eager intake of small, frequent feedings"}, {"id": "d", "text": "An incision that is clean and dry"}]'::jsonb, '["a"]', 'Persistent vomiting after surgery may indicate an incomplete pyloromyotomy and should be reported. A single small emesis is expected because some post-op vomiting is normal.'),
  ('pyloric', 21, 'An infant continues to vomit after every feeding for several days after a pyloromyotomy. The nurse recognizes that this may indicate:', '[{"id": "a", "text": "feeding volumes that are too small."}, {"id": "b", "text": "normal residual swelling at the site."}, {"id": "c", "text": "an incomplete pyloromyotomy."}, {"id": "d", "text": "metabolic alkalosis caused by surgery."}]'::jsonb, '["c"]', 'Persistent post-operative vomiting may indicate an incomplete pyloromyotomy. Residual swelling explains only some vomiting, not vomiting that persists after every feeding.'),
  ('pyloric', 22, 'Which nursing action is part of routine post-operative care for an infant after a pyloromyotomy?', '[{"id": "a", "text": "Keep the infant NPO for the first week."}, {"id": "b", "text": "Monitor the incision for signs of infection."}, {"id": "c", "text": "Stop all feedings if any vomiting occurs."}, {"id": "d", "text": "Begin full-strength feedings immediately."}]'::jsonb, '["b"]', 'Post-operative care includes monitoring the incision site for signs of infection. Feedings are restarted gradually, and some vomiting is normal, so stopping feedings for any vomiting is not indicated.'),
  ('pyloric', 23, 'Four children are brought to the emergency department with forceful vomiting after meals. Which child''s age is most consistent with pyloric stenosis?', '[{"id": "a", "text": "A 9-month-old infant"}, {"id": "b", "text": "A 4-year-old child"}, {"id": "c", "text": "A 15-year-old adolescent"}, {"id": "d", "text": "A 3-week-old infant"}]'::jsonb, '["d"]', 'Pyloric stenosis affects infants 2 to 8 weeks old, so the 3-week-old fits. Older children and teenagers are not the typical age group.'),
  ('pyloric', 24, 'A nursing student asks why the vomit of an infant with pyloric stenosis is not green. Which explanation by the nurse is correct?', '[{"id": "a", "text": "The obstruction is above the ampulla of Vater, so bile cannot mix in."}, {"id": "b", "text": "The obstruction is below the ampulla of Vater, so bile is held back."}, {"id": "c", "text": "The obstruction is in the large intestine, far from where bile enters."}, {"id": "d", "text": "The infant''s eager feeding dilutes the bile so it cannot be seen."}]'::jsonb, '["a"]', 'Non-bilious vomiting means the obstruction is above the ampulla of Vater, so bile cannot mix in yet. An obstruction below that point would allow bile to mix into the vomitus.'),
  ('pyloric', 25, 'The parent of a 5-week-old infant asks the nurse what pyloric stenosis is. Which response is most accurate?', '[{"id": "a", "text": "\"Part of the intestine slides into the part next to it.\""}, {"id": "b", "text": "\"Nerve cells are missing from part of the large bowel.\""}, {"id": "c", "text": "\"The stomach outlet muscle is thick, blocking food flow.\""}, {"id": "d", "text": "\"The esophagus is too narrow for milk to reach the stomach.\""}]'::jsonb, '["c"]', 'Pyloric stenosis is thickening of the pylorus causing gastric outlet obstruction. The other statements describe a different location or mechanism than a thickened pylorus.'),
  ('pyloric', 26, 'The nurse assesses a 7-week-old infant with pyloric stenosis who has been vomiting for 3 days. Which finding supports dehydration?', '[{"id": "a", "text": "Moist mucous membranes with tears"}, {"id": "b", "text": "Dry mouth and decreased tears"}, {"id": "c", "text": "A bulging fontanelle when upright"}, {"id": "d", "text": "Steady weight gain since birth"}]'::jsonb, '["b"]', 'Dry mouth and decreased tears are systemic signs of dehydration in pyloric stenosis. Moist membranes, a bulging fontanelle, and weight gain are the opposite of the expected findings.'),
  ('pyloric', 27, 'A parent reports that a 4-week-old infant with suspected pyloric stenosis has been vomiting after feedings. Which additional history finding does the nurse expect?', '[{"id": "a", "text": "Fewer wet diapers than usual"}, {"id": "b", "text": "More wet diapers than usual"}, {"id": "c", "text": "Sleeping through most feedings"}, {"id": "d", "text": "Green vomit after each feeding"}]'::jsonb, '["a"]', 'Decreased urine output is a sign of dehydration in pyloric stenosis, so fewer wet diapers are expected. The vomiting is non-bilious, and these infants are constantly hungry.'),
  ('pyloric', 28, 'An infant with pyloric stenosis is weighed at a clinic visit. Which finding is consistent with this condition?', '[{"id": "a", "text": "Weight gain above the expected amount"}, {"id": "b", "text": "Weight unchanged with normal intake"}, {"id": "c", "text": "Rapid weight gain from eager feeding"}, {"id": "d", "text": "Weight loss since the previous visit"}]'::jsonb, '["d"]', 'Weight loss is a systemic sign of dehydration in pyloric stenosis. Even though the infant feeds eagerly, food cannot pass into the small intestine, so weight gain is not expected.'),
  ('pyloric', 29, 'An infant with pyloric stenosis has been receiving IV fluids before surgery. Which finding indicates that the fluid therapy is effective?', '[{"id": "a", "text": "The anterior fontanelle is more sunken."}, {"id": "b", "text": "The hematocrit and BUN continue to rise."}, {"id": "c", "text": "The infant''s urine output is increasing."}, {"id": "d", "text": "The infant''s mouth remains dry with no tears."}]'::jsonb, '["c"]', 'IV fluids are given to correct dehydration, so rising urine output shows improvement. A more sunken fontanelle, rising hematocrit and BUN, and a dry mouth indicate ongoing dehydration.'),
  ('pyloric', 30, 'Which sequence of care is correct for an infant diagnosed with pyloric stenosis?', '[{"id": "a", "text": "Pyloromyotomy, then fluid and electrolyte correction, then gradual refeeding"}, {"id": "b", "text": "Fluid and electrolyte correction, then pyloromyotomy, then gradual refeeding"}, {"id": "c", "text": "Gradual refeeding, then pyloromyotomy, then fluid and electrolyte correction"}, {"id": "d", "text": "Fluid and electrolyte correction, then full feedings, then pyloromyotomy"}]'::jsonb, '["b"]', 'Pre-operative stabilization with fluid and electrolyte correction comes first, followed by pyloromyotomy and then gradual post-operative refeeding. Operating before correction is dangerous.'),
  ('pyloric', 31, 'A 4-week-old infant''s laboratory results show a low potassium, a low chloride, and metabolic alkalosis. How should the nurse interpret this pattern?', '[{"id": "a", "text": "It is the classic triad seen in pyloric stenosis."}, {"id": "b", "text": "It is a pattern expected mainly in older children."}, {"id": "c", "text": "It indicates that the infant is vomiting bile."}, {"id": "d", "text": "It means the infant is ready for surgery now."}]'::jsonb, '["a"]', 'Hypokalemia, hypochloremia, and metabolic alkalosis form the classic triad of pyloric stenosis in young infants. These imbalances must be corrected before surgery, not treated as a sign of readiness.'),
  ('pyloric', 32, 'The nurse is teaching the parents of an infant with pyloric stenosis about the vomiting. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"His vomiting tends to happen after feedings.\""}, {"id": "b", "text": "\"The vomit can shoot out with a lot of force.\""}, {"id": "c", "text": "\"He may still act hungry after he vomits.\""}, {"id": "d", "text": "\"I should expect his vomit to look green.\""}]'::jsonb, '["d"]', 'The vomiting in pyloric stenosis is non-bilious (not green), so expecting green vomit needs correction. Forceful vomiting after feeding and continued hunger are expected.'),
  ('pyloric', 33, 'The nurse observes a UAP caring for an infant on the first day after a pyloromyotomy. Which action by the UAP requires correction?', '[{"id": "a", "text": "Recording the amount taken at each feeding"}, {"id": "b", "text": "Reporting a small emesis to the nurse"}, {"id": "c", "text": "Giving a full-volume bottle at the first feeding"}, {"id": "d", "text": "Telling the nurse about redness at the incision"}]'::jsonb, '["c"]', 'Refeeding after pyloromyotomy should begin with small volumes and increase slowly, so a full-volume first feeding is incorrect. Recording intake and reporting vomiting or incision changes are appropriate.'),
  ('pyloric', 34, 'A 6-week-old infant with pyloric stenosis feeds eagerly but continues to lose weight. Which explanation best accounts for the weight loss?', '[{"id": "a", "text": "The infant refuses most of the offered feedings."}, {"id": "b", "text": "Food cannot pass from the stomach to the small intestine."}, {"id": "c", "text": "Food moves too quickly through the small intestine."}, {"id": "d", "text": "Bile is lost each time the infant vomits."}]'::jsonb, '["b"]', 'In pyloric stenosis, food cannot pass from the stomach into the small intestine because of the gastric outlet obstruction. The infant feeds eagerly rather than refusing feeds, and the vomit is non-bilious.'),
  ('pyloric', 35, 'The parent of a 3-week-old infant says, "After he eats, I can see waves moving across his belly." Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"That can be a sign of pyloric stenosis, so I''ll report it.\""}, {"id": "b", "text": "\"That is normal digestion and needs no further follow-up.\""}, {"id": "c", "text": "\"That means the formula is moving through him too fast.\""}, {"id": "d", "text": "\"That only happens when a baby swallows too much air.\""}]'::jsonb, '["a"]', 'Visible peristaltic waves across the abdomen are a classic GI sign of pyloric stenosis. Treating them as normal digestion would miss a key finding.'),
  ('pyloric', 36, 'A 5-week-old infant is being evaluated for pyloric stenosis. Which assessment finding would cause the nurse to question this diagnosis?', '[{"id": "a", "text": "Projectile vomiting after feedings"}, {"id": "b", "text": "Olive-shaped mass in the right upper quadrant"}, {"id": "c", "text": "Eager feeding right after vomiting"}, {"id": "d", "text": "Bright green vomitus after feedings"}]'::jsonb, '["d"]', 'Pyloric stenosis causes non-bilious vomiting because the obstruction is above the ampulla of Vater, so green vomitus does not fit. Projectile vomiting, an olive-shaped RUQ mass, and eager feeding are classic findings.'),
  ('pyloric', 37, 'Before discharge after a pyloromyotomy, which statement by a parent indicates correct understanding of post-operative care?', '[{"id": "a", "text": "\"He can have his full bottle at every feeding starting today.\""}, {"id": "b", "text": "\"Some vomiting at first can be normal, but not if it persists.\""}, {"id": "c", "text": "\"Any vomiting at all means the surgery did not work.\""}, {"id": "d", "text": "\"Once he is home, I won''t need to look at his incision.\""}]'::jsonb, '["b"]', 'Some vomiting after surgery is normal because of residual swelling, but persistent vomiting may indicate an incomplete pyloromyotomy. Refeeding is gradual, and the incision is monitored for infection.'),
  ('pyloric', 38, 'The parent of an infant with suspected pyloric stenosis asks how the diagnosis will be confirmed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A rectal biopsy will look for missing nerve cells.\""}, {"id": "b", "text": "\"An enema will push the bowel back into place.\""}, {"id": "c", "text": "\"An ultrasound will show if the pylorus is thickened.\""}, {"id": "d", "text": "\"Blood tests alone will confirm the diagnosis.\""}]'::jsonb, '["c"]', 'Abdominal ultrasound is the first-line test and confirms pyloric thickening. Labs show supportive findings such as electrolyte imbalances, but the ultrasound is the gold standard.'),
  ('pyloric', 39, 'A nurse is reviewing pediatric GI conditions with a new graduate. Pyloric stenosis most typically presents in which age group?', '[{"id": "a", "text": "Infants 2 to 8 weeks old"}, {"id": "b", "text": "Infants 6 to 12 months old"}, {"id": "c", "text": "Children 2 to 5 years old"}, {"id": "d", "text": "Adolescents 12 to 16 years old"}]'::jsonb, '["a"]', 'Pyloric stenosis affects young infants 2 to 8 weeks old. Older children, teenagers, and adults are not the expected age group.'),
  ('pyloric', 40, 'An infant with pyloric stenosis is receiving IV fluids while awaiting surgery. Which assessment data are the nurse''s priority to monitor before the infant goes to surgery?', '[{"id": "a", "text": "Head circumference"}, {"id": "b", "text": "Developmental milestones"}, {"id": "c", "text": "Stool color and pattern"}, {"id": "d", "text": "Serum electrolyte levels"}]'::jsonb, '["d"]', 'Pre-operative care includes monitoring electrolytes so that potassium, chloride, and metabolic alkalosis are corrected before surgery. The other data do not determine readiness for surgery.'),
  ('pyloric', 41, 'An infant with pyloric stenosis is awaiting surgery and is crying. The parent asks, "Can I give him just a little formula to calm him down?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, a small amount is fine since he is so hungry.\""}, {"id": "b", "text": "\"No, he must stay NPO and get IV fluids before surgery.\""}, {"id": "c", "text": "\"Yes, but give clear liquids instead of formula.\""}, {"id": "d", "text": "\"Yes, if you hold him upright during the feeding.\""}]'::jsonb, '["b"]', 'Pre-operative stabilization requires NPO status with IV fluids to correct dehydration and electrolyte imbalances. Any oral intake, including small amounts, is not allowed.'),
  ('pyloric', 42, 'The nurse reviews the blood gas results of an infant with pyloric stenosis. Which finding does the nurse expect?', '[{"id": "a", "text": "Decreased bicarbonate level"}, {"id": "b", "text": "Elevated chloride level"}, {"id": "c", "text": "Elevated bicarbonate level"}, {"id": "d", "text": "Elevated potassium level"}]'::jsonb, '["c"]', 'Loss of HCl causes excess bicarbonate (base) to accumulate, producing metabolic alkalosis. Chloride and potassium are both decreased in pyloric stenosis.'),
  ('pyloric', 43, 'Which feeding behavior does the nurse expect to observe in a 4-week-old infant with pyloric stenosis?', '[{"id": "a", "text": "Feeds eagerly even after vomiting"}, {"id": "b", "text": "Refuses feedings and turns away"}, {"id": "c", "text": "Falls asleep early in each feeding"}, {"id": "d", "text": "Vomits only before feedings begin"}]'::jsonb, '["a"]', 'Infants with pyloric stenosis are constantly hungry and feed eagerly despite vomiting. The vomiting occurs after feeding, not before.'),
  ('pyloric', 44, 'The nurse is preparing discharge teaching for the parents of an infant after a pyloromyotomy. Which instruction should the nurse include?', '[{"id": "a", "text": "\"Expect forceful vomiting after every feeding.\""}, {"id": "b", "text": "\"Give large feedings so he regains weight fast.\""}, {"id": "c", "text": "\"Green-colored vomit is expected after surgery.\""}, {"id": "d", "text": "\"Watch the incision for signs of infection.\""}]'::jsonb, '["d"]', 'Post-operative care includes monitoring the incision site for signs of infection. Persistent vomiting may indicate an incomplete pyloromyotomy, and feedings are increased gradually rather than given in large volumes.'),
  ('pyloric', 45, 'A parent asks why the infant vomited a little after the first feeding following a pyloromyotomy. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"The surgeon removed part of the stomach outlet.\""}, {"id": "b", "text": "\"The incision has become infected.\""}, {"id": "c", "text": "\"There is still some swelling at the surgical site.\""}, {"id": "d", "text": "\"His metabolic alkalosis has returned.\""}]'::jsonb, '["c"]', 'Some vomiting is normal after surgery because of residual swelling. The procedure does not remove tissue, and a single small emesis is not presented as a sign of infection.'),
  ('pyloric', 46, 'An infant with pyloric stenosis is awaiting rehydration. Which change in laboratory results indicates that dehydration is worsening?', '[{"id": "a", "text": "Decreasing hematocrit and BUN"}, {"id": "b", "text": "Rising hematocrit and BUN"}, {"id": "c", "text": "Rising potassium and chloride"}, {"id": "d", "text": "Decreasing bicarbonate level"}]'::jsonb, '["b"]', 'Elevated hematocrit and BUN reflect hemoconcentration from dehydration, so rising values suggest worsening dehydration. Decreasing values would suggest improvement.'),
  ('pyloric', 47, 'The nurse explains pyloric stenosis to the parents of a 6-week-old infant. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"Food is passing into his intestines too quickly.\""}, {"id": "b", "text": "\"The muscle at the stomach outlet is too thick.\""}, {"id": "c", "text": "\"Food has trouble leaving his stomach.\""}, {"id": "d", "text": "\"His stomach outlet is blocked.\""}]'::jsonb, '["a"]', 'In pyloric stenosis, food cannot pass from the stomach into the small intestine because the thickened pylorus obstructs the gastric outlet. Food moving too quickly into the intestine is the opposite of what happens.'),
  ('pyloric', 48, 'The nurse reviews the potassium level of an infant who has had projectile vomiting for several days. Which finding and explanation are accurate?', '[{"id": "a", "text": "High potassium, because of dehydration"}, {"id": "b", "text": "High potassium, because acid is retained"}, {"id": "c", "text": "Low potassium, because bile is vomited"}, {"id": "d", "text": "Low potassium, partly lost in the vomit"}]'::jsonb, '["d"]', 'Hypokalemia occurs in pyloric stenosis, with potassium lost in the vomit. Potassium is not elevated, and the vomitus is non-bilious.'),
  ('pyloric', 49, 'A 3-week-old infant feeds eagerly and then has forceful, non-green vomiting. Which additional assessment finding should the nurse expect?', '[{"id": "a", "text": "Bulging fontanelle"}, {"id": "b", "text": "Increased urine output"}, {"id": "c", "text": "Visible peristaltic waves"}, {"id": "d", "text": "Green-tinged stools"}]'::jsonb, '["c"]', 'Visible peristalsis across the abdomen is a classic finding of pyloric stenosis. A bulging fontanelle and increased urine output are the reverse of the expected dehydration signs.'),
  ('pyloric', 50, 'An infant''s pyloric stenosis has been confirmed, and fluid and electrolyte imbalances have been corrected. The nurse prepares the infant for which surgical treatment?', '[{"id": "a", "text": "Pyloromyotomy"}, {"id": "b", "text": "Gastrectomy"}, {"id": "c", "text": "Bowel resection"}, {"id": "d", "text": "Colostomy"}]'::jsonb, '["a"]', 'The treatment for pyloric stenosis is pyloromyotomy, which cuts the thickened muscle without removing tissue. Procedures that remove tissue are not the treatment described.'),
  ('intussusception', 1, 'The parent of a 9-month-old infant with episodes of severe crying calls the clinic about the infant''s stools. Which stool description is most concerning for intussusception?', '[{"id": "a", "text": "Hard, pellet-like brown stools"}, {"id": "b", "text": "Loose, yellow, seedy stools"}, {"id": "c", "text": "Stool that looks like red jelly with mucus"}, {"id": "d", "text": "Soft, formed stools with no blood"}]'::jsonb, '["c"]', 'Currant jelly stools, which are bloody and contain mucus, are the hallmark finding of intussusception. Stools without blood or mucus do not show this hallmark.'),
  ('intussusception', 2, 'A nursing student asks what causes currant jelly stools in a child with intussusception. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Intestinal ischemia and sloughing of the mucosa"}, {"id": "b", "text": "Swallowed blood from a recent nosebleed"}, {"id": "c", "text": "Undigested red fruit from the child''s diet"}, {"id": "d", "text": "Bleeding from a small tear in the anus"}]'::jsonb, '["a"]', 'Currant jelly stools result from intestinal ischemia and mucosal sloughing as the telescoped bowel loses its blood supply. The other explanations do not reflect this mechanism.'),
  ('intussusception', 3, 'A 14-month-old child is admitted for intermittent abdominal pain. The nurse finds a stool in the diaper that is bloody and full of mucus. Which action should the nurse take?', '[{"id": "a", "text": "Save the diaper and report it at the end of the shift."}, {"id": "b", "text": "Document it as an expected finding and continue care."}, {"id": "c", "text": "Encourage oral fluids to soften the next stool."}, {"id": "d", "text": "Report the currant jelly stool to the provider immediately."}]'::jsonb, '["d"]', 'Nursing care for intussusception includes monitoring stools and reporting a currant jelly appearance immediately. Delaying the report or offering oral fluids is inappropriate because the child is kept NPO for procedure preparation.'),
  ('intussusception', 4, 'The nurse is observing an 11-month-old infant with suspected intussusception during a pain episode. Which behavior does the nurse expect?', '[{"id": "a", "text": "Lying still with both legs straight"}, {"id": "b", "text": "Drawing the knees up to the chest"}, {"id": "c", "text": "Arching the back and stiffening"}, {"id": "d", "text": "Rubbing the eyes and pulling the ears"}]'::jsonb, '["b"]', 'During pain episodes, a child with intussusception draws the knees to the chest. Lying still with legs straight or arching the back does not match the described pain behavior.'),
  ('intussusception', 5, 'The parent of a 2-year-old says, "He screams for a few minutes, then plays like nothing happened, and then it starts again." How should the nurse interpret this report?', '[{"id": "a", "text": "The pain cannot be serious if he plays in between."}, {"id": "b", "text": "The child is most likely seeking extra attention."}, {"id": "c", "text": "It fits the intermittent pain of intussusception."}, {"id": "d", "text": "It shows that the obstruction has already resolved."}]'::jsonb, '["c"]', 'Intussusception causes severe intermittent abdominal pain, and the child appears normal between episodes. Appearing normal between episodes does not mean the pain is minor or that the obstruction has resolved.'),
  ('intussusception', 6, 'The nurse gently palpates the abdomen of a 10-month-old infant with suspected intussusception. Which finding does the nurse expect?', '[{"id": "a", "text": "A sausage-shaped abdominal mass"}, {"id": "b", "text": "An olive-shaped abdominal mass"}, {"id": "c", "text": "A pulsating abdominal mass"}, {"id": "d", "text": "A soft abdomen with no mass"}]'::jsonb, '["a"]', 'A palpable sausage-shaped mass is part of the classic symptom triad of intussusception. An olive-shaped or pulsating mass is not the described finding.'),
  ('intussusception', 7, 'Which set of findings represents the classic symptom triad of intussusception?', '[{"id": "a", "text": "Currant jelly stools, constant mild pain, and a sausage-shaped mass"}, {"id": "b", "text": "Watery stools, intermittent severe pain, and an olive-shaped mass"}, {"id": "c", "text": "Bloody stools, fever, and abdominal distension"}, {"id": "d", "text": "Currant jelly stools, intermittent severe pain, and a sausage-shaped mass"}]'::jsonb, '["d"]', 'The classic triad is currant jelly stools, severe intermittent abdominal pain, and a palpable sausage-shaped mass. Fever and distension are additional symptoms rather than part of the triad, and the pain is intermittent rather than constant.'),
  ('intussusception', 8, 'The parent of a 1-year-old newly diagnosed with intussusception asks what the condition is. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"The muscle at the stomach outlet has become too thick.\""}, {"id": "b", "text": "\"One part of the intestine has slid into the part next to it.\""}, {"id": "c", "text": "\"Nerve cells are missing from part of the large intestine.\""}, {"id": "d", "text": "\"The intestine is irritated by a viral stomach infection.\""}]'::jsonb, '["b"]', 'Intussusception occurs when one part of the intestine slides or telescopes into another, causing bowel obstruction. The other answers describe different mechanisms.'),
  ('intussusception', 9, 'The parent of a 15-month-old with intussusception asks why treatment must start right away. Which response by the nurse is best?', '[{"id": "a", "text": "\"The folded bowel can lose blood flow, and that tissue can die.\""}, {"id": "b", "text": "\"Waiting longer will make his stomach outlet grow thicker.\""}, {"id": "c", "text": "\"Waiting causes ongoing diarrhea but no harm to the bowel.\""}, {"id": "d", "text": "\"Waiting mainly raises his risk of a mild skin rash.\""}]'::jsonb, '["a"]', 'Intussusception cuts off blood supply, leading to ischemia and then necrosis if untreated. Saying that waiting causes no harm to the bowel is incorrect.'),
  ('intussusception', 10, 'Four children are seen in the emergency department for abdominal pain. Which child is in the age group most commonly affected by intussusception?', '[{"id": "a", "text": "A 2-week-old newborn"}, {"id": "b", "text": "An 8-month-old infant"}, {"id": "c", "text": "A 12-year-old child"}, {"id": "d", "text": "A 16-year-old adolescent"}]'::jsonb, '["b"]', 'Intussusception is most common in infants and young children from 3 months to 6 years of age, which includes the 8-month-old. The newborn and the older children fall outside this range.'),
  ('intussusception', 11, 'A 9-month-old infant with suspected intussusception vomits green-tinged fluid. How should the nurse interpret this finding?', '[{"id": "a", "text": "It rules out intussusception as the diagnosis."}, {"id": "b", "text": "It shows that the bowel has been reduced."}, {"id": "c", "text": "It can occur with intussusception."}, {"id": "d", "text": "It confirms that the bowel has perforated."}]'::jsonb, '["c"]', 'Vomiting, which may be bilious, is an additional symptom of intussusception. Bilious vomiting does not rule out the condition and is not described as a sign of reduction or perforation.'),
  ('intussusception', 12, 'A 2-year-old with intussusception who is awaiting treatment develops a new fever. The nurse recognizes that this finding may indicate:', '[{"id": "a", "text": "successful reduction of the bowel."}, {"id": "b", "text": "an expected finding before the enema."}, {"id": "c", "text": "a normal response to being NPO."}, {"id": "d", "text": "bowel necrosis or perforation."}]'::jsonb, '["d"]', 'Fever occurs in intussusception if bowel necrosis or perforation occurs. It is not a sign of successful reduction or an expected pre-procedure finding.'),
  ('intussusception', 13, 'An ultrasound is performed on a 1-year-old with suspected intussusception. Which finding on the report is consistent with this diagnosis?', '[{"id": "a", "text": "Target or doughnut sign"}, {"id": "b", "text": "Thickened pyloric muscle"}, {"id": "c", "text": "Narrow transition zone"}, {"id": "d", "text": "Absent ganglion cells"}]'::jsonb, '["a"]', 'Ultrasound is the first-line imaging for intussusception and shows a target sign or doughnut sign. The other findings are not the ultrasound findings described for intussusception.'),
  ('intussusception', 14, 'A 13-month-old is brought to the emergency department with intermittent severe abdominal pain and a currant jelly stool. Which imaging study does the nurse anticipate first?', '[{"id": "a", "text": "Abdominal CT scan"}, {"id": "b", "text": "Contrast enema"}, {"id": "c", "text": "Abdominal ultrasound"}, {"id": "d", "text": "Upper GI series"}]'::jsonb, '["c"]', 'Ultrasound is the first-line imaging study for intussusception. A contrast enema can both diagnose and treat, but it is listed as the first-line treatment rather than the first-line imaging.'),
  ('intussusception', 15, 'The parent of a toddler with intussusception asks why an enema has been scheduled. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It only cleans out the bowel before surgery.\""}, {"id": "b", "text": "\"It can both diagnose and fix the problem.\""}, {"id": "c", "text": "\"It only takes pictures; surgery fixes it.\""}, {"id": "d", "text": "\"It delivers antibiotics into the bowel.\""}]'::jsonb, '["b"]', 'An air or barium enema both diagnoses and treats intussusception by reducing it non-surgically. It is not only a picture-taking or cleansing step before surgery.'),
  ('intussusception', 16, 'A 10-month-old infant has been diagnosed with intussusception and has no signs of perforation or necrosis. Which treatment does the nurse anticipate first?', '[{"id": "a", "text": "Immediate bowel resection"}, {"id": "b", "text": "Oral laxatives and fluids"}, {"id": "c", "text": "Observation with no treatment"}, {"id": "d", "text": "Air or barium enema"}]'::jsonb, '["d"]', 'First-line, nonsurgical treatment is an air or barium enema, which reduces the intussusception. Bowel resection is reserved for a necrotic segment.'),
  ('intussusception', 17, 'The nurse is teaching the parents of a 2-year-old newly diagnosed with intussusception. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"He will definitely need surgery to fix this problem.\""}, {"id": "b", "text": "\"The enema may push the bowel back into place.\""}, {"id": "c", "text": "\"Surgery may be needed if the enema does not work.\""}, {"id": "d", "text": "\"An ultrasound is usually the first imaging test.\""}]'::jsonb, '["a"]', 'First-line treatment is a nonsurgical air or barium enema, so surgery is not definite. Surgery is reserved for an unsuccessful enema or suspected perforation or necrosis.'),
  ('intussusception', 18, 'For a child with intussusception who has no signs of perforation, which situation indicates that surgery is needed?', '[{"id": "a", "text": "The ultrasound shows a target sign."}, {"id": "b", "text": "The child has had a currant jelly stool."}, {"id": "c", "text": "The air enema was unsuccessful."}, {"id": "d", "text": "The child has been kept NPO."}]'::jsonb, '["c"]', 'Surgery is indicated if the enema is unsuccessful. A target sign and a currant jelly stool are diagnostic findings that are first managed with an enema.'),
  ('intussusception', 19, 'The parent of a child scheduled for surgery for intussusception asks, "Will they have to remove part of his bowel?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, part of the bowel is always removed.\""}, {"id": "b", "text": "\"Only if a section of bowel has died.\""}, {"id": "c", "text": "\"No, the bowel is never removed.\""}, {"id": "d", "text": "\"Only if the ultrasound showed a target sign.\""}]'::jsonb, '["b"]', 'Bowel resection is performed if a necrotic segment is present. It is not always done, and a target sign is a diagnostic finding rather than an indication for resection.'),
  ('intussusception', 20, 'A 16-month-old with intussusception has had frequent episodes of severe pain. The nurse now finds that the pain episodes have suddenly stopped and the child is lethargic. Which action is the nurse''s priority?', '[{"id": "a", "text": "Document that the child''s condition is improving."}, {"id": "b", "text": "Offer clear fluids now that the pain has stopped."}, {"id": "c", "text": "Let the child rest and reassess in one hour."}, {"id": "d", "text": "Notify the surgeon of the change immediately."}]'::jsonb, '["d"]', 'Pain that suddenly stops with lethargy is not improvement; it may indicate perforation and is an immediate surgical emergency. Documenting improvement or waiting delays urgent treatment.'),
  ('intussusception', 21, 'The parent of a toddler with intussusception tells the nurse, "He finally stopped crying and is just lying there limp. He must be feeling better." Which response by the nurse is best?', '[{"id": "a", "text": "\"Sudden calm with limpness can be a warning sign, so I''ll assess him now.\""}, {"id": "b", "text": "\"Yes, this means the bowel has gone back into place on its own.\""}, {"id": "c", "text": "\"He is worn out from crying, so let him sleep undisturbed.\""}, {"id": "d", "text": "\"That is good news, so we can cancel the planned enema.\""}]'::jsonb, '["a"]', 'When the pain episodes suddenly stop and the child becomes quiet or lethargic, it is not improvement and may indicate perforation or worsening necrosis. The nurse must act rather than reassure.'),
  ('intussusception', 22, 'The nurse is monitoring a 2-year-old with intussusception for perforation. Which set of findings should the nurse report as signs of perforation?', '[{"id": "a", "text": "Passage of a normal brown stool and active bowel sounds"}, {"id": "b", "text": "Normal temperature, slow heart rate, and falling WBC count"}, {"id": "c", "text": "Fever, tachycardia, and an elevated WBC count"}, {"id": "d", "text": "Tolerance of small feedings and a soft abdomen"}]'::jsonb, '["c"]', 'Signs of perforation include fever, tachycardia, and an increased WBC count. A normal brown stool, bowel sounds, and feeding tolerance are monitored after a procedure as signs of recovery.'),
  ('intussusception', 23, 'The nurse is assessing pain in a 1-year-old admitted with intussusception. Which documentation best reflects the recommended pain assessment?', '[{"id": "a", "text": "Pain rating recorded once at the end of the shift"}, {"id": "b", "text": "Frequency, duration, and character of pain episodes"}, {"id": "c", "text": "Pain noted only when the parent requests medication"}, {"id": "d", "text": "Location of pain recorded once on admission only"}]'::jsonb, '["b"]', 'Nursing care includes assessing the pain pattern by noting the frequency, duration, and character of episodes. A single rating does not capture the intermittent pattern.'),
  ('intussusception', 24, 'A 9-month-old with intussusception is scheduled for an air enema. Which pre-procedure orders does the nurse expect?', '[{"id": "a", "text": "Regular diet and oral pain medication"}, {"id": "b", "text": "Clear liquids and an oral laxative"}, {"id": "c", "text": "Small feedings every 2 hours"}, {"id": "d", "text": "NPO status and IV fluids"}]'::jsonb, '["d"]', 'Nursing care includes NPO status for procedure or surgery preparation and IV fluids for hydration. Oral intake, including clear liquids, is not appropriate before the procedure.'),
  ('intussusception', 25, 'A nurse observes a UAP caring for a 3-year-old with intussusception who is awaiting a barium enema. Which action by the UAP requires correction?', '[{"id": "a", "text": "Giving the child a cup of apple juice"}, {"id": "b", "text": "Reporting a bloody stool to the nurse"}, {"id": "c", "text": "Taking and recording vital signs"}, {"id": "d", "text": "Telling the nurse that the child is crying"}]'::jsonb, '["a"]', 'The child must remain NPO in preparation for the enema or surgery, so giving juice requires correction. Reporting stools, vital signs, and pain behavior is appropriate.'),
  ('intussusception', 26, 'A 14-month-old has just had an air enema to reduce an intussusception. Which finding best indicates that the treatment was effective?', '[{"id": "a", "text": "Passage of another currant jelly stool"}, {"id": "b", "text": "Absent bowel sounds on auscultation"}, {"id": "c", "text": "Passage of the first normal stool"}, {"id": "d", "text": "Vomiting after each small feeding"}]'::jsonb, '["c"]', 'After the procedure, the nurse monitors bowel sounds, the first normal stool, and tolerance of feeds. A currant jelly stool, absent bowel sounds, or vomiting would not indicate success.'),
  ('intussusception', 27, 'Which set of assessments should the nurse include in the plan of care for a child after a successful enema reduction of an intussusception?', '[{"id": "a", "text": "Head circumference, urine color, and skin turgor only"}, {"id": "b", "text": "Bowel sounds, first normal stool, and tolerance of feeds"}, {"id": "c", "text": "Pupil response, reflexes, and grip strength"}, {"id": "d", "text": "Stool color only, checked once before discharge"}]'::jsonb, '["b"]', 'Post-procedure care includes monitoring bowel sounds, the first normal stool, and tolerance of feeds. The other assessments do not address recovery of bowel function.'),
  ('intussusception', 28, 'A toddler is recovering after an enema reduction of an intussusception. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Took a small feeding without vomiting"}, {"id": "b", "text": "Passed a normal brown stool this morning"}, {"id": "c", "text": "Bowel sounds are present on auscultation"}, {"id": "d", "text": "Abdominal distension and vomiting with each feeding"}]'::jsonb, '["d"]', 'Post-procedure monitoring includes tolerance of feeds, and vomiting with abdominal distension are symptoms of intussusception. A normal stool, bowel sounds, and tolerated feedings are expected recovery findings.'),
  ('intussusception', 29, 'A 2-year-old has been diagnosed with intussusception. Which nursing action best supports the child and family at this time?', '[{"id": "a", "text": "Prepare them for the enema and possible surgery."}, {"id": "b", "text": "Tell them the problem will resolve without treatment."}, {"id": "c", "text": "Advise them to wait at home and return if pain worsens."}, {"id": "d", "text": "Explain that surgery is never needed for this condition."}]'::jsonb, '["a"]', 'Nursing care includes preparing the child and family for the enema procedure or surgery. Intussusception requires treatment, and surgery is needed if the enema fails or complications occur.'),
  ('intussusception', 30, 'The nurse is caring for four children on a pediatric unit. Which child should the nurse assess first?', '[{"id": "a", "text": "A 2-year-old awaiting an enema who is crying with intermittent pain"}, {"id": "b", "text": "An 18-month-old who passed a normal stool after an air enema"}, {"id": "c", "text": "A 1-year-old with intussusception whose pain suddenly stopped and who is now limp"}, {"id": "d", "text": "A 10-month-old who is NPO and fussing for a bottle"}]'::jsonb, '["c"]', 'Pain that suddenly stops with lethargy may indicate perforation and is an immediate surgical emergency. Intermittent crying is expected, and a normal stool after an enema is a recovery finding.'),
  ('intussusception', 31, 'Which sequence of care is expected for a child with suspected intussusception and no signs of perforation?', '[{"id": "a", "text": "Surgery, then ultrasound, then air enema"}, {"id": "b", "text": "Ultrasound, then air enema, then surgery if it fails"}, {"id": "c", "text": "Air enema, then surgery, then ultrasound"}, {"id": "d", "text": "Bowel resection, then ultrasound, then barium enema"}]'::jsonb, '["b"]', 'Ultrasound is the first-line imaging, an air or barium enema is the first-line treatment, and surgery follows if the enema is unsuccessful. Starting with surgery skips the nonsurgical first-line treatment.'),
  ('intussusception', 32, 'Which finding does the nurse recognize as the hallmark sign of intussusception?', '[{"id": "a", "text": "Vomiting"}, {"id": "b", "text": "Fever"}, {"id": "c", "text": "Abdominal distension"}, {"id": "d", "text": "Currant jelly stool"}]'::jsonb, '["d"]', 'Currant jelly stool is the hallmark sign of intussusception. Vomiting, distension, and fever are listed as additional symptoms.'),
  ('intussusception', 33, 'The nurse inspects the abdomen of a 10-month-old infant with intussusception. Which finding is consistent with this condition?', '[{"id": "a", "text": "Abdominal distension"}, {"id": "b", "text": "A sunken abdomen"}, {"id": "c", "text": "An olive-shaped mass"}, {"id": "d", "text": "A flat, nontender abdomen"}]'::jsonb, '["a"]', 'Abdominal distension is an additional symptom of intussusception, so a sunken or flat abdomen is not expected. The mass in intussusception is sausage-shaped, not olive-shaped.'),
  ('intussusception', 34, 'A 1-year-old with intussusception develops vomiting and abdominal distension. The nurse recognizes that these findings result from:', '[{"id": "a", "text": "a thickened stomach outlet blocking feeds."}, {"id": "b", "text": "constipation caused by poor fluid intake."}, {"id": "c", "text": "bowel obstruction from the telescoped intestine."}, {"id": "d", "text": "a viral infection of the stomach lining."}]'::jsonb, '["c"]', 'In intussusception, one part of the intestine telescopes into another, causing bowel obstruction, and vomiting and distension are additional symptoms. The other explanations do not describe this mechanism.'),
  ('intussusception', 35, 'The nurse is precepting a new graduate on a pediatric unit. Which statement about intussusception by the new graduate requires correction?', '[{"id": "a", "text": "\"Currant jelly stools should be reported right away.\""}, {"id": "b", "text": "\"If the pain stops and the child gets lethargic, he is improving.\""}, {"id": "c", "text": "\"The child may draw the knees to the chest during pain.\""}, {"id": "d", "text": "\"An enema can both diagnose and treat the condition.\""}]'::jsonb, '["b"]', 'Sudden calm with lethargy is a red flag that may indicate perforation, not improvement. The other statements are accurate.'),
  ('intussusception', 36, 'A 3-year-old with intussusception who is awaiting an enema develops a fever, tachycardia, and a rising WBC count. The nurse anticipates preparing the child for:', '[{"id": "a", "text": "discharge with home observation."}, {"id": "b", "text": "a repeat ultrasound next week."}, {"id": "c", "text": "an oral feeding trial."}, {"id": "d", "text": "surgery."}]'::jsonb, '["d"]', 'Fever, tachycardia, and elevated WBC are signs of perforation, and surgery is indicated if perforation or necrosis is suspected. Discharge, delay, or oral feeding would be unsafe.'),
  ('intussusception', 37, 'The ultrasound report for an 18-month-old with intermittent abdominal pain describes a "target sign." How should the nurse interpret this finding?', '[{"id": "a", "text": "It is consistent with intussusception."}, {"id": "b", "text": "It shows that the bowel has perforated."}, {"id": "c", "text": "It confirms the bowel is now reduced."}, {"id": "d", "text": "It is a normal finding in toddlers."}]'::jsonb, '["a"]', 'Ultrasound is the first-line imaging for intussusception and shows a target sign or doughnut sign. The finding supports the diagnosis rather than reduction or perforation.'),
  ('intussusception', 38, 'A parent asks why the nurse keeps checking the vital signs of a 2-year-old with intussusception. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"To see whether the enema dye has been absorbed.\""}, {"id": "b", "text": "\"To decide when he can start eating again.\""}, {"id": "c", "text": "\"To watch for signs that the bowel has perforated.\""}, {"id": "d", "text": "\"To check whether he is ready to go home today.\""}]'::jsonb, '["c"]', 'Vital signs are monitored to watch for signs of perforation, such as fever and tachycardia. This monitoring is a nursing safety priority in intussusception.'),
  ('intussusception', 39, 'IV fluids are started for a 1-year-old with intussusception who is awaiting an enema. The nurse explains that the main purpose of the IV fluids is to:', '[{"id": "a", "text": "deliver the contrast for the enema."}, {"id": "b", "text": "keep the child hydrated while NPO."}, {"id": "c", "text": "dissolve the mass in the bowel."}, {"id": "d", "text": "replace blood lost in the stools."}]'::jsonb, '["b"]', 'Nursing care includes IV fluids for hydration while the child is NPO for procedure or surgery preparation. The IV fluids do not reduce the intussusception.'),
  ('intussusception', 40, 'The nurse teaches the parent of a 13-month-old about intussusception. Which statement by the parent indicates understanding of the pain pattern?', '[{"id": "a", "text": "\"His pain should stay steady and mild all day.\""}, {"id": "b", "text": "\"He will lie flat with his legs straight when it hurts.\""}, {"id": "c", "text": "\"His pain happens only when he passes a stool.\""}, {"id": "d", "text": "\"He may pull his knees up when the pain comes.\""}]'::jsonb, '["d"]', 'The child draws the knees to the chest during episodes of severe intermittent pain. Pain that is steady and mild does not match this pattern.'),
  ('intussusception', 41, 'The parent of a 2-year-old with intussusception asks why the child is not allowed to eat or drink. Which response by the nurse is best?', '[{"id": "a", "text": "\"He needs to be ready for the enema or for surgery.\""}, {"id": "b", "text": "\"Food would make his currant jelly stools worse.\""}, {"id": "c", "text": "\"Eating would cause his fever to go up.\""}, {"id": "d", "text": "\"Being NPO helps the bowel unfold on its own.\""}]'::jsonb, '["a"]', 'The child is kept NPO for procedure or surgery preparation. NPO status is not described as treating or reducing the intussusception.'),
  ('intussusception', 42, 'A nursing student is caring for a 10-month-old with suspected intussusception. Which statement by the student requires correction?', '[{"id": "a", "text": "\"The child may have abdominal distension.\""}, {"id": "b", "text": "\"Currant jelly stools are the hallmark finding.\""}, {"id": "c", "text": "\"Green vomiting rules out intussusception.\""}, {"id": "d", "text": "\"A sausage-shaped mass may be palpated.\""}]'::jsonb, '["c"]', 'Vomiting in intussusception may be bilious, so green vomiting does not rule it out. The other statements are accurate.'),
  ('intussusception', 43, 'The nurse is monitoring a child with intussusception whose treatment has been delayed. Which complication results when the telescoped bowel''s blood supply is cut off?', '[{"id": "a", "text": "Thickening of the pyloric muscle"}, {"id": "b", "text": "Ischemia progressing to necrosis"}, {"id": "c", "text": "Loss of nerve cells in the colon"}, {"id": "d", "text": "Narrowing of the esophagus"}]'::jsonb, '["b"]', 'The telescoped bowel loses its blood supply, which leads to ischemia and then necrosis if untreated. The other options do not describe the complications of intussusception.'),
  ('intussusception', 44, 'The nurse is observing a 7-month-old infant with intermittent episodes of inconsolable crying. Which finding should the nurse report immediately?', '[{"id": "a", "text": "A wet diaper every few hours"}, {"id": "b", "text": "Interest in toys between crying spells"}, {"id": "c", "text": "A temperature within the normal range"}, {"id": "d", "text": "A stool containing blood and mucus"}]'::jsonb, '["d"]', 'A bloody stool with mucus is a currant jelly stool, which should be reported immediately. Appearing normal between pain episodes is expected in intussusception.'),
  ('intussusception', 45, 'An air enema performed on a 2-year-old with intussusception did not reduce the bowel. Which action does the nurse anticipate next?', '[{"id": "a", "text": "Preparing the child for surgery"}, {"id": "b", "text": "Discharging the child with follow-up"}, {"id": "c", "text": "Starting the child on oral feedings"}, {"id": "d", "text": "Giving an oral laxative and observing"}]'::jsonb, '["a"]', 'Surgery is indicated if the enema is unsuccessful. Discharging the child or starting feedings ignores an unresolved obstruction.'),
  ('intussusception', 46, 'The nurse is reviewing four children with intussusception. For which child does the nurse anticipate surgery rather than an enema as the first treatment?', '[{"id": "a", "text": "A child whose ultrasound shows a doughnut sign"}, {"id": "b", "text": "A child with currant jelly stools and pain episodes"}, {"id": "c", "text": "A child with suspected bowel perforation"}, {"id": "d", "text": "A child with a palpable sausage-shaped mass"}]'::jsonb, '["c"]', 'Surgery is indicated if bowel perforation or necrosis is suspected. The other children show classic diagnostic findings that are first managed with an air or barium enema.'),
  ('intussusception', 47, 'A 15-month-old with intussusception is admitted. Which explanation best describes why the child develops a bowel obstruction?', '[{"id": "a", "text": "The bowel wall becomes paralyzed from missing nerves."}, {"id": "b", "text": "One section of intestine telescopes into another."}, {"id": "c", "text": "Hard stool collects and blocks the large intestine."}, {"id": "d", "text": "The stomach outlet muscle thickens and narrows."}]'::jsonb, '["b"]', 'Intussusception is a bowel-within-bowel obstruction in which the intestine folds into itself like a collapsing telescope. The other choices describe different mechanisms.'),
  ('intussusception', 48, 'The nurse is assessing the pain pattern of a 1-year-old with suspected intussusception. Which question to the parent is most useful?', '[{"id": "a", "text": "\"Does his pain get better after he eats?\""}, {"id": "b", "text": "\"Did the pain start after a fall or injury?\""}, {"id": "c", "text": "\"Is the pain worse when he lies on his back?\""}, {"id": "d", "text": "\"How often do the episodes occur, and how long do they last?\""}]'::jsonb, '["d"]', 'Pain assessment in intussusception focuses on the frequency, duration, and character of the intermittent episodes. The other questions do not capture this pattern.'),
  ('intussusception', 49, 'A nursing student is reviewing intussusception. Which statement by the student requires correction?', '[{"id": "a", "text": "\"It is seen most often in teenagers and adults.\""}, {"id": "b", "text": "\"It is most common in infants and young children.\""}, {"id": "c", "text": "\"It can cause a sausage-shaped abdominal mass.\""}, {"id": "d", "text": "\"It can cause stools with blood and mucus.\""}]'::jsonb, '["a"]', 'Intussusception is most common in infants and young children from 3 months to 6 years old, not in teenagers and adults. The other statements are accurate.'),
  ('intussusception', 50, 'The parent of a 20-month-old asks how intussusception pain usually appears. Which description by the nurse is accurate?', '[{"id": "a", "text": "\"A mild, steady ache that lasts all day\""}, {"id": "b", "text": "\"A burning pain that occurs after meals\""}, {"id": "c", "text": "\"Severe pain that comes and goes in episodes\""}, {"id": "d", "text": "\"Pain that occurs only while passing stool\""}]'::jsonb, '["c"]', 'Intussusception causes severe intermittent abdominal pain, with the child appearing normal between episodes. A mild, steady ache does not match this pattern.'),
  ('hirschsprung', 1, 'A full-term newborn is 50 hours old and has not passed meconium. Which action should the nurse take?', '[{"id": "a", "text": "Document this as a normal finding for a newborn."}, {"id": "b", "text": "Report the finding to the provider promptly."}, {"id": "c", "text": "Wait until 72 hours before taking any action."}, {"id": "d", "text": "Increase the feeding volume to stimulate a stool."}]'::jsonb, '["b"]', 'Failure to pass meconium within 48 hours after birth is a key red-flag sign of Hirschsprung disease and should be reported. Treating it as normal or waiting longer delays a diagnosis that must be made early.'),
  ('hirschsprung', 2, 'The nurse is reviewing newborn assessment data. Which finding is the key sign of Hirschsprung disease in a newborn?', '[{"id": "a", "text": "Passage of meconium within the first 24 hours"}, {"id": "b", "text": "Projectile, non-green vomiting after feeding"}, {"id": "c", "text": "Stools that contain blood and mucus"}, {"id": "d", "text": "Failure to pass meconium within 48 hours"}]'::jsonb, '["d"]', 'Failure to pass meconium within 48 hours after birth is the key newborn sign of Hirschsprung disease. Passing meconium within 24 hours is not a red flag.'),
  ('hirschsprung', 3, 'A newborn has not passed meconium within 48 hours of birth. Besides Hirschsprung disease, which condition should the nurse also consider?', '[{"id": "a", "text": "Cystic fibrosis"}, {"id": "b", "text": "Pyloric stenosis"}, {"id": "c", "text": "Intussusception"}, {"id": "d", "text": "Viral gastroenteritis"}]'::jsonb, '["a"]', 'Failure to pass meconium in 48 hours is a red flag for Hirschsprung disease or cystic fibrosis. Delayed meconium should prompt consideration of both conditions.'),
  ('hirschsprung', 4, 'A 2-day-old newborn vomits green fluid after a feeding. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is normal spit-up that needs no follow-up."}, {"id": "b", "text": "It indicates the newborn is being overfed."}, {"id": "c", "text": "It suggests a serious bowel obstruction."}, {"id": "d", "text": "It shows that meconium is about to pass."}]'::jsonb, '["c"]', 'Bilious (green) vomiting indicates a serious obstruction and is not normal spit-up. It is one of the newborn signs of Hirschsprung disease.'),
  ('hirschsprung', 5, 'The nurse is teaching the parents of a newborn being evaluated for Hirschsprung disease. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I should tell the nurse if his belly looks swollen.\""}, {"id": "b", "text": "\"Green vomit is just normal spit-up for a newborn.\""}, {"id": "c", "text": "\"I should report it if he has not passed his first stool.\""}, {"id": "d", "text": "\"I should tell the nurse if he is feeding poorly.\""}]'::jsonb, '["b"]', 'Bilious vomiting signals a serious obstruction and is not normal spit-up. A distended abdomen, failure to pass meconium, and poor feeding are newborn signs that should be reported.'),
  ('hirschsprung', 6, 'Which set of findings in a newborn is most consistent with Hirschsprung disease?', '[{"id": "a", "text": "Meconium passed at 12 hours, non-green vomiting, and a flat abdomen"}, {"id": "b", "text": "Meconium passed at 24 hours, green vomiting, and a sunken abdomen"}, {"id": "c", "text": "No meconium by 48 hours, non-green vomiting, and eager feeding"}, {"id": "d", "text": "No meconium by 48 hours, green vomiting, and a distended abdomen"}]'::jsonb, '["d"]', 'Newborn signs of Hirschsprung disease include failure to pass meconium within 48 hours, bilious (green) vomiting, and a distended abdomen. Poor feeding, not eager feeding, is also a newborn sign.'),
  ('hirschsprung', 7, 'A 2-year-old with chronic constipation is being evaluated for late-diagnosed Hirschsprung disease. Which stool description does the nurse expect the parent to report?', '[{"id": "a", "text": "Thin, ribbon-like stools"}, {"id": "b", "text": "Red, jelly-like stools with mucus"}, {"id": "c", "text": "Frequent, large, soft stools"}, {"id": "d", "text": "Pale, greasy, floating stools"}]'::jsonb, '["a"]', 'Ribbon-like stools are a later sign of Hirschsprung disease caused by partial obstruction. The other stool descriptions are not the later signs described for this condition.'),
  ('hirschsprung', 8, 'A nursing student asks why a child with Hirschsprung disease has ribbon-like stools. Which explanation by the nurse is correct?', '[{"id": "a", "text": "The bowel is infected and inflamed."}, {"id": "b", "text": "The child is not absorbing nutrients."}, {"id": "c", "text": "There is a partial bowel obstruction."}, {"id": "d", "text": "There is a complete bowel obstruction."}]'::jsonb, '["c"]', 'Ribbon-like stools are a later sign that reflects partial obstruction. A complete obstruction would not allow ribbon-like stool to pass.'),
  ('hirschsprung', 9, 'The nurse is taking a history from the parent of a 3-year-old suspected of having Hirschsprung disease. Which history finding is consistent with this condition?', '[{"id": "a", "text": "Frequent loose stools and rapid weight gain"}, {"id": "b", "text": "Chronic constipation and failure to thrive"}, {"id": "c", "text": "Bloody stools and episodes of knee-to-chest pain"}, {"id": "d", "text": "Forceful vomiting followed by eager feeding"}]'::jsonb, '["b"]', 'Later signs of Hirschsprung disease include chronic constipation and failure to thrive. Loose stools and rapid weight gain are the opposite of these findings.'),
  ('hirschsprung', 10, 'The parent of a child with Hirschsprung disease asks what the term "megacolon" means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The colon has extra nerve cells in it.\""}, {"id": "b", "text": "\"The colon is too short to absorb water.\""}, {"id": "c", "text": "\"The colon has slid into the small bowel.\""}, {"id": "d", "text": "\"The bowel has become severely enlarged.\""}]'::jsonb, '["d"]', 'Megacolon is severe bowel enlargement, a later sign of Hirschsprung disease. The disease involves an absence, not an excess, of ganglion cells.'),
  ('hirschsprung', 11, 'A nursing student asks why stool cannot pass through the affected part of the colon in Hirschsprung disease. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Missing ganglion cells mean there is no peristalsis."}, {"id": "b", "text": "The muscle at the stomach outlet is thickened."}, {"id": "c", "text": "The colon has telescoped into another segment."}, {"id": "d", "text": "Peristalsis is too rapid for stool to form."}]'::jsonb, '["a"]', 'Without ganglion cells there is no nerve stimulation and no peristalsis, so stool cannot pass. The problem is absent peristalsis rather than rapid peristalsis.'),
  ('hirschsprung', 12, 'Which statement best describes the aganglionic segment of bowel in Hirschsprung disease?', '[{"id": "a", "text": "It stays relaxed and cannot contract."}, {"id": "b", "text": "It is the dilated, enlarged section of colon."}, {"id": "c", "text": "It stays contracted and cannot relax."}, {"id": "d", "text": "It contracts and relaxes too quickly."}]'::jsonb, '["c"]', 'The aganglionic segment stays contracted and cannot relax to move stool through. It is the narrow segment, while the normal colon above it becomes dilated.'),
  ('hirschsprung', 13, 'Which sequence correctly describes the pathophysiology of Hirschsprung disease?', '[{"id": "a", "text": "No peristalsis, then no ganglion cells, then bowel dilation, then obstruction"}, {"id": "b", "text": "No ganglion cells, then no nerve stimulation, then no peristalsis, then obstruction"}, {"id": "c", "text": "Bowel dilation, then no ganglion cells, then no peristalsis, then obstruction"}, {"id": "d", "text": "No nerve stimulation, then obstruction, then no ganglion cells, then no peristalsis"}]'::jsonb, '["b"]', 'Absent ganglion cells lead to no nerve stimulation, then no peristalsis, so stool cannot pass, causing obstruction and bowel dilation. The other sequences place the steps out of order.'),
  ('hirschsprung', 14, 'A barium enema is performed on an infant with suspected Hirschsprung disease. Which finding does the nurse expect on the report?', '[{"id": "a", "text": "A dilated aganglionic segment leading to a narrow normal colon"}, {"id": "b", "text": "A uniformly dilated colon with no change in width"}, {"id": "c", "text": "A uniformly narrow colon with no change in width"}, {"id": "d", "text": "A narrow aganglionic segment leading to a dilated normal colon"}]'::jsonb, '["d"]', 'The barium enema shows a transition zone from the narrow aganglionic segment to the dilated normal colon. The first option reverses which segment is narrow and which is dilated.'),
  ('hirschsprung', 15, 'An infant has signs suggestive of Hirschsprung disease. Which test does the nurse anticipate to confirm the diagnosis as the gold standard?', '[{"id": "a", "text": "Rectal suction biopsy"}, {"id": "b", "text": "Barium enema X-ray"}, {"id": "c", "text": "Anorectal manometry"}, {"id": "d", "text": "Abdominal X-ray"}]'::jsonb, '["a"]', 'Rectal suction biopsy is the gold standard because it confirms the absence of ganglion cells. The other tests show supportive findings such as a transition zone or distended loops.'),
  ('hirschsprung', 16, 'The nurse reviews the rectal suction biopsy report for an infant with suspected Hirschsprung disease. Which finding confirms the diagnosis?', '[{"id": "a", "text": "Increased numbers of ganglion cells"}, {"id": "b", "text": "Normal ganglion cells in the sample"}, {"id": "c", "text": "Absence of ganglion cells"}, {"id": "d", "text": "Thickened muscle with normal nerves"}]'::jsonb, '["c"]', 'The gold standard rectal biopsy confirms Hirschsprung disease by showing an absence of ganglion cells. Normal or increased ganglion cells would not confirm the disease.'),
  ('hirschsprung', 17, 'Anorectal manometry is performed on a child with suspected Hirschsprung disease. Which result is consistent with the diagnosis?', '[{"id": "a", "text": "An exaggerated internal anal sphincter relaxation reflex"}, {"id": "b", "text": "Absence of the internal anal sphincter relaxation reflex"}, {"id": "c", "text": "A normal internal anal sphincter relaxation reflex"}, {"id": "d", "text": "Relaxation of the sphincter only during crying"}]'::jsonb, '["b"]', 'Anorectal manometry in Hirschsprung disease shows absence of the internal anal sphincter relaxation reflex. A normal or exaggerated reflex does not support the diagnosis.'),
  ('hirschsprung', 18, 'An abdominal X-ray is obtained for a newborn with a distended abdomen and suspected Hirschsprung disease. Which finding does the nurse expect on the report?', '[{"id": "a", "text": "Thickened pyloric muscle"}, {"id": "b", "text": "Target or doughnut sign"}, {"id": "c", "text": "Normal, gas-free bowel"}, {"id": "d", "text": "Distended loops with air-fluid levels"}]'::jsonb, '["d"]', 'In Hirschsprung disease, the abdominal X-ray shows distended bowel loops and air-fluid levels. A normal bowel pattern would not fit the obstruction.'),
  ('hirschsprung', 19, 'The parents of an infant with confirmed Hirschsprung disease ask which treatment will cure the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Surgery to remove the bowel segment that lacks nerve cells.\""}, {"id": "b", "text": "\"Daily stool softeners given for the rest of his childhood.\""}, {"id": "c", "text": "\"Regular enemas given at home to keep the bowel empty.\""}, {"id": "d", "text": "\"A high-fiber formula to help stool pass more easily.\""}]'::jsonb, '["a"]', 'Surgical removal of the aganglionic bowel segment is the only definitive cure. Stool softeners, enemas, and diet changes do not remove the segment without nerve cells.'),
  ('hirschsprung', 20, 'The nurse is teaching the parents of a child with Hirschsprung disease about treatment. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"Surgery will remove the part without nerve cells.\""}, {"id": "b", "text": "\"He may need a temporary colostomy if severe.\""}, {"id": "c", "text": "\"Daily laxatives will cure his condition.\""}, {"id": "d", "text": "\"Healthy bowel will be connected to the anus.\""}]'::jsonb, '["c"]', 'Surgical removal of the aganglionic segment is the only definitive cure, so laxatives will not cure the condition. The other statements correctly describe the surgical approach.'),
  ('hirschsprung', 21, 'An infant with Hirschsprung disease is scheduled for a pull-through procedure. Which description of the procedure by the nurse is accurate?', '[{"id": "a", "text": "\"The aganglionic segment is connected directly to the anus.\""}, {"id": "b", "text": "\"The aganglionic segment is removed and normal bowel is joined to the anus.\""}, {"id": "c", "text": "\"The thickened muscle is cut lengthwise without removing tissue.\""}, {"id": "d", "text": "\"The bowel is pushed back into place using an air enema.\""}]'::jsonb, '["b"]', 'The pull-through procedure removes the aganglionic segment and connects normal bowel to the anus. Connecting the aganglionic segment itself would leave the non-functioning bowel in place.'),
  ('hirschsprung', 22, 'The parent of an infant with severe Hirschsprung disease asks whether a colostomy will be needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Every child with this condition gets a colostomy.\""}, {"id": "b", "text": "\"A colostomy is the only definitive cure.\""}, {"id": "c", "text": "\"A colostomy is never part of the treatment.\""}, {"id": "d", "text": "\"A temporary colostomy may be needed in severe cases.\""}]'::jsonb, '["d"]', 'A temporary colostomy may be required in severe cases. The definitive cure is surgical removal of the aganglionic segment, not a colostomy.'),
  ('hirschsprung', 23, 'The nurse is reviewing complications of Hirschsprung disease with a new graduate. Which complication is the most deadly?', '[{"id": "a", "text": "Enterocolitis"}, {"id": "b", "text": "Megacolon"}, {"id": "c", "text": "Ribbon-like stools"}, {"id": "d", "text": "Failure to thrive"}]'::jsonb, '["a"]', 'Hirschsprung-associated enterocolitis is the most deadly complication because it can lead to sepsis and sudden septic shock. Megacolon, ribbon-like stools, and failure to thrive are later signs of the disease.'),
  ('hirschsprung', 24, 'The nurse is monitoring an infant with Hirschsprung disease for enterocolitis. Which set of findings indicates this complication?', '[{"id": "a", "text": "Hard stools, low temperature, and a soft abdomen"}, {"id": "b", "text": "Ribbon-like stools, normal temperature, and weight gain"}, {"id": "c", "text": "Fever, explosive foul-smelling diarrhea, and worsening distension"}, {"id": "d", "text": "Bloody mucus stools, knee-to-chest pain, and a sausage-shaped mass"}]'::jsonb, '["c"]', 'Signs of enterocolitis are fever, explosive foul-smelling diarrhea, worsening abdominal distension, and high WBC. The other combinations do not match these signs.'),
  ('hirschsprung', 25, 'An infant with Hirschsprung disease awaiting surgery develops a fever and explosive, foul-smelling diarrhea. Which action is the nurse''s priority?', '[{"id": "a", "text": "Record the stools and recheck at the next scheduled assessment."}, {"id": "b", "text": "Notify the provider immediately of the change."}, {"id": "c", "text": "Reassure the parents that the bowel is starting to work."}, {"id": "d", "text": "Increase the feeding volume to replace lost fluid."}]'::jsonb, '["b"]', 'These are signs of enterocolitis, the most deadly complication, which requires close monitoring and immediate intervention. Waiting or interpreting the stools as improvement delays care.'),
  ('hirschsprung', 26, 'The parent of an infant with Hirschsprung disease says, "He finally has lots of stool, even though it smells bad and comes out explosively, and he feels warm. He must be getting better." Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, this shows his bowel has started to work normally.\""}, {"id": "b", "text": "\"This is expected, so we can wait until his next checkup.\""}, {"id": "c", "text": "\"This means the narrow part of his bowel has relaxed.\""}, {"id": "d", "text": "\"These can be signs of a serious bowel infection, so I''ll check him now.\""}]'::jsonb, '["d"]', 'Fever with explosive, foul-smelling diarrhea are signs of enterocolitis, a bowel infection that can lead to sepsis. These findings require immediate action rather than reassurance.'),
  ('hirschsprung', 27, 'An infant with Hirschsprung disease has a fever, leukocytosis, and worsening abdominal distension. How should the nurse interpret these findings?', '[{"id": "a", "text": "They are signs of sepsis that require prompt action."}, {"id": "b", "text": "They are expected findings before surgery."}, {"id": "c", "text": "They show that the obstruction is resolving."}, {"id": "d", "text": "They reflect dehydration from poor feeding only."}]'::jsonb, '["a"]', 'Fever, leukocytosis, and worsening abdominal distension are sepsis signs the nurse must monitor for in Hirschsprung disease. They are not expected or reassuring findings.'),
  ('hirschsprung', 28, 'A nursing student asks what Hirschsprung-associated enterocolitis is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A thickening of the bowel muscle that blocks stool"}, {"id": "b", "text": "A sliding of one bowel segment into another"}, {"id": "c", "text": "A bowel infection that can lead to sepsis"}, {"id": "d", "text": "A normal stage of healing after surgery"}]'::jsonb, '["c"]', 'Hirschsprung-associated enterocolitis is a bowel infection leading to sepsis, and it is the most deadly complication. It is not a normal or expected stage of the disease.'),
  ('hirschsprung', 29, 'The parent of a newborn being evaluated for Hirschsprung disease asks why the team is moving so quickly with testing. Which response by the nurse is best?', '[{"id": "a", "text": "\"Testing is quick because the condition goes away on its own.\""}, {"id": "b", "text": "\"Delays in diagnosis can lead to a life-threatening bowel infection.\""}, {"id": "c", "text": "\"Early testing is needed only to choose the right formula.\""}, {"id": "d", "text": "\"Testing is rushed because he will be discharged today.\""}]'::jsonb, '["b"]', 'Early diagnosis is critical because delays can lead to fatal enterocolitis. The condition does not resolve on its own; surgery is the only definitive cure.'),
  ('hirschsprung', 30, 'The nurse is planning care for an infant after a pull-through procedure for Hirschsprung disease. Which set of nursing actions should be included?', '[{"id": "a", "text": "Keep NPO for 2 weeks and restrict all pain medication"}, {"id": "b", "text": "Measure head circumference and check reflexes"}, {"id": "c", "text": "Encourage full feedings at once and limit assessments"}, {"id": "d", "text": "Monitor for infection, manage pain, and watch for bowel function"}]'::jsonb, '["d"]', 'Post-operative nursing priorities include monitoring for infection, managing pain, and watching for the return of bowel function. The other actions do not address these priorities.'),
  ('hirschsprung', 31, 'An infant is 1 day post-op after a pull-through procedure. Which finding should the nurse report to the surgeon immediately?', '[{"id": "a", "text": "Fever with worsening abdominal distension"}, {"id": "b", "text": "Pain relieved after prescribed medication"}, {"id": "c", "text": "Parents asking about home care"}, {"id": "d", "text": "A clean, dry surgical dressing"}]'::jsonb, '["a"]', 'Fever and worsening abdominal distension are sepsis signs that require prompt reporting. Controlled pain and a clean dressing are expected findings.'),
  ('hirschsprung', 32, 'The nurse is preparing discharge teaching for the parents of a child with Hirschsprung disease. Which instruction is most important to include?', '[{"id": "a", "text": "\"Explosive diarrhea is expected and can be watched at home.\""}, {"id": "b", "text": "\"A swollen belly is normal and does not need to be reported.\""}, {"id": "c", "text": "\"Call right away for fever, explosive diarrhea, or a swollen belly.\""}, {"id": "d", "text": "\"Fever is common and only needs to be reported if it lasts a week.\""}]'::jsonb, '["c"]', 'Family education includes signs of complications to watch for at home, and fever, explosive diarrhea, and distension are signs of enterocolitis. These signs need immediate attention rather than home observation.'),
  ('hirschsprung', 33, 'The parent of a newborn diagnosed with Hirschsprung disease asks what the condition is. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"The muscle at the stomach outlet is too thick.\""}, {"id": "b", "text": "\"Nerve cells are missing from part of the colon.\""}, {"id": "c", "text": "\"Part of the intestine slides into the next part.\""}, {"id": "d", "text": "\"The colon has an infection that blocks the stool.\""}]'::jsonb, '["b"]', 'Hirschsprung disease is a congenital absence of ganglion cells (nerve cells) in part of the colon. The other answers describe different mechanisms.'),
  ('hirschsprung', 34, 'The mother of a newborn with Hirschsprung disease asks, "Did something I did after he was born cause this?" Which response by the nurse is best?', '[{"id": "a", "text": "\"It was caused by the type of formula he was given.\""}, {"id": "b", "text": "\"It developed because he was fed too often.\""}, {"id": "c", "text": "\"It was caused by an infection after delivery.\""}, {"id": "d", "text": "\"It is congenital, so it was present at birth.\""}]'::jsonb, '["d"]', 'Hirschsprung disease is a congenital absence of ganglion cells, also called congenital aganglionic megacolon. It is not caused by feeding choices after birth.'),
  ('hirschsprung', 35, 'The parent of an infant with Hirschsprung disease asks why another child with the same diagnosis had more severe symptoms. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Severity depends on how long the affected segment is.\""}, {"id": "b", "text": "\"Severity depends on how much formula the child takes.\""}, {"id": "c", "text": "\"Severity depends on how many ganglion cells were added.\""}, {"id": "d", "text": "\"Severity is the same for every child with this disease.\""}]'::jsonb, '["a"]', 'The aganglionic segment can extend proximally, and severity depends on the length of the aganglionic segment. Severity is not the same for every child.'),
  ('hirschsprung', 36, 'The nurse is assessing a 3-day-old newborn suspected of having Hirschsprung disease. Which feeding behavior is consistent with this condition?', '[{"id": "a", "text": "Eager feeding with weight gain"}, {"id": "b", "text": "Feeding well with soft stools"}, {"id": "c", "text": "Poor feeding and feeding difficulty"}, {"id": "d", "text": "Rapid feeding followed by hunger"}]'::jsonb, '["c"]', 'Poor feeding or feeding difficulty is a newborn sign of Hirschsprung disease. Eager feeding with weight gain is not one of the listed signs.'),
  ('hirschsprung', 37, 'The nurse is caring for four newborns. Which newborn should the nurse assess first?', '[{"id": "a", "text": "A 12-hour-old who has not yet passed meconium"}, {"id": "b", "text": "A 36-hour-old with green vomiting and a distended abdomen"}, {"id": "c", "text": "A 24-hour-old who passed meconium this morning"}, {"id": "d", "text": "A 20-hour-old who spits up a small amount of milk"}]'::jsonb, '["b"]', 'Bilious vomiting signals a serious obstruction, and with a distended abdomen it suggests Hirschsprung disease. A 12-hour-old without meconium has not yet reached the 48-hour red-flag point.'),
  ('hirschsprung', 38, 'The nurse prepares the parents of an infant for a rectal suction biopsy. Which explanation of the test''s purpose is accurate?', '[{"id": "a", "text": "\"It shows whether the bowel has telescoped.\""}, {"id": "b", "text": "\"It measures how thick the stomach outlet is.\""}, {"id": "c", "text": "\"It pushes stool out of the narrowed bowel.\""}, {"id": "d", "text": "\"It checks the tissue for missing nerve cells.\""}]'::jsonb, '["d"]', 'A rectal suction biopsy is the gold standard because it confirms the absence of ganglion cells (nerve cells). It is a diagnostic test, not a treatment.'),
  ('hirschsprung', 39, 'A barium enema report for an infant with abdominal distension states, "Narrow distal segment with a dilated colon above it." How should the nurse interpret this finding?', '[{"id": "a", "text": "It is consistent with the transition zone of Hirschsprung disease."}, {"id": "b", "text": "It shows that the narrowed bowel has been successfully reduced."}, {"id": "c", "text": "It indicates that the dilated bowel is the aganglionic segment."}, {"id": "d", "text": "It is a normal finding in a newborn with abdominal distension."}]'::jsonb, '["a"]', 'The barium enema in Hirschsprung disease shows a transition zone from the narrow aganglionic segment to the dilated normal colon. The dilated section is normal colon, not the aganglionic segment.'),
  ('hirschsprung', 40, 'The parent of a child scheduled for anorectal manometry asks what the test checks. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It looks for a mass in the upper abdomen.\""}, {"id": "b", "text": "\"It takes a tissue sample from the rectum.\""}, {"id": "c", "text": "\"It checks if the inner anal muscle relaxes.\""}, {"id": "d", "text": "\"It shows the bowel on an ultrasound image.\""}]'::jsonb, '["c"]', 'Anorectal manometry checks the internal anal sphincter relaxation reflex, which is absent in Hirschsprung disease. A tissue sample is obtained by rectal suction biopsy, not manometry.'),
  ('hirschsprung', 41, 'The nurse reviews the documentation of a UAP caring for newborns. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting that a newborn vomited green fluid"}, {"id": "b", "text": "Charting no meconium at 50 hours without telling the nurse"}, {"id": "c", "text": "Telling the nurse that a newborn''s abdomen looks swollen"}, {"id": "d", "text": "Reporting that a newborn is feeding poorly"}]'::jsonb, '["b"]', 'Failure to pass meconium within 48 hours is a red flag that must be reported, not just charted. Reporting green vomiting, distension, and poor feeding is appropriate.'),
  ('hirschsprung', 42, 'The nurse is assessing an infant 2 days after a pull-through procedure. Which finding indicates the return of bowel function?', '[{"id": "a", "text": "The abdomen is becoming more distended."}, {"id": "b", "text": "The infant has developed a new fever."}, {"id": "c", "text": "The infant is vomiting green fluid."}, {"id": "d", "text": "The infant has passed a stool."}]'::jsonb, '["d"]', 'Post-operative care includes watching for the return of bowel function, shown by the passage of stool. Worsening distension and fever are sepsis signs, and bilious vomiting signals obstruction.'),
  ('hirschsprung', 43, 'Which finding is a later sign of Hirschsprung disease rather than a newborn sign?', '[{"id": "a", "text": "Ribbon-like stools"}, {"id": "b", "text": "Bilious vomiting"}, {"id": "c", "text": "No meconium by 48 hours"}, {"id": "d", "text": "Poor feeding"}]'::jsonb, '["a"]', 'Ribbon-like stools are a later sign caused by partial obstruction. Bilious vomiting, failure to pass meconium, and poor feeding are newborn signs.'),
  ('hirschsprung', 44, 'The nurse inspects the abdomen of a 2-day-old newborn suspected of having Hirschsprung disease. Which finding does the nurse expect?', '[{"id": "a", "text": "A sunken, scaphoid abdomen"}, {"id": "b", "text": "An olive-shaped mass"}, {"id": "c", "text": "A distended abdomen"}, {"id": "d", "text": "A sausage-shaped mass"}]'::jsonb, '["c"]', 'A distended abdomen is a newborn sign of Hirschsprung disease. A sunken abdomen is the opposite of this finding.'),
  ('hirschsprung', 45, 'The nurse is teaching the parents of an infant scheduled for a pull-through procedure. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"The section without nerve cells will be taken out.\""}, {"id": "b", "text": "\"The bowel without nerve cells will be joined to the anus.\""}, {"id": "c", "text": "\"Healthy bowel will be connected down to the anus.\""}, {"id": "d", "text": "\"This surgery treats the cause of his blockage.\""}]'::jsonb, '["b"]', 'The pull-through procedure removes the aganglionic segment and connects normal bowel to the anus. Joining the bowel without nerve cells to the anus is incorrect.'),
  ('hirschsprung', 46, 'The nurse teaches the parents of an infant with severe Hirschsprung disease who needs a colostomy. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"The colostomy may be needed because his case is severe.\""}, {"id": "b", "text": "\"The bowel segment without nerve cells still has to be removed.\""}, {"id": "c", "text": "\"Surgery to remove the affected segment is the real cure.\""}, {"id": "d", "text": "\"He will have to keep this colostomy for the rest of his life.\""}]'::jsonb, '["d"]', 'A colostomy in severe Hirschsprung disease is described as temporary. Surgical removal of the aganglionic segment remains the only definitive cure.'),
  ('hirschsprung', 47, 'An abdominal X-ray of a newborn who has not passed meconium shows distended bowel loops with air-fluid levels. How should the nurse interpret this finding?', '[{"id": "a", "text": "It supports a bowel obstruction such as Hirschsprung disease."}, {"id": "b", "text": "It confirms that ganglion cells are present in the rectum."}, {"id": "c", "text": "It is a normal finding in a newborn who has not fed yet."}, {"id": "d", "text": "It shows that the bowel obstruction has fully resolved."}]'::jsonb, '["a"]', 'Distended bowel loops and air-fluid levels on abdominal X-ray are expected findings in Hirschsprung disease. Ganglion cells are evaluated by rectal biopsy, not X-ray.'),
  ('hirschsprung', 48, 'A nursing student is reviewing Hirschsprung disease. Which statement by the student requires correction?', '[{"id": "a", "text": "\"The affected segment of colon has no ganglion cells.\""}, {"id": "b", "text": "\"The affected segment can extend further up the colon.\""}, {"id": "c", "text": "\"Every child has the same length of affected bowel.\""}, {"id": "d", "text": "\"The affected segment cannot relax to move stool.\""}]'::jsonb, '["c"]', 'The aganglionic segment can extend proximally, and severity depends on its length, so the length is not the same for every child. The other statements are accurate.'),
  ('hirschsprung', 49, 'An infant with Hirschsprung disease has developed enterocolitis. The nurse monitors closely because this complication can suddenly progress to:', '[{"id": "a", "text": "a thickened pyloric muscle."}, {"id": "b", "text": "septic shock."}, {"id": "c", "text": "a telescoped bowel segment."}, {"id": "d", "text": "a return of normal stools."}]'::jsonb, '["b"]', 'Hirschsprung-associated enterocolitis is a bowel infection leading to sepsis that can cause sudden septic shock. It is the most deadly complication of the disease.'),
  ('hirschsprung', 50, 'A nursing student asks why the colon above the affected segment becomes enlarged in Hirschsprung disease. Which explanation by the nurse is correct?', '[{"id": "a", "text": "The normal colon has no ganglion cells."}, {"id": "b", "text": "The affected segment is too relaxed to hold stool."}, {"id": "c", "text": "Infection causes the colon wall to swell."}, {"id": "d", "text": "Stool cannot pass the contracted segment."}]'::jsonb, '["d"]', 'The aganglionic segment stays contracted, so stool cannot pass, causing obstruction and dilation of the bowel above it. The affected segment is contracted, not relaxed.'),
  ('cf', 1, 'Parents of an infant newly diagnosed with cystic fibrosis (CF) ask how their child developed the disorder. Which response by the nurse is accurate?', '[{"id": "a", "text": "It results from an autosomal dominant CFTR gene mutation."}, {"id": "b", "text": "It results from an infection acquired before birth."}, {"id": "c", "text": "It results from an autosomal recessive CFTR gene mutation."}, {"id": "d", "text": "It results from a lack of fat-soluble vitamins in pregnancy."}]'::jsonb, '["c"]', 'CF is caused by an autosomal recessive CFTR gene mutation. Infections and fat-soluble vitamin deficiencies are consequences of the thick mucus, not the cause.'),
  ('cf', 2, 'A nursing student asks why secretions become so thick in cystic fibrosis. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Abnormal chloride transport dehydrates the body''s secretions."}, {"id": "b", "text": "Excess sodium is retained in the sweat and airway secretions."}, {"id": "c", "text": "Overactive pancreatic enzymes thicken the body''s mucus."}, {"id": "d", "text": "Chronic hypoxia causes the mucus glands to enlarge."}]'::jsonb, '["a"]', 'The defective CFTR gene causes abnormal chloride transport, which dehydrates secretions and produces thick mucus. Sodium chloride is lost in sweat, not retained.'),
  ('cf', 3, 'A child with cystic fibrosis has pancreatic ducts obstructed by thick mucus. The nurse anticipates malabsorption of which nutrients?', '[{"id": "a", "text": "Water-soluble vitamins only"}, {"id": "b", "text": "Fats, proteins, and fat-soluble vitamins"}, {"id": "c", "text": "Simple sugars and free water"}, {"id": "d", "text": "Sodium, chloride, and potassium"}]'::jsonb, '["b"]', 'Pancreatic duct obstruction causes malabsorption of fats, proteins, and fat-soluble vitamins (A, D, E, K). Water-soluble vitamins are not the vitamins affected.'),
  ('cf', 4, 'The nurse is assessing a newborn suspected of having cystic fibrosis. Which finding is often the first sign of the disease in newborns?', '[{"id": "a", "text": "Clubbing of the fingers"}, {"id": "b", "text": "Barrel-shaped chest"}, {"id": "c", "text": "Nasal polyps"}, {"id": "d", "text": "Meconium ileus"}]'::jsonb, '["d"]', 'Meconium ileus, thick stool blocking the intestines, is the first sign of CF in newborns. Clubbing and barrel chest are late signs.'),
  ('cf', 5, 'A newborn with suspected cystic fibrosis has abdominal distention and has not passed meconium. The nurse recognizes that the most likely cause is', '[{"id": "a", "text": "overproduction of loose, watery stool."}, {"id": "b", "text": "toxicity from excess fat-soluble vitamins."}, {"id": "c", "text": "thick meconium obstructing the intestines."}, {"id": "d", "text": "swelling of the upper airway."}]'::jsonb, '["c"]', 'In CF, thick mucus in the GI tract causes meconium ileus in newborns, a thick stool that blocks the intestines. CF stools are thick and fatty, not watery.'),
  ('cf', 6, 'The parent of a toddler with cystic fibrosis describes the child''s stools. Which description should the nurse expect?', '[{"id": "a", "text": "Black and tarry"}, {"id": "b", "text": "Small, hard, and dry"}, {"id": "c", "text": "Watery and odorless"}, {"id": "d", "text": "Fatty and foul-smelling"}]'::jsonb, '["d"]', 'Fat malabsorption in CF causes steatorrhea, which is fatty, foul-smelling stool.'),
  ('cf', 7, 'The parent of a 2-year-old with cystic fibrosis says, ''He eats all the time, but he keeps losing weight.'' How should the nurse interpret this finding?', '[{"id": "a", "text": "It shows that the disease is going into remission."}, {"id": "b", "text": "It suggests the child is receiving too much enzyme."}, {"id": "c", "text": "It indicates that the child needs fewer calories."}, {"id": "d", "text": "It reflects failure to thrive from malabsorption."}]'::jsonb, '["d"]', 'Failure to thrive in CF is weight loss despite a good appetite, caused by malabsorption from pancreatic insufficiency. The child needs a high-calorie diet, not fewer calories.'),
  ('cf', 8, 'The parent of an infant reports that the baby''s skin tastes salty when kissed. The nurse explains that this occurs because of', '[{"id": "a", "text": "retention of sodium by the kidneys."}, {"id": "b", "text": "excess salt added to the infant formula."}, {"id": "c", "text": "increased loss of sodium chloride in sweat."}, {"id": "d", "text": "decreased activity of the sweat glands."}]'::jsonb, '["c"]', 'In CF, the sweat glands lose increased sodium chloride, producing salty-tasting skin.'),
  ('cf', 9, 'While assessing a 14-year-old with long-standing cystic fibrosis, the nurse notes clubbing of the fingers. The nurse recognizes this finding as a', '[{"id": "a", "text": "late sign of chronic hypoxia."}, {"id": "b", "text": "first sign of pancreatic failure."}, {"id": "c", "text": "sign of fat-soluble vitamin excess."}, {"id": "d", "text": "finding expected in all newborns with CF."}]'::jsonb, '["a"]', 'Clubbing of the fingers is a late sign of chronic hypoxia in CF. The first sign in newborns is meconium ileus, not clubbing.'),
  ('cf', 10, 'Which finding in a client with cystic fibrosis does the nurse recognize as a late sign of the disease?', '[{"id": "a", "text": "Meconium ileus"}, {"id": "b", "text": "Salty-tasting skin"}, {"id": "c", "text": "Steatorrhea"}, {"id": "d", "text": "Barrel chest"}]'::jsonb, '["d"]', 'Barrel chest is a late sign of CF. Meconium ileus is the first sign in newborns, and salty skin and steatorrhea are not described as late signs.'),
  ('cf', 11, 'The nurse is assessing a school-age child admitted with cystic fibrosis. Which respiratory finding is expected?', '[{"id": "a", "text": "Occasional cough with thin, watery sputum"}, {"id": "b", "text": "Clear breath sounds without any wheezing"}, {"id": "c", "text": "Chronic cough with thick sputum"}, {"id": "d", "text": "Rare respiratory infections"}]'::jsonb, '["c"]', 'Children with CF have a chronic cough with thick sputum, wheezing, and recurrent infections. Thin, watery sputum is the opposite of the thick mucus of CF.'),
  ('cf', 12, 'Which additional assessment finding would the nurse expect in a child with cystic fibrosis?', '[{"id": "a", "text": "Thin, watery airway secretions"}, {"id": "b", "text": "Nasal polyps with sinus infections"}, {"id": "c", "text": "Low sodium content in the sweat"}, {"id": "d", "text": "Weight gain with a poor appetite"}]'::jsonb, '["b"]', 'Nasal polyps and sinus infections are respiratory findings in CF. Sweat in CF has increased sodium chloride loss, and secretions are thick.'),
  ('cf', 13, 'The nurse is reinforcing teaching for the parents of a child with cystic fibrosis. Which vitamins should the nurse explain need to be supplemented?', '[{"id": "a", "text": "Vitamins A, D, E, and K"}, {"id": "b", "text": "Vitamins B1, B6, and B12"}, {"id": "c", "text": "Vitamin C and folic acid"}, {"id": "d", "text": "Vitamins B2, B3, and C"}]'::jsonb, '["a"]', 'Fat malabsorption in CF causes deficiencies of the fat-soluble vitamins A, D, E, and K, which are supplemented.'),
  ('cf', 14, 'The nurse is planning ongoing monitoring for an adolescent with cystic fibrosis and pancreatic insufficiency. The nurse should monitor for which complication?', '[{"id": "a", "text": "Excess fat-soluble vitamins"}, {"id": "b", "text": "CF-related diabetes"}, {"id": "c", "text": "Oversecretion of pancreatic enzymes"}, {"id": "d", "text": "Excessive weight gain"}]'::jsonb, '["b"]', 'Pancreatic insufficiency in CF can lead to CF-related diabetes (CFRD), so the nurse monitors for it. Pancreatic insufficiency means reduced, not excess, enzyme output.'),
  ('cf', 15, 'A 7-year-old has a sweat chloride test result of 72 mmol/L. How should the nurse interpret this result?', '[{"id": "a", "text": "It is too low to support cystic fibrosis."}, {"id": "b", "text": "It indicates pancreatic insufficiency only."}, {"id": "c", "text": "It confirms CF-related diabetes."}, {"id": "d", "text": "It is consistent with cystic fibrosis."}]'::jsonb, '["d"]', 'A sweat chloride level greater than 60 mmol/L in children is diagnostic of CF. Pancreatic insufficiency is checked with a fecal elastase test, not a sweat test.'),
  ('cf', 16, 'Which test does the nurse anticipate as the gold standard for diagnosing cystic fibrosis in a child?', '[{"id": "a", "text": "Fecal elastase test"}, {"id": "b", "text": "Chest X-ray"}, {"id": "c", "text": "Sweat chloride test"}, {"id": "d", "text": "Pulmonary function tests"}]'::jsonb, '["c"]', 'The sweat chloride test is the gold standard for CF diagnosis. Fecal elastase checks pancreatic insufficiency, and chest X-ray and PFTs show lung changes.'),
  ('cf', 17, 'A provider orders a fecal elastase test for a child with cystic fibrosis. The nurse explains to the parent that this test is used to', '[{"id": "a", "text": "confirm the CFTR gene mutation."}, {"id": "b", "text": "measure the chloride in sweat."}, {"id": "c", "text": "identify hyperinflation of the lungs."}, {"id": "d", "text": "check for pancreatic insufficiency."}]'::jsonb, '["d"]', 'The fecal elastase test checks for pancreatic insufficiency. The CFTR mutation is identified by genetic testing, and sweat chloride by the sweat test.'),
  ('cf', 18, 'Which pulmonary function test result does the nurse expect in a client with cystic fibrosis?', '[{"id": "a", "text": "Reduced FEV1 with an obstructive pattern"}, {"id": "b", "text": "Increased FEV1 with a normal pattern"}, {"id": "c", "text": "Reduced FEV1 with a restrictive pattern"}, {"id": "d", "text": "Increased FEV1 with an obstructive pattern"}]'::jsonb, '["a"]', 'PFTs in CF show a reduced FEV1 and an obstructive pattern, reflecting airway obstruction by thick mucus.'),
  ('cf', 19, 'The nurse reviews a chest X-ray report for an adolescent with cystic fibrosis. Which findings are expected?', '[{"id": "a", "text": "Small, underinflated lung fields"}, {"id": "b", "text": "Clear lungs with no changes"}, {"id": "c", "text": "Enlarged heart with clear lungs"}, {"id": "d", "text": "Hyperinflation and mucus plugging"}]'::jsonb, '["d"]', 'Chest X-ray in CF shows hyperinflation, mucus plugging, and bronchiectasis. Underinflated or clear lungs are not the expected findings.'),
  ('cf', 20, 'Besides the sweat chloride test, which diagnostic test identifies the underlying cause of cystic fibrosis?', '[{"id": "a", "text": "Fecal elastase testing"}, {"id": "b", "text": "Genetic testing for a CFTR mutation"}, {"id": "c", "text": "Chest X-ray imaging"}, {"id": "d", "text": "Pulmonary function testing"}]'::jsonb, '["b"]', 'CF is caused by a CFTR gene mutation, which genetic testing identifies. Fecal elastase checks pancreatic insufficiency, and X-ray and PFTs show lung effects.'),
  ('cf', 21, 'The nurse is planning morning care for a child with cystic fibrosis who has thick secretions and a productive cough. Which intervention is the priority?', '[{"id": "a", "text": "Give fat-soluble vitamin supplements."}, {"id": "b", "text": "Perform airway clearance therapy."}, {"id": "c", "text": "Offer a high-calorie, high-protein snack."}, {"id": "d", "text": "Teach about increasing salt intake."}]'::jsonb, '["b"]', 'Airway clearance is always the priority in CF. Vitamins, high-calorie snacks, and salt teaching are important but come after clearing the airway.'),
  ('cf', 22, 'Which nursing action is part of chest physiotherapy (CPT) for a child with cystic fibrosis?', '[{"id": "a", "text": "Postural drainage, percussion, and vibration"}, {"id": "b", "text": "Inhaled bronchodilator, then inhaled antibiotic"}, {"id": "c", "text": "Nebulized dornase alfa and hypertonic saline"}, {"id": "d", "text": "High-calorie, high-protein snacks"}]'::jsonb, '["a"]', 'CPT consists of postural drainage, percussion, and vibration. Bronchodilators, mucolytics, and antibiotics are inhaled medications given around CPT, not CPT itself.'),
  ('cf', 23, 'A parent asks about the high-frequency chest wall oscillation vest prescribed for a child with cystic fibrosis. The nurse explains that the vest is used for', '[{"id": "a", "text": "airway clearance."}, {"id": "b", "text": "pancreatic enzyme delivery."}, {"id": "c", "text": "sweat chloride testing."}, {"id": "d", "text": "inhaled antibiotic delivery."}]'::jsonb, '["a"]', 'Vest therapy is a method of airway clearance, which is the priority in CF. Inhaled antibiotics are given separately, after airway clearance.'),
  ('cf', 24, 'An adolescent with cystic fibrosis is prescribed an Acapella device. The nurse explains that this device is used to', '[{"id": "a", "text": "deliver the inhaled tobramycin."}, {"id": "b", "text": "measure sweat chloride levels."}, {"id": "c", "text": "help clear mucus from the airways."}, {"id": "d", "text": "monitor blood glucose for CFRD."}]'::jsonb, '["c"]', 'The Acapella is a positive expiratory pressure (PEP) device, one of the airway clearance methods used in CF.'),
  ('cf', 25, 'A child with cystic fibrosis is scheduled for chest physiotherapy. Which medication should the nurse administer before the treatment?', '[{"id": "a", "text": "Tobramycin"}, {"id": "b", "text": "Albuterol"}, {"id": "c", "text": "Pancrelipase"}, {"id": "d", "text": "Ivacaftor"}]'::jsonb, '["b"]', 'A bronchodilator such as albuterol is given before chest physiotherapy to open the airways. Inhaled tobramycin is given last, after airway clearance.'),
  ('cf', 26, 'The nurse is preparing a child''s morning respiratory treatments for cystic fibrosis. In which order should they be given?', '[{"id": "a", "text": "Albuterol, dornase alfa, chest physiotherapy, inhaled tobramycin"}, {"id": "b", "text": "Dornase alfa, albuterol, inhaled tobramycin, chest physiotherapy"}, {"id": "c", "text": "Inhaled tobramycin, albuterol, dornase alfa, chest physiotherapy"}, {"id": "d", "text": "Chest physiotherapy, albuterol, inhaled tobramycin, dornase alfa"}]'::jsonb, '["a"]', 'The correct order is bronchodilator, mucolytic, airway clearance (CPT), then inhaled antibiotic. Giving the antibiotic before CPT is incorrect because it is given last.'),
  ('cf', 27, 'Which action by a new nurse caring for a child with cystic fibrosis requires correction?', '[{"id": "a", "text": "Giving inhaled tobramycin before chest physiotherapy"}, {"id": "b", "text": "Giving albuterol before chest physiotherapy"}, {"id": "c", "text": "Giving pancrelipase with the child''s lunch"}, {"id": "d", "text": "Performing hand hygiene before entering"}]'::jsonb, '["a"]', 'Inhaled antibiotics such as tobramycin are given last, after all airway clearance. Giving albuterol before CPT and enzymes with meals are correct actions.'),
  ('cf', 28, 'A child with cystic fibrosis is prescribed albuterol, hypertonic saline (7%), vest therapy, and inhaled tobramycin. Which treatment should be given second?', '[{"id": "a", "text": "Albuterol"}, {"id": "b", "text": "Vest therapy"}, {"id": "c", "text": "Inhaled tobramycin"}, {"id": "d", "text": "Hypertonic saline"}]'::jsonb, '["d"]', 'The sequence is bronchodilator first, mucolytic (such as hypertonic saline) second, airway clearance third, and inhaled antibiotic last.'),
  ('cf', 29, 'A parent asks how dornase alfa (Pulmozyme) helps their child with cystic fibrosis. The nurse explains that this medication', '[{"id": "a", "text": "breaks down DNA in thick mucus."}, {"id": "b", "text": "opens up the narrowed airways."}, {"id": "c", "text": "treats Pseudomonas infection."}, {"id": "d", "text": "replaces pancreatic enzymes."}]'::jsonb, '["a"]', 'Dornase alfa is a mucolytic that breaks down DNA in thick mucus. Opening the airways is the action of a bronchodilator such as albuterol.'),
  ('cf', 30, 'A child with cystic fibrosis has very thick, tenacious secretions. Which medication does the nurse anticipate will be prescribed to thin the mucus?', '[{"id": "a", "text": "Albuterol"}, {"id": "b", "text": "Pancrelipase (Creon)"}, {"id": "c", "text": "Dornase alfa (Pulmozyme)"}, {"id": "d", "text": "Tobramycin"}]'::jsonb, '["c"]', 'Dornase alfa is the mucolytic enzyme that breaks down DNA in thick mucus. Albuterol opens airways, and tobramycin treats Pseudomonas infection.'),
  ('cf', 31, 'Nebulized hypertonic saline (7%) is prescribed for a child with cystic fibrosis. The nurse explains that its purpose is to', '[{"id": "a", "text": "hydrate the airways."}, {"id": "b", "text": "treat Pseudomonas infection."}, {"id": "c", "text": "replace sodium lost in sweat."}, {"id": "d", "text": "replace pancreatic enzymes."}]'::jsonb, '["a"]', 'Hypertonic saline (7%) hydrates the airways as a mucolytic step. Sodium lost in sweat is replaced through increased dietary salt intake.'),
  ('cf', 32, 'A nursing student asks why albuterol is the first inhaled medication given to a child with cystic fibrosis. The nurse explains that albuterol', '[{"id": "a", "text": "thins the mucus."}, {"id": "b", "text": "opens the airways."}, {"id": "c", "text": "treats the infection."}, {"id": "d", "text": "hydrates the airways."}]'::jsonb, '["b"]', 'Albuterol is a bronchodilator given first to open the airways. Thinning mucus is the role of the mucolytic given second.'),
  ('cf', 33, 'The nurse is teaching the parent of a child with cystic fibrosis about pancrelipase (Creon). When should the parent give this medication?', '[{"id": "a", "text": "One hour before each meal"}, {"id": "b", "text": "One hour after each meal"}, {"id": "c", "text": "With each meal and snack"}, {"id": "d", "text": "Once daily at bedtime"}]'::jsonb, '["c"]', 'Pancreatic enzymes are given with meals and snacks, not before or after.'),
  ('cf', 34, 'Which statement by the parent of a child with cystic fibrosis indicates a need for further teaching about pancrelipase?', '[{"id": "a", "text": "I''ll give it with his afternoon snack."}, {"id": "b", "text": "I''ll give it after he finishes his dinner."}, {"id": "c", "text": "I''ll sprinkle it on his applesauce."}, {"id": "d", "text": "I''ll give it with his breakfast."}]'::jsonb, '["b"]', 'Pancrelipase is taken with meals and snacks, not after eating. Sprinkling it on applesauce is correct because acidic foods protect enzyme activity.'),
  ('cf', 35, 'A toddler with cystic fibrosis cannot swallow pancrelipase capsules. Which instruction should the nurse give the parent?', '[{"id": "a", "text": "Skip doses until he can swallow capsules."}, {"id": "b", "text": "Sprinkle the capsule contents on applesauce."}, {"id": "c", "text": "Give the capsule contents after the meal."}, {"id": "d", "text": "Mix the contents in water an hour before eating."}]'::jsonb, '["b"]', 'Pancreatic enzymes can be sprinkled on acidic foods such as applesauce to protect enzyme activity. They are given with meals, not before or after.'),
  ('cf', 36, 'A parent asks why pancreatic enzyme beads should be mixed with applesauce. The nurse explains that the acidic food', '[{"id": "a", "text": "replaces fat-soluble vitamins."}, {"id": "b", "text": "improves salt absorption."}, {"id": "c", "text": "thins the airway mucus."}, {"id": "d", "text": "protects the enzyme activity."}]'::jsonb, '["d"]', 'Sprinkling enzymes on acidic foods like applesauce protects enzyme activity.'),
  ('cf', 37, 'Which diet should the nurse recommend for a child with cystic fibrosis?', '[{"id": "a", "text": "Low-calorie, high-protein"}, {"id": "b", "text": "Low-fat, low-calorie"}, {"id": "c", "text": "High-calorie, high-protein"}, {"id": "d", "text": "High-calorie, low-protein"}]'::jsonb, '["c"]', 'Children with CF need a high-calorie, high-protein diet because of malabsorption and failure to thrive.'),
  ('cf', 38, 'Which instruction about salt is appropriate for the parent of a child with cystic fibrosis?', '[{"id": "a", "text": "Restrict salt to prevent fluid retention."}, {"id": "b", "text": "Avoid salty snacks to protect the lungs."}, {"id": "c", "text": "Increase salt intake to replace sodium loss."}, {"id": "d", "text": "Limit salt because the skin is salty."}]'::jsonb, '["c"]', 'Increased salt intake compensates for the sodium lost in sweat. Salty skin reflects sodium loss, so salt should not be limited.'),
  ('cf', 39, 'Which statement by an adolescent with cystic fibrosis indicates a need for further teaching about nutrition?', '[{"id": "a", "text": "I should eat frequent meals and snacks."}, {"id": "b", "text": "I should choose high-protein foods."}, {"id": "c", "text": "I should eat three small meals and skip snacks."}, {"id": "d", "text": "I should add extra salt to my food."}]'::jsonb, '["c"]', 'Nutrition in CF includes frequent meals and snacks with high calories and protein, plus increased salt. Skipping snacks contradicts this teaching.'),
  ('cf', 40, 'The parent of a 10-year-old with cystic fibrosis is concerned about the child''s short stature and slow growth. Which response by the nurse is appropriate?', '[{"id": "a", "text": "Growth will improve if you limit fat in the diet."}, {"id": "b", "text": "Slow growth is not related to cystic fibrosis."}, {"id": "c", "text": "The child should stop taking pancreatic enzymes."}, {"id": "d", "text": "The child may need supplemental tube feedings at night."}]'::jsonb, '["d"]', 'Malnutrition is common in CF, and a child with short stature and slow growth may need supplemental nighttime tube feedings. Limiting calories or enzymes would worsen malnutrition.'),
  ('cf', 41, 'A child with cystic fibrosis remains severely malnourished despite frequent high-calorie meals. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "A switch to a low-protein diet"}, {"id": "b", "text": "Fewer snacks between meals"}, {"id": "c", "text": "Nasogastric or gastrostomy tube feedings"}, {"id": "d", "text": "Stopping fat-soluble vitamins"}]'::jsonb, '["c"]', 'NG or GT tube feedings are used for severe malnutrition in CF. A low-protein diet or fewer snacks contradicts the high-calorie, high-protein, frequent-feeding plan.'),
  ('cf', 42, 'The parent of a child with cystic fibrosis calls the clinic. Which report should the nurse recognize as a possible respiratory infection?', '[{"id": "a", "text": "Salty-tasting skin after playing outside"}, {"id": "b", "text": "Low-grade fever and increased coughing"}, {"id": "c", "text": "Good appetite with frequent snacking"}, {"id": "d", "text": "Sleeping well through the night"}]'::jsonb, '["b"]', 'The nurse monitors for respiratory infections in CF, indicated by low-grade fever and increased cough. Salty skin is an expected finding of CF itself.'),
  ('cf', 43, 'A charge nurse is making room assignments on a pediatric unit. Which action requires correction?', '[{"id": "a", "text": "Using contact precautions for resistant bacteria"}, {"id": "b", "text": "Performing hand hygiene between clients"}, {"id": "c", "text": "Placing a child with CF in a private room"}, {"id": "d", "text": "Placing two children with cystic fibrosis in one room"}]'::jsonb, '["d"]', 'Infection control in CF includes avoiding contact with other CF patients, so two children with CF should not share a room.'),
  ('cf', 44, 'A child with cystic fibrosis is colonized with resistant bacteria. Which isolation precautions should the nurse implement?', '[{"id": "a", "text": "Contact precautions"}, {"id": "b", "text": "Airborne precautions"}, {"id": "c", "text": "Droplet precautions"}, {"id": "d", "text": "No precautions"}]'::jsonb, '["a"]', 'Infection control in CF includes hand hygiene and contact precautions for resistant bacteria.'),
  ('cf', 45, 'An adolescent with cystic fibrosis is prescribed ivacaftor (Kalydeco). The nurse identifies this medication as a', '[{"id": "a", "text": "mucolytic."}, {"id": "b", "text": "CFTR modulator."}, {"id": "c", "text": "bronchodilator."}, {"id": "d", "text": "pancreatic enzyme."}]'::jsonb, '["b"]', 'Ivacaftor (Kalydeco) is a CFTR modulator. Dornase alfa is the mucolytic, albuterol the bronchodilator, and pancrelipase the enzyme replacement.'),
  ('cf', 46, 'A child with cystic fibrosis is prescribed inhaled aztreonam. The nurse recognizes that this medication is used to treat infection with which organism?', '[{"id": "a", "text": "Pseudomonas aeruginosa"}, {"id": "b", "text": "Candida albicans"}, {"id": "c", "text": "Clostridioides difficile"}, {"id": "d", "text": "Escherichia coli"}]'::jsonb, '["a"]', 'Inhaled tobramycin and aztreonam are used for Pseudomonas infections, one of the recurrent infections in CF.'),
  ('cf', 47, 'A 16-year-old male with cystic fibrosis asks whether the disease affects his reproductive health. Which response by the nurse is accurate?', '[{"id": "a", "text": "The reproductive organs are not affected by this disease."}, {"id": "b", "text": "Infertility is common from an absent or blocked vas deferens."}, {"id": "c", "text": "Infertility occurs only in females with this disease."}, {"id": "d", "text": "Infertility results from high sweat chloride levels."}]'::jsonb, '["b"]', 'CF causes male infertility because the vas deferens is absent or obstructed. Females are also affected, by thick cervical mucus.'),
  ('cf', 48, 'A young woman with cystic fibrosis asks how the disease can affect female reproduction. Which response by the nurse is accurate?', '[{"id": "a", "text": "It causes an absent vas deferens."}, {"id": "b", "text": "It can cause thick cervical mucus."}, {"id": "c", "text": "It produces thin reproductive mucus."}, {"id": "d", "text": "It does not affect reproduction."}]'::jsonb, '["b"]', 'In females, CF causes thick cervical mucus. An absent or obstructed vas deferens is the male reproductive effect.'),
  ('cf', 49, 'A school-age child with cystic fibrosis reports abdominal pain and has not had a bowel movement in several days. The nurse recognizes the child is at risk for which complication?', '[{"id": "a", "text": "Meconium ileus"}, {"id": "b", "text": "Excess vitamin absorption"}, {"id": "c", "text": "Salt overload"}, {"id": "d", "text": "Bowel obstruction"}]'::jsonb, '["d"]', 'Thick mucus in the GI tract places clients with CF at risk for bowel obstruction. Meconium ileus is the form seen in newborns.'),
  ('cf', 50, 'When auscultating the lungs of a child with cystic fibrosis and airway obstruction, which finding should the nurse expect?', '[{"id": "a", "text": "Wheezing with dyspnea"}, {"id": "b", "text": "Clear breath sounds bilaterally"}, {"id": "c", "text": "Dry cough without sputum"}, {"id": "d", "text": "Slow, easy respirations"}]'::jsonb, '["a"]', 'Respiratory symptoms of CF include wheezing and dyspnea from thick mucus and airway obstruction. A dry cough is not expected because CF causes thick sputum.'),
  ('epiglottitis', 1, 'A 4-year-old arrives at the emergency department with a sudden high fever, drooling, and a muffled voice and is sitting upright, leaning forward. Which action should the nurse take first?', '[{"id": "a", "text": "Inspect the throat using a tongue blade."}, {"id": "b", "text": "Notify the provider and prepare airway equipment."}, {"id": "c", "text": "Obtain a throat swab for culture."}, {"id": "d", "text": "Take an oral temperature reading."}]'::jsonb, '["b"]', 'When epiglottitis is suspected, the priority is to notify the provider immediately and prepare airway equipment. Tongue blades, throat swabs, and oral temperatures are all contraindicated.'),
  ('epiglottitis', 2, 'A nursing student is caring for a child with suspected epiglottitis. Which action by the student requires the nurse to intervene?', '[{"id": "a", "text": "Allowing the child to sit leaning forward"}, {"id": "b", "text": "Staying at the bedside with the child"}, {"id": "c", "text": "Keeping airway equipment within reach"}, {"id": "d", "text": "Getting a tongue depressor to look at the throat"}]'::jsonb, '["d"]', 'Tongue blades and oral exams must not be used because they can trigger complete airway obstruction. Allowing tripod positioning and staying with the child are correct.'),
  ('epiglottitis', 3, 'The parent of a child with suspected epiglottitis asks why no one will look in the child''s throat. Which response by the nurse is best?', '[{"id": "a", "text": "The swelling makes the throat impossible to see."}, {"id": "b", "text": "A throat exam could cause a spasm that blocks the airway."}, {"id": "c", "text": "A throat exam is needed only after the fever breaks."}, {"id": "d", "text": "Looking at the throat would be too painful for her."}]'::jsonb, '["b"]', 'Oral exams can trigger complete airway obstruction due to reflex spasm, so the throat is not examined.'),
  ('epiglottitis', 4, 'The nurse receives prescriptions for a child with suspected epiglottitis. Which prescription should the nurse question?', '[{"id": "a", "text": "Obtain a throat swab for culture."}, {"id": "b", "text": "Administer IV ceftriaxone."}, {"id": "c", "text": "Administer humidified oxygen as needed."}, {"id": "d", "text": "Draw blood cultures."}]'::jsonb, '["a"]', 'Throat swabs are not done in epiglottitis. The causative organism is identified with blood cultures, and IV ceftriaxone and humidified oxygen are appropriate.'),
  ('epiglottitis', 5, 'Which action by an unlicensed assistive personnel (UAP) caring for a child with suspected epiglottitis requires correction?', '[{"id": "a", "text": "Remaining in the room with the child"}, {"id": "b", "text": "Monitoring the child''s oxygen saturation"}, {"id": "c", "text": "Speaking calmly to the child"}, {"id": "d", "text": "Taking the child''s temperature orally"}]'::jsonb, '["d"]', 'Oral temperatures are not taken in suspected epiglottitis. Staying with the child, keeping the child calm, and monitoring oxygen saturation are appropriate.'),
  ('epiglottitis', 6, 'A child with epiglottitis is sitting upright, leaning forward with the chin up and mouth open. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Allow the child to remain in this position."}, {"id": "b", "text": "Place the child supine to ease breathing."}, {"id": "c", "text": "Lay the child flat for a throat exam."}, {"id": "d", "text": "Turn the child to a side-lying position."}]'::jsonb, '["a"]', 'The nurse should allow tripod positioning in epiglottitis. Laying the child flat for a throat exam is unsafe because oral exams are contraindicated.'),
  ('epiglottitis', 7, 'The nurse documents that a child with suspected epiglottitis is in the tripod position. Which description matches this finding?', '[{"id": "a", "text": "Lying supine with the head flat"}, {"id": "b", "text": "Lying on the side with knees flexed"}, {"id": "c", "text": "Leaning forward with chin up and mouth open"}, {"id": "d", "text": "Sitting back with the chin tucked down"}]'::jsonb, '["c"]', 'The tripod position in epiglottitis is leaning forward with the chin up and the mouth open.'),
  ('epiglottitis', 8, 'While awaiting the provider, the nurse caring for a child with suspected epiglottitis realizes the airway supplies are in another room. Which action is best?', '[{"id": "a", "text": "Leave briefly to gather the supplies."}, {"id": "b", "text": "Stay with the child and call for the supplies."}, {"id": "c", "text": "Ask the parent to watch the child and leave."}, {"id": "d", "text": "Walk the child to the supply room."}]'::jsonb, '["b"]', 'The nurse must stay with the child at all times and not leave the child alone, while ensuring emergency airway equipment is prepared.'),
  ('epiglottitis', 9, 'Which nursing intervention is most appropriate for a crying, anxious toddler with suspected epiglottitis?', '[{"id": "a", "text": "Restrain the child to inspect the mouth."}, {"id": "b", "text": "Encourage the child to cough forcefully."}, {"id": "c", "text": "Keep the child calm and comforted."}, {"id": "d", "text": "Lay the child down in a quiet room."}]'::jsonb, '["c"]', 'The nurse keeps the child calm because crying worsens swelling. Restraining the child for a mouth exam is contraindicated.'),
  ('epiglottitis', 10, 'Which intervention should the nurse include in the plan of care for a child with epiglottitis?', '[{"id": "a", "text": "Take oral temperatures every 4 hours."}, {"id": "b", "text": "Inspect the throat with a tongue blade."}, {"id": "c", "text": "Administer humidified oxygen as needed."}, {"id": "d", "text": "Place the child flat in bed to rest."}]'::jsonb, '["c"]', 'Humidified oxygen is administered as needed in epiglottitis. Oral temperatures and tongue blades are contraindicated.'),
  ('epiglottitis', 11, 'Which assessments should the nurse monitor most closely in a child with epiglottitis?', '[{"id": "a", "text": "Throat appearance, oral temperature, and gag reflex"}, {"id": "b", "text": "Pupil size, deep tendon reflexes, and grip strength"}, {"id": "c", "text": "Oxygen saturation, respiratory effort, and level of consciousness"}, {"id": "d", "text": "Bowel sounds, abdominal girth, and stool pattern"}]'::jsonb, '["c"]', 'The nurse monitors O2 saturation, respiratory effort, and LOC. Examining the throat or taking oral temperatures is contraindicated.'),
  ('epiglottitis', 12, 'Which finding helps the nurse distinguish epiglottitis from croup?', '[{"id": "a", "text": "Inspiratory stridor"}, {"id": "b", "text": "A barky, seal-like cough"}, {"id": "c", "text": "Absence of a cough"}, {"id": "d", "text": "Gradual onset of symptoms"}]'::jsonb, '["c"]', 'No cough is the key distinguishing feature of epiglottitis. Inspiratory stridor occurs in both conditions, while a barky cough and gradual onset suggest croup.'),
  ('epiglottitis', 13, 'Two children with stridor arrive at the emergency department. Which finding suggests croup rather than epiglottitis?', '[{"id": "a", "text": "Drooling and a muffled voice"}, {"id": "b", "text": "A high fever with sudden onset"}, {"id": "c", "text": "A barky, seal-like cough"}, {"id": "d", "text": "Sitting in the tripod position"}]'::jsonb, '["c"]', 'Croup produces a barky, seal-like cough, while cough is absent in epiglottitis. Drooling, high fever, sudden onset, and tripod position point to epiglottitis.'),
  ('epiglottitis', 14, 'The nurse is triaging four children in the emergency department. Which child should the nurse see first?', '[{"id": "a", "text": "A 3-year-old drooling in the tripod position with no cough"}, {"id": "b", "text": "A 2-year-old with a barky cough and a mild fever"}, {"id": "c", "text": "A 3-year-old with a gradual-onset cough and normal posture"}, {"id": "d", "text": "A 4-year-old with a seal-like cough and no drooling"}]'::jsonb, '["a"]', 'Drooling, tripod position, and absent cough indicate epiglottitis, which is a true airway emergency. Croup, with its barky cough, is less likely to be an airway emergency.'),
  ('epiglottitis', 15, 'Which history finding is most consistent with epiglottitis rather than croup?', '[{"id": "a", "text": "Symptoms that began suddenly"}, {"id": "b", "text": "Symptoms that developed gradually"}, {"id": "c", "text": "A barky cough that worsened"}, {"id": "d", "text": "A mild fever for several days"}]'::jsonb, '["a"]', 'Epiglottitis has a sudden onset with acute symptoms, whereas croup has a gradual onset, barky cough, and mild fever.'),
  ('epiglottitis', 16, 'Which temperature finding does the nurse expect in a child with epiglottitis?', '[{"id": "a", "text": "High fever"}, {"id": "b", "text": "Mild fever"}, {"id": "c", "text": "No fever"}, {"id": "d", "text": "Low body temperature"}]'::jsonb, '["a"]', 'Epiglottitis presents with a high fever, whereas croup typically has a mild fever.'),
  ('epiglottitis', 17, 'A child with suspected epiglottitis is drooling. The nurse understands that this finding is related to', '[{"id": "a", "text": "a barky, seal-like cough."}, {"id": "b", "text": "excess saliva from teething."}, {"id": "c", "text": "difficulty swallowing."}, {"id": "d", "text": "a mild, gradual fever."}]'::jsonb, '["c"]', 'Drooling in epiglottitis reflects dysphagia, or difficulty swallowing. A barky cough is a feature of croup, not epiglottitis.'),
  ('epiglottitis', 18, 'A lateral neck X-ray is obtained for a child with suspected epiglottitis. Which finding indicates a swollen epiglottis?', '[{"id": "a", "text": "A small, flattened epiglottis"}, {"id": "b", "text": "An enlarged epiglottis called the thumb sign"}, {"id": "c", "text": "A normal epiglottis and clear airway"}, {"id": "d", "text": "An epiglottis that is not visible"}]'::jsonb, '["b"]', 'The classic lateral neck X-ray finding in epiglottitis is the thumb sign, an enlarged, swollen epiglottis.'),
  ('epiglottitis', 19, 'Which diagnostic test does the nurse anticipate to identify the classic finding of epiglottitis?', '[{"id": "a", "text": "Lateral neck X-ray"}, {"id": "b", "text": "Throat swab culture"}, {"id": "c", "text": "Oral exam with a tongue blade"}, {"id": "d", "text": "Bedside laryngoscopy on arrival"}]'::jsonb, '["a"]', 'A lateral neck X-ray shows the classic thumb sign. Throat swabs and tongue blades are contraindicated, and laryngoscopy is done only in controlled airway settings.'),
  ('epiglottitis', 20, 'The provider plans to visualize the epiglottis of a child with suspected epiglottitis using laryngoscopy. The nurse anticipates that this will be done', '[{"id": "a", "text": "at the bedside during triage."}, {"id": "b", "text": "in the waiting area with the parent."}, {"id": "c", "text": "during the lateral neck X-ray."}, {"id": "d", "text": "in a controlled airway setting."}]'::jsonb, '["d"]', 'Laryngoscopy in epiglottitis is performed only in controlled airway settings because manipulating the airway can trigger obstruction.'),
  ('epiglottitis', 21, 'Blood cultures are drawn for a child with epiglottitis. The nurse explains to the parent that the purpose of this test is to', '[{"id": "a", "text": "confirm the thumb sign."}, {"id": "b", "text": "measure the airway swelling."}, {"id": "c", "text": "identify the causative organism."}, {"id": "d", "text": "check the child''s hydration."}]'::jsonb, '["c"]', 'Blood cultures identify the causative organism in epiglottitis. The thumb sign is seen on lateral neck X-ray.'),
  ('epiglottitis', 22, 'Which organism does the nurse recognize as the most common cause of epiglottitis?', '[{"id": "a", "text": "Haemophilus influenzae type B"}, {"id": "b", "text": "Streptococcus pneumoniae"}, {"id": "c", "text": "Staphylococcus aureus"}, {"id": "d", "text": "Streptococcus pyogenes"}]'::jsonb, '["a"]', 'Haemophilus influenzae type B (Hib) is the most common cause of epiglottitis. The other organisms can cause it but are less common.'),
  ('epiglottitis', 23, 'A parent asks how to prevent epiglottitis in a younger sibling. Which response by the nurse is best?', '[{"id": "a", "text": "Give antibiotics at the first sign of a cold."}, {"id": "b", "text": "Make sure the Hib vaccine series is completed."}, {"id": "c", "text": "Keep the child away from all other children."}, {"id": "d", "text": "Check the child''s throat daily with a spoon."}]'::jsonb, '["b"]', 'The Hib vaccine is the most effective prevention strategy for epiglottitis.'),
  ('epiglottitis', 24, 'The parent of a 9-month-old who has received the primary Hib vaccine doses asks when the booster is due. The nurse should tell the parent that the booster is given', '[{"id": "a", "text": "at 6 months of age."}, {"id": "b", "text": "at 4 to 6 years of age."}, {"id": "c", "text": "at 18 to 24 months of age."}, {"id": "d", "text": "at 12 to 15 months of age."}]'::jsonb, '["d"]', 'The Hib vaccine is given at 2, 4, and 6 months (if applicable), with a booster at 12 to 15 months.'),
  ('epiglottitis', 25, 'At what age should the nurse expect an infant to receive the first dose of the Hib vaccine?', '[{"id": "a", "text": "At birth"}, {"id": "b", "text": "At 6 months of age"}, {"id": "c", "text": "At 12 months of age"}, {"id": "d", "text": "At 2 months of age"}]'::jsonb, '["d"]', 'The Hib vaccination schedule begins at 2 months, followed by doses at 4 and 6 months and a booster at 12 to 15 months.'),
  ('epiglottitis', 26, 'A toddler is brought to the emergency department after drinking very hot liquid from a cup. The nurse monitors for epiglottitis because', '[{"id": "a", "text": "hot liquids introduce the Hib organism."}, {"id": "b", "text": "hot liquids cause a barky, seal-like cough."}, {"id": "c", "text": "burns from hot liquids can inflame the epiglottis."}, {"id": "d", "text": "burns prevent the Hib vaccine from working."}]'::jsonb, '["c"]', 'Burns from hot liquids are a non-infectious cause of epiglottitis. Hib is an infectious cause, and a barky cough is a feature of croup.'),
  ('epiglottitis', 27, 'Which client history represents a non-infectious cause of epiglottitis?', '[{"id": "a", "text": "Exposure to Haemophilus influenzae type B"}, {"id": "b", "text": "Inhalation of toxic substances"}, {"id": "c", "text": "Infection with Streptococcus pyogenes"}, {"id": "d", "text": "Infection with Staphylococcus aureus"}]'::jsonb, '["b"]', 'Inhalation of toxic substances is a non-infectious cause of epiglottitis. Hib, Streptococcus pyogenes, and Staphylococcus aureus are infectious causes.'),
  ('epiglottitis', 28, 'A nursing student states, ''Only young children can develop epiglottitis.'' Which response by the nurse is correct?', '[{"id": "a", "text": "It is more common in children, but adults can be affected."}, {"id": "b", "text": "That is correct; adults are never affected by it."}, {"id": "c", "text": "It is more common in adults than in children."}, {"id": "d", "text": "It affects only infants younger than 6 months."}]'::jsonb, '["a"]', 'Epiglottitis is more common in children, but adults can also be affected.'),
  ('epiglottitis', 29, 'The nurse explains the normal function of the epiglottis to a parent. Which statement is accurate?', '[{"id": "a", "text": "It opens over the trachea during swallowing."}, {"id": "b", "text": "It closes over the trachea during breathing."}, {"id": "c", "text": "It closes over the trachea during swallowing."}, {"id": "d", "text": "It stays closed during both swallowing and breathing."}]'::jsonb, '["c"]', 'The epiglottis closes over the trachea during swallowing and opens during breathing.'),
  ('epiglottitis', 30, 'A parent asks where the epiglottis is located. Which response by the nurse is accurate?', '[{"id": "a", "text": "Below the larynx, inside the trachea"}, {"id": "b", "text": "Behind the tongue, above the larynx"}, {"id": "c", "text": "In front of the tongue, near the teeth"}, {"id": "d", "text": "Below the vocal cords, in the chest"}]'::jsonb, '["b"]', 'The epiglottis is a flap-like cartilage located behind the tongue and above the larynx.'),
  ('epiglottitis', 31, 'While assessing a child with epiglottitis, the nurse hears a high-pitched noise on inspiration. The nurse documents this finding as', '[{"id": "a", "text": "wheezing."}, {"id": "b", "text": "stridor."}, {"id": "c", "text": "a barky cough."}, {"id": "d", "text": "crackles."}]'::jsonb, '["b"]', 'Stridor is a high-pitched inspiratory noise seen in epiglottitis. A barky cough is a croup finding and is absent in epiglottitis.'),
  ('epiglottitis', 32, 'Which finding indicates that a child with epiglottitis is using accessory muscles to breathe?', '[{"id": "a", "text": "Suprasternal and intercostal retractions"}, {"id": "b", "text": "A barky, seal-like cough"}, {"id": "c", "text": "A muffled voice when speaking"}, {"id": "d", "text": "Drooling from the mouth"}]'::jsonb, '["a"]', 'Use of accessory muscles appears as visible suprasternal and intercostal retractions. Drooling reflects dysphagia, and a barky cough is a croup finding.'),
  ('epiglottitis', 33, 'Which assessment finding in a child with epiglottitis most directly indicates difficulty breathing?', '[{"id": "a", "text": "High fever"}, {"id": "b", "text": "Absence of cough"}, {"id": "c", "text": "Drooling"}, {"id": "d", "text": "Nasal flaring"}]'::jsonb, '["d"]', 'Nasal flaring reflects difficulty breathing in epiglottitis. Drooling reflects dysphagia, and high fever and absent cough are other features of the disease.'),
  ('epiglottitis', 34, 'Which medication does the nurse anticipate administering to treat the infection in a child with epiglottitis?', '[{"id": "a", "text": "IV dexamethasone"}, {"id": "b", "text": "IV ceftriaxone"}, {"id": "c", "text": "Oral acetaminophen"}, {"id": "d", "text": "Oral ibuprofen"}]'::jsonb, '["b"]', 'IV antibiotics such as ceftriaxone or cefotaxime treat the infection. Dexamethasone reduces swelling, and acetaminophen and ibuprofen are antipyretics.'),
  ('epiglottitis', 35, 'Dexamethasone is prescribed for a child with epiglottitis. The nurse explains that the purpose of this medication is to', '[{"id": "a", "text": "treat the infection."}, {"id": "b", "text": "lower the high fever."}, {"id": "c", "text": "prevent dehydration."}, {"id": "d", "text": "reduce the swelling."}]'::jsonb, '["d"]', 'Dexamethasone is a corticosteroid given to reduce swelling. Antibiotics treat infection, antipyretics lower fever, and IV fluids prevent dehydration.'),
  ('epiglottitis', 36, 'A drooling child with epiglottitis is receiving IV fluids. The parent asks why. The nurse explains that the IV fluids are given to', '[{"id": "a", "text": "prevent dehydration."}, {"id": "b", "text": "reduce the swelling."}, {"id": "c", "text": "treat the infection."}, {"id": "d", "text": "lower the fever."}]'::jsonb, '["a"]', 'IV fluids are given in epiglottitis to prevent dehydration. Dexamethasone reduces swelling, and IV antibiotics treat infection.'),
  ('epiglottitis', 37, 'A child with epiglottitis has a high fever. Which medication does the nurse anticipate administering for the fever?', '[{"id": "a", "text": "Acetaminophen"}, {"id": "b", "text": "Dexamethasone"}, {"id": "c", "text": "Ceftriaxone"}, {"id": "d", "text": "Cefotaxime"}]'::jsonb, '["a"]', 'Antipyretics such as acetaminophen or ibuprofen treat fever. Ceftriaxone and cefotaxime are antibiotics, and dexamethasone reduces swelling.'),
  ('epiglottitis', 38, 'A child with epiglottitis develops worsening respiratory distress despite treatment. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Throat exam with a tongue blade"}, {"id": "b", "text": "Oral fluids to soothe the throat"}, {"id": "c", "text": "Placing the child in a supine position"}, {"id": "d", "text": "Intubation or tracheostomy"}]'::jsonb, '["d"]', 'Airway management in epiglottitis may require intubation or tracheostomy, with an anesthesiologist or ENT involved. Tongue blade exams are contraindicated.'),
  ('epiglottitis', 39, 'When the epiglottis becomes inflamed, the nurse recognizes that the most serious danger to the client is', '[{"id": "a", "text": "severe dehydration from the fever."}, {"id": "b", "text": "complete upper airway obstruction."}, {"id": "c", "text": "permanent loss of the voice."}, {"id": "d", "text": "spread of infection to the bowel."}]'::jsonb, '["b"]', 'Epiglottitis is a life-threatening airway emergency because the swollen epiglottis can completely obstruct the upper airway.'),
  ('epiglottitis', 40, 'A child with epiglottitis caused by Hib has just been started on IV antibiotics. Which isolation precautions should the nurse initiate?', '[{"id": "a", "text": "Airborne precautions until discharge"}, {"id": "b", "text": "Contact precautions for 7 days"}, {"id": "c", "text": "Droplet precautions for the first 24 hours"}, {"id": "d", "text": "No isolation precautions"}]'::jsonb, '["c"]', 'Droplet precautions are initiated for the first 24 hours after antibiotics are started.'),
  ('epiglottitis', 41, 'IV antibiotics for a child with epiglottitis were started at 0800 yesterday, and droplet precautions were initiated. It is now 0900 today. Which statement about the precautions is correct?', '[{"id": "a", "text": "Droplet precautions must continue until discharge."}, {"id": "b", "text": "The 24-hour droplet period has been completed."}, {"id": "c", "text": "Droplet precautions should begin only now."}, {"id": "d", "text": "Airborne precautions should replace droplet now."}]'::jsonb, '["b"]', 'Droplet precautions are needed for the first 24 hours after antibiotics are started, and 25 hours have now passed.'),
  ('epiglottitis', 42, 'Which behavior does the nurse expect to observe in a child with epiglottitis?', '[{"id": "a", "text": "Calm, playful behavior"}, {"id": "b", "text": "Sleeping comfortably lying flat"}, {"id": "c", "text": "Irritability and anxiety"}, {"id": "d", "text": "Eagerness to eat and drink"}]'::jsonb, '["c"]', 'Children with epiglottitis show irritability and anxiety, along with drooling from difficulty swallowing.'),
  ('epiglottitis', 43, 'When a child with suspected epiglottitis speaks, which voice quality does the nurse expect?', '[{"id": "a", "text": "Clear and normal"}, {"id": "b", "text": "Muffled"}, {"id": "c", "text": "Loud and strong"}, {"id": "d", "text": "Unchanged from baseline"}]'::jsonb, '["b"]', 'A muffled voice is part of the classic presentation of epiglottitis, along with high fever, drooling, tripod position, and no cough.'),
  ('epiglottitis', 44, 'Which set of findings is most consistent with epiglottitis?', '[{"id": "a", "text": "Mild fever, barky cough, gradual onset"}, {"id": "b", "text": "High fever, barky cough, normal position"}, {"id": "c", "text": "Mild fever, seal-like cough, rare drooling"}, {"id": "d", "text": "High fever, drooling, muffled voice, no cough"}]'::jsonb, '["d"]', 'High fever, drooling, muffled voice, tripod position, and no cough indicate epiglottitis. A barky or seal-like cough indicates croup.'),
  ('epiglottitis', 45, 'The nurse has four tasks for a newly admitted child with suspected epiglottitis. Which task should the nurse complete first?', '[{"id": "a", "text": "Draw the prescribed blood cultures."}, {"id": "b", "text": "Start the prescribed IV fluids."}, {"id": "c", "text": "Give acetaminophen for the fever."}, {"id": "d", "text": "Prepare emergency airway equipment."}]'::jsonb, '["d"]', 'Epiglottitis is a true airway emergency, so preparing airway equipment comes first. Blood cultures, IV fluids, and antipyretics follow.'),
  ('epiglottitis', 46, 'Which statement by the parent of a child with epiglottitis indicates understanding of the nurse''s teaching?', '[{"id": "a", "text": "I''ll let her sit leaning forward if that''s easier."}, {"id": "b", "text": "I''ll lay her flat so she can rest better."}, {"id": "c", "text": "I''ll check her throat with a spoon tonight."}, {"id": "d", "text": "I''ll take her temperature by mouth later."}]'::jsonb, '["a"]', 'The nurse allows tripod positioning. Oral exams and oral temperatures are contraindicated because they can trigger airway obstruction.'),
  ('epiglottitis', 47, 'Which statement by a parent best describes the typical onset of epiglottitis?', '[{"id": "a", "text": "She has had a cough that slowly got worse all week."}, {"id": "b", "text": "Her barky cough started gradually a few days ago."}, {"id": "c", "text": "She has had a mild fever and runny nose for days."}, {"id": "d", "text": "She was fine this morning and suddenly got very sick."}]'::jsonb, '["d"]', 'Epiglottitis has a rapid, sudden onset of acute symptoms, whereas croup develops gradually with a barky cough and mild fever.'),
  ('epiglottitis', 48, 'A school-age child sustained a blunt injury to the throat during a sports game. The nurse monitors for epiglottitis, recognizing throat trauma as', '[{"id": "a", "text": "an infectious cause."}, {"id": "b", "text": "a non-infectious cause."}, {"id": "c", "text": "a cause of barky cough."}, {"id": "d", "text": "a cause seen only in adults."}]'::jsonb, '["b"]', 'Throat trauma is listed with burns and toxic inhalation as non-infectious causes of epiglottitis.'),
  ('epiglottitis', 49, 'Which statement by the parent of an infant indicates a need for further teaching about the Hib vaccine?', '[{"id": "a", "text": "My baby gets Hib doses at 2 and 4 months."}, {"id": "b", "text": "My baby may need a Hib dose at 6 months."}, {"id": "c", "text": "My baby needs a Hib booster at 12 to 15 months."}, {"id": "d", "text": "My baby only needs one Hib shot at 2 months."}]'::jsonb, '["d"]', 'The Hib schedule is 2 months, 4 months, 6 months if applicable, and a booster at 12 to 15 months, so a single dose is not enough.'),
  ('epiglottitis', 50, 'A child with epiglottitis is resting calmly in the tripod position. Which action by the nurse requires correction?', '[{"id": "a", "text": "Leaving the child alone to retrieve supplies"}, {"id": "b", "text": "Keeping airway equipment at the bedside"}, {"id": "c", "text": "Monitoring oxygen saturation continuously"}, {"id": "d", "text": "Allowing a parent to comfort the child"}]'::jsonb, '["a"]', 'The nurse must stay with the child at all times and not leave the child alone. Keeping airway equipment ready and keeping the child calm are correct.'),
  ('lead', 1, 'A 3-year-old has a blood lead level (BLL) of 48 µg/dL. Which action is the priority?', '[{"id": "a", "text": "Recheck the blood lead level in 6 months."}, {"id": "b", "text": "Begin chelation therapy and remove the exposure source."}, {"id": "c", "text": "Provide iron-rich foods as the only treatment."}, {"id": "d", "text": "Schedule a developmental screening only."}]'::jsonb, '["b"]', 'A BLL of 48 µg/dL exceeds the chelation threshold of 45 µg/dL in children, so chelation and removing the source are the priority. Nutrition alone is not enough at this level.'),
  ('lead', 2, 'The nurse reviews blood lead levels for four children. Which child meets the criterion for chelation therapy?', '[{"id": "a", "text": "A 4-year-old with a BLL of 12 µg/dL"}, {"id": "b", "text": "A 4-year-old with a BLL of 25 µg/dL"}, {"id": "c", "text": "A 4-year-old with a BLL of 46 µg/dL"}, {"id": "d", "text": "A 4-year-old with a BLL of 40 µg/dL"}]'::jsonb, '["c"]', 'Chelation therapy is given when the BLL is 45 µg/dL or higher in children. Only 46 µg/dL meets this threshold.'),
  ('lead', 3, 'Which medication does the nurse recognize as a chelating agent used to treat lead poisoning?', '[{"id": "a", "text": "Ferrous sulfate"}, {"id": "b", "text": "Succimer (DMSA)"}, {"id": "c", "text": "Calcium carbonate"}, {"id": "d", "text": "Ascorbic acid (vitamin C)"}]'::jsonb, '["b"]', 'Succimer (DMSA), EDTA, and dimercaprol (BAL) are chelating agents. Iron, calcium, and vitamin C are nutritional support that reduce lead absorption.'),
  ('lead', 4, 'A child is about to begin chelation therapy for lead poisoning. Which nursing action is essential?', '[{"id": "a", "text": "Ensure adequate hydration before and during therapy."}, {"id": "b", "text": "Restrict fluids for the duration of therapy."}, {"id": "c", "text": "Withhold all fluids until therapy has ended."}, {"id": "d", "text": "Offer fluids only after therapy is complete."}]'::jsonb, '["a"]', 'The nurse ensures adequate hydration before and during chelation therapy because hydration promotes renal excretion of lead.'),
  ('lead', 5, 'A parent asks why their child needs extra fluids during chelation therapy. The nurse explains that hydration', '[{"id": "a", "text": "prevents lead from being stored in bones."}, {"id": "b", "text": "promotes excretion of lead through the kidneys."}, {"id": "c", "text": "replaces iron that is lost during therapy."}, {"id": "d", "text": "reduces absorption of lead from food."}]'::jsonb, '["b"]', 'Hydration promotes renal excretion of lead bound by chelation. Reducing lead absorption from food is the role of iron, calcium, and vitamin C.'),
  ('lead', 6, 'When taking a history for a toddler with suspected lead poisoning, which question is most important?', '[{"id": "a", "text": "Has your child had a flu vaccine?"}, {"id": "b", "text": "How many hours does your child sleep?"}, {"id": "c", "text": "What year was your home built?"}, {"id": "d", "text": "Does your child drink fruit juice?"}]'::jsonb, '["c"]', 'Lead-based paint is common in homes built before 1978, so the age of the home is a key part of identifying the exposure source.'),
  ('lead', 7, 'A family lives in an older home with lead plumbing. The nurse identifies which possible source of lead exposure?', '[{"id": "a", "text": "Fresh fruit from the market"}, {"id": "b", "text": "Bottled water from a store"}, {"id": "c", "text": "Drinking water from the pipes"}, {"id": "d", "text": "A newly tiled kitchen floor"}]'::jsonb, '["c"]', 'Lead plumbing or solder can leach lead into drinking water.'),
  ('lead', 8, 'An adult client reports headaches and weakness causing wrist drop. Which occupational history is most relevant?', '[{"id": "a", "text": "Working in a battery factory"}, {"id": "b", "text": "Working as an office receptionist"}, {"id": "c", "text": "Working as a school librarian"}, {"id": "d", "text": "Working as a retail cashier"}]'::jsonb, '["a"]', 'Occupational lead exposure occurs in battery factories, smelting, and construction. Wrist drop and headache are adult signs of lead poisoning.'),
  ('lead', 9, 'A family that recently immigrated reports giving their child a folk remedy called azarcon for stomach upset. Which action should the nurse take?', '[{"id": "a", "text": "Screen the child for lead exposure."}, {"id": "b", "text": "Encourage continued use of the remedy."}, {"id": "c", "text": "Give the remedy with milk to aid it."}, {"id": "d", "text": "Recommend doubling the remedy dose."}]'::jsonb, '["a"]', 'Folk remedies such as azarcon and greta may contain lead, so the child should be screened. Immigrant children are also at increased risk.'),
  ('lead', 10, 'Which item in a child''s environment should the nurse identify as a possible source of lead?', '[{"id": "a", "text": "A home built in 2015"}, {"id": "b", "text": "A floor that is wet-mopped"}, {"id": "c", "text": "Fresh leafy green vegetables"}, {"id": "d", "text": "Imported jewelry with painted surfaces"}]'::jsonb, '["d"]', 'Imported toys and jewelry may contain unsafe lead paint. Wet-mopping reduces lead dust, and leafy greens are recommended foods.'),
  ('lead', 11, 'Which home location places a child at risk for lead exposure from contaminated soil or dust?', '[{"id": "a", "text": "A new home far from any roads"}, {"id": "b", "text": "A home with wet-mopped floors"}, {"id": "c", "text": "A home near an industrial site"}, {"id": "d", "text": "A home with no peeling paint"}]'::jsonb, '["c"]', 'Contaminated dust or soil comes from old paint, industrial sites, and areas near highways.'),
  ('lead', 12, 'A child with lead poisoning also has iron deficiency. The nurse explains that the iron deficiency matters because it', '[{"id": "a", "text": "increases the excretion of lead."}, {"id": "b", "text": "blocks the effect of chelation."}, {"id": "c", "text": "prevents lead storage in bones."}, {"id": "d", "text": "increases the absorption of lead."}]'::jsonb, '["d"]', 'Poor nutrition with iron or calcium deficiency increases lead absorption, which is why iron and calcium are encouraged.'),
  ('lead', 13, 'Which child should the nurse identify as having the highest risk for lead poisoning?', '[{"id": "a", "text": "A 10-year-old living in a 2005 home"}, {"id": "b", "text": "A 9-year-old with a calcium-rich diet"}, {"id": "c", "text": "A 2-year-old refugee who recently arrived"}, {"id": "d", "text": "An 8-year-old in newly built housing"}]'::jsonb, '["c"]', 'Risk factors include age under 6 and immigrant or refugee status from possible prior exposure. Newer housing and good nutrition lower the risk.'),
  ('lead', 14, 'A parent asks why young children are most affected by lead. The nurse explains that children under 6', '[{"id": "a", "text": "excrete lead more quickly than adults do."}, {"id": "b", "text": "store lead only in their growing bones."}, {"id": "c", "text": "absorb lead more easily and have developing nervous systems."}, {"id": "d", "text": "are rarely exposed to household lead dust."}]'::jsonb, '["c"]', 'Lead poisoning is most common in children under 6 because they absorb lead more easily and have developing nervous systems.'),
  ('lead', 15, 'A child with lead poisoning has anemia. The nurse understands that the anemia occurs because lead', '[{"id": "a", "text": "increases red blood cell production."}, {"id": "b", "text": "interferes with heme synthesis."}, {"id": "c", "text": "damages the renal tubules."}, {"id": "d", "text": "blocks absorption of calcium."}]'::jsonb, '["b"]', 'Lead interferes with heme synthesis, causing anemia. Damage to the renal tubules is lead''s effect on kidney function, not the cause of anemia.'),
  ('lead', 16, 'Which renal effect should the nurse monitor for in a child with chronic lead exposure?', '[{"id": "a", "text": "Increased urine concentration"}, {"id": "b", "text": "Improved kidney filtration"}, {"id": "c", "text": "Damage to the renal tubules"}, {"id": "d", "text": "Increased excretion of iron"}]'::jsonb, '["c"]', 'Lead interferes with kidney function by damaging the renal tubules, and kidney damage occurs with chronic exposure.'),
  ('lead', 17, 'The nurse explains to a parent that lead can remain in the body for years because it is', '[{"id": "a", "text": "stored in the liver."}, {"id": "b", "text": "trapped in the lungs."}, {"id": "c", "text": "held in the skin."}, {"id": "d", "text": "stored in the bones."}]'::jsonb, '["d"]', 'Lead interferes with bone growth and is stored in bones for years.'),
  ('lead', 18, 'Which gastrointestinal findings should the nurse expect in a child with lead poisoning?', '[{"id": "a", "text": "Increased appetite and weight gain"}, {"id": "b", "text": "Fatty, foul-smelling stools"}, {"id": "c", "text": "Excessive hunger and thirst"}, {"id": "d", "text": "Anorexia, abdominal pain, and constipation"}]'::jsonb, '["d"]', 'GI symptoms of lead poisoning in children include anorexia, abdominal pain, constipation, and vomiting.'),
  ('lead', 19, 'The nurse is assessing a 4-year-old with lead poisoning. Which neurological findings are expected?', '[{"id": "a", "text": "Advanced language skills"}, {"id": "b", "text": "Irritability and developmental delay"}, {"id": "c", "text": "An improved attention span"}, {"id": "d", "text": "Calm, quiet behavior"}]'::jsonb, '["b"]', 'Neurological signs in children include developmental delay, learning difficulties, irritability, hyperactivity, and seizures.'),
  ('lead', 20, 'A teacher reports that a 5-year-old who lives in a pre-1978 home has become aggressive and inattentive. How should the nurse interpret this report?', '[{"id": "a", "text": "These may be behavioral signs of lead poisoning."}, {"id": "b", "text": "These behaviors are unrelated to the home."}, {"id": "c", "text": "These signs rule out lead exposure."}, {"id": "d", "text": "These behaviors occur only in adults."}]'::jsonb, '["a"]', 'Aggression and inattentiveness are behavioral signs of lead poisoning in children, and pre-1978 homes are a common source of lead paint.'),
  ('lead', 21, 'A child being treated for lead poisoning has a seizure. The nurse recognizes this may indicate which complication?', '[{"id": "a", "text": "Encephalopathy"}, {"id": "b", "text": "Peripheral neuropathy"}, {"id": "c", "text": "Hearing loss"}, {"id": "d", "text": "Growth retardation"}]'::jsonb, '["a"]', 'Encephalopathy is a complication of lead poisoning that leads to seizures and coma. Peripheral neuropathy causes wrist and foot drop in adults.'),
  ('lead', 22, 'Which finding should the nurse expect in an adult with lead poisoning?', '[{"id": "a", "text": "Lead lines at bone growth plates"}, {"id": "b", "text": "Delayed developmental milestones"}, {"id": "c", "text": "Aggression and inattentiveness"}, {"id": "d", "text": "Wrist drop from peripheral neuropathy"}]'::jsonb, '["d"]', 'Adults with lead poisoning develop peripheral neuropathy with wrist drop and foot drop. Lead lines at growth plates, developmental delay, and aggression are findings in children.'),
  ('lead', 23, 'A construction worker with lead poisoning reports abdominal pain. The nurse recognizes this finding as', '[{"id": "a", "text": "lead lines."}, {"id": "b", "text": "lead colic."}, {"id": "c", "text": "basophilic stippling."}, {"id": "d", "text": "foot drop."}]'::jsonb, '["b"]', 'In adults, abdominal pain from lead poisoning is called lead colic. Basophilic stippling is a blood smear finding.'),
  ('lead', 24, 'A woman who works at a smelting plant asks how lead could affect her plans to have a baby. The nurse explains that lead exposure in adults is associated with', '[{"id": "a", "text": "improved fertility."}, {"id": "b", "text": "infertility and miscarriage."}, {"id": "c", "text": "no reproductive effects."}, {"id": "d", "text": "effects only in males."}]'::jsonb, '["b"]', 'Reproductive effects of lead poisoning in adults include infertility and miscarriage. Smelting is an occupational source of lead.'),
  ('lead', 25, 'Which complete blood count (CBC) finding does the nurse expect in a child with lead poisoning?', '[{"id": "a", "text": "Macrocytic anemia"}, {"id": "b", "text": "Elevated hemoglobin"}, {"id": "c", "text": "Normal red blood cells"}, {"id": "d", "text": "Microcytic hypochromic anemia"}]'::jsonb, '["d"]', 'The CBC in lead poisoning may show microcytic hypochromic anemia because lead interferes with heme synthesis.'),
  ('lead', 26, 'Which peripheral blood smear finding is the hallmark of lead poisoning?', '[{"id": "a", "text": "Sickle-shaped red cells"}, {"id": "b", "text": "Large, oval red cells"}, {"id": "c", "text": "Normal red blood cells"}, {"id": "d", "text": "Basophilic stippling"}]'::jsonb, '["d"]', 'Basophilic stippling, blue granules in red blood cells, is the hallmark peripheral smear finding in lead poisoning.'),
  ('lead', 27, 'Which laboratory result suggests chronic lead exposure?', '[{"id": "a", "text": "Decreased erythrocyte protoporphyrin"}, {"id": "b", "text": "Elevated erythrocyte protoporphyrin"}, {"id": "c", "text": "Elevated hemoglobin"}, {"id": "d", "text": "Normal peripheral smear"}]'::jsonb, '["b"]', 'Erythrocyte protoporphyrin is elevated in chronic lead exposure.'),
  ('lead', 28, 'A child with suspected lead poisoning has X-rays taken. Where does the nurse expect lead lines to appear?', '[{"id": "a", "text": "Along the lung fields"}, {"id": "b", "text": "Within the kidneys"}, {"id": "c", "text": "Within the stomach"}, {"id": "d", "text": "At the bone growth plates"}]'::jsonb, '["d"]', 'X-rays in children with lead poisoning show lead lines at the bone growth plates.'),
  ('lead', 29, 'Which test does the nurse anticipate as the diagnostic test for lead poisoning in a child?', '[{"id": "a", "text": "Blood lead level"}, {"id": "b", "text": "Erythrocyte protoporphyrin"}, {"id": "c", "text": "Complete blood count"}, {"id": "d", "text": "X-ray of the long bones"}]'::jsonb, '["a"]', 'The blood lead level (BLL) is the diagnostic test. The CBC and erythrocyte protoporphyrin show anemia and chronic exposure but are not the diagnostic test.'),
  ('lead', 30, 'Which instruction should the nurse give parents living in an older home with lead dust?', '[{"id": "a", "text": "Sweep the floors daily to remove dust."}, {"id": "b", "text": "Wet-mop floors instead of sweeping."}, {"id": "c", "text": "Open windows and sweep dust outside."}, {"id": "d", "text": "Dry-dust surfaces with a cloth daily."}]'::jsonb, '["b"]', 'Wet-mopping floors instead of sweeping prevents airborne lead dust. Sweeping stirs dust into the air.'),
  ('lead', 31, 'Which statement by a parent indicates a need for further teaching about reducing lead exposure?', '[{"id": "a", "text": "I will wet-mop the floors."}, {"id": "b", "text": "I will sweep the floors every day."}, {"id": "c", "text": "I will wash his hands before meals."}, {"id": "d", "text": "I will keep him away from peeling paint."}]'::jsonb, '["b"]', 'Dust should never be swept; floors should be wet-mopped instead. Handwashing before eating and avoiding peeling paint are correct.'),
  ('lead', 32, 'A toddler with lead exposure often puts objects in the mouth. Which teaching is most important for the parents?', '[{"id": "a", "text": "Wash the child''s hands only at bedtime."}, {"id": "b", "text": "Sweep up dust right after meals."}, {"id": "c", "text": "Allow supervised play near peeling paint."}, {"id": "d", "text": "Wash the child''s hands before eating."}]'::jsonb, '["d"]', 'Parents should wash the child''s hands before eating, wet-mop floors, and avoid peeling paint to reduce lead ingestion.'),
  ('lead', 33, 'Which action by a parent demonstrates understanding of lead exposure prevention?', '[{"id": "a", "text": "Keeping the child away from peeling paint"}, {"id": "b", "text": "Sweeping paint chips into a dustpan"}, {"id": "c", "text": "Washing the child''s hands after meals only"}, {"id": "d", "text": "Limiting milk in the child''s diet"}]'::jsonb, '["a"]', 'Parents are taught to avoid peeling paint, wet-mop rather than sweep, wash hands before eating, and encourage calcium-rich foods such as milk.'),
  ('lead', 34, 'Which foods should the nurse encourage for a child with lead poisoning?', '[{"id": "a", "text": "Foods low in calcium and iron"}, {"id": "b", "text": "Foods without any vitamin C"}, {"id": "c", "text": "Milk, leafy greens, and lean meats"}, {"id": "d", "text": "Low-protein, low-iron snacks"}]'::jsonb, '["c"]', 'Nutritional counseling encourages calcium- and iron-rich foods such as milk, leafy greens, and lean meats to reduce lead absorption.'),
  ('lead', 35, 'A parent asks why the nurse recommended more milk for their child with lead exposure. The nurse explains that the calcium in milk', '[{"id": "a", "text": "decreases lead absorption."}, {"id": "b", "text": "increases lead absorption."}, {"id": "c", "text": "binds lead for excretion."}, {"id": "d", "text": "stores lead in the bones."}]'::jsonb, '["a"]', 'Milk (high calcium) and lean meat (iron-rich) both decrease lead absorption. Binding lead for excretion is the action of chelation therapy.'),
  ('lead', 36, 'Which nutritional supplements does the nurse anticipate for a child with lead poisoning?', '[{"id": "a", "text": "Iron, calcium, and vitamin C"}, {"id": "b", "text": "Sodium and potassium"}, {"id": "c", "text": "Vitamin B12 and folate"}, {"id": "d", "text": "Vitamins A, D, E, and K"}]'::jsonb, '["a"]', 'Iron, calcium, and vitamin C are given as nutritional support because they reduce lead absorption.'),
  ('lead', 37, 'A child has completed chelation therapy for lead poisoning. How should the nurse evaluate the effectiveness of treatment?', '[{"id": "a", "text": "Ask whether the child''s appetite improved."}, {"id": "b", "text": "Measure the child''s height and weight."}, {"id": "c", "text": "Check whether the child sleeps better."}, {"id": "d", "text": "Recheck the blood lead level for a decline."}]'::jsonb, '["d"]', 'Follow-up testing rechecks the BLL after intervention to ensure it has declined.'),
  ('lead', 38, 'A child has been diagnosed with lead poisoning. Which action is required of the health care team?', '[{"id": "a", "text": "Report the case to public health authorities."}, {"id": "b", "text": "Keep the diagnosis from public health."}, {"id": "c", "text": "Report only if the child has seizures."}, {"id": "d", "text": "Report only if siblings are also affected."}]'::jsonb, '["a"]', 'Lead poisoning is a reportable condition, so it must be reported to public health authorities.'),
  ('lead', 39, 'Which nursing assessment is most important at follow-up visits for a toddler treated for lead poisoning?', '[{"id": "a", "text": "Monitoring developmental milestones"}, {"id": "b", "text": "Checking for foot drop"}, {"id": "c", "text": "Assessing for lead colic"}, {"id": "d", "text": "Screening for infertility"}]'::jsonb, '["a"]', 'Monitoring developmental milestones catches early neurological deficits in children. Foot drop, lead colic, and infertility are adult findings.'),
  ('lead', 40, 'Which complication of lead poisoning should the nurse include when planning follow-up screening for a child?', '[{"id": "a", "text": "Improved cognition"}, {"id": "b", "text": "Accelerated growth"}, {"id": "c", "text": "Increased bone density"}, {"id": "d", "text": "Hearing loss"}]'::jsonb, '["d"]', 'Complications of lead poisoning include hearing loss, kidney damage, cognitive impairment, behavioral disorders, and growth retardation.'),
  ('lead', 41, 'Parents ask whether their child''s learning problems from severe, prolonged lead poisoning will go away. Which response by the nurse is accurate?', '[{"id": "a", "text": "All learning problems resolve after chelation."}, {"id": "b", "text": "Learning problems are unrelated to lead."}, {"id": "c", "text": "Cognitive effects occur only in adults."}, {"id": "d", "text": "The cognitive impairment may be permanent."}]'::jsonb, '["d"]', 'Cognitive impairment from lead poisoning is irreversible if the poisoning is severe and prolonged.'),
  ('lead', 42, 'Which growth-related complication should the nurse monitor for in a child with lead poisoning?', '[{"id": "a", "text": "Accelerated height gain"}, {"id": "b", "text": "Growth retardation"}, {"id": "c", "text": "Excessive weight gain"}, {"id": "d", "text": "Increased bone density"}]'::jsonb, '["b"]', 'Growth retardation is a complication of lead poisoning; lead also interferes with bone growth.'),
  ('lead', 43, 'An adult with lead poisoning cannot lift the front of the foot when walking. The nurse recognizes this finding as', '[{"id": "a", "text": "lead colic from GI involvement."}, {"id": "b", "text": "anemia from impaired heme synthesis."}, {"id": "c", "text": "foot drop from peripheral neuropathy."}, {"id": "d", "text": "lead lines at the growth plates."}]'::jsonb, '["c"]', 'Foot drop and wrist drop result from peripheral neuropathy in lead poisoning. Lead colic is abdominal pain, and lead lines appear at growth plates in children.'),
  ('lead', 44, 'Which intervention is considered primary prevention for lead poisoning?', '[{"id": "a", "text": "Chelation therapy"}, {"id": "b", "text": "Home inspection and lead abatement"}, {"id": "c", "text": "Hydration during chelation"}, {"id": "d", "text": "Rechecking the blood lead level"}]'::jsonb, '["b"]', 'Removing the exposure source through home inspection and lead abatement is primary prevention. Chelation and follow-up testing occur after poisoning.'),
  ('lead', 45, 'A parent asks how lead gets into the body. Which response by the nurse is accurate?', '[{"id": "a", "text": "Only by drinking contaminated water"}, {"id": "b", "text": "Only through direct contact with skin"}, {"id": "c", "text": "By swallowing it or breathing in lead dust or fumes"}, {"id": "d", "text": "Only by eating chips of old paint"}]'::jsonb, '["c"]', 'Lead enters the body by ingestion (swallowing) or inhalation of dust or fumes, so exposure is not limited to one route.'),
  ('lead', 46, 'A toddler with lead poisoning has hematologic involvement. Which findings should the nurse expect?', '[{"id": "a", "text": "Flushed skin and high energy"}, {"id": "b", "text": "Pallor and fatigue"}, {"id": "c", "text": "Itching and yellow skin"}, {"id": "d", "text": "Bruising and nosebleeds"}]'::jsonb, '["b"]', 'Hematologic involvement in children with lead poisoning causes anemia, seen as pallor and fatigue.'),
  ('lead', 47, 'Which topics are most important to ask about when assessing a client for the source of lead exposure?', '[{"id": "a", "text": "Sleep habits, exercise, and stress"}, {"id": "b", "text": "Vaccinations, allergies, and surgeries"}, {"id": "c", "text": "Home age, occupation, and imported items"}, {"id": "d", "text": "Screen time, bedtime, and naps"}]'::jsonb, '["c"]', 'To identify and remove the exposure source, the nurse asks about the age of the home, occupation, and imported items.'),
  ('lead', 48, 'The nurse explains how lead travels in the body after it is absorbed. Which statement is accurate?', '[{"id": "a", "text": "It binds to red blood cells and moves into soft tissues and bones."}, {"id": "b", "text": "It is excreted unchanged within a few hours."}, {"id": "c", "text": "It remains only in the stomach and intestines."}, {"id": "d", "text": "It binds only to white blood cells in the blood."}]'::jsonb, '["a"]', 'Lead binds to red blood cells and distributes to soft tissues and bones, where it can be stored for years.'),
  ('lead', 49, 'Which family situation increases a child''s risk of lead poisoning?', '[{"id": "a", "text": "A family living in housing built in 2010"}, {"id": "b", "text": "A family that wet-mops floors each week"}, {"id": "c", "text": "A low-income family living in pre-1978 housing"}, {"id": "d", "text": "A family whose child eats iron-rich foods"}]'::jsonb, '["c"]', 'Risk factors include low socioeconomic status and living in older, pre-1978 housing. Wet-mopping and iron-rich foods reduce risk.'),
  ('lead', 50, 'A parent asks which body systems lead can damage. Which response by the nurse is accurate?', '[{"id": "a", "text": "The brain, kidneys, and blood-forming organs"}, {"id": "b", "text": "The skin, hair, and nails"}, {"id": "c", "text": "The muscles, tendons, and ligaments"}, {"id": "d", "text": "The thyroid and adrenal glands"}]'::jsonb, '["a"]', 'Lead is a heavy metal that damages the brain, nervous system, kidneys, and blood-forming organs.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _gi_seed_map m USING (source_key)
 CROSS JOIN _gi_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _gi_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'GI-Hepatic seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
